CREATE OR REPLACE FUNCTION "app_private"."apply_lifecycle_definition"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "expected_preview_token" "text", "apply_reason" "text", "target_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d app_private.lifecycle_definition%rowtype; preview jsonb; item jsonb; r public.employee_onboarding_requirements%rowtype;
 case_id uuid; member public.workspace_memberships%rowtype; deadline timestamptz; applied integer:=0; valid_approved boolean;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 if nullif(btrim(apply_reason),'') is null or char_length(apply_reason)>500 then raise exception 'application reason required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,52001));
 if target_kind='acknowledgement' then perform 1 from public.signature_template_versions where id=target_document_type_id and workspace_id=target_workspace_id for update; else perform 1 from public.document_types where id=target_document_type_id and workspace_id=target_workspace_id for update; end if; select * into d from app_private.lifecycle_definition where id=target_document_type_id and workspace_id=target_workspace_id and kind=target_kind;
 if d.id is null or d.lifecycle_revision is distinct from expected_revision then raise exception 'document type changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 -- Lock every scoped input that contributes to this preview before revalidation.
 perform 1 from public.employee_profiles e where e.workspace_id=target_workspace_id and e.archived_at is null order by e.id for update;
 perform 1 from public.employee_onboarding_cases where workspace_id=target_workspace_id order by id for update;
 perform 1 from public.employee_onboarding_requirements where workspace_id=target_workspace_id and source_id=d.id order by id for update;
 preview:=app_private.preview_lifecycle_definition(actor_user_id,target_workspace_id,d.id,target_kind);
 if preview->>'preview_token' is distinct from expected_preview_token then raise exception 'document impact changed; refresh preview' using errcode='PT409',hint='document.changed'; end if;
 for item in select value from jsonb_array_elements(preview->'employees') where value->>'action' in ('assign','update','reopen','remove') loop
  select m.* into member from public.workspace_memberships m join public.employee_profiles e on e.workspace_id=m.workspace_id and e.user_id=m.user_id
   where e.id=(item->>'employee_id')::uuid and m.workspace_id=target_workspace_id;
  if item->>'action'='assign' then
   insert into public.employee_onboarding_cases(workspace_id,employee_id,membership_id,status,approved_at,approved_by)
   values(target_workspace_id,(item->>'employee_id')::uuid,member.id,
    case when member.status='active' then 'approved'::public.employee_onboarding_case_status else 'in_progress'::public.employee_onboarding_case_status end,
    case when member.status='active' then now() end,case when member.status='active' then actor_user_id end)
   on conflict(employee_id) do nothing;
   select id into case_id from public.employee_onboarding_cases where workspace_id=target_workspace_id and employee_id=(item->>'employee_id')::uuid;
   insert into public.employee_onboarding_requirements(workspace_id,employee_id,case_id,kind,source_id,title,description,required,blocks_activation,requires_review,sort_order,source_snapshot,lifecycle_settings)
   values(target_workspace_id,(item->>'employee_id')::uuid,case_id,target_kind::public.employee_onboarding_requirement_kind,d.id,d.title,d.description,d.lifecycle_settings->>'mode'='required',d.lifecycle_settings->>'mode'='required',d.requires_review,100+d.sort_order,d.snapshot,d.lifecycle_settings)
   returning * into r;
  else
   select * into r from public.employee_onboarding_requirements where id=(item->>'requirement_id')::uuid;
   deadline:=r.deadline_at;
   r.publication_paused_at:=null; r.lifecycle_closed_at:=null; if r.status='superseded' then r.status:='not_started'; end if;
   valid_approved:=app_private.document_obligation_state(r,now())='completed';
   if item->>'deadline_action'='clear' or valid_approved then deadline:=null;
   elsif item->>'deadline_action'='restart' then
    deadline:=case when member.status='active' and d.lifecycle_settings->>'period_days' is not null then now()+(d.lifecycle_settings->>'period_days')::integer*interval '24 hours' end;
   end if;
   update public.employee_onboarding_requirements set
    title=d.title,description=d.description,source_snapshot=d.snapshot,lifecycle_settings=d.lifecycle_settings,
    required=d.lifecycle_settings->>'mode'='required',blocks_activation=d.lifecycle_settings->>'mode'='required',requires_review=d.requires_review,
    lifecycle_assignment_disabled=d.archived_at is not null,lifecycle_closed_at=case when item->>'action'='remove' then now() end,lifecycle_close_reason=case when item->>'action'='remove' then btrim(apply_reason) end,
    status=case when item->>'action'='reopen' and status='superseded' then 'not_started'::public.employee_onboarding_requirement_status else status end,
    publication_paused_at=case when target_kind='document' then null else publication_paused_at end,deadline_at=deadline,paused_remaining_seconds=case when target_kind='document' and item->>'deadline_action'='restart' and not valid_approved and d.lifecycle_settings->>'mode'<>'optional' and exists(select 1 from public.employee_document_submissions s where s.id=r.submitted_document_id and s.state='pending_review') then (d.lifecycle_settings->>'period_days')::numeric*86400 when item->>'deadline_action'='preserve' then paused_remaining_seconds end,
    document_suspended_at=case when target_kind='document' and item->>'deadline_action'='restart' then null when item->>'action'='remove' or d.lifecycle_settings->>'mode'='optional' or not (d.lifecycle_settings->>'suspend_on_overdue')::boolean then null else document_suspended_at end,
    lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning * into r;
  end if;
  perform app_private.document_audit(r,actor_user_id,'document.definition_applied',jsonb_build_object('reason',btrim(apply_reason),'definition_revision',d.lifecycle_revision,'action',item->>'action','revision',r.lifecycle_revision,'deadline_action',item->>'deadline_action'));
  if member.status='pending_activation' and r.required and item->>'action' in ('assign','reopen') then update public.employee_onboarding_cases set status='changes_requested',revision=revision+1,updated_at=now() where id=r.case_id and status='submitted'; end if; perform app_private.document_sync_onboarding(r.id,actor_user_id); applied:=applied+1;
 end loop;
 return jsonb_build_object('applied',applied);
end;
$$;


ALTER FUNCTION "app_private"."apply_lifecycle_definition"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "expected_preview_token" "text", "apply_reason" "text", "target_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."apply_owner_onboarding_update"("actor_user_id" "uuid", "target_workspace_id" "uuid", "workspace_name" "text", "next_step" smallint, "mark_complete" boolean DEFAULT false, "expected_revision" integer DEFAULT NULL::integer, "owner_first_name" "text" DEFAULT NULL::"text", "owner_middle_name" "text" DEFAULT NULL::"text", "owner_last_name" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  owner_employee_id uuid;
  current_status public.onboarding_status;
  current_revision integer;
  completed_timestamp timestamptz;
  names_given boolean := coalesce(btrim(owner_first_name), '') <> ''
    or coalesce(btrim(owner_middle_name), '') <> ''
    or coalesce(btrim(owner_last_name), '') <> '';
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;
  if not exists (
    select 1
    from public.workspace_memberships membership
    where membership.workspace_id = target_workspace_id
      and membership.user_id = actor_user_id
      and app_private.role_class(membership.role_id) = 'owner'
      and membership.status = 'active'
  ) then
    raise exception 'owner access required' using errcode = '42501';
  end if;
  if char_length(btrim(workspace_name)) not between 1 and 120 then
    raise exception 'workspace name must be between 1 and 120 characters' using errcode = '22023';
  end if;
  if next_step not between 1 and 4 then
    raise exception 'invalid onboarding step' using errcode = '22023';
  end if;

  select onboarding.status, onboarding.revision
  into current_status, current_revision
  from public.workspace_onboarding onboarding
  where onboarding.workspace_id = target_workspace_id
  for update;

  if current_status is null then
    raise exception 'workspace onboarding was not found' using errcode = 'P0002';
  end if;

  if current_status = 'complete'::public.onboarding_status then
    if mark_complete then
      return;
    end if;
    raise exception 'completed owner onboarding cannot be changed' using errcode = '22023';
  end if;

  if expected_revision is not null and current_revision <> expected_revision then
    raise exception 'owner onboarding revision conflict' using errcode = 'PT409', hint = 'workspace.onboarding_changed';
  end if;

  if mark_complete and not exists (
    select 1
    from public.locations location
    where location.workspace_id = target_workspace_id
      and location.archived_at is null
  ) then
    raise exception 'at least one active location is required to complete owner onboarding' using errcode = '23514';
  end if;

  if mark_complete and not exists (
    select 1
    from public.departments department
    where department.workspace_id = target_workspace_id
      and department.archived_at is null
      and department.system_key is null
  ) then
    raise exception 'at least one department of your own is required to complete owner onboarding' using errcode = '23514';
  end if;

  if mark_complete and not exists (
    select 1
    from public.jobs job
    left join public.departments department on department.id = job.department_id
    where job.workspace_id = target_workspace_id
      and job.archived_at is null
      and department.system_key is distinct from 'management'
  ) then
    raise exception 'at least one job outside Management is required to complete owner onboarding' using errcode = '23514';
  end if;

  completed_timestamp := now();

  update public.workspaces
  set name = btrim(workspace_name), updated_at = completed_timestamp
  where id = target_workspace_id;

  update public.workspace_onboarding
  set
    status = case
      when mark_complete then 'complete'::public.onboarding_status
      else 'incomplete'::public.onboarding_status
    end,
    current_step = next_step,
    completed_at = case when mark_complete then completed_timestamp else null end,
    revision = revision + 1,
    updated_by = actor_user_id,
    updated_at = completed_timestamp
  where workspace_id = target_workspace_id;

  -- No names sent and none on file: the first step has not been answered.
  if not names_given and not exists (
    select 1
    from public.employee_profiles employee
    join public.employee_private_profiles private_profile
      on private_profile.employee_id = employee.id
    where employee.workspace_id = target_workspace_id
      and employee.user_id = actor_user_id
      and employee.archived_at is null
  ) then
    raise exception 'the owner''s legal name is required' using errcode = '23514';
  end if;

  -- The owner is a member from the first step, so their record exists from the
  -- first step too. Waiting for completion meant the team list did not contain
  -- the one person who was certainly on the team.
  owner_employee_id := app_private.ensure_owner_employee_profile(
    target_workspace_id,
    actor_user_id,
    owner_first_name,
    owner_middle_name,
    owner_last_name
  );

  if names_given then
    perform app_private.write_owner_legal_name(
      target_workspace_id, owner_employee_id,
      owner_first_name, owner_middle_name, owner_last_name
    );
  end if;

  -- Management, Owner and Manager exist from the first save, so the setup steps
  -- and Settings show them; nothing under Management counts as the owner's own
  -- department and job (K2).
  perform app_private.ensure_management_and_owner(target_workspace_id);

  -- Locations come into existence during setup, so this runs on every save and
  -- picks up whatever was added since the last one.
  perform app_private.open_owner_record_to_everything(
    target_workspace_id,
    owner_employee_id,
    actor_user_id
  );

  if mark_complete then
    -- DAVET-ERISIM: the founder's record as a new workspace starts (Mert 2026-10-20): the Owner job is their
    -- primary job, the first location their primary location, and they stay off the Schedule until they
    -- choose otherwise. Only a record with no primary yet: a setup finishing again changes nothing.
    if not exists (
      select 1 from public.employee_job_assignments a
      where a.employee_id = owner_employee_id and a.ended_at is null and a.is_primary
    ) and not exists (
      select 1 from public.employee_location_assignments a
      where a.employee_id = owner_employee_id and a.ended_at is null and a.is_primary
    ) then
      update public.employee_job_assignments a
      set is_primary = true
      from public.jobs j
      where a.employee_id = owner_employee_id and a.ended_at is null
        and j.id = a.job_id and j.workspace_id = target_workspace_id and j.system_key = 'owner';
      update public.employee_location_assignments a
      set is_primary = true
      where a.id = (
        select first.id from public.employee_location_assignments first
        join public.locations l on l.id = first.location_id
        where first.employee_id = owner_employee_id and first.ended_at is null and l.archived_at is null
        order by l.created_at, l.name, l.id
        limit 1);
      update public.employee_profiles
      set is_excluded_from_schedule = true, revision = revision + 1, updated_at = now()
      where id = owner_employee_id and workspace_id = target_workspace_id;
    end if;

    insert into public.workspace_entitlements (
      workspace_id,
      status,
      trial_started_at,
      trial_ends_at,
      current_period_started_at,
      current_period_ends_at,
      billing_owner_user_id,
      provider,
      created_at,
      updated_at
    ) values (
      target_workspace_id,
      'trialing'::public.workspace_entitlement_status,
      completed_timestamp,
      completed_timestamp + interval '14 days',
      completed_timestamp,
      completed_timestamp + interval '14 days',
      actor_user_id,
      'internal'::public.workspace_entitlement_provider,
      completed_timestamp,
      completed_timestamp
    )
    on conflict (workspace_id) do nothing;
  end if;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id,
    actor_user_id,
    case when mark_complete then 'workspace.onboarding_completed' else 'workspace.onboarding_saved' end,
    'workspace',
    target_workspace_id::text,
    jsonb_build_object(
      'step', next_step,
      'previous_revision', current_revision,
      'revision', current_revision + 1
    )
  );
end;
$$;


ALTER FUNCTION "app_private"."apply_owner_onboarding_update"("actor_user_id" "uuid", "target_workspace_id" "uuid", "workspace_name" "text", "next_step" smallint, "mark_complete" boolean, "expected_revision" integer, "owner_first_name" "text", "owner_middle_name" "text", "owner_last_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_document_definition_target"("actor" "uuid", "w" "uuid", "target" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare options jsonb; pair text[]; selected jsonb;
begin
 options:=public.document_definition_target_options_service(actor,w);
 if coalesce(target->>'operator','and') not in ('and','or') then raise exception 'valid target operator required' using errcode='22023'; end if;
 foreach pair slice 1 in array array[['location_ids','locations'],['department_ids','departments'],['job_ids','jobs'],['employee_ids','employees']] loop
  if jsonb_typeof(coalesce(target->pair[1],'[]'))<>'array' then raise exception 'valid target selection required' using errcode='22023'; end if;
  for selected in select value from jsonb_array_elements(coalesce(target->pair[1],'[]')) loop
   if not exists(select 1 from jsonb_array_elements(options->pair[2]) o where o->'id'=selected) then raise exception 'document target access denied' using errcode='42501'; end if;
  end loop;
 end loop;
end;
$$;


ALTER FUNCTION "app_private"."assert_document_definition_target"("actor" "uuid", "w" "uuid", "target" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."employee_onboarding_requirements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "case_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "kind" "public"."employee_onboarding_requirement_kind" NOT NULL,
    "source_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "required" boolean DEFAULT true NOT NULL,
    "blocks_activation" boolean DEFAULT true NOT NULL,
    "requires_review" boolean DEFAULT false NOT NULL,
    "sort_order" integer NOT NULL,
    "status" "public"."employee_onboarding_requirement_status" DEFAULT 'not_started'::"public"."employee_onboarding_requirement_status" NOT NULL,
    "source_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "rejection_reason" "text",
    "completed_at" timestamp with time zone,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lifecycle_revision" integer DEFAULT 1 NOT NULL,
    "lifecycle_settings" "jsonb",
    "lifecycle_user_id" "uuid",
    "deadline_at" timestamp with time zone,
    "paused_remaining_seconds" numeric,
    "document_suspended_at" timestamp with time zone,
    "lifecycle_closed_at" timestamp with time zone,
    "lifecycle_close_reason" "text",
    "lifecycle_exempt" boolean DEFAULT false NOT NULL,
    "conditional_reason" "text",
    "submitted_document_id" "uuid",
    "approved_document_id" "uuid",
    "lifecycle_retired_at" timestamp with time zone,
    "lifecycle_assignment_disabled" boolean DEFAULT false NOT NULL,
    "publication_paused_at" timestamp with time zone,
    "owner_excused" boolean DEFAULT false NOT NULL,
    CONSTRAINT "employee_onboarding_requirements_check" CHECK (((NOT "blocks_activation") OR "required")),
    CONSTRAINT "employee_onboarding_requirements_description_check" CHECK (("char_length"("description") <= 500)),
    CONSTRAINT "employee_onboarding_requirements_lifecycle_revision_check" CHECK (("lifecycle_revision" > 0)),
    CONSTRAINT "employee_onboarding_requirements_paused_remaining_seconds_check" CHECK (("paused_remaining_seconds" >= (0)::numeric)),
    CONSTRAINT "employee_onboarding_requirements_rejection_reason_check" CHECK ((("rejection_reason" IS NULL) OR (("char_length"("rejection_reason") >= 1) AND ("char_length"("rejection_reason") <= 500)))),
    CONSTRAINT "employee_onboarding_requirements_sort_order_check" CHECK (("sort_order" >= 0)),
    CONSTRAINT "employee_onboarding_requirements_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 120)))
);


