COMMENT ON FUNCTION "app_private"."clear_member_avatar"("target_membership_id" "uuid") IS 'Deletes a membership''s avatar (public.member_avatars) and every app_private.last_avatars row whose source is that membership; returns the removed photo_path, null for a drawing or no avatar (AVATAR-IKON, S-187). Does not authorize: the caller authorizes first. Callers: remove_own_avatar_service and remove_member_photo_service. Access removal (public.remove_employee_access_service, decision S-187) will call it when a person''s access to a workspace is removed; that call is not wired yet. The caller must delete the returned object from the employee-profile-photos bucket.';



CREATE OR REPLACE FUNCTION "app_private"."close_employee_side"("w" "uuid", "emp" "uuid", "actor" "uuid", "reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  impact jsonb;
  opened uuid[];
  closed record;
  why text := case reason
    when 'terminated' then 'This person no longer works here.'
    when 'access_removed' then 'This person no longer has access to the workspace.'
    else 'This person no longer works shifts here.' end;
begin
  if reason is null or reason not in ('access_dropped', 'terminated', 'access_removed') then
    raise exception 'unknown reason to close the employee side' using errcode = '22023';
  end if;
  perform public.availability_lock_workspace(w);
  impact := app_private.employee_side_impact(w, emp);

  if reason = 'access_dropped' then
    with released as (
      update public.schedule_published_shifts shift
      set employee_id = null
      from public.schedule_location_publications publication, public.locations location
      where publication.id = shift.publication_id and publication.workspace_id = shift.workspace_id
        and publication.location_id = shift.location_id and publication.status = 'current'
        and location.id = shift.location_id and location.workspace_id = shift.workspace_id
        and shift.workspace_id = w and shift.employee_id = emp
        and (shift.scheduled_date + shift.start_time) at time zone location.timezone >= now()
      returning shift.id)
    select coalesce(array_agg(id), '{}') into opened from released;
    perform app_private.schedule_tell_unassigned(w, opened, actor);
  else
    impact := impact || jsonb_build_object('shifts_opened', 0, 'availability_deleted', false);
  end if;

  -- Their own requests: a swap, a cover, a release.
  for closed in
    update public.shift_exchange_cases c
    set status = 'cancelled', revision = c.revision + 1, updated_at = now()
    where c.workspace_id = w and c.owner_id = emp and c.status = 'open'
    returning c.id
  loop
    update public.shift_exchange_applications
    set status = 'closed_case_cancelled', updated_at = now()
    where case_id = closed.id and status in ('invited', 'pending_manager');
    delete from public.shift_exchange_votes where case_id = closed.id;
    perform public.shift_exchange_emit(actor, w, closed.id, null, 'case_closed',
      why || case when reason = 'access_removed' then ' This request was closed. The owner keeps this shift.'
        else ' This request was closed. The shift is open for someone else to pick up.' end);
  end loop;

  -- What they answered on somebody else's request; a request made to them alone closes with it.
  for closed in
    update public.shift_exchange_applications a
    set status = 'closed_case_cancelled', updated_at = now()
    from public.shift_exchange_cases c
    where c.id = a.case_id and c.workspace_id = a.workspace_id and c.status = 'open'
      and a.workspace_id = w and a.employee_id = emp and a.status in ('invited', 'pending_manager')
    returning a.id, a.case_id, c.audience
  loop
    delete from public.shift_exchange_votes where case_id = closed.case_id and application_id = closed.id;
    update public.shift_exchange_cases
    set status = case when closed.audience = 'direct' then 'cancelled' else status end,
        revision = revision + 1, updated_at = now()
    where id = closed.case_id;
    perform public.shift_exchange_emit(actor, w, closed.case_id, closed.id, 'application_closed',
      why || ' Their answer was closed. No assignment changed.');
  end loop;

  -- Their time off waiting for an answer is withdrawn (design §4.8; time off rebuild D2); its cards close (D3).
  for closed in
    update public.time_off_requests r
    set status = 'withdrawn', ended_by = actor, ended_at = now(), ended_note = why, revision = r.revision + 1, updated_at = now()
    where r.workspace_id = w and r.employee_id = emp and r.status = 'pending'
    returning r.id
  loop
    perform app_private.notification_resolve(w, 'time_off', closed.id, 'withdrawn', actor);
  end loop;

  return impact;
end;
$$;


ALTER FUNCTION "app_private"."close_employee_side"("w" "uuid", "emp" "uuid", "actor" "uuid", "reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."schedule_edit_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "week_start" "date" NOT NULL,
    "source_kind" "public"."schedule_edit_source" NOT NULL,
    "source_draft_id" "uuid",
    "source_revision" integer DEFAULT 0 NOT NULL,
    "holder_user_id" "uuid" NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "dirty" boolean DEFAULT false NOT NULL,
    "status" "public"."schedule_edit_session_status" DEFAULT 'active'::"public"."schedule_edit_session_status" NOT NULL,
    "last_heartbeat" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '00:04:00'::interval) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "recovered_draft_id" "uuid",
    "location_ids" "uuid"[] NOT NULL,
    "base_publication_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    CONSTRAINT "schedule_edit_sessions_check" CHECK (((("source_kind" = 'draft'::"public"."schedule_edit_source") AND ("source_draft_id" IS NOT NULL) AND ("source_revision" > 0)) OR (("source_kind" <> 'draft'::"public"."schedule_edit_source") AND ("source_draft_id" IS NULL)))),
    CONSTRAINT "schedule_edit_sessions_location_ids_check" CHECK (("cardinality"("location_ids") > 0)),
    CONSTRAINT "schedule_edit_sessions_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "schedule_edit_sessions_source_revision_check" CHECK (("source_revision" >= 0))
);


ALTER TABLE "public"."schedule_edit_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."close_schedule_edit_session"("edit" "public"."schedule_edit_sessions") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare recovery_draft_id uuid; base_name text; draft_name text; copy integer := 1;
begin
  -- Unsaved work becomes a recovery draft; nothing of it is deleted.
  if edit.dirty then
    -- KK-162: "Auto-save · Ayşe Yılmaz · Oct 5, 9:14 PM", in the edit's
    -- location's time and the workspace's 12/24-hour clock.
    base_name := 'Auto-save · ' || left(coalesce(nullif(btrim((select profile.display_name from public.user_profiles profile
        where profile.user_id = edit.holder_user_id)), ''), 'Manager'), 40)
      || ' · ' || to_char(now() at time zone coalesce((select location.timezone from public.locations location
          where location.id = any(edit.location_ids) order by location.name, location.id limit 1), 'UTC'),
        case when (select settings.time_format from public.workspace_scheduling_settings settings
          where settings.workspace_id = edit.workspace_id) = '24h' then 'Mon FMDD, HH24:MI' else 'Mon FMDD, FMHH12:MI AM' end);
    draft_name := base_name;
    -- ponytail: names are unique in a week; count up until one is free.
    while exists (select 1 from public.schedule_drafts draft
      where draft.workspace_id = edit.workspace_id and draft.week_start = edit.week_start
        and draft.archived_at is null and lower(btrim(draft.name)) = lower(btrim(draft_name))) loop
      copy := copy + 1;
      draft_name := base_name || ' (' || copy || ')';
    end loop;
    insert into public.schedule_drafts (
      workspace_id, week_start, name, created_by, updated_by, location_ids, base_publication_ids
    ) values (
      edit.workspace_id, edit.week_start, draft_name,
      edit.holder_user_id, edit.holder_user_id, edit.location_ids, edit.base_publication_ids
    ) returning id into recovery_draft_id;
    insert into public.schedule_draft_shifts (id, workspace_id, draft_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, revision, label_ids, label_names)
    select id, workspace_id, recovery_draft_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, revision, label_ids, label_names
    from public.schedule_edit_session_shifts
    -- A shift the person took off stays off, as when they save.
    where session_id = edit.id and pending_op_type is distinct from 'delete';
  end if;
  update public.schedule_edit_sessions
  set status = case when recovery_draft_id is null then 'expired'::public.schedule_edit_session_status
                    else 'recovered'::public.schedule_edit_session_status end,
      recovered_draft_id = recovery_draft_id,
      closed_at = now()
  where id = edit.id;
  return recovery_draft_id;
end;
$$;


ALTER FUNCTION "app_private"."close_schedule_edit_session"("edit" "public"."schedule_edit_sessions") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."closure_covers"("kind" "text", "opens" time without time zone, "closes" time without time zone, "starts" time without time zone, "ends" time without time zone) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case kind
    when 'closed' then true
    when 'short' then coalesce(not (m.s >= m.o and m.e <= m.c), false)
    else false end
  from (select extract(epoch from starts) / 60 s,
               extract(epoch from ends) / 60 + case when ends <= starts then 1440 else 0 end e,
               extract(epoch from opens) / 60 o,
               extract(epoch from closes) / 60 + case when closes <= opens then 1440 else 0 end c) m
$$;


ALTER FUNCTION "app_private"."closure_covers"("kind" "text", "opens" time without time zone, "closes" time without time zone, "starts" time without time zone, "ends" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."closure_reason"("kind" "text", "opens" time without time zone, "closes" time without time zone, "starts" time without time zone, "ends" time without time zone) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when kind = 'closed' then 'closed'
    when kind <> 'short' or not app_private.closure_covers(kind, opens, closes, starts, ends) then null
    when m.e <= m.o then 'prep'
    when m.s >= m.c then 'after_close'
    else 'over' end
  from (select extract(epoch from starts) / 60 s,
               extract(epoch from ends) / 60 + case when ends <= starts then 1440 else 0 end e,
               extract(epoch from opens) / 60 o,
               extract(epoch from closes) / 60 + case when closes <= opens then 1440 else 0 end c) m
$$;


ALTER FUNCTION "app_private"."closure_reason"("kind" "text", "opens" time without time zone, "closes" time without time zone, "starts" time without time zone, "ends" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."communication_reason"("state" "app_private"."actor_state", "w" "uuid", "kind" "text", "stored" "uuid"[], "author" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  live uuid[] := app_private.live_locations(w, stored);
  writer uuid := (
    select membership.user_id from public.workspace_memberships membership
    where membership.workspace_id = w and membership.user_id = author and membership.status = 'active'
  );
  -- The role the author last had here, whether they are still here or not.
  last_role public.workspace_role := (
    select role.access_class from public.workspace_memberships membership
    join public.workspace_roles role on role.id = coalesce(membership.role_id, membership.employee_role_id) and role.workspace_id = membership.workspace_id
    where membership.workspace_id = w and membership.user_id = author
  );
  narrow app_private.authz_actions;
  wide app_private.authz_actions;
  reason text;
begin
  select * into strict narrow from app_private.authz_actions a where a.key = kind || '.write';
  select * into strict wide from app_private.authz_actions a where a.key = kind || '.write_wide';
  -- An admin or owner who has left protects the record harder, not softer:
  -- only an admin or the owner changes it (Mert, 2026-10-02, O1; fail
  -- closed). So does a record that no longer says who wrote it (a deleted
  -- account). A manager who has left ranks as the manager they were ("En
  -- nihayetinde o da müdürdü.", Mert, 2026-10-02): the K3 rule goes on.
  if writer is null and (last_role is null or last_role in ('owner', 'admin')) then
    reason := app_private.authz_check(state, wide, null, null, null);
    return case when reason = 'out_of_scope' then 'rank' else reason end;
  end if;
  writer := author;
  if cardinality(stored) > 0 and cardinality(live) = 1 then
    return app_private.authz_check(state, narrow, live, null, writer);
  end if;
  return app_private.authz_check(state, wide, null, null, writer);
end;
$$;


ALTER FUNCTION "app_private"."communication_reason"("state" "app_private"."actor_state", "w" "uuid", "kind" "text", "stored" "uuid"[], "author" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."complete_due_workspace_closures"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  due record;
  scheduled_request public.workspace_closure_requests%rowtype;
  completed integer := 0;
begin
  for due in
    select workspace.id, workspace.closure_effective_at, workspace.created_by
    from public.workspaces workspace
    where workspace.lifecycle_status = 'closure_scheduled'
      and workspace.closure_effective_at <= now()
    order by workspace.closure_effective_at
    for update skip locked
  loop
    -- One workspace's failure undoes only its own closure and stays scheduled
    -- for the next run; the others still close (as time_off_sweep does).
    begin
      select * into scheduled_request
      from public.workspace_closure_requests request
      where request.workspace_id = due.id
        and request.status = 'scheduled'
      order by request.created_at desc
      limit 1
      for update;

      update public.workspace_closure_requests
      set status = 'completed',
          completed_at = now(),
          updated_at = now()
      where id = scheduled_request.id;

      perform app_private.finish_workspace_closure(
        due.id, coalesce(scheduled_request.requested_by, due.created_by), scheduled_request.id,
        due.closure_effective_at, 'scheduled'
      );
      completed := completed + 1;
    exception when others then
      raise warning 'workspace-closures: workspace % failed: % %', due.id, sqlstate, sqlerrm;
    end;
  end loop;

  return completed;
end;
$$;


ALTER FUNCTION "app_private"."complete_due_workspace_closures"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."daily_lineup_rows_no_replace_loop"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  step uuid := new.replaced_by_row_id;
  hops integer := 0;
begin
  -- A row pointing at itself is daily_lineup_rows_replaced_by_other's to refuse.
  if step = new.id then
    return new;
  end if;
  while step is not null and hops < 100 loop
    if step = new.id then
      raise exception 'A row cannot be replaced by one it replaced' using errcode = '23514',
        constraint = 'daily_lineup_rows_replaced_by_loop', hint = 'lineup.replace_loop';
    end if;
    select r.replaced_by_row_id into step from public.daily_lineup_rows r where r.id = step;
    hops := hops + 1;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."daily_lineup_rows_no_replace_loop"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."deal_lineup_art"("seed" "text", "pairs" "jsonb", "stored" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  team text[] := array(select a.key from app_private.lineup_art a where a.kind = 'team');
  dealt jsonb := '{}';
  used jsonb := '{}';
  pair record;
  best text;
begin
  -- pairs: [{employee_id, job_id, icons}]; stored: {"<employee>:<job>": key}. Returns {"<employee>:<job>": key}.
  -- The written pairs of this lineup stay as written, and count.
  for pair in
    select s.key as k, s.value as art
    from jsonb_each_text(coalesce(stored, '{}'::jsonb)) s
    where exists (select 1 from jsonb_array_elements(coalesce(pairs, '[]'::jsonb)) x
                  where (x ->> 'employee_id') || ':' || (x ->> 'job_id') = s.key)
  loop
    dealt := dealt || jsonb_build_object(pair.k, pair.art);
    used := used || jsonb_build_object(pair.art, coalesce((used ->> pair.art)::integer, 0) + 1);
  end loop;
  -- The rest in the seed's order, each the least used of its pool; a tie goes in the seed's order of the pool.
  for pair in
    select t.k, t.icons from (
      select distinct on (k) (x ->> 'employee_id') || ':' || (x ->> 'job_id') as k,
        array(select jsonb_array_elements_text(coalesce(x -> 'icons', '[]'::jsonb))) as icons
      from jsonb_array_elements(coalesce(pairs, '[]'::jsonb)) x
      order by k) t
    where not dealt ? t.k
    order by md5(seed || ':' || t.k), t.k
  loop
    select c into best
    from unnest(case when cardinality(pair.icons) > 0 then pair.icons else team end) c
    order by coalesce((used ->> c)::integer, 0), md5(seed || ':' || c), c
    limit 1;
    dealt := dealt || jsonb_build_object(pair.k, best);
    if best is not null then
      used := used || jsonb_build_object(best, coalesce((used ->> best)::integer, 0) + 1);
    end if;
  end loop;
  return dealt;
end;
$$;


ALTER FUNCTION "app_private"."deal_lineup_art"("seed" "text", "pairs" "jsonb", "stored" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."deal_lineup_art"("seed" "text", "pairs" "jsonb", "stored" "jsonb") IS 'AVATAR-IKON slice 4: deals Lineup drawings to a lineup''s (person, job) pairs: written pairs stay; the rest, in md5(seed:pair) order, take the least used key of their job''s icons (the team drawings when it has none), ties in md5(seed:key) order.';



CREATE OR REPLACE FUNCTION "app_private"."decision_tier"("w" "uuid", "requester" "uuid", "loc" "uuid", "other" "uuid" DEFAULT NULL::"uuid", "action" "text" DEFAULT 'exchange.approve'::"text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with side as (
    select e.user_id from public.employee_profiles e
    where e.workspace_id = decision_tier.w and e.id in (decision_tier.requester, decision_tier.other) and e.user_id is not null
  ), decider as (
    -- Who holds a management access and may decide there; the class as the core holds it.
    select (app_private.actor(m.user_id, decision_tier.w)).class
    from public.workspace_memberships m
    where m.workspace_id = decision_tier.w and m.status = 'active' and m.role_id is not null
      and not exists (select 1 from side s where s.user_id = m.user_id)
      and app_private.authz_reason(m.user_id, decision_tier.w, decision_tier.action,
        case when decision_tier.loc is null then null else array[decision_tier.loc] end) is null
  )
  select case
    when exists (select 1 from decider d where d.class = 'manager') then 'location_manager'
    when exists (select 1 from decider d where d.class = 'admin') then 'admin'
    when exists (select 1 from decider d where d.class = 'owner') then 'owner'
    -- The owner holds every permission, so only an owner who is a side of it leaves nobody.
    else 'self_only' end;
$$;


