CREATE OR REPLACE FUNCTION "app_private"."dispatch_cron_endpoint"("endpoint_path" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  base_url text;
  cron_secret text;
begin
  select decrypted_secret into base_url
  from vault.decrypted_secrets where name = 'app_api_url';
  select decrypted_secret into cron_secret
  from vault.decrypted_secrets where name = 'cron_secret';

  -- No configuration means no call: local databases stay quiet and a restored
  -- backup never posts to someone else's deployment.
  if base_url is null or cron_secret is null then
    return null;
  end if;

  return net.http_post(
    url := rtrim(base_url, '/') || endpoint_path,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || cron_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 10000
  );
end;
$$;


ALTER FUNCTION "app_private"."dispatch_cron_endpoint"("endpoint_path" "text") OWNER TO "postgres";


