    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform pg_advisory_xact_lock(hashtextextended(coalesce(new.workspace_id,old.workspace_id)::text,52001));
 return coalesce(new,old);
end;
$$;


