CREATE OR REPLACE FUNCTION "app_private"."document_initial_action_missing"("r" "public"."employee_onboarding_requirements") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select r.publication_paused_at is null and r.kind='document' and r.lifecycle_settings->>'mode'='conditional'
  and not r.lifecycle_exempt and r.lifecycle_closed_at is null and r.status<>'superseded'
  and app_private.document_obligation_state(r,now())<>'completed'
  and not exists(select 1 from public.employee_document_submissions s where s.id=r.submitted_document_id and s.state in ('accepted','pending_review'))
  and (nullif(btrim(r.conditional_reason),'') is null or exists(select 1 from public.employee_document_submissions s where s.requirement_id=r.id and s.state='rejected'));
$$;


ALTER FUNCTION "app_private"."document_initial_action_missing"("r" "public"."employee_onboarding_requirements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_obligation_blocked"("r" "public"."employee_onboarding_requirements", "at_time" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare state text; pending public.employee_document_submissions%rowtype;
begin
 state:=app_private.document_obligation_state(r,at_time);
 if state in ('completed','removed','exempt','paused') or coalesce(r.lifecycle_settings->>'mode','optional')='optional'
  or not coalesce((r.lifecycle_settings->>'suspend_on_overdue')::boolean,false) then return false; end if;
 -- A past suspension cannot be undone by a fresh submission or rejection period.
 if r.document_suspended_at is not null then return true; end if;
 select * into pending from public.employee_document_submissions where id=r.submitted_document_id;
 if pending.state='pending_review' and (r.deadline_at is null or pending.submitted_at<=r.deadline_at) then return false; end if;
 return r.deadline_at is not null and r.deadline_at<=at_time;
end;
$$;


ALTER FUNCTION "app_private"."document_obligation_blocked"("r" "public"."employee_onboarding_requirements", "at_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_obligation_json"("r" "public"."employee_onboarding_requirements") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select jsonb_build_object(
  'id',r.id,'workspace_id',r.workspace_id,'employee_id',r.employee_id,'employee_name',concat_ws(' ',e.first_name,e.last_name),
  'title',r.title,'source_id',r.source_id,'kind',r.kind,'mode',r.lifecycle_settings->>'mode',
  'publication_paused',r.publication_paused_at is not null,'status',case when r.publication_paused_at is not null and not r.lifecycle_exempt and r.lifecycle_closed_at is null then 'paused' when not r.lifecycle_exempt and r.lifecycle_closed_at is null and r.status<>'superseded'
    and exists(select 1 from public.employee_document_submissions s where s.id=r.submitted_document_id and s.state='pending_review')
    then 'pending_review' else app_private.document_obligation_state(r,now()) end,'revision',r.lifecycle_revision,'requires_review',r.requires_review,
  'deadline_at',r.deadline_at,'remaining_seconds',case when r.publication_paused_at is not null then null else coalesce(r.paused_remaining_seconds,case when r.deadline_at is not null then greatest(0,extract(epoch from r.deadline_at-now())) end) end,
  'rejection_reason',r.rejection_reason,'suspended',app_private.document_obligation_blocked(r,now()),
  'exemption_locked',app_private.employee_record_is_workspace_owner(r.workspace_id,r.employee_id),
  'submitted_id',r.submitted_document_id,'approved_id',r.approved_document_id,
  'location_ids',coalesce((select jsonb_agg(l.id order by l.name) from public.employee_location_assignments a join public.locations l on l.id=a.location_id and l.workspace_id=a.workspace_id where a.employee_id=r.employee_id and a.workspace_id=r.workspace_id and a.ended_at is null),'[]'),
  'location_names',coalesce((select jsonb_agg(l.name order by l.name) from public.employee_location_assignments a join public.locations l on l.id=a.location_id and l.workspace_id=a.workspace_id where a.employee_id=r.employee_id and a.workspace_id=r.workspace_id and a.ended_at is null),'[]'),
  'timezone',app_private.document_employee_timezone(r.workspace_id,r.employee_id),'settings',r.lifecycle_settings,
  'accepted_formats',coalesce(r.source_snapshot->'accepted_formats','[]'), 'tracks_expiry',coalesce((r.source_snapshot->>'tracks_expiry')::boolean,false),
  'expiry_date',(select s.expiry_date from public.employee_document_submissions s where s.id=r.approved_document_id and s.requirement_id=r.id),
  'expiring_soon',coalesce((select s.expiry_date<=current_date+t.expiry_warning_days
    from public.employee_document_submissions s
    join public.document_types t on t.id=r.source_id and t.workspace_id=r.workspace_id and t.tracks_expiry and t.archived_at is null
    where s.id=r.approved_document_id and s.requirement_id=r.id and s.expiry_date is not null),false))
 from public.employee_profiles e where e.id=r.employee_id and e.workspace_id=r.workspace_id;
$$;


ALTER FUNCTION "app_private"."document_obligation_json"("r" "public"."employee_onboarding_requirements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_obligation_state"("r" "public"."employee_onboarding_requirements", "at_time" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare approved public.employee_document_submissions%rowtype; submitted public.employee_document_submissions%rowtype;
begin
 if r.lifecycle_exempt then return 'exempt'; end if;
 if r.lifecycle_closed_at is not null or r.status='superseded' then return 'removed'; end if;
 if r.publication_paused_at is not null then return 'paused'; end if;
 select * into approved from public.employee_document_submissions where id=r.approved_document_id;
 select * into submitted from public.employee_document_submissions where id=r.submitted_document_id;
 -- Expiration is a date. Its zone is snapshotted on assignment; legacy uses UTC
 -- until an explicit org-zone Apply, never the session's TimeZone setting.
 if approved.id is not null and approved.expiry_date is not null and app_private.document_employee_timezone(r.workspace_id,r.employee_id) is null then return 'timezone_required'; end if; if approved.id is not null and (approved.expiry_date is null or approved.expiry_date >= (at_time at time zone app_private.document_employee_timezone(r.workspace_id,r.employee_id))::date) then return 'completed'; end if;
 if submitted.state='pending_review' then return 'pending_review'; end if;
 if submitted.state='rejected' then return 'rejected'; end if;
 if approved.id is not null then return 'expired'; end if;
 if r.kind='acknowledgement' and r.status='completed' then return 'completed'; end if;
 if r.lifecycle_settings->>'mode'='conditional' and r.deadline_at>at_time then return 'grace'; end if;
 return 'missing';
end;
$$;


ALTER FUNCTION "app_private"."document_obligation_state"("r" "public"."employee_onboarding_requirements", "at_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_reconcile_employee"("w" "uuid", "e" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.employee_profiles%rowtype; m public.workspace_memberships%rowtype; r public.employee_onboarding_requirements%rowtype;
 d app_private.lifecycle_definition%rowtype; c uuid; matching boolean; valid_approved boolean; next_deadline timestamptz; changed boolean:=false;
begin
 perform pg_advisory_xact_lock(hashtextextended(w::text,52001));
 select * into p from public.employee_profiles where id=e and workspace_id=w;
 select * into m from public.workspace_memberships where workspace_id=w and user_id=p.user_id;
 if p.id is null or p.user_id is null then return; end if;
 -- Lock order follows document commands: case, then requirements.
 perform 1 from public.employee_onboarding_cases where workspace_id=w and employee_id=e for update;
 for r in select * from public.employee_onboarding_requirements where workspace_id=w and employee_id=e and kind in ('document','acknowledgement') and lifecycle_retired_at is null order by id for update loop
  if r.publication_paused_at is not null or r.lifecycle_exempt or r.lifecycle_assignment_disabled then continue; end if;
  matching:=p.archived_at is null and m.status in ('active','pending_activation')
   
   and app_private.document_target_matches(w,e,r.lifecycle_settings->'target');
  -- Source-less historical requirements retain their explicit assignment.
  if r.source_id is null then continue; end if;
  if not matching and r.lifecycle_closed_at is null then
   update public.employee_onboarding_requirements set lifecycle_closed_at=now(),lifecycle_close_reason='Employee no longer matches the assignment',
    deadline_at=null,paused_remaining_seconds=null,document_suspended_at=null,lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id;
   changed:=true; perform app_private.document_audit(r,null,'document.assignment_removed',jsonb_build_object('reason','target_changed','revision',r.lifecycle_revision+1));
  elsif matching and (r.lifecycle_closed_at is not null or r.status='superseded') then
   r.lifecycle_closed_at:=null; if r.status='superseded' then r.status:='not_started'; end if;
   valid_approved:=app_private.document_obligation_state(r,now())='completed';
   next_deadline:=case when not valid_approved and m.status='active' and r.lifecycle_settings->>'mode'<>'optional' and r.lifecycle_settings->>'period_days' is not null
    then now()+(r.lifecycle_settings->>'period_days')::integer*interval '24 hours' end;
   update public.employee_onboarding_requirements set lifecycle_closed_at=null,lifecycle_close_reason=null,
    status=case when valid_approved then 'completed'::public.employee_onboarding_requirement_status when status='superseded' then 'not_started'::public.employee_onboarding_requirement_status else status end,
    deadline_at=next_deadline,paused_remaining_seconds=null,document_suspended_at=null,lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id;
   changed:=true; perform app_private.document_audit(r,null,'document.assignment_reopened',jsonb_build_object('revision',r.lifecycle_revision+1,'deadline',next_deadline,'valid_approved',valid_approved));
  end if;
 end loop;
 if p.archived_at is not null or m.id is null or m.status not in ('active','pending_activation') then return; end if;
 for d in select * from app_private.lifecycle_definition dt where dt.workspace_id=w and dt.archived_at is null and dt.current_version
  and (m.status='pending_activation' or dt.lifecycle_settings->>'assignment_scope'='all_active')
  and app_private.document_target_matches(w,e,dt.lifecycle_settings->'target')
  and not exists(select 1 from public.employee_onboarding_requirements q where q.workspace_id=w and q.employee_id=e and q.kind::text=dt.kind and q.lifecycle_retired_at is null and q.source_id=dt.id) order by dt.id loop
  insert into public.employee_onboarding_cases(workspace_id,employee_id,membership_id,status,approved_at,approved_by)
  values(w,e,m.id,case when m.status='active' then 'approved'::public.employee_onboarding_case_status else 'in_progress'::public.employee_onboarding_case_status end,
   case when m.status='active' then now() end,case when m.status='active' then p.user_id end) on conflict(employee_id) do nothing;
  select id into c from public.employee_onboarding_cases where employee_id=e and workspace_id=w for update;
  insert into public.employee_onboarding_requirements(workspace_id,employee_id,case_id,kind,source_id,title,description,required,blocks_activation,requires_review,sort_order,source_snapshot,lifecycle_settings)
  values(w,e,c,d.kind::public.employee_onboarding_requirement_kind,d.id,d.title,d.description,d.lifecycle_settings->>'mode'='required',d.lifecycle_settings->>'mode'='required',d.requires_review,100+d.sort_order,d.snapshot,d.lifecycle_settings)
  on conflict(case_id,kind,source_id) where lifecycle_retired_at is null do nothing returning * into r;
  if r.id is not null then if m.status='pending_activation' and r.required then update public.employee_onboarding_cases set status='changes_requested',revision=revision+1,updated_at=now() where id=r.case_id and status='submitted'; end if; changed:=true; perform app_private.document_audit(r,null,'document.assignment_created',jsonb_build_object('definition_revision',d.lifecycle_revision)); end if;
 end loop;
 if changed then select * into r from public.employee_onboarding_requirements where workspace_id=w and employee_id=e and kind in ('document','acknowledgement') and lifecycle_retired_at is null order by id limit 1; if r.id is not null then perform app_private.document_sync_onboarding(r.id,null); end if; end if;
end;
$$;


ALTER FUNCTION "app_private"."document_reconcile_employee"("w" "uuid", "e" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_requirement_asked"("requirement" "public"."employee_onboarding_requirements") RETURNS "public"."employee_onboarding_requirements"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  requirement.required := requirement.lifecycle_settings ->> 'mode' = 'required';
  requirement.blocks_activation := requirement.required;
  return requirement;
end;
$$;


ALTER FUNCTION "app_private"."document_requirement_asked"("requirement" "public"."employee_onboarding_requirements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_row_readable"("actor" "uuid", "r" "public"."employee_onboarding_requirements") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.document_actor_can_read(actor, r.workspace_id, r.employee_id, r.lifecycle_user_id)
    and (r.approved_document_id is not null
      or not exists (
        select 1 from public.employee_document_submissions s
        where s.id = r.submitted_document_id and s.state = 'pending_review')
      or app_private.document_sees_pending(actor, r));
$$;


ALTER FUNCTION "app_private"."document_row_readable"("actor" "uuid", "r" "public"."employee_onboarding_requirements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_sees_pending"("actor" "uuid", "r" "public"."employee_onboarding_requirements") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select r.lifecycle_user_id = actor
    or app_private.authz_reason(actor, r.workspace_id, 'documents.review', null, r.employee_id) is null;
$$;


ALTER FUNCTION "app_private"."document_sees_pending"("actor" "uuid", "r" "public"."employee_onboarding_requirements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_shift_reasons"("w" "uuid", "e" "uuid", "shift_day" "date", "shift_start" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; approved public.employee_document_submissions%rowtype;
 submitted public.employee_document_submissions%rowtype; code text; result jsonb:='[]'; state text;
begin
 for r in select * from public.employee_onboarding_requirements where workspace_id=w and employee_id=e and kind='document'
  and publication_paused_at is null and lifecycle_settings->>'mode'<>'optional' and not lifecycle_exempt and lifecycle_closed_at is null and status<>'superseded' order by id loop
  select * into approved from public.employee_document_submissions where id=r.approved_document_id;
  if approved.id is not null and (approved.expiry_date is null or approved.expiry_date>=shift_day) then continue; end if;
  select * into submitted from public.employee_document_submissions where id=r.submitted_document_id;
  state:=case when submitted.state='pending_review' then 'pending_review' when submitted.state='rejected' then 'rejected' when approved.id is not null then 'expired' else 'missing' end;
  code:=case when r.lifecycle_settings->>'mode'='required' then 'document_required'
   when r.document_suspended_at is null and ((submitted.state='pending_review' and coalesce(r.paused_remaining_seconds,0)>0) or r.deadline_at>shift_start) then 'document_conditional_grace'
   else 'document_conditional_overdue' end;
  result:=result||jsonb_build_array(jsonb_build_object('code',code,'definite',true,
   'message',format('%s: %s.',r.title,replace(state,'_',' ')),'requirement_id',r.id,'document_status',state,'expiry_date',approved.expiry_date,'deadline_at',r.deadline_at));
 end loop;
 return result;
end;
$$;


ALTER FUNCTION "app_private"."document_shift_reasons"("w" "uuid", "e" "uuid", "shift_day" "date", "shift_start" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_submission_visible"("actor" "uuid", "r" "public"."employee_onboarding_requirements", "submission_state" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select submission_state = 'accepted'
    or (submission_state in ('pending_review', 'superseded', 'rejected') and app_private.document_sees_pending(actor, r));
$$;


ALTER FUNCTION "app_private"."document_submission_visible"("actor" "uuid", "r" "public"."employee_onboarding_requirements", "submission_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_suspend_overdue"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare suspended integer;
begin
  update public.employee_onboarding_requirements q set document_suspended_at = now()
  from public.employee_onboarding_cases oc
  join public.employee_profiles p on p.id = oc.employee_id and p.workspace_id = oc.workspace_id and p.archived_at is null
  join public.workspace_memberships m on m.id = oc.membership_id and m.user_id = p.user_id
    and m.status in ('active', 'pending_activation')
  where q.case_id = oc.id
    and q.document_suspended_at is null and q.lifecycle_retired_at is null
    -- What document_obligation_blocked needs before it can say yes, read first so the check runs on few rows.
    and q.deadline_at <= now()
    and coalesce((q.lifecycle_settings ->> 'suspend_on_overdue')::boolean, false)
    and app_private.workspace_allows_interactive_access(oc.workspace_id)
    and app_private.document_obligation_blocked(q, now());
  get diagnostics suspended = row_count;
  return suspended;
end;
$$;


ALTER FUNCTION "app_private"."document_suspend_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_sync_onboarding"("target_requirement_id" "uuid", "actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; c public.employee_onboarding_cases%rowtype;
begin
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id;
 update public.employee_documents f set review_status=case
  when sf.decision='discard' then 'superseded'::public.employee_document_review_status
  when s.id=r.approved_document_id and s.state='accepted' then 'accepted'::public.employee_document_review_status
  when s.id=r.submitted_document_id and s.state='pending_review' then 'awaiting_review'::public.employee_document_review_status
  when s.id=r.submitted_document_id and s.state='rejected' then 'rejected'::public.employee_document_review_status
  else 'superseded'::public.employee_document_review_status end, expiry_date=s.expiry_date
 from public.employee_document_submission_files sf join public.employee_document_submissions s on s.id=sf.submission_id
 where sf.file_id=f.id and s.requirement_id=r.id;
 if app_private.document_obligation_state(r,now())='completed' then
  update public.employee_onboarding_requirements set status='completed' where id=r.id and status<>'completed';
 end if;
 select c0.* into c from public.employee_onboarding_cases c0 join public.workspace_memberships m on m.id=c0.membership_id
 where c0.id=r.case_id and m.status='pending_activation' for update of c0;
 if c.id is null then return; end if;
 if r.kind='document' and r.lifecycle_settings->>'mode' in ('required','conditional') and r.status='rejected' and app_private.document_obligation_state(r,now())<>'completed' then c.status:='changes_requested'; end if; update public.employee_onboarding_cases set status=c.status,revision=revision+1,updated_at=now() where id=c.id;
 if c.status='submitted' and not c.final_approval_required
  and not exists(select 1 from public.employee_onboarding_requirements q where q.case_id=c.id and
   (app_private.document_activation_blocked(q) or (q.required and q.blocks_activation and q.status<>'completed' and
    (q.kind<>'document' or (q.publication_paused_at is null and not q.lifecycle_exempt and q.lifecycle_closed_at is null and q.status<>'superseded'))))) then
  perform app_private.activate_employee_onboarding_case(c.id,coalesce(actor,r.lifecycle_user_id),'employee.auto_activated');
 end if;
end;
$$;


ALTER FUNCTION "app_private"."document_sync_onboarding"("target_requirement_id" "uuid", "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_target_matches"("w" "uuid", "e" "uuid", "target" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select app_private.document_target_matches_assignments(w,e,target,
  array(select location_id from public.employee_location_assignments where workspace_id=w and employee_id=e and ended_at is null),
  array(select job_id from public.employee_job_assignments where workspace_id=w and employee_id=e and ended_at is null));
$$;


ALTER FUNCTION "app_private"."document_target_matches"("w" "uuid", "e" "uuid", "target" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_target_matches_assignments"("w" "uuid", "e" "uuid", "target" "jsonb", "location_ids" "uuid"[], "job_ids" "uuid"[]) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare loc jsonb:=coalesce(target->'location_ids','[]'); dep jsonb:=coalesce(target->'department_ids','[]'); job jsonb:=coalesce(target->'job_ids','[]'); loc_ok boolean; job_ok boolean;
begin
 if coalesce(target->'employee_ids','[]') ? e::text then return true; end if;
 if jsonb_array_length(loc)+jsonb_array_length(dep)+jsonb_array_length(job)=0 then return true; end if;
 loc_ok:=exists(select 1 from public.locations l where l.workspace_id=w and l.id=any(location_ids) and l.archived_at is null and loc ? l.id::text);
 if coalesce(target->>'operator','and')='or' then
  return loc_ok or exists(select 1 from public.jobs j where j.workspace_id=w and j.id=any(job_ids) and j.archived_at is null and (job ? j.id::text or dep ? j.department_id::text));
 end if;
 job_ok:=exists(select 1 from public.jobs j where j.workspace_id=w and j.id=any(job_ids) and j.archived_at is null and (jsonb_array_length(job)=0 or job ? j.id::text) and (jsonb_array_length(dep)=0 or dep ? j.department_id::text));
 return (jsonb_array_length(loc)=0 or loc_ok) and ((jsonb_array_length(job)=0 and jsonb_array_length(dep)=0) or job_ok);
end;
$$;


ALTER FUNCTION "app_private"."document_target_matches_assignments"("w" "uuid", "e" "uuid", "target" "jsonb", "location_ids" "uuid"[], "job_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_tell"("r" "public"."employee_onboarding_requirements", "actor" "uuid", "event_action" "text", "event_metadata" "jsonb") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  person public.employee_profiles%rowtype;
  name text;
  decided text;
  now_row public.employee_onboarding_requirements%rowtype;
  sent integer := 0;
begin
  select * into person from public.employee_profiles e where e.id = r.employee_id and e.workspace_id = r.workspace_id;
  -- The row as it is now: an event may be handed the row from before its own change (an owner no longer
  -- excused after a handover is asked again).
  select * into now_row from public.employee_onboarding_requirements x where x.id = r.id;
  if person.user_id is null then
    return 0;
  end if;
  name := btrim(coalesce(nullif(person.preferred_name, ''), person.first_name) || ' ' || person.last_name);

  -- Asked: a document assigned or reopened (on publishing it, or the person coming to match it), or an
  -- exemption taken back.
  if event_action in ('document.assignment_created', 'document.assignment_reopened')
     or (event_action = 'document.definition_applied' and event_metadata ->> 'action' in ('assign', 'reopen'))
     or event_action = 'document.exemption_removed' then
    -- Nothing to do when what was approved before still counts, or the person no longer matches it. An
    -- exemption's row is the one before it was taken back: its event says.
    if now_row.owner_excused
       or (event_action = 'document.exemption_removed'
           and (coalesce((event_metadata ->> 'valid_approved')::boolean, false) or not coalesce((event_metadata ->> 'matching')::boolean, true)))
       or (event_action <> 'document.exemption_removed' and app_private.document_obligation_state(r, now()) not in ('grace', 'missing', 'rejected', 'expired')) then
      return 0;
    end if;
    -- The person's card: it closes when nothing is asked of them (document_tell_settle).
    return app_private.notify('documents.requested', r.workspace_id, array[person.user_id],
      -- One go, one notice: every document asked of the person in one transaction is one event.
      -- Asked again (an exemption taken back, a handover) is its own go, also one notice.
      case when event_action = 'document.exemption_removed' then 'doc_request_again:' else 'doc_request:' end
        || r.employee_id::text || ':' || txid_current()::text,
      'You have documents to complete', 'Open your documents to see what is asked and by when.',
      '/account/documents?workspace=' || r.workspace_id::text, actor, 'employee_documents', r.employee_id,
      jsonb_build_object('requirement_id', r.id, 'title', r.title));
  end if;

  -- Gone from under a waiting review: an exemption, an unassignment, the type taken down. Its cards close.
  if event_action in ('document.exempted', 'document.assignment_removed', 'document.publication_paused')
     or (event_action = 'document.definition_applied' and event_metadata ->> 'action' = 'remove') then
    perform app_private.notification_resolve(r.workspace_id, 'document_requirement', r.id, 'closed', actor);
  end if;

  if event_action = 'document.submitted' and event_metadata ->> 'state' = 'pending_review' then
    -- Accepted without review: nobody to ask, and the sender knows.
    sent := app_private.notify('documents.review_needed', r.workspace_id,
      app_private.notify_holders(r.workspace_id, 'documents.review', null, r.employee_id),
      'doc_review:' || r.id::text || ':' || coalesce(event_metadata ->> 'submission_id', ''),
      name || ' sent ' || r.title || ' for review', null,
      '/app/employees/documents?requirement=' || r.id::text, actor, 'document_requirement', r.id,
      jsonb_build_object('requirement_id', r.id, 'employee_id', r.employee_id));
  end if;

  if event_action in ('document.approve', 'document.reject') then
    decided := case when event_action = 'document.approve' then 'approved' else 'declined' end;
    sent := app_private.notify('documents.decided', r.workspace_id, array[person.user_id],
      'doc_decision:' || r.id::text || ':' || coalesce(event_metadata ->> 'revision', txid_current()::text),
      'Your ' || r.title || case when decided = 'approved' then ' was approved' else ' needs a change' end,
      case when decided = 'declined' then 'Open your documents to see what to change.' end,
      '/account/documents?workspace=' || r.workspace_id::text, actor, 'document_requirement', r.id,
      jsonb_build_object('requirement_id', r.id, 'outcome', decided));
    perform app_private.notification_resolve(r.workspace_id, 'document_requirement', r.id, decided, actor);
  end if;

  -- Nothing asked of the person any more: their "documents to complete" closes.
  if not exists (
    select 1 from public.employee_onboarding_requirements x
    where x.workspace_id = r.workspace_id and x.employee_id = r.employee_id and x.kind in ('document', 'acknowledgement')
      and x.lifecycle_retired_at is null and not x.owner_excused
      and app_private.document_obligation_state(x, now()) in ('grace', 'missing', 'rejected', 'expired')
  ) then
    perform app_private.notification_resolve(r.workspace_id, 'employee_documents', r.employee_id, 'completed', actor);
  end if;
  return sent;
end;
$$;


ALTER FUNCTION "app_private"."document_tell"("r" "public"."employee_onboarding_requirements", "actor" "uuid", "event_action" "text", "event_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_timezone_admin"("actor" "uuid", "w" "uuid", "e" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- Saves the person and writes document settings: an owner or an admin.
 select app_private.authz_reason(actor,w,'employee.save',null,e) is null
  and app_private.authz_reason(actor,w,'settings.documents.write') is null;
$$;


ALTER FUNCTION "app_private"."document_timezone_admin"("actor" "uuid", "w" "uuid", "e" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."document_view"("actor" "uuid", "r" "public"."employee_onboarding_requirements") RETURNS "public"."employee_onboarding_requirements"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if r.kind <> 'document' or r.submitted_document_id is null
    or not exists (select 1 from public.employee_document_submissions s
                   where s.id = r.submitted_document_id and s.state in ('pending_review', 'rejected'))
    or app_private.document_sees_pending(actor, r) then
    return r;
  end if;
  r.submitted_document_id := null;
  r.paused_remaining_seconds := null;
  r.rejection_reason := null;
  r.status := case when app_private.document_obligation_state(r, now()) = 'completed'
    then 'completed' else 'in_progress' end::public.employee_onboarding_requirement_status;
  return r;
end;
$$;


ALTER FUNCTION "app_private"."document_view"("actor" "uuid", "r" "public"."employee_onboarding_requirements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."draft_starts_from_its_publication"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  update public.schedule_drafts draft
  set base_publication_ids = array(
    select base_id from unnest(draft.base_publication_ids) base_id
    where not exists (
      select 1 from public.schedule_location_publications publication
      where publication.id = base_id and publication.location_id = new.location_id
    )
  ) || new.id
  where draft.id = new.source_draft_id;
  return null;
end;
$$;


ALTER FUNCTION "app_private"."draft_starts_from_its_publication"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."eligibility"("w" "uuid", "emp" "uuid", "shift" "jsonb", "ctx" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 op text:=ctx->>'operation';
 excluded uuid[]:=array(select value::uuid from jsonb_array_elements_text(
  case when jsonb_typeof(ctx->'excluded')='array' then ctx->'excluded' else '[]'::jsonb end) where value is not null);
 loc uuid:=(shift->>'location_id')::uuid; d date:=(shift->>'date')::date;
 tz text; span tstzrange; a jsonb; settings public.workspace_scheduling_settings%rowtype;
 blockers jsonb:='[]'; acks jsonb:='[]'; flags jsonb:='[]'; r jsonb;
 travel numeric; rest numeric; gap numeric; n record; near numeric; near_travel numeric;
begin
 if op is null or op not in ('swap','release_pickup','cover_accept') then
  raise exception 'Unknown exchange operation' using errcode='22023'; end if;
 if nullif(shift->>'start_time','') is null or nullif(shift->>'end_time','') is null then
  return jsonb_build_object('employee_id',emp,'operation',op,'eligible',false,'status','verification_required',
   'blockers',jsonb_build_array(jsonb_build_object('code','hours_unconfirmed','message','A manager must confirm the shift hours before a full-shift exchange')),
   'acknowledgements','[]'::jsonb,'approval_flags','[]'::jsonb,'approvals_required',jsonb_build_array(loc),
   'reasons',jsonb_build_array('A manager must confirm the shift hours before a full-shift exchange'));
 end if;
 select coalesce(nullif(shift->>'time_timezone',''),nullif(shift->'time_snapshot'->>'timezone',''),l.timezone) into tz
  from public.locations l where l.id=loc and l.workspace_id=w and l.archived_at is null;
 if tz is null then raise exception 'location not found'; end if;
 select * into settings from public.workspace_scheduling_settings where workspace_id=w;
 span:=app_private.shift_time_range(d,(shift->>'start_time')::time,(shift->>'end_time')::time,tz);

 if not exists(select 1 from public.employee_profiles e join public.workspace_memberships m
  on m.workspace_id=e.workspace_id and m.user_id=e.user_id and m.status='active' where e.workspace_id=w and e.id=emp) then
  blockers:=blockers||jsonb_build_array(jsonb_build_object('code','workspace_access','message','Active workspace access is required')); end if;
 if not exists(select 1 from public.employee_location_assignments x where x.workspace_id=w and x.employee_id=emp and x.location_id=loc
  and x.assigned_at<=lower(span) and (x.ended_at is null or x.ended_at>=upper(span))) then
  blockers:=blockers||jsonb_build_array(jsonb_build_object('code','location_assignment','message','Not assigned to this location')); end if;
 if not exists(select 1 from public.employee_job_assignments x where x.workspace_id=w and x.employee_id=emp and x.job_id=(shift->>'job_id')::uuid
  and x.assigned_at<=lower(span) and (x.ended_at is null or x.ended_at>=upper(span))) then
  blockers:=blockers||jsonb_build_array(jsonb_build_object('code','job_assignment','message','Not eligible for this position')); end if;
 -- Documents stay as they are today (out of scope 2): an expired blocking document,
 -- and any document rule the conflict settings raise, below.
 if public.employee_has_hard_document_schedule_conflict_service(w,emp,d) then
  blockers:=blockers||jsonb_build_array(jsonb_build_object('code','document_expired','message','Required document is expired')); end if;

 -- The assessment reads the shift the way Schedule does; '_shift_exchange'
 -- keeps travel and rest out of it, they are flags here (D7).
 a:=public.assess_weekly_shift_availability(w,emp,shift||jsonb_build_object('scheduled_date',d,
  '_exclude_shift_ids',to_jsonb(excluded),'_shift_exchange',true));
 for r in select value from jsonb_array_elements(a->'reasons') loop
  if r->>'code' not in ('availability','note') and not blockers @> jsonb_build_array(jsonb_build_object('code',r->>'code')) then
   blockers:=blockers||jsonb_build_array(jsonb_build_object('code',r->>'code','message',r->>'message')); end if;
 end loop;
 -- Approved time off is a blocker like the reasons above, even by a minute
 -- and for the person themselves (KARARLAR §1.1, 2026-10-09; BL-995).
 if coalesce((a->>'has_availability_conflict')::boolean,false) and jsonb_array_length(coalesce(a->'employee_intervals','[]'))>0 then
  acks:=acks||jsonb_build_array(jsonb_build_object('code','availability','intervals',a->'employee_intervals'));
  flags:=flags||jsonb_build_array(jsonb_build_object('code','availability_consent'));
 end if;
 if jsonb_array_length(coalesce(a->'manager_intervals','[]'))>0 then
  flags:=flags||jsonb_build_array(jsonb_build_object('code','manager_note')); end if;

 -- Travel and rest, measured against the person's other published shifts (D7).
 for n in select p.location_id,app_private.shift_time_range(p.scheduled_date,p.start_time,p.end_time,coalesce(p.time_timezone,l.timezone)) r
  from public.schedule_published_shifts p join public.schedule_location_publications pub on pub.id=p.publication_id and pub.status='current'
  join public.locations l on l.id=p.location_id
  where p.workspace_id=w and p.employee_id=emp and p.scheduled_date between d-2 and d+2
   and not p.id=any(excluded) and not coalesce(p.source_shift_id,p.id)=any(excluded)
 loop
  if n.r && span then continue; end if;
  gap:=extract(epoch from greatest(lower(span)-upper(n.r),lower(n.r)-upper(span)))/60;
  near:=least(coalesce(near,gap),gap);
  if n.location_id<>loc then near_travel:=least(coalesce(near_travel,gap),gap); end if;
  if n.location_id<>loc and gap<settings.minimum_travel_minutes then travel:=least(coalesce(travel,gap),gap); end if;
  if gap<settings.minimum_rest_minutes then rest:=least(coalesce(rest,gap),gap); end if;
 end loop;
 if travel is not null then flags:=flags||jsonb_build_array(jsonb_build_object('code','minimum_travel',
  'gap_minutes',travel::integer,'rule_minutes',settings.minimum_travel_minutes)); end if;
 if rest is not null then flags:=flags||jsonb_build_array(jsonb_build_object('code','minimum_rest',
  'gap_minutes',rest::integer,'rule_minutes',settings.minimum_rest_minutes)); end if;

 return jsonb_build_object('employee_id',emp,'operation',op,'eligible',jsonb_array_length(blockers)=0,
  'status',case when jsonb_array_length(blockers)=0 then 'eligible' else 'ineligible' end,
  'blockers',blockers,'acknowledgements',acks,'approval_flags',flags,'approvals_required',jsonb_build_array(loc),
  'reasons',case when jsonb_array_length(blockers)=0 then '["Position and location match","No assignment blockers"]'::jsonb
   else (select jsonb_agg(b->>'message') from jsonb_array_elements(blockers) b) end)
  ||case when coalesce((ctx->>'with_assessment')::boolean,false) then jsonb_build_object('assessment',a) else '{}'::jsonb end
  -- C2: the swap review names the rule that holds too ("12 h of rest / 10 h needed").
  ||case when coalesce((ctx->>'with_measures')::boolean,false) then jsonb_build_object('measures',jsonb_build_object(
   'rest_gap_minutes',near::integer,'travel_gap_minutes',near_travel::integer,
   'rest_rule_minutes',settings.minimum_rest_minutes,'travel_rule_minutes',settings.minimum_travel_minutes)) else '{}'::jsonb end;
end;
$$;


ALTER FUNCTION "app_private"."eligibility"("w" "uuid", "emp" "uuid", "shift" "jsonb", "ctx" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."email_channel_open"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  insert into app_private.notification_email_channel (opened_at) values (now())
  on conflict (only_row) do update set opened_at = excluded.opened_at;
  update public.notification_deliveries set status = 'skipped', last_error = 'before_launch', lease_expires_at = null,
    updated_at = now()
  where channel = 'email' and status in ('queued', 'sending', 'failed');
end;
$$;


ALTER FUNCTION "app_private"."email_channel_open"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."employee_onboarding_case_id"("target_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select onboarding.id
  from public.employee_onboarding_cases onboarding
  join public.employee_profiles candidate on candidate.id = onboarding.employee_id
  where candidate.user_id = target_user_id
    and (target_workspace_id is null or onboarding.workspace_id = target_workspace_id)
  order by onboarding.status in ('approved', 'cancelled'), onboarding.created_at
  limit 1;
$$;


ALTER FUNCTION "app_private"."employee_onboarding_case_id"("target_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."employee_record_is_workspace_owner"("target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.employee_profiles employee
    join public.workspace_memberships membership
      on membership.workspace_id = employee.workspace_id
     and membership.user_id = employee.user_id
    where employee.id = target_employee_id
      and employee.workspace_id = target_workspace_id
      and employee.user_id is not null
      and exists (select 1 from public.workspace_roles role
                  where role.id = membership.role_id and role.access_class = 'owner')
  );
$$;


ALTER FUNCTION "app_private"."employee_record_is_workspace_owner"("target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."employee_side_impact"("w" "uuid", "emp" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'shifts_opened', (
      select count(*)::integer
      from public.schedule_published_shifts shift
      join public.schedule_location_publications publication
        on publication.id = shift.publication_id and publication.workspace_id = shift.workspace_id
       and publication.location_id = shift.location_id and publication.status = 'current'
      join public.locations location on location.id = shift.location_id and location.workspace_id = shift.workspace_id
      where shift.workspace_id = w and shift.employee_id = emp
        and (shift.scheduled_date + shift.start_time) at time zone location.timezone >= now()),
    'requests_closed', (
      select count(*)::integer from public.shift_exchange_cases c
      where c.workspace_id = w and c.owner_id = emp and c.status = 'open'),
    'applications_closed', (
      select count(*)::integer
      from public.shift_exchange_applications a
      join public.shift_exchange_cases c on c.id = a.case_id and c.workspace_id = a.workspace_id
      where a.workspace_id = w and a.employee_id = emp and a.status in ('invited', 'pending_manager')
        and c.status = 'open' and c.owner_id is distinct from emp),
    'time_off_withdrawn', (
      select count(*)::integer from public.time_off_requests r
      where r.workspace_id = w and r.employee_id = emp and r.status = 'pending'),
    'availability_deleted',
      exists (select 1 from public.employee_weekly_preferences p where p.workspace_id = w and p.employee_id = emp)
      or exists (select 1 from public.manager_weekly_reminders m where m.workspace_id = w and m.employee_id = emp))
$$;


ALTER FUNCTION "app_private"."employee_side_impact"("w" "uuid", "emp" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enqueue_workspace_retention_purge_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  completed_closure_request_id uuid;
begin
  if new.lifecycle_status <> 'deleted' then
    return new;
  end if;

  select request.id into completed_closure_request_id
  from public.workspace_closure_requests request
  where request.workspace_id = new.id
    and request.status = 'completed'
  order by request.completed_at desc, request.created_at desc
  limit 1;

  insert into public.workspace_retention_purge_jobs (
    workspace_id,
    closure_request_id,
    due_at,
    metadata
  )
  values (
    new.id,
    completed_closure_request_id,
    coalesce(new.closed_at, now()),
    jsonb_build_object('source', 'workspace_deleted')
  )
  on conflict (workspace_id) do update
    set closure_request_id = coalesce(public.workspace_retention_purge_jobs.closure_request_id, excluded.closure_request_id),
        due_at = least(public.workspace_retention_purge_jobs.due_at, excluded.due_at),
        updated_at = now()
    where public.workspace_retention_purge_jobs.status = 'pending';

  return new;
end;
$$;


ALTER FUNCTION "app_private"."enqueue_workspace_retention_purge_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."ensure_management_and_owner"("target_workspace_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  management uuid;
begin
  insert into public.departments (workspace_id, name, system_key)
  values (target_workspace_id, 'Management', 'management')
  on conflict (workspace_id, system_key) where system_key is not null do nothing;
  select d.id into management from public.departments d
  where d.workspace_id = target_workspace_id and d.system_key = 'management';

  if not exists (
    select 1 from public.jobs j
    where j.workspace_id = target_workspace_id and j.department_id = management
      and j.system_key is null
  ) then
    insert into public.jobs (workspace_id, name, department_id)
    values (target_workspace_id, 'General Manager', management),
           (target_workspace_id, 'Assistant Manager', management)
    on conflict (workspace_id, lower(name)) where archived_at is null do nothing;
  end if;

  insert into public.jobs (workspace_id, name, department_id, system_key)
  values (target_workspace_id, 'Owner', management, 'owner')
  on conflict (workspace_id, system_key) where system_key is not null do nothing;

  -- The owner holds the Owner job on the management side (design §4.2).
  insert into public.membership_management_jobs (workspace_id, membership_id, job_id)
  select target_workspace_id, m.id, j.id
  from public.workspace_memberships m
  join public.jobs j on j.workspace_id = m.workspace_id and j.system_key = 'owner'
  where m.workspace_id = target_workspace_id and app_private.role_class(m.role_id) = 'owner'
  on conflict (membership_id, job_id) do nothing;
end;
$$;


ALTER FUNCTION "app_private"."ensure_management_and_owner"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."ensure_owner_employee_profile"("target_workspace_id" "uuid", "owner_user_id" "uuid", "owner_first_name" "text" DEFAULT NULL::"text", "owner_middle_name" "text" DEFAULT NULL::"text", "owner_last_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  existing_employee_id uuid;
  next_code bigint;
  owner_email text;
  given_name text := btrim(coalesce(owner_first_name, ''));
  family_name text := btrim(coalesce(owner_last_name, ''));
begin
  if not exists (
    select 1
    from public.workspace_memberships membership
    where membership.workspace_id = target_workspace_id
      and membership.user_id = owner_user_id
      and app_private.role_class(membership.role_id) = 'owner'
      and membership.status = 'active'::public.membership_status
  ) then
    raise exception 'active owner membership required' using errcode = '42501';
  end if;

  select employee.id
  into existing_employee_id
  from public.employee_profiles employee
  where employee.workspace_id = target_workspace_id
    and employee.user_id = owner_user_id
    and employee.archived_at is null
  order by employee.created_at
  limit 1
  for update;

  -- Whatever the employees tab says is what the workspace decided to call this
  -- person. Setup finishing again is not a reason to argue with it, and the
  -- owner hides from the schedule there like anyone else.
  if existing_employee_id is not null then
    return existing_employee_id;
  end if;

  if given_name = '' or family_name = '' then
    raise exception 'a legal name needs a first and a last name' using errcode = '22023';
  end if;

  select lower(auth_user.email) into owner_email
  from auth.users auth_user
  where auth_user.id = owner_user_id;

  select coalesce(max(substring(employee.employee_code from 3)::bigint), 0) + 1
  into next_code
  from public.employee_profiles employee
  where employee.workspace_id = target_workspace_id
    and employee.employee_code ~ '^E-[0-9]+$';

  insert into public.workspace_employee_counters (workspace_id, next_value)
  values (target_workspace_id, next_code + 1)
  on conflict (workspace_id) do update
  set next_value = greatest(
    public.workspace_employee_counters.next_value + 1,
    excluded.next_value
  )
  returning next_value - 1 into next_code;

  insert into public.employee_profiles (
    workspace_id, user_id, employee_code, first_name, middle_name, last_name,
    preferred_name, invitation_email, internal_note, is_remote,
    is_excluded_from_schedule, created_by
  ) values (
    target_workspace_id,
    owner_user_id,
    'E-' || lpad(next_code::text, 4, '0'),
    -- Too long is refused with the legal name's own words right after this.
    left(given_name, 80),
    left(btrim(coalesce(owner_middle_name, '')), 80),
    left(family_name, 80),
    '',
    owner_email,
    -- An internal note is a manager's sentence about a person. Nothing the
    -- system has to say belongs in it.
    '',
    false,
    -- On the schedule like everyone else. Exclude is a choice made in the row.
    false,
    owner_user_id
  )
  returning id into existing_employee_id;

  insert into public.employee_events (
    workspace_id, employee_id, actor_user_id, action, summary
  ) values (
    target_workspace_id,
    existing_employee_id,
    owner_user_id,
    'employee.owner_record_created',
    'Owner employee record created when setup began'
  );

  return existing_employee_id;
end;
$_$;


ALTER FUNCTION "app_private"."ensure_owner_employee_profile"("target_workspace_id" "uuid", "owner_user_id" "uuid", "owner_first_name" "text", "owner_middle_name" "text", "owner_last_name" "text") OWNER TO "postgres";


