    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status in ('active', 'pending_activation') then
    perform app_private.open_account_row(new.user_id, new.workspace_id);
  end if;
  return null;
end;
$$;


