CREATE OR REPLACE FUNCTION "app_private"."exchange_decision_reason"("actor" "uuid", "w" "uuid", "giver" "uuid", "receiver" "uuid", "loc" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when not exists (select 1 from public.employee_profiles e
                     where e.workspace_id = exchange_decision_reason.w
                       and e.id in (exchange_decision_reason.giver, exchange_decision_reason.receiver)
                       and e.user_id = exchange_decision_reason.actor)
      then app_private.authz_reason(actor, w, 'exchange.approve', array[loc])
    when (app_private.actor(actor, w)).class = 'owner' and app_private.decision_tier(w, giver, loc, receiver) = 'self_only'
      then app_private.authz_reason(actor, w, 'exchange.approve', array[loc])
    else 'rank' end;
$$;


ALTER FUNCTION "app_private"."exchange_decision_reason"("actor" "uuid", "w" "uuid", "giver" "uuid", "receiver" "uuid", "loc" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."fair_due"("target_channel" "text", "target_size" integer) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce((array_agg(x.id order by x.required desc, x.turn, x.created_at, x.id))[1:target_size], '{}')
  from (
    select d.id, d.created_at, (t.level = 'required') required,
      row_number() over (partition by n.workspace_id, (t.level = 'required') order by d.created_at, d.id) turn
    from public.notification_deliveries d
    join public.person_notifications n on n.id = d.notification_id
    join public.notification_types t on t.key = n.type_key
    where d.channel = target_channel
      and app_private.delivery_due(d.status, d.next_attempt_at, d.lease_expires_at)
  ) x
  -- No workspace's turn past one batch can make it into one.
  where x.turn <= target_size
$$;


ALTER FUNCTION "app_private"."fair_due"("target_channel" "text", "target_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."finish_workspace_closure"("target_workspace_id" "uuid", "closing_actor" "uuid", "closure_request" "uuid", "closed_at_time" timestamp with time zone, "closure_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  edit_sessions_expired integer := 0;
  revocation jsonb;
begin
  update public.workspaces
  set lifecycle_status = 'deleted',
      closure_scheduled_at = null,
      closure_effective_at = closed_at_time,
      closed_at = closed_at_time,
      closed_by = closing_actor,
      updated_at = now()
  where id = target_workspace_id;

  perform set_config('app.workspace_closure', 'on', true);

  update public.workspace_memberships
  set status = 'suspended',
      updated_at = now()
  where workspace_id = target_workspace_id
    and status <> 'suspended';

  update public.employee_invitations
  set status = 'revoked',
      revoked_at = coalesce(revoked_at, now()),
      updated_at = now()
  where workspace_id = target_workspace_id
    and status = 'pending';

  update public.schedule_edit_sessions
  set status = 'expired',
      closed_at = coalesce(closed_at, now()),
      expires_at = now()
  where workspace_id = target_workspace_id
    and status = 'active';
  get diagnostics edit_sessions_expired = row_count;

  delete from public.user_workspace_preferences
  where active_workspace_id = target_workspace_id;

  revocation := jsonb_build_object(
    'schedule_edit_sessions_expired', edit_sessions_expired
  );

  insert into public.audit_events (
    workspace_id,
    actor_user_id,
    action,
    target_type,
    target_id,
    metadata
  )
  values (
    target_workspace_id,
    closing_actor,
    case closure_mode
      when 'immediate' then 'workspace.closure.completed_immediate'
      else 'workspace.closure.completed_scheduled'
    end,
    'workspace',
    target_workspace_id::text,
    jsonb_build_object('closure_request_id', closure_request, 'runtime_revocation', revocation)
  );

  return revocation;
end;
$$;


ALTER FUNCTION "app_private"."finish_workspace_closure"("target_workspace_id" "uuid", "closing_actor" "uuid", "closure_request" "uuid", "closed_at_time" timestamp with time zone, "closure_mode" "text") OWNER TO "postgres";


