end; $$;


ALTER FUNCTION "app_private"."guard_deleted_location_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_document_definition_edit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
 if old.publication_status='published' and
  (new.title,new.description,new.required_at_onboarding,new.requires_review,new.accepted_formats,new.tracks_expiry,new.expiry_warning_days,new.expiry_schedule_impact,new.lifecycle_settings,new.lifecycle_revision)
  is distinct from
  (old.title,old.description,old.required_at_onboarding,old.requires_review,old.accepted_formats,old.tracks_expiry,old.expiry_warning_days,old.expiry_schedule_impact,old.lifecycle_settings,old.lifecycle_revision)
 then raise exception 'Published documents cannot be edited; unpublish first' using errcode='PT409',hint='document.published_locked'; end if;
 if old.publication_status='draft' and new.lifecycle_revision=old.lifecycle_revision and old.updated_at is distinct from now()
  and (new.title,new.description,new.required_at_onboarding,new.requires_review,new.accepted_formats,new.tracks_expiry,new.expiry_warning_days,new.expiry_schedule_impact,new.lifecycle_settings) is distinct from (old.title,old.description,old.required_at_onboarding,old.requires_review,old.accepted_formats,old.tracks_expiry,old.expiry_warning_days,old.expiry_schedule_impact,old.lifecycle_settings) then new.lifecycle_revision:=old.lifecycle_revision+1; end if;
 return new;
end;
$$;


ALTER FUNCTION "app_private"."guard_document_definition_edit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_document_requirement_publication"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if new.kind='document' and new.source_id is not null and not exists(
  select 1 from public.document_types d where d.id=new.source_id and d.workspace_id=new.workspace_id and d.publication_status='published'
 ) then return null; end if;
 return new;
end;
$$;


ALTER FUNCTION "app_private"."guard_document_requirement_publication"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_job_deletion_state"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if current_user not in ('postgres','service_role') then
    if (tg_op='INSERT' and new.deleted_at is not null) or
      (tg_op='UPDATE' and (old.deleted_at is not null or new.deleted_at is distinct from old.deleted_at)) then
      raise exception 'Deleted jobs cannot be edited or restored. Use the authorized job deletion command.' using errcode='42501';
    end if;
  end if;
  return new;
end; $$;


ALTER FUNCTION "app_private"."guard_job_deletion_state"() OWNER TO "postgres";


