CREATE OR REPLACE FUNCTION "app_private"."home_section_order"("target_order" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with allowed(value, position) as (
    values ('operations', 1), ('pending_requests', 2), ('quick_actions', 3), ('updates', 4),
      ('open_shifts', 5), ('announcements', 6), ('coming_up', 7), ('todos', 8)
  ),
  placed as (
    select input.value, min(input.ordinality) as ordinality
    from unnest(coalesce(target_order, '{}'::text[])) with ordinality input(value, ordinality)
    join allowed on allowed.value = input.value
    group by input.value
  )
  select array_agg(allowed.value order by coalesce(placed.ordinality, 1000 + allowed.position), allowed.position)
  from allowed left join placed on placed.value = allowed.value;
$$;


ALTER FUNCTION "app_private"."home_section_order"("target_order" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."initialize_employee_onboarding"("target_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  employee public.employee_profiles%rowtype;
  membership public.workspace_memberships%rowtype;
  onboarding_case_id uuid;
  should_snapshot_requirements boolean;
begin
  select profile.*
  into employee
  from public.employee_profiles profile
  join public.workspace_memberships candidate
    on candidate.workspace_id = profile.workspace_id
   and candidate.user_id = profile.user_id
  where profile.user_id = target_user_id
    and profile.archived_at is null
    and candidate.status in ('pending_activation', 'active')
    and (target_workspace_id is null or profile.workspace_id = target_workspace_id)
  order by candidate.created_at
  limit 1;

  if employee.id is null then
    raise exception 'employee onboarding is unavailable' using errcode = 'P0002';
  end if;

  select *
  into membership
  from public.workspace_memberships
  where workspace_id = employee.workspace_id
    and user_id = target_user_id
    and status in ('pending_activation', 'active')
  order by created_at
  limit 1;

  insert into public.employee_onboarding_cases (workspace_id, employee_id, membership_id)
  values (employee.workspace_id, employee.id, membership.id)
  on conflict (employee_id) do update
    set membership_id = excluded.membership_id,
        updated_at = public.employee_onboarding_cases.updated_at
  returning id into onboarding_case_id;

  should_snapshot_requirements := not exists (
    select 1
    from public.employee_onboarding_requirements requirement
    where requirement.case_id = onboarding_case_id and requirement.lifecycle_retired_at is null
  );

  if should_snapshot_requirements then
    insert into public.employee_onboarding_requirements (
      workspace_id, case_id, employee_id, kind, title, description,
      required, blocks_activation, requires_review, sort_order, source_snapshot
    ) values
      (employee.workspace_id, onboarding_case_id, employee.id, 'profile', 'Profile and privacy', 'Private contact, identity, and teammate visibility choices.', true, true, false, 10, '{}'::jsonb),
      (employee.workspace_id, onboarding_case_id, employee.id, 'availability', 'Availability', 'Confirmed recurring weekly availability.', false, false, false, 500, '{}'::jsonb)
    on conflict (case_id, kind, source_id) where lifecycle_retired_at is null do nothing;

    insert into public.employee_onboarding_requirements (
      workspace_id, case_id, employee_id, kind, source_id, title, description,
      required, blocks_activation, requires_review, sort_order, source_snapshot
    )
    select employee.workspace_id, onboarding_case_id, employee.id, 'document', document.id,
      document.title, document.description, true,
      true, document.requires_review,
      100 + document.sort_order,
      jsonb_build_object(
        'document_type_id', document.id,
        'accepted_formats', document.accepted_formats,
        'tracks_expiry', document.tracks_expiry,
        'requires_review', document.requires_review
      )
    from public.document_types document
    where document.workspace_id = employee.workspace_id
      and membership.status='pending_activation' and app_private.document_target_matches(employee.workspace_id,employee.id,document.lifecycle_settings->'target')
      and document.archived_at is null
    on conflict (case_id, kind, source_id) where lifecycle_retired_at is null do nothing;

    insert into public.employee_onboarding_requirements (
      workspace_id, case_id, employee_id, kind, source_id, title, description,
      required, blocks_activation, requires_review, sort_order, source_snapshot
    )
    select employee.workspace_id, onboarding_case_id, employee.id, 'acknowledgement', version.id,
      version.title, version.summary, version.required_at_onboarding,
      version.blocks_activation, false, 300 + version.version_number,
      jsonb_build_object(
        'template_version_id', version.id,
        'content_text', version.content_text,
        'content_digest', version.content_digest,
        'intent_statement', version.intent_statement,
        'locale', version.locale,
        'effective_date', version.effective_date,
        'retention_policy_id', version.retention_policy_id
      )
    from public.signature_template_versions version
    join public.signature_templates template on template.id = version.template_id
    where version.workspace_id = employee.workspace_id
      and version.status = 'published'
      and version.execution_class = 'acknowledgement'
      and membership.status='pending_activation' and app_private.document_target_matches(employee.workspace_id,employee.id,app_private.policy_lifecycle_settings(version)->'target')
      and template.archived_at is null
      and not exists (
        select 1
        from public.signature_template_versions newer
        where newer.template_id = version.template_id
          and newer.status = 'published'
          and newer.version_number > version.version_number
      )
    on conflict (case_id, kind, source_id) where lifecycle_retired_at is null do nothing;
  end if;

  if not exists (
    select 1
    from public.onboarding_events event
    where event.case_id = onboarding_case_id
      and event.action in ('onboarding.started', 'onboarding.rehire_started')
  ) then
    insert into public.onboarding_events (
      workspace_id, employee_id, case_id, actor_user_id, action, target_type, target_id
    ) values (
      employee.workspace_id, employee.id, onboarding_case_id, target_user_id,
      'onboarding.started', 'onboarding_case', onboarding_case_id::text
    );
  end if;

  return onboarding_case_id;
end;
$$;


ALTER FUNCTION "app_private"."initialize_employee_onboarding"("target_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."invitation_access_check"("actor" "uuid", "w" "uuid", "next_employee_role" "uuid", "next_management_role" "uuid", "places" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  management_class public.workspace_role;
begin
  if next_employee_role is null and next_management_role is null then
    raise exception 'choose an employee access, a management access or both'
      using errcode = '22023', hint = 'access.role_required';
  end if;
  if next_employee_role is not null and (
    not exists (select 1 from public.workspace_roles r where r.id = next_employee_role and r.workspace_id = w)
    or app_private.role_class(next_employee_role) is distinct from 'employee'
  ) then
    raise exception 'the employee slot holds an employee class role'
      using errcode = '22023', hint = 'membership.employee_slot';
  end if;
  if next_management_role is not null then
    select r.access_class into management_class from public.workspace_roles r
    where r.id = next_management_role and r.workspace_id = w;
    if management_class is null or management_class not in ('manager', 'admin') then
      raise exception 'the management slot holds a manager or admin class role'
        using errcode = '22023', hint = 'membership.management_slot';
    end if;
  end if;
  if (next_employee_role is not null and not app_private.can_invite_with_role(actor, w, next_employee_role))
     or (next_management_role is not null and not app_private.can_invite_with_role(actor, w, next_management_role)) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  if management_class = 'manager' then
    if cardinality(coalesce(places, '{}')) = 0 then
      raise exception 'a manager needs a location to manage'
        using errcode = '22023', hint = 'access.manages_required';
    end if;
    if exists (select 1 from unnest(places) given(id) where not exists (
        select 1 from public.locations l
        where l.id = given.id and l.workspace_id = w and app_private.location_is_live(l))) then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'employee.invite';
    end if;
  elsif cardinality(coalesce(places, '{}')) > 0 then
    raise exception 'only a manager manages chosen locations'
      using errcode = '22023', hint = 'access.manages_only_for_manager';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."invitation_access_check"("actor" "uuid", "w" "uuid", "next_employee_role" "uuid", "next_management_role" "uuid", "places" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."is_employee_onboarding_document_path"("candidate_path" "text", "target_workspace_id" "uuid", "target_employee_id" "uuid", "target_requirement_id" "uuid") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select coalesce(candidate_path, '') ~* (
    '^'
    || target_workspace_id::text
    || '/'
    || target_employee_id::text
    || '/'
    || target_requirement_id::text
    || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(pdf|jpg|png|webp)$'
  );
$_$;


ALTER FUNCTION "app_private"."is_employee_onboarding_document_path"("candidate_path" "text", "target_workspace_id" "uuid", "target_employee_id" "uuid", "target_requirement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."is_workspace_member"("target_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select not app_private.document_actor_blocked((select auth.uid()), target_workspace_id) and exists (
    select 1
    from public.workspace_memberships membership
    where membership.workspace_id = target_workspace_id
      and membership.user_id = (select auth.uid())
      and membership.status = 'active'
      and app_private.workspace_open_to_actor(target_workspace_id, (select auth.uid()))
  );
$$;


ALTER FUNCTION "app_private"."is_workspace_member"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."job_assignment_candidates"("actor" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid") RETURNS TABLE("employee_id" "uuid", "display_name" "text", "employee_code" "text", "location_name" "text", "location_ids" "uuid"[], "display_status" "text", "assigned" boolean, "is_primary" boolean, "revision" integer, "can_manage" boolean, "disabled_reason" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with me as (select app_private.actor(actor, target_workspace_id) as state),
  read_rule as (select r from app_private.authz_actions r where r.key = 'employee.list'),
  save_rule as (select r from app_private.authz_actions r where r.key = 'employee.save'),
  reached as (
    select e.*, app_private.authz_check((select state from me), (select r from save_rule), null, e.id, null) is null as may_save
    from public.employee_profiles e
    where e.workspace_id = target_workspace_id and e.archived_at is null
      and app_private.authz_check((select state from me), (select r from read_rule), null, e.id, null) is null
  )
  select e.id, concat_ws(' ', coalesce(nullif(e.preferred_name, ''), e.first_name), e.last_name), e.employee_code,
    loc.name, coalesce(locs.ids, '{}'::uuid[]),
    case when m.status = 'active' then 'active'
      when oc.status in ('submitted', 'changes_requested') then 'needs_attention'
      when m.status = 'pending_activation' then 'onboarding'
      when invitation.status = 'pending' and invitation.expires_at > now() then 'invited'
      else 'not_invited' end,
    a.id is not null, coalesce(a.is_primary, false), e.revision,
    e.may_save,
    case when e.may_save then null else 'Your role cannot change this employee''s assignments.' end
  from reached e
  left join public.employee_job_assignments a on a.workspace_id = e.workspace_id
    and a.employee_id = e.id and a.job_id = target_job_id and a.ended_at is null
  left join public.employee_location_assignments pl on pl.employee_id = e.id and pl.ended_at is null and pl.is_primary
  left join public.locations loc on loc.id = pl.location_id
  left join lateral (select array_agg(la.location_id) ids from public.employee_location_assignments la
    where la.employee_id = e.id and la.ended_at is null) locs on true
  left join public.workspace_memberships m on m.workspace_id = e.workspace_id and m.user_id = e.user_id
  left join public.employee_onboarding_cases oc on oc.employee_id = e.id and oc.workspace_id = e.workspace_id
  left join lateral (select i.status, i.expires_at from public.employee_invitations i
    where i.employee_id = e.id order by i.created_at desc, i.id limit 1) invitation on true;
$$;


ALTER FUNCTION "app_private"."job_assignment_candidates"("actor" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."jobs_lineup_icons"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  valid boolean;
begin
  if tg_op = 'INSERT' and new.lineup_icons is null then
    new.lineup_icons := app_private.suggest_lineup_art(new.name);
  end if;
  -- A nested list is refused before its keys are read: array_position cannot search one.
  valid := coalesce(array_ndims(new.lineup_icons), 1) = 1;
  if valid then
    valid := app_private.lineup_art_keys_valid(new.lineup_icons) and cardinality(new.lineup_icons) <= 24;
  end if;
  if not valid then
    raise exception 'Choose up to 24 different drawings from the archive'
      using errcode = '22023', hint = 'job.lineup_icons_invalid';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."jobs_lineup_icons"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_job_assignment_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.ended_at is not null then
    -- The owner keeps the Owner job (S1 a); a change of ownership moves the
    -- membership first, so the old owner's assignment ends as anyone's.
    if tg_op = 'UPDATE' and old.ended_at is null
       and exists (select 1 from public.jobs job where job.id = new.job_id and job.system_key = 'owner')
       and app_private.employee_record_is_workspace_owner(new.workspace_id, new.employee_id) then
      raise exception 'The owner keeps the Owner job'
        using errcode = '23514', hint = 'employee.owner_job';
    end if;
    return new;
  end if;
  if exists (select 1 from public.jobs job where job.id = new.job_id and job.system_key = 'owner')
     and not app_private.employee_record_is_workspace_owner(new.workspace_id, new.employee_id) then
    raise exception 'Only the workspace owner works the Owner job'
      using errcode = '42501', hint = 'authz.owner_only';
  end if;
  -- DAVET-ERISIM: every job can be its holder's primary job, the Owner job too (EMP-001 S2 widened).
  return new;
end;
$$;


ALTER FUNCTION "app_private"."keep_job_assignment_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_jobs_out_of_archived_departments"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare department_archived_at timestamptz;
begin
  if new.archived_at is not null or new.department_id is null then return new; end if;
  -- A save that keeps an active job where it is reads nothing: Settings sends
  -- department_id on every save, and locking the department there could
  -- deadlock with that department's archive, which locks this job.
  if tg_op = 'UPDATE' and old.archived_at is null and new.department_id is not distinct from old.department_id then
    return new;
  end if;
  -- Shares the department's row so an archive running at the same moment
  -- either waits for this job or is seen by it.
  select department.archived_at into department_archived_at
  from public.departments department
  where department.id = new.department_id and department.workspace_id = new.workspace_id
  for share;
  if department_archived_at is null then return new; end if;
  if tg_op = 'UPDATE' and old.archived_at is not null then
    new.department_id := null;
    return new;
  end if;
  raise exception 'Restore the department before adding jobs'
    using errcode = '22023', hint = 'department.archived';
end;
$$;


ALTER FUNCTION "app_private"."keep_jobs_out_of_archived_departments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_manager_at_a_location"("w" "uuid", "target_employee" "uuid", "becoming" "public"."workspace_role" DEFAULT NULL::"public"."workspace_role") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  record public.employee_profiles%rowtype;
  holder app_private.actor_state;
begin
  select * into record
  from public.employee_profiles employee
  where employee.id = target_employee and employee.workspace_id = w;
  if record.id is null or record.archived_at is not null or record.is_remote then
    return;
  end if;

  if becoming is null then
    if record.user_id is null then
      return;
    end if;
    holder := app_private.actor(record.user_id, w);
    if holder.class is distinct from 'manager' or holder.status not in ('active', 'pending_activation') then
      return;
    end if;
    if cardinality(holder.manages) = 0 then
      raise exception 'a manager needs a location to manage'
        using errcode = '22023', hint = 'employee.manager_location_required';
    end if;
    return;
  elsif becoming <> 'manager' then
    return;
  end if;

  -- ponytail: somebody becoming a manager (an invitation) is checked on the locations the invitation
  -- gives, Manages' first rows, until the invitation fills Manages itself (ROL-CIFT slice 5).
  if not exists (
    select 1 from public.employee_location_assignments assignment
    where assignment.employee_id = record.id and assignment.ended_at is null
  ) then
    raise exception 'a manager needs a location to manage'
      using errcode = '22023', hint = 'employee.manager_location_required';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."keep_manager_at_a_location"("w" "uuid", "target_employee" "uuid", "becoming" "public"."workspace_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_owner_at_every_location"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.ended_at is null and new.ended_at is not null
     and app_private.employee_record_is_workspace_owner(new.workspace_id, new.employee_id)
     and exists (select 1 from public.locations location
                 where location.id = new.location_id and location.archived_at is null) then
    raise exception 'The owner works at every location'
      using errcode = '23514', hint = 'employee.owner_locations';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."keep_owner_at_every_location"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_session_shift_in_session_locations"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if not exists (
    select 1 from public.schedule_edit_sessions session
    where session.id = new.session_id and new.location_id = any(session.location_ids)
  ) then
    raise exception 'shift location is outside this edit' using errcode = '42501', detail = 'schedule.edit', hint = 'authz.out_of_scope';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."keep_session_shift_in_session_locations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_system_catalog_records"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.system_key is not null and current_user not in ('postgres', 'service_role') then
      raise exception 'Management and Owner are made by setup'
        using errcode = '23514', hint = 'catalog.system_record';
    end if;
    return new;
  end if;
  if new.system_key is distinct from old.system_key then
    raise exception 'A catalog record cannot become or stop being Management or Owner'
      using errcode = '23514', hint = 'catalog.system_record';
  end if;
  if old.system_key is not null
     and (new.archived_at is not null or new.deleted_at is not null) then
    raise exception 'Management and Owner are kept; rename them instead'
      using errcode = '23514', hint = 'catalog.system_record';
  end if;
  -- The Owner job stays under Management (S2 a): elsewhere it could be marked
  -- primary and leave the Management group.
  if tg_table_name = 'jobs' then
    if old.system_key = 'owner' and new.department_id is distinct from old.department_id then
      raise exception 'The Owner job stays under Management'
        using errcode = '23514', hint = 'catalog.system_record';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."keep_system_catalog_records"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."leave_spans"("target_workspace" "uuid", "target_people" "uuid"[], "target_window" "tstzrange") RETURNS TABLE("employee_id" "uuid", "request_id" "uuid", "segment_id" "uuid", "revision" integer, "span" "tstzrange", "pending" boolean, "zone" "text")
    LANGUAGE "sql" STABLE STRICT
    SET "search_path" TO ''
    AS $$
  -- What is approved, or left of it, is `effective`; one request is one range, so its id is also the piece's
  -- (time off rebuild D2; the old tables' branch went in D8).
  select r.employee_id, r.id, r.id, r.revision, piece.span, false, r.time_timezone
  from public.time_off_requests r
  cross join lateral unnest(r.effective) piece(span)
  where r.workspace_id = leave_spans.target_workspace
    and r.employee_id = any (leave_spans.target_people)
    and r.kind = 'leave'
    and not isempty(r.effective)
    and (upper_inf(leave_spans.target_window) or r.starts_at < upper(leave_spans.target_window))
    and piece.span && leave_spans.target_window
  union all
  -- A request waiting for an answer, as the hours asked, until it starts: then it has expired.
  select r.employee_id, r.id, r.id, r.revision, tstzrange(r.starts_at, r.ends_at, '[)'), true, r.time_timezone
  from public.time_off_requests r
  where r.workspace_id = leave_spans.target_workspace
    and r.employee_id = any (leave_spans.target_people)
    and r.kind = 'leave'
    and r.status = 'pending'
    and r.starts_at > now()
    and (upper_inf(leave_spans.target_window) or r.starts_at < upper(leave_spans.target_window))
    and tstzrange(r.starts_at, r.ends_at, '[)') && leave_spans.target_window;
$$;


ALTER FUNCTION "app_private"."leave_spans"("target_workspace" "uuid", "target_people" "uuid"[], "target_window" "tstzrange") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lineup_art_keys_valid"("keys" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select lineup_art_keys_valid.keys is not null
    and array_position(lineup_art_keys_valid.keys, null) is null
    and cardinality(lineup_art_keys_valid.keys) = (
      select count(distinct given.key) from unnest(lineup_art_keys_valid.keys) as given(key)
    )
    and not exists (
      select 1
      from unnest(lineup_art_keys_valid.keys) as given(key)
      where not exists (select 1 from app_private.lineup_art art where art.key = given.key)
    );
$$;


ALTER FUNCTION "app_private"."lineup_art_keys_valid"("keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lineup_day"("target_workspace_id" "uuid", "target_date" "date", "target_places" "uuid"[], "target_shift_type_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  resolved_week_start date := app_private.lineup_week_start(target_workspace_id, target_date);
  result jsonb;
begin
  with places as materialized (
    select l.id, l.name, l.timezone, l.sort_order
    from public.locations l
    where l.workspace_id = target_workspace_id and l.archived_at is null and l.deleted_at is null
      and l.id = any (target_places)
  ), closures as materialized (
    select c.location_id, c.kind, c.title, c.opens, c.closes, c.status
    from public.schedule_closures c
    join places p on p.id = c.location_id
    where c.workspace_id = target_workspace_id and c.closed_date = target_date
  ), shifts as materialized (
    select s.*
    from public.schedule_published_shifts s
    join public.schedule_location_publications publication
      on publication.id = s.publication_id and publication.status = 'current'
     and publication.week_start = resolved_week_start
    join places p on p.id = s.location_id
    where s.workspace_id = target_workspace_id and s.scheduled_date = target_date
  ), headers as materialized (
    select d.*
    from public.daily_lineups d
    join places p on p.id = d.location_id
    where d.workspace_id = target_workspace_id and d.service_date = target_date
  ), rows_all as materialized (
    -- A Schedule shift, with what its lineup changed.
    select s.location_id,
      case when r.id is not null then h.shift_type_id else s.shift_type_id end as group_type,
      r.id as row_id, s.id as shift_id, s.source_shift_id, s.employee_id,
      coalesce(r.job_id, s.job_id) as job_id, s.job_id as schedule_job_id,
      coalesce(r.starts, s.start_time) as starts, coalesce(r.ends, s.end_time) as ends,
      s.start_time as schedule_starts, s.end_time as schedule_ends,
      coalesce(r.label_ids, s.label_ids) as label_ids, r.label_ids is not null as own_labels, s.label_names,
      s.shift_type_id as schedule_type, r.section_id, r.section_name, r.sort_order, r.called_off_at, r.called_off_by,
      false as lineup_only,
      r.replaced_by_row_id
    from shifts s
    -- Only a row of this day's lineups: a shift moved here from another day comes as the Schedule has it.
    left join (public.daily_lineup_rows r join headers h on h.id = r.lineup_id)
      on r.workspace_id = target_workspace_id and r.source_shift_id = s.source_shift_id
     and r.location_id = s.location_id and r.service_date = target_date
    union all
    -- A person added in the lineup only.
    select r.location_id, h.shift_type_id, r.id, null, null, r.employee_id,
      r.job_id, null, r.starts, r.ends, null, null,
      coalesce(r.label_ids, '{}'), true, '{}', null, r.section_id, r.section_name, r.sort_order, r.called_off_at,
      r.called_off_by, true,
      r.replaced_by_row_id
    from public.daily_lineup_rows r
    join headers h on h.id = r.lineup_id
    where r.source_shift_id is null
  ), rows_wanted as materialized (
    select r.* from rows_all r
    where target_shift_type_ids is null or r.group_type = any (target_shift_type_ids)
  ), groups as materialized (
    select distinct r.location_id, r.group_type from rows_wanted r
    union
    select h.location_id, h.shift_type_id from headers h
    where target_shift_type_ids is null or h.shift_type_id = any (target_shift_type_ids)
  ), people as materialized (
    -- Who is on each lineup, and whether they have the app (a membership that can sign in). A called off or
    -- replaced person is not on it (LINEUP-EDIT L1, S-178); the rows still read, for their own groups.
    select r.location_id, r.group_type, count(distinct r.employee_id) as people,
      count(distinct r.employee_id) filter (where exists (
        select 1 from public.employee_profiles e
        join public.workspace_memberships m on m.workspace_id = target_workspace_id and m.user_id = e.user_id
        where e.id = r.employee_id and e.workspace_id = target_workspace_id
          and m.status in ('active', 'pending_activation'))) as with_app
    from rows_wanted r
    where r.employee_id is not null and r.called_off_at is null and r.replaced_by_row_id is null
    group by r.location_id, r.group_type
  ), deals as materialized (
    -- AVATAR-IKON slice 4: each lineup's drawings, dealt once per read; everyone on it counts, called off too, so
    -- calling somebody off moves nobody else's drawing.
    select g.location_id, g.group_type, app_private.lineup_deal(target_workspace_id, g.location_id, target_date,
      g.group_type, (select jsonb_agg(jsonb_build_object('employee_id', r.employee_id, 'job_id', r.job_id))
                     from rows_wanted r
                     where r.location_id = g.location_id and r.group_type is not distinct from g.group_type
                       and r.employee_id is not null)) as art
    from groups g
  ), own_art as materialized (
    -- A drawing the person chose as her avatar here comes first; a photo never reaches a lineup.
    -- Her membership is her account's in this workspace, as has_app finds it.
    select e.id as employee_id, a.art_key
    from public.employee_profiles e
    join public.workspace_memberships m on m.workspace_id = target_workspace_id and m.user_id = e.user_id
    join public.member_avatars a on a.membership_id = m.id and a.workspace_id = target_workspace_id
    where e.workspace_id = target_workspace_id and a.art_key is not null
      and e.id in (select r.employee_id from rows_wanted r)
  )
  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'date', target_date,
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'name', p.name, 'timezone', p.timezone,
        'closed', (select jsonb_build_object('title', c.title, 'status', c.status)
                   from closures c where c.location_id = p.id and c.kind = 'closed' order by c.title limit 1),
        'short_hours', (select jsonb_build_object('title', c.title, 'status', c.status,
                          'opens', to_char(c.opens, 'HH24:MI'), 'closes', to_char(c.closes, 'HH24:MI'))
                        from closures c where c.location_id = p.id and c.kind = 'short' order by c.title limit 1),
        'lineups', case when exists (select 1 from closures c where c.location_id = p.id and c.kind = 'closed')
          then '[]'::jsonb
          else coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', h.id,
              'shift_type_id', g.group_type,
              'shift_type_name', t.name,
              'color', t.color,
              'status', case
                when target_date < (now() at time zone p.timezone)::date then 'past'
                when h.editing then 'editing'
                when coalesce(h.latest_version, 0) > 0 then 'shared'
                else 'draft' end,
              'version', nullif(h.latest_version, 0),
              'shared_at', v.shared_at,
              'ask_ack', v.ask_ack,
              -- Read's count above the line, like the one below it, is who is on the lineup (LINEUP-EDIT L2a).
              'acknowledged', case when v.id is null then null
                else (select count(*) from public.daily_lineup_acknowledgements a where a.version_id = v.id
                        and exists (select 1 from rows_wanted w where w.location_id = g.location_id
                          and w.group_type is not distinct from g.group_type and w.employee_id = a.employee_id
                          and w.called_off_at is null and w.replaced_by_row_id is null)) end,
              'revision', h.revision,
              -- LINEUP-PUBLISH: whether employees see it now, the version they see, who published it, and how
              -- many are on it and have the app ("Read 7/11" is acknowledged / with_app).
              'published', coalesce(h.latest_version, 0) > 0 and not h.editing,
              'version_id', v.id,
              'shared_by', v.shared_by,
              'shared_by_name', (select btrim(coalesce(nullif(e.preferred_name, ''), e.first_name) || ' ' || e.last_name)
                                 from public.employee_profiles e
                                 where e.workspace_id = target_workspace_id and e.user_id = v.shared_by
                                 order by e.archived_at nulls first limit 1),
              'people', coalesce(pc.people, 0),
              'with_app', coalesce(pc.with_app, 0),
              'notes', jsonb_build_object('specials', coalesce(h.specials, ''), 'n86', coalesce(h.n86, ''),
                'shift_notes', coalesce(h.shift_notes, '')),
              'rows', coalesce((
                select jsonb_agg(jsonb_build_object(
                  'id', r.row_id,
                  'shift_id', r.shift_id,
                  'source_shift_id', r.source_shift_id,
                  'employee_id', r.employee_id,
                  -- AVATAR-IKON slice 4: her own drawing, else the lineup's deal; null for nobody.
                  'art_key', case when r.employee_id is not null
                    then coalesce(oa.art_key, dl.art ->> (r.employee_id || ':' || r.job_id)) end,
                  'name', case when e.id is not null
                    then coalesce(nullif(e.preferred_name, ''), e.first_name) || ' ' || e.last_name end,
                  'job_id', r.job_id, 'job_name', j.name, 'job_color', j.color,
                  'department_id', dept.id, 'department_name', dept.name,
                  'start_time', to_char(r.starts, 'HH24:MI'), 'end_time', to_char(r.ends, 'HH24:MI'),
                  'crosses_midnight', r.ends <= r.starts,
                  'schedule_start_time', to_char(r.schedule_starts, 'HH24:MI'),
                  'schedule_end_time', to_char(r.schedule_ends, 'HH24:MI'),
                  'label_ids', to_jsonb(r.label_ids),
                  'label_names', case when r.own_labels
                    then coalesce((select jsonb_agg(sl.name order by array_position(r.label_ids, sl.id))
                                   from public.shift_labels sl
                                   where sl.workspace_id = target_workspace_id and sl.id = any (r.label_ids)), '[]'::jsonb)
                    else to_jsonb(r.label_names) end,
                  -- LINEUP-EDIT L2b: one of the location's sections, or a name typed in this lineup only ("Other…").
                  'section_id', r.section_id, 'section_name', coalesce(sec.name, r.section_name),
                  'sort_order', r.sort_order,
                  'called_off_at', r.called_off_at, 'called_off_by', r.called_off_by,
                  -- LINEUP-EDIT L1: the row of this lineup that took this one's place (S-178 "Replaced").
                  'replaced_by_row_id', r.replaced_by_row_id,
                  'lineup_only', r.lineup_only,
                  -- The Read list (Mert 2026-10-17): whether the person has the app (what with_app counts) and
                  -- when she acknowledged the version staff see; null for anyone else, and for nobody.
                  'has_app', r.employee_id is not null and exists (
                    select 1 from public.workspace_memberships m
                    where m.workspace_id = target_workspace_id and m.user_id = e.user_id
                      and m.status in ('active', 'pending_activation')),
                  'acknowledged_at', case when v.id is not null and r.employee_id is not null then
                    (select a.acknowledged_at from public.daily_lineup_acknowledgements a
                     where a.version_id = v.id and a.employee_id = r.employee_id) end,
                  'changed', to_jsonb(array_remove(array[
                    case when not r.lineup_only and r.starts is distinct from r.schedule_starts then 'start_time' end,
                    case when not r.lineup_only and r.ends is distinct from r.schedule_ends then 'end_time' end,
                    case when not r.lineup_only and r.job_id is distinct from r.schedule_job_id then 'job_id' end,
                    case when not r.lineup_only and r.own_labels then 'labels' end,
                    case when not r.lineup_only and r.group_type is distinct from r.schedule_type then 'shift_type' end
                  ]::text[], null))
                ) order by r.sort_order nulls last, r.starts, e.last_name nulls last, e.first_name, r.shift_id)
                from rows_wanted r
                left join public.employee_profiles e on e.id = r.employee_id and e.workspace_id = target_workspace_id
                -- Names as the Schedule names them: archived ones too, null once deleted.
                left join public.jobs j on j.id = r.job_id and j.workspace_id = target_workspace_id and j.deleted_at is null
                left join public.departments dept on dept.id = j.department_id and dept.workspace_id = target_workspace_id
                  and dept.deleted_at is null
                left join public.location_sections sec on sec.id = r.section_id
                left join own_art oa on oa.employee_id = r.employee_id
                where r.location_id = p.id and r.group_type is not distinct from g.group_type
              ), '[]'::jsonb)
            ) order by t.sort_order nulls last, t.name nulls last)
            from groups g
            left join public.shift_types t on t.id = g.group_type and t.workspace_id = target_workspace_id
              and t.deleted_at is null
            left join headers h on h.location_id = g.location_id and h.shift_type_id is not distinct from g.group_type
            left join public.daily_lineup_versions v on v.lineup_id = h.id and v.version = h.latest_version
            left join people pc on pc.location_id = g.location_id and pc.group_type is not distinct from g.group_type
            left join deals dl on dl.location_id = g.location_id and dl.group_type is not distinct from g.group_type
            where g.location_id = p.id
          ), '[]'::jsonb) end
      ) order by p.sort_order, p.name)
      from places p
    ), '[]'::jsonb),
    'sections', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'location_id', s.location_id, 'name', s.name,
        'sort_order', s.sort_order) order by s.location_id, s.sort_order, s.name)
      from public.location_sections s
      join places p on p.id = s.location_id
      where s.archived_at is null
    ), '[]'::jsonb)
  ) into result;
  return result;
end;
$$;


ALTER FUNCTION "app_private"."lineup_day"("target_workspace_id" "uuid", "target_date" "date", "target_places" "uuid"[], "target_shift_type_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lineup_deal"("target_workspace_id" "uuid", "target_location_id" "uuid", "target_date" "date", "target_shift_type_id" "uuid", "people" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select app_private.deal_lineup_art(
    target_location_id || ':' || target_date || ':' || coalesce(target_shift_type_id::text, 'other'),
    coalesce((
      select jsonb_agg(jsonb_build_object('employee_id', p.employee_id, 'job_id', p.job_id,
        'icons', to_jsonb(coalesce(j.lineup_icons, '{}'::text[]))))
      from (select distinct (x ->> 'employee_id')::uuid as employee_id, (x ->> 'job_id')::uuid as job_id
            from jsonb_array_elements(coalesce(people, '[]'::jsonb)) x
            where x ->> 'employee_id' is not null and x ->> 'job_id' is not null) p
      left join public.jobs j on j.id = p.job_id and j.workspace_id = target_workspace_id and j.deleted_at is null
    ), '[]'::jsonb),
    coalesce((
      select jsonb_object_agg(s.employee_id || ':' || s.job_id, s.art_key)
      from public.daily_lineups d
      join public.daily_lineup_drawings s on s.lineup_id = d.id
      where d.workspace_id = target_workspace_id and d.location_id = target_location_id
        and d.service_date = target_date and d.shift_type_id is not distinct from target_shift_type_id
    ), '{}'::jsonb))
$$;


