CREATE OR REPLACE FUNCTION "app_private"."managed_location_needs_manager"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if (select app_private.role_class(m.role_id) from public.workspace_memberships m
      where m.id = new.membership_id and m.workspace_id = new.workspace_id) is distinct from 'manager' then
    raise exception 'only a manager has Manages; admins and owners manage every location'
      using errcode = '23514', hint = 'membership.manages_needs_manager';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."managed_location_needs_manager"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."management_job_holds"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  slot_class public.workspace_role;
  job public.jobs;
begin
  select r.access_class into slot_class
  from public.workspace_memberships m
  join public.workspace_roles r on r.id = m.role_id and r.workspace_id = m.workspace_id
  where m.id = new.membership_id and m.workspace_id = new.workspace_id;
  if slot_class is null then
    raise exception 'a management job needs a management access'
      using errcode = '23514', hint = 'membership.management_job_needs_access';
  end if;
  select j.* into job from public.jobs j where j.id = new.job_id and j.workspace_id = new.workspace_id;
  if not exists (
    select 1 from public.departments d
    where d.id = job.department_id and d.workspace_id = new.workspace_id and d.system_key = 'management'
  ) then
    raise exception 'a management job is a job of the Management department'
      using errcode = '23514', hint = 'membership.management_job_department';
  end if;
  if job.archived_at is not null or job.deleted_at is not null then
    raise exception 'an archived or deleted job is no management job'
      using errcode = '23514', hint = 'membership.management_job_archived';
  end if;
  if job.system_key = 'owner' and slot_class <> 'owner' then
    raise exception 'the Owner job belongs to the owner'
      using errcode = '23514', hint = 'membership.owner_job';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."management_job_holds"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."management_job_stays_held"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  leaving boolean;
  stranded text[];
begin
  leaving := old.system_key is null
    and old.archived_at is null and old.deleted_at is null
    and exists (select 1 from public.departments d where d.id = old.department_id and d.system_key = 'management')
    and (tg_op = 'DELETE'
         or new.archived_at is not null or new.deleted_at is not null
         or not exists (select 1 from public.departments d where d.id = new.department_id and d.system_key = 'management'));
  if not leaving then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  -- ponytail: the setup reset deletes every job of an unfinished workspace at once; nobody but the owner
  -- holds one there, and the reset starts setup over.
  if tg_op = 'DELETE' then
    return old;
  end if;

  select coalesce(array_agg(app_private.membership_display_name(mj.membership_id)
                           order by app_private.membership_display_name(mj.membership_id)), '{}')
    into stranded
  from public.membership_management_jobs mj
  where mj.job_id = old.id
    and not exists (select 1 from public.membership_management_jobs other
                    where other.membership_id = mj.membership_id and other.job_id <> old.id);

  if cardinality(stranded) > 0 or not exists (
    select 1 from public.jobs j
    join public.departments d on d.id = j.department_id and d.system_key = 'management'
    where j.workspace_id = old.workspace_id and j.id <> old.id
      and j.archived_at is null and j.deleted_at is null and j.system_key is null
  ) then
    raise exception 'Management keeps at least one job, and everybody with management access keeps one'
      using errcode = '22023', hint = 'jobs.last_management_job',
            detail = jsonb_build_object('people', to_jsonb(stranded))::text;
  end if;

  delete from public.membership_management_jobs where job_id = old.id;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."management_job_stays_held"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."management_jobs_for"("w" "uuid", "emp" "uuid", "member" "uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    nullif(array(
      select a.job_id from public.employee_job_assignments a
      join public.jobs j on j.id = a.job_id and j.workspace_id = w
      join public.departments d on d.id = j.department_id and d.system_key = 'management'
      where a.employee_id = emp and a.ended_at is null
        and j.system_key is null and j.archived_at is null and j.deleted_at is null
      order by a.job_id), '{}'),
    nullif(array(
      select held.job_id from public.membership_management_jobs held
      join public.jobs j on j.id = held.job_id and j.workspace_id = w
      where held.membership_id = member
        and j.system_key is null and j.archived_at is null and j.deleted_at is null
      order by held.job_id), '{}'),
    array(
      select j.id from public.jobs j
      join public.departments d on d.id = j.department_id and d.system_key = 'management'
      where j.workspace_id = w and j.system_key is null and j.archived_at is null and j.deleted_at is null
      order by case when lower(j.name) = 'manager' then 1 when lower(j.name) = 'general manager' then 2 else 3 end,
        lower(j.name)
      limit 1))
$$;


ALTER FUNCTION "app_private"."management_jobs_for"("w" "uuid", "emp" "uuid", "member" "uuid") OWNER TO "postgres";


