CREATE OR REPLACE FUNCTION "app_private"."membership_receives"("target_workspace" "uuid", "target_user" "uuid", "to_former_members" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select target_workspace is null or exists (
    select 1 from public.workspace_memberships m
    where m.workspace_id = target_workspace and m.user_id = target_user
      and (m.status in ('active', 'pending_activation') or (to_former_members and m.status in ('suspended', 'removed'))))
$$;


ALTER FUNCTION "app_private"."membership_receives"("target_workspace" "uuid", "target_user" "uuid", "to_former_members" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."membership_slot_rows_follow"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  slot_class public.workspace_role := (select r.access_class from public.workspace_roles r where r.id = new.role_id);
  was_class public.workspace_role := (select r.access_class from public.workspace_roles r where r.id = old.role_id);
begin
  if slot_class is distinct from 'manager' then
    delete from public.membership_managed_locations where membership_id = new.id;
  end if;
  if slot_class is null then
    delete from public.membership_management_jobs where membership_id = new.id;
    return null;
  end if;

  if slot_class = 'owner' and was_class is distinct from 'owner' then
    insert into public.membership_management_jobs (workspace_id, membership_id, job_id)
    select new.workspace_id, new.id, j.id from public.jobs j
    where j.workspace_id = new.workspace_id and j.system_key = 'owner'
    on conflict (membership_id, job_id) do nothing;
  elsif slot_class <> 'owner' then
    delete from public.membership_management_jobs mj
    using public.jobs j
    where mj.membership_id = new.id and j.id = mj.job_id and j.system_key = 'owner';
    -- An owner who hands the workspace over keeps a Management job (KARARLAR S-168).
    if was_class = 'owner' and not exists (
      select 1 from public.membership_management_jobs mj where mj.membership_id = new.id
    ) then
      insert into public.membership_management_jobs (workspace_id, membership_id, job_id)
      select new.workspace_id, new.id, j.id
      from public.jobs j
      join public.departments d on d.id = j.department_id and d.system_key = 'management'
      where j.workspace_id = new.workspace_id and j.archived_at is null and j.deleted_at is null
        and j.system_key is null
      order by (lower(j.name) = 'general manager') desc, lower(j.name)
      limit 1;
    end if;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "app_private"."membership_slot_rows_follow"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notification_resolve"("target_workspace" "uuid", "target_subject_type" "text", "target_subject_id" "uuid", "target_resolution" "text", "target_resolved_by" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  told uuid[];
  person uuid;
begin
  with closed as (
    update public.person_notifications n
    set resolved_at = now(), resolution = target_resolution, resolved_by = target_resolved_by
    from public.notification_types t
    where t.key = n.type_key and t.needs_action
      and n.workspace_id = target_workspace and n.subject_type = target_subject_type and n.subject_id = target_subject_id
      and n.resolved_at is null
    returning n.user_id
  )
  select coalesce(array_agg(c.user_id), '{}'::uuid[]) into told from closed c;
  foreach person in array array(select distinct x from unnest(told) x) loop
    perform realtime.send(jsonb_build_object('workspace_id', target_workspace), 'changed', 'notifications:' || person::text, true);
  end loop;
  return cardinality(told);
end;
$$;


ALTER FUNCTION "app_private"."notification_resolve"("target_workspace" "uuid", "target_subject_type" "text", "target_subject_id" "uuid", "target_resolution" "text", "target_resolved_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notification_route"("target_type" "text", "target_workspace" "uuid", "target_user" "uuid") RETURNS TABLE("channel" "text", "sends" boolean, "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  kind public.notification_types;
  email_on boolean := true;
  push_on boolean := true;
  sms_on boolean := false;
  address text;
  suppressed boolean;
  devices integer;
  sms_consent boolean;
  sms_stopped boolean;
  email_choice boolean;
  push_choice boolean;
  sms_choice boolean;
  email_sends boolean;
  email_why text;
  push_sends boolean;
  push_why text;
  sms_sends boolean;
  sms_why text;
begin
  select * into kind from public.notification_types t where t.key = target_type;
  if kind.key is null then
    raise exception 'unknown notification type' using errcode = '22023', hint = 'notifications.unknown_type';
  end if;

  if target_workspace is not null then
    if exists (select 1 from public.notification_workspace_muted_types m
               where m.workspace_id = target_workspace and m.type_key = kind.key) then
      return query values ('in_app', false, 'owner_off'), ('email', false, 'owner_off'),
                          ('push', false, 'owner_off'), ('sms', false, 'owner_off');
      return;
    end if;
    select s.email_enabled, s.push_enabled, s.sms_enabled into email_on, push_on, sms_on
    from public.notification_workspace_settings s where s.workspace_id = target_workspace;
    email_on := coalesce(email_on, true);
    push_on := coalesce(push_on, true);
    sms_on := coalesce(sms_on, false);
    select bool_or(p.enabled) filter (where p.channel = 'email'),
           bool_or(p.enabled) filter (where p.channel = 'push'),
           bool_or(p.enabled) filter (where p.channel = 'sms')
      into email_choice, push_choice, sms_choice
    from public.notification_preferences p
    where p.workspace_id = target_workspace and p.user_id = target_user and p.topic_key = kind.topic_key;
    select count(*) > 0, coalesce(bool_or(o.phone_e164 is not null), false) into sms_consent, sms_stopped
    from public.notification_sms_consents c
    left join public.notification_sms_opt_outs o on o.phone_e164 = c.phone_e164
    where c.workspace_id = target_workspace and c.user_id = target_user and c.revoked_at is null;
  end if;

  select lower(u.email) into address from auth.users u where u.id = target_user;
  suppressed := exists (select 1 from public.notification_email_suppressions s where s.email = address and s.cleared_at is null);
  select count(*) into devices from public.notification_push_subscriptions d where d.user_id = target_user and d.revoked_at is null;

  -- Email.
  if kind.level <> 'required' and not email_on then
    email_sends := false; email_why := 'owner_off';
  elsif address is null then
    email_sends := false; email_why := 'no_address';
  elsif suppressed then
    email_sends := false; email_why := 'suppressed';
  elsif kind.level = 'required' then
    email_sends := true; email_why := 'required';
  elsif email_choice is not null then
    email_sends := email_choice; email_why := case when email_choice then 'person_on' else 'person_off' end;
  else
    email_sends := kind.default_email; email_why := case when kind.default_email then 'default_on' else 'default_off' end;
  end if;

  -- Push: wanted first, then whether a device takes it.
  if kind.level = 'required' then
    push_sends := true; push_why := 'required';
  elsif not push_on then
    push_sends := false; push_why := 'owner_off';
  elsif push_choice is not null then
    push_sends := push_choice; push_why := case when push_choice then 'person_on' else 'person_off' end;
  else
    push_sends := kind.default_push; push_why := case when kind.default_push then 'default_on' else 'default_off' end;
  end if;
  if push_sends and devices = 0 then
    push_sends := false; push_why := 'no_device';
    if kind.level in ('required', 'important') and not email_sends and email_why = 'default_off' then
      email_sends := true; email_why := 'push_fallback';
    end if;
  end if;

  -- Text message: closed at the gate, then as the other channels, a stopped number closing it last.
  if not app_private.sms_channel_open() then
    sms_sends := false; sms_why := 'not_available';
  elsif kind.level <> 'required' and not sms_on then
    sms_sends := false; sms_why := 'owner_off';
  elsif not coalesce(sms_consent, false) then
    sms_sends := false; sms_why := 'no_consent';
  elsif sms_stopped then
    sms_sends := false; sms_why := 'stopped';
  elsif kind.level = 'required' then
    sms_sends := true; sms_why := 'required';
  elsif sms_choice is not null then
    sms_sends := sms_choice; sms_why := case when sms_choice then 'person_on' else 'person_off' end;
  else
    sms_sends := kind.default_sms; sms_why := case when kind.default_sms then 'default_on' else 'default_off' end;
  end if;

  return query values ('in_app', true, 'always'), ('email', email_sends, email_why),
                      ('push', push_sends, push_why), ('sms', sms_sends, sms_why);
end;
$$;


ALTER FUNCTION "app_private"."notification_route"("target_type" "text", "target_workspace" "uuid", "target_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notify"("target_type" "text", "target_workspace" "uuid", "target_recipients" "uuid"[], "target_event_key" "text", "target_title" "text", "target_body" "text" DEFAULT NULL::"text", "target_url" "text" DEFAULT NULL::"text", "target_actor" "uuid" DEFAULT NULL::"uuid", "target_subject_type" "text" DEFAULT NULL::"text", "target_subject_id" "uuid" DEFAULT NULL::"uuid", "target_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  kind public.notification_types;
begin
  select * into kind from public.notification_types t where t.key = target_type;
  if kind.key is null then
    raise exception 'unknown notification type' using errcode = '22023', hint = 'notifications.unknown_type';
  end if;
  if (kind.scope = 'account') <> (target_workspace is null) then
    raise exception 'an account notice names no workspace; every other names one'
      using errcode = '22023', hint = 'notifications.scope_mismatch';
  end if;
  if nullif(btrim(coalesce(target_event_key, '')), '') is null then
    raise exception 'an event key is required' using errcode = '22023', hint = 'notifications.event_required';
  end if;
  if nullif(btrim(coalesce(target_title, '')), '') is null then
    raise exception 'a title is required' using errcode = '22023', hint = 'notifications.title_required';
  end if;
  if target_url is not null and target_url !~ '^/([^/\\].*)?$' then
    raise exception 'a link stays inside the app' using errcode = '22023', hint = 'notifications.url_outside_app';
  end if;
  return app_private.notify_rows(target_workspace, target_actor, (
    select coalesce(jsonb_agg(jsonb_build_object(
      'type', target_type, 'user_id', r.id, 'event_key', target_event_key, 'title', target_title, 'body', target_body,
      'url', target_url, 'subject_type', target_subject_type, 'subject_id', target_subject_id, 'data', target_data)), '[]'::jsonb)
    from (select distinct x.id from unnest(coalesce(target_recipients, '{}'::uuid[])) x(id) where x.id is not null) r));
end;
$_$;


ALTER FUNCTION "app_private"."notify"("target_type" "text", "target_workspace" "uuid", "target_recipients" "uuid"[], "target_event_key" "text", "target_title" "text", "target_body" "text", "target_url" "text", "target_actor" "uuid", "target_subject_type" "text", "target_subject_id" "uuid", "target_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notify_account_security"("target_user" "uuid", "target_event" "text", "target_audit_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  said jsonb := coalesce((select e.metadata from app_private.security_audit_events e where e.id = target_audit_id), '{}'::jsonb);
  kind text;
  heading text;
  body text;
begin
  case target_event
    when 'account.password_changed' then
      kind := 'account.password_changed';
      heading := 'Your password was changed';
      body := case when (said ->> 'others_signed_out')::boolean
        then 'Your other devices were signed out. If this wasn''t you, reset your password now.'
        else 'If this wasn''t you, reset your password now.' end;
    when 'account.sessions_revoked' then
      -- Signed out as part of a password change: that notice says so.
      if coalesce((said ->> 'with_password_change')::boolean, false) then
        return 0;
      end if;
      kind := 'account.signed_out_elsewhere';
      heading := 'You signed out everywhere else';
      body := 'Your other devices were signed out. If this wasn''t you, change your password now.';
    when 'account.email_change_requested' then
      kind := 'account.sign_in_email_changed';
      heading := 'A sign-in email change was asked for';
      body := 'Confirm it from the link sent to the new address. If this wasn''t you, cancel it on the Security page.';
    when 'account.email_change_cancelled' then
      kind := 'account.sign_in_email_changed';
      heading := 'Your sign-in email change was cancelled';
      body := 'You still sign in with the same email.';
    else
      return 0;
  end case;
  return app_private.notify(
    kind, null, array[target_user], 'security:' || target_audit_id::text, heading, body, '/account/security',
    target_user, 'account', target_user
  );
end;
$$;


ALTER FUNCTION "app_private"."notify_account_security"("target_user" "uuid", "target_event" "text", "target_audit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notify_deciders"("target_workspace" "uuid", "target_action" "text", "target_places" "uuid"[], "target_person" "uuid", "target_wide_action" "text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  wide uuid[] := app_private.notify_holders(target_workspace, target_wide_action, null, target_person);
  up uuid[] := array(select u from unnest(wide) u where (app_private.actor(u, target_workspace)).class = 'admin');
  found uuid[] := '{}';
  here uuid[];
  place uuid;
  short boolean := coalesce(cardinality(target_places), 0) = 0;
begin
  if cardinality(up) = 0 then
    up := wide;
  end if;
  foreach place in array coalesce(target_places, '{}'::uuid[]) loop
    here := array(select u from unnest(app_private.notify_holders(target_workspace, target_action, array[place], target_person)) u
                  where u <> all (wide));
    if cardinality(here) = 0 then
      short := true;
    end if;
    found := found || here;
  end loop;
  if short then
    found := found || up;
  end if;
  return array(select distinct u from unnest(found) u order by u);
end;
$$;


ALTER FUNCTION "app_private"."notify_deciders"("target_workspace" "uuid", "target_action" "text", "target_places" "uuid"[], "target_person" "uuid", "target_wide_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notify_holders"("target_workspace" "uuid", "target_action" "text", "target_places" "uuid"[] DEFAULT NULL::"uuid"[], "target_person" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(m.user_id order by m.user_id), '{}')
  from public.workspace_memberships m
  where m.workspace_id = target_workspace and m.status = 'active'
    and app_private.authz_reason(m.user_id, target_workspace, target_action, target_places, target_person) is null;
$$;


ALTER FUNCTION "app_private"."notify_holders"("target_workspace" "uuid", "target_action" "text", "target_places" "uuid"[], "target_person" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notify_rows"("target_workspace" "uuid", "target_actor" "uuid", "target_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  total integer;
  told uuid[];
  person uuid;
begin
  if jsonb_typeof(coalesce(target_rows, '[]'::jsonb)) <> 'array' then
    raise exception 'notice rows are an array' using errcode = '22023', hint = 'notifications.rows_required';
  end if;
  if exists (select 1 from jsonb_array_elements(coalesce(target_rows, '[]'::jsonb)) x
             where not exists (select 1 from public.notification_types t where t.key = x ->> 'type')) then
    raise exception 'unknown notification type' using errcode = '22023', hint = 'notifications.unknown_type';
  end if;
  if exists (select 1 from jsonb_array_elements(coalesce(target_rows, '[]'::jsonb)) x
             join public.notification_types t on t.key = x ->> 'type'
             where (t.scope = 'account') <> (target_workspace is null)) then
    raise exception 'an account notice names no workspace; every other names one'
      using errcode = '22023', hint = 'notifications.scope_mismatch';
  end if;
  if exists (select 1 from jsonb_array_elements(coalesce(target_rows, '[]'::jsonb)) x
             where nullif(btrim(coalesce(x ->> 'event_key', '')), '') is null) then
    raise exception 'an event key is required' using errcode = '22023', hint = 'notifications.event_required';
  end if;
  if exists (select 1 from jsonb_array_elements(coalesce(target_rows, '[]'::jsonb)) x
             where nullif(btrim(coalesce(x ->> 'title', '')), '') is null) then
    raise exception 'a title is required' using errcode = '22023', hint = 'notifications.title_required';
  end if;
  if exists (select 1 from jsonb_array_elements(coalesce(target_rows, '[]'::jsonb)) x
             where x ->> 'url' is not null and (x ->> 'url' !~ '^/([^/\\].*)?$' or x ->> 'url' ~ '[[:cntrl:]]')) then
    raise exception 'a link stays inside the app' using errcode = '22023', hint = 'notifications.url_outside_app';
  end if;

  with given as (
    select distinct on (x.user_id, x.type, btrim(x.event_key)) x.*
    from jsonb_to_recordset(coalesce(target_rows, '[]'::jsonb)) x(type text, user_id uuid, event_key text, title text,
      body text, url text, subject_type text, subject_id uuid, data jsonb)
    where x.user_id is not null
    order by x.user_id, x.type, btrim(x.event_key)
  ), kept as (
    select g.*, t.retention_days
    from given g
    join public.notification_types t on t.key = g.type
    where (t.notify_actor or g.user_id is distinct from target_actor)
      -- The owner turned this optional type off: nobody gets it, not even in the list.
      and not exists (select 1 from public.notification_workspace_muted_types m
                      where m.workspace_id = target_workspace and m.type_key = t.key)
      and exists (select 1 from auth.users u where u.id = g.user_id)
      and (t.scope = 'account' or app_private.membership_receives(target_workspace, g.user_id, t.to_former_members))
  ), written as (
    insert into public.person_notifications (
      workspace_id, user_id, type_key, event_key, actor_user_id, subject_type, subject_id, title, body, url, data, expires_at
    )
    select target_workspace, k.user_id, k.type, btrim(k.event_key), target_actor, k.subject_type, k.subject_id,
      btrim(k.title), nullif(btrim(coalesce(k.body, '')), ''), k.url, coalesce(k.data, '{}'::jsonb),
      now() + make_interval(days => k.retention_days)
    from kept k
    on conflict (user_id, workspace_id, type_key, event_key) do nothing
    returning id, user_id, type_key
  ), queued as (
    insert into public.notification_deliveries (notification_id, channel, reason)
    select w.id, r.channel, r.reason
    from written w cross join lateral app_private.notification_route(w.type_key, target_workspace, w.user_id) r
    where r.sends and r.channel <> 'in_app'
    returning 1
  )
  select count(*)::integer, coalesce(array_agg(distinct w.user_id), '{}'::uuid[]) into total, told from written w;

  -- A private signal per person that carries no content.
  foreach person in array told loop
    perform realtime.send(jsonb_build_object('workspace_id', target_workspace), 'changed', 'notifications:' || person::text, true);
  end loop;
  return total;
end;
$_$;


ALTER FUNCTION "app_private"."notify_rows"("target_workspace" "uuid", "target_actor" "uuid", "target_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notify_workspace_closing"("target_workspace" "uuid", "target_actor" "uuid", "target_request" "uuid", "target_effective_at" timestamp with time zone, "target_cancelled" boolean) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  place_name text;
  zone text;
begin
  if target_request is null then
    return 0;
  end if;
  select w.name into place_name from public.workspaces w where w.id = target_workspace;
  select l.timezone into zone from public.locations l
  where l.workspace_id = target_workspace order by l.archived_at nulls first, l.created_at, l.id limit 1;
  return app_private.notify(
    'workspace.closure_scheduled',
    target_workspace,
    array(select m.user_id from public.workspace_memberships m where m.workspace_id = target_workspace),
    'closure:' || target_request::text || case when target_cancelled then ':cancelled' else ':scheduled' end,
    place_name || case when target_cancelled then ' is no longer closing' else ' is closing' end,
    case when target_cancelled then 'The owner cancelled the closing. Everything stays as it is.'
         else format('It closes on %s. Save anything you need before then.',
                     to_char(target_effective_at at time zone coalesce(zone, 'UTC'), 'FMMon FMDD, YYYY')) end,
    '/account/workspaces',
    target_actor,
    'workspace_closure',
    target_request,
    jsonb_build_object('closure_request_id', target_request, 'effective_at', target_effective_at,
                       'cancelled', target_cancelled)
  );
end;
$$;


ALTER FUNCTION "app_private"."notify_workspace_closing"("target_workspace" "uuid", "target_actor" "uuid", "target_request" "uuid", "target_effective_at" timestamp with time zone, "target_cancelled" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."employee_onboarding_cases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "membership_id" "uuid" NOT NULL,
    "status" "public"."employee_onboarding_case_status" DEFAULT 'in_progress'::"public"."employee_onboarding_case_status" NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "submitted_at" timestamp with time zone,
    "approved_at" timestamp with time zone,
    "approved_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "final_approval_required" boolean NOT NULL,
    "document_notification_checked_at" timestamp with time zone,
    "document_restriction_told_at" timestamp with time zone,
    CONSTRAINT "employee_onboarding_cases_check" CHECK ((("status" = 'approved'::"public"."employee_onboarding_case_status") = (("approved_at" IS NOT NULL) AND ("approved_by" IS NOT NULL)))),
    CONSTRAINT "employee_onboarding_cases_revision_check" CHECK (("revision" > 0))
);


ALTER TABLE "public"."employee_onboarding_cases" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."onboarding_person"("target_case" "public"."employee_onboarding_cases") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select e.user_id from public.employee_profiles e
  where e.id = target_case.employee_id and e.workspace_id = target_case.workspace_id
$$;


ALTER FUNCTION "app_private"."onboarding_person"("target_case" "public"."employee_onboarding_cases") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."onboarding_reviewers"("target_case" "public"."employee_onboarding_cases") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(distinct who order by who), '{}') from (
    select unnest(app_private.notify_holders(target_case.workspace_id, 'onboarding.legal_name', null, target_case.employee_id)) who
    where exists (select 1 from public.employee_onboarding_requirements r
                  where r.case_id = target_case.id and r.kind = 'profile' and r.requires_review
                    and r.status <> 'completed'::public.employee_onboarding_requirement_status)
    union
    select unnest(app_private.place_deciders(target_case.workspace_id, 'onboarding.review', null, target_case.employee_id))
    where target_case.final_approval_required
  ) reviewers
$$;


ALTER FUNCTION "app_private"."onboarding_reviewers"("target_case" "public"."employee_onboarding_cases") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."onboarding_self_workspace"("u" "uuid", "w" "uuid", "by_case" boolean) RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    w,
    case when by_case then (
      select c.workspace_id from public.employee_onboarding_cases c
      where c.id = app_private.employee_onboarding_case_id(u, null)
    ) end,
    (select profile.workspace_id
     from public.employee_profiles profile
     join public.workspace_memberships candidate
       on candidate.workspace_id = profile.workspace_id and candidate.user_id = profile.user_id
     where profile.user_id = u and profile.archived_at is null
       and candidate.status in ('pending_activation', 'active')
     order by candidate.created_at
     limit 1)
  );
$$;


ALTER FUNCTION "app_private"."onboarding_self_workspace"("u" "uuid", "w" "uuid", "by_case" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."onboarding_tell"("target_case" "public"."employee_onboarding_cases", "event" "text", "actor" "uuid", "reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if event = 'submitted' then
    perform app_private.notification_resolve(target_case.workspace_id, 'onboarding_changes', target_case.id, 'resubmitted', actor);
    perform app_private.notification_resolve(target_case.workspace_id, 'onboarding_case', target_case.id, 'resubmitted', actor);
    return app_private.people_tell('people.onboarding_review_needed', target_case.workspace_id,
      app_private.onboarding_reviewers(target_case),
      'onboarding:' || target_case.id::text || ':submitted:' || target_case.revision::text,
      app_private.people_name(target_case.employee_id) || '''s onboarding is ready for review', null,
      '/app/employees?employeeId=' || target_case.employee_id::text, actor, 'onboarding_case', target_case.id,
      jsonb_build_object('employee_id', target_case.employee_id));
  elsif event = 'changes' then
    perform app_private.notification_resolve(target_case.workspace_id, 'onboarding_case', target_case.id, 'changes_requested', actor);
    return app_private.people_tell('people.onboarding_change_requested', target_case.workspace_id,
      array[app_private.onboarding_person(target_case)],
      'onboarding:' || target_case.id::text || ':changes:' || target_case.revision::text,
      'Your onboarding needs a change', btrim(reason),
      '/onboarding?workspace=' || target_case.workspace_id::text, actor, 'onboarding_changes', target_case.id, '{}'::jsonb);
  elsif event = 'reviewed' then
    if cardinality(app_private.onboarding_reviewers(target_case)) = 0 then
      return app_private.notification_resolve(target_case.workspace_id, 'onboarding_case', target_case.id, 'approved', actor);
    end if;
    return 0;
  elsif event = 'completed' then
    perform app_private.notification_resolve(target_case.workspace_id, 'onboarding_changes', target_case.id, 'approved', actor);
    perform app_private.notification_resolve(target_case.workspace_id, 'onboarding_case', target_case.id, 'approved', actor);
    return app_private.people_tell('people.onboarding_completed', target_case.workspace_id,
      array[app_private.onboarding_person(target_case)],
      'onboarding:' || target_case.id::text || ':completed',
      'Your onboarding is complete',
      'You can use ' || (select w.name from public.workspaces w where w.id = target_case.workspace_id) || ' now.',
      '/app', actor, 'onboarding_case', target_case.id, '{}'::jsonb);
  end if;
  return 0;
exception when others then
  raise warning 'onboarding_tell: % notices for % skipped: % (%)', event, target_case.id, sqlerrm, sqlstate;
  return 0;
end;
$$;


ALTER FUNCTION "app_private"."onboarding_tell"("target_case" "public"."employee_onboarding_cases", "event" "text", "actor" "uuid", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."open_account_row"("target_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  insert into public.user_profiles (user_id, display_name)
  select
    account.id,
    left(coalesce(
      nullif(btrim(account.raw_user_meta_data ->> 'display_name'), ''),
      nullif(btrim(account.raw_user_meta_data ->> 'full_name'), ''),
      (select nullif(btrim(record.first_name || ' ' || record.last_name), '')
       from public.employee_profiles record
       where record.workspace_id = target_workspace_id
         and record.user_id = account.id
         and record.archived_at is null
       order by record.created_at
       limit 1),
      nullif(btrim(split_part(account.email, '@', 1)), ''),
      'Team member'
    ), 100)
  from auth.users account
  where account.id = target_user_id
    and not exists (
      select 1 from public.account_deletion_requests deletion
      where deletion.user_id = account.id and deletion.status = 'completed'
    )
  on conflict (user_id) do nothing;
$$;


ALTER FUNCTION "app_private"."open_account_row"("target_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."open_owner_record_to_everything"("target_workspace_id" "uuid", "owner_employee_id" "uuid", "actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with opened_locations as (
    insert into public.employee_location_assignments (
      workspace_id, employee_id, location_id, created_by
    )
    select target_workspace_id, owner_employee_id, location.id, actor_user_id
    from public.locations location
    where location.workspace_id = target_workspace_id
      and location.archived_at is null
      and not exists (
        select 1
        from public.employee_location_assignments assignment
        where assignment.employee_id = owner_employee_id
          and assignment.location_id = location.id
          and assignment.ended_at is null
      )
    returning 1
  )
  insert into public.employee_job_assignments (
    workspace_id, employee_id, job_id, created_by
  )
  -- Every location, and of the jobs only Owner (BL-218): the owner works any
  -- other job once somebody assigns it, like everyone else.
  select target_workspace_id, owner_employee_id, job.id, actor_user_id
  from public.jobs job
  where job.workspace_id = target_workspace_id
    and job.system_key = 'owner'
    and not exists (
      select 1
      from public.employee_job_assignments assignment
      where assignment.employee_id = owner_employee_id
        and assignment.job_id = job.id
        and assignment.ended_at is null
    );
$$;


ALTER FUNCTION "app_private"."open_owner_record_to_everything"("target_workspace_id" "uuid", "owner_employee_id" "uuid", "actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."open_owner_records_to_new_entity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  owner_record record;
begin
  -- An archived location or job is not somewhere anybody works.
  if new.archived_at is not null then
    return new;
  end if;

  for owner_record in
    select employee.id as employee_id, employee.user_id
    from public.employee_profiles employee
    join public.workspace_memberships membership
      on membership.workspace_id = employee.workspace_id
     and membership.user_id = employee.user_id
    where employee.workspace_id = new.workspace_id
      and employee.archived_at is null
      and app_private.role_class(membership.role_id) = 'owner'
      and membership.status = 'active'::public.membership_status
  loop
    perform app_private.open_owner_record_to_everything(
      new.workspace_id,
      owner_record.employee_id,
      owner_record.user_id
    );
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."open_owner_records_to_new_entity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."owner_document_excused"("requirement" "public"."employee_onboarding_requirements") RETURNS "public"."employee_onboarding_requirements"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  requirement.owner_excused := true;
  requirement.lifecycle_exempt := true;
  requirement.required := false;
  requirement.blocks_activation := false;
  requirement.deadline_at := null;
  requirement.paused_remaining_seconds := null;
  requirement.document_suspended_at := null;
  requirement.lifecycle_closed_at := null;
  requirement.lifecycle_close_reason :=
    'An owner is not asked for the documents they ask of everyone else';
  return requirement;
end;
$$;


ALTER FUNCTION "app_private"."owner_document_excused"("requirement" "public"."employee_onboarding_requirements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."owner_documents_arrive_excused"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.kind in ('document', 'acknowledgement')
    and not coalesce(new.lifecycle_exempt, false)
    and app_private.employee_record_is_workspace_owner(new.workspace_id, new.employee_id)
  then
    new := app_private.owner_document_excused(new);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."owner_documents_arrive_excused"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."workspace_ownership_transfers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "initiated_by" "uuid" NOT NULL,
    "target_user_id" "uuid" NOT NULL,
    "previous_owner_membership_id" "uuid" NOT NULL,
    "target_membership_id" "uuid" NOT NULL,
    "status" "public"."workspace_ownership_transfer_status" DEFAULT 'pending'::"public"."workspace_ownership_transfer_status" NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '7 days'::interval) NOT NULL,
    "accepted_at" timestamp with time zone,
    "rejected_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cancelled_by" "uuid",
    CONSTRAINT "workspace_ownership_transfers_check" CHECK (("initiated_by" <> "target_user_id")),
    CONSTRAINT "workspace_ownership_transfers_check1" CHECK (((("status" = 'pending'::"public"."workspace_ownership_transfer_status") AND ("accepted_at" IS NULL) AND ("rejected_at" IS NULL) AND ("cancelled_at" IS NULL)) OR (("status" = 'accepted'::"public"."workspace_ownership_transfer_status") AND ("accepted_at" IS NOT NULL)) OR (("status" = 'rejected'::"public"."workspace_ownership_transfer_status") AND ("rejected_at" IS NOT NULL)) OR (("status" = 'cancelled'::"public"."workspace_ownership_transfer_status") AND ("cancelled_at" IS NOT NULL))))
);


ALTER TABLE "public"."workspace_ownership_transfers" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."ownership_tell"("transfer" "public"."workspace_ownership_transfers", "event" "text", "actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  place text;
begin
  place := app_private.workspace_name(transfer.workspace_id);
  if event = 'initiated' then
    return app_private.people_tell('people.ownership_transfer_requested', transfer.workspace_id, array[transfer.target_user_id],
      'ownership:' || transfer.id::text || ':initiated',
      app_private.account_name(transfer.initiated_by) || ' asked you to become the owner of ' || place, null,
      '/account/workspaces', actor, 'ownership_transfer', transfer.id, '{}'::jsonb);
  end if;
  perform app_private.notification_resolve(transfer.workspace_id, 'ownership_transfer', transfer.id, event, actor);
  return app_private.people_tell('people.ownership_transfer_answered', transfer.workspace_id,
    array[case when event = 'cancelled' then transfer.target_user_id else transfer.initiated_by end],
    'ownership:' || transfer.id::text || ':' || event,
    case event
      when 'declined' then app_private.account_name(transfer.target_user_id) || ' declined to become the owner of ' || place
      when 'accepted' then app_private.account_name(transfer.target_user_id) || ' is the owner of ' || place || ' now'
      else 'The ownership transfer of ' || place || ' was cancelled' end,
    null, '/account/workspaces', actor, 'ownership_transfer', transfer.id, jsonb_build_object('outcome', event));
exception when others then
  raise warning 'ownership_tell: % notice for % skipped: % (%)', event, transfer.id, sqlerrm, sqlstate;
  return 0;
end;
$$;


ALTER FUNCTION "app_private"."ownership_tell"("transfer" "public"."workspace_ownership_transfers", "event" "text", "actor" "uuid") OWNER TO "postgres";


