CREATE TABLE IF NOT EXISTS "public"."employee_invitations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "email" "text" NOT NULL,
    "token_hash" "text" NOT NULL,
    "status" "public"."employee_invitation_status" DEFAULT 'pending'::"public"."employee_invitation_status" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "sent_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resend_count" integer DEFAULT 0 NOT NULL,
    "accepted_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "declined_at" timestamp with time zone,
    "delivery_status" "text" DEFAULT 'sent'::"text" NOT NULL,
    "delivery_attempted_at" timestamp with time zone,
    "delivery_failed_at" timestamp with time zone,
    "delivery_error" "text",
    "employee_role_id" "uuid",
    "management_role_id" "uuid",
    "managed_location_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "role_id" "uuid" GENERATED ALWAYS AS (COALESCE("management_role_id", "employee_role_id")) STORED,
    CONSTRAINT "employee_invitations_delivery_error_check" CHECK ((("delivery_error" IS NULL) OR ("char_length"("delivery_error") <= 500))),
    CONSTRAINT "employee_invitations_delivery_status_check" CHECK (("delivery_status" = ANY (ARRAY['pending'::"text", 'sent'::"text", 'failed'::"text"]))),
    CONSTRAINT "employee_invitations_email_check" CHECK (("email" = "lower"("btrim"("email")))),
    CONSTRAINT "employee_invitations_holds_an_access" CHECK ((("employee_role_id" IS NOT NULL) OR ("management_role_id" IS NOT NULL))),
    CONSTRAINT "employee_invitations_resend_count_check" CHECK (("resend_count" >= 0)),
    CONSTRAINT "employee_invitations_token_hash_check" CHECK (("token_hash" ~ '^[0-9a-f]{64}$'::"text"))
);


ALTER TABLE "public"."employee_invitations" OWNER TO "postgres";


COMMENT ON COLUMN "public"."employee_invitations"."managed_location_ids" IS 'Where an invited manager will manage (Manages). Empty for every other access.';



COMMENT ON COLUMN "public"."employee_invitations"."role_id" IS 'The higher of the two accesses (the management role when there is one): what rank checks read. Computed.';



CREATE OR REPLACE FUNCTION "app_private"."people_tell_invitation"("invitation" "public"."employee_invitations", "kind" "text", "actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  name text;
  theirs boolean;
begin
  name := app_private.people_name(invitation.employee_id);
  theirs := app_private.authz_reason(invitation.created_by, invitation.workspace_id, 'employee.invite', null,
    invitation.employee_id) is null;
  return app_private.people_tell('people.' || kind, invitation.workspace_id,
    case when theirs then array[invitation.created_by]
         else app_private.notify_holders(invitation.workspace_id, 'employee.invite', null, invitation.employee_id) end,
    'invite:' || invitation.id::text || ':' || kind,
    case kind
      when 'joined' then name || ' accepted ' || case when theirs then 'your' else 'an' end || ' invitation'
      when 'invitation_declined' then name || ' declined ' || case when theirs then 'your' else 'an' end || ' invitation'
      else case when theirs then 'Your' else 'An' end || ' invitation to ' || name || ' was cancelled' end,
    case kind
      when 'joined' then 'They are finishing their onboarding.'
      when 'invitation_cancelled' then 'They can no longer accept it.' end,
    '/app/employees?employeeId=' || invitation.employee_id::text, actor, 'employee', invitation.employee_id,
    jsonb_build_object('invitation_id', invitation.id, 'employee_id', invitation.employee_id));
exception when others then
  raise warning 'people_tell_invitation: % notice for % skipped: % (%)', kind, invitation.id, sqlerrm, sqlstate;
  return 0;
end;
$$;


ALTER FUNCTION "app_private"."people_tell_invitation"("invitation" "public"."employee_invitations", "kind" "text", "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."phone_used_in_workspace"("target_workspace_id" "uuid", "target_phone" "text", "except_employee_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select target_phone is not null and exists (
    select 1
    from public.employee_private_profiles private_record
    join public.employee_profiles record
      on record.id = private_record.employee_id
     and record.workspace_id = private_record.workspace_id
    where private_record.workspace_id = target_workspace_id
      and private_record.phone = target_phone
      and record.id is distinct from except_employee_id
      and record.user_id is distinct from (
        select own.user_id from public.employee_profiles own where own.id = except_employee_id)
  );
$$;


ALTER FUNCTION "app_private"."phone_used_in_workspace"("target_workspace_id" "uuid", "target_phone" "text", "except_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."place_deciders"("target_workspace" "uuid", "target_action" "text", "target_place" "uuid", "target_person" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with holders as (
    select unnest(app_private.notify_holders(target_workspace, target_action,
      case when target_place is null then null else array[target_place] end, target_person)) who
  ), managers as (
    -- The class as the core holds it (actor_state), not read from roles here.
    select h.who from holders h where (app_private.actor(h.who, target_workspace)).class = 'manager'
  )
  select coalesce(array_agg(x.who order by x.who), '{}') from (
    select who from managers
    union all
    select who from holders where not exists (select 1 from managers)
  ) x
$$;


ALTER FUNCTION "app_private"."place_deciders"("target_workspace" "uuid", "target_action" "text", "target_place" "uuid", "target_person" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."signature_template_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "template_id" "uuid" NOT NULL,
    "version_number" integer NOT NULL,
    "title" "text" NOT NULL,
    "summary" "text" DEFAULT ''::"text" NOT NULL,
    "execution_class" "public"."signature_execution_class" DEFAULT 'acknowledgement'::"public"."signature_execution_class" NOT NULL,
    "content_text" "text" NOT NULL,
    "content_digest" "text" NOT NULL,
    "intent_statement" "text" NOT NULL,
    "locale" "text" DEFAULT 'en-US'::"text" NOT NULL,
    "effective_date" "date" NOT NULL,
    "required_at_onboarding" boolean DEFAULT true NOT NULL,
    "blocks_activation" boolean DEFAULT true NOT NULL,
    "retention_policy_id" "uuid" NOT NULL,
    "status" "public"."signature_version_status" DEFAULT 'draft'::"public"."signature_version_status" NOT NULL,
    "published_by" "uuid",
    "published_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lifecycle_settings" "jsonb",
    "lifecycle_revision" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "signature_template_versions_check" CHECK (((("status" = 'draft'::"public"."signature_version_status") AND ("published_by" IS NULL) AND ("published_at" IS NULL)) OR (("status" = 'published'::"public"."signature_version_status") AND ("published_by" IS NOT NULL) AND ("published_at" IS NOT NULL)))),
    CONSTRAINT "signature_template_versions_check1" CHECK (((NOT "blocks_activation") OR "required_at_onboarding")),
    CONSTRAINT "signature_template_versions_content_digest_check" CHECK (("content_digest" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "signature_template_versions_content_text_check" CHECK ((("char_length"("content_text") >= 1) AND ("char_length"("content_text") <= 50000))),
    CONSTRAINT "signature_template_versions_intent_statement_check" CHECK ((("char_length"("btrim"("intent_statement")) >= 1) AND ("char_length"("btrim"("intent_statement")) <= 500))),
    CONSTRAINT "signature_template_versions_locale_check" CHECK (("locale" ~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$'::"text")),
    CONSTRAINT "signature_template_versions_summary_check" CHECK (("char_length"("summary") <= 240)),
    CONSTRAINT "signature_template_versions_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 80))),
    CONSTRAINT "signature_template_versions_version_number_check" CHECK (("version_number" > 0))
);


