    "workspace_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "requested_name" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "decided_by" "uuid",
    "decided_at" timestamp with time zone,
    CONSTRAINT "employee_preferred_name_requests_requested_name_check" CHECK ((("char_length"("btrim"("requested_name")) >= 1) AND ("char_length"("btrim"("requested_name")) <= 80))),
    CONSTRAINT "employee_preferred_name_requests_requested_name_us_letters" CHECK ((NORMALIZE("requested_name", NFC) !~ '[şŞğĞıİ]'::"text")),
    CONSTRAINT "employee_preferred_name_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"])))
);


ALTER TABLE "public"."employee_preferred_name_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."employee_preferred_name_requests" IS 'A preferred name waiting for an answer. A refused one is kept here and nowhere else: the person is not told, and the name never appears.';



CREATE OR REPLACE FUNCTION "app_private"."preferred_name_tell_answered"("request" "public"."employee_preferred_name_requests", "approve" boolean, "actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.notification_resolve(request.workspace_id, 'preferred_name_request', request.id,
    case when approve then 'approved' else 'declined' end, actor);
  -- S-131: a refusal is silent; only an approval is told.
  if not approve then
    return 0;
  end if;
  return app_private.people_tell('people.preferred_name_decided', request.workspace_id,
    array(select e.user_id from public.employee_profiles e where e.id = request.employee_id and e.workspace_id = request.workspace_id),
    'preferred_name:' || request.id::text || ':decided',
    'You''ll be called ' || request.requested_name, null,
    '/account/profile', actor, 'preferred_name_request', request.id,
    jsonb_build_object('outcome', 'approved'));
exception when others then
  raise warning 'preferred_name_tell_answered: notices for % skipped: % (%)', request.id, sqlerrm, sqlstate;
  return 0;
end;
$$;


ALTER FUNCTION "app_private"."preferred_name_tell_answered"("request" "public"."employee_preferred_name_requests", "approve" boolean, "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."preferred_name_tell_asked"("target_workspace" "uuid", "target_employee" "uuid", "replaced" "uuid"[], "asked" "uuid", "wanted" "text", "deciders" "uuid"[], "actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.notification_resolve(target_workspace, 'preferred_name_request', r, 'closed', actor)
  from unnest(coalesce(replaced, '{}')) r;
  if asked is null then
    return 0;
  end if;
  return app_private.people_tell('people.preferred_name_requested', target_workspace, deciders,
    'preferred_name:' || asked::text,
    app_private.people_name(target_employee) || ' asked to be called ' || wanted, null,
    '/app/employees?employeeId=' || target_employee::text, actor, 'preferred_name_request', asked,
    jsonb_build_object('employee_id', target_employee, 'requested_name', wanted));
exception when others then
  raise warning 'preferred_name_tell_asked: notices for % skipped: % (%)', target_employee, sqlerrm, sqlstate;
  return 0;
end;
$$;


ALTER FUNCTION "app_private"."preferred_name_tell_asked"("target_workspace" "uuid", "target_employee" "uuid", "replaced" "uuid"[], "asked" "uuid", "wanted" "text", "deciders" "uuid"[], "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."preview_lifecycle_definition"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "target_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d app_private.lifecycle_definition%rowtype; rows jsonb; token text;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 select * into d from app_private.lifecycle_definition where id=target_document_type_id and workspace_id=target_workspace_id and kind=target_kind;
 if d.id is null then raise exception 'document type not found' using errcode='P0002'; end if;
 with candidates as (
  select e.id,e.first_name,e.last_name,e.revision as employee_revision,r,
   d.archived_at is null and (target_kind<>'document' or (e.archived_at is null and m.status in ('active','pending_activation'))) and app_private.document_target_matches(e.workspace_id,e.id,d.lifecycle_settings->'target') as matches,
   m.status as membership_status
  from public.employee_profiles e join public.workspace_memberships m on m.workspace_id=e.workspace_id and m.user_id=e.user_id
  left join public.employee_onboarding_requirements r on r.workspace_id=e.workspace_id and r.employee_id=e.id and r.source_id=d.id and r.kind::text=target_kind and r.lifecycle_retired_at is null
  where e.workspace_id=target_workspace_id and ((e.archived_at is null and m.status in ('active','pending_activation')) or (target_kind='document' and (r).publication_paused_at is not null))
 ), effects as (
  select *,case when (r).lifecycle_exempt then 'exempt'
   when target_kind='document' and ((r).lifecycle_retired_at is not null or (r).lifecycle_assignment_disabled or (r).lifecycle_closed_at is not null or (r).status='superseded') then 'unchanged' when target_kind='document' and matches and (r).publication_paused_at is not null then 'update' when not matches and (r).id is not null and (r).lifecycle_closed_at is null then 'remove'
   when matches and (r).id is null and (membership_status='pending_activation' or d.lifecycle_settings->>'assignment_scope'='all_active') then 'assign'
   when matches and ((r).lifecycle_closed_at is not null or (r).status='superseded') then 'reopen'
   when matches and (r).id is not null and ((r).lifecycle_settings is distinct from d.lifecycle_settings or (r).source_snapshot is distinct from d.snapshot
    or (r).title is distinct from d.title or (r).description is distinct from d.description) then 'update'
   else 'unchanged' end as action
  from candidates
 ) select coalesce(jsonb_agg(jsonb_build_object('employee_id',id,'employee_name',concat_ws(' ',first_name,last_name),'employee_revision',employee_revision,
   'requirement_id',(r).id,'revision',(r).lifecycle_revision,'action',action,
   'deadline_action',case when action in ('remove','exempt') or d.lifecycle_settings->>'mode'='optional' then 'clear'
    when target_kind='document' and (r).publication_paused_at is not null and action='update' then 'restart' when action in ('assign','reopen') then 'restart'
    when action='update' and ((r).lifecycle_settings->>'mode',(r).lifecycle_settings->>'period_days',(r).lifecycle_settings->>'suspend_on_overdue')
      is distinct from (d.lifecycle_settings->>'mode',d.lifecycle_settings->>'period_days',d.lifecycle_settings->>'suspend_on_overdue') then 'restart'
    else 'preserve' end) order by id),'[]') into rows from effects;
 token:=encode(extensions.digest(convert_to(jsonb_build_object('actor',actor_user_id,'definition',to_jsonb(d),'employees',rows)::text,'UTF8'),'sha256'),'hex');
 return jsonb_build_object('revision',d.lifecycle_revision,'preview_token',token,'employees',rows);
end;
$$;


ALTER FUNCTION "app_private"."preview_lifecycle_definition"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "target_kind" "text") OWNER TO "postgres";


