CREATE OR REPLACE FUNCTION "app_private"."record_schedule_edit_undo_step"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  edit uuid := coalesce(new.session_id, old.session_id);
  call_at timestamptz := statement_timestamp();
  call_xact xid8 := pg_current_xact_id();
  this_step bigint;
begin
  -- A closed edit keeps no history, nor does one being deleted.
  if not exists (select 1 from public.schedule_edit_sessions session where session.id = edit and session.status = 'active') then
    return null;
  end if;
  -- The shifts an edit is opened or widened with are not a step of it.
  if current_setting('app.schedule_edit_widening', true) = 'on' then
    return null;
  end if;
  select step.step_no into this_step
  from app_private.schedule_edit_undo_steps step
  where step.session_id = edit and step.step_at = call_at and step.step_xact = call_xact
  limit 1;
  -- A new step: only the 24 before it are kept, and it is numbered after them.
  if this_step is null then
    delete from app_private.schedule_edit_undo_steps step
    where step.session_id = edit and step.step_no <= (
      select kept.step_no
      from (select distinct older.step_no from app_private.schedule_edit_undo_steps older
            where older.session_id = edit) kept
      order by kept.step_no desc offset 24 limit 1);
    this_step := nextval('app_private.schedule_edit_undo_step_no');
  end if;
  insert into app_private.schedule_edit_undo_steps (workspace_id, session_id, step_at, step_xact, step_no, shift_id, before)
  values (coalesce(new.workspace_id, old.workspace_id), edit, call_at, call_xact, this_step, coalesce(new.id, old.id),
    case when tg_op = 'INSERT' then null else to_jsonb(old) end)
  -- The first change in a step is how the row was before it.
  on conflict (session_id, shift_id, step_at, step_xact) do nothing;
  return null;
end;
$$;


ALTER FUNCTION "app_private"."record_schedule_edit_undo_step"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."record_security_audit_event_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "event_type" "text", "surface" "text", "resource_type" "text" DEFAULT NULL::"text", "raw_resource_id" "text" DEFAULT NULL::"text", "metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  event_id uuid;
begin
  if btrim(coalesce(event_type, '')) = '' then
    raise exception 'security audit event type required' using errcode = '23514';
  end if;
  if btrim(coalesce(surface, '')) = '' then
    raise exception 'security audit surface required' using errcode = '23514';
  end if;
  if metadata is null or jsonb_typeof(metadata) <> 'object' then
    raise exception 'security audit metadata object required' using errcode = '23514';
  end if;

  insert into app_private.security_audit_events (
    actor_user_id,
    workspace_id,
    event_type,
    surface,
    resource_type,
    resource_id_hash,
    metadata
  ) values (
    actor_user_id,
    target_workspace_id,
    btrim(event_type),
    btrim(surface),
    nullif(btrim(coalesce(resource_type, '')), ''),
    case
      when raw_resource_id is null or btrim(raw_resource_id) = '' then null
      else encode(extensions.digest(btrim(raw_resource_id), 'sha256'), 'hex')
    end,
    metadata
  )
  returning id into event_id;

  return event_id;
end;
$$;


ALTER FUNCTION "app_private"."record_security_audit_event_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "event_type" "text", "surface" "text", "resource_type" "text", "raw_resource_id" "text", "metadata" "jsonb") OWNER TO "postgres";


