CREATE OR REPLACE FUNCTION "app_private"."schedule_publication_changes_since_start"("preview" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case when jsonb_typeof(preview -> 'locations') is distinct from 'array' then preview
  else jsonb_set(preview, '{locations}', coalesce((
    select jsonb_agg(item || jsonb_build_object('changed_since_start', (
      select case
        when current_publication.id is not null then jsonb_build_object(
          'kind', 'published',
          'by_name', coalesce(publisher.display_name, 'Another manager'),
          'at', current_publication.published_at)
        else jsonb_build_object(
          'kind', 'unpublished',
          'by_name', coalesce(unpublisher.display_name, 'Another manager'),
          'at', latest.unpublished_at)
      end
      from public.schedule_drafts draft
      left join public.schedule_location_publications current_publication
        on current_publication.id = nullif(item ->> 'active_publication_id', '')::uuid
      left join public.user_profiles publisher on publisher.user_id = current_publication.published_by
      left join lateral (
        select publication.* from public.schedule_location_publications publication
        where publication.location_id = (item ->> 'location_id')::uuid
          and publication.week_start = draft.week_start
        order by publication.version_number desc
        limit 1
      ) latest on true
      left join public.user_profiles unpublisher on unpublisher.user_id = latest.unpublished_by
      where draft.id = (preview ->> 'draft_id')::uuid
        and current_publication.id is distinct from (
          select publication.id from public.schedule_location_publications publication
          where publication.id = any(draft.base_publication_ids)
            and publication.location_id = (item ->> 'location_id')::uuid
        )
    )) order by position)
    from jsonb_array_elements(preview -> 'locations') with ordinality entry(item, position)
  ), '[]'::jsonb))
  -- The open shifts this publish asks about (Mert, 2026-10-20); the draft revision guards them.
  || jsonb_build_object('open_shifts', app_private.schedule_publication_open_shifts(preview)) end;
$$;


ALTER FUNCTION "app_private"."schedule_publication_changes_since_start"("preview" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_publication_open_shifts"("preview" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', d.id, 'location_id', d.location_id, 'location_name', l.name, 'job_id', d.job_id,
      'job_name', coalesce(j.name, 'Unassigned position'), 'scheduled_date', d.scheduled_date,
      'start_time', to_char(d.start_time, 'HH24:MI'), 'end_time', to_char(d.end_time, 'HH24:MI'))
    order by d.scheduled_date, d.start_time, l.name, d.id), '[]'::jsonb)
  from public.schedule_draft_shifts d
  join public.locations l on l.id = d.location_id
  left join public.jobs j on j.id = d.job_id
  where d.draft_id = (preview ->> 'draft_id')::uuid
    and d.employee_id is null
    and d.location_id in (select (x ->> 'location_id')::uuid from jsonb_array_elements(coalesce(preview -> 'locations', '[]'::jsonb)) x)
    and public.schedule_shift_in_department_scope_service(d.job_id,
      case when jsonb_typeof(preview -> 'department_ids') = 'array'
        then array(select jsonb_array_elements_text(preview -> 'department_ids'))::uuid[] end,
      coalesce((preview ->> 'include_no_department')::boolean, true))
    and lower(app_private.shift_time_range(d.scheduled_date, d.start_time, d.end_time, coalesce(d.time_timezone, l.timezone)))
      - interval '4 hours' > now()
    and not exists (
      select 1 from public.schedule_published_shifts p
      join public.schedule_location_publications pub on pub.id = p.publication_id and pub.status = 'current'
      where p.workspace_id = d.workspace_id and p.source_shift_id = d.id and p.employee_id is null
        and p.job_id is not distinct from d.job_id and p.shift_type_id is not distinct from d.shift_type_id
        and p.scheduled_date = d.scheduled_date and p.start_time is not distinct from d.start_time
        and p.end_time is not distinct from d.end_time and p.time_basis is not distinct from d.time_basis
        and p.time_snapshot is not distinct from d.time_snapshot and p.time_timezone is not distinct from d.time_timezone
        and p.note is not distinct from d.note)
$$;


ALTER FUNCTION "app_private"."schedule_publication_open_shifts"("preview" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_referenced_catalog"("target_workspace_id" "uuid", "job_ids" "uuid"[], "shift_type_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'referenced_jobs', coalesce((
      select jsonb_agg(jsonb_build_object('id', job.id, 'name', job.name) order by lower(job.name), job.id)
      from public.jobs job
      where job.workspace_id = target_workspace_id and job.id = any (job_ids)
        and job.archived_at is not null and job.deleted_at is null
    ), '[]'::jsonb),
    'referenced_shift_types', coalesce((
      select jsonb_agg(jsonb_build_object('id', shift_type.id, 'name', shift_type.name)
        order by lower(shift_type.name), shift_type.id)
      from public.shift_types shift_type
      where shift_type.workspace_id = target_workspace_id and shift_type.id = any (shift_type_ids)
        and shift_type.archived_at is not null and shift_type.deleted_at is null
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "app_private"."schedule_referenced_catalog"("target_workspace_id" "uuid", "job_ids" "uuid"[], "shift_type_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_tell_closed_day"("target_workspace" "uuid", "target_actor" "uuid", "item" "public"."announcements", "target_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  fmt text := app_private.announcement_time_format(target_workspace);
  notices jsonb;
begin
  with r as (
    select (x ->> 'employee_id')::uuid emp, x ->> 'outcome' outcome, (x ->> 'day')::date d, x ->> 'kind' kind,
      nullif(x ->> 'from', '')::time st, nullif(x ->> 'until', '')::time en
    from jsonb_array_elements(target_rows) x where x ->> 'employee_id' is not null
  ), person as (
    select e.user_id, count(*) filter (where r.outcome <> 'edited')::integer taken, count(*)::integer shifts,
      min(r.d) first_day, max(r.d) last_day, bool_and(r.kind = 'closed') closed, min(r.st) st, min(r.en) en
    from r join public.employee_profiles e on e.id = r.emp and e.workspace_id = target_workspace
    where e.user_id is not null
    group by e.user_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'type', case when p.taken > 0 then 'schedule.closed_day_removed_shift' else 'schedule.shift_changed' end,
    'user_id', p.user_id, 'event_key', 'closed_day:' || item.id::text || ':' || item.revision::text,
    'title', case
      when p.taken > 0 and p.first_day = p.last_day then to_char(p.first_day, 'FMDy, FMMon FMDD')
        || case when p.closed then ' is closed.' else ' has short hours.' end
        || case when p.shifts = 1 then ' Your shift was removed.' else ' Your shifts were removed.' end
      when p.taken > 0 then item.title || ': your shifts were removed'
      when p.shifts = 1 then 'Your ' || to_char(p.first_day, 'FMDy, FMMon FMDD') || ' shift now runs '
        || app_private.announcement_hours_text(p.st, p.en, fmt)
      else item.title || ': your shift hours changed' end,
    'body', item.title,
    'url', '/app/employee-hub/schedule?view=day&date=' || p.first_day::text,
    'subject_type', 'announcement', 'subject_id', item.id,
    'data', jsonb_build_object('announcement_id', item.id, 'removed', p.taken, 'shifts', p.shifts))), '[]'::jsonb)
  into notices from person p;
  return app_private.notify_rows(target_workspace, target_actor, notices);
end;
$$;


ALTER FUNCTION "app_private"."schedule_tell_closed_day"("target_workspace" "uuid", "target_actor" "uuid", "item" "public"."announcements", "target_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_tell_published"("target_workspace" "uuid", "target_actor" "uuid", "target_event" "uuid", "target_week" "date", "target_pairs" "jsonb", "target_told" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  fmt text := app_private.announcement_time_format(target_workspace);
  week text := app_private.schedule_week_text(target_week);
  link text := '/app/employee-hub/schedule?view=day&date=' || target_week::text;
  notices jsonb;
begin
  with pair as (
    select nullif(p ->> 'previous', '')::uuid prev, (p ->> 'current')::uuid cur from jsonb_array_elements(target_pairs) p
  ), old_row as (
    select s.*, pair.cur from public.schedule_published_shifts s join pair on s.publication_id = pair.prev
  ), new_row as (
    select s.*, pair.prev from public.schedule_published_shifts s join pair on s.publication_id = pair.cur
  ), joined as (
    select o.id old_id, n.id new_id, n.prev is null first_time,
      o.employee_id old_emp, o.scheduled_date old_day, o.start_time old_start, o.end_time old_end,
      n.employee_id new_emp, n.scheduled_date new_day, n.start_time new_start, n.end_time new_end,
      (o.id is not null and n.id is not null and (
        o.employee_id is distinct from n.employee_id or o.job_id is distinct from n.job_id
        or o.shift_type_id is distinct from n.shift_type_id or o.scheduled_date is distinct from n.scheduled_date
        or o.start_time is distinct from n.start_time or o.end_time is distinct from n.end_time
        or o.time_basis is distinct from n.time_basis or o.time_snapshot is distinct from n.time_snapshot
        or o.time_timezone is distinct from n.time_timezone or o.note is distinct from n.note)) changed
    from old_row o full join new_row n on n.publication_id = o.cur and n.source_shift_id = o.source_shift_id
  ), change as (
    select new_emp emp, case when first_time then 'first' else 'added' end kind, new_day d, new_start st, new_end en
    from joined where old_id is null
    union all select old_emp, 'removed', old_day, old_start, old_end from joined where new_id is null
    union all select new_emp, 'changed', new_day, new_start, new_end from joined where changed and old_emp is not distinct from new_emp
    union all select old_emp, 'removed', old_day, old_start, old_end from joined where changed and old_emp is distinct from new_emp
    union all select new_emp, 'added', new_day, new_start, new_end from joined where changed and old_emp is distinct from new_emp
  ), person as (
    select e.user_id,
      count(*) filter (where c.kind = 'first')::integer firsts,
      count(*) filter (where c.kind = 'added')::integer added,
      count(*) filter (where c.kind = 'changed')::integer changed,
      count(*) filter (where c.kind = 'removed')::integer removed,
      min(c.d) d, min(c.st) st, min(c.en) en
    from change c
    join public.employee_profiles e on e.id = c.emp and e.workspace_id = target_workspace
    -- The people the publish preview counted (schedule_people_told): the dialog's number.
    where c.emp = any (target_told)
    group by e.user_id
  ), worded as (
    select p.*, to_char(p.d, 'FMDy, FMMon FMDD') day_text, app_private.announcement_hours_text(p.st, p.en, fmt) hours,
      case when p.removed > 0 then 'schedule.shift_removed' when p.changed > 0 then 'schedule.shift_changed'
           when p.added > 0 then 'schedule.shift_added' else 'schedule.published' end kind,
      p.added + p.changed + p.removed = 1 and p.firsts = 0 single
    from person p
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'type', w.kind, 'user_id', w.user_id, 'event_key', 'publish:' || target_event::text,
    'title', case
      when w.kind = 'schedule.published' then 'Your schedule for ' || week || ' is out'
      when w.single and w.kind = 'schedule.shift_changed' then 'Your ' || w.day_text || ' shift changed'
      when w.single and w.kind = 'schedule.shift_added' then 'New shift: ' || w.day_text || ' · ' || w.hours
      when w.single then 'Your ' || w.day_text || ' shift was removed'
      else 'Your schedule for ' || week || ' changed' end,
    'body', case
      when w.kind = 'schedule.published' then w.firsts || case when w.firsts = 1 then ' shift' else ' shifts' end || ' this week.'
      when w.single and w.kind = 'schedule.shift_changed' then 'Now ' || w.hours || '.'
      when w.single and w.kind = 'schedule.shift_added' then null
      when w.single then 'It is no longer yours.'
      else array_to_string(array_remove(array[
        case when w.changed > 0 then w.changed || case when w.changed = 1 then ' shift changed' else ' shifts changed' end end,
        case when w.added + w.firsts > 0 then (w.added + w.firsts) || ' new' end,
        case when w.removed > 0 then w.removed || ' removed' end], null), ', ') || '.' end,
    'url', link, 'subject_type', 'schedule_publication', 'subject_id', target_event,
    'data', jsonb_build_object('week_start', target_week, 'added', w.added + w.firsts, 'changed', w.changed, 'removed', w.removed))),
    '[]'::jsonb)
  into notices from worded w;
  return app_private.notify_rows(target_workspace, target_actor, notices);
end;
$$;


ALTER FUNCTION "app_private"."schedule_tell_published"("target_workspace" "uuid", "target_actor" "uuid", "target_event" "uuid", "target_week" "date", "target_pairs" "jsonb", "target_told" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_tell_unassigned"("target_workspace" "uuid", "shift_ids" "uuid"[], "actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  place record;
  told integer := 0;
  card uuid;
begin
  for place in
    select s.location_id, l.name, count(*)::integer shifts, array_agg(s.id order by s.id) ids
    from public.schedule_published_shifts s
    join public.locations l on l.id = s.location_id and l.workspace_id = s.workspace_id
    where s.workspace_id = target_workspace and s.id = any (coalesce(shift_ids, '{}'))
    group by s.location_id, l.name
  loop
    -- Each card is its own subject, so closing it touches no other card about the same place.
    card := gen_random_uuid();
    told := told + app_private.people_tell('schedule.shifts_unassigned', target_workspace,
      app_private.place_deciders(target_workspace, 'schedule.publish', place.location_id),
      'unassigned:' || card::text,
      place.shifts || case when place.shifts = 1 then ' shift at ' else ' shifts at ' end || place.name
        || case when place.shifts = 1 then ' has nobody' else ' have nobody' end,
      'Give them to somebody or leave them open.',
      '/app/schedule', actor, 'unassigned_shifts', card,
      jsonb_build_object('location_id', place.location_id, 'shift_ids', to_jsonb(place.ids)));
  end loop;
  return told;
exception when others then
  raise warning 'schedule_tell_unassigned: notices skipped: % (%)', sqlerrm, sqlstate;
  return 0;
end;
$$;


ALTER FUNCTION "app_private"."schedule_tell_unassigned"("target_workspace" "uuid", "shift_ids" "uuid"[], "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_tell_unpublished"("target_workspace" "uuid", "target_actor" "uuid", "target_event" "uuid", "target_week" "date", "target_publications" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  week text := app_private.schedule_week_text(target_week);
  notices jsonb;
begin
  with held as (
    select s.employee_id, s.source_shift_id from public.schedule_published_shifts s
    where s.workspace_id = target_workspace and s.publication_id = any (target_publications) and s.employee_id is not null
  ), person as (
    select e.user_id, bool_or(exists (
      select 1 from public.shift_exchange_cases c
      where c.workspace_id = target_workspace and c.status = 'open'
        and (c.offered_source_id = h.source_shift_id or c.requested_source_id = h.source_shift_id))) asked
    from held h join public.employee_profiles e on e.id = h.employee_id and e.workspace_id = target_workspace
    where e.user_id is not null
    group by e.user_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'type', 'schedule.unpublished', 'user_id', p.user_id, 'event_key', 'unpublish:' || target_event::text,
    'title', 'Your schedule for ' || week || ' was taken back',
    'body', 'It isn''t final until it is published again.'
      -- The exchange maintenance closes them right after; the notice says it will.
      || case when p.asked then ' Your open shift change requests for those shifts will be closed.' else '' end,
    'url', '/app/employee-hub/schedule?view=day&date=' || target_week::text,
    'subject_type', 'schedule_publication', 'subject_id', target_event,
    'data', jsonb_build_object('week_start', target_week, 'requests_closed', p.asked))), '[]'::jsonb)
  into notices from person p;
  return app_private.notify_rows(target_workspace, target_actor, notices);
end;
$$;


ALTER FUNCTION "app_private"."schedule_tell_unpublished"("target_workspace" "uuid", "target_actor" "uuid", "target_event" "uuid", "target_week" "date", "target_publications" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_template_department_ids"("w" "uuid", "department_keys" "text"[]) RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  ids uuid[];
begin
  if department_keys is null then
    return '{}'::uuid[];
  end if;
  if cardinality(department_keys) = 0 then
    raise exception 'select at least one department' using errcode = '22023';
  end if;
  if exists (
    select 1 from unnest(department_keys) as key(value)
    where key.value <> '__no_department__'
      and key.value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception 'invalid department key' using errcode = '22023';
  end if;
  ids := array(select key.value::uuid from unnest(department_keys) as key(value) where key.value <> '__no_department__');
  if exists (
    select 1 from unnest(ids) as selected(id)
    left join public.departments department
      on department.id = selected.id and department.workspace_id = w and department.archived_at is null
    where department.id is null
  ) then
    raise exception 'schedule template department not found' using errcode = 'P0002';
  end if;
  return ids;
end;
$_$;


ALTER FUNCTION "app_private"."schedule_template_department_ids"("w" "uuid", "department_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_template_replace_targets"("w" "uuid", "edit_session" "uuid", "template" "uuid", "department_keys" "text"[]) RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with template_shift as (
    select template_shift.location_id, job.department_id
    from public.schedule_template_shifts template_shift
    join public.jobs job on job.id = template_shift.job_id and job.workspace_id = template_shift.workspace_id
    where template_shift.template_id = template and template_shift.workspace_id = w
      and template_shift.location_id = any (public.live_location_ids(w, array(
        select distinct s.location_id from public.schedule_template_shifts s where s.template_id = template)))
  ), picked as (
    select app_private.schedule_template_department_ids(w, department_keys) as ids
  )
  select edit_shift.id
  from public.schedule_edit_session_shifts edit_shift
  join public.jobs job on job.id = edit_shift.job_id and job.workspace_id = edit_shift.workspace_id
  join public.locations location on location.id = edit_shift.location_id and location.workspace_id = edit_shift.workspace_id
  cross join picked
  where edit_shift.session_id = edit_session and edit_shift.workspace_id = w
    and edit_shift.pending_op_type is distinct from 'delete'
    and exists (
      select 1 from template_shift t
      where t.location_id = edit_shift.location_id and t.department_id is not distinct from job.department_id)
    and (department_keys is null
      or job.department_id = any (picked.ids)
      or (job.department_id is null and '__no_department__' = any (department_keys)))
    -- A shift that has started stays (P09); an unknown time counts as not started.
    and coalesce(lower(app_private.shift_time_range(edit_shift.scheduled_date, edit_shift.start_time,
          edit_shift.end_time, coalesce(edit_shift.time_timezone, location.timezone))) > now(), true)
$$;


ALTER FUNCTION "app_private"."schedule_template_replace_targets"("w" "uuid", "edit_session" "uuid", "template" "uuid", "department_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_week_availability"("target_workspace_id" "uuid", "target_week_start" "date", "target_employee_ids" "uuid"[], "target_location_ids" "uuid"[], "with_reminders" boolean DEFAULT true) RETURNS TABLE("employee_id" "uuid", "location_id" "uuid", "unavailable" "tstzmultirange", "leave" "tstzmultirange", "projection" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
with location_zone as (
  select l.id, l.name, l.timezone, app_private.timezone_name_valid(l.timezone) as zone_ok
  from public.locations l
  where l.workspace_id = target_workspace_id and l.id = any(target_location_ids)
), zone as (
  select distinct z.timezone as zone_name from location_zone z where z.zone_ok
), piece as (
  -- Two four-day pieces, as the offset helper is bounded to eight physical
  -- days and a fall-back week is eight days and an hour.
  select z.zone_name,
    tstzrange((target_week_start + o.offset_days)::timestamp at time zone z.zone_name,
              (target_week_start + o.offset_days + 4)::timestamp at time zone z.zone_name, '[)') as span
  from zone z cross join (values (0), (4)) o(offset_days)
), segment as (
  select p.zone_name, s.utc_span, s.offset_seconds
  from piece p cross join lateral public.availability_offset_segments(p.span, p.zone_name) s
), mark as (
  select e.employee_id, false as reminder, e.preference, public.weekly_preference_valid(e.preference) as valid
  from public.employee_weekly_preferences e
  where e.workspace_id = target_workspace_id and e.employee_id = any(target_employee_ids)
  union all
  select m.employee_id, true, m.preference, public.weekly_preference_valid(m.preference)
  from public.manager_weekly_reminders m
  where with_reminders and m.workspace_id = target_workspace_id and m.employee_id = any(target_employee_ids) and m.enabled
), mark_day as (
  select m.employee_id, m.reminder, d.value as rule
  from mark m cross join lateral jsonb_array_elements(case when m.valid then m.preference -> 'days' else '[]'::jsonb end) d
), clock as (
  -- Availability is hours only: a whole day, or the day's one range.
  select md.employee_id, md.reminder, (md.rule ->> 'day')::integer as dow,
    time '00:00' as start_clock, time '24:00' as end_clock
  from mark_day md
  where coalesce((md.rule ->> 'all_day')::boolean, false)
  union all
  select md.employee_id, md.reminder, (md.rule ->> 'day')::integer,
    (r.value ->> 'start')::time, (r.value ->> 'end')::time
  from mark_day md
  cross join lateral jsonb_array_elements(md.rule -> 'ranges') r
  where not coalesce((md.rule ->> 'all_day')::boolean, false)
), broken as (
  -- A mark that cannot be read makes the employee's week unknown rather than
  -- partly drawn.
  select m.employee_id from mark m where not m.valid
), local_day as (
  select s.zone_name, s.utc_span, s.offset_seconds, day::date as local_date
  from segment s
  cross join lateral generate_series(
    (((lower(s.utc_span) at time zone 'UTC') + make_interval(secs => s.offset_seconds))::date - 1)::timestamp,
    (((upper(s.utc_span) at time zone 'UTC') + make_interval(secs => s.offset_seconds))::date)::timestamp,
    interval '1 day') day
), unavailable_piece as (
  select c.employee_id, c.reminder, ld.zone_name,
    tstzrange(((ld.local_date + c.start_clock) at time zone 'UTC') - make_interval(secs => ld.offset_seconds),
              ((ld.local_date + c.end_clock + case when c.end_clock < c.start_clock then interval '1 day' else interval '0' end) at time zone 'UTC')
                - make_interval(secs => ld.offset_seconds), '[)') * ld.utc_span as span
  from local_day ld
  join clock c on c.dow = extract(dow from ld.local_date)::integer
), unavailable as (
  -- Unavailable is the employee's own marks; a manager's note is kept apart,
  -- only a reminder (M12).
  select u.employee_id, u.zone_name, range_agg(u.span) filter (where not u.reminder) as spans,
    range_agg(u.span) filter (where u.reminder) as note_spans
  from unavailable_piece u
  where not isempty(u.span)
  group by u.employee_id, u.zone_name
), leave_target as (
  select z.zone_name,
    tstzrange(target_week_start::timestamp at time zone z.zone_name, (target_week_start + 8)::timestamp at time zone z.zone_name, '[)') as span
  from zone z
), leave_piece as materialized (
  -- Read once for the week and a day either side, whatever the zones (UTC-12 to UTC+14).
  -- Time off waiting for an answer comes in the same read, kept apart below.
  select away.employee_id, away.span, away.pending
  from app_private.leave_spans(target_workspace_id, target_employee_ids,
    tstzrange((target_week_start - 1)::timestamp at time zone 'UTC', (target_week_start + 9)::timestamp at time zone 'UTC', '[)')) away
), leave as (
  select lp.employee_id, lt.zone_name, range_agg(lp.span * lt.span) as spans
  from leave_target lt
  join leave_piece lp on lp.span && lt.span and not lp.pending
  group by lp.employee_id, lt.zone_name
), pending_leave as (
  -- Time off waiting for an answer (KARARLAR S-239 (9)): only a warning. It is never part of `leave`, so
  -- nothing blocks on it and it is no conflict; the grid hands it only to who may answer it.
  select lp.employee_id, lt.zone_name, range_agg(lp.span * lt.span) as spans
  from leave_target lt
  join leave_piece lp on lp.span && lt.span and lp.pending
  group by lp.employee_id, lt.zone_name
), clock_segments as (
  select s.zone_name,
    jsonb_agg(jsonb_build_object('start_at', lower(s.utc_span), 'end_at', upper(s.utc_span), 'offset_seconds', s.offset_seconds)
      order by lower(s.utc_span)) as segments
  from segment s
  group by s.zone_name
), day_span as (
  select z.zone_name, target_week_start + i as work_date,
    tstzrange((target_week_start + i)::timestamp at time zone z.zone_name, (target_week_start + i + 1)::timestamp at time zone z.zone_name, '[)') as span
  from zone z cross join generate_series(0, 6) i
), employee_zone as (
  -- Everything but the location's own name is the same for every location in
  -- a time zone, so it is built once per employee and zone.
  select e.employee_id, z.zone_name,
    coalesce(u.spans, '{}'::tstzmultirange) as unavailable,
    coalesce(lv.spans, '{}'::tstzmultirange) as leave,
    jsonb_build_object(
      'status', 'ready',
      'unavailable_intervals', public.availability_ranges_json(coalesce(u.spans, '{}'::tstzmultirange)),
      'employee_intervals', public.availability_ranges_json(coalesce(u.spans, '{}'::tstzmultirange)),
      -- The note's hours, for the card shown while writing; the caller keeps
      -- them only for whoever may read the note.
      'note_intervals', public.availability_ranges_json(coalesce(u.note_spans, '{}'::tstzmultirange)),
      'leave_intervals', public.availability_ranges_json(coalesce(lv.spans, '{}'::tstzmultirange)),
      'pending_leave_intervals', public.availability_ranges_json(coalesce(pl.spans, '{}'::tstzmultirange)),
      'clock_segments', cs.segments,
      'days', (select jsonb_agg(jsonb_build_object(
                 'date', ds.work_date,
                 'has_unavailable', coalesce(u.spans, '{}'::tstzmultirange) && ds.span,
                 'all_day', coalesce(u.spans, '{}'::tstzmultirange) @> ds.span) order by ds.work_date)
               from day_span ds where ds.zone_name = z.zone_name)) as body
  from unnest(target_employee_ids) e(employee_id)
  cross join zone z
  left join unavailable u on u.employee_id = e.employee_id and u.zone_name = z.zone_name
  left join leave lv on lv.employee_id = e.employee_id and lv.zone_name = z.zone_name
  left join pending_leave pl on pl.employee_id = e.employee_id and pl.zone_name = z.zone_name
  left join clock_segments cs on cs.zone_name = z.zone_name
  where not exists (select 1 from broken b where b.employee_id = e.employee_id)
)
select e.employee_id, lz.id, ez.unavailable, ez.leave,
  jsonb_build_object('location_id', lz.id, 'location_name', lz.name, 'timezone', lz.timezone, 'week_start', target_week_start)
  || coalesce(ez.body, jsonb_build_object('status', 'unknown', 'unavailable_intervals', '[]'::jsonb, 'employee_intervals', '[]'::jsonb, 'note_intervals', '[]'::jsonb, 'leave_intervals', '[]'::jsonb,
       'pending_leave_intervals', '[]'::jsonb, 'clock_segments', '[]'::jsonb, 'days', '[]'::jsonb))
from unnest(target_employee_ids) e(employee_id)
cross join location_zone lz
left join employee_zone ez on ez.employee_id = e.employee_id and ez.zone_name = lz.timezone and lz.zone_ok;
$$;


ALTER FUNCTION "app_private"."schedule_week_availability"("target_workspace_id" "uuid", "target_week_start" "date", "target_employee_ids" "uuid"[], "target_location_ids" "uuid"[], "with_reminders" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_week_start_at"("w" "uuid", "places" "uuid"[], "instant" timestamp with time zone) RETURNS "date"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case settings.week_start_day
    when 'sunday' then local.today - extract(dow from local.today)::integer
    else local.today - (extract(isodow from local.today)::integer - 1)
  end
  from public.workspace_scheduling_settings settings
  cross join lateral (
    -- The westernmost place's date: the week is not past while any place is still in it.
    select coalesce(
      (select min((instant at time zone location.timezone)::date) from public.locations location
       where location.workspace_id = w and location.id = any(places)),
      (select min((instant at time zone location.timezone)::date) from public.locations location
       where location.workspace_id = w and app_private.location_is_live(location)),
      (instant at time zone 'UTC')::date) as today
  ) local
  where settings.workspace_id = w;
$$;


ALTER FUNCTION "app_private"."schedule_week_start_at"("w" "uuid", "places" "uuid"[], "instant" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_week_text"("target_week" "date") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when date_trunc('month', target_week) = date_trunc('month', target_week + 6)
    then to_char(target_week, 'FMMon FMDD') || '–' || to_char(target_week + 6, 'FMDD')
    else to_char(target_week, 'FMMon FMDD') || '–' || to_char(target_week + 6, 'FMMon FMDD') end;
$$;


ALTER FUNCTION "app_private"."schedule_week_text"("target_week" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."scope_set"("actor" "uuid", "w" "uuid", "action" "text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rule_row app_private.authz_actions;
  state app_private.actor_state;
begin
  select * into rule_row from app_private.authz_actions a where a.key = action;
  if not found then
    raise exception 'Unknown action %', action using errcode = '22023';
  end if;
  state := app_private.actor(actor, w);
  return coalesce((
    select array_agg(location.id order by location.id)
    from public.locations location
    where location.workspace_id = w
      and app_private.location_is_live(location)
      and app_private.authz_check(state, rule_row, array[location.id], null, null) is null
  ), '{}');
end;
$$;


ALTER FUNCTION "app_private"."scope_set"("actor" "uuid", "w" "uuid", "action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."set_document_exemption"("r" "public"."employee_onboarding_requirements", "actor_user_id" "uuid", "make_exempt" boolean, "exemption_reason" "text", "expected_revision" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare next_deadline timestamptz; matching boolean; valid_approved boolean; asked public.employee_onboarding_requirements; next_revision integer;
begin
 if not make_exempt and app_private.employee_record_is_workspace_owner(r.workspace_id,r.employee_id) then
  raise exception 'an owner is not asked for the documents they ask of everyone else' using errcode='42501';
 end if;
 if not make_exempt then perform app_private.assert_document_published(r); end if;
 if expected_revision is null or r.lifecycle_revision<>expected_revision then raise exception 'document changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 if make_exempt is null or nullif(btrim(exemption_reason),'') is null or char_length(exemption_reason)>500 then raise exception 'exemption reason required' using errcode='22023'; end if;
 if r.lifecycle_exempt=make_exempt then return r.lifecycle_revision; end if;
 asked:=app_private.document_requirement_asked(r);
 matching:=app_private.document_target_matches(r.workspace_id,r.employee_id,r.lifecycle_settings->'target');
 -- Ignore exemption/closure while checking a retained approved version.
 r.lifecycle_exempt:=false; r.lifecycle_closed_at:=null;
 if r.status='superseded' then r.status:='not_started'; end if;
 valid_approved:=app_private.document_obligation_state(r,now())='completed';
 if not make_exempt and matching and not valid_approved and r.lifecycle_settings->>'mode'<>'optional' and r.lifecycle_settings->>'period_days' is not null then
  next_deadline:=now()+(r.lifecycle_settings->>'period_days')::integer*interval '24 hours';
 end if;
 update public.employee_onboarding_requirements set lifecycle_exempt=make_exempt,
  lifecycle_closed_at=case when make_exempt or matching then null else coalesce(lifecycle_closed_at,now()) end,
  lifecycle_close_reason=btrim(exemption_reason),deadline_at=next_deadline,paused_remaining_seconds=null,document_suspended_at=null,
  required=case when make_exempt then required else asked.required end,
  blocks_activation=case when make_exempt then blocks_activation else asked.blocks_activation end,
  owner_excused=false,
  lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning lifecycle_revision into next_revision;
 perform app_private.document_audit(r,actor_user_id,case when make_exempt then 'document.exempted' else 'document.exemption_removed' end,
  jsonb_build_object('reason',btrim(exemption_reason),'revision',next_revision,'old_deadline',r.deadline_at,'new_deadline',next_deadline,'matching',matching,'valid_approved',valid_approved));
 return next_revision;
end;
$$;


ALTER FUNCTION "app_private"."set_document_exemption"("r" "public"."employee_onboarding_requirements", "actor_user_id" "uuid", "make_exempt" boolean, "exemption_reason" "text", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."settings_locations"("w" "uuid", "ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(to_jsonb(l) order by l.sort_order, l.name, l.id), '[]'::jsonb)
  from (
    select location.id, location.workspace_id, location.name, location.short_name, location.phone,
      location.street_address, location.city, location.region, location.postal_code,
      location.country_code, location.timezone, location.sort_order, location.archived_at
    from public.locations location
    where location.workspace_id = w and location.deleted_at is null and location.id = any (ids)
  ) l;
$$;


ALTER FUNCTION "app_private"."settings_locations"("w" "uuid", "ids" "uuid"[]) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."shift_exchange_cases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "audience" "text" DEFAULT 'eligible_pool'::"text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "offered_source_id" "uuid" NOT NULL,
    "requested_source_id" "uuid",
    "owner_id" "uuid",
    "offered_snapshot" "jsonb" NOT NULL,
    "requested_snapshot" "jsonb",
    "consent_fingerprint" "text" NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "private_note" "text" DEFAULT ''::"text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "teammate_note" "text" DEFAULT ''::"text" NOT NULL,
    "open_shift_publication_id" "uuid",
    CONSTRAINT "shift_exchange_cases_audience_check" CHECK (("audience" = ANY (ARRAY['eligible_pool'::"text", 'direct'::"text"]))),
    CONSTRAINT "shift_exchange_cases_check" CHECK ((("kind" = 'swap'::"text") = ("requested_source_id" IS NOT NULL))),
    CONSTRAINT "shift_exchange_cases_kind_check" CHECK (("kind" = ANY (ARRAY['cover'::"text", 'swap'::"text"]))),
    CONSTRAINT "shift_exchange_cases_open_shift_check" CHECK ((("owner_id" IS NULL) = ("open_shift_publication_id" IS NOT NULL))),
    CONSTRAINT "shift_exchange_cases_open_shift_pool_check" CHECK ((("owner_id" IS NOT NULL) OR (("kind" = 'cover'::"text") AND ("audience" = 'eligible_pool'::"text")))),
    CONSTRAINT "shift_exchange_cases_private_note_check" CHECK (("length"("private_note") <= 1000)),
    CONSTRAINT "shift_exchange_cases_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'completed'::"text", 'cancelled'::"text", 'expired'::"text", 'invalidated'::"text"]))),
    CONSTRAINT "shift_exchange_cases_teammate_note_check" CHECK (("length"("teammate_note") <= 200))
);


ALTER TABLE "public"."shift_exchange_cases" OWNER TO "postgres";


COMMENT ON COLUMN "public"."shift_exchange_cases"."teammate_note" IS 'A release''s note for teammates: everyone it reaches reads it (TAKAS-RELEASE).';



COMMENT ON COLUMN "public"."shift_exchange_cases"."open_shift_publication_id" IS 'The publication that offered this open shift to eligible employees; set exactly when nobody owns the request (Mert, 2026-10-20).';



CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_case_item"("actor" "uuid", "w" "uuid", "c" "public"."shift_exchange_cases", "allowed" boolean, "emp_id" "uuid", "published_offered" "jsonb", "published_requested" "jsonb", "live_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare s jsonb := coalesce(published_offered, c.offered_snapshot); t jsonb := coalesce(published_requested, c.requested_snapshot);
 current_published boolean := published_offered is not null; requested_published boolean := published_requested is not null;
 decides boolean; mine boolean := coalesce(c.owner_id = emp_id, false); apps jsonb; hist jsonb; stage text;
begin
  -- Who decides the case (D3, K-S1) gets its buttons and its private notes (K-S5).
  decides:=allowed and exists(select 1 from unnest(array_remove(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid],null)) x
   where app_private.exchange_decision_reason(actor,w,c.owner_id,null,x) is null);
  select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'employee_id',a.employee_id,'employee_name',coalesce(nullif(e.preferred_name,''),concat_ws(' ',e.first_name,e.last_name)),
   'status',case when live_status in('expired','invalidated') and a.status in('invited','pending_manager') then live_status else a.status end,'created_at',a.created_at,'reason',case when allowed or a.employee_id=emp_id then a.reason else '' end,
   'eligibility',case when (allowed or a.employee_id=emp_id) and live_status='open' then (app_private.eligibility(w,a.employee_id,s,jsonb_build_object('operation',case when c.kind='swap' then 'swap' when c.audience='direct' then 'cover_accept' else 'release_pickup' end,'excluded',to_jsonb(array_remove(array[(s->>'id')::uuid,(t->>'id')::uuid],null))))-case when allowed then '{}'::text[] else array['approval_flags'] end) || case when a.employee_id=emp_id and a.status='invited' then jsonb_build_object('availability_warning',public.weekly_exchange_employee_warning(w,emp_id,s)) else '{}'::jsonb end end) order by a.created_at),'[]'::jsonb)
  into apps from public.shift_exchange_applications a join public.employee_profiles e on e.id=a.employee_id where a.case_id=c.id and (allowed or mine or a.employee_id=emp_id) and (a.status<>'declined_by_employee' or c.audience='direct');
  select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'action',e.action,'created_at',e.created_at,
   -- BL-910: a declined application's reason is read by the applicant and by who reads the
   -- location's requests (allowed), as applications[].reason already is.
   'message',case when e.action='application_rejected' and not allowed and not exists(select 1 from public.shift_exchange_applications a
    where a.id=e.application_id and a.employee_id=emp_id) then 'A request for your shift was declined. You are still responsible for this shift.' else e.message end,
   -- K-S5: the note goes to who decides this case for this application too.
   'private_note',case when decides and exists(select 1 from unnest(array_remove(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid],null)) x
    where app_private.exchange_decision_reason(actor,w,c.owner_id,(select a.employee_id from public.shift_exchange_applications a where a.id=e.application_id),x) is null)
    then nullif(e.private_note,'') end) order by e.created_at),'[]'::jsonb)
  into hist from public.shift_exchange_events e where e.case_id=c.id and (allowed or mine or e.application_id is null or exists(select 1 from public.shift_exchange_applications a where a.id=e.application_id and a.employee_id=emp_id));
  stage:=case when live_status<>'open' then 'closed'
   when exists(select 1 from public.shift_exchange_votes where case_id=c.id) then 'awaiting_other_manager'
   when exists(select 1 from public.shift_exchange_applications where case_id=c.id and status='pending_manager') then 'ready_for_manager'
   when exists(select 1 from public.shift_exchange_applications where case_id=c.id and status='invited') then 'awaiting_peer' else 'seeking_candidates' end;
 return jsonb_build_object('id',c.id,'kind',c.kind,'audience',c.audience,'status',live_status,'current_published',current_published,'requested_current_published',case when c.kind='swap' then requested_published else null end,
   'stage',stage,'revision',c.revision,'created_at',c.created_at,'expires_at',c.expires_at,'owner_id',c.owner_id,'owner_name',c.offered_snapshot->'employee_name',
   'shift',s,'requested_shift',t,'applications',apps,'candidate_count',(select count(*) from public.shift_exchange_applications where case_id=c.id and status in('invited','pending_manager') and live_status='open'),
   'can_manage',decides,
   'is_owner',mine,'teammate_note',c.teammate_note,'private_note',case when allowed or mine then c.private_note else '' end,'history',hist);
end; $$;


ALTER FUNCTION "app_private"."shift_exchange_case_item"("actor" "uuid", "w" "uuid", "c" "public"."shift_exchange_cases", "allowed" boolean, "emp_id" "uuid", "published_offered" "jsonb", "published_requested" "jsonb", "live_status" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."shift_exchange_case_item"("actor" "uuid", "w" "uuid", "c" "public"."shift_exchange_cases", "allowed" boolean, "emp_id" "uuid", "published_offered" "jsonb", "published_requested" "jsonb", "live_status" "text") IS 'One shift change as the Requests lists draw it; the reader decides who may see it (EKRAN-02 A4).';



CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_deadline"("s" "jsonb", "t" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select least((s ->> 'starts_at')::timestamptz, (t ->> 'starts_at')::timestamptz) - interval '4 hours'
$$;


ALTER FUNCTION "app_private"."shift_exchange_deadline"("s" "jsonb", "t" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."shift_exchange_deadline"("s" "jsonb", "t" "jsonb") IS 'When a shift change closes: 4 hours before its shift, the earlier one in a swap (TAKAS-RELEASE).';



CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_deciders"("w" "uuid", "cid" "uuid", "receiver" "uuid", "waiting" boolean DEFAULT false) RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  c public.shift_exchange_cases%rowtype;
  loc uuid;
  here uuid[];
  found uuid[] := '{}';
begin
  select * into c from public.shift_exchange_cases x where x.id = cid and x.workspace_id = w;
  for loc in select distinct x from unnest(array_remove(array[(c.offered_snapshot ->> 'location_id')::uuid,
    (c.requested_snapshot ->> 'location_id')::uuid], null)) x loop
    if waiting and exists (select 1 from public.shift_exchange_votes v where v.case_id = cid and v.location_id = loc) then
      continue;
    end if;
    here := array(select u from unnest(app_private.notify_holders(w, 'exchange.approve', array[loc])) u
                  where app_private.exchange_decision_reason(u, w, c.owner_id, receiver, loc) is null);
    found := found || coalesce(
      nullif(array(select u from unnest(here) u where (app_private.actor(u, w)).class not in ('owner', 'admin')), '{}'),
      nullif(array(select u from unnest(here) u where (app_private.actor(u, w)).class = 'admin'), '{}'),
      here);
  end loop;
  return array(select distinct u from unnest(found) u order by u);
end;
$$;


ALTER FUNCTION "app_private"."shift_exchange_deciders"("w" "uuid", "cid" "uuid", "receiver" "uuid", "waiting" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_name"("w" "uuid", "emp" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select btrim(coalesce(nullif(e.preferred_name, ''), e.first_name) || ' ' || e.last_name)
  from public.employee_profiles e where e.workspace_id = shift_exchange_name.w and e.id = shift_exchange_name.emp
$$;


ALTER FUNCTION "app_private"."shift_exchange_name"("w" "uuid", "emp" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_pool"("w" "uuid", "cid" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  c public.shift_exchange_cases%rowtype;
  s jsonb;
  e record;
  checked jsonb;
  found uuid[] := '{}';
begin
  select * into c from public.shift_exchange_cases x where x.id = cid and x.workspace_id = w;
  s := public.shift_exchange_shift(w, c.offered_source_id);
  if s is null then
    return found;
  end if;
  for e in select p.id, p.user_id from public.employee_profiles p
    join public.workspace_memberships m on m.workspace_id = p.workspace_id and m.user_id = p.user_id and m.status = 'active'
    where p.workspace_id = w and p.archived_at is null and p.id <> c.owner_id
    order by p.id loop
    if app_private.authz_reason(e.user_id, w, 'exchange.apply_own') is not null then
      continue;
    end if;
    checked := app_private.eligibility(w, e.id, s, '{"operation":"release_pickup"}');
    if checked ->> 'status' = 'eligible' or (checked ->> 'status' = 'ineligible' and not exists (
      select 1 from jsonb_array_elements(checked -> 'blockers') b where b ->> 'code' <> 'approved_time_off')) then
      found := found || e.user_id;
    end if;
  end loop;
  return found;
end;
$$;


ALTER FUNCTION "app_private"."shift_exchange_pool"("w" "uuid", "cid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_reached_managers"("w" "uuid", "cid" "uuid") RETURNS boolean
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  select case
    when c.status = 'open' and public.shift_exchange_live_status(shift_exchange_reached_managers.w, c.id) = 'open' then
      exists (select 1 from public.shift_exchange_applications a where a.case_id = c.id and a.status in ('pending_manager', 'rejected_by_manager'))
      or exists (select 1 from public.shift_exchange_votes v where v.case_id = c.id)
    else exists (select 1 from public.shift_exchange_events e
      where e.workspace_id = shift_exchange_reached_managers.w and e.case_id = c.id
        and e.action in ('application_submitted', 'peer_accepted'))
  end
  from public.shift_exchange_cases c
  where c.workspace_id = shift_exchange_reached_managers.w and c.id = shift_exchange_reached_managers.cid
$$;


ALTER FUNCTION "app_private"."shift_exchange_reached_managers"("w" "uuid", "cid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_remind"("pass_limit" integer DEFAULT 500) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  c public.shift_exchange_cases%rowtype;
  a public.shift_exchange_applications%rowtype;
  first_ask timestamptz;
  waiting uuid[];
  owner_name text;
  who_name text;
  said text;
  zone text;
  fmt text;
  turn integer;
  done integer := 0;
begin
  for c in select x.* from public.shift_exchange_cases x
    where x.status = 'open' and x.expires_at > now()
      and exists (select 1 from public.shift_exchange_applications p where p.case_id = x.id and p.status = 'pending_manager')
    order by x.expires_at, x.id limit pass_limit loop
    begin
    -- The lock a decision holds (shift_exchanges_command_service): a case being decided waits for the next pass.
    if not pg_try_advisory_xact_lock(hashtextextended(c.workspace_id::text, 921)) then
      continue;
    end if;
    if not exists (select 1 from public.shift_exchange_cases x where x.id = c.id and x.status = 'open')
      or public.shift_exchange_live_status(c.workspace_id, c.id) <> 'open' then
      continue;
    end if;
    select min(e.created_at) into first_ask from public.shift_exchange_events e
    where e.case_id = c.id and e.action in ('application_submitted', 'peer_accepted');
    if first_ask is null then
      continue;
    end if;
    select * into a from public.shift_exchange_applications p where p.case_id = c.id and p.status = 'pending_manager'
    order by p.created_at, p.id limit 1;
    waiting := app_private.shift_exchange_deciders(c.workspace_id, c.id, a.employee_id, true);
    owner_name := app_private.shift_exchange_name(c.workspace_id, c.owner_id);
    who_name := app_private.shift_exchange_name(c.workspace_id, a.employee_id);
    said := case when c.kind = 'swap'
      then owner_name || ' and ' || who_name || ' want to swap ' || app_private.shift_exchange_shift_text(c.workspace_id, c.offered_snapshot)
        || ' for ' || app_private.shift_exchange_shift_text(c.workspace_id, c.requested_snapshot)
      -- An open shift a publish offered has nobody's name on it (Mert, 2026-10-20).
      when c.owner_id is null then who_name || ' wants the open shift ' || app_private.shift_exchange_shift_text(c.workspace_id, c.offered_snapshot)
      else who_name || ' wants ' || owner_name || '''s ' || app_private.shift_exchange_shift_text(c.workspace_id, c.offered_snapshot) end;
    if now() >= c.expires_at - interval '4 hours' then
      if first_ask >= c.expires_at - interval '4 hours'
        or exists (select 1 from public.person_notifications n where n.workspace_id = c.workspace_id
                   and n.subject_id = c.id and n.event_key = 'case:' || c.id::text || ':last_call') then
        continue;
      end if;
      -- A new reminder replaces the one before it.
      perform app_private.shift_exchange_resolve(c.workspace_id, c.id, array['shift_changes.approval_reminder'], 'reminded_again', null, waiting);
      zone := coalesce(c.offered_snapshot ->> 'timezone', 'UTC');
      fmt := (select x.time_format from public.workspace_scheduling_settings x where x.workspace_id = c.workspace_id);
      done := done + app_private.notify('shift_changes.approval_reminder', c.workspace_id, waiting, 'case:' || c.id::text || ':last_call',
        'Decide by ' || to_char(c.expires_at at time zone zone, case when fmt = '24h' then 'FMDy HH24:MI' else 'FMDy FMHH12:MI AM' end)
          || ' or it closes',
        said, '/app/schedule/requests?type=shift_changes', null, 'shift_exchange_case', c.id,
        jsonb_build_object('case_id', c.id, 'kind', c.kind, 'audience', c.audience, 'last_call', true));
    elsif not exists (select 1 from public.person_notifications n where n.workspace_id = c.workspace_id
                      and n.subject_id = c.id and n.event_key = 'case:' || c.id::text || ':last_call') then
      turn := floor(extract(epoch from now() - first_ask) / 43200)::integer;
      if turn >= 1 and not exists (select 1 from public.person_notifications n where n.workspace_id = c.workspace_id
                                   and n.subject_id = c.id and n.event_key = 'case:' || c.id::text || ':reminder:' || turn::text) then
        perform app_private.shift_exchange_resolve(c.workspace_id, c.id, array['shift_changes.approval_reminder'], 'reminded_again', null, waiting);
        done := done + app_private.notify('shift_changes.approval_reminder', c.workspace_id, waiting,
          'case:' || c.id::text || ':reminder:' || turn::text, 'Shift change still waits for your approval',
          said, '/app/schedule/requests?type=shift_changes', null, 'shift_exchange_case', c.id,
          jsonb_build_object('case_id', c.id, 'kind', c.kind, 'audience', c.audience));
      end if;
    end if;
    exception when others then
      -- One broken case does not stop the others' reminders (as time_off_sweep).
      raise warning 'shift-exchange-reminders: case % of workspace % failed: % %', c.id, c.workspace_id, sqlstate, sqlerrm;
    end;
  end loop;
  return done;
end;
$$;


ALTER FUNCTION "app_private"."shift_exchange_remind"("pass_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_resolve"("w" "uuid", "cid" "uuid", "kinds" "text"[], "how" "text", "by_user" "uuid", "people" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  told uuid[];
  person uuid;
begin
  with closed as (
    update public.person_notifications n
    set resolved_at = now(), resolution = how, resolved_by = by_user
    from public.notification_types t
    where t.key = n.type_key and t.needs_action
      and n.workspace_id = w and n.subject_type = 'shift_exchange_case' and n.subject_id = cid
      and n.resolved_at is null
      and (kinds is null or n.type_key = any (kinds))
      and (people is null or n.user_id = any (people))
    returning n.user_id
  )
  select coalesce(array_agg(x.user_id), '{}'::uuid[]) into told from closed x;
  foreach person in array array(select distinct x from unnest(told) x) loop
    perform realtime.send(jsonb_build_object('workspace_id', w), 'changed', 'notifications:' || person::text, true);
  end loop;
  return cardinality(told);
end;
$$;


ALTER FUNCTION "app_private"."shift_exchange_resolve"("w" "uuid", "cid" "uuid", "kinds" "text"[], "how" "text", "by_user" "uuid", "people" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_shift_text"("w" "uuid", "s" "jsonb") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select to_char((s ->> 'date')::date, 'FMDy, FMMon FMDD') || ' · '
    || app_private.announcement_hours_text((s ->> 'start_time')::time, (s ->> 'end_time')::time,
         (select x.time_format from public.workspace_scheduling_settings x where x.workspace_id = shift_exchange_shift_text.w))
    || ' · ' || coalesce(s ->> 'job_name', 'Unassigned position') || ', ' || coalesce(s ->> 'location_name', '')
$$;


ALTER FUNCTION "app_private"."shift_exchange_shift_text"("w" "uuid", "s" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shift_exchange_tell"("actor" "uuid", "w" "uuid", "cid" "uuid", "aid" "uuid", "act" "text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  c public.shift_exchange_cases%rowtype;
  a public.shift_exchange_applications%rowtype;
  approvals constant text[] := array['shift_changes.approval_needed', 'shift_changes.approval_reminder'];
  invitations constant text[] := array['shift_changes.cover_asked', 'shift_changes.swap_offered'];
  hub text;
  desk text := '/app/schedule/requests?type=shift_changes';
  key text := 'case:' || cid::text;
  owner_user uuid;
  owner_name text;
  whose text;
  whose_day text;
  who_user uuid;
  who_name text;
  day text;
  day_only text;
  theirs text;
  pool boolean;
  what text;
  askers uuid[];
  deciders uuid[];
  facts jsonb;
  sent integer := 0;
begin
  select * into c from public.shift_exchange_cases x where x.id = cid and x.workspace_id = w;
  if c.id is null then
    return 0;
  end if;
  if aid is not null then
    select * into a from public.shift_exchange_applications x where x.id = aid and x.case_id = cid;
    who_user := app_private.shift_exchange_user(w, a.employee_id);
    who_name := app_private.shift_exchange_name(w, a.employee_id);
  end if;
  owner_user := app_private.shift_exchange_user(w, c.owner_id);
  owner_name := app_private.shift_exchange_name(w, c.owner_id);
  day := app_private.shift_exchange_shift_text(w, c.offered_snapshot);
  -- An open shift a publish offered has nobody's name on it (Mert, 2026-10-20).
  whose := case when c.owner_id is null then 'the open shift' else owner_name || '''s shift' end;
  whose_day := case when c.owner_id is null then 'the open shift ' || day else owner_name || '''s ' || day end;
  day_only := to_char((c.offered_snapshot ->> 'date')::date, 'FMDy, FMMon FMDD');
  theirs := case when c.kind = 'swap' then app_private.shift_exchange_shift_text(w, c.requested_snapshot) end;
  pool := c.audience = 'eligible_pool';
  -- Shift Hub opens on the case and its days (it reads 42 days from today otherwise).
  hub := '/app/employee-hub/shift-hub?case=' || cid::text
    || '&from=' || least(c.offered_snapshot ->> 'date', coalesce(c.requested_snapshot ->> 'date', c.offered_snapshot ->> 'date'))
    || '&to=' || greatest(c.offered_snapshot ->> 'date', coalesce(c.requested_snapshot ->> 'date', c.offered_snapshot ->> 'date'));
  what := case when c.kind = 'swap' then 'swap' else 'cover' end;
  facts := jsonb_build_object('case_id', cid, 'kind', c.kind, 'audience', c.audience)
    || case when aid is not null then jsonb_build_object('application_id', aid) else '{}'::jsonb end;

  if act = 'cover_opened' then
    -- An offered open shift waits in Shift Hub: nobody is told until the notification program starts.
    if c.owner_id is null then
      return 0;
    end if;
    -- A release, to everyone it reaches (plan 04:51).
    return app_private.notify('shift_changes.open_shift_available', w, app_private.shift_exchange_pool(w, cid), key || ':open',
      'Extra shift available', owner_name || ' can''t make ' || day || '. Want it?', hub || '&hub_view=available', actor, 'shift_exchange_case', cid, facts);

  elsif act = 'peer_invited' then
    if c.kind = 'swap' then
      return app_private.notify('shift_changes.swap_offered', w, array[who_user], key || ':invite:' || aid::text,
        'Confirm your swap with ' || owner_name, 'You give ' || theirs || ' · You get ' || day, hub, actor, 'shift_exchange_case', cid, facts);
    end if;
    return app_private.notify('shift_changes.cover_asked', w, array[who_user], key || ':invite:' || aid::text,
      owner_name || ' asked you to cover', day, hub, actor, 'shift_exchange_case', cid, facts);

  elsif act in ('application_submitted', 'peer_accepted') then
    if act = 'peer_accepted' then
      perform app_private.shift_exchange_resolve(w, cid, invitations, 'accepted', actor, array[who_user]);
      if c.kind = 'swap' then
        sent := sent + app_private.notify('shift_changes.swap_answered', w, array[owner_user], key || ':answer:' || aid::text,
          who_name || ' confirmed your swap', 'You give ' || day || ' · You get ' || theirs || '. Your manager decides.',
          hub, actor, 'shift_exchange_case', cid, facts);
      end if;
    end if;
    -- Who decides hears it once while a card of theirs is open (plan 05:03: the first one asking rings).
    deciders := array(select u from unnest(app_private.shift_exchange_deciders(w, cid, a.employee_id)) u
      where not exists (select 1 from public.person_notifications n where n.workspace_id = w
        and n.subject_type = 'shift_exchange_case' and n.subject_id = cid and n.user_id = u
        and n.type_key = any (approvals) and n.resolved_at is null));
    return sent + app_private.notify('shift_changes.approval_needed', w, deciders, key || ':approval:' || aid::text,
      'Shift change needs your approval',
      case when c.kind = 'swap' then owner_name || ' and ' || who_name || ' want to swap ' || day || ' for ' || theirs
        else who_name || ' wants ' || whose_day end,
      desk, actor, 'shift_exchange_case', cid, facts);

  elsif act in ('peer_declined', 'application_withdrawn', 'application_closed') then
    -- An answer: declined, taken back, or closed because its teammate left (close_employee_side).
    perform app_private.shift_exchange_resolve(w, cid, invitations,
      case act when 'peer_declined' then 'declined' when 'application_withdrawn' then 'withdrawn' else 'closed' end, actor, array[who_user]);
    if not pool then
      if c.kind = 'swap' then
        sent := app_private.notify('shift_changes.swap_answered', w, array[owner_user], key || ':answer:' || aid::text,
          who_name || case act when 'peer_declined' then ' declined your swap' when 'application_withdrawn' then ' withdrew from your swap'
            else ' can no longer swap with you' end,
          'Nothing changed. You still work ' || day || '.', hub, actor, 'shift_exchange_case', cid, facts);
      else
        sent := app_private.notify('shift_changes.cover_unfilled', w, array[owner_user], key || ':unfilled:' || aid::text,
          'No one could cover your ' || day_only || ' shift',
          who_name || case when act = 'peer_declined' then ' can''t cover it.' else ' can no longer cover it.' end
            || ' You are still responsible for this shift.', hub, actor, 'shift_exchange_case', cid, facts);
      end if;
      perform app_private.shift_exchange_resolve(w, cid, null, 'withdrawn', actor);
    elsif not exists (select 1 from public.shift_exchange_applications x where x.case_id = cid and x.status = 'pending_manager') then
      perform app_private.shift_exchange_resolve(w, cid, approvals, 'withdrawn', actor);
    end if;
    return sent;

  elsif act = 'scope_approved' then
    -- One location approved a two-location swap: its deciders' cards close; the other location's wait.
    perform app_private.shift_exchange_resolve(w, cid, approvals, 'approved', actor,
      array(select u from unnest(app_private.shift_exchange_deciders(w, cid, a.employee_id)) u
            where u <> all (app_private.shift_exchange_deciders(w, cid, a.employee_id, true))));
    return 0;

  elsif act = 'application_rejected' then
    -- The reason is the applicant's (BL-910); the owner reads that it was declined.
    sent := app_private.notify('shift_changes.decided', w, array[who_user], key || ':decided:' || aid::text,
      case when pool then 'Your pickup request was declined'
        when c.kind = 'swap' then 'Your swap with ' || owner_name || ' was declined'
        else 'Your cover for ' || owner_name || ' was declined' end,
      coalesce(nullif(btrim(coalesce(a.reason, '')), ''), day || '. Your schedule has not changed.'),
      hub, actor, 'shift_exchange_case', cid, facts || jsonb_build_object('outcome', 'declined'));
    if not pool then
      sent := sent + app_private.notify('shift_changes.decided', w, array[owner_user], key || ':decided:' || aid::text,
        'Your manager declined the ' || what,
        case when c.kind = 'swap' then 'Nothing changed. You still work ' || day || '.'
          else who_name || ' won''t cover ' || day || '. You are still responsible for this shift.' end,
        hub, actor, 'shift_exchange_case', cid, facts || jsonb_build_object('outcome', 'declined'));
      perform app_private.shift_exchange_resolve(w, cid, null, 'declined', actor);
    elsif not exists (select 1 from public.shift_exchange_applications x where x.case_id = cid and x.status = 'pending_manager') then
      perform app_private.shift_exchange_resolve(w, cid, approvals, 'declined', actor);
    end if;
    return sent;

  elsif act = 'other_selected' then
    if pool then
      return app_private.notify('shift_changes.open_shift_taken', w, array[who_user], key || ':taken:' || aid::text,
        'Another teammate got it', day || '. Your schedule has not changed.', hub, actor, 'shift_exchange_case', cid, facts);
    end if;
    return app_private.notify('shift_changes.cover_taken', w, array[who_user], key || ':taken:' || aid::text,
      'Someone else is covering', day || '. Your schedule has not changed.', hub, actor, 'shift_exchange_case', cid, facts);

  elsif act = 'transfer_completed' then
    if c.kind = 'swap' then
      sent := app_private.notify('shift_changes.decided', w, array[who_user], key || ':decided:' || aid::text,
        'Your swap is approved', 'You now work ' || day || '.', hub, actor, 'shift_exchange_case', cid,
        facts || jsonb_build_object('outcome', 'approved'))
        + app_private.notify('shift_changes.decided', w, array[owner_user], key || ':decided:' || aid::text,
        'Your swap is approved', 'You now work ' || theirs || '.', hub, actor, 'shift_exchange_case', cid,
        facts || jsonb_build_object('outcome', 'approved'));
    else
      sent := app_private.notify('shift_changes.decided', w, array[who_user], key || ':decided:' || aid::text,
        case when pool then 'Your pickup is approved' else 'Your cover is approved' end, day || '. It''s yours now.',
        hub, actor, 'shift_exchange_case', cid, facts || jsonb_build_object('outcome', 'approved'))
        + app_private.notify('shift_changes.decided', w, array[owner_user], key || ':decided:' || aid::text,
        'You are no longer responsible for this shift', who_name || ' works ' || day || ' now.',
        hub, actor, 'shift_exchange_case', cid, facts || jsonb_build_object('outcome', 'approved'));
    end if;
    perform app_private.shift_exchange_resolve(w, cid, null, 'approved', actor);
    return sent;

  elsif act = 'case_closed' then
    askers := array(select app_private.shift_exchange_user(w, x.employee_id) from public.shift_exchange_applications x
      where x.case_id = cid and x.status = 'closed_case_cancelled');
    if c.owner_id is not null and actor is not distinct from owner_user then
      -- Taken back (plan §3 Release: "Maria kept this shift").
      sent := app_private.notify(case when pool then 'shift_changes.open_shift_kept' else 'shift_changes.closed' end, w, askers,
        key || ':closed', case when pool then owner_name || ' kept this shift' else owner_name || ' cancelled the request' end,
        day || '. Your schedule has not changed.', hub, actor, 'shift_exchange_case', cid, facts);
    else
      -- A manager's reason is for who asked, as a decline's is.
      sent := app_private.notify_rows(w, actor, (
        select coalesce(jsonb_agg(jsonb_build_object('type', 'shift_changes.closed', 'user_id', app_private.shift_exchange_user(w, x.employee_id),
          'event_key', key || ':closed', 'title', 'A manager closed the request for ' || whose,
          'body', coalesce(nullif(btrim(coalesce(x.reason, '')), ''), day || '. Your schedule has not changed.'),
          'url', hub, 'subject_type', 'shift_exchange_case', 'subject_id', cid, 'data', facts)), '[]'::jsonb)
        from public.shift_exchange_applications x where x.case_id = cid and x.status = 'closed_case_cancelled'))
        + app_private.notify('shift_changes.closed', w, array[owner_user], key || ':closed', 'A manager closed your request',
        day || '. You are still responsible for this shift.', hub, actor, 'shift_exchange_case', cid, facts);
    end if;
    perform app_private.shift_exchange_resolve(w, cid, null, 'cancelled', actor);
    return sent;

  elsif act in ('expired', 'invalidated') and aid is not null then
    -- One acceptance ended (refresh_weekly_exchange_terms: the new hours overlap the teammate's other shift);
    -- the request stays open: only that teammate hears it, and only their cards close.
    sent := app_private.notify('shift_changes.closed', w, array[who_user], key || ':ended:' || aid::text,
      'Your request for ' || whose || ' ended',
      'The shift changed and now overlaps another of your shifts. Your schedule has not changed.',
      hub, actor, 'shift_exchange_case', cid, facts);
    perform app_private.shift_exchange_resolve(w, cid, null, 'shift_changed', actor, array[who_user]);
    if not exists (select 1 from public.shift_exchange_applications x where x.case_id = cid and x.status = 'pending_manager') then
      perform app_private.shift_exchange_resolve(w, cid, approvals, 'shift_changed', actor);
    end if;
    return sent;

  elsif act in ('expired', 'invalidated') then
    -- Everything closes 4 hours before the shift, and a changed shift ends it; everyone it held hears it
    -- (plan §4.1, §4.2).
    askers := array(select app_private.shift_exchange_user(w, x.employee_id) from public.shift_exchange_applications x
      where x.case_id = cid and x.status = act);
    sent := app_private.notify('shift_changes.closed', w, array[owner_user], key || ':closed', 'Your shift change request closed',
        case when act = 'expired' then 'It closed 4 hours before the shift. ' else 'The shift changed, so it ended. ' end
        || 'You are still responsible for this shift.', hub, actor, 'shift_exchange_case', cid, facts)
      + app_private.notify('shift_changes.closed', w, askers, key || ':closed', 'The request for ' || whose || ' closed',
        case when act = 'expired' then 'It closed 4 hours before the shift. ' else 'The shift changed, so it ended. ' end
        || 'Your schedule has not changed.', hub, actor, 'shift_exchange_case', cid, facts);
    perform app_private.shift_exchange_resolve(w, cid, null, case when act = 'expired' then 'expired' else 'shift_changed' end, actor);
    return sent;
  end if;
  return 0;
end;
$$;


