CREATE OR REPLACE FUNCTION "app_private"."time_off_decider_why"("state" "app_private"."actor_state", "person" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  decide_rule app_private.authz_actions;
  alone_rule app_private.authz_actions;
  why text;
  alone text;
  place uuid;
begin
  select * into decide_rule from app_private.authz_actions a where a.key = 'time_off.decide';
  select * into alone_rule from app_private.authz_actions a where a.key = 'time_off.decide_alone';
  why := app_private.authz_check(state, decide_rule, null, null, null);
  if why is not null and why <> 'out_of_scope' then
    return why;
  end if;
  if person is null then
    return null;
  end if;
  alone := app_private.authz_check(state, alone_rule, null, person, null);
  -- 'rank' is their own request (no_self): no location changes that.
  if alone is null or alone = 'rank' then
    return alone;
  end if;
  for place in
    select a.location_id
    from public.employee_location_assignments a
    join public.locations l on l.id = a.location_id and l.workspace_id = a.workspace_id
    where a.workspace_id = state.workspace_id and a.employee_id = person and a.ended_at is null
      and app_private.location_is_live(l)
    order by a.is_primary desc, a.location_id
  loop
    if app_private.authz_check(state, decide_rule, array[place], person, null) is null then
      return null;
    end if;
  end loop;
  return alone;
end;
$$;


ALTER FUNCTION "app_private"."time_off_decider_why"("state" "app_private"."actor_state", "person" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_entry_person"("state" "app_private"."actor_state", "person" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  why text := app_private.time_off_decider_why(state, null);
  account uuid;
  zone_name text;
begin
  if why is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || why, detail = 'time_off.decide';
  end if;
  select e.user_id into account from public.employee_profiles e
  where e.id = person and e.workspace_id = state.workspace_id and e.archived_at is null;
  if not found then
    -- Nobody by that id answers as somebody the actor may not add time off for (BL-354).
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'time_off.decide';
  end if;
  why := app_private.time_off_decider_why(state, person);
  if why is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || why, detail = 'time_off.decide';
  end if;
  if account is not null and not app_private.has_employee_access(state.workspace_id, account) then
    raise exception 'Time off is only for people who work shifts' using errcode = '22023', hint = 'time_off.no_employee_access';
  end if;
  zone_name := app_private.time_off_timezone(state.workspace_id, person);
  if zone_name is null then
    raise exception 'This person needs a location before they can have time off' using errcode = '55000', hint = 'time_off.no_location';
  end if;
  return zone_name;
end;
$$;


ALTER FUNCTION "app_private"."time_off_entry_person"("state" "app_private"."actor_state", "person" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_entry_range"("zone_name" "text", "first_day" "date", "last_day" "date", "from_clock" time without time zone, "to_clock" time without time zone) RETURNS "tstzrange"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  begins timestamptz;
  ends timestamptz;
begin
  if first_day is null or last_day is null or (from_clock is null) <> (to_clock is null) or from_clock = '24:00' then
    raise exception 'Choose the days, and both hours unless it is all day' using errcode = '22023', hint = 'time_off.invalid';
  end if;
  if last_day < first_day then
    raise exception 'The last day is before the first day' using errcode = '22023', hint = 'time_off.order';
  end if;
  if from_clock is null then
    if last_day - first_day + 1 > 31 then
      raise exception 'Enter 31 days or fewer at a time' using errcode = '22023', hint = 'time_off.too_long';
    end if;
    begins := first_day::timestamp at time zone zone_name;
    ends := (last_day + 1)::timestamp at time zone zone_name;
  else
    if last_day + to_clock <= first_day + from_clock then
      raise exception 'The end is before the start' using errcode = '22023', hint = 'time_off.order';
    end if;
    if (last_day + to_clock) - (first_day + from_clock) > interval '31 days' then
      raise exception 'Enter 31 days or fewer at a time' using errcode = '22023', hint = 'time_off.too_long';
    end if;
    begin
      -- A clock the zone repeats is its first time; one it skips does not exist.
      begins := public.time_off_resolve_clock(first_day + from_clock, zone_name, 'earlier');
      ends := public.time_off_resolve_clock(last_day + to_clock, zone_name, 'earlier');
    exception when sqlstate '22023' then
      raise exception 'These hours do not exist on this date in this time zone'
        using errcode = '22023', hint = 'time_off.no_such_time';
    end;
  end if;
  if first_day < (now() at time zone zone_name)::date or ends <= now() then
    raise exception 'That time has passed. Time off can start today at the earliest'
      using errcode = '22023', hint = 'time_off.past';
  end if;
  return tstzrange(begins, ends, '[)');
end;
$$;


ALTER FUNCTION "app_private"."time_off_entry_range"("zone_name" "text", "first_day" "date", "last_day" "date", "from_clock" time without time zone, "to_clock" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_impact_view"("state" "app_private"."actor_state", "at_stake" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with read_rule as (select a from app_private.authz_actions a where a.key = 'schedule.read'),
  seen as (
    select x, app_private.authz_check(time_off_impact_view.state, (select a from read_rule),
      array[(x ->> 'location_id')::uuid], null, null) is null as readable
    from jsonb_array_elements(time_off_impact_view.at_stake) x
  )
  select jsonb_build_object(
    'fingerprint', app_private.time_off_shifts_print(time_off_impact_view.at_stake),
    'shift_count', jsonb_array_length(time_off_impact_view.at_stake),
    'hidden_shift_count', (select count(*)::integer from seen where not seen.readable),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object('location_id', place.location_id, 'location_name', place.location_name,
        'shifts', place.shifts) order by place.location_name, place.location_id)
      from (
        select (s.x ->> 'location_id')::uuid as location_id, min(s.x ->> 'location_name') as location_name,
          jsonb_agg(jsonb_build_object(
            'id', s.x ->> 'id',
            'scheduled_date', s.x ->> 'scheduled_date',
            'start_time', to_char((s.x ->> 'start_time')::time, 'HH24:MI'),
            'end_time', to_char((s.x ->> 'end_time')::time, 'HH24:MI'),
            'job_name', s.x ->> 'job_name',
            'starts_at', s.x ->> 'starts_at',
            'ends_at', s.x ->> 'ends_at',
            'timezone', s.x ->> 'timezone') order by s.x ->> 'starts_at', s.x ->> 'id') as shifts
        from seen s
        where s.readable
        group by (s.x ->> 'location_id')::uuid
      ) place), '[]'::jsonb))
$$;


ALTER FUNCTION "app_private"."time_off_impact_view"("state" "app_private"."actor_state", "at_stake" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_open_shifts"("r" "public"."time_off_requests", "actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  s jsonb;
  changes jsonb := '[]';
  other record;
begin
  for s in select x from jsonb_array_elements(app_private.time_off_shifts_at_stake(r)) x loop
    insert into public.time_off_request_releases (workspace_id, request_id, published_shift_id, before_assignment, actor_user_id)
    values (r.workspace_id, r.id, (s ->> 'id')::uuid, s, actor);
    update public.schedule_published_shifts set employee_id = null
    where workspace_id = r.workspace_id and id = (s ->> 'id')::uuid and employee_id = r.employee_id;
    if not found then
      raise exception 'A published shift changed before it could be opened. Review it again'
        using errcode = 'PT409', hint = 'time_off.changed';
    end if;
    changes := changes || jsonb_build_array(s || jsonb_build_object('new_employee_id', null));
  end loop;
  if jsonb_array_length(changes) > 0 then
    perform public.shift_exchange_reconcile_batch(actor, r.workspace_id, changes);
    for other in select c.id from public.shift_exchange_cases c where c.workspace_id = r.workspace_id and c.status = 'open'
     and exists (select 1 from jsonb_array_elements(changes) x where (x ->> 'source_id')::uuid in (c.offered_source_id, c.requested_source_id)) loop
      update public.shift_exchange_cases set status = 'invalidated', revision = revision + 1, updated_at = now() where id = other.id;
      update public.shift_exchange_applications set status = 'invalidated', updated_at = now()
      where case_id = other.id and status in ('invited', 'pending_manager');
      perform public.shift_exchange_emit(actor, r.workspace_id, other.id, null, 'invalidated',
        'An involved assignment was released with approved time off. Review the current schedule.');
    end loop;
    perform realtime.send(jsonb_build_object('workspace_id', r.workspace_id, 'request_id', r.id), 'changed',
      'shift-exchanges:' || r.workspace_id::text, true);
  end if;
  return changes;
end;
$$;


ALTER FUNCTION "app_private"."time_off_open_shifts"("r" "public"."time_off_requests", "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_reason"("actor" "uuid", "w" "uuid", "action" "text", "person" "uuid" DEFAULT NULL::"uuid", "place" "uuid" DEFAULT NULL::"uuid", "documents_aside" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  state app_private.actor_state := app_private.actor(actor, w);
  rule_row app_private.authz_actions;
  why text;
begin
  select * into rule_row from app_private.authz_actions a where a.key = action;
  if not found then
    raise exception 'Unknown action %', action using errcode = '22023';
  end if;
  -- documents_aside: whether somebody could act once a missing document is in (a passing restriction).
  if state.class = 'owner' or documents_aside then
    state.document_blocked := false;
  end if;
  why := app_private.authz_check(state, rule_row, case when place is null then null else array[place] end, person, null);
  if why = 'rank' and action in ('time_off.decide_alone', 'requests.read') and state.class = 'owner'
     and exists (select 1 from public.employee_profiles e where e.id = person and e.workspace_id = w and e.user_id = actor)
     and app_private.decision_tier(w, person, null, null, 'time_off.decide_alone') = 'self_only'
     and not exists (select 1 from public.employee_location_assignments a
                     join public.locations l on l.id = a.location_id and l.workspace_id = a.workspace_id
                     where a.workspace_id = w and a.employee_id = person and a.ended_at is null
                       and app_private.location_is_live(l)
                       and app_private.decision_tier(w, person, a.location_id, null, 'time_off.decide') <> 'self_only') then
    return null;
  end if;
  return why;
end;
$$;


ALTER FUNCTION "app_private"."time_off_reason"("actor" "uuid", "w" "uuid", "action" "text", "person" "uuid", "place" "uuid", "documents_aside" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_request_tell"("r" "public"."time_off_requests", "what" "text", "actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  person public.employee_profiles%rowtype;
  name text;
  days text := app_private.time_off_days_label(r);
  card_url text := '/app/schedule/requests?type=time_off&request=' || r.id::text;
  mine_url text := '/app/employee-hub/my-availability?section=time-off';
  asked uuid[];
  opened integer;
  sent integer := 0;
begin
  select * into person from public.employee_profiles e where e.id = r.employee_id and e.workspace_id = r.workspace_id;
  name := btrim(coalesce(nullif(btrim(person.preferred_name), ''), person.first_name) || ' ' || person.last_name);
  if what = 'requested' or (r.kind = 'leave' and what in ('approved', 'revoked', 'entered', 'reminder')) then
    asked := app_private.notify_deciders(r.workspace_id, 'time_off.decide', array(
      select a.location_id
      from public.employee_location_assignments a
      join public.locations l on l.id = a.location_id and l.workspace_id = a.workspace_id
      where a.workspace_id = r.workspace_id and a.employee_id = r.employee_id and a.ended_at is null
        and app_private.location_is_live(l)
      order by a.location_id), r.employee_id, 'time_off.decide_alone');
  end if;

  if r.kind = 'cancel' then
    if what = 'requested' then
      sent := app_private.notify('time_off.requested', r.workspace_id, asked,
        'time_off:' || r.id::text || ':requested', name || ' asks to cancel time off',
        days || coalesce(' · ' || left(r.note, 900), ''), card_url, actor, 'time_off', r.id,
        jsonb_build_object('request_id', r.id, 'kind', 'cancel', 'cancels_id', r.cancels_id, 'kind_of_leave', r.kind_of_leave));
      return sent;
    end if;
    if what in ('approved', 'declined') then
      sent := app_private.notify('time_off.decided', r.workspace_id, array[person.user_id],
        'time_off:' || r.id::text || ':' || what,
        case what when 'approved' then 'Your time off ' || days || ' is cancelled'
          else 'Your request to cancel time off ' || days || ' is declined' end,
        r.decision_note, mine_url, actor, 'time_off', r.id,
        jsonb_build_object('request_id', r.id, 'kind', 'cancel', 'cancels_id', r.cancels_id, 'outcome', what));
    end if;
    perform app_private.notification_resolve(r.workspace_id, 'time_off', r.id, what, actor);
    return sent;
  end if;

  if what = 'requested' then
    return app_private.notify('time_off.requested', r.workspace_id, asked,
      'time_off:' || r.id::text || ':requested', 'Time off request from ' || name,
      days || coalesce(' · ' || left(r.note, 900), ''), card_url, actor, 'time_off', r.id,
      jsonb_build_object('request_id', r.id, 'kind_of_leave', r.kind_of_leave));
  end if;

  -- A day before it starts, still waiting (D6): whoever would be asked now; nothing closes.
  if what = 'reminder' then
    return app_private.notify('time_off.decision_reminder', r.workspace_id, asked,
      'time_off:' || r.id::text || ':reminder', 'Time off request from ' || name || ' still waits',
      days || ' · It starts in less than a day. Answer it before it starts.', card_url, null, 'time_off', r.id,
      jsonb_build_object('request_id', r.id, 'kind_of_leave', r.kind_of_leave));
  end if;

  -- Entered for the person (D5): approved at once; nobody was asked, so no card closes.
  if what = 'entered' then
    opened := (select count(*)::integer from public.time_off_request_releases x
               where x.workspace_id = r.workspace_id and x.request_id = r.id);
    sent := app_private.notify('time_off.decided', r.workspace_id, array[person.user_id],
      'time_off:' || r.id::text || ':entered', 'Time off ' || days || ' was added for you',
      r.note, mine_url, actor, 'time_off', r.id,
      jsonb_build_object('request_id', r.id, 'outcome', 'approved', 'entered', true, 'shifts_opened', opened));
    sent := sent + app_private.notify('time_off.decided', r.workspace_id,
      array(select u from unnest(asked) u where u is distinct from actor and u is distinct from person.user_id),
      'time_off:' || r.id::text || ':entered', name || '''s time off ' || days || ' was added',
      case when opened = 1 then '1 shift went to open shifts.' when opened > 1 then opened || ' shifts went to open shifts.' end,
      card_url, actor, 'time_off', r.id,
      jsonb_build_object('request_id', r.id, 'outcome', 'approved', 'entered', true, 'shifts_opened', opened));
    return sent;
  end if;

  if what in ('approved', 'declined') then
    opened := (select count(*)::integer from public.time_off_request_releases x
               where x.workspace_id = r.workspace_id and x.request_id = r.id);
    sent := app_private.notify('time_off.decided', r.workspace_id, array[person.user_id],
      'time_off:' || r.id::text || ':' || what,
      'Your time off ' || days || case what when 'approved' then ' is approved' else ' is declined' end,
      r.decision_note, mine_url, actor, 'time_off', r.id,
      jsonb_build_object('request_id', r.id, 'outcome', what, 'shifts_opened', opened));
    if what = 'approved' then
      sent := sent + app_private.notify('time_off.decided', r.workspace_id,
        array(select u from unnest(asked) u where u is distinct from actor and u is distinct from person.user_id),
        'time_off:' || r.id::text || ':approved', name || '''s time off ' || days || ' is approved',
        case when opened = 1 then '1 shift went to open shifts.' when opened > 1 then opened || ' shifts went to open shifts.' end,
        card_url, actor, 'time_off', r.id,
        jsonb_build_object('request_id', r.id, 'outcome', what, 'shifts_opened', opened));
    end if;
  end if;

  -- Nobody answered before it started (D6): the employee hears it, as the old system's "wasn't decided in time".
  if what = 'expired' then
    sent := app_private.notify('time_off.decided', r.workspace_id, array[person.user_id],
      'time_off:' || r.id::text || ':expired', 'Your time off ' || days || ' wasn''t answered in time',
      'Nobody answered it before it started.', mine_url, null, 'time_off', r.id,
      jsonb_build_object('request_id', r.id, 'outcome', 'expired'));
  end if;

  if what = 'revoked' then
    sent := app_private.notify('time_off.decided', r.workspace_id, array[person.user_id],
      'time_off:' || r.id::text || ':revoked', 'Your time off ' || days || ' was revoked',
      r.ended_note, mine_url, actor, 'time_off', r.id,
      jsonb_build_object('request_id', r.id, 'outcome', what));
    sent := sent + app_private.notify('time_off.decided', r.workspace_id,
      array(select u from unnest(asked) u where u is distinct from actor and u is distinct from person.user_id),
      'time_off:' || r.id::text || ':revoked', name || '''s time off ' || days || ' was revoked',
      r.ended_note, card_url, actor, 'time_off', r.id,
      jsonb_build_object('request_id', r.id, 'outcome', what));
  end if;
  perform app_private.notification_resolve(r.workspace_id, 'time_off', r.id, what, actor);
  return sent;
end;
$$;


ALTER FUNCTION "app_private"."time_off_request_tell"("r" "public"."time_off_requests", "what" "text", "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_request_view"("r" "public"."time_off_requests") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', r.id,
    'kind', r.kind,
    'cancels_id', r.cancels_id,
    'kind_of_leave', r.kind_of_leave,
    'status', case when r.status = 'pending' and r.kind = 'leave' and r.starts_at <= now() then 'expired'
      when r.status = 'pending' and r.kind = 'cancel' and r.ends_at <= now() then 'expired'
      else r.status end,
    'starts_at', r.starts_at,
    'ends_at', r.ends_at,
    'all_day', r.all_day,
    'time_timezone', r.time_timezone,
    'start_date', (r.starts_at at time zone r.time_timezone)::date,
    'end_date', case when r.all_day or (r.ends_at at time zone r.time_timezone)::time = '00:00'
      then (r.ends_at at time zone r.time_timezone)::date - 1 else (r.ends_at at time zone r.time_timezone)::date end,
    'start_time', case when r.all_day then null else to_char(r.starts_at at time zone r.time_timezone, 'HH24:MI') end,
    'end_time', case when r.all_day then null
      when (r.ends_at at time zone r.time_timezone)::time = '00:00' then '24:00'
      else to_char(r.ends_at at time zone r.time_timezone, 'HH24:MI') end,
    'note', r.note,
    'revision', r.revision,
    'created_at', r.created_at,
    'added_by_name', case when r.kind = 'leave' and r.created_by is distinct from
      (select e.user_id from public.employee_profiles e where e.id = r.employee_id and e.workspace_id = r.workspace_id)
      then app_private.account_name(r.created_by) end,
    'decided_at', r.decided_at,
    'decided_by_name', case when r.decided_by is null then null else app_private.account_name(r.decided_by) end,
    'decision_note', r.decision_note,
    'ended_at', r.ended_at,
    'ended_by_name', case when r.ended_by is null then null else app_private.account_name(r.ended_by) end,
    'ended_note', r.ended_note,
    'used_until', case when r.kind = 'leave' and r.status in ('cancelled', 'revoked') and not isempty(r.effective)
      then upper(r.effective) end,
    'cancellation', (
      select jsonb_build_object(
        'id', c.id,
        'status', case when c.status = 'pending' and c.ends_at <= now() then 'expired' else c.status end,
        'note', c.note,
        'revision', c.revision,
        'created_at', c.created_at,
        'decided_at', c.decided_at,
        'decided_by_name', case when c.decided_by is null then null else app_private.account_name(c.decided_by) end,
        'decision_note', c.decision_note)
      from public.time_off_requests c
      where r.kind = 'leave' and c.cancels_id = r.id and c.workspace_id = r.workspace_id and c.kind = 'cancel'
        and c.status <> 'withdrawn'
      order by c.status = 'pending' desc, c.created_at desc, c.id desc
      limit 1))
$$;


ALTER FUNCTION "app_private"."time_off_request_view"("r" "public"."time_off_requests") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_requests_sweep"("pass_limit" integer DEFAULT 500, "pass_time" interval DEFAULT '00:00:30'::interval) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  started timestamptz := clock_timestamp();
  due record;
  r public.time_off_requests;
  done integer := 0;
begin
  for due in
    select q.id, q.workspace_id
    from public.time_off_requests q
    where q.status = 'pending'
      and ((q.kind = 'leave' and (q.starts_at <= now()
             or (q.reminded_at is null and q.starts_at - interval '1 day' <= now()
                 and q.created_at < q.starts_at - interval '1 day')))
        or (q.kind = 'cancel' and q.ends_at <= now()))
    -- One that failed before waits behind the rest, so broken requests never fill a pass (nf-guvenlik, D7).
    order by exists (select 1 from app_private.time_off_request_sweep_failures f where f.request_id = q.id),
             case when q.kind = 'cancel' then q.ends_at when q.starts_at <= now() then q.starts_at
                  else q.starts_at - interval '1 day' end, q.id
    limit pass_limit
  loop
    -- Each request on its own: one that fails is rolled back alone and kept; the rest of the pass goes on.
    begin
      -- Read again under its row lock: an answer or a withdrawal may have closed it. One that somebody holds
      -- now is left for the next pass.
      select * into r from public.time_off_requests q where q.id = due.id and q.status = 'pending'
      for update skip locked;
      if found then
        if (r.kind = 'leave' and r.starts_at <= now()) or (r.kind = 'cancel' and r.ends_at <= now()) then
          update public.time_off_requests
          set status = 'expired', ended_at = case when r.kind = 'cancel' then r.ends_at else r.starts_at end,
              revision = revision + 1, updated_at = now()
          where id = r.id
          returning * into r;
          perform app_private.time_off_request_tell(r, 'expired', null);
          done := done + 1;
        elsif r.kind = 'leave' and r.reminded_at is null and r.starts_at - interval '1 day' <= now()
              and r.created_at < r.starts_at - interval '1 day' then
          update public.time_off_requests set reminded_at = now() where id = r.id returning * into r;
          perform app_private.time_off_request_tell(r, 'reminder', null);
          done := done + 1;
        end if;
        delete from app_private.time_off_request_sweep_failures f where f.request_id = r.id;
      end if;
    exception when others then
      insert into app_private.time_off_request_sweep_failures (request_id, workspace_id, sqlstate, message)
      values (due.id, due.workspace_id, sqlstate, sqlerrm)
      on conflict (request_id) do update
      set last_failed_at = now(), attempts = app_private.time_off_request_sweep_failures.attempts + 1,
          sqlstate = excluded.sqlstate, message = excluded.message;
      raise warning 'time-off-requests: request % of workspace % failed: % %', due.id, due.workspace_id, sqlstate, sqlerrm;
    end;
    -- Out of time: the request in hand is done; the rest wait for the next pass.
    exit when clock_timestamp() - started >= pass_time;
  end loop;
  return done;
end;
$$;


ALTER FUNCTION "app_private"."time_off_requests_sweep"("pass_limit" integer, "pass_time" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_shifts_at_stake"("r" "public"."time_off_requests") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
