  select coalesce(jsonb_agg(x order by x ->> 'starts_at', x ->> 'id'), '[]'::jsonb)
  from jsonb_array_elements(public.time_off_assignment_impact(r.workspace_id, r.employee_id,
    tstzmultirange(tstzrange(r.starts_at, r.ends_at, '[)')))) x
