    AS $$
  select exists (
    select 1
    from public.workspace_ownership_transfers transfer
    where transfer.status = 'pending'
      and (
        transfer.initiated_by = actor_user_id
        or transfer.target_user_id = actor_user_id
      )
  );
$$;


