CREATE OR REPLACE FUNCTION "app_private"."weekly_preference_may_write"("actor" "uuid", "w" "uuid", "source" "text", "model" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if source is null or source not in ('employee','manager') then raise exception 'Choose whose week to save' using errcode='22023'; end if;
 if not coalesce((model->>case when source='employee' then 'can_edit_employee' else 'can_manage' end)::boolean,false) then
  -- The core says why.
  perform app_private.authorize(actor,w,case when source='employee' then 'availability.own' else 'availability.team_write' end,
   target_person=>(model->>'employee_id')::uuid);
  raise exception 'Not allowed' using errcode='42501',hint='authz.out_of_scope',detail='availability';
 end if;
end;
$$;


ALTER FUNCTION "app_private"."weekly_preference_may_write"("actor" "uuid", "w" "uuid", "source" "text", "model" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."workspace_allows_interactive_access"("target_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.workspaces workspace
    where workspace.id = target_workspace_id
      and (
        workspace.lifecycle_status = 'active'
        or (
          workspace.lifecycle_status = 'closure_scheduled'
          and workspace.closure_effective_at > now()
        )
        or (
          workspace.lifecycle_status = 'draft'
          and current_setting('app.allow_incomplete_workspace_context', true) = 'on'
        )
      )
  );
$$;


