    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select w.name from public.workspaces w where w.id = target_workspace
$$;


ALTER FUNCTION "app_private"."workspace_name"("target_workspace" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."workspace_open_to_actor"("target_workspace_id" "uuid", "actor_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.workspace_allows_interactive_access(target_workspace_id)
    or exists (
      select 1
      from public.workspaces workspace
      join public.workspace_memberships membership
        on membership.workspace_id = workspace.id
      join public.workspace_roles role
        on role.id = membership.role_id and role.workspace_id = membership.workspace_id
      where workspace.id = target_workspace_id
        and workspace.lifecycle_status = 'draft'
        and membership.user_id = actor_user_id
        and membership.status = 'active'
        and role.access_class = 'owner'
    );
$$;


ALTER FUNCTION "app_private"."workspace_open_to_actor"("target_workspace_id" "uuid", "actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."workspace_role_for"("target_workspace_id" "uuid") RETURNS "public"."workspace_role"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- The management slot's class, else employee (ROL-CIFT).
  select coalesce(role.access_class, 'employee'::public.workspace_role)
  from public.workspace_memberships membership
  left join public.workspace_roles role
    on role.id = membership.role_id and role.workspace_id = membership.workspace_id
  where membership.workspace_id = target_workspace_id
    and membership.user_id = (select auth.uid())
    and membership.status = 'active'
    and not app_private.document_actor_blocked((select auth.uid()), target_workspace_id)
    and app_private.workspace_open_to_actor(target_workspace_id, (select auth.uid()))
  limit 1;
$$;


ALTER FUNCTION "app_private"."workspace_role_for"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."workspace_todos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "body" "text" DEFAULT ''::"text" NOT NULL,
    "severity" "public"."workspace_todo_severity" DEFAULT 'info'::"public"."workspace_todo_severity" NOT NULL,
    "status" "public"."workspace_todo_status" DEFAULT 'open'::"public"."workspace_todo_status" NOT NULL,
    "system_generated" boolean DEFAULT true NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "source_key" "text" NOT NULL,
    "employee_id" "uuid",
    "due_at" timestamp with time zone,
    "action_url" "text",
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workspace_todos_action_url_check" CHECK ((("action_url" IS NULL) OR (("char_length"("action_url") <= 500) AND ("action_url" ~ '^/app(/|$)'::"text")))),
    CONSTRAINT "workspace_todos_body_check" CHECK (("char_length"("body") <= 1000)),
    CONSTRAINT "workspace_todos_check" CHECK ((("status" = 'resolved'::"public"."workspace_todo_status") = ("resolved_at" IS NOT NULL))),
    CONSTRAINT "workspace_todos_source_key_check" CHECK ((("char_length"("btrim"("source_key")) >= 1) AND ("char_length"("btrim"("source_key")) <= 160))),
    CONSTRAINT "workspace_todos_source_type_check" CHECK ((("char_length"("btrim"("source_type")) >= 1) AND ("char_length"("btrim"("source_type")) <= 80))),
    CONSTRAINT "workspace_todos_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 160)))
);


ALTER TABLE "public"."workspace_todos" OWNER TO "postgres";


