    SET "search_path" TO ''
    AS $$
begin
 delete from public.schedule_export_presets where id=target_preset_id and workspace_id=target_workspace_id and created_by=actor_user_id;
 if not found then raise exception 'schedule export preset not found' using errcode='P0002'; end if;
 return jsonb_build_object('status','deleted','preset_id',target_preset_id);
end; $$;


ALTER FUNCTION "public"."delete_schedule_export_preset_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_preset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_schedule_export_schedule_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_schedule_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing public.scheduled_schedule_exports%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
    target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.export'));

  select * into existing
    from public.scheduled_schedule_exports s
   where s.id = target_schedule_id
     and s.workspace_id = target_workspace_id
   for update;

  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
    target_locations => public.live_location_ids(target_workspace_id, existing.location_ids));

  if existing.id is null then
    raise exception 'scheduled export not found' using errcode='P0002';
  end if;

  delete from public.scheduled_schedule_exports
   where id = target_schedule_id
     and workspace_id = target_workspace_id;

  return jsonb_build_object('status', 'deleted', 'schedule_id', target_schedule_id);
end;
$$;


ALTER FUNCTION "public"."delete_schedule_export_schedule_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_schedule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare old_name text;
begin
 perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.templates', target_locations => case
   when not exists (select 1 from public.schedule_templates t where t.id = target_template_id and t.workspace_id = target_workspace_id) then null
   else public.live_location_ids(target_workspace_id, array(select distinct s.location_id from public.schedule_template_shifts s
     where s.template_id = target_template_id and s.workspace_id = target_workspace_id))
 end);
 delete from public.schedule_templates where id=target_template_id and workspace_id=target_workspace_id and revision=expected_revision returning name into old_name;
 if old_name is null then raise exception 'schedule template revision stale' using errcode = 'PT409', hint = 'schedule.template_changed'; end if;
 insert into public.schedule_template_events(workspace_id,template_id,template_name,action,actor_user_id) values(target_workspace_id,target_template_id,old_name,'deleted',actor_user_id);
 return jsonb_build_object('status','deleted','template_id',target_template_id);
end;
$$;


ALTER FUNCTION "public"."delete_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_workspace_role_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_role_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target public.workspace_roles;
begin
 perform pg_advisory_xact_lock(hashtextextended('roles:'||target_workspace_id::text,0));
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.roles.write');
 if not app_private.can_edit_role(actor_user_id,target_workspace_id,target_role_id) then raise exception 'role management access denied' using errcode='42501',hint=case when not exists(select 1 from public.workspace_roles r where r.id=target_role_id and r.workspace_id=target_workspace_id) then 'authz.out_of_scope' else 'authz.rank' end; end if;
 select * into target from public.workspace_roles where id=target_role_id and workspace_id=target_workspace_id for update;
 if target.system_key is not null then raise exception 'Built-in roles cannot be deleted' using errcode='42501'; end if;
 if exists(select 1 from public.workspace_memberships where role_id=target_role_id) or exists(select 1 from public.employee_invitations where target_role_id in (employee_role_id, management_role_id)) or exists(select 1 from public.employee_access_snapshots where role_id=target_role_id) then raise exception 'Role has member or invitation references. Resolve these dependencies before deleting.' using errcode='PT409',hint='role.in_use'; end if;
 delete from public.workspace_roles where id=target_role_id;
 insert into public.audit_events(workspace_id,actor_user_id,action,target_type,target_id,metadata) values(target_workspace_id,actor_user_id,'role.deleted','workspace_role',target_role_id::text,jsonb_build_object('name',target.name));
end; $$;


ALTER FUNCTION "public"."delete_workspace_role_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_role_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discard_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform public.availability_lock_workspace(target_workspace_id);
  -- The edit's locations are still the person's to edit (B-3).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => session.location_ids)
  from public.schedule_edit_sessions session
  where session.id = target_session_id and session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id and session.status = 'active';
  delete from public.schedule_edit_session_shifts shift
  using public.schedule_edit_sessions session
  where session.id = target_session_id and session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id and session.status = 'active'
    and shift.session_id = session.id;
  update public.schedule_edit_sessions session
  set status = 'discarded', dirty = false, closed_at = now(), expires_at = now()
  where session.id = target_session_id and session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id and session.status = 'active';
  if not found then
    raise exception 'edit session not found' using errcode = 'P0002';
  end if;
  return jsonb_build_object('status', 'discarded');
end;
$$;


ALTER FUNCTION "public"."discard_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_definition_target_options_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 select jsonb_build_object(
  'locations',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'name',l.name) order by l.name) from public.locations l where l.workspace_id=target_workspace_id and app_private.location_is_live(l)),'[]'),
  'departments',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'name',d.name) order by lower(d.name),d.id) from public.departments d where d.workspace_id=target_workspace_id and d.archived_at is null),'[]'),
  'jobs',coalesce((select jsonb_agg(jsonb_build_object('id',j.id,'name',j.name,'department_id',j.department_id) order by lower(j.name),j.id) from public.jobs j where j.workspace_id=target_workspace_id and j.archived_at is null),'[]'),
  'employees',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'name',concat_ws(' ',e.first_name,e.last_name)) order by e.first_name,e.last_name) from public.employee_profiles e where e.workspace_id=target_workspace_id and e.archived_at is null),'[]')
 ) into result;
 return result;
end;
$$;


ALTER FUNCTION "public"."document_definition_target_options_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."documents_maintain_service"("target_batch_size" integer DEFAULT 100, "at_time" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.employee_onboarding_cases%rowtype; checked integer:=0; suspended integer;
begin
 if target_batch_size not between 1 and 500 or at_time is null then raise exception 'valid maintenance batch required' using errcode='22023'; end if;
 -- The restriction first, for every case and on its own.
 suspended:=app_private.document_suspend_overdue();
 -- A batch of cases at a time, oldest checked first.
 for c in select oc.* from public.employee_onboarding_cases oc
  join public.employee_profiles p on p.id=oc.employee_id and p.workspace_id=oc.workspace_id and p.archived_at is null
  join public.workspace_memberships m on m.id=oc.membership_id and m.user_id=p.user_id and m.status in ('active','pending_activation')
  where app_private.workspace_allows_interactive_access(oc.workspace_id)
   and exists(select 1 from public.employee_onboarding_requirements q where q.case_id=oc.id and q.kind in ('document','acknowledgement') and q.lifecycle_retired_at is null)
  order by oc.document_notification_checked_at nulls first,oc.id limit target_batch_size for update of oc skip locked loop
  checked:=checked+1;
  update public.employee_onboarding_cases set document_notification_checked_at=at_time where id=c.id;
  -- Its notices (document_check_case); a case that fails is named and the batch goes on.
  -- ponytail: one subtransaction per case; past 64 in one transaction Postgres keeps their ids beside the
  -- cache, a little slower, never wrong. The cron sends 100; drop it below 64 if a check ever shows it.
  begin
   perform app_private.document_check_case(c.id, at_time);
  exception when others then
   raise warning 'documents_maintain_service: case % skipped: % (%)', c.id, sqlerrm, sqlstate;
  end;
 end loop;
 return jsonb_build_object('checked',checked,'suspended',suspended);
end;
$$;


ALTER FUNCTION "public"."documents_maintain_service"("target_batch_size" integer, "at_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_has_hard_document_schedule_conflict_service"("target_workspace_id" "uuid", "target_employee_id" "uuid", "target_scheduled_date" "date") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with active_document_requirements as (
    select distinct on (requirement.source_id)
      requirement.id as requirement_id
    from public.employee_onboarding_requirements requirement
    join public.document_types document_type
      on document_type.id = requirement.source_id
     and document_type.workspace_id = requirement.workspace_id
    where requirement.workspace_id = target_workspace_id
      and requirement.employee_id = target_employee_id
      and requirement.kind = 'document'::public.employee_onboarding_requirement_kind
      and requirement.status <> 'superseded'::public.employee_onboarding_requirement_status
      and document_type.archived_at is null
      and document_type.required_at_onboarding
      and document_type.tracks_expiry
      and document_type.expiry_schedule_impact = 'block'
    order by requirement.source_id, requirement.created_at desc, requirement.id
  ),
  latest_accepted_documents as (
    select distinct on (document.requirement_id)
      document.requirement_id,
      document.expiry_date
    from public.employee_documents document
    join active_document_requirements requirement
      on requirement.requirement_id = document.requirement_id
    where document.workspace_id = target_workspace_id
      and document.employee_id = target_employee_id
      and document.review_status = 'accepted'::public.employee_document_review_status
    order by document.requirement_id, document.version_number desc, document.id
  )
  select exists (
    select 1
    from latest_accepted_documents document
    where document.expiry_date is not null
      and document.expiry_date < target_scheduled_date
  );
$$;


ALTER FUNCTION "public"."employee_has_hard_document_schedule_conflict_service"("target_workspace_id" "uuid", "target_employee_id" "uuid", "target_scheduled_date" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."employee_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "user_id" "uuid",
    "employee_code" "text" NOT NULL,
    "first_name" "text" NOT NULL,
    "last_name" "text" NOT NULL,
    "preferred_name" "text" DEFAULT ''::"text" NOT NULL,
    "invitation_email" "text",
    "start_date" "date",
    "internal_note" "text" DEFAULT ''::"text" NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_remote" boolean DEFAULT false NOT NULL,
    "is_excluded_from_schedule" boolean DEFAULT false NOT NULL,
    "document_timezone" "text",
    "middle_name" "text" DEFAULT ''::"text" NOT NULL,
    CONSTRAINT "employee_profiles_employee_code_check" CHECK (("employee_code" ~ '^E-[0-9]{4,}$'::"text")),
    CONSTRAINT "employee_profiles_first_name_check" CHECK ((("char_length"("btrim"("first_name")) >= 1) AND ("char_length"("btrim"("first_name")) <= 80))),
    CONSTRAINT "employee_profiles_first_name_us_letters" CHECK ((NORMALIZE("first_name", NFC) !~ '[şŞğĞıİ]'::"text")),
    CONSTRAINT "employee_profiles_internal_note_check" CHECK (("char_length"("internal_note") <= 1000)),
    CONSTRAINT "employee_profiles_invitation_email_check" CHECK ((("invitation_email" IS NULL) OR ("invitation_email" = "lower"("btrim"("invitation_email"))))),
    CONSTRAINT "employee_profiles_last_name_check" CHECK ((("char_length"("btrim"("last_name")) >= 1) AND ("char_length"("btrim"("last_name")) <= 80))),
    CONSTRAINT "employee_profiles_last_name_us_letters" CHECK ((NORMALIZE("last_name", NFC) !~ '[şŞğĞıİ]'::"text")),
    CONSTRAINT "employee_profiles_middle_name_check" CHECK (("char_length"("middle_name") <= 80)),
    CONSTRAINT "employee_profiles_middle_name_us_letters" CHECK ((NORMALIZE("middle_name", NFC) !~ '[şŞğĞıİ]'::"text")),
    CONSTRAINT "employee_profiles_preferred_name_check" CHECK (("char_length"("preferred_name") <= 80)),
    CONSTRAINT "employee_profiles_preferred_name_us_letters" CHECK ((NORMALIZE("preferred_name", NFC) !~ '[şŞğĞıİ]'::"text")),
    CONSTRAINT "employee_profiles_revision_check" CHECK (("revision" > 0))
);


ALTER TABLE "public"."employee_profiles" OWNER TO "postgres";


COMMENT ON COLUMN "public"."employee_profiles"."middle_name" IS 'Optional. Empty string when the person has none or has not given one.';



CREATE OR REPLACE FUNCTION "public"."employee_hub_actor_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "public"."employee_profiles"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  employee public.employee_profiles%rowtype;
begin
  if me.membership_id is null then
    raise exception 'active employee membership required' using errcode = '42501', hint = 'authz.not_member';
  end if;
  if me.status <> 'active' then
    raise exception 'active employee membership required' using errcode = '42501', hint = 'authz.not_active';
  end if;
  if not me.workspace_open then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.workspace_closed';
  end if;
  -- The hub is the employee access's (ROL-CIFT 6.2): the core's answer for an employee-side action
  -- without it. A missing document still opens the hub, as before.
  if not coalesce(me.has_employee, false) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee_hub.read';
  end if;
  select * into employee from public.employee_profiles profile
  where profile.workspace_id = target_workspace_id
    and profile.user_id = actor_user_id
    and profile.archived_at is null;
  -- A member with no employee record of their own has no hub here.
  if employee.id is null then
    raise exception 'employee profile required' using errcode = '42501', hint = 'authz.out_of_scope';
  end if;
  return employee;
end;
$$;


ALTER FUNCTION "public"."employee_hub_actor_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


