CREATE OR REPLACE FUNCTION "public"."finish_notification_email_service"("target_delivery" "uuid", "target_outcome" "text", "target_provider_id" "text", "target_error" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  found_row public.notification_deliveries;
begin
  if target_outcome is null or target_outcome not in ('sent', 'retry', 'dead') then
    raise exception 'an outcome is sent, retry or dead' using errcode = '22023', hint = 'notifications.outcome';
  end if;
  if target_error is not null and target_error !~ '^[a-z0-9_]{1,40}$' then
    raise exception 'an error is a short code' using errcode = '22023', hint = 'notifications.error_code';
  end if;
  if target_provider_id is not null and char_length(target_provider_id) not between 1 and 200 then
    raise exception 'a provider id is 1 to 200 characters' using errcode = '22023', hint = 'notifications.provider_id';
  end if;
  select * into found_row from public.notification_deliveries d where d.id = target_delivery and d.channel = 'email' for update;
  if not found then
    return null;
  end if;
  -- Only a row being sent is finished: a late answer never undoes what came after it.
  if found_row.status <> 'sending' then
    return found_row.status;
  end if;
  update public.notification_deliveries d set
    status = case target_outcome
      when 'sent' then 'sent'
      when 'dead' then 'dead'
      else case when d.attempts >= 5 then 'dead' else 'failed' end end,
    next_attempt_at = case when target_outcome = 'retry' and d.attempts < 5
      then now() + make_interval(mins => (2 ^ (d.attempts - 1))::integer) else now() end,
    provider_message_id = case when target_outcome = 'sent' then target_provider_id else d.provider_message_id end,
    sent_at = case when target_outcome = 'sent' then now() else d.sent_at end,
    last_error = case when target_outcome = 'sent' then null else target_error end,
    lease_expires_at = null,
    updated_at = now()
  where d.id = target_delivery
  returning d.status into found_row.status;
  return found_row.status;
end;
$_$;


ALTER FUNCTION "public"."finish_notification_email_service"("target_delivery" "uuid", "target_outcome" "text", "target_provider_id" "text", "target_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_notification_push_service"("target_delivery" "uuid", "target_results" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  found_row public.notification_deliveries;
  owner_user uuid;
  answer jsonb;
  waits boolean := false;
  too_large boolean := false;
  wait_for integer := 0;
  retry_code text;
  next_status text;
begin
  if jsonb_typeof(target_results) is distinct from 'array' or jsonb_array_length(target_results) > 10 then
    raise exception 'answers are a list of up to ten' using errcode = '22023', hint = 'notifications.push_results';
  end if;
  for answer in select value from jsonb_array_elements(target_results) loop
    if jsonb_typeof(answer) is distinct from 'object' or jsonb_typeof(answer -> 'subscription_id') is distinct from 'string'
       or (answer ->> 'subscription_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or (case coalesce(jsonb_typeof(answer -> 'retry_after'), 'null')
             when 'null' then false
             when 'number' then (answer ->> 'retry_after')::numeric not between 0 and 86400
             else true end) then
      raise exception 'answers are a list of up to ten' using errcode = '22023', hint = 'notifications.push_results';
    end if;
    if coalesce(answer ->> 'outcome', '') not in ('accepted', 'gone', 'refused', 'retry', 'too_large') then
      raise exception 'an outcome is accepted, gone, refused, retry or too_large' using errcode = '22023', hint = 'notifications.outcome';
    end if;
    if answer ->> 'code' is not null and answer ->> 'code' !~ '^[a-z0-9_]{1,40}$' then
      raise exception 'an error is a short code' using errcode = '22023', hint = 'notifications.error_code';
    end if;
  end loop;

  select * into found_row from public.notification_deliveries d where d.id = target_delivery and d.channel = 'push' for update;
  if not found then
    return null;
  end if;
  -- Only a row being sent is finished: a late answer never undoes what came after it.
  if found_row.status <> 'sending' then
    return found_row.status;
  end if;
  select n.user_id into owner_user from public.person_notifications n where n.id = found_row.notification_id;

  for answer in
    select a.value from jsonb_array_elements(target_results) a
    join public.notification_push_subscriptions s on s.id = (a.value ->> 'subscription_id')::uuid and s.user_id = owner_user
  loop
    case answer ->> 'outcome'
      when 'accepted' then
        insert into public.notification_push_sends (delivery_id, subscription_id) values (found_row.id, (answer ->> 'subscription_id')::uuid)
        on conflict do nothing;
        update public.notification_push_subscriptions set last_used_at = now() where id = (answer ->> 'subscription_id')::uuid;
      when 'gone' then
        update public.notification_push_subscriptions set revoked_at = now(), revoked_reason = 'gone'
        where id = (answer ->> 'subscription_id')::uuid and revoked_at is null;
      when 'retry' then
        waits := true;
        retry_code := coalesce(retry_code, answer ->> 'code');
        wait_for := greatest(wait_for, coalesce((answer ->> 'retry_after')::numeric, 0)::integer);
      when 'too_large' then
        too_large := true;
      else
        null;
    end case;
  end loop;

  if too_large then
    next_status := 'dead';
    update public.notification_deliveries set status = 'dead', last_error = 'payload_too_large', lease_expires_at = null,
      updated_at = now() where id = found_row.id;
  elsif waits and found_row.attempts < 5 then
    next_status := 'failed';
    update public.notification_deliveries set status = 'failed', last_error = coalesce(retry_code, 'retry'), lease_expires_at = null,
      next_attempt_at = now() + greatest(make_interval(mins => (2 ^ (found_row.attempts - 1))::integer),
                                         make_interval(secs => least(wait_for, 3600))),
      updated_at = now() where id = found_row.id;
  elsif exists (select 1 from public.notification_push_sends s where s.delivery_id = found_row.id) then
    next_status := 'sent';
    update public.notification_deliveries set status = 'sent', sent_at = now(), last_error = null, lease_expires_at = null,
      updated_at = now() where id = found_row.id;
  else
    next_status := 'dead';
    update public.notification_deliveries set status = 'dead',
      last_error = case when waits then 'retries_exhausted' else 'no_device_reached' end, lease_expires_at = null,
      updated_at = now() where id = found_row.id;
  end if;
  if next_status = 'dead' and not exists (select 1 from public.notification_push_sends s where s.delivery_id = found_row.id) then
    perform app_private.push_fallback_email(found_row.notification_id);
  end if;
  return next_status;
end;
$_$;


ALTER FUNCTION "public"."finish_notification_push_service"("target_delivery" "uuid", "target_results" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_account_deletion_blockers_service"("actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with blocker_rows as (
    select
      'active_membership'::text as kind,
      membership.workspace_id,
      workspace.name as workspace_name,
      role.name as role_name,
      (role.system_key = 'owner') as is_owner,
      null::uuid as transfer_id,
      null::text as transfer_direction
    from public.workspace_memberships membership
    join public.workspaces workspace on workspace.id = membership.workspace_id
    join public.workspace_roles role on role.id = coalesce(membership.role_id, membership.employee_role_id)
    where membership.user_id = actor_user_id
      and membership.status = 'active'
      and (
        workspace.lifecycle_status = 'active'
        or (
          workspace.lifecycle_status = 'closure_scheduled'
          and workspace.closure_effective_at > now()
        )
      )

    union all

    select
      'pending_ownership_transfer'::text,
      transfer.workspace_id,
      workspace.name,
      null::text,
      false,
      transfer.id,
      case
        when transfer.initiated_by = actor_user_id then 'outgoing'
        else 'incoming'
      end
    from public.workspace_ownership_transfers transfer
    join public.workspaces workspace on workspace.id = transfer.workspace_id
    where transfer.status = 'pending'
      and (
        transfer.initiated_by = actor_user_id
        or transfer.target_user_id = actor_user_id
      )
  )
  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'kind', kind,
        'workspace_id', workspace_id,
        'workspace_name', workspace_name,
        'role_name', role_name,
        'is_owner', is_owner,
        'transfer_id', transfer_id,
        'transfer_direction', transfer_direction
      ))
      order by workspace_name, kind, transfer_id
    ),
    '[]'::jsonb
  )
  from blocker_rows;
$$;


ALTER FUNCTION "public"."get_account_deletion_blockers_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_announcement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  w uuid := target_workspace_id;
  reader app_private.actor_state;
  item public.announcements;
  allowed boolean;
  seen uuid[];
begin
  perform app_private.authorize(actor_user_id, w, 'announcement.read');
  perform app_private.announcement_release(w);
  reader := app_private.actor(actor_user_id, w);
  select * into item from public.announcements where id = target_announcement_id and workspace_id = w;
  if item.id is null or not app_private.announcement_visible(reader, item) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'announcement.read';
  end if;
  allowed := app_private.announcement_reason(reader, app_private.announcement_places(item.id), item.created_by,
    app_private.announcement_dates(item)) is null;
  if not allowed then
    return app_private.announcement_item(reader, item, false);
  end if;
  seen := app_private.scope_set(actor_user_id, w, 'schedule.read');
  return app_private.announcement_item(reader, item, true) || jsonb_build_object(
    'people', coalesce((
      select jsonb_agg(app_private.announcement_person(w, person.user_id) order by person.user_id)
      from public.announcement_people person where person.announcement_id = item.id), '[]'::jsonb),
    'shift_choices', item.shift_choices,
    'reminders_left_today', app_private.announcement_reminders_left(item),
    'choices_saved_at', item.choices_saved_at,
    -- Whose shifts it changed, where the reader may read the Schedule (D1).
    'changes', coalesce((
      select jsonb_agg(app_private.announcement_change_item(change) order by change.scheduled_date, change.changed_at, change.id)
      from public.announcement_shift_changes change
      where change.announcement_id = item.id and change.location_id = any (seen)), '[]'::jsonb),
    'hidden_change_count', (select count(*) from public.announcement_shift_changes change
      where change.announcement_id = item.id and not change.location_id = any (seen)),
    'acknowledgements', coalesce((
      select jsonb_agg(app_private.announcement_person(w, who) || jsonb_build_object('acknowledged_at', ack.acknowledged_at)
        order by ack.acknowledged_at is not null, ack.acknowledged_at, who)
      from unnest(case when item.ask_ack and item.status = 'published'
                       then app_private.announcement_respondents(item) else '{}'::uuid[] end) who
      left join public.announcement_acknowledgements ack on ack.announcement_id = item.id and ack.user_id = who), '[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object('id', change.id, 'action', change.action, 'detail', change.detail,
        'changed_at', change.changed_at, 'actor_user_id', change.actor_user_id,
        'actor_name', coalesce(account.display_name, case when change.actor_user_id is null then null else 'Workspace member' end))
        order by change.changed_at desc, change.id)
      from public.announcement_changes change
      left join public.user_profiles account on account.user_id = change.actor_user_id
      where change.announcement_id = item.id), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."get_announcement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_announcements_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  w uuid := target_workspace_id;
  reader app_private.actor_state;
  writable uuid[];
  dates_writable uuid[];
  wide boolean;
  dates_wide boolean;
  manages boolean;
begin
  perform app_private.authorize(actor_user_id, w, 'announcement.read');
  perform app_private.announcement_release(w);
  reader := app_private.actor(actor_user_id, w);
  writable := app_private.scope_set(actor_user_id, w, 'announcement.write');
  dates_writable := app_private.scope_set(actor_user_id, w, 'important_date.write');
  wide := app_private.authz_reason(actor_user_id, w, 'announcement.write_wide') is null;
  dates_wide := app_private.authz_reason(actor_user_id, w, 'important_date.write_wide') is null;
  manages := wide or cardinality(writable) > 0;
  return jsonb_build_object(
    'workspace_id', w,
    'can_manage', manages,
    'can_write_dates', manages and (dates_wide or cardinality(dates_writable) > 0),
    'can_read_dates', app_private.authz_reason(actor_user_id, w, 'settings.important_dates.read') is null,
    'time_format', app_private.announcement_time_format(w),
    'locations', case when manages then coalesce((
      select jsonb_agg(jsonb_build_object('id', location.id, 'name', location.name, 'short_name', location.short_name,
        'timezone', location.timezone,
        'can_change_hours', dates_wide or location.id = any (dates_writable),
        'people_count', (select count(distinct person.user_id) from public.employee_location_assignments assignment
                         join public.employee_profiles person on person.id = assignment.employee_id and person.archived_at is null
                         join public.workspace_memberships membership
                           on membership.workspace_id = w and membership.user_id = person.user_id and membership.status = 'active'
                         -- Bug 35: whoever is writing never gets their own post.
                         where assignment.location_id = location.id and assignment.ended_at is null
                           and person.user_id <> actor_user_id))
        order by location.sort_order, location.name)
      from public.locations location
      where location.workspace_id = w and location.archived_at is null and (wide or location.id = any (writable))), '[]'::jsonb)
      else '[]'::jsonb end,
    'people', case when manages then coalesce((
      select jsonb_agg(app_private.announcement_person(w, membership.user_id) order by lower(coalesce(
        nullif(person.preferred_name, ''), person.first_name, account.display_name)), lower(person.last_name), membership.user_id)
      from public.workspace_memberships membership
      left join public.employee_profiles person
        on person.workspace_id = w and person.user_id = membership.user_id and person.archived_at is null
      left join public.user_profiles account on account.user_id = membership.user_id
      where membership.workspace_id = w and membership.status = 'active' and membership.user_id <> actor_user_id
        and (wide or app_private.announcement_places_of(w, '{}', array[membership.user_id]) <@ writable)), '[]'::jsonb)
      else '[]'::jsonb end,
    'departments', case when manages then coalesce((
      select jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) order by lower(d.name), d.id)
      from public.departments d where d.workspace_id = w and d.archived_at is null), '[]'::jsonb) else '[]'::jsonb end,
    'jobs', case when manages then coalesce((
      select jsonb_agg(jsonb_build_object('id', j.id, 'name', j.name, 'department_id', j.department_id) order by lower(j.name), j.id)
      from public.jobs j where j.workspace_id = w and j.archived_at is null), '[]'::jsonb) else '[]'::jsonb end,
    'announcements', coalesce((
      select jsonb_agg(app_private.announcement_item(reader, item, control.allowed)
        order by coalesce(item.published_at, item.publish_at, item.created_at) desc, item.id)
      from public.announcements item
      cross join lateral (select app_private.announcement_reason(reader, app_private.announcement_places(item.id),
        item.created_by, app_private.announcement_dates(item)) is null allowed) control
      where item.workspace_id = w
        and case when item.status = 'draft' then item.created_by = actor_user_id
                 else control.allowed or app_private.announcement_reaches(item, actor_user_id) end), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."get_announcements_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_detail_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state;
  reads_private boolean;
  reads_access boolean;
  removal app_private.authz_actions;
  invite_rule app_private.authz_actions;
  change_rule app_private.authz_actions;
  answer jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.read', target_person => target_employee_id);
  me := app_private.actor(actor_user_id, target_workspace_id);
  -- The owner holds every permission.
  reads_private := me.class = 'owner' or 'employees.private.read' = any (me.permissions);
  reads_access := me.class = 'owner' or 'employee_access.read' = any (me.permissions);
  select * into removal from app_private.authz_actions action where action.key = 'employee.remove_from_location';
  if not found then
    raise exception 'core action employee.remove_from_location is missing' using errcode = '22023';
  end if;
  select * into invite_rule from app_private.authz_actions action where action.key = 'employee.invite';
  if not found then
    raise exception 'core action employee.invite is missing' using errcode = '22023';
  end if;
  select * into change_rule from app_private.authz_actions action where action.key = 'employee.change_role';
  if not found then
    raise exception 'core action employee.change_role is missing' using errcode = '22023';
  end if;

  select jsonb_build_object(
    'id', employee.id,
    'workspace_id', employee.workspace_id,
    'employee_code', employee.employee_code,
    'first_name', employee.first_name,
    'last_name', employee.last_name,
    'preferred_name', employee.preferred_name,
    'display_name', concat_ws(' ', employee.first_name, employee.last_name),
    'invitation_email', employee.invitation_email,
    'account_email', account_user.email,
    'start_date', employee.start_date,
    'primary_location_id', primary_location.location_id,
    'primary_location_name', location.name,
    'location_count', (
      select count(*)
      from public.employee_location_assignments assignment
      where assignment.employee_id = employee.id and assignment.ended_at is null
    ),
    'primary_job_id', primary_job.job_id,
    'primary_job_name', job.name,
    'job_count', (
      select count(*)
      from public.employee_job_assignments assignment
      where assignment.employee_id = employee.id and assignment.ended_at is null
    ),
    'role_id', role.id,
    'role_name', role.name,
    -- ROL-CIFT 2.2: the record's two access slots (somebody with no account yet works); the drawer
    -- asks here, not the role's name.
    'access', jsonb_build_object(
      'employee', app_private.has_employee_access(employee.workspace_id, employee.user_id),
      'management', management_role.access_class),
    -- DAVET-ERISIM: the two slots by role, and where a manager manages, for who reads access or may change it.
    'employee_role_id', membership.employee_role_id,
    'management_role_id', membership.role_id,
    'managed_location_ids', case
      when membership.id is null or not (reads_access
        or app_private.authz_check(me, change_rule, null, employee.id, null) is null) then '[]'::jsonb
      else coalesce((select jsonb_agg(managed.location_id order by managed.location_id)
        from public.membership_managed_locations managed where managed.membership_id = membership.id), '[]'::jsonb)
    end,
    'display_status', case
      when employee.archived_at is not null then 'archived'
      when membership.status = 'active' then 'active'
      when membership.status = 'pending_activation' then 'onboarding'
      when invitation.status = 'pending' and invitation.expires_at > now() then 'invited'
      else 'not_invited'
    end,
    'archived_at', employee.archived_at,
    'revision', employee.revision,
    'user_id', employee.user_id,
    'internal_note', employee.internal_note,
    'is_remote', employee.is_remote,
    'is_excluded_from_schedule', employee.is_excluded_from_schedule,
    -- Whether this is the workspace owner's record: the drawer asks here, not
    -- the role's name (BL-421).
    'is_workspace_owner', app_private.employee_record_is_workspace_owner(employee.workspace_id, employee.id),
    -- null only when the reader may not read it. Somebody with nothing on file
    -- yet reads as an empty profile: no names, nothing given, the defaults the
    -- shared employeeDetailSchema needs (7b QA finding 1, shape agreed with
    -- nf-backend).
    'private_contact', case
      when not reads_private then null
      else jsonb_strip_nulls(jsonb_build_object(
        'legal_first_name', private_profile.legal_first_name,
        'legal_last_name', private_profile.legal_last_name,
        'preferred_name', private_profile.preferred_name
      )) || jsonb_build_object(
        'phone', private_profile.phone,
        'street_address', private_profile.street_address,
        'city', private_profile.city,
        'region', private_profile.region,
        'postal_code', private_profile.postal_code,
        'country_code', private_profile.country_code,
        'date_of_birth', private_profile.date_of_birth,
        'emergency_contact_name', private_profile.emergency_contact_name,
        'emergency_contact_relationship', private_profile.emergency_contact_relationship,
        'emergency_contact_phone', private_profile.emergency_contact_phone,
        'emergency_contact_email', coalesce(private_profile.emergency_contact_email, ''),
        'share_phone_with_teammates', coalesce(private_profile.share_phone_with_teammates, false),
        'share_email_with_teammates', coalesce(private_profile.share_email_with_teammates, false)
      )
    end,
    'locations', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', assignment.location_id,
          'name', assigned_location.name,
          'primary', assignment.is_primary,
          'archived', assigned_location.archived_at is not null,
          -- May the reader take them off this location.
          'removable', app_private.authz_check(me, removal, array[assignment.location_id], employee.id, null) is null
        )
        order by assignment.is_primary desc, assigned_location.name
      )
      from public.employee_location_assignments assignment
      join public.locations assigned_location on assigned_location.id = assignment.location_id
      where assignment.employee_id = employee.id and assignment.ended_at is null
    ), '[]'::jsonb),
    'jobs', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', assignment.job_id,
          'name', assigned_job.name,
          'primary', assignment.is_primary,
          'archived', assigned_job.archived_at is not null
        )
        order by assignment.is_primary desc, lower(assigned_job.name), assigned_job.id
      )
      from public.employee_job_assignments assignment
      join public.jobs assigned_job on assigned_job.id = assignment.job_id
      where assignment.employee_id = employee.id and assignment.ended_at is null
    ), '[]'::jsonb),
    'invitation', case
      -- Who reads access reads it; so does whoever its buttons answer to
      -- (employee.invite, a role they may give; BL-1069).
      when invitation.id is null or not (reads_access
        or (app_private.authz_check(me, invite_rule, null, employee.id, null) is null
          and app_private.can_invite_with_role(actor_user_id, target_workspace_id, invitation.role_id))) then null
      else jsonb_build_object(
        'id', invitation.id,
        'email', invitation.email,
        'role_id', invitation.role_id,
        -- DAVET-ERISIM: the two accesses it carries.
        'employee_role_id', invitation.employee_role_id,
        'management_role_id', invitation.management_role_id,
        'managed_location_ids', to_jsonb(invitation.managed_location_ids),
        'status', invitation.status,
        'expires_at', invitation.expires_at,
        'sent_at', invitation.sent_at,
        'delivery_status', invitation.delivery_status,
        'delivery_attempted_at', invitation.delivery_attempted_at,
        'delivery_failed_at', invitation.delivery_failed_at,
        'delivery_error', invitation.delivery_error,
        'role_name', invitation_role.name,
        'invited_by_name', coalesce(
          nullif(btrim(inviter_profile.display_name), ''),
          inviter_user.email
        )
      )
    end,
    'onboarding', jsonb_build_object(
      'status', case
        when membership.status = 'pending_activation' then 'in_progress'
        when invitation.status = 'pending' then 'invited'
        else 'not_requested'
      end,
      'required_documents', (
        select count(*)
        from public.document_types document_type
        where document_type.workspace_id = employee.workspace_id
          and document_type.required_at_onboarding
          and document_type.archived_at is null
      ),
      'completed_documents', 0
    ),
    'events', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', event.id,
          'action', event.action,
          'occurred_at', event.occurred_at,
          'actor_user_id', event.actor_user_id,
          'summary', event.summary
        )
        order by event.occurred_at desc
      )
      from (
        select *
        from public.employee_events
        where employee_id = employee.id
        order by occurred_at desc
        limit 50
      ) event
    ), '[]'::jsonb),
    -- What the reader may do to this record, by the same rules the actions ask.
    'allowed', (
      select jsonb_object_agg(replace(replace(action.key, 'employee.', ''), '.', '_'),
        app_private.authz_check(me, action, null, employee.id, null) is null
        -- Only a live record with no account on it is invitable, as
        -- prepare_employee_invitation_service says (7b QA finding 2).
        and (action.key <> 'employee.invite'
          or (employee.user_id is null and employee.archived_at is null)))
      from app_private.authz_actions action
      where action.key in ('employee.save', 'employee.terminate', 'employee.archive',
        'employee.remove_access', 'employee.change_role', 'employee.make_admin',
        'employee.invite', 'onboarding.review')
    )
  ) into answer
  from public.employee_profiles employee
  left join public.employee_private_profiles private_profile
    on private_profile.employee_id = employee.id
  left join auth.users account_user
    on account_user.id = employee.user_id
  left join public.employee_location_assignments primary_location
    on primary_location.employee_id = employee.id
    and primary_location.ended_at is null
    and primary_location.is_primary
  left join public.locations location on location.id = primary_location.location_id
  left join public.employee_job_assignments primary_job
    on primary_job.employee_id = employee.id
    and primary_job.ended_at is null
    and primary_job.is_primary
  left join public.jobs job on job.id = primary_job.job_id
  left join public.workspace_memberships membership
    on membership.workspace_id = employee.workspace_id
    and membership.user_id = employee.user_id
  left join public.workspace_roles role on role.id = coalesce(membership.role_id, membership.employee_role_id)
  left join public.workspace_roles management_role on management_role.id = membership.role_id
  left join lateral (
    select *
    from public.employee_invitations candidate
    where candidate.employee_id = employee.id
    order by candidate.created_at desc
    limit 1
  ) invitation on true
  left join public.workspace_roles invitation_role
    on invitation_role.id = invitation.role_id
  left join public.user_profiles inviter_profile
    on inviter_profile.user_id = invitation.created_by
  left join auth.users inviter_user
    on inviter_user.id = invitation.created_by
  where employee.id = target_employee_id
    and employee.workspace_id = target_workspace_id;

  return answer;
end;
$$;


ALTER FUNCTION "public"."get_employee_detail_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_document_access_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'documents.self');
 return jsonb_build_object('restricted',app_private.document_actor_blocked(actor_user_id,target_workspace_id));
end;
$$;


ALTER FUNCTION "public"."get_employee_document_access_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_document_lifecycle_path_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "target_submission_id" "uuid", "target_file_id" "uuid", "self_only" boolean) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare detail jsonb; path text;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,case when self_only then 'documents.self' else 'documents.read' end,target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id and q.kind in ('document','acknowledgement')));
 detail:=public.get_employee_document_lifecycle_service(actor_user_id,target_workspace_id,target_requirement_id,self_only);
 select f.object_path into path from public.employee_document_submission_files sf
 join public.employee_document_submissions s on s.id=sf.submission_id join public.employee_documents f on f.id=sf.file_id
 where sf.requirement_id=target_requirement_id and sf.workspace_id=target_workspace_id and sf.submission_id=target_submission_id and sf.file_id=target_file_id and sf.decision='keep'
 and (self_only or app_private.document_submission_visible(actor_user_id,
  (select q from public.employee_onboarding_requirements q where q.id=target_requirement_id),s.state));
 if path is null then raise exception 'document file unavailable' using errcode='P0002'; end if;
 return path;
end;
$$;


ALTER FUNCTION "public"."get_employee_document_lifecycle_path_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "target_submission_id" "uuid", "target_file_id" "uuid", "self_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "self_only" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; submissions jsonb; history jsonb;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,case when self_only then 'documents.self' else 'documents.read' end,target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id and q.kind in ('document','acknowledgement')));
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and workspace_id=target_workspace_id and kind in ('document','acknowledgement');
 if r.id is null or self_only is null or (self_only and r.lifecycle_user_id is distinct from actor_user_id)
 then raise exception 'document unavailable' using errcode='P0002'; end if;
 -- A document waiting for review is its decider's and its owner's (S2).
 if not self_only and not app_private.document_row_readable(actor_user_id, r) then
  raise exception 'Not allowed' using errcode='42501', hint='authz.out_of_scope', detail='documents.read';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'version',s.version,'state',s.state,'submitted_at',s.submitted_at,
  'reviewed_at',s.reviewed_at,'expiry_date',s.expiry_date,'metadata',s.metadata,'rejection_reason',s.rejection_reason,
  'files',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'filename',f.original_filename,'media_type',f.media_type,'size_bytes',f.size_bytes,'decision',sf.decision,'note',sf.note) order by f.created_at,f.id)
   from public.employee_document_submission_files sf join public.employee_documents f on f.id=sf.file_id where sf.submission_id=s.id),'[]')) order by s.version desc),'[]')
 into submissions from public.employee_document_submissions s where s.requirement_id=r.id
  and (self_only or app_private.document_submission_visible(actor_user_id,r,s.state));
 select coalesce(jsonb_agg(jsonb_build_object('id',ev.id,'action',ev.action,'occurred_at',ev.occurred_at,'metadata',ev.metadata) order by ev.occurred_at desc),'[]') into history
 from public.onboarding_events ev where ev.workspace_id=r.workspace_id and ev.employee_id=r.employee_id and ev.target_id=r.id::text
  and (self_only or not exists(select 1 from public.employee_document_submissions s
   where s.id::text=ev.metadata->>'submission_id'
    and not app_private.document_submission_visible(get_employee_document_lifecycle_service.actor_user_id,r,s.state)));
 return jsonb_build_object('obligation',app_private.document_obligation_json(app_private.document_view(actor_user_id,r)),'submissions',submissions,'history',history,'policy',case when r.kind='acknowledgement' then jsonb_build_object('content_text',r.source_snapshot->>'content_text','content_digest',r.source_snapshot->>'content_digest','intent_statement',r.source_snapshot->>'intent_statement','can_withdraw',self_only and exists(select 1 from public.employee_onboarding_cases c join public.workspace_memberships m on m.id=c.membership_id where c.id=r.case_id and c.submitted_at is null and c.status='in_progress' and m.status='pending_activation' and r.lifecycle_retired_at is null),'history',coalesce((select jsonb_agg(jsonb_build_object('typed_name',a.typed_name,'executed_at',a.executed_at,'withdrawn_at',a.withdrawn_at,'content_digest',a.content_digest) order by a.executed_at,a.id) from public.employee_acknowledgement_envelopes a where a.requirement_id=r.id and (not self_only or a.user_id=actor_user_id)),'[]'::jsonb),'evidence',(select jsonb_build_object('typed_name',a.typed_name,'executed_at',a.executed_at,'content_digest',a.content_digest,'intent_statement',a.intent_statement) from public.employee_acknowledgement_envelopes a where a.requirement_id=r.id and a.withdrawn_at is null and (not self_only or a.user_id=actor_user_id))) end,'initial_deferral',jsonb_build_object('reason',r.conditional_reason,'allowed',self_only and r.kind='document' and r.lifecycle_settings->>'mode'='conditional' and r.submitted_document_id is null and not r.lifecycle_exempt and r.lifecycle_closed_at is null and not exists(select 1 from public.employee_document_submissions s where s.requirement_id=r.id and s.state<>'draft') and exists(select 1 from public.employee_onboarding_cases c join public.workspace_memberships m on m.id=c.membership_id where c.id=r.case_id and m.status='pending_activation')),'timezone_settings',(select jsonb_build_object('value',app_private.document_employee_timezone(r.workspace_id,r.employee_id),'configured_value',p.document_timezone,'employee_revision',p.revision,'can_manage',not self_only and (p.is_remote or p.is_excluded_from_schedule) and app_private.document_timezone_admin(actor_user_id,r.workspace_id,r.employee_id) and app_private.time_off_timezone(r.workspace_id,r.employee_id) is null) from public.employee_profiles p where p.id=r.employee_id));
end;
$$;


ALTER FUNCTION "public"."get_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "self_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_hub_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_from" "date", "target_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare employee public.employee_profiles%rowtype; result jsonb;
begin
  if target_to < target_from or target_to > target_from + 62 then
    raise exception 'employee hub date range is invalid' using errcode = '22023';
  end if;
  employee := public.employee_hub_actor_service(actor_user_id, target_workspace_id);

  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'employee', jsonb_build_object(
      'id', employee.id,
      'display_name', concat_ws(' ', coalesce(nullif(employee.preferred_name,''),employee.first_name), employee.last_name)
    ),
    'time_off_timezone', app_private.time_off_timezone(target_workspace_id, employee.id),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object('id',location.id,'name',location.name) order by location.sort_order,location.name)
      from public.employee_location_assignments assignment
      join public.locations location on location.id=assignment.location_id and location.archived_at is null
      where assignment.employee_id=employee.id and assignment.ended_at is null
    ),'[]'::jsonb),
    'shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',shift.id,'location_id',shift.location_id,'location_name',location.name,'job_name',job.name,
        'scheduled_date',shift.scheduled_date,'time_basis',shift.time_basis,'time_snapshot',shift.time_snapshot,'time_timezone',shift.time_timezone,'start_time',to_char(shift.start_time,'HH24:MI'),
        'end_time',to_char(shift.end_time,'HH24:MI'),'note',shift.note,'employee_id',shift.employee_id,
        'shift_type_name',shift_type.name,'shift_type_color',shift_type.color,
        'shift_type_start_time',to_char(shift_type.default_start_time,'HH24:MI'),
        'shift_type_end_time',to_char(shift_type.default_end_time,'HH24:MI')
      ) order by shift.scheduled_date,shift.start_time)
      from public.schedule_published_shifts shift
      join public.schedule_location_publications publication on publication.id=shift.publication_id and publication.status='current'
      join public.locations location on location.id=shift.location_id
      join public.jobs job on job.id=shift.job_id
      left join public.shift_types shift_type on shift_type.id=shift.shift_type_id and shift_type.workspace_id=shift.workspace_id
      where shift.workspace_id=target_workspace_id and shift.employee_id=employee.id
        and shift.scheduled_date between target_from and target_to
    ),'[]'::jsonb),
    -- An open shift reaches an employee only offered, in Shift Hub, to who is eligible (Mert, 2026-10-20).
    -- The field stays empty until the clients stop reading it (EKRAN 02 #47).
    'open_shifts', '[]'::jsonb,
    'team_shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',shift.id,'location_id',shift.location_id,'location_name',location.name,'job_name',job.name,
        'scheduled_date',shift.scheduled_date,'time_basis',shift.time_basis,'time_snapshot',shift.time_snapshot,'time_timezone',shift.time_timezone,'start_time',to_char(shift.start_time,'HH24:MI'),
        'end_time',to_char(shift.end_time,'HH24:MI'),'note','','employee_id',shift.employee_id,
        'employee_name',concat_ws(' ',coalesce(nullif(teammate.preferred_name,''),teammate.first_name),teammate.last_name),
        'is_management',coalesce((select department.system_key='management' from public.departments department
          where department.id=job.department_id and department.workspace_id=shift.workspace_id),false)
      ) order by shift.scheduled_date,shift.start_time)
      from public.schedule_published_shifts shift
      join public.schedule_location_publications publication on publication.id=shift.publication_id and publication.status='current'
      join public.locations location on location.id=shift.location_id
      join public.jobs job on job.id=shift.job_id
      join public.employee_profiles teammate on teammate.id=shift.employee_id
      where shift.workspace_id=target_workspace_id and shift.employee_id<>employee.id
        and shift.scheduled_date between target_from and target_to
        and exists(select 1 from public.employee_location_assignments assignment
          where assignment.employee_id=employee.id and assignment.location_id=shift.location_id and assignment.ended_at is null)
    ),'[]'::jsonb),
    -- The days of the range with time off the person has (time off rebuild D3): approved, or what is left
    -- of it (app_private.leave_spans), as days of the zone it was asked in. A piece that ends at midnight is the day before's. My shifts and Home's week read it.
    'leave_days', coalesce((
      select jsonb_agg(to_char(off_day.day, 'YYYY-MM-DD') order by off_day.day)
      from (
        select distinct d::date as day
        from app_private.leave_spans(target_workspace_id, array[employee.id],
          tstzrange((target_from - 1)::timestamp at time zone 'UTC', (target_to + 2)::timestamp at time zone 'UTC', '[)')) away
        cross join lateral generate_series((lower(away.span) at time zone away.zone)::date,
          ((upper(away.span) - interval '1 microsecond') at time zone away.zone)::date, interval '1 day') d
        where not away.pending
      ) off_day
      where off_day.day between target_from and target_to
    ),'[]'::jsonb),
    -- The days of the range whose week is posted at one of the person's locations, for one of their jobs: a day
    -- with no shift there is a day off, not a schedule still to come (Home's week strip).
    'posted_days', coalesce((
      select jsonb_agg(to_char(posted.day, 'YYYY-MM-DD') order by posted.day)
      from (
        select d::date as day
        from generate_series(target_from, target_to, interval '1 day') d
        where exists(select 1 from public.schedule_location_publications publication
          join public.employee_location_assignments assignment
            on assignment.location_id=publication.location_id and assignment.employee_id=employee.id and assignment.ended_at is null
          where publication.workspace_id=target_workspace_id and publication.status='current'
            and publication.week_start<=d::date and d::date<publication.week_start+7
            and (publication.department_ids is null or exists(select 1 from public.employee_job_assignments job_assignment
              where job_assignment.employee_id=employee.id and job_assignment.ended_at is null
                and public.schedule_shift_in_department_scope_service(job_assignment.job_id,
                  publication.department_ids, publication.include_no_department))))
      ) posted
    ),'[]'::jsonb),
    'team', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',teammate.id,
        'display_name',concat_ws(' ',coalesce(nullif(teammate.preferred_name,''),teammate.first_name),teammate.last_name),
        'job_names',coalesce((select jsonb_agg(job.name order by lower(job.name),job.id) from public.employee_job_assignments assignment join public.jobs job on job.id=assignment.job_id where assignment.employee_id=teammate.id and assignment.ended_at is null),'[]'::jsonb),
        'location_names',coalesce((select jsonb_agg(location.name order by location.sort_order,location.name) from public.employee_location_assignments assignment join public.locations location on location.id=assignment.location_id where assignment.employee_id=teammate.id and assignment.ended_at is null),'[]'::jsonb)
      ) order by teammate.last_name,teammate.first_name)
      from public.employee_profiles teammate
      where teammate.workspace_id=target_workspace_id and teammate.archived_at is null and teammate.id<>employee.id
        and exists(select 1 from public.employee_location_assignments mine join public.employee_location_assignments theirs on theirs.location_id=mine.location_id and theirs.ended_at is null where mine.employee_id=employee.id and mine.ended_at is null and theirs.employee_id=teammate.id)
    ),'[]'::jsonb)
  ) into result;
  return result;
end; $$;


ALTER FUNCTION "public"."get_employee_hub_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_from" "date", "target_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_onboarding_review_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target_case public.employee_onboarding_cases%rowtype; requirement_rows jsonb; total_count integer; completed_count integer;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'onboarding.review', target_person => target_employee_id);
  select * into target_case from public.employee_onboarding_cases
  where workspace_id = target_workspace_id and employee_id = target_employee_id;
  if target_case.id is null then raise exception 'onboarding case unavailable' using errcode = 'P0002'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', requirement.id, 'kind', requirement.kind, 'title', requirement.title,
    'description', requirement.description, 'status', (app_private.document_view(actor_user_id, requirement)).status,
    'required', requirement.required, 'blocks_activation', requirement.blocks_activation,
    'requires_review', requirement.requires_review, 'sort_order', requirement.sort_order,
    'source_id', requirement.source_id,
    'accepted_formats', coalesce(requirement.source_snapshot->'accepted_formats', '[]'::jsonb),
    'content_text', null, 'content_digest', requirement.source_snapshot->>'content_digest',
    'intent_statement', null, 'rejection_reason', (app_private.document_view(actor_user_id, requirement)).rejection_reason
  ) order by requirement.sort_order), '[]'::jsonb),
  count(*) filter (where requirement.required),
  count(*) filter (where requirement.required and (app_private.document_view(actor_user_id, requirement)).status = 'completed')
  into requirement_rows, total_count, completed_count
  from public.employee_onboarding_requirements requirement
  where requirement.case_id = target_case.id and requirement.status <> 'superseded' and requirement.lifecycle_retired_at is null
    -- a row the reader may not see is not counted either (S2)
    and (requirement.kind <> 'document' or app_private.document_row_readable(actor_user_id, requirement));
  return jsonb_build_object(
    'case_id', target_case.id, 'employee_id', target_case.employee_id,
    'case_status', target_case.status, 'revision', target_case.revision,
    'submitted_at', target_case.submitted_at,
    'progress_completed', completed_count, 'progress_total', total_count,
    'ssn_present', false,
    'requirements', requirement_rows
  );
end;
$$;


ALTER FUNCTION "public"."get_employee_onboarding_review_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_onboarding_service"("target_user_id" "uuid", "target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_case public.employee_onboarding_cases%rowtype;
  employee public.employee_profiles%rowtype;
  membership public.workspace_memberships%rowtype;
  profile jsonb;
  requirements jsonb;
  completed_count integer;
  total_count integer;
  first_path text;
begin
 perform app_private.authorize(target_user_id, app_private.onboarding_self_workspace(target_user_id, target_workspace_id, true), 'onboarding.self');
  perform app_private.initialize_employee_onboarding(target_user_id, target_workspace_id);
  select onboarding.* into target_case
  from public.employee_onboarding_cases onboarding
  where onboarding.id = app_private.employee_onboarding_case_id(target_user_id, target_workspace_id);
  if target_case.id is null then
    raise exception 'employee onboarding is unavailable' using errcode = 'P0002';
  end if;
  select * into employee from public.employee_profiles where id = target_case.employee_id;
  select * into membership from public.workspace_memberships where id = target_case.membership_id;

  select to_jsonb(private_profile) - 'created_at' - 'updated_at' - 'employee_id' - 'workspace_id'
  into profile from public.employee_private_profiles private_profile
  where private_profile.employee_id = employee.id;
  profile := coalesce(
    profile,
    jsonb_build_object(
      'legal_first_name', employee.first_name,
      'legal_last_name', employee.last_name
    )
  );


  select coalesce(jsonb_agg(jsonb_build_object(
    'id', requirement.id,
    'kind', requirement.kind,
    'title', requirement.title,
    'description', requirement.description,
    'status', requirement.status,
    'required', requirement.required,'document_mode',requirement.lifecycle_settings->>'mode', 'conditional_reason',requirement.conditional_reason,
    'blocks_activation', requirement.blocks_activation,
    'requires_review', requirement.requires_review,
    'sort_order', requirement.sort_order,
    'source_id', requirement.source_id,
    'accepted_formats', coalesce(requirement.source_snapshot->'accepted_formats', '[]'::jsonb),
    'content_text', requirement.source_snapshot->>'content_text',
    'content_digest', requirement.source_snapshot->>'content_digest',
    'intent_statement', requirement.source_snapshot->>'intent_statement',
    'rejection_reason', requirement.rejection_reason
  ) order by requirement.sort_order, requirement.id), '[]'::jsonb),
  count(*) filter (where requirement.required or (requirement.kind='document' and requirement.lifecycle_settings->>'mode'='conditional')),
  count(*) filter (where (requirement.required and requirement.status in ('completed', 'awaiting_review')) or (requirement.kind='document' and requirement.lifecycle_settings->>'mode'='conditional' and not app_private.document_initial_action_missing(requirement)))
  into requirements, total_count, completed_count
  from public.employee_onboarding_requirements requirement
  where requirement.case_id = target_case.id and requirement.status <> 'superseded' and requirement.lifecycle_retired_at is null and (requirement.kind<>'document' or (not requirement.lifecycle_exempt and requirement.lifecycle_closed_at is null));

  select case requirement.kind
    when 'profile' then '/welcome/profile'
    when 'ssn' then '/welcome/review'
    when 'document' then '/welcome/documents/' || requirement.id
    when 'acknowledgement' then '/welcome/acknowledgements/' || requirement.id
    when 'availability' then '/welcome/availability'
  end into first_path
  from public.employee_onboarding_requirements requirement
  where requirement.case_id = target_case.id
    and (requirement.required or app_private.document_initial_action_missing(requirement))
    and requirement.status in ('not_started', 'in_progress', 'rejected', 'manual_follow_up')
  order by case when requirement.status = 'rejected' then 0 else 1 end,
    requirement.sort_order, requirement.id
  limit 1;
  first_path := coalesce(first_path,
    case when target_case.status = 'approved' then '/app/employee-hub' else '/welcome/review' end);

  return jsonb_build_object(
    'case_id', target_case.id,
    'workspace_id', target_case.workspace_id,
    'workspace_name', (select name from public.workspaces where id = target_case.workspace_id),
    'employee_id', employee.id,
    'employee_name', concat_ws(' ', employee.first_name, employee.last_name),
    'membership_id', membership.id,
    'membership_status', membership.status,
    'case_status', target_case.status,
    'revision', target_case.revision,
    'progress_completed', completed_count,
    'progress_total', total_count,
    'first_actionable_path', first_path,
    'ssn_status', jsonb_build_object(
      'present', false,
      'last_four', null
    ),
    'profile', profile,
    'assignments', jsonb_build_object(
      'locations', coalesce((select jsonb_agg(location.name order by assignment.is_primary desc, location.name)
        from public.employee_location_assignments assignment join public.locations location on location.id = assignment.location_id
        where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb),
      'jobs', coalesce((select jsonb_agg(job.name order by assignment.is_primary desc, lower(job.name), job.id)
        from public.employee_job_assignments assignment join public.jobs job on job.id = assignment.job_id
        where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb)
    ),
    'requirements', requirements
  );
end;
$$;


ALTER FUNCTION "public"."get_employee_onboarding_service"("target_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_schedule_board_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor public.employee_profiles%rowtype;
  settings public.workspace_scheduling_settings%rowtype;
  resolved_week_start date;
  result jsonb;
begin
  actor := public.employee_hub_actor_service(actor_user_id, target_workspace_id);

  select * into settings
  from public.workspace_scheduling_settings
  where workspace_id = target_workspace_id;
  if settings.workspace_id is null then
    raise exception 'scheduling settings are unavailable' using errcode = 'P0002';
  end if;

  resolved_week_start := case settings.week_start_day
    when 'sunday' then target_date - extract(dow from target_date)::integer
    else target_date - (extract(isodow from target_date)::integer - 1)
  end;

  with allowed_locations as (
    select location.*
    from public.locations location
    where location.workspace_id = target_workspace_id
      and location.archived_at is null
      and exists (
        select 1
        from public.employee_location_assignments assignment
        where assignment.employee_id = actor.id
          and assignment.location_id = location.id
          and assignment.ended_at is null
      )
  ), current_publications as (
    select publication.*
    from public.schedule_location_publications publication
    join allowed_locations location on location.id = publication.location_id
    where publication.week_start = resolved_week_start
      and publication.status = 'current'
  ), visible_employees as (
    select distinct employee.*
    from public.employee_profiles employee
    where employee.workspace_id = target_workspace_id
      and employee.archived_at is null
      and exists (
        select 1
        from public.employee_location_assignments assignment
        join allowed_locations location on location.id = assignment.location_id
        where assignment.employee_id = employee.id and assignment.ended_at is null
      )
      -- ROL-CIFT 2.1: the team is the people who can be scheduled; who only manages is not on it.
      and app_private.has_employee_access(target_workspace_id, employee.user_id)
  ), current_shifts as (
    select shift.*
    from public.schedule_published_shifts shift
    join current_publications publication on publication.id = shift.publication_id
    where shift.scheduled_date between resolved_week_start and resolved_week_start + 6
      -- An open shift is the manager's: offered, it reaches who may take it in Shift Hub (Mert, 2026-10-20).
      and shift.employee_id is not null
  ), own_availability as materialized (
    -- The employee's own marks; the manager's private reminder never reaches here.
    select * from app_private.schedule_week_availability(
      target_workspace_id, resolved_week_start, array[actor.id],
      (select coalesce(array_agg(location.id), '{}') from allowed_locations location), false)
  )
  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'week_start', resolved_week_start,
    'week_start_day', settings.week_start_day,
    'settings', jsonb_build_object(
      'time_format', coalesce(settings.time_format, '12h')
    ),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', location.id,
        'name', location.name,
        'timezone', location.timezone,
        'sort_order', location.sort_order,
        'publication_status', case when publication.id is null then 'unpublished' else 'published' end,
        'published_at', publication.published_at
      ) order by location.sort_order, location.name)
      from allowed_locations location
      left join current_publications publication on publication.location_id = location.id
    ), '[]'::jsonb),
    'shift_types', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', shift_type.id, 'name', shift_type.name, 'color', shift_type.color,
        'sort_order', shift_type.sort_order,
        'default_revision', shift_type.default_revision,
        'default_start_time', case when shift_type.default_start_time is null then null else to_char(shift_type.default_start_time, 'HH24:MI') end,
        'default_end_time', case when shift_type.default_end_time is null then null else to_char(shift_type.default_end_time, 'HH24:MI') end
      ) order by shift_type.sort_order, shift_type.name)
      from public.shift_types shift_type
      where shift_type.workspace_id = target_workspace_id and shift_type.archived_at is null
    ), '[]'::jsonb),
    'shift_labels', '[]'::jsonb,
    'employees', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', employee.id,
        'employee_code', employee.employee_code,
        'display_name', coalesce(nullif(employee.preferred_name, ''), employee.first_name) || ' ' || employee.last_name,
        'location_ids', coalesce((select jsonb_agg(assignment.location_id order by assignment.location_id)
          from public.employee_location_assignments assignment
          join allowed_locations location on location.id = assignment.location_id
          where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb),
        'job_ids', coalesce((select jsonb_agg(assignment.job_id order by assignment.job_id)
          from public.employee_job_assignments assignment
          where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb),
        'primary_job_id', app_private.stored_primary_job(employee.id)
      ) || case when employee.id = actor.id then jsonb_build_object('weekly_availability', coalesce((
          select jsonb_agg(own.projection order by own.location_id)
          from own_availability own
          where exists (select 1 from public.employee_location_assignments assignment
            where assignment.employee_id = actor.id and assignment.location_id = own.location_id
              and assignment.ended_at is null)), '[]'::jsonb))
        else '{}'::jsonb end
      order by employee.last_name, employee.first_name, employee.id)
      from visible_employees employee
    ), '[]'::jsonb),
    'shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', shift.id,
        'location_id', shift.location_id,
        'employee_id', shift.employee_id,
        'job_id', shift.job_id,
        'shift_type_id', shift.shift_type_id,
        'scheduled_date', shift.scheduled_date,
        'time_basis', shift.time_basis,
        'time_snapshot', shift.time_snapshot,
        'time_timezone', shift.time_timezone,
        'start_time', to_char(shift.start_time, 'HH24:MI'),
        'end_time', to_char(shift.end_time, 'HH24:MI'),
        'crosses_midnight', shift.crosses_midnight,
        'unpaid_break_minutes', coalesce(shift.unpaid_break_minutes, 0),
        'hide_time_on_badge', coalesce(shift.hide_time_on_badge, false),
        'note', case when shift.employee_id = actor.id then shift.note else '' end,
        'label_ids', to_jsonb(coalesce(shift.label_ids, '{}'::uuid[])),
        'label_names', to_jsonb(coalesce(shift.label_names, '{}'::text[])),
        'warning_codes', to_jsonb(array_remove(array[
          case when exists (
            select 1 from public.schedule_closures closure
            where closure.location_id = shift.location_id
              and closure.closed_date = shift.scheduled_date and closure.status <> 'scheduled'
              and app_private.closure_covers(closure.kind, closure.opens, closure.closes, shift.start_time, shift.end_time)
          ) then 'closed_location' end,
          -- Only a conflict with the employee's own marks, as accepted at publishing.
          case when shift.employee_id = actor.id
            and coalesce((shift.availability_snapshot -> 'assessment' ->> 'has_availability_conflict')::boolean, false)
            and jsonb_array_length(coalesce(shift.availability_snapshot -> 'assessment' -> 'employee_intervals', '[]'::jsonb)) > 0
          then 'availability' end,
          case when shift.employee_id is not null and exists (
            select 1 from current_shifts other
            where other.employee_id = shift.employee_id
              and other.scheduled_date = shift.scheduled_date
              and other.id <> shift.id
              and not shift.crosses_midnight and not other.crosses_midnight
              and shift.start_time < other.end_time and shift.end_time > other.start_time
          ) then 'overlap' end
        ]::text[], null))
      ) order by shift.scheduled_date, shift.start_time, shift.id)
      from current_shifts shift
    ), '[]'::jsonb),
    'closures', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', closure.id, 'location_id', closure.location_id,
        'closed_date', closure.closed_date, 'title', closure.title,
        'is_all_day', closure.is_all_day, 'kind', closure.kind,
        'opens', to_char(closure.opens, 'HH24:MI'), 'closes', to_char(closure.closes, 'HH24:MI'),
        'announcement_id', closure.announcement_id
      ) order by closure.closed_date, closure.title)
      from public.schedule_closures closure
      join allowed_locations location on location.id = closure.location_id
      where closure.closed_date between resolved_week_start and resolved_week_start + 6
        and closure.status <> 'scheduled'
    ), '[]'::jsonb),
    -- Records on the Schedule that are out to the employee and touch the week,
    -- one row per their checked location; a record for no location is theirs
    -- wherever they work. A yearly record's next year is its own record.
    'important_dates', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', item.id, 'location_id', place.location_id, 'title', item.title,
        'category', item.category, 'category_other', item.category_other,
        'starts_on', item.starts_on, 'ends_on', coalesce(item.ends_on, item.starts_on),
        'status', item.status, 'publish_at', item.publish_at, 'day', place.day,
        'opens', to_char(place.opens, 'HH24:MI'), 'closes', to_char(place.closes, 'HH24:MI'),
        'event_from', to_char(item.event_from, 'HH24:MI'), 'event_until', to_char(item.event_until, 'HH24:MI')
      ) order by item.starts_on, item.title, place.location_id)
      from public.announcements item
      cross join lateral (
        select target.location_id, target.day, target.opens, target.closes
        from public.announcement_locations target
        join allowed_locations location on location.id = target.location_id
        where target.announcement_id = item.id
        union all
        select null::uuid, 'open', null::time, null::time
        where not exists (
          select 1 from public.announcement_locations target
          join public.locations location on location.id = target.location_id and location.archived_at is null
          where target.announcement_id = item.id)
      ) place
      where item.workspace_id = target_workspace_id and item.status = 'published' and item.archived_at is null
        and item.on_schedule and item.starts_on is not null
        and item.starts_on <= resolved_week_start + 6 and resolved_week_start <= coalesce(item.ends_on, item.starts_on)
        and app_private.announcement_reaches(item, actor_user_id)
    ), '[]'::jsonb)
  ) || app_private.schedule_departments_and_jobs(target_workspace_id)
    || app_private.schedule_referenced_catalog(target_workspace_id,
      array(select shift.job_id from current_shifts shift),
      array(select shift.shift_type_id from current_shifts shift))
  into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_employee_schedule_board_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_important_dates_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  w uuid := target_workspace_id;
  reader app_private.actor_state;
  writable uuid[];
begin
  perform app_private.authorize(actor_user_id, w, 'settings.important_dates.read');
  perform app_private.announcement_release(w);
  reader := app_private.actor(actor_user_id, w);
  writable := app_private.scope_set(actor_user_id, w, 'important_date.write');
  return jsonb_build_object(
    'workspace_id', w,
    'time_format', app_private.announcement_time_format(w),
    'can_write', app_private.authz_reason(actor_user_id, w, 'important_date.write_wide') is null or cardinality(writable) > 0,
    'dates', coalesce((
      select jsonb_agg(app_private.announcement_item(reader, item, control.allowed) order by item.starts_on, item.event_from nulls first, item.id)
      from public.announcements item
      cross join lateral (select app_private.announcement_reason(reader, app_private.announcement_places(item.id),
        item.created_by, app_private.announcement_dates(item)) is null allowed) control
      where item.workspace_id = w and item.on_important_dates and item.starts_on is not null
        and item.status = 'published' and item.archived_at is null
        and (control.allowed or app_private.announcement_reaches(item, actor_user_id))), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."get_important_dates_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_last_avatar_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  membership uuid;
  remembered app_private.last_avatars;
  source_photo text;
  source_name text;
  source_live boolean;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'avatar.self');

  select m.id into membership
  from public.workspace_memberships m
  where m.workspace_id = target_workspace_id and m.user_id = actor_user_id;

  select * into remembered from app_private.last_avatars l where l.user_id = actor_user_id;
  if remembered.user_id is null or remembered.source_membership_id is not distinct from membership then
    return null;
  end if;

  select w.name, a.photo_path,
    m.status in ('active', 'pending_activation') and app_private.workspace_open_to_actor(m.workspace_id, actor_user_id)
    into source_name, source_photo, source_live
  from public.workspace_memberships m
  join public.workspaces w on w.id = m.workspace_id
  left join public.member_avatars a on a.membership_id = m.id
  where m.id = remembered.source_membership_id and m.user_id = actor_user_id;

  -- A drawing whose membership was deleted (source forgotten) is still offered; a known source must be live.
  if remembered.source_membership_id is not null and source_live is not true then
    return null;
  end if;

  if remembered.art_key is not null then
    return jsonb_build_object('kind', 'art', 'art_key', remembered.art_key, 'source_photo_path', null,
      'from_workspace_name', source_name);
  end if;
  if source_photo is null then
    return null;
  end if;
  return jsonb_build_object('kind', 'photo', 'art_key', null, 'source_photo_path', source_photo,
    'from_workspace_name', source_name);
end;
$$;


ALTER FUNCTION "public"."get_last_avatar_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lineup_candidates_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  place public.locations;
  day date;
  type_id uuid;
  edit jsonb := payload -> 'row';
  department uuid;
  read jsonb;
  target jsonb;
  win_from timestamptz;
  win_to timestamptz;
  win_minutes numeric;
  result jsonb;
  uuid_shape constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
begin
  if jsonb_typeof(payload) is distinct from 'object'
     or payload ->> 'location_id' is null or (payload ->> 'location_id') !~* uuid_shape
     or payload ->> 'service_date' is null or (payload ->> 'service_date') !~ '^\d{4}-\d{2}-\d{2}$'
     or (payload ->> 'shift_type_id' is not null and (payload ->> 'shift_type_id') !~* uuid_shape)
     or (payload ? 'row') = (payload ? 'department_id')
     or (payload ? 'row' and (jsonb_typeof(edit) is distinct from 'object'
         or ((edit ->> 'source_shift_id') is null) = ((edit ->> 'row_id') is null)
         or coalesce(edit ->> 'source_shift_id', edit ->> 'row_id') !~* uuid_shape))
     or (payload ->> 'department_id' is not null and (payload ->> 'department_id') !~* uuid_shape) then
    raise exception 'Choose a department or a person' using errcode = '22023', hint = 'lineup.invalid_command';
  end if;
  -- The core first: a stranger learns nothing.
  perform app_private.authorize(actor_user_id, target_workspace_id, 'lineup.share',
    target_locations => array[(payload ->> 'location_id')::uuid]);

  select * into place from public.locations l
  where l.id = (payload ->> 'location_id')::uuid and l.workspace_id = target_workspace_id;
  day := (payload ->> 'service_date')::date;
  type_id := (payload ->> 'shift_type_id')::uuid;
  department := (payload ->> 'department_id')::uuid;
  if type_id is not null and not exists (
    select 1 from public.shift_types t where t.id = type_id and t.workspace_id = target_workspace_id and t.deleted_at is null
  ) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'lineup.share';
  end if;

  -- The whole day, every location's lineups: who works where, and when.
  read := app_private.lineup_day(target_workspace_id, day, array(
    select l.id from public.locations l
    where l.workspace_id = target_workspace_id and l.archived_at is null and l.deleted_at is null));

  if payload ? 'row' then
    select r into target
    from jsonb_array_elements(read -> 'locations') l, jsonb_array_elements(l -> 'lineups') x, jsonb_array_elements(x -> 'rows') r
    where (l ->> 'id')::uuid = place.id and (x ->> 'shift_type_id')::uuid is not distinct from type_id
      and (r ->> 'employee_id') is not null
      and ((edit ? 'source_shift_id' and r ->> 'source_shift_id' = edit ->> 'source_shift_id')
        or (edit ? 'row_id' and r ->> 'id' = edit ->> 'row_id' and (r -> 'lineup_only')::boolean));
    if target is null then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'lineup.share';
    end if;
    if target ->> 'called_off_at' is not null or target ->> 'replaced_by_row_id' is not null then
      raise exception 'This person isn''t on the lineup now' using errcode = '22023', hint = 'lineup.row_out';
    end if;
    win_from := (day + (target ->> 'start_time')::time) at time zone place.timezone;
    win_to := (day + (target ->> 'end_time')::time
      + case when (target -> 'crosses_midnight')::boolean then interval '1 day' else interval '0' end) at time zone place.timezone;
  else
    -- The department's hours on this lineup (its first in to its last out), else the shift type's.
    select min((day + (r ->> 'start_time')::time) at time zone place.timezone),
      max((day + (r ->> 'end_time')::time
        + case when (r -> 'crosses_midnight')::boolean then interval '1 day' else interval '0' end) at time zone place.timezone)
    into win_from, win_to
    from jsonb_array_elements(read -> 'locations') l, jsonb_array_elements(l -> 'lineups') x, jsonb_array_elements(x -> 'rows') r
    where (l ->> 'id')::uuid = place.id and (x ->> 'shift_type_id')::uuid is not distinct from type_id
      and r ->> 'employee_id' is not null and r ->> 'called_off_at' is null and r ->> 'replaced_by_row_id' is null
      and (r ->> 'department_id')::uuid is not distinct from department;
    if win_from is null then
      select (day + t.default_start_time) at time zone place.timezone,
        (day + t.default_end_time + case when t.default_end_time <= t.default_start_time then interval '1 day' else interval '0' end)
          at time zone place.timezone
      into win_from, win_to
      from public.shift_types t where t.id = type_id and t.workspace_id = target_workspace_id
        and t.default_start_time is not null and t.default_end_time is not null;
    end if;
  end if;
  -- No hours to measure by: the whole day there.
  if win_from is null then
    win_from := day::timestamp at time zone place.timezone;
    win_to := (day + 1)::timestamp at time zone place.timezone;
  end if;
  win_minutes := extract(epoch from win_to - win_from) / 60;

  with day_rows as (
    -- Everyone's shift that day, wherever, but this lineup's: who is on it is not offered. Here, and where its lineup
    -- is published, as the lineup has it; at another location's draft, as its published Schedule has it (a draft is
    -- its manager's; the Schedule's ghost shift says no more).
    select (r ->> 'employee_id')::uuid as employee_id, (l ->> 'id')::uuid as location_id, l ->> 'name' as location_name,
      l ->> 'timezone' as zone, coalesce(x ->> 'shift_type_name', 'No shift type') as shift_name, r,
      (l ->> 'id')::uuid = place.id or (x -> 'published')::boolean as live
    from jsonb_array_elements(read -> 'locations') l, jsonb_array_elements(l -> 'lineups') x, jsonb_array_elements(x -> 'rows') r
    where r ->> 'employee_id' is not null
      and not ((l ->> 'id')::uuid = place.id and (x ->> 'shift_type_id')::uuid is not distinct from type_id)
  ), shifts as (
    select d.employee_id, d.location_id, d.location_name, d.shift_name, t.start_time, t.end_time,
      (day + t.start_time::time) at time zone d.zone as from_at,
      (day + t.end_time::time + case when t.end_time::time <= t.start_time::time then interval '1 day' else interval '0' end)
        at time zone d.zone as to_at
    from day_rows d
    cross join lateral (select
        case when d.live then d.r ->> 'start_time' else d.r ->> 'schedule_start_time' end as start_time,
        case when d.live then d.r ->> 'end_time' else d.r ->> 'schedule_end_time' end as end_time) t
    where case when d.live then d.r ->> 'called_off_at' is null and d.r ->> 'replaced_by_row_id' is null
               else not (d.r -> 'lineup_only')::boolean end
  ), measured as (
    select s.*, greatest(0, extract(epoch from least(s.to_at, win_to) - greatest(s.from_at, win_from)) / 60) as overlap
    from shifts s
  ), on_lineup as (
    select (r ->> 'employee_id')::uuid as employee_id
    from jsonb_array_elements(read -> 'locations') l, jsonb_array_elements(l -> 'lineups') x, jsonb_array_elements(x -> 'rows') r
    where (l ->> 'id')::uuid = place.id and (x ->> 'shift_type_id')::uuid is not distinct from type_id
      and r ->> 'employee_id' is not null
  ), people as (
    select e.id, coalesce(nullif(e.preferred_name, ''), e.first_name) || ' ' || e.last_name as name,
      array(select a.job_id from public.employee_job_assignments a join public.jobs j on j.id = a.job_id
            where a.workspace_id = target_workspace_id and a.employee_id = e.id and a.ended_at is null and j.archived_at is null
            order by a.is_primary desc, j.name) as job_ids
    from public.employee_profiles e
    where e.workspace_id = target_workspace_id
      and app_private.lineup_staff_eligible(target_workspace_id, place.id, e.id)
      and not exists (select 1 from on_lineup o where o.employee_id = e.id)
  ), on_leave as materialized (
    -- Time off in these hours, as it is now: revoked or given back hours are no time off (D1a).
    select distinct l.employee_id
    from app_private.leave_spans(target_workspace_id, array(select p.id from people p), tstzrange(win_from, win_to, '[)')) l
    where not l.pending
  ), fitted as (
    select p.*,
      array(select j.id from unnest(p.job_ids) as k (id) join public.jobs j on j.id = k.id
            where case when target is not null then j.id = (target ->> 'job_id')::uuid
                       else j.department_id is not distinct from department end) as fits,
      exists (select 1 from on_leave o where o.employee_id = p.id) as off,
      away.location_name as away_location, away.shift_name as away_shift, away.start_time as away_start,
      away.end_time as away_end, away.overlap as away_overlap,
      here.shift_name as here_shift, here.start_time as here_start, here.end_time as here_end, here.overlap as here_overlap,
      first.location_id as first_location_id, first.location_name as first_location, first.shift_name as first_shift,
      first.start_time as first_start, first.end_time as first_end
    from people p
    -- The most of these hours somewhere else, the most here, and the day's first shift.
    left join lateral (select m.* from measured m where m.employee_id = p.id and m.location_id <> place.id and m.overlap > 0
                       order by m.overlap desc limit 1) away on true
    left join lateral (select m.* from measured m where m.employee_id = p.id and m.location_id = place.id and m.overlap > 0
                       order by m.overlap desc limit 1) here on true
    left join lateral (select m.* from measured m where m.employee_id = p.id order by m.from_at limit 1) first on true
  ), scored as (
    select f.*, cardinality(f.fits) > 0 as match,
      case
        when f.off then 10 + case when cardinality(f.fits) > 0 then 5 else 0 end
        when f.away_overlap is not null then (case when f.away_overlap < win_minutes then 40 else 25 end)
          + case when cardinality(f.fits) > 0 then 5 else 0 end
        when f.here_overlap is not null then 30
        when f.first_start is not null then case when f.first_location_id = place.id then 65 else 70 end
        else 100
      end as score
    from fitted f
    -- Here at another shift for half these hours or more: not free for this one.
    where f.off or f.away_overlap is not null or f.here_overlap is null or f.here_overlap < win_minutes / 2
  )
  select jsonb_build_object(
    'window', jsonb_build_object('start_time', to_char(win_from at time zone place.timezone, 'HH24:MI'),
      'end_time', to_char(win_to at time zone place.timezone, 'HH24:MI')),
    'job_id', target -> 'job_id',
    'candidates', coalesce(jsonb_agg(jsonb_build_object(
      'employee_id', s.id,
      'name', s.name,
      'job_ids', to_jsonb(s.job_ids),
      -- The position the person would take: the row's on Replace, else her first in the department.
      'job_id', case when target is not null then target -> 'job_id' else to_jsonb(s.fits[1]) end,
      'group', case when s.off or s.away_overlap is not null then 'unavailable' when not s.match then 'consider'
                    when s.score = 100 then 'best_fit' else 'available' end,
      'score', s.score,
      'why', case
        when s.off then jsonb_build_object('reason', 'time_off')
        when s.away_overlap is not null then jsonb_build_object('reason', 'elsewhere', 'location_name', s.away_location,
          'shift_name', s.away_shift, 'start_time', s.away_start, 'end_time', s.away_end,
          'partial', s.away_overlap < win_minutes)
        when s.here_overlap is not null then jsonb_build_object('reason', 'overlap_here', 'shift_name', s.here_shift,
          'start_time', s.here_start, 'end_time', s.here_end, 'overlap_minutes', round(s.here_overlap))
        when s.first_start is not null then jsonb_build_object('reason', 'other_shift',
          'location_name', case when s.first_location_id = place.id then null else s.first_location end,
          'shift_name', s.first_shift, 'start_time', s.first_start, 'end_time', s.first_end)
        else jsonb_build_object('reason', 'no_shift')
      end
    ) order by s.score desc, s.name, s.id), '[]'::jsonb))
  into result
  from scored s;
  return result;
end;
$_$;


ALTER FUNCTION "public"."get_lineup_candidates_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lineup_day_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date", "target_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "target_shift_type_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reach uuid[] := app_private.scope_set(actor_user_id, target_workspace_id, 'lineup.read');
begin
  if target_date is null then
    raise exception 'a day is required' using errcode = '22023', hint = 'lineup.invalid_day';
  end if;
  if target_location_ids is not null then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'lineup.read', target_locations => target_location_ids);
  elsif cardinality(reach) = 0
     and (app_private.authz_reason(actor_user_id, target_workspace_id, 'lineup.read') is distinct from 'out_of_scope'
          or exists (select 1 from public.locations l where l.workspace_id = target_workspace_id and l.deleted_at is null)) then
    -- Nowhere to read: the core says why. A workspace with no live location reads as empty.
    perform app_private.authorize(actor_user_id, target_workspace_id, 'lineup.read');
  end if;

  return app_private.lineup_day(target_workspace_id, target_date,
    array(select x from unnest(reach) x where target_location_ids is null or x = any (target_location_ids)),
    target_shift_type_ids);
end;
$$;


ALTER FUNCTION "public"."get_lineup_day_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date", "target_location_ids" "uuid"[], "target_shift_type_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_manager_home_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state;
  documents_rule app_private.authz_actions;
  employee_rule app_private.authz_actions;
  places uuid[];
  exchange_places uuid[];
  saved public.workspace_layout_preferences;
  local_today date;
  result jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.todos');
  me := app_private.actor(actor_user_id, target_workspace_id);
  places := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.read');
  exchange_places := app_private.scope_set(actor_user_id, target_workspace_id, 'exchange.read');
  select * into documents_rule from app_private.authz_actions r where r.key = 'documents.read';
  select * into employee_rule from app_private.authz_actions r where r.key = 'employee.read';
  select * into saved from public.workspace_layout_preferences p
  where p.workspace_id = target_workspace_id and p.user_id = actor_user_id;
  -- Coming up starts on the earliest "today" among the locations in view.
  local_today := coalesce(
    (select min((now() at time zone l.timezone)::date) from public.locations l
     where l.workspace_id = target_workspace_id and l.id = any(places)),
    (now() at time zone 'UTC')::date);

  with place as (
    select l.id, l.name, l.timezone, (now() at time zone l.timezone)::date as today
    from public.locations l
    where l.workspace_id = target_workspace_id
      and l.id = any(places)
  ),
  shift as (
    select s.id, s.location_id, s.employee_id, s.job_id, s.scheduled_date,
      (s.scheduled_date + s.start_time) at time zone s.time_timezone as starts_at,
      (s.scheduled_date + s.end_time + case when s.crosses_midnight then interval '1 day' else interval '0 days' end)
        at time zone s.time_timezone as ends_at
    from public.schedule_published_shifts s
    join public.schedule_location_publications p on p.id = s.publication_id and p.status = 'current'
    join place on place.id = s.location_id
    where s.workspace_id = target_workspace_id
      -- Every zone's date is within a day of UTC's: keeps the date index range.
      and s.scheduled_date between (now() at time zone 'UTC')::date - 2 and (now() at time zone 'UTC')::date + 8
      and s.scheduled_date between place.today - 1 and place.today + 6
  ),
  person as (
    select e.id, e.user_id, btrim(coalesce(nullif(btrim(e.preferred_name), ''), e.first_name) || ' ' || e.last_name) as name
    from public.employee_profiles e
    where e.workspace_id = target_workspace_id
  ),
  -- Updates (S-225), the last seven days. A location-week published, its latest version.
  published as (
    select distinct on (p.location_id, p.week_start) p.id, p.location_id, p.week_start, p.published_at, p.published_by
    from public.schedule_location_publications p
    where p.workspace_id = target_workspace_id
      and p.location_id = any(places)
      and p.published_at > now() - interval '7 days'
    order by p.location_id, p.week_start, p.published_at desc
  ),
  -- A shift change a manager closed: approved, or declined where that ends it (a direct request).
  decided_exchange as (
    select distinct on (event.case_id) event.id, event.action, event.actor_user_id as decided_by, event.created_at, exchange.kind,
      exchange.owner_id, exchange.offered_snapshot, exchange.requested_snapshot
    from public.shift_exchange_events event
    join public.shift_exchange_cases exchange on exchange.id = event.case_id
    where event.workspace_id = target_workspace_id
      and event.created_at > now() - interval '7 days'
      and (event.action = 'transfer_completed' or (event.action = 'application_rejected' and exchange.audience = 'direct'))
      and ((exchange.offered_snapshot ->> 'location_id')::uuid = any(exchange_places)
        or (exchange.kind = 'swap' and (exchange.requested_snapshot ->> 'location_id')::uuid = any(exchange_places)))
    order by event.case_id, event.created_at desc
  ),
  joined as materialized (
    select invitation.id, invitation.employee_id, invitation.accepted_at
    from public.employee_invitations invitation
    where invitation.workspace_id = target_workspace_id
      and invitation.accepted_at > now() - interval '7 days'
  ),
  update_line as (
    select published.published_at as at, jsonb_build_object(
      'kind', 'published',
      'id', published.id::text,
      'at', published.published_at,
      'location_ids', jsonb_build_array(published.location_id),
      'by', (select person.name from person where person.user_id = published.published_by limit 1),
      'first_date', published.week_start,
      'last_date', published.week_start + 6,
      'shifts', (select count(*) from public.schedule_published_shifts s
        where s.workspace_id = target_workspace_id and s.location_id = published.location_id
          and s.scheduled_date between published.week_start and published.week_start + 6
          and s.publication_id = published.id)
    ) as line
    from published
    union all
    -- Time off's answers (time off rebuild D3), from the request itself: approved or declined in the
    -- last seven days and still so, read by whoever may answer it.
    select answered.decided_at, jsonb_build_object(
      'kind', 'time_off',
      'id', answered.id::text,
      'at', answered.decided_at,
      'location_ids', coalesce((
        select jsonb_agg(assignment.location_id order by assignment.is_primary desc, assignment.location_id)
        from public.employee_location_assignments assignment
        where assignment.employee_id = answered.employee_id and assignment.ended_at is null
          and assignment.location_id = any(places)
      ), '[]'::jsonb),
      'approved', answered.status = 'approved',
      'person', who.name,
      'by', (select person.name from person where person.user_id = answered.decided_by limit 1),
      'first_date', (answered.starts_at at time zone answered.time_timezone)::date,
      'last_date', ((answered.ends_at - interval '1 microsecond') at time zone answered.time_timezone)::date
    )
    from public.time_off_requests answered
    join person who on who.id = answered.employee_id
    where answered.workspace_id = target_workspace_id
      and answered.kind = 'leave'
      and answered.decided_at > now() - interval '7 days'
      and answered.status in ('approved', 'declined')
      and app_private.time_off_decider_why(me, answered.employee_id) is null
    union all
    select decided.created_at, jsonb_build_object(
      'kind', decided.kind,
      'id', decided.id::text,
      'at', decided.created_at,
      'location_ids', to_jsonb(array(
        select distinct side from unnest(array[(decided.offered_snapshot ->> 'location_id')::uuid,
          (decided.requested_snapshot ->> 'location_id')::uuid]) side
        where side = any(exchange_places))),
      'approved', decided.action = 'transfer_completed',
      'person', coalesce(owner.name, 'Somebody'),
      'by', (select person.name from person where person.user_id = decided.decided_by limit 1),
      'first_date', (decided.offered_snapshot ->> 'date')::date,
      'last_date', (decided.offered_snapshot ->> 'date')::date
    )
    from decided_exchange decided
    left join person owner on owner.id = decided.owner_id
    union all
    select joined.accepted_at, jsonb_build_object(
      'kind', 'joined',
      'id', joined.id::text,
      'at', joined.accepted_at,
      'location_ids', coalesce((
        select jsonb_agg(assignment.location_id order by assignment.is_primary desc, assignment.location_id)
        from public.employee_location_assignments assignment
        where assignment.employee_id = joined.employee_id and assignment.ended_at is null
          and assignment.location_id = any(places)
      ), '[]'::jsonb),
      'person', who.name
    )
    from joined
    join person who on who.id = joined.employee_id
    where who.user_id is distinct from actor_user_id
      and app_private.authz_check(me, employee_rule, null, joined.employee_id, null) is null
  ),
  -- Coming up (S-225), the next fourteen days. A day an announcement closes a location in view.
  closed as (
    select closure.announcement_id, closure.title, min(closure.closed_date) as first_date, max(closure.closed_date) as last_date,
      jsonb_agg(distinct closure.location_id) as location_ids
    from public.schedule_closures closure
    join place on place.id = closure.location_id
    where closure.workspace_id = target_workspace_id
      and closure.kind = 'closed'
      and closure.closed_date between place.today and place.today + 13
    group by closure.announcement_id, closure.title
  ),
  -- Time off as it is now (D1a): the days left of it, in the zone it was asked in. A piece that
  -- ends at midnight is that day's; the next fourteen days hold it.
  approved_off as materialized (
    select away.request_id as id, away.employee_id,
      greatest(min((lower(away.span) at time zone away.zone)::date), local_today) as first_date,
      least(max(((upper(away.span) - interval '1 microsecond') at time zone away.zone)::date), local_today + 13) as last_date
    from app_private.leave_spans(target_workspace_id,
      array(select e.id from public.employee_profiles e where e.workspace_id = target_workspace_id),
      tstzrange((local_today - 1)::timestamp at time zone 'UTC', (local_today + 15)::timestamp at time zone 'UTC', '[)')) away
    where not away.pending
      and (lower(away.span) at time zone away.zone)::date <= local_today + 13
      and ((upper(away.span) - interval '1 microsecond') at time zone away.zone)::date >= local_today
    group by away.request_id, away.employee_id
  ),
  -- Days past the next seven (those are in "Needs you") with no current publication.
  unpublished as (
    select place.id as location_id, min(day.date) as first_date, max(day.date) as last_date
    from place
    cross join lateral (select (place.today + offset_days)::date as date from generate_series(7, 13) offset_days) day
    where not exists (
      select 1 from public.schedule_location_publications publication
      where publication.location_id = place.id and publication.status = 'current'
        and day.date >= publication.week_start and day.date < publication.week_start + 7)
    group by place.id
  ),
  coming_line as (
    select closed.first_date, 1 as rank, jsonb_build_object(
      'kind', 'closed', 'id', closed.announcement_id::text, 'location_ids', closed.location_ids, 'name', closed.title,
      'first_date', closed.first_date, 'last_date', closed.last_date) as line
    from closed
    union all
    select off.first_date, 2, jsonb_build_object(
      'kind', 'time_off', 'id', off.id::text,
      'location_ids', coalesce((
        select jsonb_agg(assignment.location_id order by assignment.is_primary desc, assignment.location_id)
        from public.employee_location_assignments assignment
        where assignment.employee_id = off.employee_id and assignment.ended_at is null
          and assignment.location_id = any(places)
      ), '[]'::jsonb),
      'person', who.name, 'first_date', off.first_date, 'last_date', off.last_date)
    from approved_off off
    join person who on who.id = off.employee_id
    where app_private.time_off_reason(actor_user_id, target_workspace_id, 'requests.read', off.employee_id) is null
    union all
    select unpublished.first_date, 3, jsonb_build_object(
      'kind', 'unpublished', 'id', unpublished.location_id::text || ':' || unpublished.first_date::text,
      'location_ids', jsonb_build_array(unpublished.location_id),
      'first_date', unpublished.first_date, 'last_date', unpublished.last_date)
    from unpublished
  )
  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'now', now(),
    -- S-220: in the person's own order; a location they have not placed comes after, by name.
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', place.id,
        'name', place.name,
        'timezone', place.timezone,
        'today', place.today,
        -- Today's shifts there, last night's that run into it too: "on now" and the hours line.
        'today_shifts', coalesce((
          select jsonb_agg(jsonb_build_object('starts_at', shift.starts_at, 'ends_at', shift.ends_at,
            'open', shift.employee_id is null) order by shift.starts_at, shift.id)
          from shift
          where shift.location_id = place.id
            and shift.scheduled_date <= place.today
            and shift.ends_at > place.today::timestamp at time zone place.timezone
        ), '[]'::jsonb),
        -- S-163 (7): somebody in a Management job on a published shift there today.
        'floor_managers', coalesce((
          select jsonb_agg(jsonb_build_object('name', person.name, 'starts_at', shift.starts_at, 'ends_at', shift.ends_at)
            order by shift.starts_at, person.name)
          from shift
          join person on person.id = shift.employee_id
          join public.jobs job on job.id = shift.job_id
          join public.departments department on department.id = job.department_id and department.system_key = 'management'
          where shift.location_id = place.id
            and shift.scheduled_date <= place.today
            and shift.ends_at > place.today::timestamp at time zone place.timezone
        ), '[]'::jsonb),
        'week', (
          select jsonb_agg(jsonb_build_object(
            'date', day.date,
            'shifts', (select count(*) from shift where shift.location_id = place.id and shift.scheduled_date = day.date),
            'open', (select count(*) from shift where shift.location_id = place.id and shift.scheduled_date = day.date and shift.employee_id is null),
            'published', exists (
              select 1 from public.schedule_location_publications publication
              where publication.location_id = place.id and publication.status = 'current'
                and day.date >= publication.week_start and day.date < publication.week_start + 7)
          ) order by day.date)
          from (select (place.today + offset_days)::date as date from generate_series(0, 6) offset_days) day
        ),
        'open_shifts', coalesce((
          select jsonb_agg(jsonb_build_object('date', open_shift.scheduled_date, 'starts_at', open_shift.starts_at,
            'ends_at', open_shift.ends_at, 'job_name', open_shift.job_name) order by open_shift.starts_at)
          from (
            select shift.scheduled_date, shift.starts_at, shift.ends_at, job.name as job_name
            from shift join public.jobs job on job.id = shift.job_id
            where shift.location_id = place.id and shift.employee_id is null and shift.ends_at > now()
            order by shift.starts_at, shift.id
            limit 12
          ) open_shift
        ), '[]'::jsonb),
        -- S-206: whoever works here without a required document, as the documents rule lets the actor see.
        'missing_documents', coalesce((
          select jsonb_agg(jsonb_build_object('employee_id', missing.employee_id, 'name', missing.name,
            'document', missing.title, 'requirement_id', missing.id, 'status', missing.state)
            order by missing.name, missing.title, missing.id)
          from (
            select requirement.id, requirement.employee_id, person.name, requirement.title, obligation.state
            from public.employee_onboarding_requirements requirement
            join person on person.id = requirement.employee_id
            join public.employee_profiles profile on profile.id = requirement.employee_id and profile.archived_at is null
            cross join lateral (select app_private.document_obligation_state(requirement, now()) as state) obligation
            where requirement.workspace_id = target_workspace_id
              and requirement.kind = 'document'
              and requirement.required
              and not requirement.owner_excused
              and exists (
                select 1 from public.employee_location_assignments assignment
                where assignment.employee_id = requirement.employee_id and assignment.location_id = place.id
                  and assignment.ended_at is null)
              and obligation.state in ('missing', 'rejected', 'expired')
              and app_private.authz_check(me, documents_rule, null, requirement.employee_id, null) is null
            order by person.name, requirement.title, requirement.id
            limit 20
          ) missing
        ), '[]'::jsonb)
      ) order by array_position(coalesce(saved.location_order, '{}'::uuid[]), place.id) nulls last, place.name, place.id)
      from place
    ), '[]'::jsonb),
    -- Time off waiting on an answer the actor may read, with the person's locations in view.
    'time_off', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', request.id,
        'employee_id', request.employee_id,
        'employee_name', person.name,
        -- leave: time off asked for; cancel: approved time off its person asks to cancel (D7).
        'kind', request.kind,
        'first_date', request.first_date,
        'last_date', request.last_date,
        'location_ids', coalesce((
          select jsonb_agg(assignment.location_id order by assignment.is_primary desc, assignment.location_id)
          from public.employee_location_assignments assignment
          where assignment.employee_id = request.employee_id and assignment.ended_at is null
            and assignment.location_id = any(places)
        ), '[]'::jsonb)
      ) order by request.created_at, request.id)
      from (
        select waiting.* from (
          -- Waiting, and this person may answer it (time off rebuild D3). Time off waits until it starts; a
          -- cancellation until the time off ends (D7: cancellations are listed too).
          select r.id, r.employee_id, r.created_at, r.kind,
            (r.starts_at at time zone r.time_timezone)::date as first_date,
            ((r.ends_at - interval '1 microsecond') at time zone r.time_timezone)::date as last_date
          from public.time_off_requests r
          where r.workspace_id = target_workspace_id
            and r.status = 'pending'
            and case when r.kind = 'cancel' then r.ends_at else r.starts_at end > now()
            and app_private.time_off_decider_why(me, r.employee_id) is null
        ) waiting
        order by waiting.created_at, waiting.id
        limit 50
      ) request
      join person on person.id = request.employee_id
    ), '[]'::jsonb),
    -- S-220: the person's sections, the two new ones after what they placed.
    'layout', jsonb_build_object(
      'widget_order', to_jsonb(app_private.home_section_order(saved.widget_order)),
      'hidden_widget_ids', to_jsonb(array(
        select distinct value from unnest(coalesce(saved.hidden_widget_ids, '{}'::text[])) value
        where value = any(app_private.home_section_order(null))))
    ),
    'updates', coalesce((
      select jsonb_agg(item.line order by item.at desc, item.line ->> 'id')
      from (select * from update_line order by at desc, line ->> 'id' limit 30) item
    ), '[]'::jsonb),
    'coming_up', coalesce((
      select jsonb_agg(item.line order by item.first_date, item.rank, item.line ->> 'id')
      from (select * from coming_line order by first_date, rank, line ->> 'id' limit 30) item
    ), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_manager_home_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_member_avatar_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  photo text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.read', target_person => target_employee_id);

  select a.photo_path into photo
  from public.employee_profiles profile
  join public.workspace_memberships m on m.workspace_id = profile.workspace_id and m.user_id = profile.user_id
  join public.member_avatars a on a.membership_id = m.id
  where profile.id = target_employee_id and profile.workspace_id = target_workspace_id;

  return photo;
end;
$$;


ALTER FUNCTION "public"."get_member_avatar_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_lineups_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me uuid;
  assigned uuid[];
  places uuid[];
  mine_result jsonb;
  others_result jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee_hub.read');
  if target_date is null then
    raise exception 'a day is required' using errcode = '22023', hint = 'lineup.invalid_day';
  end if;
  select e.id into me from public.employee_profiles e
  where e.workspace_id = target_workspace_id and e.user_id = actor_user_id and e.archived_at is null;
  -- Where she works now: the others come from these locations only.
  assigned := array(
    select a.location_id from public.employee_location_assignments a
    where a.workspace_id = target_workspace_id and a.employee_id = me and a.ended_at is null);
  -- Only the locations with a published lineup that day where she works or has a shift or a lineup row: the
  -- read stays small. A wider set is harmless; the rows below decide.
  places := array(
    select distinct d.location_id from public.daily_lineups d
    where d.workspace_id = target_workspace_id and d.service_date = target_date
      and d.latest_version > 0 and not d.editing
      and (d.location_id = any (assigned)
        or exists (select 1 from public.schedule_published_shifts s
                   where s.workspace_id = target_workspace_id and s.employee_id = me
                     and s.scheduled_date = target_date and s.location_id = d.location_id)
        or exists (select 1 from public.daily_lineup_rows r
                   where r.workspace_id = target_workspace_id and r.employee_id = me
                     and r.service_date = target_date and r.location_id = d.location_id)));
  if me is null or cardinality(places) = 0 then
    return jsonb_build_object('workspace_id', target_workspace_id, 'date', target_date,
      'lineups', '[]'::jsonb, 'others', '[]'::jsonb);
  end if;

  select
    coalesce(jsonb_agg(base || jsonb_build_object(
        'acknowledged_at', (select to_jsonb(a.acknowledged_at) from public.daily_lineup_acknowledgements a
                            where a.version_id = (x ->> 'version_id')::uuid and a.employee_id = me),
        'mine', (select jsonb_agg(mine_rows.v) from (
                   select jsonb_build_object('start_time', r -> 'start_time', 'end_time', r -> 'end_time',
                     'crosses_midnight', r -> 'crosses_midnight', 'job_name', r -> 'job_name', 'job_color', r -> 'job_color',
                     'section_name', r -> 'section_name', 'label_names', r -> 'label_names',
                     'art_key', r -> 'art_key',
                     'called_off', r ->> 'called_off_at' is not null,
                     -- LINEUP-EDIT L2a: someone took her place (S-178 "Replaced").
                     'replaced', r ->> 'replaced_by_row_id' is not null) v
                   from jsonb_array_elements(x -> 'rows') r where (r ->> 'employee_id')::uuid = me) mine_rows))
      order by l ->> 'name', x ->> 'shift_type_name') filter (where on_it), '[]'::jsonb),
    -- Another lineup at her location: read whole, with no ticket and no acknowledgement of hers.
    coalesce(jsonb_agg(base order by l ->> 'name', x ->> 'shift_type_name')
      filter (where not on_it and (l ->> 'id')::uuid = any (assigned)), '[]'::jsonb)
  into mine_result, others_result
  from jsonb_array_elements(app_private.lineup_day(target_workspace_id, target_date, places) -> 'locations') l,
    jsonb_array_elements(l -> 'lineups') x,
    lateral (select exists (select 1 from jsonb_array_elements(x -> 'rows') r
                            where (r ->> 'employee_id')::uuid = me) as on_it) mine_check,
    lateral (select jsonb_build_object(
      'id', x -> 'id',
      'version_id', x -> 'version_id',
      'version', x -> 'version',
      'location', jsonb_build_object('id', l -> 'id', 'name', l -> 'name', 'timezone', l -> 'timezone'),
      'shift_type_id', x -> 'shift_type_id',
      'shift_type_name', x -> 'shift_type_name',
      'color', x -> 'color',
      'shared_at', x -> 'shared_at',
      'ask_ack', x -> 'ask_ack',
      'notes', x -> 'notes',
      -- The team as the lineup orders it: people only (an open shift is nobody's), no manager detail.
      'team', coalesce((select jsonb_agg(jsonb_build_object('employee_id', r -> 'employee_id', 'name', r -> 'name',
                   'job_name', r -> 'job_name', 'job_color', r -> 'job_color',
                   'department_name', r -> 'department_name', 'start_time', r -> 'start_time',
                   'end_time', r -> 'end_time', 'crosses_midnight', r -> 'crosses_midnight',
                   'section_name', r -> 'section_name', 'label_names', r -> 'label_names',
                   'called_off', r ->> 'called_off_at' is not null,
                   'art_key', r -> 'art_key',
                   'is_me', (r ->> 'employee_id')::uuid = me) order by o)
                 from jsonb_array_elements(x -> 'rows') with ordinality t(r, o)
                 -- A replaced person is not on the team; the one in her place is.
                 where r ->> 'employee_id' is not null and r ->> 'replaced_by_row_id' is null), '[]'::jsonb)
    ) as base) built
  where (x -> 'published')::boolean;

  return jsonb_build_object('workspace_id', target_workspace_id, 'date', target_date,
    'lineups', mine_result, 'others', others_result);
end;
$$;


ALTER FUNCTION "public"."get_my_lineups_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_feed_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_filter" "text" DEFAULT 'all'::"text", "target_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "target_before_id" "uuid" DEFAULT NULL::"uuid", "target_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  viewer uuid := actor_user_id;
  result jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'notifications.read_own');
  if target_filter is null or target_filter not in ('all', 'unread', 'needs_action')
     or target_limit is null or target_limit not between 1 and 100
     -- The next page starts after the last row: its time and its id, both or neither.
     or (target_before is null) <> (target_before_id is null) then
    raise exception 'valid list request required' using errcode = '22023', hint = 'notifications.invalid_list';
  end if;

  with mine as (
    select n.*, t.area, t.topic_key, t.level, t.needs_action
    from public.person_notifications n
    join public.notification_types t on t.key = n.type_key
    where n.user_id = viewer and (n.workspace_id = target_workspace_id or n.workspace_id is null)
  ),
  page as (
    select m.* from mine m
    where (target_before is null or (m.created_at, m.id) < (target_before, target_before_id))
      and (target_filter = 'all'
           or (target_filter = 'unread' and m.read_at is null)
           or (target_filter = 'needs_action' and m.needs_action and m.resolved_at is null))
    order by m.created_at desc, m.id desc
    limit target_limit + 1
  )
  select jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'workspace_id', p.workspace_id, 'type', p.type_key, 'area', p.area, 'topic', p.topic_key,
        'level', p.level, 'needs_action', p.needs_action, 'title', p.title, 'body', p.body, 'url', p.url,
        'data', p.data, 'actor_user_id', p.actor_user_id, 'subject_type', p.subject_type, 'subject_id', p.subject_id,
        'created_at', p.created_at, 'seen_at', p.seen_at, 'read_at', p.read_at,
        'resolved_at', p.resolved_at, 'resolution', p.resolution, 'resolved_by', p.resolved_by
      ) order by p.created_at desc, p.id desc)
      from (select * from page order by page.created_at desc, page.id desc limit target_limit) p
    ), '[]'::jsonb),
    'has_more', (select count(*) from page) > target_limit,
    'unseen_count', (select count(*) from mine where mine.seen_at is null),
    'unread_count', (select count(*) from mine where mine.read_at is null),
    'needs_action_count', (select count(*) from mine where mine.needs_action and mine.resolved_at is null)
  ) into result;
  return result;
end;
$$;


ALTER FUNCTION "public"."get_notification_feed_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_filter" "text", "target_before" timestamp with time zone, "target_before_id" "uuid", "target_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_preferences_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  held text[];
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'notifications.read_own');
  -- What the person hears: 'self', always, being a member; and the actions they hold somewhere in the
  -- workspace, as the core says: at a live location, or across it (the core's '{}', an owner's or an
  -- admin's even with no open location left).
  select array['self'] || coalesce(array_agg(x.a), '{}') into held
  from (select distinct unnest(t.heard_by) a from public.notification_types t) x
  where x.a <> 'self'
    and (cardinality(app_private.scope_set(actor_user_id, target_workspace_id, x.a)) > 0
         or app_private.authz_reason(actor_user_id, target_workspace_id, x.a, '{}') is null);

  select jsonb_build_object(
    'channels', jsonb_build_object(
      'in_app', jsonb_build_object('locked', true),
      'email', jsonb_build_object(
        'workspace_enabled', coalesce(s.email_enabled, true),
        'address_on_file', u.email is not null,
        'suppressed', exists (select 1 from public.notification_email_suppressions x where x.email = lower(u.email) and x.cleared_at is null)),
      'push', jsonb_build_object(
        'workspace_enabled', coalesce(s.push_enabled, true),
        'devices', (select count(*) from public.notification_push_subscriptions d where d.user_id = actor_user_id and d.revoked_at is null)),
      'sms', jsonb_build_object('available', app_private.sms_channel_open(), 'workspace_enabled', coalesce(s.sms_enabled, false))),
    'topics', coalesce((
      select jsonb_agg(jsonb_build_object(
        'key', o.key, 'name', o.name, 'level', o.level, 'description', o.description,
        'email', jsonb_build_object('choice', (select p.enabled from public.notification_preferences p
                   where p.workspace_id = target_workspace_id and p.user_id = actor_user_id and p.topic_key = o.key and p.channel = 'email'),
                 'default', o.email_default),
        'push', jsonb_build_object('choice', (select p.enabled from public.notification_preferences p
                   where p.workspace_id = target_workspace_id and p.user_id = actor_user_id and p.topic_key = o.key and p.channel = 'push'),
                 'default', o.push_default)
      ) order by o.position)
      from (
        select tp.key, tp.name, tp.position, tp.description,
          case when bool_and(t.level = 'optional') then 'optional' else 'important' end level,
          bool_or(t.default_email) email_default, bool_or(t.default_push) push_default
        from public.notification_topics tp
        join public.notification_types t on t.topic_key = tp.key and t.level <> 'required'
        where t.heard_by && held
          and not exists (select 1 from public.notification_workspace_muted_types m
                          where m.workspace_id = target_workspace_id and m.type_key = t.key)
        group by tp.key, tp.name, tp.position, tp.description
      ) o
    ), '[]'::jsonb)
  ) into result
  from auth.users u
  left join public.notification_workspace_settings s on s.workspace_id = target_workspace_id
  where u.id = actor_user_id;
  return result;
end;
$$;


ALTER FUNCTION "public"."get_notification_preferences_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_workspace_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.organization.write');
  select jsonb_build_object(
    'email_enabled', coalesce(s.email_enabled, true),
    'push_enabled', coalesce(s.push_enabled, true),
    'sms_enabled', coalesce(s.sms_enabled, false),
    'sms_available', app_private.sms_channel_open(),
    'optional', coalesce((
      select jsonb_agg(jsonb_build_object('key', t.key, 'area', t.area, 'description', t.description,
        'enabled', not exists (select 1 from public.notification_workspace_muted_types m
                               where m.workspace_id = target_workspace_id and m.type_key = t.key)) order by t.position)
      from public.notification_types t where t.level = 'optional'), '[]'::jsonb),
    'always_sent', coalesce((
      select jsonb_agg(jsonb_build_object('key', t.key, 'area', t.area, 'level', t.level, 'description', t.description) order by t.position)
      from public.notification_types t where t.level <> 'optional'), '[]'::jsonb)
  ) into result
  from (select 1) one
  left join public.notification_workspace_settings s on s.workspace_id = target_workspace_id;
  return result;
end;
$$;


