CREATE OR REPLACE FUNCTION "public"."leave_employee_onboarding_service"("target_user_id" "uuid", "expected_revision" integer, "target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_case public.employee_onboarding_cases%rowtype;
  target_membership public.workspace_memberships%rowtype;
begin
  perform app_private.authorize(target_user_id, app_private.onboarding_self_workspace(target_user_id, target_workspace_id, true), 'onboarding.self');

  select onboarding.* into target_case
  from public.employee_onboarding_cases onboarding
  where onboarding.id = app_private.employee_onboarding_case_id(target_user_id, target_workspace_id)
  for update;

  if target_case.id is null then
    raise exception 'onboarding unavailable' using errcode = 'P0002';
  end if;
  if target_case.revision <> expected_revision then
    raise exception 'onboarding changed; refresh required' using errcode = 'PT409', hint = 'onboarding.changed';
  end if;

  select membership.* into target_membership
  from public.workspace_memberships membership
  where membership.id = target_case.membership_id
    and membership.workspace_id = target_case.workspace_id
    and membership.user_id = target_user_id
  for update;

  if target_membership.id is null then
    raise exception 'workspace membership unavailable' using errcode = 'P0002';
  end if;
  if target_membership.status = 'active'::public.membership_status then
    raise exception 'active employees cannot leave onboarding' using errcode = '23514';
  end if;
  if target_membership.status <> 'pending_activation'::public.membership_status then
    raise exception 'pending onboarding membership required' using errcode = '23514';
  end if;
  if target_case.status = 'approved'::public.employee_onboarding_case_status then
    raise exception 'approved onboarding cannot be cancelled' using errcode = '22023';
  end if;

  perform set_config('app.workspace_closure', 'on', true);

  update public.workspace_memberships
  set status = 'suspended'::public.membership_status,
      updated_at = now()
  where id = target_membership.id
    and workspace_id = target_case.workspace_id;

  update public.employee_onboarding_cases
  set status = 'cancelled'::public.employee_onboarding_case_status,
      revision = revision + 1,
      updated_at = now()
  where id = target_case.id
  returning * into target_case;

  insert into public.onboarding_events (
    workspace_id, employee_id, case_id, actor_user_id, action, target_type, target_id
  ) values (
    target_case.workspace_id, target_case.employee_id, target_case.id, target_user_id,
    'onboarding.left', 'onboarding_case', target_case.id::text
  );

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_case.workspace_id, target_user_id, 'employee_onboarding.left',
    'workspace_membership', target_membership.id::text,
    jsonb_build_object('employee_id', target_case.employee_id, 'case_id', target_case.id)
  );

  return jsonb_build_object(
    'status', 'left',
    'workspace_id', target_case.workspace_id,
    'employee_id', target_case.employee_id,
    'membership_id', target_membership.id,
    'revision', target_case.revision
  );
end;
$$;


ALTER FUNCTION "public"."leave_employee_onboarding_service"("target_user_id" "uuid", "expected_revision" integer, "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lineup_command_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "command_id" "uuid", "kind" "text", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  prior public.lineup_commands;
  item jsonb;
  place public.locations;
  day date;
  type_id uuid;
  header public.daily_lineups;
  live jsonb;
  dealt jsonb;
  version_row public.daily_lineup_versions;
  ask boolean;
  done jsonb := '[]'::jsonb;
  told uuid[] := '{}';
  shared_lineups integer := 0;
  shared_names text[] := '{}';
  shared_day date;
  result jsonb;
begin
  if command_id is null or kind is null or kind not in ('share', 'unpublish')
     or jsonb_typeof(payload) is distinct from 'object' or jsonb_typeof(payload -> 'lineups') is distinct from 'array'
     or jsonb_array_length(payload -> 'lineups') = 0 or jsonb_array_length(payload -> 'lineups') > 50
     or (kind = 'share' and jsonb_typeof(payload -> 'ask_ack') is distinct from 'boolean') then
    raise exception 'Choose lineups to publish or unpublish' using errcode = '22023', hint = 'lineup.invalid_command';
  end if;
  -- The core first, every location named: a stranger learns nothing, not even a command id.
  for item in select value from jsonb_array_elements(payload -> 'lineups') loop
    if jsonb_typeof(item) is distinct from 'object' or item ->> 'location_id' is null or item ->> 'service_date' is null
       or (item ->> 'location_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or (item ->> 'service_date') !~ '^\d{4}-\d{2}-\d{2}$'
       or (item ->> 'shift_type_id' is not null
           and (item ->> 'shift_type_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
      raise exception 'Choose lineups to publish or unpublish' using errcode = '22023', hint = 'lineup.invalid_command';
    end if;
    perform app_private.authorize(actor_user_id, target_workspace_id, 'lineup.share',
      target_locations => array[(item ->> 'location_id')::uuid]);
  end loop;
  -- One command is one day: its notice names that day.
  if (select count(distinct x ->> 'service_date') from jsonb_array_elements(payload -> 'lineups') x) > 1 then
    raise exception 'Choose lineups of one day' using errcode = '22023', hint = 'lineup.one_day';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text, 1017));
  select * into prior from public.lineup_commands c
  where c.workspace_id = target_workspace_id and c.actor_user_id = lineup_command_service.actor_user_id
    and c.command_id = lineup_command_service.command_id;
  if prior.command_id is not null then
    if prior.kind <> lineup_command_service.kind or prior.payload <> lineup_command_service.payload then
      raise exception 'This command id was used for another command' using errcode = '22023', hint = 'lineup.command_reused';
    end if;
    return prior.result;
  end if;

  ask := coalesce((payload ->> 'ask_ack')::boolean, true);
  for item in select value from jsonb_array_elements(payload -> 'lineups') loop
    select * into place from public.locations l
    where l.id = (item ->> 'location_id')::uuid and l.workspace_id = target_workspace_id;
    day := (item ->> 'service_date')::date;
    type_id := (item ->> 'shift_type_id')::uuid;
    if type_id is not null and not exists (
      select 1 from public.shift_types t where t.id = type_id and t.workspace_id = target_workspace_id
        and (t.deleted_at is null or lineup_command_service.kind = 'unpublish')
    ) then
      -- An unknown shift type is an unknown lineup: the same answer as one out of reach. A deleted one is not
      -- published again, but a lineup published before it went can still be taken back.
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'lineup.share';
    end if;
    if day < (now() at time zone place.timezone)::date then
      raise exception 'This day has passed' using errcode = '22023', hint = 'lineup.past_day';
    end if;
    if exists (select 1 from public.schedule_closures c
               where c.workspace_id = target_workspace_id and c.location_id = place.id and c.closed_date = day
                 and c.kind = 'closed') then
      raise exception 'This location is closed that day' using errcode = '22023', hint = 'lineup.closed_day';
    end if;

    select * into header from public.daily_lineups d
    where d.workspace_id = target_workspace_id and d.location_id = place.id and d.service_date = day
      and d.shift_type_id is not distinct from type_id
    for update;

    if lineup_command_service.kind = 'share' then
      if not exists (select 1 from public.schedule_location_publications publication
                     where publication.workspace_id = target_workspace_id and publication.location_id = place.id
                       and publication.status = 'current'
                       and publication.week_start = app_private.lineup_week_start(target_workspace_id, day)) then
        raise exception 'Publish this week''s Schedule first' using errcode = '22023', hint = 'lineup.week_not_published';
      end if;
      if header.id is not null and header.latest_version > 0 and not header.editing then
        -- Already published: it stays as it is, its acknowledgements too.
        done := done || jsonb_build_object('lineup_id', header.id, 'version', header.latest_version, 'status', 'unchanged');
        continue;
      end if;
      if header.id is null then
        insert into public.daily_lineups (workspace_id, location_id, service_date, shift_type_id, updated_by)
        values (target_workspace_id, place.id, day, type_id, actor_user_id)
        returning * into header;
      end if;
      -- The lineup as it is now, for the record; employees read the live day, never this.
      select x into live
      from jsonb_array_elements(app_private.lineup_day(target_workspace_id, day, array[place.id]) -> 'locations') l,
        jsonb_array_elements(l -> 'lineups') x
      where (x ->> 'shift_type_id')::uuid is not distinct from type_id;
      -- The drawings as shown now are this lineup's from here on (AVATAR-IKON slice 4); written ones stay.
      dealt := app_private.lineup_deal(target_workspace_id, place.id, day, type_id, live -> 'rows');
      insert into public.daily_lineup_drawings (lineup_id, workspace_id, employee_id, job_id, art_key)
      select header.id, target_workspace_id, split_part(d.key, ':', 1)::uuid, split_part(d.key, ':', 2)::uuid, d.value
      from jsonb_each_text(dealt) d
      where d.value is not null
      on conflict do nothing;
      -- The rows as published: who has the app, who read an earlier version and the drawings are the day's, not
      -- the record's.
      live := jsonb_build_object('notes', live -> 'notes', 'rows', coalesce(
        (select jsonb_agg(r - 'has_app' - 'acknowledged_at' - 'art_key' order by o)
         from jsonb_array_elements(live -> 'rows') with ordinality t(r, o)), '[]'::jsonb));
      insert into public.daily_lineup_versions (workspace_id, lineup_id, version, shared_by, ask_ack, snapshot, fingerprint)
      values (target_workspace_id, header.id, header.latest_version + 1, actor_user_id, ask, live,
        encode(sha256(convert_to(live::text, 'UTF8')), 'hex'))
      returning * into version_row;
      update public.daily_lineups d
      set latest_version = version_row.version, editing = false, revision = d.revision + 1,
        updated_at = now(), updated_by = actor_user_id
      where d.id = header.id;
      done := done || jsonb_build_object('lineup_id', header.id, 'version', version_row.version,
        'version_id', version_row.id, 'status', 'shared');
      -- Who hears of it: everybody on it with an account (notify_rows drops whoever is not a member now).
      told := told || array(
        select e.user_id from jsonb_array_elements(live -> 'rows') r
        join public.employee_profiles e on e.id = (r ->> 'employee_id')::uuid and e.workspace_id = target_workspace_id
        where e.user_id is not null);
      shared_lineups := shared_lineups + 1;
      shared_names := shared_names || coalesce((select t.name from public.shift_types t where t.id = type_id), '');
      shared_day := case when shared_day is null or shared_day = day then day else shared_day end;
    else
      if header.id is null or header.latest_version = 0 then
        raise exception 'This lineup is not published' using errcode = '22023', hint = 'lineup.not_shared';
      end if;
      if not header.editing then
        update public.daily_lineups d
        set editing = true, revision = d.revision + 1, updated_at = now(), updated_by = actor_user_id
        where d.id = header.id;
        -- LINEUP-EDIT L2b (Mert 2026-10-20, "Edit'e kadar kalsın"): a section removed while this lineup was
        -- published leaves its rows now that it is a draft again.
        update public.daily_lineup_rows r set section_id = null, updated_at = now(), updated_by = actor_user_id
        from public.location_sections s
        where r.lineup_id = header.id and s.id = r.section_id and s.archived_at is not null;
      end if;
      -- Unpublish tells nobody (PLAN §9).
      done := done || jsonb_build_object('lineup_id', header.id, 'version', header.latest_version, 'status', 'unpublished');
    end if;
  end loop;

  result := jsonb_build_object('command_id', command_id, 'kind', kind, 'lineups', done);
  insert into public.lineup_commands (workspace_id, actor_user_id, command_id, kind, payload, result)
  values (target_workspace_id, actor_user_id, command_id, kind, payload, result);

  -- One notice per person per share, however many lineups it published (PLAN §9; lineup.shared). Its event key
  -- is the transaction's, so a share sent again under the same command id (answered above) tells nobody again.
  if shared_lineups > 0 then
    perform app_private.lineup_tell('lineup.shared', target_workspace_id,
      array(select distinct x from unnest(told) x),
      'lineup_published:' || target_workspace_id::text || ':' || txid_current()::text,
      case when shared_lineups = 1
        then 'Your ' || coalesce(nullif(shared_names[1], '') || ' ', '') || 'lineup is ready'
        else 'Your lineups for ' || to_char(shared_day, 'Dy, Mon FMDD') || ' are ready' end
        || case when ask then ' · please acknowledge' else '' end,
      null,
      '/app/employee-hub/schedule/lineup?date=' || to_char(shared_day, 'YYYY-MM-DD'),
      actor_user_id, 'lineup_share', command_id,
      jsonb_build_object('date', shared_day, 'ask_ack', ask,
        'lineup_ids', (select jsonb_agg(d -> 'lineup_id') from jsonb_array_elements(done) d where d ->> 'status' = 'shared')));
  end if;
  return result;
end;
$_$;


ALTER FUNCTION "public"."lineup_command_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "command_id" "uuid", "kind" "text", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lineup_edit_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "command_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  prior public.lineup_commands;
  place public.locations;
  day date;
  type_id uuid;
  header public.daily_lineups;
  target jsonb;
  edit jsonb := payload -> 'row';
  notes jsonb := payload -> 'notes';
  -- LINEUP-EDIT L3a: who is added or put in a place.
  person jsonb := payload -> 'person';
  who uuid;
  hours_in time;
  hours_out time;
  place_row uuid;
  row_id uuid;
  label uuid;
  section uuid;
  typed text;
  result jsonb;
  uuid_shape constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  time_shape constant text := '^([01][0-9]|2[0-3]):[0-5][0-9]$';
begin
  if command_id is null or jsonb_typeof(payload) is distinct from 'object'
     or payload ->> 'action' is null
     or payload ->> 'action' not in ('set_row', 'set_notes', 'call_off', 'call_in', 'add_person', 'replace', 'undo_replace')
     or payload ->> 'location_id' is null or (payload ->> 'location_id') !~* uuid_shape
     or payload ->> 'service_date' is null or (payload ->> 'service_date') !~ '^\d{4}-\d{2}-\d{2}$'
     or (payload ->> 'shift_type_id' is not null and (payload ->> 'shift_type_id') !~* uuid_shape)
     or (payload ->> 'action' in ('set_row', 'call_off', 'call_in', 'replace', 'undo_replace')
         and (jsonb_typeof(edit) is distinct from 'object'
         or ((edit ->> 'source_shift_id') is null) = ((edit ->> 'row_id') is null)
         or coalesce(edit ->> 'source_shift_id', edit ->> 'row_id') !~* uuid_shape
         or (edit ? 'save_section' and jsonb_typeof(edit -> 'save_section') is distinct from 'boolean')))
     or (payload ->> 'action' = 'undo_replace' and edit ->> 'row_id' is null)
     or (payload ->> 'action' in ('add_person', 'replace') and (jsonb_typeof(person) is distinct from 'object'
         or person ->> 'employee_id' is null or (person ->> 'employee_id') !~* uuid_shape))
     or (payload ->> 'action' = 'add_person' and (person ->> 'job_id' is null or (person ->> 'job_id') !~* uuid_shape))
     or (payload ->> 'action' = 'set_notes' and jsonb_typeof(notes) is distinct from 'object') then
    raise exception 'Choose what to change in the lineup' using errcode = '22023', hint = 'lineup.invalid_command';
  end if;
  -- The core first: a stranger learns nothing, not even a command id.
  perform app_private.authorize(actor_user_id, target_workspace_id, 'lineup.share',
    target_locations => array[(payload ->> 'location_id')::uuid]);

  perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text, 1017));
  select * into prior from public.lineup_commands c
  where c.workspace_id = target_workspace_id and c.actor_user_id = lineup_edit_service.actor_user_id
    and c.command_id = lineup_edit_service.command_id;
  if prior.command_id is not null then
    if prior.kind <> 'edit' or prior.payload <> lineup_edit_service.payload then
      raise exception 'This command id was used for another command' using errcode = '22023', hint = 'lineup.command_reused';
    end if;
    return prior.result;
  end if;

  select * into place from public.locations l
  where l.id = (payload ->> 'location_id')::uuid and l.workspace_id = target_workspace_id;
  day := (payload ->> 'service_date')::date;
  type_id := (payload ->> 'shift_type_id')::uuid;
  if type_id is not null and not exists (
    select 1 from public.shift_types t where t.id = type_id and t.workspace_id = target_workspace_id and t.deleted_at is null
  ) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'lineup.share';
  end if;
  if day < (now() at time zone place.timezone)::date then
    raise exception 'This day has passed' using errcode = '22023', hint = 'lineup.past_day';
  end if;
  if exists (select 1 from public.schedule_closures c
             where c.workspace_id = target_workspace_id and c.location_id = place.id and c.closed_date = day
               and c.kind = 'closed') then
    raise exception 'This location is closed that day' using errcode = '22023', hint = 'lineup.closed_day';
  end if;

  select * into header from public.daily_lineups d
  where d.workspace_id = target_workspace_id and d.location_id = place.id and d.service_date = day
    and d.shift_type_id is not distinct from type_id
  for update;
  if header.id is not null and header.latest_version > 0 and not header.editing then
    raise exception 'Take the lineup back with Edit first' using errcode = '22023', hint = 'lineup.live';
  end if;
  if app_private.lineup_started(target_workspace_id, place.id, day, type_id, now()) then
    raise exception 'This shift has started' using errcode = '22023', hint = 'lineup.started';
  end if;

  -- LINEUP-EDIT L3a: the row a row action names, as the day reads it (set_row's, now shared).
  if payload ->> 'action' in ('set_row', 'call_off', 'call_in', 'replace', 'undo_replace') then
    -- The row as the day reads it: on this lineup, or it is out of reach (an unknown row gets the same answer).
    select r into target
    from jsonb_array_elements(app_private.lineup_day(target_workspace_id, day, array[place.id]) -> 'locations') l,
      jsonb_array_elements(l -> 'lineups') x, jsonb_array_elements(x -> 'rows') r
    where (x ->> 'shift_type_id')::uuid is not distinct from type_id
      and (r ->> 'employee_id') is not null
      and ((edit ? 'source_shift_id' and r ->> 'source_shift_id' = edit ->> 'source_shift_id')
        or (edit ? 'row_id' and r ->> 'id' = edit ->> 'row_id' and (r -> 'lineup_only')::boolean));
    if target is null then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'lineup.share';
    end if;
  end if;
  -- LINEUP-EDIT L3a: who is added or put in a place: someone this lineup may take, not on it already in any way
  -- (called off: Call in brings her back; replaced: Undo does).
  if payload ->> 'action' in ('add_person', 'replace') then
    who := (person ->> 'employee_id')::uuid;
    if not app_private.lineup_staff_eligible(target_workspace_id, place.id, who) then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'lineup.share';
    end if;
    if exists (
      select 1
      from jsonb_array_elements(app_private.lineup_day(target_workspace_id, day, array[place.id]) -> 'locations') l,
        jsonb_array_elements(l -> 'lineups') x, jsonb_array_elements(x -> 'rows') r
      where (x ->> 'shift_type_id')::uuid is not distinct from type_id and (r ->> 'employee_id')::uuid = who
    ) then
      raise exception 'This person is on this lineup already' using errcode = '22023', hint = 'lineup.already_on';
    end if;
  end if;
  -- Called off or replaced, a person isn't on the lineup to be called off or replaced (Call in brings one back);
  -- a place taken from someone who took a place goes back the way it came, the last one first.
  if payload ->> 'action' in ('call_off', 'replace')
     and (target ->> 'called_off_at' is not null or target ->> 'replaced_by_row_id' is not null)
     or payload ->> 'action' in ('call_in', 'undo_replace') and target ->> 'replaced_by_row_id' is not null then
    raise exception 'This person isn''t on the lineup now' using errcode = '22023', hint = 'lineup.row_out';
  end if;

  if payload ->> 'action' = 'set_row' then
    if edit ? 'starts' or edit ? 'ends' then
      if (edit ->> 'starts' is null) <> (edit ->> 'ends' is null)
         or (edit ->> 'starts' is not null and ((edit ->> 'starts') !~ time_shape or (edit ->> 'ends') !~ time_shape
             or edit ->> 'starts' = edit ->> 'ends'))
         or (edit ->> 'starts' is null and (target -> 'lineup_only')::boolean) then
        raise exception 'Use a time like 4:30 PM' using errcode = '22023', hint = 'lineup.invalid_hours';
      end if;
    end if;
    if edit ? 'job_id' and (edit ->> 'job_id' is null and (target -> 'lineup_only')::boolean
        or edit ->> 'job_id' is not null and ((edit ->> 'job_id') !~* uuid_shape or not exists (
          select 1 from public.jobs j where j.id = (edit ->> 'job_id')::uuid and j.workspace_id = target_workspace_id
            and j.archived_at is null))) then
      raise exception 'Choose a position' using errcode = '22023', hint = 'lineup.invalid_job';
    end if;
    if edit ? 'label_ids' then
      if edit -> 'label_ids' <> 'null'::jsonb and jsonb_typeof(edit -> 'label_ids') is distinct from 'array' then
        raise exception 'Choose labels' using errcode = '22023', hint = 'lineup.invalid_label';
      end if;
      for label in select (value #>> '{}')::uuid from jsonb_array_elements(coalesce(nullif(edit -> 'label_ids', 'null'::jsonb), '[]')) loop
        if not exists (select 1 from public.shift_labels s where s.id = label and s.workspace_id = target_workspace_id
                         and s.archived_at is null and s.deleted_at is null) then
          raise exception 'Choose labels' using errcode = '22023', hint = 'lineup.invalid_label';
        end if;
      end loop;
    end if;
    if edit ? 'section_id' and edit ->> 'section_id' is not null and ((edit ->> 'section_id') !~* uuid_shape or not exists (
         select 1 from public.location_sections s where s.id = (edit ->> 'section_id')::uuid
           and s.location_id = place.id and s.workspace_id = target_workspace_id and s.archived_at is null)) then
      raise exception 'Choose one of this location''s sections' using errcode = '22023', hint = 'lineup.invalid_section';
    end if;
    -- LINEUP-EDIT L2b: "Other…", a name typed in this lineup only (S-178 madde 4).
    if edit ? 'section_name' then
      if edit ? 'section_id' then
        raise exception 'Choose one of this location''s sections' using errcode = '22023', hint = 'lineup.invalid_section';
      end if;
      if edit -> 'section_name' <> 'null'::jsonb then
        typed := btrim(edit ->> 'section_name');
        if jsonb_typeof(edit -> 'section_name') <> 'string' or char_length(typed) not between 1 and 40 then
          raise exception 'Name the section in 40 characters or fewer' using errcode = '22023',
            hint = 'lineup.invalid_section_name';
        end if;
        -- The location's section of that name, if it has one; "Save to sections" adds it.
        select s.id into section from public.location_sections s
        where s.workspace_id = target_workspace_id and s.location_id = place.id and s.archived_at is null
          and lower(btrim(s.name)) = lower(typed);
        if section is null and (edit -> 'save_section') = 'true'::jsonb then
          insert into public.location_sections (workspace_id, location_id, name, sort_order)
          select target_workspace_id, place.id, typed, coalesce(max(s.sort_order) + 1, 0)
          from public.location_sections s
          where s.workspace_id = target_workspace_id and s.location_id = place.id and s.archived_at is null
          returning id into section;
        end if;
      end if;
    end if;

    if header.id is null then
      insert into public.daily_lineups (workspace_id, location_id, service_date, shift_type_id, updated_by)
      values (target_workspace_id, place.id, day, type_id, actor_user_id)
      returning * into header;
    end if;
    row_id := (target ->> 'id')::uuid;
    if row_id is null then
      insert into public.daily_lineup_rows (workspace_id, lineup_id, location_id, service_date, source_shift_id, updated_by)
      values (target_workspace_id, header.id, place.id, day, (target ->> 'source_shift_id')::uuid, actor_user_id)
      returning id into row_id;
    end if;
    update public.daily_lineup_rows r set
      job_id = case when edit ? 'job_id' then (edit ->> 'job_id')::uuid else r.job_id end,
      label_ids = case when edit ? 'label_ids' then
          case when edit -> 'label_ids' = 'null'::jsonb then null
            else array(select (value #>> '{}')::uuid from jsonb_array_elements(edit -> 'label_ids')) end
        else r.label_ids end,
      starts = case when edit ? 'starts' then (edit ->> 'starts')::time else r.starts end,
      ends = case when edit ? 'ends' then (edit ->> 'ends')::time else r.ends end,
      section_id = case when edit ? 'section_name' then section
        when edit ? 'section_id' then (edit ->> 'section_id')::uuid else r.section_id end,
      section_name = case when edit ? 'section_name' then case when section is null then typed end
        when edit ? 'section_id' then null else r.section_name end,
      updated_at = now(), updated_by = actor_user_id
    where r.id = row_id;
  elsif payload ->> 'action' = 'set_notes' then
    if char_length(coalesce(notes ->> 'specials', '')) > 500 or char_length(coalesce(notes ->> 'n86', '')) > 500
       or char_length(coalesce(notes ->> 'shift_notes', '')) > 1000 then
      raise exception 'This note is too long' using errcode = '22023', hint = 'lineup.note_too_long';
    end if;
    if header.id is null then
      insert into public.daily_lineups (workspace_id, location_id, service_date, shift_type_id, updated_by)
      values (target_workspace_id, place.id, day, type_id, actor_user_id)
      returning * into header;
    end if;
    update public.daily_lineups d set
      specials = case when notes ? 'specials' then coalesce(notes ->> 'specials', '') else d.specials end,
      n86 = case when notes ? 'n86' then coalesce(notes ->> 'n86', '') else d.n86 end,
      shift_notes = case when notes ? 'shift_notes' then coalesce(notes ->> 'shift_notes', '') else d.shift_notes end
    where d.id = header.id;
  -- LINEUP-EDIT L3a: Call off and Call in (S-178 madde 5).
  elsif payload ->> 'action' in ('call_off', 'call_in') then
    if header.id is null then
      insert into public.daily_lineups (workspace_id, location_id, service_date, shift_type_id, updated_by)
      values (target_workspace_id, place.id, day, type_id, actor_user_id)
      returning * into header;
    end if;
    row_id := (target ->> 'id')::uuid;
    if row_id is null then
      insert into public.daily_lineup_rows (workspace_id, lineup_id, location_id, service_date, source_shift_id, updated_by)
      values (target_workspace_id, header.id, place.id, day, (target ->> 'source_shift_id')::uuid, actor_user_id)
      returning id into row_id;
    end if;
    update public.daily_lineup_rows r set
      called_off_at = case when payload ->> 'action' = 'call_off' then coalesce(r.called_off_at, now()) end,
      called_off_by = case when payload ->> 'action' = 'call_off' then coalesce(r.called_off_by, actor_user_id) end,
      updated_at = now(), updated_by = actor_user_id
    where r.id = row_id;
  -- LINEUP-EDIT L3a: Add Staff (S-178 madde 6): a person in the lineup only, the Schedule untouched.
  elsif payload ->> 'action' = 'add_person' then
    if not exists (select 1 from public.jobs j where j.id = (person ->> 'job_id')::uuid
                     and j.workspace_id = target_workspace_id and j.archived_at is null) then
      raise exception 'Choose a position' using errcode = '22023', hint = 'lineup.invalid_job';
    end if;
    if (person ->> 'starts' is null) <> (person ->> 'ends' is null)
       or (person ->> 'starts' is not null and ((person ->> 'starts') !~ time_shape or (person ->> 'ends') !~ time_shape
           or person ->> 'starts' = person ->> 'ends')) then
      raise exception 'Use a time like 4:30 PM' using errcode = '22023', hint = 'lineup.invalid_hours';
    end if;
    -- No hours sent: someone in that position on this lineup, else the shift type's.
    if person ->> 'starts' is not null then
      hours_in := (person ->> 'starts')::time;
      hours_out := (person ->> 'ends')::time;
    else
      select (r ->> 'start_time')::time, (r ->> 'end_time')::time into hours_in, hours_out
      from jsonb_array_elements(app_private.lineup_day(target_workspace_id, day, array[place.id]) -> 'locations') l,
        jsonb_array_elements(l -> 'lineups') x, jsonb_array_elements(x -> 'rows') r
      where (x ->> 'shift_type_id')::uuid is not distinct from type_id and r ->> 'job_id' = person ->> 'job_id'
        and r ->> 'employee_id' is not null and r ->> 'called_off_at' is null and r ->> 'replaced_by_row_id' is null
      order by r ->> 'start_time'
      limit 1;
      if hours_in is null then
        select t.default_start_time, t.default_end_time into hours_in, hours_out
        from public.shift_types t where t.id = type_id and t.workspace_id = target_workspace_id;
      end if;
      if hours_in is null or hours_out is null then
        raise exception 'Use a time like 4:30 PM' using errcode = '22023', hint = 'lineup.invalid_hours';
      end if;
    end if;
    if header.id is null then
      insert into public.daily_lineups (workspace_id, location_id, service_date, shift_type_id, updated_by)
      values (target_workspace_id, place.id, day, type_id, actor_user_id)
      returning * into header;
    end if;
    insert into public.daily_lineup_rows (workspace_id, lineup_id, location_id, service_date, employee_id, job_id,
      starts, ends, updated_by)
    values (target_workspace_id, header.id, place.id, day, who, (person ->> 'job_id')::uuid, hours_in, hours_out,
      actor_user_id)
    returning id into row_id;
  -- LINEUP-EDIT L3a: Replace (S-178 madde 7): the person takes the row's place, the row is Replaced.
  elsif payload ->> 'action' = 'replace' then
    if header.id is null then
      insert into public.daily_lineups (workspace_id, location_id, service_date, shift_type_id, updated_by)
      values (target_workspace_id, place.id, day, type_id, actor_user_id)
      returning * into header;
    end if;
    place_row := (target ->> 'id')::uuid;
    if place_row is null then
      insert into public.daily_lineup_rows (workspace_id, lineup_id, location_id, service_date, source_shift_id, updated_by)
      values (target_workspace_id, header.id, place.id, day, (target ->> 'source_shift_id')::uuid, actor_user_id)
      returning id into place_row;
    end if;
    insert into public.daily_lineup_rows (workspace_id, lineup_id, location_id, service_date, employee_id, job_id,
      starts, ends, label_ids, section_id, section_name, sort_order, updated_by)
    values (target_workspace_id, header.id, place.id, day, who, (target ->> 'job_id')::uuid,
      (target ->> 'start_time')::time, (target ->> 'end_time')::time,
      array(select (value #>> '{}')::uuid from jsonb_array_elements(coalesce(nullif(target -> 'label_ids', 'null'::jsonb), '[]'))),
      (target ->> 'section_id')::uuid,
      case when target ->> 'section_id' is null then target ->> 'section_name' end,
      (target ->> 'sort_order')::integer, actor_user_id)
    returning id into row_id;
    update public.daily_lineup_rows r set replaced_by_row_id = row_id, updated_at = now(), updated_by = actor_user_id
    where r.id = place_row;
  -- LINEUP-EDIT L3a: Undo (S-178 madde 7): the place goes back; who took it leaves the lineup.
  else
    if not exists (select 1 from public.daily_lineup_rows r
                   where r.workspace_id = target_workspace_id and r.replaced_by_row_id = (target ->> 'id')::uuid) then
      raise exception 'This person took nobody''s place' using errcode = '22023', hint = 'lineup.not_replacing';
    end if;
    update public.daily_lineup_rows r set replaced_by_row_id = null, updated_at = now(), updated_by = actor_user_id
    where r.workspace_id = target_workspace_id and r.replaced_by_row_id = (target ->> 'id')::uuid;
    -- A person added in the lineup only: the row goes (target is lineup_only; header is its lineup).
    delete from public.daily_lineup_rows r where r.id = (target ->> 'id')::uuid and r.source_shift_id is null;
  end if;

  update public.daily_lineups d set revision = d.revision + 1, updated_at = now(), updated_by = actor_user_id
  where d.id = header.id;
  result := jsonb_build_object('command_id', command_id, 'kind', 'edit', 'lineup_id', header.id, 'row_id', row_id);
  insert into public.lineup_commands (workspace_id, actor_user_id, command_id, kind, payload, result)
  values (target_workspace_id, actor_user_id, command_id, 'edit', payload, result);
  return result;
end;
$_$;


ALTER FUNCTION "public"."lineup_edit_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "command_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lineup_sections_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  place public.locations;
  section public.location_sections;
  typed text;
  wanted uuid[];
  uuid_shape constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
begin
  if jsonb_typeof(payload) is distinct from 'object'
     or payload ->> 'action' is null or payload ->> 'action' not in ('add', 'rename', 'reorder', 'remove')
     or payload ->> 'location_id' is null or (payload ->> 'location_id') !~* uuid_shape
     or (payload ->> 'action' in ('rename', 'remove')
         and (payload ->> 'section_id' is null or (payload ->> 'section_id') !~* uuid_shape))
     or (payload ->> 'action' in ('add', 'rename') and jsonb_typeof(payload -> 'name') is distinct from 'string')
     or (payload ->> 'action' = 'reorder' and (jsonb_typeof(payload -> 'section_ids') is distinct from 'array'
         or exists (select 1 from jsonb_array_elements(payload -> 'section_ids') v
                    where jsonb_typeof(v) <> 'string' or (v #>> '{}') !~* uuid_shape))) then
    raise exception 'Choose what to change in the sections' using errcode = '22023', hint = 'lineup.invalid_command';
  end if;
  -- The core first: a stranger learns nothing.
  perform app_private.authorize(actor_user_id, target_workspace_id, 'lineup.share',
    target_locations => array[(payload ->> 'location_id')::uuid]);
  -- The lineup's edits and the sections, one at a time.
  perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text, 1017));

  select * into place from public.locations l
  where l.id = (payload ->> 'location_id')::uuid and l.workspace_id = target_workspace_id;
  if place.id is null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'lineup.share';
  end if;
  if payload ->> 'action' in ('rename', 'remove') then
    -- Another location's section, or none, gets the same answer.
    select * into section from public.location_sections s
    where s.id = (payload ->> 'section_id')::uuid and s.workspace_id = target_workspace_id and s.location_id = place.id
      and (s.archived_at is null or payload ->> 'action' = 'remove');
    if section.id is null then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'lineup.share';
    end if;
  end if;
  if payload ->> 'action' in ('add', 'rename') then
    typed := btrim(payload ->> 'name');
    if char_length(typed) not between 1 and 40 then
      raise exception 'Name the section in 40 characters or fewer' using errcode = '22023',
        hint = 'lineup.invalid_section_name';
    end if;
  end if;

  if payload ->> 'action' = 'add' then
    if not exists (select 1 from public.location_sections s
                   where s.workspace_id = target_workspace_id and s.location_id = place.id and s.archived_at is null
                     and lower(btrim(s.name)) = lower(typed)) then
      insert into public.location_sections (workspace_id, location_id, name, sort_order)
      select target_workspace_id, place.id, typed, coalesce(max(s.sort_order) + 1, 0)
      from public.location_sections s
      where s.workspace_id = target_workspace_id and s.location_id = place.id and s.archived_at is null;
    end if;
  elsif payload ->> 'action' = 'rename' then
    if exists (select 1 from public.location_sections s
               where s.workspace_id = target_workspace_id and s.location_id = place.id and s.archived_at is null
                 and s.id <> section.id and lower(btrim(s.name)) = lower(typed)) then
      raise exception 'This location has a section with that name' using errcode = '22023',
        hint = 'lineup.section_exists';
    end if;
    update public.location_sections s set name = typed, updated_at = now() where s.id = section.id;
  elsif payload ->> 'action' = 'reorder' then
    wanted := array(select (v #>> '{}')::uuid from jsonb_array_elements(payload -> 'section_ids') v);
    if cardinality(wanted) <> (select count(distinct w) from unnest(wanted) w)
       or array(select w from unnest(wanted) w order by w) is distinct from array(
         select s.id from public.location_sections s
         where s.workspace_id = target_workspace_id and s.location_id = place.id and s.archived_at is null
         order by s.id) then
      raise exception 'Order every section of this location' using errcode = '22023', hint = 'lineup.invalid_section';
    end if;
    update public.location_sections s set sort_order = o.ord - 1, updated_at = now()
    from unnest(wanted) with ordinality as o (id, ord)
    where s.id = o.id;
  elsif section.archived_at is null then
    update public.location_sections s set archived_at = now(), updated_at = now() where s.id = section.id;
    -- Mert 2026-10-20: the draft rows that had it, today and later, have none. A published lineup keeps it until
    -- Edit takes it back (lineup_command_service), and a day that is over keeps its rows.
    with cleared as (
      update public.daily_lineup_rows r set section_id = null, updated_at = now(), updated_by = actor_user_id
      from public.daily_lineups d
      where r.workspace_id = target_workspace_id and r.section_id = section.id
        and r.service_date >= (now() at time zone place.timezone)::date
        and d.id = r.lineup_id and (d.latest_version = 0 or d.editing)
      returning r.lineup_id
    )
    update public.daily_lineups d set revision = d.revision + 1, updated_at = now(), updated_by = actor_user_id
    where d.id in (select c.lineup_id from cleared c);
  end if;

  return jsonb_build_object('location_id', place.id, 'sections', coalesce((
    select jsonb_agg(jsonb_build_object('id', s.id, 'location_id', s.location_id, 'name', s.name,
      'sort_order', s.sort_order) order by s.sort_order, s.name)
    from public.location_sections s
    where s.workspace_id = target_workspace_id and s.location_id = place.id and s.archived_at is null
  ), '[]'::jsonb));
end;
$_$;


ALTER FUNCTION "public"."lineup_sections_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_account_deletion_avatar_objects_service"("target_request_id" "uuid", "target_lease_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  photos text[];
  folders text[];
begin
  perform public.renew_account_deletion_work_service(target_request_id, target_lease_id);

  select coalesce(array_agg(a.photo_path order by a.photo_path), '{}') into photos
  from public.account_deletion_requests request
  join public.workspace_memberships m on m.user_id = request.user_id
  join public.member_avatars a on a.membership_id = m.id
  where request.id = target_request_id and a.photo_path is not null;

  select coalesce(array_agg(place.folder order by place.folder), '{}') into folders
  from (
    select m.workspace_id::text || '/' || m.id::text || '/' as folder
    from public.account_deletion_requests request
    join public.workspace_memberships m on m.user_id = request.user_id
    where request.id = target_request_id
  ) place;

  return jsonb_build_object('photos', to_jsonb(photos), 'folders', to_jsonb(folders));
end;
$$;


ALTER FUNCTION "public"."list_account_deletion_avatar_objects_service"("target_request_id" "uuid", "target_lease_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "self_only" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,case when self_only then 'documents.self' else 'documents.read' end,
  target_locations=>case when self_only then null else app_private.scope_set(actor_user_id,target_workspace_id,'documents.read') end);
 if self_only is null then raise exception 'document audience required' using errcode='22023'; end if;
 return (select coalesce(jsonb_agg(app_private.document_obligation_json(app_private.document_view(actor_user_id,r)) order by r.sort_order,r.id),'[]')
 from public.employee_onboarding_requirements r where r.workspace_id=target_workspace_id and r.kind in ('document','acknowledgement')
 and (not self_only or r.lifecycle_user_id=actor_user_id)
 -- One's own document waiting for review is never in one's list to review (ROL-CIFT 5.2).
 and (self_only or r.lifecycle_user_id is distinct from actor_user_id or not exists (
  select 1 from public.employee_document_submissions s where s.id=r.submitted_document_id and s.state='pending_review'))
 and app_private.document_row_readable(actor_user_id,r));
end;
$$;


ALTER FUNCTION "public"."list_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "self_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_employees_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "include_archived" boolean DEFAULT false, "search_text" "text" DEFAULT ''::"text", "status_filter" "text" DEFAULT 'all'::"text", "page_limit" integer DEFAULT 100, "page_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "workspace_id" "uuid", "employee_code" "text", "first_name" "text", "last_name" "text", "preferred_name" "text", "display_name" "text", "invitation_email" "text", "start_date" "date", "locations" "jsonb", "primary_job_id" "uuid", "primary_job_name" "text", "job_count" bigint, "management_access" boolean, "employee_access" boolean, "display_status" "text", "archived_at" timestamp with time zone, "revision" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  rule_row app_private.authz_actions;
  reason text;
begin
  select * into rule_row from app_private.authz_actions action where action.key = 'employee.list';
  if not found then
    raise exception 'core action employee.list is missing' using errcode = '22023';
  end if;
  -- May they list anybody at all; who, is answered row by row.
  reason := app_private.authz_check(me, rule_row, null, null, null);
  if reason is not null and reason <> 'out_of_scope' then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'employee.list';
  end if;

  return query
  with directory as (
    select employee.id, employee.workspace_id, employee.employee_code,
      employee.first_name, employee.last_name, employee.preferred_name,
      concat_ws(' ', coalesce(nullif(employee.preferred_name, ''), employee.first_name), employee.last_name) as display_name,
      employee.invitation_email, employee.start_date,
      -- Every location they work at, the primary first, then A to Z (BL-436).
      coalesce((
        select jsonb_agg(jsonb_build_object('id', place.id, 'name', place.name, 'primary', assignment.is_primary)
          order by assignment.is_primary desc, lower(place.name), place.id)
        from public.employee_location_assignments assignment
        join public.locations place on place.id = assignment.location_id
        where assignment.employee_id = employee.id and assignment.ended_at is null
      ), '[]'::jsonb) as locations,
      primary_job.job_id as primary_job_id, app_private.listed_job_name(employee.id) as primary_job_name,
      (select count(*) from public.employee_job_assignments a where a.employee_id = employee.id and a.ended_at is null) as job_count,
      -- The two access slots apart (KARARLAR S-179): which app the person reaches, not a rank.
      membership.role_id is not null as management_access,
      -- No membership (not joined yet, no account) reaches neither app: No access.
      membership.employee_role_id is not null as employee_access,
      case
        when employee.archived_at is not null then 'archived'
        when membership.status = 'active' then 'active'
        when onboarding.status = 'submitted' then 'needs_attention'
        when onboarding.status = 'changes_requested' then 'changes_requested'
        when membership.status = 'pending_activation' then 'onboarding'
        when invitation.status = 'pending' and invitation.expires_at > now() then 'invited'
        else 'not_invited'
      end as display_status,
      employee.archived_at, employee.revision
    from public.employee_profiles employee
    left join public.employee_job_assignments primary_job on primary_job.employee_id = employee.id and primary_job.ended_at is null and primary_job.is_primary
    left join public.workspace_memberships membership on membership.workspace_id = employee.workspace_id and membership.user_id = employee.user_id
    left join public.employee_onboarding_cases onboarding on onboarding.employee_id = employee.id
    left join lateral (
      select candidate.status, candidate.expires_at
      from public.employee_invitations candidate
      where candidate.employee_id = employee.id
      order by candidate.created_at desc limit 1
    ) invitation on true
    where employee.workspace_id = target_workspace_id
      and (include_archived = (employee.archived_at is not null))
      and app_private.authz_check(me, rule_row, null, employee.id, null) is null
  )
  select * from directory
  where (
      btrim(search_text) = ''
      or concat_ws(
        ' ',
        directory.first_name,
        directory.last_name,
        directory.preferred_name,
        directory.employee_code,
        directory.invitation_email,
        (select string_agg(place ->> 'name', ' ') from jsonb_array_elements(directory.locations) place),
        directory.primary_job_name
      ) ilike '%' || btrim(search_text) || '%'
    )
    and (status_filter = 'all' or directory.display_status = status_filter)
  order by lower(directory.display_name), directory.id
  limit least(greatest(page_limit, 1), 200)
  offset greatest(page_offset, 0);
end;
$$;


ALTER FUNCTION "public"."list_employees_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "include_archived" boolean, "search_text" "text", "status_filter" "text", "page_limit" integer, "page_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_workspace_identities_service"("actor_user_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "workspace_role" "public"."workspace_role", "employee_name" "text", "employee_code" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    workspace.id,
    workspace.name,
    coalesce((select slot.access_class from public.workspace_roles slot where slot.id = membership.role_id), 'employee'::public.workspace_role),
    nullif(btrim(coalesce(employee.first_name, '') || ' ' || coalesce(employee.last_name, '')), ''),
    employee.employee_code
  from public.workspace_memberships membership
  join public.workspaces workspace on workspace.id = membership.workspace_id
  left join public.employee_profiles employee
    on employee.workspace_id = membership.workspace_id
   and employee.user_id = membership.user_id
   and employee.archived_at is null
  where membership.user_id = actor_user_id
    and membership.status in (
      'active'::public.membership_status,
      'pending_activation'::public.membership_status
    )
    and workspace.lifecycle_status <> 'deleted'::public.workspace_lifecycle_status
  order by workspace.name;
$$;


ALTER FUNCTION "public"."list_my_workspace_identities_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_workspaces"() RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "workspace_role" "public"."workspace_role", "membership_status" "public"."membership_status", "is_active" boolean, "onboarding_status" "public"."onboarding_status", "onboarding_current_step" smallint, "workspace_lifecycle_status" "public"."workspace_lifecycle_status", "closure_effective_at" timestamp with time zone, "last_used_at" timestamp with time zone, "access_removed" boolean, "pending_ownership_transfer_id" "uuid", "pending_ownership_transfer_role" "text", "pending_ownership_transfer_expires_at" timestamp with time zone, "other_member_count" integer, "pending_invitation_count" integer, "default_closure_effective_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    workspace.id,
    workspace.name,
    coalesce((select slot.access_class from public.workspace_roles slot where slot.id = membership.role_id), 'employee'::public.workspace_role),
    membership.status,
    coalesce(workspace.id = preference.active_workspace_id, false)
      and membership.status = 'active'
      and (
        workspace.lifecycle_status = 'active'
        or (
          workspace.lifecycle_status = 'closure_scheduled'
          and workspace.closure_effective_at > now()
        )
      ),
    coalesce(onboarding.status, 'complete'::public.onboarding_status),
    coalesce(onboarding.current_step, 2::smallint),
    workspace.lifecycle_status,
    workspace.closure_effective_at,
    membership.last_used_at,
    exists (
      select 1
      from public.employee_access_snapshots snapshot
      where snapshot.membership_id = membership.id
        and snapshot.restored_at is null
    ),
    transfer.id,
    case
      when transfer.id is null then null
      when transfer.target_user_id = (select auth.uid()) then 'target'
      else 'initiator'
    end,
    transfer.expires_at,
    -- Everybody else who would lose access, and everybody who has been asked
    -- and not answered. The reader is not counted: they know about themselves,
    -- and what the closing screen has to say is what it costs other people.
    (
      select count(*)
      from public.workspace_memberships other
      where other.workspace_id = workspace.id
        and other.user_id <> membership.user_id
        and other.status in ('active', 'pending_activation')
        and not exists (
          select 1
          from public.employee_profiles employee
          where employee.workspace_id = other.workspace_id
            and employee.user_id = other.user_id
            and employee.archived_at is not null
        )
    )::integer,
    (
      select count(*)
      from public.employee_invitations invitation
      where invitation.workspace_id = workspace.id
        and invitation.status = 'pending'
        and invitation.expires_at > now()
    )::integer,
    -- What a scheduled closure would land on if nobody names a date, so the
    -- panel can say it before anybody commits to anything.
    now() + app_private.default_closure_period()
  from public.workspace_memberships membership
  join public.workspaces workspace on workspace.id = membership.workspace_id
  left join public.user_workspace_preferences preference on preference.user_id = membership.user_id
  left join public.workspace_onboarding onboarding on onboarding.workspace_id = workspace.id
  left join lateral (
    select pending_transfer.id,
           pending_transfer.target_user_id,
           pending_transfer.expires_at
    from public.workspace_ownership_transfers pending_transfer
    where pending_transfer.workspace_id = workspace.id
      and pending_transfer.status = 'pending'
      -- Keep expired requests visible to their sender so they can be cancelled.
      and (pending_transfer.expires_at > now() or pending_transfer.initiated_by = membership.user_id)
      and (
        pending_transfer.initiated_by = membership.user_id
        or pending_transfer.target_user_id = membership.user_id
      )
    order by pending_transfer.created_at desc
    limit 1
  ) transfer on true
  where membership.user_id = (select auth.uid())
    and not exists (
      select 1
      from public.employee_profiles employee
      where employee.workspace_id = membership.workspace_id
        and employee.user_id = membership.user_id
        and employee.archived_at is not null
    )
  order by
    (membership.status = 'active') desc,
    (coalesce(workspace.id = preference.active_workspace_id, false) and membership.status = 'active') desc,
    workspace.name asc;
$$;


ALTER FUNCTION "public"."list_my_workspaces"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_workspaces_service"("actor_user_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "workspace_role" "public"."workspace_role", "membership_status" "public"."membership_status", "is_active" boolean, "onboarding_status" "public"."onboarding_status", "onboarding_current_step" smallint, "workspace_lifecycle_status" "public"."workspace_lifecycle_status", "closure_effective_at" timestamp with time zone, "last_used_at" timestamp with time zone, "access_removed" boolean, "pending_ownership_transfer_id" "uuid", "pending_ownership_transfer_role" "text", "pending_ownership_transfer_expires_at" timestamp with time zone, "other_member_count" integer, "pending_invitation_count" integer, "default_closure_effective_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;

  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);
  return query select * from public.list_my_workspaces();
end;
$$;


ALTER FUNCTION "public"."list_my_workspaces_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_own_employment_records_service"("actor_user_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "employee_id" "uuid", "preferred_name" "text", "phone" "text", "emergency_contact_name" "text", "emergency_contact_relationship" "text", "emergency_contact_phone" "text", "emergency_contact_email" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    employee.workspace_id,
    workspace.name,
    employee.id,
    coalesce(employee.preferred_name, ''),
    private_profile.phone,
    coalesce(private_profile.emergency_contact_name, ''),
    coalesce(private_profile.emergency_contact_relationship, ''),
    coalesce(private_profile.emergency_contact_phone, ''),
    coalesce(private_profile.emergency_contact_email, '')
  from public.employee_profiles employee
  join public.workspaces workspace on workspace.id = employee.workspace_id
  join public.workspace_memberships membership
    on membership.workspace_id = employee.workspace_id
   and membership.user_id = employee.user_id
  left join public.employee_private_profiles private_profile
    on private_profile.employee_id = employee.id
  where employee.user_id = actor_user_id
    and employee.archived_at is null
    and membership.status in (
      'active'::public.membership_status,
      'pending_activation'::public.membership_status
    )
    and workspace.lifecycle_status <> 'deleted'
  order by workspace.name;
$$;


ALTER FUNCTION "public"."list_own_employment_records_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_owner_onboarding_invitation_intents_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS TABLE("employee_id" "uuid", "email" "text", "employee_role_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  onboarding_status public.onboarding_status;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.setup');

  select onboarding.status
  into onboarding_status
  from public.workspace_onboarding onboarding
  where onboarding.workspace_id = target_workspace_id;

  if onboarding_status is null then
    raise exception 'workspace onboarding was not found' using errcode = 'P0002';
  end if;
  if onboarding_status <> 'complete'::public.onboarding_status then
    raise exception 'owner onboarding must be complete' using errcode = '22023';
  end if;

  return query
  select intent.employee_id, intent.email,
    -- DAVET-ERISIM
    (select r.id from public.workspace_roles r where r.workspace_id = target_workspace_id and r.system_key = 'employee')
  from public.owner_onboarding_invitation_intents intent
  join public.employee_profiles employee
    on employee.workspace_id = intent.workspace_id
   and employee.id = intent.employee_id
  where intent.workspace_id = target_workspace_id
    and intent.dispatched_at is null
    and employee.archived_at is null
    and employee.user_id is null
    and not exists (
      select 1
      from public.employee_invitations invitation
      where invitation.workspace_id = intent.workspace_id
        and invitation.employee_id = intent.employee_id
        and invitation.status in ('pending', 'accepted')
    )
  order by intent.created_at, intent.employee_id;
end;
$$;


ALTER FUNCTION "public"."list_owner_onboarding_invitation_intents_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_pending_employee_invitations_for_account_service"("actor_user_id" "uuid") RETURNS TABLE("invitation_id" "uuid", "workspace_id" "uuid", "workspace_name" "text", "email" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_email text;
  email_confirmed boolean;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;

  select lower(user_row.email), user_row.email_confirmed_at is not null
  into normalized_email, email_confirmed
  from auth.users user_row
  where user_row.id = actor_user_id;

  if normalized_email is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;
  if not email_confirmed then
    return;
  end if;

  return query
  select
    invitation.id,
    invitation.workspace_id,
    workspace.name,
    invitation.email,
    invitation.expires_at
  from public.employee_invitations invitation
  join public.workspaces workspace on workspace.id = invitation.workspace_id
  where invitation.email = normalized_email
    and invitation.status = 'pending'
    and invitation.expires_at > now()
    and not exists (
      select 1
      from public.workspace_memberships membership
      where membership.workspace_id = invitation.workspace_id
        and membership.user_id = actor_user_id
    )
  order by invitation.expires_at asc, workspace.name asc;
end;
$$;


ALTER FUNCTION "public"."list_pending_employee_invitations_for_account_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_pending_preferred_names_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS TABLE("request_id" "uuid", "employee_id" "uuid", "employee_name" "text", "requested_name" "text", "requested_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  rule_row app_private.authz_actions;
  reason text;
begin
  select * into rule_row from app_private.authz_actions action where action.key = 'employee.decide_preferred_name';
  -- May they answer anybody at all; whom, is answered row by row.
  reason := app_private.authz_check(me, rule_row, null, null, null);
  if reason is not null and reason <> 'out_of_scope' then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'employee.decide_preferred_name';
  end if;
  return query
  select
    request.id,
    request.employee_id,
    concat_ws(' ', employee.first_name, employee.last_name),
    request.requested_name,
    request.requested_at
  from public.employee_preferred_name_requests request
  join public.employee_profiles employee on employee.id = request.employee_id
  where request.workspace_id = target_workspace_id
    and request.status = 'pending'
    and employee.archived_at is null
    and app_private.authz_check(me, rule_row, null, request.employee_id, null) is null
  order by request.requested_at;
end;
$$;


ALTER FUNCTION "public"."list_pending_preferred_names_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_draft_document_conflicts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[], "target_department_ids" "uuid"[] DEFAULT NULL::"uuid"[], "include_no_department" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  draft_week date;
  conflicts jsonb := '[]'::jsonb;
  fingerprint text := 'none';
  normalized_locations uuid[];
  normalized_departments uuid[];
  effective_include_no_department boolean := coalesce(include_no_department, true);
  requested uuid;
begin
  if cardinality(coalesce(target_location_ids, '{}'::uuid[])) = 0 then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => '{}'::uuid[]);
  end if;
  foreach requested in array target_location_ids loop
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => array[requested]);
  end loop;

  select coalesce(array_agg(distinct location.id order by location.id), '{}'::uuid[])
  into normalized_locations
  from public.locations location
  join unnest(coalesce(target_location_ids, '{}'::uuid[])) requested(location_id)
    on requested.location_id = location.id
  where location.workspace_id = target_workspace_id
    and location.archived_at is null;

  if cardinality(normalized_locations) = 0 then
    return jsonb_build_object(
      'status', 'ok',
      'conflicts', conflicts,
      'fingerprint', fingerprint
    );
  end if;

  if target_department_ids is not null then
    select coalesce(array_agg(distinct department.id order by department.id), '{}'::uuid[])
    into normalized_departments
    from public.departments department
    join unnest(target_department_ids) requested(id)
      on requested.id = department.id
    where department.workspace_id = target_workspace_id
      and department.archived_at is null;
  end if;

  select draft.week_start
  into draft_week
  from public.schedule_drafts draft
  where draft.id = target_draft_id
    and draft.workspace_id = target_workspace_id
    and draft.archived_at is null
  limit 1;

  if draft_week is null or draft_week <> target_week_start then
    return jsonb_build_object(
      'status', 'ok',
      'conflicts', conflicts,
      'fingerprint', fingerprint
    );
  end if;

  with candidate_shifts as (
    select
      shift.id,
      shift.location_id,
      location.name as location_name,
      shift.employee_id,
      trim(coalesce(nullif(employee.preferred_name, ''), employee.first_name) || ' ' || employee.last_name) as employee_name,
      shift.scheduled_date,
      to_char(shift.start_time, 'HH24:MI') as start_time,
      to_char(shift.end_time, 'HH24:MI') as end_time
    from public.schedule_draft_shifts shift
    join public.locations location
      on location.id = shift.location_id
     and location.workspace_id = shift.workspace_id
    join public.employee_profiles employee
      on employee.id = shift.employee_id
     and employee.workspace_id = shift.workspace_id
     and employee.archived_at is null
    where shift.workspace_id = target_workspace_id
      and shift.draft_id = target_draft_id
      and shift.employee_id is not null
      and shift.location_id = any(normalized_locations)
      and public.schedule_shift_in_department_scope_service(
        shift.job_id,
        normalized_departments,
        effective_include_no_department
      )
      and shift.scheduled_date >= target_week_start
      and shift.scheduled_date < target_week_start + 7
  ),
  active_document_requirements as (
    select distinct on (requirement.employee_id, requirement.source_id)
      requirement.employee_id,
      requirement.id as requirement_id,
      requirement.source_id as document_type_id,
      requirement.title as document_title
    from public.employee_onboarding_requirements requirement
    join public.document_types document_type
      on document_type.id = requirement.source_id
     and document_type.workspace_id = requirement.workspace_id
    where requirement.workspace_id = target_workspace_id
      and requirement.kind = 'document'::public.employee_onboarding_requirement_kind
      and requirement.status <> 'superseded'::public.employee_onboarding_requirement_status
      and document_type.archived_at is null
      and document_type.tracks_expiry
      and document_type.expiry_schedule_impact in ('warn', 'block')
    order by requirement.employee_id, requirement.source_id, requirement.created_at desc, requirement.id
  ),
  latest_accepted_documents as (
    select distinct on (document.workspace_id, document.requirement_id)
      document.*
    from public.employee_documents document
    where document.workspace_id = target_workspace_id
      and document.review_status = 'accepted'::public.employee_document_review_status
    order by document.workspace_id, document.requirement_id, document.version_number desc
  ),
  latest_pending_documents as (
    select distinct on (document.workspace_id, document.requirement_id)
      document.*
    from public.employee_documents document
    where document.workspace_id = target_workspace_id
      and document.review_status = 'awaiting_review'::public.employee_document_review_status
    order by document.workspace_id, document.requirement_id, document.version_number desc
  ),
  violation_rows as (
    select
      document_type.expiry_schedule_impact,
      document_type.expiry_policy_version,
      requirement.requirement_id,
      requirement.document_type_id,
      requirement.document_title,
      accepted.id as document_id,
      accepted.expiry_date,
      pending.id as pending_document_id,
      shift.id as shift_id,
      shift.location_id,
      shift.location_name,
      shift.employee_id,
      shift.employee_name,
      shift.scheduled_date,
      shift.start_time,
      shift.end_time
    from candidate_shifts shift
    join active_document_requirements requirement
      on requirement.employee_id = shift.employee_id
    join public.document_types document_type
      on document_type.id = requirement.document_type_id
     and document_type.workspace_id = target_workspace_id
    join latest_accepted_documents accepted
      on accepted.requirement_id = requirement.requirement_id
    left join latest_pending_documents pending
      on pending.requirement_id = requirement.requirement_id
    where accepted.expiry_date is not null
      and accepted.expiry_date < shift.scheduled_date
  ),
  conflict_rows as (
    select
      jsonb_build_object(
        'kind', 'document_expiry',
        'employee_id', employee_id,
        'employee_name', employee_name,
        'shift_id', shift_id,
        'location_id', location_id,
        'location_name', location_name,
        'date', scheduled_date,
        'start_time', start_time,
        'end_time', end_time,
        'document_type_id', document_type_id,
        'requirement_id', requirement_id,
        'document_id', document_id,
        'document_title', document_title,
        'expiry_date', expiry_date,
        'expiry_policy_version', expiry_policy_version,
        'pending_document_id', pending_document_id,
        'review_action', case when pending_document_id is null then null else 'review_document' end,
        'severity', case
          when expiry_schedule_impact = 'block' then 'hard'
          else 'soft'
        end,
        'overrideable', expiry_schedule_impact = 'warn',
        'warning_text', case
          when expiry_schedule_impact = 'block'
            then document_title || ' is expired and blocks scheduling.'
          else document_title || ' is expired.'
        end,
        'conflict_fingerprint', 'pending'
      ) as conflict,
      concat_ws(
        '|',
        employee_id,
        shift_id,
        document_type_id,
        requirement_id,
        document_id,
        pending_document_id,
        expiry_schedule_impact,
        expiry_policy_version,
        scheduled_date,
        expiry_date
      ) as conflict_key
    from violation_rows
    order by scheduled_date, start_time, shift_id, document_type_id
  )
  select coalesce(jsonb_agg(conflict), '[]'::jsonb),
         coalesce(
           encode(
             extensions.digest(
               convert_to(string_agg(conflict_key, E'\n' order by conflict_key), 'UTF8'),
               'sha256'
             ),
             'hex'
           ),
           'none'
         )
  into conflicts, fingerprint
  from conflict_rows;

  if fingerprint <> 'none' then
    conflicts := (
      select jsonb_agg(conflict - 'conflict_fingerprint' || jsonb_build_object(
        'conflict_fingerprint',
        fingerprint
      ))
      from jsonb_array_elements(conflicts) conflict
    );
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'conflicts', conflicts,
    'fingerprint', fingerprint
  );
end;
$$;


ALTER FUNCTION "public"."list_schedule_draft_document_conflicts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[], "target_department_ids" "uuid"[], "include_no_department" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_drafts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare edit_scope uuid[]; org_wide boolean;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit',
    target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit'));
  edit_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit');
  org_wide := app_private.authz_reason(actor_user_id, target_workspace_id, 'schedule.edit', '{}'::uuid[]) is null;
  return jsonb_build_object('drafts', coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', draft.id, 'workspace_id', draft.workspace_id,
      'week_start', draft.week_start, 'name', draft.name,
      'revision', draft.revision, 'created_by', draft.created_by,
      'updated_by', draft.updated_by, 'created_at', draft.created_at,
      'updated_at', draft.updated_at,
      'updated_by_name', coalesce((
        select nullif(profile.display_name, '') from public.user_profiles profile
        where profile.user_id = draft.updated_by), 'Team member'),
      'shift_count', facts.shift_count, 'paid_minutes', facts.paid_minutes,
      'open_shift_count', facts.open_shift_count
    ) order by draft.updated_at desc, draft.name)
    from public.schedule_drafts draft
    cross join lateral (
      select count(*) filter (where shift.employee_id is not null)::integer as shift_count,
        coalesce(sum(greatest(0, (case when shift.end_time <= shift.start_time then 1440 else 0 end
          + extract(epoch from (shift.end_time - shift.start_time)) / 60)::integer
          - shift.unpaid_break_minutes)) filter (where shift.employee_id is not null), 0)::integer as paid_minutes,
        count(*) filter (where shift.employee_id is null)::integer as open_shift_count
      from public.schedule_draft_shifts shift
      where shift.draft_id = draft.id and shift.workspace_id = target_workspace_id
        and (org_wide or shift.location_id = any (edit_scope))
    ) facts
    where draft.workspace_id = target_workspace_id
      and draft.week_start = target_week_start and draft.archived_at is null
      and (org_wide or draft.location_ids && edit_scope)
  ), '[]'::jsonb),
  'published', (
    select jsonb_build_object('shift_count', count(*) filter (where shift.employee_id is not null)::integer,
      'paid_minutes', coalesce(sum(greatest(0, (case when shift.end_time <= shift.start_time then 1440 else 0 end
        + extract(epoch from (shift.end_time - shift.start_time)) / 60)::integer
        - shift.unpaid_break_minutes)) filter (where shift.employee_id is not null), 0)::integer,
      'open_shift_count', count(*) filter (where shift.employee_id is null)::integer)
    from public.schedule_published_shifts shift
    join public.schedule_location_publications publication
      on publication.id = shift.publication_id and publication.workspace_id = shift.workspace_id
    where publication.workspace_id = target_workspace_id
      and publication.week_start = target_week_start and publication.status = 'current'
      and (org_wide or shift.location_id = any (edit_scope))
  ));
end;
$$;


ALTER FUNCTION "public"."list_schedule_drafts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_export_cron_candidates_service"("target_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'schedules',
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'workspace_id', s.workspace_id,
          'workspace_name', w.name,
          'created_by', s.created_by,
          'preset_id', s.preset_id,
          'preset_name', p.name,
          'settings', p.settings,
          'name', s.name,
          'recipients', s.recipients,
          'location_ids', to_jsonb(public.live_location_ids(s.workspace_id, s.location_ids)),
          'day_of_week', s.day_of_week,
          'send_hour', s.send_hour,
          'timezone', s.timezone,
          'week_start_day', coalesce(settings.week_start_day::text, 'monday'),
          'last_sent_at', s.last_sent_at,
          'consecutive_failures', s.consecutive_failures
        )
        order by s.workspace_id, s.send_hour, s.id
      ),
      '[]'::jsonb
    )
  )
  from public.scheduled_schedule_exports s
  join public.schedule_export_presets p
    on p.id = s.preset_id
   and p.workspace_id = s.workspace_id
  join public.workspaces w
    on w.id = s.workspace_id
  left join public.workspace_scheduling_settings settings
    on settings.workspace_id = s.workspace_id
  where s.enabled
    and (s.last_failed_at is null or s.last_failed_at <= target_now - interval '15 minutes')
    and s.auto_disabled_at is null
    and cardinality(s.location_ids) > 0
    and app_private.workspace_allows_interactive_access(s.workspace_id)
    and (
      s.last_sent_at is null
      or s.last_sent_at <= target_now - interval '20 hours'
    );
$$;


ALTER FUNCTION "public"."list_schedule_export_cron_candidates_service"("target_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_export_events_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare export_scope uuid[]; org_wide boolean;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
    target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.export'));
  export_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.export');
  org_wide := app_private.authz_reason(actor_user_id, target_workspace_id, 'schedule.export', '{}'::uuid[]) is null;
  return (
    select jsonb_build_object(
      'events',
      coalesce(
        jsonb_agg(public.schedule_export_event_json(event_row) order by event_row.created_at desc, event_row.id desc),
        '[]'::jsonb
      )
    )
    from (
      select event.*
        from public.schedule_export_events event
        cross join lateral (
          -- The locations it was for; null when the list is missing or holds
          -- anything that is not a location id.
          select case
            when jsonb_typeof(event.params -> 'location_ids') = 'array'
              and not exists (
                select 1 from jsonb_array_elements(event.params -> 'location_ids') item
                where jsonb_typeof(item) <> 'string'
                   or item #>> '{}' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              )
            then array(select (item #>> '{}')::uuid from jsonb_array_elements(event.params -> 'location_ids') item)
          end as ids
        ) places
       where event.workspace_id = target_workspace_id
         and (org_wide or (cardinality(public.live_location_ids(target_workspace_id, places.ids)) > 0
           and public.live_location_ids(target_workspace_id, places.ids) <@ export_scope))
       order by event.created_at desc, event.id desc
       limit 10
    ) event_row
  );
end;
$_$;


