CREATE OR REPLACE FUNCTION "public"."list_schedule_pending_ops_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "target_draft_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'pending_ops',
    coalesce(jsonb_agg(jsonb_build_object(
      'id', shift.id,
      'location_id', shift.location_id,
      'week_start', session.week_start,
      'op_type', shift.pending_op_type,
      'target_shift_id', shift.source_published_shift_id,
      'target_draft_id', session.source_draft_id,
      'payload', public.schedule_pending_op_payload_json(shift),
      'created_by', session.holder_user_id,
      'created_at', shift.created_at,
      'updated_at', shift.updated_at
    ) order by shift.updated_at asc, shift.id asc), '[]'::jsonb)
  )
  from public.schedule_edit_sessions session
  join public.schedule_edit_session_shifts shift
    on shift.session_id = session.id
   and shift.workspace_id = session.workspace_id
  where session.workspace_id = target_workspace_id
    and session.week_start = target_week_start
    and session.status = 'active'
    -- Each manager's own unsaved changes only (D-Y5).
    and session.holder_user_id = actor_user_id
    and shift.pending_op_type is not null
    and (
      target_draft_id is null
      or session.source_draft_id = target_draft_id
    )
    and (
      target_location_ids is null
      or cardinality(target_location_ids) = 0
      or shift.location_id = any(target_location_ids)
    )
    and shift.location_id = any ((select app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit'))::uuid[]);
$$;


ALTER FUNCTION "public"."list_schedule_pending_ops_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[], "target_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_templates_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare template_scope uuid[]; org_wide boolean;
begin
 perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.templates.read',
   target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates.read'));
 template_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates.read');
 org_wide := app_private.authz_reason(actor_user_id, target_workspace_id, 'schedule.templates.read', '{}'::uuid[]) is null;
 return (
 select jsonb_build_object('templates',coalesce(jsonb_agg(jsonb_build_object(
   'id',t.id,'workspace_id',t.workspace_id,'name',t.name,'revision',t.revision,
   'shift_count',x.shift_count,'open_slot_count',x.open_slot_count,
   'created_by_name',coalesce(u.display_name,'Manager'),'updated_at',t.updated_at
 ) order by t.updated_at desc,t.id) filter(where t.id is not null),'[]'::jsonb))
 from public.schedule_templates t join public.user_profiles u on u.user_id=t.created_by
 cross join lateral (select public.live_location_ids(t.workspace_id, array(select distinct z.location_id from public.schedule_template_shifts z where z.template_id=t.id)) ids) live
 cross join lateral (select count(*)::integer shift_count,count(*) filter(where s.employee_id is null)::integer open_slot_count
   from public.schedule_template_shifts s where s.template_id=t.id and s.location_id=any(live.ids)) x
 where t.workspace_id=target_workspace_id
 and (org_wide or (cardinality(live.ids)>0 and live.ids <@ template_scope))
 );
end;
$$;


ALTER FUNCTION "public"."list_schedule_templates_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_weekly_shifts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "target_draft_id" "uuid" DEFAULT NULL::"uuid", "include_live_context" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  reason text;
  reachable uuid[];
begin
  -- May they read any week at all; which locations, the core answers.
  reason := app_private.authz_check(app_private.actor(actor_user_id, target_workspace_id),
    (select r from app_private.authz_actions r where r.key = 'schedule.read'), null, null, null);
  if reason is not null and reason <> 'out_of_scope' then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'schedule.read';
  end if;
  reachable := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.read');

  if target_draft_id is not null and not exists (
    select 1
    from public.schedule_drafts draft
    where draft.id = target_draft_id
      and draft.workspace_id = target_workspace_id
      and draft.week_start = target_week_start
      and draft.archived_at is null
      and draft.location_ids && reachable
  ) then
    -- A draft touching none of the person's locations is not there for them (BL-412).
    raise exception 'Not allowed' using errcode = '42501', detail = 'schedule.read', hint = 'authz.out_of_scope';
  end if;

  with requested_locations as (
    select unnest(coalesce(target_location_ids, array[]::uuid[])) as id
  ), allowed_locations as (
    select location.id
    from public.locations location
    where location.workspace_id = target_workspace_id
      and location.archived_at is null
      and location.id = any(reachable)
      and (
        coalesce(array_length(target_location_ids, 1), 0) = 0
        or location.id in (select id from requested_locations)
      )
  ), current_publications as (
    select publication.*
    from public.schedule_location_publications publication
    join allowed_locations location on location.id = publication.location_id
    where publication.workspace_id = target_workspace_id
      and publication.week_start = target_week_start
      and publication.status = 'current'
  ), draft_shifts as (
    select
      shift.id,
      shift.workspace_id,
      shift.location_id,
      shift.employee_id,
      shift.job_id,
      shift.shift_type_id,
      shift.scheduled_date,
      shift.start_time,
      shift.end_time,
      shift.crosses_midnight,
      shift.unpaid_break_minutes,
      shift.note
    from public.schedule_draft_shifts shift
    join allowed_locations location on location.id = shift.location_id
    where target_draft_id is not null
      and shift.workspace_id = target_workspace_id
      and shift.draft_id = target_draft_id
      and shift.scheduled_date between target_week_start and target_week_start + 6
  ), published_shifts as (
    select
      shift.source_shift_id as id,
      shift.workspace_id,
      shift.location_id,
      shift.employee_id,
      shift.job_id,
      shift.shift_type_id,
      shift.scheduled_date,
      shift.start_time,
      shift.end_time,
      shift.crosses_midnight,
      shift.unpaid_break_minutes,
      shift.note
    from public.schedule_published_shifts shift
    join current_publications publication on publication.id = shift.publication_id
    where shift.workspace_id = target_workspace_id
      and shift.scheduled_date between target_week_start and target_week_start + 6
  ), selected_shifts as (
    select * from draft_shifts
    union all
    select * from published_shifts where target_draft_id is null
  ), ghost_context as (
    select published.*
    from published_shifts published
    where include_live_context
      and target_draft_id is not null
      and not exists (
        select 1 from draft_shifts draft where draft.id = published.id
      )
  ), selected_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', shift.id,
      'location_id', shift.location_id,
      'employee_id', shift.employee_id,
      'job_id', shift.job_id,
      'shift_type_id', shift.shift_type_id,
      'scheduled_date', shift.scheduled_date,
      'start_time', to_char(shift.start_time, 'HH24:MI'),
      'end_time', to_char(shift.end_time, 'HH24:MI'),
      'crosses_midnight', shift.crosses_midnight,
      'unpaid_break_minutes', coalesce(shift.unpaid_break_minutes, 0),
      'note', shift.note,
      'warning_codes', to_jsonb(array_remove(array[
        case when exists (
          select 1
          from public.schedule_closures closure
          where closure.location_id = shift.location_id
            and closure.closed_date = shift.scheduled_date
            and app_private.closure_covers(closure.kind, closure.opens, closure.closes, shift.start_time, shift.end_time)
        ) then 'closed_location' end,
        case when shift.employee_id is not null and exists (
          select 1
          from selected_shifts other
          where other.employee_id = shift.employee_id
            and other.scheduled_date = shift.scheduled_date
            and other.id <> shift.id
            and not shift.crosses_midnight and not other.crosses_midnight
            and shift.start_time < other.end_time and shift.end_time > other.start_time
        ) then 'overlap' end
      ]::text[], null))
    ) order by shift.scheduled_date, shift.start_time, shift.id), '[]'::jsonb) as payload
    from selected_shifts shift
  ), ghost_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', shift.id,
      'location_id', shift.location_id,
      'employee_id', shift.employee_id,
      'job_id', shift.job_id,
      'shift_type_id', shift.shift_type_id,
      'scheduled_date', shift.scheduled_date,
      'start_time', to_char(shift.start_time, 'HH24:MI'),
      'end_time', to_char(shift.end_time, 'HH24:MI'),
      'crosses_midnight', shift.crosses_midnight,
      'unpaid_break_minutes', coalesce(shift.unpaid_break_minutes, 0),
      'note', shift.note,
      'warning_codes', to_jsonb(array_remove(array[
        case when exists (
          select 1
          from public.schedule_closures closure
          where closure.location_id = shift.location_id
            and closure.closed_date = shift.scheduled_date
            and app_private.closure_covers(closure.kind, closure.opens, closure.closes, shift.start_time, shift.end_time)
        ) then 'closed_location' end
      ]::text[], null))
    ) order by shift.scheduled_date, shift.start_time, shift.id), '[]'::jsonb) as payload
    from ghost_context shift
  )
  select jsonb_build_object(
    'shifts', selected_json.payload,
    'ghost_shifts', ghost_json.payload
  )
  into result
  from selected_json, ghost_json;

  return public.schedule_availability_enrich_read(actor_user_id,target_workspace_id,result,target_draft_id);
end;
$$;


ALTER FUNCTION "public"."list_schedule_weekly_shifts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[], "target_draft_id" "uuid", "include_live_context" boolean) OWNER TO "postgres";


