CREATE OR REPLACE FUNCTION "public"."mark_schedule_edit_session_shift_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_source public.schedule_edit_source;
  session_week date;
begin
  select session.source_kind, session.week_start into session_source, session_week
  from public.schedule_edit_sessions session
  where session.id = new.session_id
    and session.workspace_id = new.workspace_id;

  -- D-O1: a shift added while editing a published week is new, not "Live".
  if session_source = 'published' and new.source_published_shift_id is null and exists (
    select 1 from public.schedule_location_publications publication
    join public.schedule_published_shifts published
      on published.publication_id = publication.id and published.source_shift_id = new.id
    where publication.location_id = new.location_id and publication.week_start = session_week
      and publication.status = 'current' and publication.workspace_id = new.workspace_id
  ) then
    new.source_published_shift_id := new.id;
    new.locked := true;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."mark_schedule_edit_session_shift_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_workspace_retention_purge_completed_service"("target_workspace_id" "uuid", "purge_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  workspace_row public.workspaces%rowtype;
  purge_job public.workspace_retention_purge_jobs%rowtype;
  tombstone public.workspace_retention_tombstones%rowtype;
begin
  if target_workspace_id is null then
    raise exception 'valid workspace required' using errcode = '22023';
  end if;
  if purge_metadata is null or jsonb_typeof(purge_metadata) <> 'object' then
    raise exception 'purge metadata must be an object' using errcode = '22023';
  end if;

  select * into tombstone
  from public.workspace_retention_tombstones existing
  where existing.workspace_id = target_workspace_id;
  if tombstone.workspace_id is not null then
    return jsonb_build_object(
      'status', 'completed',
      'workspace_id', tombstone.workspace_id,
      'purged_at', tombstone.purged_at,
      'idempotent', true
    );
  end if;

  select * into workspace_row
  from public.workspaces workspace
  where workspace.id = target_workspace_id
  for update;
  if workspace_row.id is null then
    raise exception 'workspace not found' using errcode = '02000';
  end if;
  if workspace_row.lifecycle_status <> 'deleted' then
    raise exception 'workspace must be deleted before retention purge' using errcode = '23514';
  end if;

  insert into public.workspace_retention_purge_jobs (
    workspace_id,
    due_at,
    metadata
  )
  values (
    target_workspace_id,
    coalesce(workspace_row.closed_at, now()),
    jsonb_build_object('source', 'manual_service_enqueue')
  )
  on conflict (workspace_id) do nothing;

  select * into purge_job
  from public.workspace_retention_purge_jobs job
  where job.workspace_id = target_workspace_id
  for update;

  if purge_job.status = 'completed' then
    return jsonb_build_object(
      'status', 'completed',
      'workspace_id', target_workspace_id,
      'purged_at', purge_job.completed_at,
      'idempotent', true
    );
  end if;
  if purge_job.due_at > now() then
    raise exception 'workspace retention purge is not due' using errcode = '23514';
  end if;

  insert into public.workspace_retention_tombstones (
    workspace_id,
    workspace_name,
    closed_at,
    closed_by,
    purge_job_id,
    metadata
  )
  values (
    target_workspace_id,
    workspace_row.name,
    coalesce(workspace_row.closed_at, now()),
    workspace_row.closed_by,
    purge_job.id,
    purge_metadata
  )
  returning * into tombstone;

  update public.workspace_retention_purge_jobs
  set status = 'completed',
      completed_at = tombstone.purged_at,
      metadata = public.workspace_retention_purge_jobs.metadata || purge_metadata,
      updated_at = now()
  where id = purge_job.id;

  insert into public.audit_events (
    workspace_id,
    actor_user_id,
    action,
    target_type,
    target_id,
    metadata
  )
  values (
    target_workspace_id,
    workspace_row.closed_by,
    'workspace.retention_purge.completed',
    'workspace',
    target_workspace_id::text,
    purge_metadata || jsonb_build_object('purge_job_id', purge_job.id)
  );

  return jsonb_build_object(
    'status', 'completed',
    'workspace_id', target_workspace_id,
    'purged_at', tombstone.purged_at,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION "public"."mark_workspace_retention_purge_completed_service"("target_workspace_id" "uuid", "purge_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mutate_schedule_edit_shift_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "operation" "text", "target_shift_id" "uuid", "expected_shift_revision" integer DEFAULT NULL::integer, "shift_payload" "jsonb" DEFAULT NULL::"jsonb", "request_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  reach uuid[];
  write_row boolean := false;
  target_session public.schedule_edit_sessions%rowtype;
  target_shift public.schedule_edit_session_shifts%rowtype;
  mutated_shift record;
  override_note text;
  audited_shift_id uuid;
begin
  perform public.availability_lock_workspace(target_workspace_id);
  if operation not in ('create', 'update', 'delete', 'restore') then
    raise exception 'invalid shift operation' using errcode = '22023';
  end if;
  reach := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit');

  -- a. Delete and restore: a published shift is marked, an unpublished one goes.
  if operation in ('create', 'update') then
    write_row := true;
  else
    select * into target_session
    from public.schedule_edit_sessions session
    where session.id = target_session_id
      and session.workspace_id = target_workspace_id
    for update;

    if target_session.id is null or target_session.holder_user_id <> actor_user_id then
      raise exception 'edit session not found' using errcode = 'P0002';
    end if;
    if target_session.status <> 'active' then
      raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
    elsif target_session.expires_at <= now() then
      raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
    end if;
    if target_session.revision <> expected_session_revision then
      raise exception 'session revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
    end if;

    select * into target_shift
    from public.schedule_edit_session_shifts shift
    where shift.session_id = target_session_id
      and shift.id = target_shift_id
      and shift.revision = expected_shift_revision
      and shift.location_id = any(reach)
    for update;

    if target_shift.id is null then
      raise exception 'shift revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
    end if;

    if operation = 'restore' then
      if target_shift.source_published_shift_id is null
        or target_shift.pending_op_type is distinct from 'delete' then
        raise exception 'shift restore unavailable' using errcode = '22023';
      end if;

      update public.schedule_edit_session_shifts shift
      set pending_op_type = null,
          locked = true,
          revision = revision + 1,
          updated_at = now()
      where shift.session_id = target_session_id
        and shift.id = target_shift_id;

      update public.schedule_edit_sessions
      set revision = revision + 1,
          dirty = true,
          last_heartbeat = now(),
          expires_at = now() + interval '4 minutes'
      where id = target_session_id;

      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    elsif target_shift.source_published_shift_id is null and not target_shift.locked then
      write_row := true;
    else
      update public.schedule_edit_session_shifts shift
      set pending_op_type = 'delete',
          locked = true,
          revision = revision + 1,
          updated_at = now()
      where shift.session_id = target_session_id
        and shift.id = target_shift_id;

      update public.schedule_edit_sessions
      set revision = revision + 1,
          dirty = true,
          last_heartbeat = now(),
          expires_at = now() + interval '4 minutes'
      where id = target_session_id;

      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    end if;
  end if;

  -- b. Write the row: create, update, or delete an unpublished shift. The
  -- block keeps its own copy of the id and payload, as the old inner layer did.
  if write_row then
    <<write_shift>>
    declare
      row_shift_id uuid := target_shift_id;
      row_payload jsonb := shift_payload;
      target_location_id uuid;
      target_employee_id uuid;
      target_job_id uuid;
      target_shift_type_id uuid;
      target_scheduled_date date;
      target_start_time time;
      target_end_time time;
      target_unpaid_break_minutes integer;
      target_hide_time_on_badge boolean;
      target_note text;
      kept public.schedule_edit_session_shifts%rowtype;
    begin
      select * into target_session from public.schedule_edit_sessions session
      where session.id = target_session_id and session.workspace_id = target_workspace_id
      for update;
      if target_session.id is null or target_session.holder_user_id <> actor_user_id then
        raise exception 'edit session not found' using errcode = 'P0002';
      end if;
      if target_session.status <> 'active' then
        raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
      elsif target_session.expires_at <= now() then
        raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
      end if;
      if target_session.revision <> expected_session_revision then
        raise exception 'session revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
      end if;

      if operation in ('create', 'update') then
        row_payload := public.normalize_schedule_time_source(target_workspace_id,row_payload,(select to_jsonb(s) from public.schedule_edit_session_shifts s where s.session_id=target_session_id and s.id=row_shift_id));
        target_location_id := (row_payload->>'location_id')::uuid;
        target_employee_id := nullif(row_payload->>'employee_id', '')::uuid;
        target_job_id := (row_payload->>'job_id')::uuid;
        target_shift_type_id := nullif(row_payload->>'shift_type_id', '')::uuid;
        target_scheduled_date := (row_payload->>'scheduled_date')::date;
        target_start_time := nullif(row_payload->>'start_time','')::time;
        target_end_time := nullif(row_payload->>'end_time','')::time;
        -- A field the payload leaves out keeps the shift's own value; a new
        -- shift starts from the default (BL-292, EKRAN-01 #11).
        select * into kept from public.schedule_edit_session_shifts s
        where s.session_id = target_session_id and s.id = row_shift_id;
        target_unpaid_break_minutes := case when row_payload ? 'unpaid_break_minutes'
          then coalesce((row_payload->>'unpaid_break_minutes')::integer, 0)
          else coalesce(kept.unpaid_break_minutes, 0) end;
        target_hide_time_on_badge := case when row_payload ? 'hide_time_on_badge'
          then coalesce((row_payload->>'hide_time_on_badge')::boolean, false)
          else coalesce(kept.hide_time_on_badge, false) end;
        target_note := case when row_payload ? 'note' then coalesce(row_payload->>'note', '')
          else coalesce(kept.note, '') end;
        if target_start_time = target_end_time then
          raise exception 'Start and end time cannot be the same.' using errcode = '22023';
        end if;
        if char_length(target_note) > 500
          or target_unpaid_break_minutes not in (0, 15, 30, 45, 60)
          or target_scheduled_date not between target_session.week_start and target_session.week_start + 6 then
          raise exception 'invalid shift values' using errcode = '22023';
        end if;
        perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => array[target_location_id]);
        if not exists (select 1 from public.jobs job where job.id = target_job_id and job.workspace_id = target_workspace_id and job.archived_at is null)
          or not exists (select 1 from public.locations location where location.id = target_location_id and location.workspace_id = target_workspace_id and location.archived_at is null)
          or (target_shift_type_id is not null and not exists (select 1 from public.shift_types shift_type where shift_type.id = target_shift_type_id and shift_type.workspace_id = target_workspace_id and shift_type.archived_at is null))
          or (target_employee_id is not null and not exists (
            select 1 from public.employee_profiles employee
            join public.employee_location_assignments location_assignment
              on location_assignment.employee_id = employee.id and location_assignment.location_id = target_location_id and location_assignment.ended_at is null
            join public.employee_job_assignments job_assignment
              on job_assignment.employee_id = employee.id and job_assignment.job_id = target_job_id and job_assignment.ended_at is null
            where employee.id = target_employee_id and employee.workspace_id = target_workspace_id and employee.archived_at is null
          )) then
          raise exception 'invalid shift reference' using errcode = '23503';
        end if;
      end if;

      if operation = 'create' then
        if request_idempotency_key is not null and exists (
          select 1 from public.schedule_edit_session_shifts shift
          where shift.session_id = target_session_id and shift.idempotency_key = request_idempotency_key
        ) then
          result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
          exit write_shift;
        end if;
        row_shift_id:=coalesce(row_shift_id,gen_random_uuid());
        perform public.schedule_prepare_availability_assignment(actor_user_id,target_workspace_id,row_payload||jsonb_build_object('id',row_shift_id,'session_id',target_session_id),null);
        insert into public.schedule_edit_session_shifts (id, workspace_id, session_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, idempotency_key) values (row_shift_id, target_workspace_id, target_session_id, target_location_id, target_employee_id, target_job_id, target_shift_type_id, target_scheduled_date, target_start_time, target_end_time, row_payload->>'time_basis', row_payload->'time_snapshot', row_payload->>'time_timezone', target_unpaid_break_minutes, target_hide_time_on_badge, target_note, request_idempotency_key);
      elsif operation = 'update' then
        perform public.schedule_prepare_availability_assignment(actor_user_id,target_workspace_id,row_payload||jsonb_build_object('id',row_shift_id,'session_id',target_session_id),(select to_jsonb(s) from public.schedule_edit_session_shifts s where s.workspace_id=target_workspace_id and s.session_id=target_session_id and s.id=row_shift_id));
        update public.schedule_edit_session_shifts shift
        set location_id = target_location_id, employee_id = target_employee_id,
          job_id = target_job_id, shift_type_id = target_shift_type_id,
          scheduled_date = target_scheduled_date, start_time = target_start_time,
          end_time = target_end_time, time_basis=row_payload->>'time_basis', time_snapshot=row_payload->'time_snapshot', time_timezone=row_payload->>'time_timezone', unpaid_break_minutes = target_unpaid_break_minutes, hide_time_on_badge = target_hide_time_on_badge, note = target_note,
          revision = revision + 1, updated_at = now()
        where shift.session_id = target_session_id and shift.id = row_shift_id
          and shift.revision = expected_shift_revision
          and shift.location_id = any(reach);
        if not found then
          raise exception 'shift revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
        end if;
      else
        update public.schedule_availability_overrides set revoked_at=now() where workspace_id=target_workspace_id and shift_id=row_shift_id and revoked_at is null;
        delete from public.schedule_edit_session_shifts shift
        where shift.session_id = target_session_id and shift.id = row_shift_id
          and shift.revision = expected_shift_revision
          and shift.location_id = any(reach);
        if not found then
          raise exception 'shift revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
        end if;
      end if;

      update public.schedule_edit_sessions
      set revision = revision + 1, dirty = true,
        last_heartbeat = now(), expires_at = now() + interval '4 minutes'
      where id = target_session_id;
      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    end write_shift;

    -- An updated published shift becomes a pending update and unlocks.
    if operation = 'update' then
      update public.schedule_edit_session_shifts shift
      set pending_op_type = case
            when shift.source_published_shift_id is not null
             and shift.pending_op_type is distinct from 'delete'
            then 'update'
            else shift.pending_op_type
          end,
          locked = case
            when shift.source_published_shift_id is not null then false
            else shift.locked
          end
      where shift.session_id = target_session_id
        and shift.id = target_shift_id;

      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    end if;
  end if;

  -- c. Labels: the catalog's name for an active label of this workspace, the
  -- shift's own copy for a label it already carries; anything else is refused.
  -- A payload without label_ids keeps the shift's labels; an empty list clears
  -- them (EKRAN-01 B7, as for the note).
  if operation in ('create', 'update') and shift_payload ? 'label_ids' then
    <<labels>>
    declare
      tag_ids uuid[];
      tag_names text[];
    begin
      select * into target_shift from public.schedule_edit_session_shifts shift
      where shift.session_id = target_session_id
        and shift.id = target_shift_id
        and shift.workspace_id = target_workspace_id;
      if target_shift.id is null then
        exit labels;
      end if;

      select coalesce(array_agg(requested.id order by requested.ord), '{}'::uuid[]),
             coalesce(array_agg(coalesce(catalog.name, kept.name) order by requested.ord), '{}'::text[])
      into tag_ids, tag_names
      from (
        select tag.value::uuid as id, min(tag.ord) as ord
        from jsonb_array_elements_text(coalesce(shift_payload->'label_ids', '[]'::jsonb)) with ordinality as tag(value, ord)
        group by tag.value::uuid
      ) requested
      left join public.shift_labels catalog
        on catalog.id = requested.id
       and catalog.workspace_id = target_workspace_id
       and catalog.archived_at is null
      left join lateral (
        select copy.name from unnest(target_shift.label_ids, target_shift.label_names) as copy(id, name)
        where copy.id = requested.id limit 1
      ) kept on true;

      if array_position(tag_names, null) is not null then
        raise exception 'invalid shift reference' using errcode = '23503';
      end if;

      update public.schedule_edit_session_shifts shift
         set label_ids = tag_ids, label_names = tag_names
       where shift.session_id = target_session_id
         and shift.id = target_shift_id
         and shift.workspace_id = target_workspace_id;
      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    end labels;
  end if;

  -- d. A person missing a required document is never on a shift that day.
  if operation in ('create', 'update') then
    select shift.employee_id, shift.scheduled_date
    into mutated_shift
    from public.schedule_edit_session_shifts shift
    where shift.workspace_id = target_workspace_id
      and shift.session_id = target_session_id
      and shift.id = target_shift_id
    limit 1;

    if mutated_shift.employee_id is not null
      and public.employee_has_hard_document_schedule_conflict_service(
        target_workspace_id,
        mutated_shift.employee_id,
        mutated_shift.scheduled_date
      ) then
      raise exception 'employee document hard conflict' using errcode = '23514';
    end if;
  end if;

  -- e. An overridden soft conflict is audited once per request.
  override_note := btrim(coalesce(shift_payload->>'conflict_override_note', ''));

  if operation in ('create', 'update') and char_length(override_note) >= 10 then
    select shift.id
    into audited_shift_id
    from public.schedule_edit_session_shifts shift
    where shift.workspace_id = target_workspace_id
      and shift.session_id = target_session_id
      and (
        shift.id = target_shift_id
        or (
          operation = 'create'
          and request_idempotency_key is not null
          and shift.idempotency_key = request_idempotency_key
        )
      )
    order by (shift.id = target_shift_id) desc
    limit 1;

    if audited_shift_id is not null
      and not exists (
        select 1
        from public.audit_events event
        where event.workspace_id = target_workspace_id
          and event.action = 'schedule.soft_conflict_overridden'
          and event.target_type = 'schedule_edit_session_shift'
          and event.target_id = audited_shift_id::text
          and request_idempotency_key is not null
          and event.metadata->>'idempotency_key' = request_idempotency_key::text
      ) then
      insert into public.audit_events (
        workspace_id,
        actor_user_id,
        action,
        target_type,
        target_id,
        metadata
      ) values (
        target_workspace_id,
        actor_user_id,
        'schedule.soft_conflict_overridden',
        'schedule_edit_session_shift',
        audited_shift_id::text,
        jsonb_build_object(
          'session_id', target_session_id,
          'operation', operation,
          'idempotency_key', request_idempotency_key,
          'note', override_note
        )
      );
    end if;
  end if;

  return result;
end;
$$;


ALTER FUNCTION "public"."mutate_schedule_edit_shift_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "operation" "text", "target_shift_id" "uuid", "expected_shift_revision" integer, "shift_payload" "jsonb", "request_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_time_off_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person uuid;
  zone_name text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee_hub.read');
  select e.id into person from public.employee_profiles e
  where e.workspace_id = target_workspace_id and e.user_id = actor_user_id and e.archived_at is null;
  if person is null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'employee_hub.read';
  end if;
  zone_name := app_private.time_off_timezone(target_workspace_id, person);
  return jsonb_build_object(
    'time_zone', zone_name,
    'today', case when zone_name is null then null else (now() at time zone zone_name)::date end,
    'location_names', coalesce((
      select jsonb_agg(l.name order by a.is_primary desc, a.assigned_at)
      from public.employee_location_assignments a
      join public.locations l on l.id = a.location_id and l.workspace_id = a.workspace_id
      where a.workspace_id = target_workspace_id and a.employee_id = person and a.ended_at is null
        and app_private.location_is_live(l)), '[]'::jsonb),
    'requests', coalesce((
      select jsonb_agg(app_private.time_off_request_view(r) order by r.starts_at desc, r.created_at desc)
      from (select * from public.time_off_requests q
            where q.workspace_id = target_workspace_id and q.employee_id = person and q.kind = 'leave'
            order by q.starts_at desc limit 200) r), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."my_time_off_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_time_off_shifts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "first_day" "date", "last_day" "date", "from_clock" time without time zone DEFAULT NULL::time without time zone, "to_clock" time without time zone DEFAULT NULL::time without time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person uuid;
  zone_name text;
  begins timestamptz;
  ends timestamptz;
  at_stake jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'time_off.request_own');
  select e.id into person from public.employee_profiles e
  where e.workspace_id = target_workspace_id and e.user_id = actor_user_id and e.archived_at is null;
  if person is null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'time_off.request_own';
  end if;
  if first_day is null or last_day is null or (from_clock is null) <> (to_clock is null) or from_clock = '24:00' then
    raise exception 'Choose the days, and both hours unless it is all day' using errcode = '22023', hint = 'time_off.invalid';
  end if;
  if last_day < first_day then
    raise exception 'The last day is before the first day' using errcode = '22023', hint = 'time_off.order';
  end if;
  zone_name := app_private.time_off_timezone(target_workspace_id, person);
  if zone_name is null then
    raise exception 'You need a location before you can ask for time off' using errcode = '55000', hint = 'time_off.no_location';
  end if;
  if from_clock is null then
    if last_day - first_day + 1 > 31 then
      raise exception 'Ask for 31 days or fewer at a time' using errcode = '22023', hint = 'time_off.too_long';
    end if;
    begins := first_day::timestamp at time zone zone_name;
    ends := (last_day + 1)::timestamp at time zone zone_name;
  else
    if last_day + to_clock <= first_day + from_clock then
      raise exception 'The end is before the start' using errcode = '22023', hint = 'time_off.order';
    end if;
    if (last_day + to_clock) - (first_day + from_clock) > interval '31 days' then
      raise exception 'Ask for 31 days or fewer at a time' using errcode = '22023', hint = 'time_off.too_long';
    end if;
    begin
      begins := public.time_off_resolve_clock(first_day + from_clock, zone_name, 'earlier');
      ends := public.time_off_resolve_clock(last_day + to_clock, zone_name, 'earlier');
    exception when sqlstate '22023' then
      raise exception 'These hours do not exist on this date in your time zone'
        using errcode = '22023', hint = 'time_off.no_such_time';
    end;
  end if;
  select coalesce(jsonb_agg(x order by x ->> 'starts_at', x ->> 'id'), '[]'::jsonb) into at_stake
  from jsonb_array_elements(public.time_off_assignment_impact(target_workspace_id, person,
    tstzmultirange(tstzrange(begins, ends, '[)')))) x
  where (x ->> 'starts_at')::timestamptz > now();
  return jsonb_build_object(
    'count', jsonb_array_length(at_stake),
    'shifts', coalesce((select jsonb_agg(jsonb_build_object(
        'id', x ->> 'id',
        'location_name', x ->> 'location_name',
        'job_name', x ->> 'job_name',
        'scheduled_date', x ->> 'scheduled_date',
        'start_time', to_char((x ->> 'start_time')::time, 'HH24:MI'),
        'end_time', to_char((x ->> 'end_time')::time, 'HH24:MI'))) from jsonb_array_elements(at_stake) x), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."my_time_off_shifts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "first_day" "date", "last_day" "date", "from_clock" time without time zone, "to_clock" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_schedule_time_source"("w" "uuid", "payload" "jsonb", "previous" "jsonb" DEFAULT NULL::"jsonb", "preserve_saved_timezone" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare basis text; snap jsonb; tz text; source_type uuid; source_revision integer; ver public.shift_type_time_versions%rowtype;
begin
  select timezone into tz from public.locations where id=(payload->>'location_id')::uuid and workspace_id=w;
  if tz is null then raise exception 'invalid shift location' using errcode='23503'; end if;
  if previous is not null and payload->>'location_id'=previous->>'location_id' then
    tz:=coalesce(nullif(previous->>'time_timezone',''),tz);
  elsif preserve_saved_timezone then
    tz:=coalesce(nullif(payload->>'time_timezone',''),tz);
  end if;
  if not app_private.timezone_name_valid(tz) then
    raise exception 'Invalid shift timezone' using errcode='22023';
  end if;
  basis:=payload->>'time_basis';
  if basis is null and previous is not null then
    if previous->>'time_basis'='type_default' and
      (nullif(payload->>'start_time','')::time,nullif(payload->>'end_time','')::time) is distinct from
      (nullif(previous->>'start_time','')::time,nullif(previous->>'end_time','')::time) then
      raise exception 'Refresh the schedule before changing reference hours' using errcode = 'PT409', hint = 'schedule.reference_hours_changed';
    end if;
    basis:=previous->>'time_basis'; snap:=previous->'time_snapshot';
  else snap:=payload->'time_snapshot'; end if;
  basis:=coalesce(basis,'explicit');
  if basis not in ('explicit','type_default') then raise exception 'invalid shift time source' using errcode='22023'; end if;
  if basis='type_default' then
    if snap is null or snap='null'::jsonb then
      source_type:=(payload->>'shift_type_id')::uuid;
      select default_revision into source_revision from public.shift_types where id=source_type and workspace_id=w;
    else
      source_type:=(snap->>'shift_type_id')::uuid; source_revision:=(snap->>'default_revision')::integer;
    end if;
    select * into ver from public.shift_type_time_versions where workspace_id=w and shift_type_id=source_type and revision=source_revision;
    if ver.shift_type_id is null or ver.start_time is null or ver.end_time is null then
      raise exception 'This shift type has no default hours. Enter start and end time.' using errcode='23514';
    end if;
    if snap is not null and snap<>'null'::jsonb and
      ((snap->>'start_time')::time,(snap->>'end_time')::time) is distinct from (ver.start_time,ver.end_time) then
      raise exception 'Shift default hours changed; refresh the reference before saving' using errcode = 'PT409', hint = 'schedule.reference_hours_changed';
    end if;
    if previous is not null and payload->>'location_id'=previous->>'location_id' then
      tz:=coalesce(nullif(previous->>'time_timezone',''),tz);
    end if;
    snap:=jsonb_build_object('shift_type_id',source_type,'default_revision',source_revision,
      'start_time',to_char(ver.start_time,'HH24:MI'),'end_time',to_char(ver.end_time,'HH24:MI'),'timezone',tz);
    payload:=payload||jsonb_build_object('start_time',to_char(ver.start_time,'HH24:MI'),'end_time',to_char(ver.end_time,'HH24:MI'));
  else
    if nullif(payload->>'start_time','') is null or nullif(payload->>'end_time','') is null then
      raise exception 'Enter start and end time.' using errcode='22023'; end if;
    if (payload->>'start_time')::time=(payload->>'end_time')::time then
      raise exception 'Start and end time cannot be the same.' using errcode='22023'; end if;
    snap:=null;
    if previous is not null and payload->>'location_id'=previous->>'location_id' then tz:=coalesce(nullif(previous->>'time_timezone',''),tz); end if;
  end if;
  return payload||jsonb_build_object('time_basis',basis,'time_snapshot',snap,'time_timezone',tz);
end; $$;


ALTER FUNCTION "public"."normalize_schedule_time_source"("w" "uuid", "payload" "jsonb", "previous" "jsonb", "preserve_saved_timezone" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_workspace_widget_order"("target_widget_order" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with allowed(value, position) as (
    values
      ('operations', 1),
      ('pending_requests', 2),
      ('open_shifts', 3),
      ('announcements', 4),
      ('todos', 5),
      ('quick_actions', 6)
  ),
  input_order as (
    select input.value, min(input.ordinality) as ordinality
    from unnest(coalesce(target_widget_order, '{}'::text[])) with ordinality input(value, ordinality)
    join allowed on allowed.value = input.value
    group by input.value
  )
  select array_agg(allowed.value order by coalesce(input_order.ordinality, 1000 + allowed.position), allowed.position)
  from allowed
  left join input_order on input_order.value = allowed.value;
$$;


ALTER FUNCTION "public"."normalize_workspace_widget_order"("target_widget_order" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_dispatch_alerts_service"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  quota app_private.notification_quotas;
  day_start timestamptz := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  month_start timestamptz := date_trunc('month', now() at time zone 'UTC') at time zone 'UTC';
  day_key text := to_char(now() at time zone 'UTC', 'YYYY-MM-DD');
  month_key text := to_char(now() at time zone 'UTC', 'YYYY-MM');
  sent_today integer;
  sent_month integer;
  candidate record;
  late record;
  late_period text := to_char(date_bin('30 minutes', now(), timestamptz '2000-01-01') at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI');
  full_now text[];
  raised jsonb := '[]'::jsonb;
begin
  for quota in select * from app_private.notification_quotas order by channel loop
    select count(*) filter (where d.sent_at >= day_start)::integer, count(*)::integer
      into sent_today, sent_month
    from public.notification_deliveries d
    where d.channel = quota.channel and d.sent_at >= month_start;
    full_now := '{}';
    for candidate in
      select * from (values
        (1, 'quota_day_full', day_key, sent_today, quota.daily_limit - quota.reserved_daily, 1.0),
        (2, 'quota_day_80', day_key, sent_today, quota.daily_limit - quota.reserved_daily, 0.8),
        (3, 'quota_month_full', month_key, sent_month, quota.monthly_limit - quota.reserved_monthly, 1.0),
        (4, 'quota_month_80', month_key, sent_month, quota.monthly_limit - quota.reserved_monthly, 0.8)
      ) v(place, kind, period, sent, cap, part)
      where v.cap is not null and v.sent >= ceil(v.cap * v.part)
      order by v.place
    loop
      -- Full says it all: no 80% alert with or after a full one in the same period.
      continue when candidate.part = 0.8 and (replace(candidate.kind, '_80', '_full') = any (full_now)
        or exists (select 1 from app_private.notification_alerts a
                   where a.kind = replace(candidate.kind, '_80', '_full') and a.channel = quota.channel
                     and a.period = candidate.period));
      if candidate.part = 1.0 then
        full_now := full_now || candidate.kind::text;
      end if;
      continue when exists (select 1 from app_private.notification_alerts a
        where a.kind = candidate.kind and a.channel = quota.channel and a.period = candidate.period);
      raised := raised || jsonb_build_array(jsonb_build_object('kind', candidate.kind, 'channel', quota.channel,
        'period', candidate.period, 'sent', candidate.sent, 'limit', candidate.cap));
    end loop;
  end loop;

  for late in
    select d.channel, count(*)::integer due,
      max(extract(epoch from now() - case when d.status = 'sending' then d.lease_expires_at else d.next_attempt_at end))::integer waited
    from public.notification_deliveries d
    where d.channel = any (app_private.dispatched_channels())
      and app_private.delivery_due(d.status, d.next_attempt_at, d.lease_expires_at)
    group by d.channel
    having max(now() - case when d.status = 'sending' then d.lease_expires_at else d.next_attempt_at end) > interval '2 minutes'
    order by d.channel
  loop
    -- Once per half hour while it lasts.
    continue when exists (select 1 from app_private.notification_alerts a
      where a.kind = 'late' and a.channel = late.channel and a.period = late_period);
    raised := raised || jsonb_build_array(jsonb_build_object('kind', 'late', 'channel', late.channel,
      'period', late_period, 'waiting_seconds', late.waited, 'due', late.due));
  end loop;
  return raised;
end;
$$;


ALTER FUNCTION "public"."notification_dispatch_alerts_service"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."onboarding_phone_in_use_service"("target_user_id" "uuid", "typed_phone" "text", "target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_case public.employee_onboarding_cases%rowtype;
begin
  perform app_private.authorize(target_user_id, app_private.onboarding_self_workspace(target_user_id, target_workspace_id, true), 'onboarding.self');
  select onboarding.* into target_case
  from public.employee_onboarding_cases onboarding
  where onboarding.id = app_private.employee_onboarding_case_id(target_user_id, target_workspace_id);
  if target_case.id is null then
    raise exception 'onboarding unavailable' using errcode = 'P0002';
  end if;
  -- Open only while the profile can still be saved: after that it would only
  -- tell somebody whose number a guess is (TEL-2 review, item 1).
  if target_case.status in ('submitted', 'approved', 'cancelled') then
    raise exception 'onboarding cannot be edited' using errcode = '22023';
  end if;
  return app_private.phone_used_in_workspace(
    target_case.workspace_id,
    app_private.account_phone_e164(typed_phone),
    target_case.employee_id
  );
end;
$$;


ALTER FUNCTION "public"."onboarding_phone_in_use_service"("target_user_id" "uuid", "typed_phone" "text", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organization_job_counts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  read_rule app_private.authz_actions;
begin
  perform app_private.authorize_employee_list(actor_user_id, target_workspace_id);
  select * into read_rule from app_private.authz_actions r where r.key = 'employee.list';
  with memberships as materialized (
    select a.employee_id,a.job_id,j.department_id,j.archived_at
    from public.employee_job_assignments a
    join public.jobs j on j.id=a.job_id and j.workspace_id=a.workspace_id
    join public.employee_profiles e on e.id=a.employee_id and e.workspace_id=a.workspace_id
    where a.workspace_id=target_workspace_id and a.ended_at is null and e.archived_at is null
      and app_private.authz_check(me, read_rule, null, e.id, null) is null
  )
  select jsonb_build_object(
    'jobs',coalesce((select jsonb_agg(to_jsonb(c)) from (
      select job_id as id,count(distinct employee_id) as employee_count from memberships group by job_id)c),'[]'),
    'departments',coalesce((select jsonb_agg(to_jsonb(c)) from (
      select department_id as id,count(distinct employee_id) as employee_count from memberships
      where department_id is not null group by department_id)c),'[]')
  ) into result;
  return result;
end; $$;


ALTER FUNCTION "public"."organization_job_counts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_account_deletion_delivery_service"("target_request_id" "uuid", "target_lease_id" "uuid", "delivery_kind" "text", "recovery_token_digest" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare request public.account_deletion_requests%rowtype;
begin
  select * into request from public.account_deletion_requests
  where id = target_request_id and status = 'pending'
    and work_lease_id = target_lease_id and work_lease_until > now()
    and restore_until > now() for update;
  if request.id is null then raise exception 'account deletion lease unavailable'; end if;
  insert into public.account_deletion_deliveries(request_id, delivery_kind, token_digest)
  values (request.id, delivery_kind, recovery_token_digest)
  on conflict on constraint account_deletion_deliveries_pkey do nothing;
  if not exists (select 1 from public.account_deletion_deliveries d
    where d.request_id = request.id and d.delivery_kind = prepare_account_deletion_delivery_service.delivery_kind
      and d.token_digest = recovery_token_digest) then
    raise exception 'account deletion delivery token changed';
  end if;
  return jsonb_build_object('email', request.typed_email, 'restore_until', request.restore_until);
end;
$$;


ALTER FUNCTION "public"."prepare_account_deletion_delivery_service"("target_request_id" "uuid", "target_lease_id" "uuid", "delivery_kind" "text", "recovery_token_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_account_deletion_recovery_resend_service"("account_email" "text", "recovery_token_digest" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  target_request public.account_deletion_requests%rowtype;
  normalized_email text := lower(btrim(coalesce(account_email, '')));
begin
  if recovery_token_digest is null
    or recovery_token_digest !~ '^[a-f0-9]{64}$' then
    raise exception 'valid recovery token digest required' using errcode = '22023';
  end if;

  select request.* into target_request
  from public.account_deletion_requests request
  join auth.users auth_user on auth_user.id = request.user_id
  where request.status = 'pending'
    and request.restore_until > now()
    and lower(btrim(auth_user.email)) = normalized_email
  order by request.requested_at desc
  limit 1
  for update of request;

  if target_request.id is null then
    return null;
  end if;

  -- KK-11: at most one new link per fifteen minutes; the link already in the
  -- inbox stays valid until then.
  if target_request.recovery_token_rotated_at > now() - interval '15 minutes' then
    return null;
  end if;

  update public.account_deletion_requests
  set recovery_token_digest = prepare_account_deletion_recovery_resend_service.recovery_token_digest,
      recovery_token_rotated_at = now(),
      updated_at = now()
  where id = target_request.id;

  return jsonb_build_object(
    'request_id', target_request.id,
    'user_id', target_request.user_id,
    'email', normalized_email,
    'restore_until', target_request.restore_until
  );
end;
$_$;


ALTER FUNCTION "public"."prepare_account_deletion_recovery_resend_service"("account_email" "text", "recovery_token_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_employee_invitation_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "employee_email" "text", "target_employee_role_id" "uuid", "target_management_role_id" "uuid", "target_managed_location_ids" "uuid"[], "invitation_token_hash" "text", "invitation_expires_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  invitation_id uuid;
  places uuid[] := array(select distinct p from unnest(coalesce(target_managed_location_ids, '{}')) p order by p);
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.invite', target_person => target_employee_id);
  if employee_email <> lower(btrim(employee_email)) or employee_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'valid normalized invitation email required' using errcode = '22023';
  end if;
  if invitation_token_hash !~ '^[0-9a-f]{64}$' or invitation_expires_at <= now() then
    raise exception 'valid invitation token and expiry required' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.employee_profiles employee
    where employee.id = target_employee_id
      and employee.workspace_id = target_workspace_id
      and employee.archived_at is null
      and employee.user_id is null
  ) then
    raise exception 'invitable employee not found' using errcode = 'P0002';
  end if;

  perform app_private.invitation_access_check(actor_user_id, target_workspace_id,
    target_employee_role_id, target_management_role_id, places);

  -- DAVET-ERISIM: Remote and Exclude from schedule no longer lift it.
  if not exists (
    select 1 from public.employee_location_assignments
    where employee_id = target_employee_id and ended_at is null
  ) then
    raise exception 'employee requires a location before invitation' using errcode = '22023';
  end if;

  -- Inviting again takes back what was waiting: only an invitation the actor
  -- could take back themselves (nf-guvenlik O-2).
  if exists (
    select 1 from public.employee_invitations pending
    where pending.employee_id = target_employee_id and pending.status = 'pending'
      and not app_private.can_invite_with_role(actor_user_id, target_workspace_id, pending.role_id)
  ) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  update public.employee_invitations
  set status = 'revoked', revoked_at = now(), updated_at = now()
  where employee_id = target_employee_id and status = 'pending';
  insert into public.employee_invitations (
    workspace_id, employee_id, email, employee_role_id, management_role_id, managed_location_ids,
    token_hash, expires_at, created_by, delivery_status
  ) values (
    target_workspace_id, target_employee_id, employee_email, target_employee_role_id, target_management_role_id,
    places, invitation_token_hash, invitation_expires_at, actor_user_id, 'pending'
  ) returning id into invitation_id;
  update public.employee_profiles
  set invitation_email = employee_email, revision = revision + 1, updated_at = now()
  where id = target_employee_id;
  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (target_workspace_id, target_employee_id, actor_user_id, 'employee.invited', 'Employee invitation prepared');
  return invitation_id;
end;
$_$;


ALTER FUNCTION "public"."prepare_employee_invitation_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "employee_email" "text", "target_employee_role_id" "uuid", "target_management_role_id" "uuid", "target_managed_location_ids" "uuid"[], "invitation_token_hash" "text", "invitation_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_weekly_schedule_assignment"("actor" "uuid", "w" "uuid", "s" "jsonb", "previous" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a jsonb; preview jsonb; evidence jsonb; logical_id uuid:=coalesce(s->>'source_shift_id',s->>'id')::uuid;
 loc uuid:=(s->>'location_id')::uuid; emp uuid:=(s->>'employee_id')::uuid;
begin
 perform public.availability_lock_workspace(w);
 if logical_id is null then
  raise exception 'Schedule location access denied' using errcode='42501'; end if;
 perform app_private.authorize(actor, w, 'schedule.edit', target_locations => array[loc]);
 if emp is not null and not exists(select 1 from public.employee_location_assignments
  where workspace_id=w and employee_id=emp and location_id=loc and ended_at is null) then
  raise exception 'Employee is not assigned to this location' using errcode='42501'; end if;
 
 
 s:=s||jsonb_build_object('_exclude_shift_id',logical_id);
 a:=public.assess_weekly_shift_availability(w,emp,s);
 if a->>'operation' in ('blocked','verification_required') then
  raise exception '%',coalesce((select string_agg(r->>'message',' ') from jsonb_array_elements(a->'reasons') r where r->>'severity'='block'),'Scheduling rules block this assignment') using errcode='23514',detail=a::text;
 end if;
 if emp is null then
   if a->>'operation'='warning_requires_override' and s->>'availability_assessment_fingerprint' is distinct from
    public.assess_weekly_shift_availability(w,emp,s-'id'-'source_shift_id')->>'fingerprint' then
    raise exception 'Review the current availability assessment before saving' using errcode='PT409', hint='schedule.availability_review_required';
   end if;
   if a->>'operation'='warning_requires_override' then
    insert into public.audit_events(workspace_id,actor_user_id,action,target_type,target_id,metadata)
    values(w,actor,'schedule.conflict_accepted','shift',logical_id::text,jsonb_build_object('assessment',a));
   end if;
   return;
  end if;
  evidence:=public.schedule_availability_override(w,s,a);
 -- Only an existing same-identity assignment can reuse its acceptance.
 if evidence is not null and previous is not null
  and coalesce(previous->>'source_shift_id',previous->>'id')=logical_id::text
  and previous->>'employee_id'=emp::text then return; end if;
 if a->>'operation'='warning_requires_override' then
  preview:=public.assess_weekly_shift_availability(w,emp,s-'id'-'source_shift_id');
  if s->>'availability_assessment_fingerprint' is distinct from preview->>'fingerprint' then
   raise exception 'Review the current availability assessment before saving' using errcode='PT409', hint='schedule.availability_review_required'; end if;
 end if;
 update public.schedule_availability_overrides set revoked_at=now() where workspace_id=w and shift_id=logical_id and revoked_at is null;
 if a->>'operation'='warning_requires_override' then
  insert into public.schedule_availability_overrides(workspace_id,shift_id,employee_id,location_id,assessment_fingerprint,assessment,reason,actor_user_id)
  values(w,logical_id,emp,loc,a->>'fingerprint',a,
   case when a->>'warning_policy'='confirm' then 'Schedule conflict confirmed by manager.' else 'Schedule warning acknowledged (warn policy).' end,actor);
 end if;
end; $$;


ALTER FUNCTION "public"."prepare_weekly_schedule_assignment"("actor" "uuid", "w" "uuid", "s" "jsonb", "previous" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_last_workspace_owner_removal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  workspace_state public.workspace_lifecycle_status;
  transfer_bypass boolean := coalesce(current_setting('app.owner_transfer', true), '') = 'on';
  owner_role uuid := (select r.id from public.workspace_roles r where r.workspace_id = old.workspace_id and r.access_class = 'owner');
begin
  if old.role_id is distinct from owner_role or old.status <> 'active' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  select lifecycle_status into workspace_state
  from public.workspaces
  where id = old.workspace_id;

  if workspace_state = 'deleted' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'UPDATE' and new.role_id = owner_role and new.status = 'active' then
    return new;
  end if;

  if not exists (
    select 1
    from public.workspace_memberships other
    where other.workspace_id = old.workspace_id
      and other.id <> old.id
      and other.role_id = owner_role
      and other.status = 'active'
  ) then
    raise exception 'workspace must retain an active owner' using errcode = '23514';
  end if;

  if not transfer_bypass then
    raise exception 'owner role can only be changed through ownership transfer'
      using errcode = '23514';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."prevent_last_workspace_owner_removal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_owner_employee_archive"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.archived_at is not null
    and old.archived_at is distinct from new.archived_at
    and old.user_id is not null
    and exists (
      select 1
      from public.workspace_memberships membership
      where membership.workspace_id = old.workspace_id
        and membership.user_id = old.user_id
        and app_private.role_class(membership.role_id) = 'owner'
    ) then
    raise exception 'owner employee record cannot be archived through ordinary lifecycle'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_owner_employee_archive"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_announcement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid", "target_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  w uuid := target_workspace_id;
  me app_private.actor_state;
  stored public.announcements;
  shown text := 'new';
  n jsonb;
  author uuid;
  reason text;
  intent text := coalesce(nullif(target_payload ->> 'intent', ''), 'publish');
  impact jsonb := jsonb_build_object('fingerprint', null, 'shifts', '[]'::jsonb, 'quiet', '[]'::jsonb,
    'counts', jsonb_build_object('removed', 0, 'edited', 0, 'opened', 0, 'kept', 0, 'quiet', 0));
  offered jsonb := '[]'::jsonb;
  span record;
  -- Whose shifts are named: only where the writer may read the Schedule (D1);
  -- the rest are counted.
  seen uuid[];
begin
  perform app_private.authorize(actor_user_id, w, 'announcement.read');
  seen := app_private.scope_set(actor_user_id, w, 'schedule.read');
  if intent not in ('draft', 'schedule', 'publish', 'save') then
    raise exception 'valid announcement intent required' using errcode = '22023', hint = 'announcement.invalid';
  end if;
  perform app_private.announcement_release(w);
  me := app_private.actor(actor_user_id, w);
  if target_announcement_id is not null then
    select * into stored from public.announcements where id = target_announcement_id and workspace_id = w;
    if stored.id is null or not app_private.announcement_visible(me, stored) then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'announcement.write';
    end if;
    reason := app_private.announcement_reason(me, app_private.announcement_places(stored.id), stored.created_by,
      app_private.announcement_dates(stored));
    if reason is not null then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'announcement.write';
    end if;
    shown := app_private.announcement_display_status(stored);
    if shown in ('past', 'archived') then
      raise exception 'This post can''t change anymore.' using errcode = 'PT409', hint = 'announcement.read_only';
    end if;
  end if;
  author := coalesce(stored.created_by, actor_user_id);
  n := app_private.announcement_proposal(w, stored, coalesce(target_payload, '{}'::jsonb), author);
  perform app_private.announcement_authorize(me, n, author);

  if (n ->> 'hours')::boolean and n ->> 'starts_on' is not null then
    impact := app_private.announcement_impact(w, stored.id, (n ->> 'starts_on')::date, (n ->> 'ends_on')::date,
      n -> 'locations', n -> 'choices', stored.choices_saved_at);
  end if;
  if shown = 'published' then
    offered := app_private.announcement_back_rows(stored, (n ->> 'starts_on')::date, (n ->> 'ends_on')::date, n -> 'locations');
  elsif shown = 'unpublished' then
    offered := app_private.announcement_back_rows(stored, null, null, '[]'::jsonb);
  end if;
  select * into span from app_private.announcement_span(w, (n ->> 'starts_on')::date, (n ->> 'ends_on')::date,
    (n ->> 'event_from')::time, (n ->> 'event_until')::time, n ->> 'time_zone', n -> 'locations');

  return jsonb_build_object(
    'problems', app_private.announcement_problems(w, stored, n, intent),
    'fingerprint', impact -> 'fingerprint',
    'shifts', coalesce((select jsonb_agg(x order by place) from jsonb_array_elements(impact -> 'shifts') with ordinality s(x, place)
                        where (x ->> 'location_id')::uuid = any (seen)), '[]'::jsonb),
    'hidden_count', (select count(*) from jsonb_array_elements(impact -> 'shifts') x
                     where not (x ->> 'location_id')::uuid = any (seen)),
    'quiet_count', (impact -> 'counts' ->> 'quiet')::integer,
    'counts', impact -> 'counts',
    'bring_back', coalesce((select jsonb_agg(x order by place) from jsonb_array_elements(offered) with ordinality s(x, place)
                            where (x ->> 'location_id')::uuid = any (seen)), '[]'::jsonb),
    'time_zone', n ->> 'time_zone',
    'starts_at', span.starts_at,
    'ends_at', span.ends_at,
    'recipient_count', cardinality(app_private.announcement_audience(w,
      array(select x::uuid from jsonb_array_elements_text(n -> 'live_location_ids') x),
      array(select x::uuid from jsonb_array_elements_text(n -> 'people') x),
      array(select (s ->> 'employee_id')::uuid from jsonb_array_elements(impact -> 'shifts') s
            where s ->> 'outcome' <> 'kept' and s ->> 'employee_id' is not null
            union
            select change.employee_id from public.announcement_shift_changes change
            where change.announcement_id = stored.id and not change.silent and change.brought_back_at is null),
      author)));
end;
$$;


ALTER FUNCTION "public"."preview_announcement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid", "target_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_document_publication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d public.document_types%rowtype; result jsonb; effects jsonb; scope_options jsonb; pair text[]; identities jsonb; token text;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 select * into d from public.document_types where id=target_document_type_id and workspace_id=target_workspace_id;
 if d.id is null then raise exception 'document type not found' using errcode='P0002'; end if;
 if d.archived_at is not null then raise exception 'Archived documents cannot be published; restore first' using errcode='PT409',hint='document.archived'; end if;
 -- Only publishing checks that the target still names live places, jobs and people; Unpublish
 -- and Archive must work after a target location, job or person is archived (BELGE-ARSIV review).
 if d.publication_status='draft' then
  perform app_private.assert_document_definition_target(actor_user_id,target_workspace_id,d.lifecycle_settings->'target');
 end if;
 result:=app_private.preview_lifecycle_definition(actor_user_id,target_workspace_id,d.id,'document');
 if d.publication_status='published' then
  select coalesce(jsonb_agg(jsonb_build_object('employee_id',r.employee_id,'employee_name',concat_ws(' ',e.first_name,e.last_name),'employee_revision',e.revision,
    'requirement_id',r.id,'revision',r.lifecycle_revision,'action','pause','deadline_action','pause') order by r.id),'[]') into effects
  from public.employee_onboarding_requirements r join public.employee_profiles e on e.id=r.employee_id and e.workspace_id=r.workspace_id
  where r.workspace_id=target_workspace_id and r.source_id=d.id and r.kind='document' and r.lifecycle_retired_at is null and r.lifecycle_closed_at is null and not r.lifecycle_exempt and not r.lifecycle_assignment_disabled;
  result:=jsonb_set(result,'{employees}',effects);
 end if;
 scope_options:=public.document_definition_target_options_service(actor_user_id,target_workspace_id);
 -- Include selected identities and the actual locations/jobs/departments of affected employees.
 foreach pair slice 1 in array array[['location_ids','locations'],['department_ids','departments'],['job_ids','jobs'],['employee_ids','named_people']] loop
  select coalesce(jsonb_agg(o order by o->>'name',o->>'id'),'[]') into identities
  from jsonb_array_elements(scope_options->case when pair[2]='named_people' then 'employees' else pair[2] end) o
  where (pair[2]<>'named_people' and jsonb_array_length(coalesce(d.lifecycle_settings->'target'->pair[1],'[]'))=0) or (d.lifecycle_settings->'target'->pair[1]) ? (o->>'id') or (pair[2]<>'named_people' and exists(
   select 1 from jsonb_array_elements(result->'employees') effect
   where effect->>'action' not in ('unchanged','exempt') and (
    (pair[2]='locations' and exists(select 1 from public.employee_location_assignments a where a.workspace_id=target_workspace_id and a.employee_id=(effect->>'employee_id')::uuid and a.ended_at is null and a.location_id=(o->>'id')::uuid)) or
    (pair[2] in ('jobs','departments') and exists(select 1 from public.employee_job_assignments a join public.jobs j on j.id=a.job_id and j.workspace_id=a.workspace_id where a.workspace_id=target_workspace_id and a.employee_id=(effect->>'employee_id')::uuid and a.ended_at is null and (case when pair[2]='jobs' then j.id else j.department_id end)=(o->>'id')::uuid))
   )));
  result:=result||jsonb_build_object(pair[2],identities);
 end loop;
 -- Return exact matcher membership even for unchanged/exempt rows; bind it to the confirmation token.
 select coalesce(jsonb_agg(effect || jsonb_build_object('matches_target',
   exists(select 1 from public.employee_profiles e join public.workspace_memberships m on m.workspace_id=e.workspace_id and m.user_id=e.user_id
    where e.id=(effect->>'employee_id')::uuid and e.workspace_id=target_workspace_id and e.archived_at is null and m.status in ('active','pending_activation')
      and app_private.document_target_matches(e.workspace_id,e.id,d.lifecycle_settings->'target')))
   order by position),'[]') into effects
 from jsonb_array_elements(result->'employees') with ordinality as entries(effect,position);
 result:=jsonb_set(result,'{employees}',effects);
 result:=(result-'preview_token')||jsonb_build_object('publication_revision',d.publication_revision,'target',d.lifecycle_settings->'target','assignment_scope',d.lifecycle_settings->>'assignment_scope','transition',case when d.publication_status='draft' then 'publish' else 'unpublish' end);
 token:=encode(extensions.digest(convert_to(jsonb_build_object('actor',actor_user_id,'definition',to_jsonb(d),'impact',result)::text,'UTF8'),'sha256'),'hex');
 return result||jsonb_build_object('preview_token',token);
end;
$$;


ALTER FUNCTION "public"."preview_document_publication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_employee_access_change_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "next_employee_role_id" "uuid", "next_management_role_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  member public.workspace_memberships := app_private.access_change_target(actor_user_id, target_workspace_id,
    target_employee_id, next_employee_role_id, next_management_role_id);
begin
  return app_private.access_change_impact(target_workspace_id, member, target_employee_id, next_employee_role_id);
end;
$$;


ALTER FUNCTION "public"."preview_employee_access_change_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "next_employee_role_id" "uuid", "next_management_role_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_employee_document_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "proposed_location_ids" "uuid"[], "proposed_job_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; d app_private.lifecycle_definition%rowtype; p public.employee_profiles%rowtype; m public.workspace_memberships%rowtype;
 result jsonb:='[]'; matching boolean; action text; readable boolean; approved boolean; next_deadline timestamptz;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'employee.save',target_person=>target_employee_id);
 select * into p from public.employee_profiles where id=target_employee_id and workspace_id=target_workspace_id;
 if p.id is null then raise exception 'employee unavailable' using errcode='P0002'; end if;
 if proposed_location_ids is null or proposed_job_ids is null or cardinality(proposed_location_ids)>100 or cardinality(proposed_job_ids)>100
  or exists(select 1 from unnest(proposed_location_ids) proposed(id) where proposed.id is null or not exists(select 1 from public.locations l where l.id=proposed.id and l.workspace_id=target_workspace_id and l.archived_at is null) or not proposed.id = any (app_private.scope_set(actor_user_id,target_workspace_id,'employee.save')))
  or exists(select 1 from unnest(proposed_job_ids) proposed(id) where proposed.id is null or not exists(select 1 from public.jobs j where j.id=proposed.id and j.workspace_id=target_workspace_id and j.archived_at is null))
 then raise exception 'Not allowed' using errcode='42501', hint='authz.out_of_scope', detail='employee.save'; end if;
 select * into m from public.workspace_memberships where workspace_id=target_workspace_id and user_id=p.user_id;
 if p.archived_at is not null or m.id is null or m.status not in ('active','pending_activation') then return result; end if;
 readable:=app_private.authz_reason(actor_user_id,target_workspace_id,'documents.read',null,target_employee_id) is null;
 for r in select * from public.employee_onboarding_requirements where workspace_id=target_workspace_id and employee_id=target_employee_id and kind in ('document','acknowledgement') and lifecycle_retired_at is null and source_id is not null and not lifecycle_exempt and not lifecycle_assignment_disabled loop
  matching:=app_private.document_target_matches_assignments(target_workspace_id,target_employee_id,r.lifecycle_settings->'target',proposed_location_ids,proposed_job_ids);
  action:=case when not matching and r.lifecycle_closed_at is null then 'remove' when matching and (r.lifecycle_closed_at is not null or r.status='superseded') then 'reopen' end;
  if action is null then continue; end if;
  next_deadline:=null;
  if action='reopen' then
   r.lifecycle_closed_at:=null; if r.status='superseded' then r.status:='not_started'; end if;
   approved:=app_private.document_obligation_state(r,now())='completed';
   if not approved and m.status='active' and r.lifecycle_settings->>'mode'<>'optional' then next_deadline:=now()+(r.lifecycle_settings->>'period_days')::integer*interval '24 hours'; end if;
  end if;
  result:=result||jsonb_build_array(jsonb_build_object('title',case when readable then r.title else 'Document requirement' end,'action',action,'deadline_at',next_deadline,'period_days',(r.lifecycle_settings->>'period_days')::integer,'clears_block',action='remove' and app_private.document_obligation_blocked(r,now())));
 end loop;
 for d in select * from app_private.lifecycle_definition q where q.workspace_id=target_workspace_id and q.archived_at is null and q.current_version
  and (m.status='pending_activation' or q.lifecycle_settings->>'assignment_scope'='all_active')
  and app_private.document_target_matches_assignments(target_workspace_id,target_employee_id,q.lifecycle_settings->'target',proposed_location_ids,proposed_job_ids)
  and not exists(select 1 from public.employee_onboarding_requirements existing_req where existing_req.workspace_id=target_workspace_id and existing_req.employee_id=target_employee_id and existing_req.kind::text=q.kind and existing_req.source_id=q.id and existing_req.lifecycle_retired_at is null) loop
  next_deadline:=case when m.status='active' and d.lifecycle_settings->>'mode'<>'optional' then now()+(d.lifecycle_settings->>'period_days')::integer*interval '24 hours' end;
  result:=result||jsonb_build_array(jsonb_build_object('title',case when readable then d.title else 'Document requirement' end,'action','assign','deadline_at',next_deadline,'period_days',(d.lifecycle_settings->>'period_days')::integer,'clears_block',false));
 end loop;
 return result;
end;
$$;


ALTER FUNCTION "public"."preview_employee_document_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "proposed_location_ids" "uuid"[], "proposed_job_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_employee_invitation_service"("invitation_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (
      select jsonb_build_object(
        'state', case
          when invitation.status = 'pending'::public.employee_invitation_status
               and invitation.expires_at <= now()
            then 'expired'
          when invitation.status = 'revoked'::public.employee_invitation_status
               and exists (
                 select 1
                 from public.employee_invitations newer
                 where newer.employee_id = invitation.employee_id
                   and newer.workspace_id = invitation.workspace_id
                   and newer.email = invitation.email
                   and newer.status = 'pending'::public.employee_invitation_status
                   and newer.id <> invitation.id
               )
            then 'replaced'
          when invitation.status <> 'pending'::public.employee_invitation_status
            then invitation.status::text
          when workspace.lifecycle_status <> 'active'::public.workspace_lifecycle_status
               and not (
                 workspace.lifecycle_status = 'closure_scheduled'::public.workspace_lifecycle_status
                 and workspace.closure_effective_at > now()
               )
            then 'workspace_unavailable'
          else 'valid'
        end,
        'workspace_name', workspace.name,
        'email', invitation.email,
        'expires_at', invitation.expires_at
      )
      from public.employee_invitations invitation
      join public.workspaces workspace on workspace.id = invitation.workspace_id
      where invitation.token_hash = preview_employee_invitation_service.invitation_token_hash
      limit 1
    ),
    jsonb_build_object('state', 'not_found')
  );
$$;


ALTER FUNCTION "public"."preview_employee_invitation_service"("invitation_token_hash" "text") OWNER TO "postgres";


