ALTER FUNCTION "public"."preview_policy_definition_apply_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule_auto_fill_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target_session public.schedule_edit_sessions%rowtype; open_shift record; candidate_payload jsonb; recommended uuid;
  proposals jsonb:='[]'::jsonb; unfilled jsonb:='[]'::jsonb; unsigned jsonb;
begin
  select * into target_session from public.schedule_edit_sessions s where s.id=target_session_id and s.workspace_id=target_workspace_id;
  if target_session.id is null or target_session.holder_user_id<>actor_user_id then raise exception 'edit session not found' using errcode='P0002'; end if;
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => target_session.location_ids);
  if target_session.status <> 'active' then raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
  elsif target_session.expires_at <= now() then raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired'; end if;
  for open_shift in select s.*,l.name location_name,j.name job_name from public.schedule_edit_session_shifts s
    join public.locations l on l.id=s.location_id join public.jobs j on j.id=s.job_id
    where s.session_id=target_session.id and s.employee_id is null order by s.scheduled_date,s.start_time,s.id loop
    with eligible as (
      select e.id employee_id,coalesce(nullif(e.preferred_name,''),e.first_name||' '||e.last_name) employee_name,ja.is_primary,assessed.a->>'fingerprint' availability_fingerprint,
        coalesce((select sum(case when x.end_time<=x.start_time then 1440 else 0 end + extract(epoch from (x.end_time-x.start_time))/60)::integer
          from public.schedule_edit_session_shifts x where x.session_id=target_session.id and x.employee_id=e.id),0) scheduled_minutes
      from public.employee_profiles e
      join public.employee_location_assignments la on la.employee_id=e.id and la.workspace_id=e.workspace_id and la.location_id=open_shift.location_id and la.ended_at is null
      join public.employee_job_assignments ja on ja.employee_id=e.id and ja.workspace_id=e.workspace_id and ja.job_id=open_shift.job_id and ja.ended_at is null
      cross join lateral (select public.assess_weekly_shift_availability(target_workspace_id,e.id,to_jsonb(open_shift)||jsonb_build_object('employee_id',e.id)) a) assessed
      where e.workspace_id=target_workspace_id and e.archived_at is null
      and not exists(select 1 from public.schedule_edit_session_shifts x where x.session_id=target_session.id and x.employee_id=e.id
        and tsrange(x.scheduled_date+x.start_time,x.scheduled_date+x.end_time+case when x.end_time<=x.start_time then interval '1 day' else interval '0' end,'[)')
          && tsrange(open_shift.scheduled_date+open_shift.start_time,open_shift.scheduled_date+open_shift.end_time+case when open_shift.end_time<=open_shift.start_time then interval '1 day' else interval '0' end,'[)'))
      and assessed.a->>'operation'='allowed' and not coalesce((assessed.a->>'has_availability_conflict')::boolean,false)
      and not exists(select 1 from jsonb_array_elements(proposals) p where (p->>'recommended_employee_id')::uuid=e.id
        and tsrange((p->>'scheduled_date')::date+(p->>'start_time')::time,(p->>'scheduled_date')::date+(p->>'end_time')::time+case when (p->>'end_time')::time<=(p->>'start_time')::time then interval '1 day' else interval '0' end,'[)')
          && tsrange(open_shift.scheduled_date+open_shift.start_time,open_shift.scheduled_date+open_shift.end_time+case when open_shift.end_time<=open_shift.start_time then interval '1 day' else interval '0' end,'[)'))
    ), ranked as (select *,min(scheduled_minutes) over() min_minutes from eligible)
    select coalesce(jsonb_agg(jsonb_build_object('employee_id',employee_id,'employee_name',employee_name,'scheduled_minutes',scheduled_minutes,
      'availability_fingerprint',availability_fingerprint,'primary_job',is_primary,'reasons',to_jsonb(array_remove(array[case when scheduled_minutes=min_minutes then 'Fewest scheduled hours' end,case when is_primary then 'Primary job' end,'Available']::text[],null)))
      order by scheduled_minutes,is_primary desc,employee_id),'[]'::jsonb) into candidate_payload from ranked;
    if jsonb_array_length(candidate_payload)=0 then unfilled:=unfilled||jsonb_build_array(jsonb_build_object('shift_id',open_shift.id,'reason','No eligible employee'));
    else
      recommended:=(candidate_payload->0->>'employee_id')::uuid;
      proposals:=proposals||jsonb_build_array(jsonb_build_object('shift_id',open_shift.id,'location_name',open_shift.location_name,'job_name',open_shift.job_name,
        'scheduled_date',open_shift.scheduled_date,'time_basis',open_shift.time_basis,'time_snapshot',open_shift.time_snapshot,'time_timezone',open_shift.time_timezone,'start_time',to_char(open_shift.start_time,'HH24:MI'),'end_time',to_char(open_shift.end_time,'HH24:MI'),
        'recommended_employee_id',recommended,'candidates',candidate_payload));
    end if;
  end loop;
  unsigned:=jsonb_build_object('workspace_id',target_workspace_id,'session_id',target_session.id,'session_revision',target_session.revision,'proposals',proposals,'unfilled',unfilled);
  return unsigned||jsonb_build_object('status','review_ready','fingerprint',encode(extensions.digest(convert_to(unsigned::text,'UTF8'),'sha256'),'hex'));
end; $$;


ALTER FUNCTION "public"."preview_schedule_auto_fill_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule_default_hours_service"("actor" "uuid", "w" "uuid", "sid" "uuid", "command" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare session public.schedule_edit_sessions%rowtype; shift record; proposed jsonb; before_a jsonb; after_a jsonb;
 rows jsonb:='[]'; evidence jsonb:='[]'; row_value jsonb; peers jsonb; before_count integer; after_count integer;
 original_span tstzrange; proposed_span tstzrange; reason text; can_override boolean; fingerprint text;
 ids uuid[]; starts date; ends date; changed integer:=0; blocked integer:=0; edit_scope uuid[]; fmt text; overlap text;
begin
 if jsonb_typeof(command) is distinct from 'object' or jsonb_typeof(command->'shift_ids') is distinct from 'array'
  or jsonb_array_length(command->'shift_ids') not between 1 and 200 then raise exception 'Choose 1 to 200 shifts to review' using errcode='22023'; end if;
 select array_agg(value::uuid order by value::uuid) into ids from jsonb_array_elements_text(command->'shift_ids');
 if cardinality(ids)<>(select count(distinct x) from unnest(ids) x) then raise exception 'Choose each shift once' using errcode='22023'; end if;
 select * into session from public.schedule_edit_sessions where workspace_id=w and id=sid;
 if session.id is null or session.holder_user_id is distinct from actor then raise exception 'Edit session not found' using errcode='42501'; end if;
 if session.status <> 'active' then
  raise exception 'Schedule editing closed; reopen the review' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
 elsif session.expires_at <= now() then
  raise exception 'Schedule editing expired; reopen the review' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
 elsif session.revision is distinct from (command->>'expected_session_revision')::integer then
  raise exception 'Schedule editing changed; reopen the review' using errcode = 'PT409', hint = 'schedule.edit_session_stale'; end if;
 starts:=(command->>'starts_on')::date; ends:=(command->>'ends_on')::date;
 if starts is null or ends is null or starts<session.week_start or ends>session.week_start+6 or ends<starts then
  raise exception 'Choose dates within this schedule week' using errcode='22023'; end if;
 if (select count(*) from public.schedule_edit_session_shifts s where s.workspace_id=w and s.session_id=sid and s.id=any(ids)
  and s.scheduled_date between starts and ends and coalesce(s.pending_op_type,'')<>'delete')<>cardinality(ids) then
  raise exception 'Selected shifts changed or are outside these dates' using errcode = 'PT409', hint = 'schedule.default_hours_stale'; end if;
 perform app_private.authorize(actor, w, 'schedule.edit', target_locations => array(
  select distinct s.location_id from public.schedule_edit_session_shifts s where s.workspace_id=w and s.session_id=sid and s.id=any(ids)));
 edit_scope:=app_private.scope_set(actor, w, 'schedule.edit');
 for shift in select s.*,to_jsonb(s) payload,t.default_revision,t.default_start_time,t.default_end_time,t.archived_at type_archived,
  t.name type_name,l.name location_name,l.archived_at location_archived,j.archived_at job_archived,
  coalesce(nullif(concat_ws(' ',coalesce(nullif(e.preferred_name,''),e.first_name),e.last_name),''),'Open shift') employee_name
  from public.schedule_edit_session_shifts s
  join public.locations l on l.id=s.location_id and l.workspace_id=w
  join public.jobs j on j.id=s.job_id and j.workspace_id=w
  left join public.shift_types t on t.id=s.shift_type_id and t.workspace_id=w
  left join public.employee_profiles e on e.id=s.employee_id and e.workspace_id=w
  where s.workspace_id=w and s.session_id=sid and s.id=any(ids) order by s.scheduled_date,s.location_id,s.id loop
  reason:=null; proposed:=null; before_a:=null; after_a:=null; can_override:=false;
  original_span:=app_private.shift_time_range(shift.scheduled_date,shift.start_time,shift.end_time,shift.time_timezone);
  if shift.time_basis<>'type_default' then reason:='Only saved shift-type reference hours are included; explicit hours stay unchanged';
  elsif shift.type_archived is not null or shift.default_revision is null then reason:='This shift type is archived or unavailable';
  elsif shift.default_start_time is null or shift.default_end_time is null then reason:='This shift type has no current default hours';
  elsif lower(original_span)<=now() then reason:='This shift has already started';
  elsif shift.time_snapshot->>'default_revision'=shift.default_revision::text and shift.time_snapshot->>'shift_type_id'=shift.shift_type_id::text then reason:='Already uses the current defaults';
  end if;
  if reason is null then
   proposed:=public.normalize_schedule_time_source(w,shift.payload||jsonb_build_object('time_snapshot',null),shift.payload);
   proposed_span:=app_private.shift_time_range(shift.scheduled_date,(proposed->>'start_time')::time,(proposed->>'end_time')::time,proposed->>'time_timezone');
   if lower(proposed_span)<=now() then reason:='The proposed start time is already in the past'; proposed:=null; end if;
  end if;
  if proposed is not null then
   changed:=changed+1;
   can_override:=shift.location_id=any(edit_scope);
   if shift.employee_id is not null then
    before_a:=public.availability_impact_assessment(public.assess_weekly_shift_availability(w,shift.employee_id,shift.payload))||jsonb_build_object('can_override',can_override);
    
    after_a:=public.assess_weekly_shift_availability(w,shift.employee_id,proposed);
    after_a:=public.availability_impact_assessment(after_a)||jsonb_build_object('can_override',can_override,
     'warning_policy',after_a->'warning_policy','has_availability_conflict',after_a->'has_availability_conflict',
     'override_recorded',public.schedule_availability_override(w,proposed,after_a) is not null);
 
   end if;
   if shift.employee_id is not null and app_private.authz_reason(actor,w,'availability.note_read',target_person=>shift.employee_id) is not null then
    before_a:=jsonb_set(before_a,'{reasons}',(select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(before_a->'reasons') r where r->>'code'<>'note'));
    after_a:=jsonb_set(after_a,'{reasons}',(select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(after_a->'reasons') r where r->>'code'<>'note'));
   end if;
   if after_a->>'operation' in('blocked','verification_required') then reason:='Resolve shift hours or approved time off before applying these hours';
   
   elsif shift.location_archived is not null or shift.job_archived is not null then reason:='The location or job is archived';
   elsif shift.employee_id is not null and public.employee_has_hard_document_schedule_conflict_service(w,shift.employee_id,shift.scheduled_date) then reason:='Employee document requirements block this assignment';
   end if;
   if after_a->>'operation'='warning_requires_override' and reason is null then
    proposed:=proposed||jsonb_build_object('availability_assessment_fingerprint',public.assess_weekly_shift_availability(w,shift.employee_id,(proposed-'id'-'source_shift_id')||jsonb_build_object('_exclude_shift_id',shift.id,'session_id',sid))->>'fingerprint'); end if;
   if reason is not null then blocked:=blocked+1; end if;
  end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('shift_id',shift.id,'shift_revision',shift.revision,'scheduled_date',shift.scheduled_date,
   'location_id',shift.location_id,'location_name',shift.location_name,'shift_type_name',coalesce(shift.type_name,'Unnamed shift'),'employee_name',shift.employee_name,
   'before',shift.payload,'after',proposed,'before_assessment',before_a,'after_assessment',after_a,'reason',reason,'will_change',proposed is not null,'can_apply',proposed is not null and reason is null,
   'current_default_revision',shift.default_revision));
 end loop;
 -- Compare the complete proposed selection together, including overnight and
 -- cross-location commitments. Of another shift only its type and hours leave
 -- this helper, which the grid already shows as a ghost (FB-6.1 .5).
 select coalesce(jsonb_agg(payload order by source,id),'[]') into peers from (
  select 'edit' source,s.id,to_jsonb(s) payload from public.schedule_edit_session_shifts s
   where s.workspace_id=w and s.session_id=sid and coalesce(s.pending_op_type,'')<>'delete'
  union all
  select 'published',p.id,to_jsonb(p)||jsonb_build_object('id',coalesce(p.source_shift_id,p.id)) from public.schedule_published_shifts p
   join public.schedule_location_publications pub on pub.id=p.publication_id and pub.workspace_id=w and pub.status='current'
   where p.workspace_id=w and p.scheduled_date between starts-2 and ends+2 and p.employee_id is not null
    and not exists(select 1 from public.schedule_edit_session_shifts s where s.workspace_id=w and s.session_id=sid and s.id=coalesce(p.source_shift_id,p.id))
 ) candidates;
 fmt:=case when (select time_format from public.workspace_scheduling_settings where workspace_id=w)='24h' then 'HH24:MI' else 'FMHH12:MI AM' end;
 for row_value in select value from jsonb_array_elements(rows) loop
  before_count:=0; after_count:=0; overlap:=null;
  if row_value->'after'<>'null'::jsonb and row_value->'before'->>'employee_id' is not null then
   original_span:=app_private.shift_time_range((row_value->>'scheduled_date')::date,(row_value->'before'->>'start_time')::time,(row_value->'before'->>'end_time')::time,row_value->'before'->>'time_timezone');
   proposed_span:=app_private.shift_time_range((row_value->>'scheduled_date')::date,(row_value->'after'->>'start_time')::time,(row_value->'after'->>'end_time')::time,row_value->'after'->>'time_timezone');
   -- A peer in the selection is compared at its proposed hours.
   select count(*) filter(where spans.before_span&&original_span),count(*) filter(where spans.after_span&&proposed_span),
    (array_agg(coalesce(t.name,'shift')||' '||to_char((eff.p->>'start_time')::time,fmt)||'–'||to_char((eff.p->>'end_time')::time,fmt) order by lower(spans.after_span))
     filter(where spans.after_span&&proposed_span))[1]
    into before_count,after_count,overlap
   from jsonb_array_elements(peers) peer
   left join lateral(select value r from jsonb_array_elements(rows) where value->>'shift_id'=peer->>'id') replacement on true
   cross join lateral(select coalesce(nullif(replacement.r->'after','null'),peer) p) eff
   cross join lateral(select app_private.shift_time_range((peer->>'scheduled_date')::date,(peer->>'start_time')::time,(peer->>'end_time')::time,peer->>'time_timezone') before_span,
    app_private.shift_time_range((eff.p->>'scheduled_date')::date,(eff.p->>'start_time')::time,(eff.p->>'end_time')::time,eff.p->>'time_timezone') after_span) spans
   left join public.shift_types t on t.workspace_id=w and t.id=(eff.p->>'shift_type_id')::uuid
   where peer->>'employee_id'=row_value->'before'->>'employee_id' and peer->>'id'<>row_value->>'shift_id';
   if overlap is not null and (row_value->>'can_apply')::boolean then
    row_value:=row_value||jsonb_build_object('reason','Overlaps '||overlap,'can_apply',false); blocked:=blocked+1;
   elsif overlap is not null and row_value->'after_assessment'->>'operation'='blocked'
    and not exists(select 1 from jsonb_array_elements(row_value->'after_assessment'->'reasons') x where x->>'severity'='block' and x->>'code'<>'time_overlap') then
    -- The core already blocked it for this overlap alone: name the shift instead of the generic availability text.
    row_value:=row_value||jsonb_build_object('reason','Overlaps '||overlap);
   end if;
  end if;
  evidence:=evidence||jsonb_build_array(row_value||jsonb_build_object('before_overlap_count',before_count,'after_overlap_count',after_count));
 end loop;
 fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('workspace',w,'actor',actor,'session',sid,'revision',session.revision,'command',command-'fingerprint'-'idempotency_key'-'confirm_availability','rows',evidence,'peers',peers)::text,'UTF8'),'sha256'),'hex');
 return jsonb_build_object('session_id',sid,'session_revision',session.revision,'starts_on',starts,'ends_on',ends,'fingerprint',fingerprint,'changed_count',changed,'blocked_count',blocked,'shifts',evidence);
end $$;


ALTER FUNCTION "public"."preview_schedule_default_hours_service"("actor" "uuid", "w" "uuid", "sid" "uuid", "command" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule_export_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "source_type" "text", "source_draft_id" "uuid", "target_location_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare normalized uuid[]; source_revision integer; rows jsonb; locations jsonb; unsigned jsonb; workspace_name text;
begin
  if source_type not in ('published','draft') then raise exception 'invalid schedule export source' using errcode='22023'; end if;
  select array_agg(distinct id order by id) into normalized from unnest(target_location_ids) id;
  if coalesce(cardinality(normalized),0)=0 then raise exception 'schedule export location required' using errcode='22023'; end if;
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export', target_locations => normalized);
  if source_type='draft' then
    select revision into source_revision from public.schedule_drafts d where d.id=source_draft_id and d.workspace_id=target_workspace_id and d.week_start=target_week_start and d.archived_at is null;
    if source_revision is null then raise exception 'schedule export draft not found' using errcode='P0002'; end if;
  elsif source_draft_id is not null then raise exception 'published export cannot specify draft' using errcode='22023'; end if;
  select name into workspace_name from public.workspaces where id=target_workspace_id;
  select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'name',l.name) order by l.sort_order,l.id),'[]'::jsonb) into locations
  from public.locations l where l.workspace_id=target_workspace_id and l.id=any(normalized);
  if jsonb_array_length(locations)<>cardinality(normalized) then raise exception 'schedule export location not found' using errcode='P0002'; end if;
  if source_type='draft' then
    select coalesce(jsonb_agg(jsonb_build_object('shift_id',s.id,'scheduled_date',s.scheduled_date,'location_name',l.name,
      'employee_name',case when s.employee_id is null then null else coalesce(nullif(e.preferred_name,''),e.first_name||' '||e.last_name) end,'job_name',j.name,'shift_type_name',st.name,
      'label_names',to_jsonb(coalesce(s.label_names,'{}'::text[])),
      'time_basis',s.time_basis,'time_snapshot',s.time_snapshot,'time_timezone',s.time_timezone,'start_time',to_char(s.start_time,'HH24:MI'),'end_time',to_char(s.end_time,'HH24:MI'),'crosses_midnight',s.crosses_midnight,'note',s.note,
      'scheduled_minutes',greatest(0,(case when s.end_time<=s.start_time then 1440 else 0 end+extract(epoch from(s.end_time-s.start_time))/60)::integer-coalesce(s.unpaid_break_minutes,0)))
      order by s.scheduled_date,l.sort_order,s.start_time,s.id),'[]'::jsonb) into rows
    from public.schedule_draft_shifts s join public.locations l on l.id=s.location_id join public.jobs j on j.id=s.job_id
    left join public.employee_profiles e on e.id=s.employee_id left join public.shift_types st on st.id=s.shift_type_id
    where s.draft_id=source_draft_id and s.location_id=any(normalized);
  else
    select coalesce(jsonb_agg(jsonb_build_object('shift_id',s.id,'scheduled_date',s.scheduled_date,'location_name',l.name,
      'employee_name',case when s.employee_id is null then null else coalesce(nullif(e.preferred_name,''),e.first_name||' '||e.last_name) end,'job_name',j.name,'shift_type_name',st.name,
      'label_names',to_jsonb(coalesce(s.label_names,'{}'::text[])),
      'time_basis',s.time_basis,'time_snapshot',s.time_snapshot,'time_timezone',s.time_timezone,'start_time',to_char(s.start_time,'HH24:MI'),'end_time',to_char(s.end_time,'HH24:MI'),'crosses_midnight',s.crosses_midnight,'note',s.note,
      'scheduled_minutes',greatest(0,(case when s.end_time<=s.start_time then 1440 else 0 end+extract(epoch from(s.end_time-s.start_time))/60)::integer-coalesce(s.unpaid_break_minutes,0)))
      order by s.scheduled_date,l.sort_order,s.start_time,s.id),'[]'::jsonb) into rows
    from public.schedule_published_shifts s join public.schedule_location_publications p on p.id=s.publication_id and p.status='current' and p.week_start=target_week_start
    join public.locations l on l.id=s.location_id join public.jobs j on j.id=s.job_id left join public.employee_profiles e on e.id=s.employee_id left join public.shift_types st on st.id=s.shift_type_id
    where s.workspace_id=target_workspace_id and s.location_id=any(normalized);
  end if;
  unsigned:=jsonb_build_object('workspace_id',target_workspace_id,'workspace_name',workspace_name,'week_start',target_week_start,
    'source',case when source_type='draft' then jsonb_build_object('type','draft','draft_id',source_draft_id) else jsonb_build_object('type','published') end,
    'source_revision',source_revision,'locations',locations,'rows',rows,'summary',jsonb_build_object('shift_count',jsonb_array_length(rows),
      'employee_count',(select count(distinct x->>'employee_name') from jsonb_array_elements(rows) x where x->>'employee_name' is not null),
      'scheduled_minutes',(select coalesce(sum((x->>'scheduled_minutes')::integer),0) from jsonb_array_elements(rows) x)));
  return unsigned||jsonb_build_object('status','export_ready','fingerprint',encode(extensions.digest(convert_to(unsigned::text,'UTF8'),'sha256'),'hex'));
end; $$;


ALTER FUNCTION "public"."preview_schedule_export_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "source_type" "text", "source_draft_id" "uuid", "target_location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule_publication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_location_ids" "uuid"[], "target_department_ids" "uuid"[] DEFAULT NULL::"uuid"[], "include_no_department" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requested uuid;
  target_draft public.schedule_drafts%rowtype;
  normalized_locations uuid[];
  normalized_departments uuid[];
  effective_include_no_department boolean := coalesce(include_no_department, true);
  location_payload jsonb;
  finding_payload jsonb;
  unsigned_payload jsonb;
  preview_fingerprint text;
  hard_count integer;
  soft_count integer;
begin
  -- Nothing named is nowhere to publish; the core says why.
  if cardinality(coalesce(target_location_ids, '{}'::uuid[])) = 0 then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => '{}'::uuid[]);
  end if;
  foreach requested in array target_location_ids loop
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => array[requested]);
  end loop;

  select * into target_draft
  from public.schedule_drafts draft
  where draft.id = target_draft_id
    and draft.workspace_id = target_workspace_id
    and draft.archived_at is null;
  if target_draft.id is null then
    raise exception 'schedule draft not found' using errcode = 'P0002';
  end if;
  -- S-01: each place publishes up to its own line.
  if exists (select 1 from unnest(target_location_ids) place
             where target_draft.week_start < public.schedule_current_week_start_service(target_workspace_id, array[place])) then
    return app_private.schedule_publication_changes_since_start(public.weekly_schedule_publication_preflight(
      jsonb_build_object(
        'status', 'past_week_closed', 'workspace_id', target_workspace_id,
        'week_start', target_draft.week_start, 'draft_id', target_draft.id,
        'draft_revision', target_draft.revision, 'fingerprint', repeat('0', 64),
        'locations', '[]'::jsonb, 'findings', '[]'::jsonb
      ), actor_user_id, target_department_ids, include_no_department));
  end if;

  select array_agg(distinct location_id order by location_id)
  into normalized_locations
  from unnest(target_location_ids) location_id;
  -- A draft publishes only the locations it covers; anything else would be
  -- replaced with nothing.
  if not normalized_locations <@ target_draft.location_ids then
    raise exception 'publication location is not in this draft' using errcode = '22023';
  end if;

  if target_department_ids is not null then
    select coalesce(array_agg(distinct department.id order by department.id), '{}'::uuid[])
    into normalized_departments
    from public.departments department
    join unnest(target_department_ids) requested(id) on requested.id = department.id
    where department.workspace_id = target_workspace_id
      and department.archived_at is null;

    if cardinality(normalized_departments) = 0
      and not effective_include_no_department then
      raise exception 'invalid department publication scope' using errcode = '22023';
    end if;
  end if;

  with selected_locations as (
    select location.id, location.name
    from public.locations location
    where location.id = any(normalized_locations)
  ), active as (
    select publication.*
    from public.schedule_location_publications publication
    where publication.workspace_id = target_workspace_id
      and publication.week_start = target_draft.week_start
      and publication.location_id = any(normalized_locations)
      and publication.status = 'current'
  ), current_shift as (
    select shift.*
    from public.schedule_published_shifts shift
    join active publication on publication.id = shift.publication_id
    where public.schedule_shift_in_department_scope_service(
      shift.job_id, normalized_departments, effective_include_no_department
    )
  ), next_shift as (
    select shift.*
    from public.schedule_draft_shifts shift
    where shift.draft_id = target_draft.id
      and shift.location_id = any(normalized_locations)
      and public.schedule_shift_in_department_scope_service(
        shift.job_id, normalized_departments, effective_include_no_department
      )
  ), comparison as (
    select location.id as location_id, location.name as location_name,
      publication.id as active_publication_id,
      publication.version_number as active_version,
      (select count(*) from current_shift shift where shift.location_id = location.id)::integer as current_shift_count,
      (select count(*) from next_shift shift where shift.location_id = location.id)::integer as next_shift_count,
      (select count(*) from next_shift next_row where next_row.location_id = location.id and not exists (
        select 1 from current_shift current_row where current_row.location_id = location.id and current_row.source_shift_id = next_row.id
      ))::integer as added,
      (select count(*) from current_shift current_row where current_row.location_id = location.id and not exists (
        select 1 from next_shift next_row where next_row.location_id = location.id and next_row.id = current_row.source_shift_id
      ))::integer as removed,
      (select count(*) from next_shift next_row join current_shift current_row
        on current_row.location_id = next_row.location_id and current_row.source_shift_id = next_row.id
        where next_row.location_id = location.id and (
          current_row.employee_id is distinct from next_row.employee_id
          or current_row.job_id is distinct from next_row.job_id
          or current_row.shift_type_id is distinct from next_row.shift_type_id
          or current_row.scheduled_date is distinct from next_row.scheduled_date
          or current_row.start_time is distinct from next_row.start_time
          or current_row.end_time is distinct from next_row.end_time
          or current_row.time_basis is distinct from next_row.time_basis
          or current_row.time_snapshot is distinct from next_row.time_snapshot
          or current_row.time_timezone is distinct from next_row.time_timezone
          or current_row.note is distinct from next_row.note
        ))::integer as updated,
      (select count(*) from next_shift next_row join current_shift current_row
        on current_row.location_id = next_row.location_id and current_row.source_shift_id = next_row.id
        where next_row.location_id = location.id and not (
          current_row.employee_id is distinct from next_row.employee_id
          or current_row.job_id is distinct from next_row.job_id
          or current_row.shift_type_id is distinct from next_row.shift_type_id
          or current_row.scheduled_date is distinct from next_row.scheduled_date
          or current_row.start_time is distinct from next_row.start_time
          or current_row.end_time is distinct from next_row.end_time
          or current_row.time_basis is distinct from next_row.time_basis
          or current_row.time_snapshot is distinct from next_row.time_snapshot
          or current_row.time_timezone is distinct from next_row.time_timezone
          or current_row.note is distinct from next_row.note
        ))::integer as unchanged,
      -- The people the publish tells (BILDIRIM-U3): not the publisher, only who a notice reaches.
      app_private.schedule_people_told(target_workspace_id, actor_user_id, coalesce((
        select array_agg(distinct affected.employee_id order by affected.employee_id)
        from (
          select next_row.employee_id
          from next_shift next_row
          where next_row.location_id = location.id
            and next_row.employee_id is not null
            and not exists (
              select 1 from current_shift current_row
              where current_row.location_id = location.id
                and current_row.source_shift_id = next_row.id
            )
          union
          select next_row.employee_id
          from next_shift next_row
          join current_shift current_row
            on current_row.location_id = next_row.location_id
           and current_row.source_shift_id = next_row.id
          where next_row.location_id = location.id
            and next_row.employee_id is not null
            and (
              current_row.employee_id is distinct from next_row.employee_id
              or current_row.job_id is distinct from next_row.job_id
              or current_row.shift_type_id is distinct from next_row.shift_type_id
              or current_row.scheduled_date is distinct from next_row.scheduled_date
              or current_row.start_time is distinct from next_row.start_time
              or current_row.end_time is distinct from next_row.end_time
              or current_row.time_basis is distinct from next_row.time_basis
          or current_row.time_snapshot is distinct from next_row.time_snapshot
          or current_row.time_timezone is distinct from next_row.time_timezone
          or current_row.note is distinct from next_row.note
            )
          union
          -- Whose shift went to someone else or was opened is affected too (BILDIRIM-U3): the
          -- publish dialog counts the people the publish tells.
          select current_row.employee_id
          from next_shift next_row
          join current_shift current_row
            on current_row.location_id = next_row.location_id
           and current_row.source_shift_id = next_row.id
          where next_row.location_id = location.id
            and current_row.employee_id is not null
            and current_row.employee_id is distinct from next_row.employee_id
          union
          select current_row.employee_id
          from current_shift current_row
          where current_row.location_id = location.id
            and current_row.employee_id is not null
            and not exists (
              select 1 from next_shift next_row
              where next_row.location_id = location.id
                and next_row.id = current_row.source_shift_id
            )
        ) affected
      ), '{}'::uuid[])) as affected_employee_ids
    from selected_locations location
    left join active publication on publication.location_id = location.id
  )
  select jsonb_agg(to_jsonb(comparison) order by location_name, location_id)
  into location_payload from comparison;

  with next_shift as (
    select shift.*,
      coalesce(nullif(employee.preferred_name, ''), employee.first_name) || ' ' || employee.last_name as employee_name,
      location.name as location_name,
      tsrange(
        shift.scheduled_date::timestamp + shift.start_time,
        shift.scheduled_date::timestamp + shift.end_time
          + case when shift.end_time <= shift.start_time then interval '1 day' else interval '0' end,
        '[)'
      ) as occupied
    from public.schedule_draft_shifts shift
    join public.locations location on location.id = shift.location_id
    left join public.employee_profiles employee on employee.id = shift.employee_id
    where shift.draft_id = target_draft.id
      and shift.location_id = any(normalized_locations)
      and public.schedule_shift_in_department_scope_service(
        shift.job_id, normalized_departments, effective_include_no_department
      )
  ), raw_findings as (
    select
      'overlap'::text as code, case when first.time_basis='explicit' and second.time_basis='explicit' then 'hard' else 'soft' end::text as severity, (first.time_basis='type_default' or second.time_basis='type_default') as overrideable,
      first.location_id, first.employee_id, first.scheduled_date,
      array[first.id, second.id]::uuid[] as shift_ids,
      first.employee_name || case when first.time_basis='type_default' or second.time_basis='type_default' then ' has overlapping reference hours on ' else ' has overlapping shifts on ' end || first.scheduled_date::text || '.' as message
    from next_shift first
    join next_shift second on second.employee_id = first.employee_id and second.id > first.id
      and first.employee_id is not null and first.time_basis in ('explicit','type_default') and second.time_basis in ('explicit','type_default') and first.occupied && second.occupied
    union all
    select
      'closed_location', 'soft', true, shift.location_id, shift.employee_id,
      shift.scheduled_date, array[shift.id]::uuid[],
      shift.location_name || case hit.kind when 'closed' then ' is closed on ' else ' has short hours on ' end
        || shift.scheduled_date::text || '.'
    from next_shift shift
    cross join lateral (
      select closure.kind from public.schedule_closures closure
      where closure.location_id = shift.location_id
        and closure.closed_date = shift.scheduled_date
        and app_private.closure_covers(closure.kind, closure.opens, closure.closes, shift.start_time, shift.end_time)
      order by closure.kind = 'closed' desc limit 1
    ) hit
  ), findings as (
    select encode(extensions.digest(convert_to(
      code || '|' || coalesce(employee_id::text, '') || '|' || scheduled_date::text || '|' || array_to_string(shift_ids, ','),
      'UTF8'), 'sha256'), 'hex') as id, *
    from raw_findings
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id, 'code', code, 'severity', severity, 'overrideable', overrideable,
    'message', message, 'location_id', location_id, 'employee_id', employee_id,
    'scheduled_date', scheduled_date, 'shift_ids', to_jsonb(shift_ids)
  ) order by severity, code, scheduled_date, id), '[]'::jsonb),
  count(*) filter (where severity = 'hard')::integer,
  count(*) filter (where severity = 'soft')::integer
  into finding_payload, hard_count, soft_count
  from findings;

  unsigned_payload := jsonb_build_object(
    'workspace_id', target_workspace_id,
    'week_start', target_draft.week_start,
    'draft_id', target_draft.id,
    'draft_revision', target_draft.revision,
    'locations', coalesce(location_payload, '[]'::jsonb),
    'findings', finding_payload
  );
  preview_fingerprint := encode(extensions.digest(convert_to(unsigned_payload::text, 'UTF8'), 'sha256'), 'hex');
  return app_private.schedule_publication_changes_since_start(public.weekly_schedule_publication_preflight(
    unsigned_payload || jsonb_build_object(
      'status', case when hard_count > 0 then 'hard_blocked'
        when soft_count > 0 then 'override_required' else 'publish_ready' end,
      'fingerprint', preview_fingerprint
    ), actor_user_id, target_department_ids, include_no_department));
end;
$$;


ALTER FUNCTION "public"."preview_schedule_publication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_location_ids" "uuid"[], "target_department_ids" "uuid"[], "include_no_department" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule_template_apply_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "target_template_id" "uuid", "department_keys" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  template_scope uuid[];
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.templates',
    target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates'));
  template_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates');
  -- Checked here too: the count below never reaches it when the edit is empty.
  perform app_private.schedule_template_department_ids(target_workspace_id, department_keys);

  if not exists (
    select 1 from public.schedule_edit_sessions session
    where session.id = target_session_id and session.workspace_id = target_workspace_id
      and session.holder_user_id = actor_user_id
  ) then
    raise exception 'edit session not found' using errcode = 'P0002';
  end if;
  if not exists (
    select 1 from public.schedule_templates template
    where template.id = target_template_id and template.workspace_id = target_workspace_id
  ) then
    raise exception 'schedule template not found' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.schedule_template_shifts template_shift
    where template_shift.template_id = target_template_id
      and template_shift.location_id = any (public.live_location_ids(target_workspace_id, array(
        select distinct s.location_id from public.schedule_template_shifts s where s.template_id = target_template_id)))
      and not template_shift.location_id = any (template_scope)
  ) then
    raise exception 'schedule template references unavailable schedule definitions' using errcode = '23503';
  end if;

  return jsonb_build_object('removed_shift_count', (
    select count(*)::integer
    from app_private.schedule_template_replace_targets(target_workspace_id, target_session_id, target_template_id,
      department_keys)));
end;
$$;


ALTER FUNCTION "public"."preview_schedule_template_apply_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "target_template_id" "uuid", "department_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule_unpublication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requested uuid;
  normalized_locations uuid[];
  location_payload jsonb;
  unsigned_payload jsonb;
  reviewed jsonb;
  assignments jsonb;
begin
  if cardinality(coalesce(target_location_ids, '{}'::uuid[])) = 0 then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => '{}'::uuid[]);
  end if;
  foreach requested in array target_location_ids loop
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => array[requested]);
  end loop;

  select array_agg(distinct location_id order by location_id) into normalized_locations
  from unnest(target_location_ids) location_id;
  select coalesce(jsonb_agg(jsonb_build_object(
    'location_id', publication.location_id, 'location_name', location.name,
    'publication_id', publication.id, 'version', publication.version_number,
    'shift_count', (select count(*) from public.schedule_published_shifts shift where shift.publication_id = publication.id)
  ) order by location.name, location.id), '[]'::jsonb)
  into location_payload
  from public.schedule_location_publications publication
  join public.locations location on location.id = publication.location_id
  where publication.workspace_id = target_workspace_id
    and publication.week_start = target_week_start
    and publication.location_id = any(normalized_locations)
    and publication.status = 'current';
  if jsonb_array_length(location_payload) <> cardinality(normalized_locations) then
    raise exception 'current schedule publication not found' using errcode = 'P0002';
  end if;
  unsigned_payload := jsonb_build_object(
    'workspace_id', target_workspace_id, 'week_start', target_week_start,
    'locations', location_payload
  );
  reviewed := unsigned_payload || jsonb_build_object(
    'status', case when exists (select 1 from unnest(target_location_ids) place
      where target_week_start < public.schedule_current_week_start_service(target_workspace_id, array[place]))
      then 'past_week_closed' else 'unpublish_ready' end,
    'fingerprint', encode(extensions.digest(convert_to(unsigned_payload::text, 'UTF8'), 'sha256'), 'hex')
  );

  -- The fingerprint also covers the published assignments, so a change to
  -- them after the preview makes the unpublish stale.
  select coalesce(jsonb_agg(jsonb_build_array(
   s.id,s.source_shift_id,s.employee_id,s.location_id,s.job_id,s.shift_type_id,
   s.scheduled_date,s.start_time,s.end_time,s.unpaid_break_minutes,
   s.time_basis,s.time_timezone,s.time_snapshot) order by s.id),'[]'::jsonb)
  into assignments
  from public.schedule_published_shifts s
  join public.schedule_location_publications p on p.id=s.publication_id and p.workspace_id=s.workspace_id
  where p.workspace_id=target_workspace_id and p.week_start=target_week_start
   and p.location_id=any(target_location_ids) and p.status='current';
  return reviewed||jsonb_build_object('fingerprint',encode(extensions.digest(
   convert_to(jsonb_build_object('review',reviewed->>'fingerprint','assignments',assignments)::text,'UTF8'),'sha256'),'hex'));
end;
$$;


ALTER FUNCTION "public"."preview_schedule_unpublication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_approved_signature_retention_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.status = 'approved'
    and not (
      tg_op = 'UPDATE'
      and new.name is not distinct from old.name
      and new.retention_trigger is not distinct from old.retention_trigger
      and new.duration_days is not distinct from old.duration_days
      and new.jurisdiction_scope is not distinct from old.jurisdiction_scope
      and new.authority_reference is not distinct from old.authority_reference
      and new.status = 'draft'
      and new.approved_by is null
      and new.approved_at is null
    )
    and (
      tg_op = 'DELETE'
      or new.name is distinct from old.name
      or new.retention_trigger is distinct from old.retention_trigger
      or new.duration_days is distinct from old.duration_days
      or new.jurisdiction_scope is distinct from old.jurisdiction_scope
      or new.authority_reference is distinct from old.authority_reference
      or new.status is distinct from old.status
      or new.approved_by is distinct from old.approved_by
      or new.approved_at is distinct from old.approved_at
    ) then
    raise exception 'approved retention policies are immutable' using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."protect_approved_signature_retention_policy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_published_signature_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.status = 'published'
    and not (
      tg_op = 'UPDATE'
      and new.workspace_id is not distinct from old.workspace_id
      and new.template_id is not distinct from old.template_id
      and new.version_number is not distinct from old.version_number
      and new.title is not distinct from old.title
      and new.summary is not distinct from old.summary
      and new.execution_class is not distinct from old.execution_class
      and new.content_text is not distinct from old.content_text
      and new.content_digest is not distinct from old.content_digest
      and new.intent_statement is not distinct from old.intent_statement
      and new.locale is not distinct from old.locale
      and new.effective_date is not distinct from old.effective_date
      and new.required_at_onboarding is not distinct from old.required_at_onboarding
      and new.blocks_activation is not distinct from old.blocks_activation
      and new.retention_policy_id is not distinct from old.retention_policy_id
      and new.status = 'draft'
      and new.published_by is null
      and new.published_at is null
    ) then
    raise exception 'published acknowledgement versions are immutable' using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."protect_published_signature_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_schedule_draft_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_location_ids" "uuid"[], "target_department_ids" "uuid"[], "include_no_department" boolean, "expected_draft_revision" integer, "expected_fingerprint" "text", "override_decisions" "jsonb" DEFAULT '[]'::"jsonb", "open_shift_choice" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requested uuid;
  result jsonb;
  target_draft public.schedule_drafts%rowtype;
  preview jsonb;
  location_item jsonb;
  finding jsonb;
  decision jsonb;
  new_publication_id uuid;
  previous_publication_id uuid;
  publication_ids uuid[] := '{}'::uuid[];
  normalized_locations uuid[];
  normalized_departments uuid[];
  effective_include_no_department boolean := coalesce(include_no_department, true);
  total_shift_count integer := 0;
  published_at timestamptz := now();
  pairs jsonb := '[]'::jsonb;
  publish_event_id uuid;
  asked uuid[];
  source uuid;
  other record;
  offered jsonb;
  offer public.shift_exchange_cases%rowtype;
begin
  -- The open shifts the publish brings (Mert, 2026-10-20): offer, keep, or delete. Nothing named keeps them.
  if open_shift_choice is not null and open_shift_choice not in ('offer', 'keep', 'delete') then
    raise exception 'Choose offer, keep or delete for the open shifts' using errcode = '22023';
  end if;
  if cardinality(coalesce(target_location_ids, '{}'::uuid[])) = 0 then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => '{}'::uuid[]);
  end if;
  foreach requested in array target_location_ids loop
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => array[requested]);
  end loop;
  perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,921));

  perform public.availability_lock_workspace(target_workspace_id);
  select * into target_draft from public.schedule_drafts draft
  where draft.id = target_draft_id and draft.workspace_id = target_workspace_id
    and draft.archived_at is null for update;
  if target_draft.id is null then raise exception 'schedule draft not found' using errcode = 'P0002'; end if;
  if target_draft.revision <> expected_draft_revision then
    raise exception 'stale publication preview' using errcode = '40001';
  end if;
  select array_agg(distinct location_id order by location_id) into normalized_locations
  from unnest(target_location_ids) location_id;

  if target_department_ids is not null then
    select coalesce(array_agg(distinct department.id order by department.id), '{}'::uuid[])
    into normalized_departments
    from public.departments department
    join unnest(target_department_ids) requested(id) on requested.id = department.id
    where department.workspace_id = target_workspace_id
      and department.archived_at is null;

    if cardinality(normalized_departments) = 0
      and not effective_include_no_department then
      raise exception 'invalid department publication scope' using errcode = '22023';
    end if;
  end if;

  perform 1 from public.schedule_location_publications publication
  where publication.workspace_id = target_workspace_id
    and publication.week_start = target_draft.week_start
    and publication.location_id = any(normalized_locations) for update;

  preview := public.preview_schedule_publication_service(
    actor_user_id,
    target_workspace_id,
    target_draft_id,
    normalized_locations,
    normalized_departments,
    effective_include_no_department
  );
  if preview->>'status' = 'past_week_closed' then
    raise exception 'past schedule week is closed' using errcode = 'P0001', hint = 'schedule.past_week_closed';
  end if;
  if preview->>'fingerprint' <> expected_fingerprint then
    raise exception 'stale publication preview' using errcode = '40001';
  end if;
  if preview->>'status' = 'hard_blocked' then
    raise exception 'schedule has hard publication blockers' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(override_decisions, '[]'::jsonb)) <> 'array' then
    raise exception 'publication overrides must be an array' using errcode = '22023';
  end if;
  -- The one place that says which findings are recorded and with which
  -- sentence (BL-190); the publisher's id and the time go with each row.
  override_decisions:=public.weekly_publication_decisions(preview,override_decisions);
  asked := array(select (x ->> 'id')::uuid from jsonb_array_elements(coalesce(preview -> 'open_shifts', '[]'::jsonb)) x);
  if open_shift_choice = 'delete' and cardinality(asked) > 0 then
    -- Deleted open shifts leave the draft and an edit of this draft holding them, as a removal on the
    -- Schedule would. Another draft of the week keeps its own copy (drafts share shift ids).
    with gone as (
      delete from public.schedule_edit_session_shifts copy
      where copy.workspace_id = target_workspace_id and copy.id = any(asked) and copy.employee_id is null
        and copy.session_id in (select e.id from public.schedule_edit_sessions e where e.source_draft_id = target_draft.id)
        -- Only a copy still as the draft has it: a change made in an open edit stays that edit's.
        and exists (select 1 from public.schedule_draft_shifts d where d.draft_id = target_draft.id and d.id = copy.id
          and public.shift_exchange_edit_matches(to_jsonb(copy), to_jsonb(d)))
        and copy.pending_op_type is distinct from 'delete'
      returning copy.session_id)
    update public.schedule_edit_sessions set revision = revision + 1 where id in (select session_id from gone);
    delete from public.schedule_draft_shifts shift
    where shift.draft_id = target_draft.id and shift.id = any(asked) and shift.employee_id is null;
    update public.schedule_drafts set revision = revision + 1, updated_at = now()
    where id = target_draft.id returning * into target_draft;
    perform app_private.schedule_edit_undo_barrier();
  end if;
  perform set_config('newfork.schedule_publish_scope',jsonb_build_object('workspace_id',target_workspace_id,'draft_id',target_draft_id,
   '_publish_locations',(select jsonb_agg(x->'location_id') from jsonb_array_elements(preview->'locations') x),
   '_publish_departments',preview->'department_ids','_publish_no_department',coalesce((preview->>'include_no_department')::boolean,true))::text,true);
  for location_item in select value from jsonb_array_elements(preview->'locations')
  loop
    previous_publication_id := nullif(location_item->>'active_publication_id', '')::uuid;
    new_publication_id := gen_random_uuid();
    if previous_publication_id is not null then
      update public.schedule_location_publications
      set status = 'superseded'
      where id = previous_publication_id and status = 'current';
      if not found then raise exception 'stale publication preview' using errcode = '40001'; end if;
    end if;
    insert into public.schedule_location_publications (
      id, workspace_id, location_id, week_start, version_number, status,
      published_by, published_at, source_draft_id, source_draft_revision,
      content_fingerprint, department_ids, include_no_department
    ) values (
      new_publication_id, target_workspace_id, (location_item->>'location_id')::uuid,
      target_draft.week_start,
      coalesce((select max(version_number) + 1 from public.schedule_location_publications
        where location_id = (location_item->>'location_id')::uuid and week_start = target_draft.week_start), 1),
      'current', actor_user_id, published_at, target_draft.id, target_draft.revision,
      expected_fingerprint, normalized_departments, effective_include_no_department
    );
    for finding in select value from jsonb_array_elements(preview->'findings')
    loop
      if finding->>'severity' <> 'soft'
        or finding->>'location_id' <> location_item->>'location_id' then continue; end if;
      select value into decision from jsonb_array_elements(override_decisions)
      where value->>'finding_id' = finding->>'id' limit 1;
      if decision is null then continue; end if;
      insert into public.schedule_publication_overrides (
        workspace_id, publication_id, source_draft_id, source_draft_revision,
        finding_id, finding_code, employee_id, location_id, scheduled_date,
        source_shift_ids, reason, actor_user_id
      ) values (
        target_workspace_id, new_publication_id, target_draft.id, target_draft.revision,
        finding->>'id', finding->>'code', nullif(finding->>'employee_id', '')::uuid,
        (finding->>'location_id')::uuid, (finding->>'scheduled_date')::date,
        array(select jsonb_array_elements_text(finding->'shift_ids')::uuid),
        btrim(decision->>'reason'), actor_user_id
      );
    end loop;
    if previous_publication_id is not null then
      update public.schedule_location_publications
      set superseded_by = new_publication_id
      where id = previous_publication_id;

      insert into public.schedule_published_shifts (workspace_id, location_id, publication_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, source_shift_id, label_ids, label_names)
      select shift.workspace_id, shift.location_id, new_publication_id, shift.employee_id, shift.job_id, shift.shift_type_id, shift.scheduled_date, shift.start_time, shift.end_time, shift.time_basis, shift.time_snapshot, shift.time_timezone, shift.unpaid_break_minutes, shift.hide_time_on_badge, shift.note, shift.source_shift_id, shift.label_ids, shift.label_names from public.schedule_published_shifts shift
      where shift.publication_id = previous_publication_id
        and not public.schedule_shift_in_department_scope_service(
          shift.job_id, normalized_departments, effective_include_no_department
        );
    end if;

    insert into public.schedule_published_shifts (workspace_id, location_id, publication_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, source_shift_id, label_ids, label_names)
    select shift.workspace_id, shift.location_id, new_publication_id, shift.employee_id, shift.job_id, shift.shift_type_id, shift.scheduled_date, shift.start_time, shift.end_time, shift.time_basis, shift.time_snapshot, shift.time_timezone, shift.unpaid_break_minutes, shift.hide_time_on_badge, shift.note, shift.id, shift.label_ids, shift.label_names from public.schedule_draft_shifts shift
    where shift.draft_id = target_draft.id
      and shift.location_id = (location_item->>'location_id')::uuid
      and public.schedule_shift_in_department_scope_service(
        shift.job_id, normalized_departments, effective_include_no_department
      );
    publication_ids := array_append(publication_ids, new_publication_id);
    pairs := pairs || jsonb_build_array(jsonb_build_object('previous', previous_publication_id, 'current', new_publication_id));

  end loop;

  -- What the publish asked about goes as the publisher chose; a request on it that the change
  -- ended closes as Shift Hub would close it.
  foreach source in array asked loop
    for other in select x.id, public.shift_exchange_live_status(target_workspace_id, x.id) live_status
      from public.shift_exchange_cases x where x.workspace_id = target_workspace_id and x.status = 'open' and x.offered_source_id = source
    loop
      if other.live_status <> 'open' then
        update public.shift_exchange_cases set status = other.live_status, revision = revision + 1, updated_at = now() where id = other.id;
        update public.shift_exchange_applications set status = other.live_status, updated_at = now()
        where case_id = other.id and status in ('invited', 'pending_manager');
        delete from public.shift_exchange_votes where case_id = other.id;
        perform public.shift_exchange_emit(actor_user_id, target_workspace_id, other.id, null, other.live_status,
          'This offer ended because the shift changed or started. Review the current schedule before making a new request.');
      -- Without a choice (an older screen) an offer that still holds is left as it is.
      elsif open_shift_choice in ('keep', 'delete') then
        update public.shift_exchange_cases set status = 'cancelled', revision = revision + 1, updated_at = now() where id = other.id;
        update public.shift_exchange_applications set status = 'closed_case_cancelled', updated_at = now()
        where case_id = other.id and status in ('invited', 'pending_manager');
        delete from public.shift_exchange_votes where case_id = other.id;
        perform public.shift_exchange_emit(actor_user_id, target_workspace_id, other.id, null, 'case_closed',
          'A manager closed this request. The owner keeps this shift.');
      end if;
    end loop;
    if open_shift_choice = 'offer' and not exists (select 1 from public.shift_exchange_cases x
      where x.workspace_id = target_workspace_id and x.status = 'open' and x.offered_source_id = source) then
      offered := public.shift_exchange_shift(target_workspace_id, source);
      if offered is not null and offered ->> 'employee_id' is null
        and app_private.shift_exchange_deadline(offered, null) > clock_timestamp() then
        insert into public.shift_exchange_cases (workspace_id, kind, audience, offered_source_id, owner_id, offered_snapshot,
          consent_fingerprint, expires_at, created_by, open_shift_publication_id)
        values (target_workspace_id, 'cover', 'eligible_pool', source, null, offered,
          public.shift_exchange_fingerprint(target_workspace_id, offered, null), app_private.shift_exchange_deadline(offered, null),
          actor_user_id, (select p.publication_id from public.schedule_published_shifts p where p.id = (offered ->> 'id')::uuid))
        returning * into offer;
        -- Its history starts here; nobody is told (the pool waits in Shift Hub).
        insert into public.shift_exchange_events (workspace_id, case_id, application_id, actor_user_id, action, message, private_note)
        values (target_workspace_id, offer.id, null, actor_user_id, 'cover_opened',
          'Offered to eligible employees when the schedule was published.', '');
        perform realtime.send(jsonb_build_object('workspace_id', target_workspace_id, 'case_id', offer.id, 'revision', offer.revision),
          'changed', 'shift-exchanges:' || target_workspace_id::text, true);
      end if;
    end if;
  end loop;

  select count(*)::integer into total_shift_count
  from public.schedule_published_shifts shift where shift.publication_id = any(publication_ids);
  insert into public.schedule_publication_events (
    workspace_id, week_start, action, actor_user_id, location_ids,
    source_draft_id, source_draft_revision, publication_ids,
    preflight_fingerprint, diff_summary
  ) values (
    target_workspace_id, target_draft.week_start, 'published', actor_user_id,
    normalized_locations, target_draft.id, target_draft.revision, publication_ids,
    expected_fingerprint,
    jsonb_build_object(
      'locations', preview->'locations',
      'department_ids', to_jsonb(normalized_departments),
      'include_no_department', effective_include_no_department
    )
  ) returning id into publish_event_id;
  -- Whose shifts changed hears it once (S-95; schedule_tell_published).
  perform app_private.schedule_tell_published(target_workspace_id, actor_user_id, publish_event_id,
    target_draft.week_start, pairs, array(select distinct x::uuid from jsonb_array_elements(preview -> 'locations') l,
      jsonb_array_elements_text(l -> 'affected_employee_ids') x));
  result := jsonb_build_object(
    'status', 'published', 'workspace_id', target_workspace_id,
    'week_start', target_draft.week_start, 'draft_id', target_draft.id,
    'draft_revision', target_draft.revision, 'location_ids', to_jsonb(normalized_locations),
    'publication_ids', to_jsonb(publication_ids), 'published_shift_count', total_shift_count,
    'published_at', published_at
  );

  -- Nobody missing a required document goes out on the published week.
  if public.schedule_draft_has_hard_document_conflicts_service(
      actor_user_id,
      target_workspace_id,
      target_draft_id,
      (result->>'week_start')::date,
      target_location_ids,
      target_department_ids,
      include_no_department
    ) then
    raise exception 'schedule has hard document blockers' using errcode = '23514';
  end if;

  return result;
exception when serialization_failure then raise exception '%',SQLERRM using errcode='PT409', hint='schedule.publication_changed';
end;
$$;


ALTER FUNCTION "public"."publish_schedule_draft_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_location_ids" "uuid"[], "target_department_ids" "uuid"[], "include_no_department" boolean, "expected_draft_revision" integer, "expected_fingerprint" "text", "override_decisions" "jsonb", "open_shift_choice" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_signature_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  draft_record public.signature_template_versions%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  select version.* into draft_record
  from public.signature_template_versions version
  join public.signature_templates template on template.id = version.template_id
  where version.workspace_id = target_workspace_id
    and version.template_id = target_template_id
    and version.status = 'draft'
    and template.archived_at is null
  for update of version;
  if draft_record.id is null then
    raise exception 'publishable acknowledgement draft not found' using errcode = 'P0002';
  end if;
  if draft_record.execution_class <> 'acknowledgement' then
    raise exception 'only acknowledgement templates can be published' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.signature_retention_policies policy
    where policy.id = draft_record.retention_policy_id
      and policy.workspace_id = target_workspace_id
      and policy.status = 'approved'
      and policy.archived_at is null
  ) then
    raise exception 'approved active retention policy required for publication' using errcode = '22023';
  end if;

  update public.signature_template_versions
  set status = 'published', published_by = actor_id, published_at = now(), updated_at = now()
  where id = draft_record.id;
  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id, actor_id, 'signature_template.published',
    'signature_template', target_template_id::text,
    jsonb_build_object('version_id', draft_record.id, 'version_number', draft_record.version_number,
      'content_digest', draft_record.content_digest)
  );
end;
$$;


ALTER FUNCTION "public"."publish_signature_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_owner_onboarding_invitation_intent_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "employee_email" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  onboarding_status public.onboarding_status;
  normalized_email text := lower(btrim(employee_email));
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.setup');

  select onboarding.status
  into onboarding_status
  from public.workspace_onboarding onboarding
  where onboarding.workspace_id = target_workspace_id;

  if onboarding_status is null then
    raise exception 'workspace onboarding was not found' using errcode = 'P0002';
  end if;
  if onboarding_status = 'complete'::public.onboarding_status then
    raise exception 'completed owner onboarding cannot queue invitations' using errcode = '22023';
  end if;
  if normalized_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'valid invitation email required' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from public.employee_profiles employee
    where employee.workspace_id = target_workspace_id
      and employee.id = target_employee_id
      and employee.archived_at is null
      and employee.user_id is null
  ) then
    raise exception 'invitable employee not found' using errcode = 'P0002';
  end if;

  insert into public.owner_onboarding_invitation_intents (
    workspace_id,
    employee_id,
    email,
    created_by,
    updated_at,
    dispatched_at,
    dispatch_error
  ) values (
    target_workspace_id,
    target_employee_id,
    normalized_email,
    actor_user_id,
    now(),
    null,
    null
  )
  on conflict (workspace_id, employee_id)
  do update set
    email = excluded.email,
    updated_at = now(),
    dispatched_at = null,
    dispatch_error = null;
end;
$_$;


ALTER FUNCTION "public"."queue_owner_onboarding_invitation_intent_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "employee_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."raise_notification_alerts_service"("target_alerts" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  added integer;
begin
  if target_alerts is null or jsonb_typeof(target_alerts) <> 'array' or jsonb_array_length(target_alerts) > 50 then
    raise exception 'alerts are a list of at most 50' using errcode = '22023', hint = 'notifications.alerts';
  end if;
  insert into app_private.notification_alerts (kind, channel, period)
  select x ->> 'kind', x ->> 'channel', x ->> 'period' from jsonb_array_elements(target_alerts) x
  on conflict do nothing;
  get diagnostics added = row_count;
  delete from app_private.notification_alerts a where a.raised_at < now() - interval '90 days';
  return added;
end;
$$;


ALTER FUNCTION "public"."raise_notification_alerts_service"("target_alerts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_employee_references_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reach uuid[] := app_private.scope_set(actor_user_id, target_workspace_id, 'employee.references.read');
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.references.read',
    target_locations => reach);
  return jsonb_build_object(
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', location.id, 'name', location.name,
        'archived_at', location.archived_at, 'timezone', location.timezone
      ) order by location.sort_order, location.name, location.id)
      from public.locations location
      where location.workspace_id = target_workspace_id and location.deleted_at is null
        and location.id = any (reach)
    ), '[]'::jsonb),
    -- Listed as the jobs are: the archived one included, so an archived job
    -- still finds its department; the deleted one not.
    'departments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', department.id, 'name', department.name,
        'archived_at', department.archived_at, 'system_key', department.system_key
      ) order by lower(department.name), department.id)
      from public.departments department
      where department.workspace_id = target_workspace_id and department.deleted_at is null
    ), '[]'::jsonb),
    'jobs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', job.id, 'name', job.name, 'archived_at', job.archived_at,
        'department_id', job.department_id, 'system_key', job.system_key
      ) order by lower(job.name), job.id)
      from public.jobs job
      where job.workspace_id = target_workspace_id and job.deleted_at is null
    ), '[]'::jsonb),
    'invite_roles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', role.id, 'name', role.name,
        'system_key', role.system_key, 'access_class', role.access_class
      ) order by role.sort_order, role.name, role.id)
      from public.workspace_roles role
      where role.workspace_id = target_workspace_id
        and app_private.can_invite_with_role(actor_user_id, target_workspace_id, role.id)
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."read_employee_references_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_job_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid", "search_text" "text" DEFAULT ''::"text", "location_filter" "uuid" DEFAULT NULL::"uuid", "assignment_filter" "text" DEFAULT 'all'::"text", "page_number" integer DEFAULT 0, "targets_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.authorize_employee_list(actor_user_id, target_workspace_id);
  if not exists(select 1 from public.jobs where id=target_job_id and workspace_id=target_workspace_id and deleted_at is null) then
    raise exception 'Job not found' using errcode='P0002'; end if;
  if assignment_filter not in ('all','assigned','unassigned') or page_number<0 then
    raise exception 'Valid filters required' using errcode='22023'; end if;
  with candidates as materialized (
    select * from app_private.job_assignment_candidates(actor_user_id,target_workspace_id,target_job_id)
  ), filtered as materialized (
    select * from candidates c
    where (coalesce(btrim(search_text),'')='' or strpos(lower(c.display_name||' '||c.employee_code),lower(btrim(search_text)))>0)
      and (location_filter is null or location_filter=any(c.location_ids))
      and (assignment_filter='all' or c.assigned=(assignment_filter='assigned'))
  ), paged as (
    select * from filtered where not targets_only or can_manage
    order by lower(display_name),employee_id
    limit case when targets_only then null else 50 end
    offset case when targets_only then 0 else page_number*50 end
  )
  select case when targets_only then
    coalesce((select jsonb_agg(jsonb_build_object('employee_id',employee_id,'assigned',assigned,'revision',revision)
      order by lower(display_name),employee_id) from paged),'[]'::jsonb)
  else jsonb_build_object(
    'employees',coalesce((select jsonb_agg(to_jsonb(p)-'location_ids' order by lower(display_name),employee_id) from paged p),'[]'::jsonb),
    'total',(select count(*) from filtered),
    'manageable_total',(select count(*) from filtered where can_manage),
    'assigned_count',(select count(*) from candidates where assigned),
    'locations',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'name',l.name) order by lower(l.name),l.id)
      from public.locations l where l.workspace_id=target_workspace_id and l.archived_at is null
      and exists(select 1 from candidates c where l.id=any(c.location_ids))),'[]'::jsonb)
  ) end into result;
  return result;
end; $$;


ALTER FUNCTION "public"."read_job_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid", "search_text" "text", "location_filter" "uuid", "assignment_filter" "text", "page_number" integer, "targets_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_new_job_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "search_text" "text" DEFAULT ''::"text", "location_filter" "uuid" DEFAULT NULL::"uuid", "assignment_filter" "text" DEFAULT 'all'::"text", "page_number" integer DEFAULT 0, "targets_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  perform app_private.authorize_employee_list(actor_user_id, target_workspace_id);
  if assignment_filter not in ('all', 'assigned', 'unassigned') or page_number < 0 then
    raise exception 'Valid filters required' using errcode = '22023';
  end if;

  with candidates as materialized (
    select * from app_private.job_assignment_candidates(actor_user_id, target_workspace_id, null::uuid)
  ), filtered as materialized (
    select * from candidates c
    where (coalesce(btrim(search_text), '') = ''
      or strpos(lower(c.display_name || ' ' || c.employee_code), lower(btrim(search_text))) > 0)
      and (location_filter is null or location_filter = any(c.location_ids))
      and (assignment_filter = 'all' or c.assigned = (assignment_filter = 'assigned'))
  ), paged as (
    select * from filtered where not targets_only or can_manage
    order by lower(display_name), employee_id
    limit case when targets_only then null else 50 end
    offset case when targets_only then 0 else page_number * 50 end
  )
  select case when targets_only then
    coalesce((select jsonb_agg(jsonb_build_object(
      'employee_id', employee_id, 'assigned', assigned, 'revision', revision
    ) order by lower(display_name), employee_id) from paged), '[]'::jsonb)
  else jsonb_build_object(
    'employees', coalesce((select jsonb_agg(to_jsonb(p) - 'location_ids' order by lower(display_name), employee_id) from paged p), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'manageable_total', (select count(*) from filtered where can_manage),
    'assigned_count', 0,
    'locations', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name) order by lower(l.name), l.id)
      from public.locations l where l.workspace_id = target_workspace_id and l.archived_at is null
      and exists(select 1 from candidates c where l.id = any(c.location_ids))), '[]'::jsonb)
  ) end into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."read_new_job_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "search_text" "text", "location_filter" "uuid", "assignment_filter" "text", "page_number" integer, "targets_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_role_workspace_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.roles.read');
  return jsonb_build_object(
    'permissions', (select jsonb_agg(p order by p.sort_order) from public.permissions p),
    'roles', coalesce((
      select jsonb_agg(to_jsonb(r) || jsonb_build_object(
        'permission_keys', coalesce((select jsonb_agg(g.permission_key order by g.permission_key)
          from public.workspace_role_permissions g where g.role_id = r.id), '[]'::jsonb),
        'member_count', (select count(*) from public.workspace_memberships m where r.id in (m.role_id, m.employee_role_id) and m.status = 'active'),
        'pending_invite_count', (select count(*) from public.employee_invitations i
          where r.id in (i.employee_role_id, i.management_role_id) and i.status = 'pending' and i.expires_at > now()),
        'blocking_member_count', (select count(*) from public.workspace_memberships m where r.id in (m.role_id, m.employee_role_id))
          + (select count(*) from public.employee_access_snapshots snap where snap.role_id = r.id),
        'blocking_invite_count', (select count(*) from public.employee_invitations i
          where r.id in (i.employee_role_id, i.management_role_id)),
        'editable', app_private.can_edit_role(actor_user_id, target_workspace_id, r.id),
        'deletable', r.system_key is null and app_private.can_edit_role(actor_user_id, target_workspace_id, r.id)
          and not exists (select 1 from public.workspace_memberships m where r.id in (m.role_id, m.employee_role_id))
          and not exists (select 1 from public.employee_invitations i where r.id in (i.employee_role_id, i.management_role_id))
          and not exists (select 1 from public.employee_access_snapshots snap where snap.role_id = r.id)
      ) order by r.sort_order, r.name)
      from public.workspace_roles r
      where r.workspace_id = target_workspace_id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."read_role_workspace_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_settings_jobs_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
