CREATE OR REPLACE FUNCTION "public"."record_account_security_event_service"("actor_user_id" "uuid", "target_event" "text", "target_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  audit_id uuid;
  said jsonb := coalesce(target_metadata, '{}'::jsonb);
begin
 if target_event is null or target_event not in ('account.email_change_requested','account.password_changed','account.sessions_revoked') then
  raise exception 'unsupported account security event' using errcode='22023';
 end if;
 if actor_user_id is null or not exists(select 1 from auth.users u where u.id=actor_user_id and u.deleted_at is null) then
  raise exception 'account session required' using errcode='42501', hint='authz.not_active';
 end if;
 -- Only what each event can say, as true or false.
 if jsonb_typeof(said) <> 'object' or exists (
   select 1 from jsonb_each(said) x
   where x.key <> case target_event when 'account.password_changed' then 'others_signed_out'
                                    when 'account.sessions_revoked' then 'with_password_change' else '' end
      or jsonb_typeof(x.value) <> 'boolean'
 ) then
  raise exception 'unsupported account security event details' using errcode='22023';
 end if;
 audit_id := app_private.record_security_audit_event_service(actor_user_id,null,target_event,'account.security','auth_user',actor_user_id::text,said);
 perform app_private.notify_account_security(actor_user_id, target_event, audit_id);
 return audit_id;
end; $$;


ALTER FUNCTION "public"."record_account_security_event_service"("actor_user_id" "uuid", "target_event" "text", "target_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_schedule_export_event_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_surface" "text", "target_format" "text", "target_params" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  created public.schedule_export_events%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export', target_locations => case
    when jsonb_typeof(target_params->'location_ids') = 'array'
      then array(select jsonb_array_elements_text(target_params->'location_ids')::uuid)
    else '{}'::uuid[]
  end);

  insert into public.schedule_export_events(
    workspace_id,
    actor_user_id,
    surface,
    format,
    params
  )
  values (
    target_workspace_id,
    actor_user_id,
    btrim(target_surface),
    btrim(target_format),
    coalesce(target_params, '{}'::jsonb)
  )
  returning * into created;

  return public.schedule_export_event_json(created);
end;
$$;


ALTER FUNCTION "public"."record_schedule_export_event_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_surface" "text", "target_format" "text", "target_params" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_schedule_export_schedule_failure_service"("target_workspace_id" "uuid", "target_schedule_id" "uuid", "target_error" "text", "auto_disable_after" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  failures integer;
  updated public.scheduled_schedule_exports%rowtype;
  was_enabled boolean;
  owner_may boolean;
  places uuid[];
begin
  select case
           when s.consecutive_failures > 0 and s.last_failed_at > now() - interval '20 hours'
             then s.consecutive_failures
           else s.consecutive_failures + 1
         end, s.enabled
    into failures, was_enabled
    from public.scheduled_schedule_exports s
   where s.id = target_schedule_id
     and s.workspace_id = target_workspace_id
   for update;

  if not found then
    raise exception 'scheduled export not found' using errcode='P0002';
  end if;

  update public.scheduled_schedule_exports
     set consecutive_failures = failures,
         last_failed_at = now(),
         last_error = left(coalesce(nullif(btrim(target_error), ''), 'Scheduled export failed'), 500),
         enabled = case
           when failures >= auto_disable_after then false
           else enabled
         end,
         auto_disabled_at = case
           when failures >= auto_disable_after then now()
           else auto_disabled_at
         end,
         updated_at = now()
   where id = target_schedule_id
     and workspace_id = target_workspace_id
   returning * into updated;

  -- It stopped just now: the person who set it up hears it, once, while the core says they still may
  -- export there; otherwise whoever may export there now, so a stopped email is never silent.
  if was_enabled and not updated.enabled then
    -- Its live locations, as the cron and the list read them; none left is '{}', the core's
    -- "no place": who may export in the workspace.
    places := public.live_location_ids(target_workspace_id, updated.location_ids);
    owner_may := app_private.authz_reason(updated.created_by, target_workspace_id, 'schedule.export', places) is null;
    perform app_private.notify('schedule.export_email_stopped', target_workspace_id,
      case when owner_may then array[updated.created_by]
           else app_private.notify_holders(target_workspace_id, 'schedule.export', places) end,
      'export_stop:' || updated.id::text || ':' || updated.auto_disabled_at::text,
      case when owner_may then 'Your scheduled schedule email stopped' else 'A scheduled schedule email stopped' end,
      format('"%s" failed %s times in a row, so it was turned off. Check its recipients and turn it back on.',
        updated.name, failures),
      '/app/schedule', null, 'scheduled_schedule_export', updated.id,
      jsonb_build_object('schedule_id', updated.id, 'failures', failures));
  end if;

  return public.schedule_export_schedule_json(
    updated,
    (select p.name from public.schedule_export_presets p where p.id = updated.preset_id)
  );
end;
$$;


ALTER FUNCTION "public"."record_schedule_export_schedule_failure_service"("target_workspace_id" "uuid", "target_schedule_id" "uuid", "target_error" "text", "auto_disable_after" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_schedule_export_schedule_success_service"("target_workspace_id" "uuid", "target_schedule_id" "uuid", "target_sent_at" timestamp with time zone, "target_format" "text", "target_params" "jsonb", "target_undelivered" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  updated public.scheduled_schedule_exports%rowtype;
begin
  update public.scheduled_schedule_exports
     set last_sent_at = target_sent_at,
         consecutive_failures = 0,
         -- Reached some, not all: the week says who missed it (KK-166).
         last_error = left(nullif(btrim(target_undelivered), ''), 500),
         auto_disabled_at = null,
         updated_at = now()
   where id = target_schedule_id
     and workspace_id = target_workspace_id
   returning * into updated;

  if not found then
    raise exception 'scheduled export not found' using errcode='P0002';
  end if;

  insert into public.schedule_export_events(
    workspace_id,
    actor_user_id,
    surface,
    format,
    params
  )
  values (
    target_workspace_id,
    updated.created_by,
    'scheduled_email',
    btrim(target_format),
    coalesce(target_params, '{}'::jsonb)
  );

  return public.schedule_export_schedule_json(
    updated,
    (select p.name from public.schedule_export_presets p where p.id = updated.preset_id)
  );
end;
$$;


