CREATE OR REPLACE FUNCTION "public"."request_account_deletion_v2_service"("actor_user_id" "uuid", "recovery_token_digest" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_email text;
  blockers jsonb;
  existing_request public.account_deletion_requests%rowtype;
  created_request public.account_deletion_requests%rowtype;
  dropped public.employee_invitations%rowtype;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;
  if recovery_token_digest is null
    or recovery_token_digest !~ '^[a-f0-9]{64}$' then
    raise exception 'valid recovery token digest required' using errcode = '22023';
  end if;

  select lower(btrim(auth_user.email)) into actor_email
  from auth.users auth_user
  where auth_user.id = actor_user_id;
  if actor_email is null then
    raise exception 'account not found' using errcode = 'P0002';
  end if;

  blockers := public.get_account_deletion_blockers_service(actor_user_id);
  if jsonb_array_length(blockers) > 0 then
    raise exception 'account deletion blocked: %', blockers::text
      using errcode = '23514';
  end if;

  select * into existing_request
  from public.account_deletion_requests request
  where request.user_id = actor_user_id
    and request.status = 'pending'
  order by request.requested_at desc
  limit 1
  for update;

  if existing_request.id is not null then
    update public.account_deletion_requests
    set recovery_token_digest = request_account_deletion_v2_service.recovery_token_digest,
        recovery_token_rotated_at = now(),
        updated_at = now()
    where id = existing_request.id
    returning * into existing_request;

    return jsonb_build_object(
      'status', existing_request.status,
      'request_id', existing_request.id,
      'email', actor_email,
      'restore_until', existing_request.restore_until
    );
  end if;

  -- Each invitation it drops tells whoever sent it, never why (the account is the invitee's own).
  for dropped in
    update public.employee_invitations invitation
    set status = 'revoked'::public.employee_invitation_status,
        revoked_at = now(),
        updated_at = now()
    where invitation.email = actor_email
      and invitation.status = 'pending'::public.employee_invitation_status
    returning invitation.*
  loop
    perform app_private.people_tell_invitation(dropped, 'invitation_cancelled', actor_user_id);
  end loop;

  insert into public.account_deletion_requests (
    user_id, typed_email, acknowledged, recovery_token_digest,
    recovery_token_rotated_at
  ) values (
    actor_user_id, actor_email, true, recovery_token_digest, now()
  )
  returning * into created_request;

  perform app_private.record_security_audit_event_service(
    actor_user_id, null, 'account.deletion_requested', 'account.security',
    'account_deletion_request', created_request.id::text,
    jsonb_build_object('restore_until', created_request.restore_until)
  );

  return jsonb_build_object(
    'status', created_request.status,
    'request_id', created_request.id,
    'email', actor_email,
    'restore_until', created_request.restore_until
  );
end;
$_$;


ALTER FUNCTION "public"."request_account_deletion_v2_service"("actor_user_id" "uuid", "recovery_token_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_employee_preferred_name_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "preferred_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  employee_row public.employee_profiles%rowtype;
  approval text;
  cleaned text := btrim(coalesce(preferred_name, ''));
  deciders uuid[];
  replaced uuid[];
  asked uuid;
begin
  -- Only on one's own record; somebody else's and an unknown one get the same
  -- answer (authz.out_of_scope).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.request_preferred_name',
    target_person => target_employee_id);
  select * into employee_row
  from public.employee_profiles
  where id = target_employee_id
    and workspace_id = target_workspace_id
    and archived_at is null;

  if employee_row.id is null then
    raise exception 'employee not found'
      using errcode = 'P0002', hint = 'employee.not_found';
  end if;
  if char_length(cleaned) > 80 then
    raise exception 'a preferred name is at most 80 characters'
      using errcode = '22023', hint = 'employee.preferred_name.too_long';
  end if;

  -- Clearing it is always the person's own business; there is nothing for a
  -- manager to answer about a name that will not be shown.
  if cleaned = '' then
    with gone as (
      update public.employee_preferred_name_requests
      set status = 'rejected', decided_by = actor_user_id, decided_at = now()
      where employee_id = target_employee_id and status = 'pending'
      returning id
    )
    select coalesce(array_agg(gone.id), '{}') into replaced from gone;
    -- The earlier ask's cards close (preferred_name_tell_asked).
    perform app_private.preferred_name_tell_asked(target_workspace_id, target_employee_id, replaced, null, null, '{}', actor_user_id);
    update public.employee_profiles set preferred_name = '', updated_at = now()
    where id = target_employee_id;
    return 'cleared';
  end if;

  -- S-131: it waits for an answer; no setting lets it through.
  approval := 'manager';

  -- Whoever the core lets decide this person's preferred name.
  -- ponytail: one core call per active member; a workspace is tens of people.
  select coalesce(array_agg(member.user_id order by member.user_id), '{}')
  into deciders
  from public.workspace_memberships member
  where member.workspace_id = target_workspace_id
    and member.status = 'active'
    and app_private.authz_reason(member.user_id, target_workspace_id,
      'employee.decide_preferred_name', null, target_employee_id) is null;

  -- Nobody ranks above the owner: with nobody to answer it, a request does
  -- not wait (KK-17).
  if cardinality(deciders) = 0 then
    approval := 'auto';
  end if;

  -- Whatever was waiting is replaced: the latest answer is the one asked for.
  with gone as (
    update public.employee_preferred_name_requests
    set status = 'rejected', decided_by = actor_user_id, decided_at = now()
    where employee_id = target_employee_id and status = 'pending'
    returning id
  )
  select coalesce(array_agg(gone.id), '{}') into replaced from gone;

  insert into public.employee_preferred_name_requests (
    workspace_id, employee_id, requested_name, status, requested_by,
    decided_by, decided_at
  )
  values (
    target_workspace_id, target_employee_id, cleaned,
    case when approval = 'auto' then 'approved' else 'pending' end,
    actor_user_id,
    case when approval = 'auto' then actor_user_id end,
    case when approval = 'auto' then now() end
  )
  returning id into asked;

  -- The earlier ask's cards close; waiting, the deciders the domain found above are told.
  perform app_private.preferred_name_tell_asked(target_workspace_id, target_employee_id, replaced,
    case when approval <> 'auto' then asked end, cleaned, deciders, actor_user_id);

  if approval = 'auto' then
    update public.employee_profiles
    set preferred_name = cleaned, updated_at = now()
    where id = target_employee_id;
  end if;

  return case when approval = 'auto' then 'published' else 'waiting' end;
end;
$$;


ALTER FUNCTION "public"."request_employee_preferred_name_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "preferred_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_workspace_closure_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "closure_mode" "text", "typed_workspace_name" "text" DEFAULT NULL::"text", "acknowledged" boolean DEFAULT false, "target_effective_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  workspace_row public.workspaces%rowtype;
  actor_role public.workspace_role;
  request_id uuid;
  effective_at timestamptz;
  revocation jsonb;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501', hint = 'actor.required';
  end if;
  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);
  if not acknowledged then
    raise exception 'workspace closure requires explicit acknowledgement' using errcode = '23514', hint = 'workspace.closure.acknowledgement_required';
  end if;
  if closure_mode not in ('scheduled_end_period', 'immediate') then
    raise exception 'valid workspace closure mode required' using errcode = '22023', hint = 'workspace.closure.mode_invalid';
  end if;

  select * into workspace_row
  from public.workspaces
  where id = target_workspace_id
  for update;

  if workspace_row.id is null or workspace_row.lifecycle_status = 'deleted' then
    raise exception 'workspace not found' using errcode = '02000', hint = 'workspace.not_found';
  end if;

  -- The core says who the actor is here (ROL-CIFT 1.4).
  select state.class into actor_role
  from app_private.actor(actor_user_id, target_workspace_id) state
  where state.status = 'active';

  if actor_role is distinct from 'owner'::public.workspace_role then
    raise exception 'workspace owner access required' using errcode = '42501', hint = 'workspace.owner_required';
  end if;

  if closure_mode = 'immediate' then
    if typed_workspace_name is distinct from workspace_row.name then
      raise exception 'workspace name confirmation does not match' using errcode = '23514', hint = 'workspace.closure.name_mismatch';
    end if;

    update public.workspace_closure_requests
    set status = 'cancelled',
        cancelled_at = now(),
        cancelled_by = actor_user_id,
        updated_at = now()
    where workspace_id = target_workspace_id
      and status = 'scheduled';

    insert into public.workspace_closure_requests (
      workspace_id,
      requested_by,
      mode,
      status,
      typed_workspace_name,
      effective_at,
      completed_at,
      metadata
    )
    values (
      target_workspace_id,
      actor_user_id,
      'immediate',
      'completed',
      typed_workspace_name,
      now(),
      now(),
      jsonb_build_object('unrecoverable_by_user', true)
    )
    returning id into request_id;

    revocation := app_private.finish_workspace_closure(
      target_workspace_id, actor_user_id, request_id, now(), 'immediate'
    );

    return jsonb_build_object(
      'status', 'deleted',
      'workspace_id', target_workspace_id,
      'closure_request_id', request_id,
      'runtime_revocation', revocation
    );
  end if;

  effective_at := coalesce(target_effective_at, now() + app_private.default_closure_period());
  if effective_at <= now() then
    raise exception 'scheduled workspace closure requires a future effective time'
      using errcode = '23514', hint = 'workspace.closure.effective_at_past';
  end if;

  update public.workspace_closure_requests
  set status = 'cancelled',
      cancelled_at = now(),
      cancelled_by = actor_user_id,
      updated_at = now()
  where workspace_id = target_workspace_id
    and status = 'scheduled';

  insert into public.workspace_closure_requests (
    workspace_id,
    requested_by,
    mode,
    status,
    effective_at
  )
  values (
    target_workspace_id,
    actor_user_id,
    'scheduled_end_period',
    'scheduled',
    effective_at
  )
  returning id into request_id;

  update public.workspaces
  set lifecycle_status = 'closure_scheduled',
      closure_scheduled_at = now(),
      closure_effective_at = effective_at,
      closed_at = null,
      closed_by = null,
      updated_at = now()
  where id = target_workspace_id;

  insert into public.audit_events (
    workspace_id,
    actor_user_id,
    action,
    target_type,
    target_id,
    metadata
  )
  values (
    target_workspace_id,
    actor_user_id,
    'workspace.closure.scheduled',
    'workspace',
    target_workspace_id::text,
    jsonb_build_object('closure_request_id', request_id, 'effective_at', effective_at)
  );

  perform app_private.notify_workspace_closing(target_workspace_id, actor_user_id, request_id, effective_at, false);

  return jsonb_build_object(
    'status', 'scheduled',
    'workspace_id', target_workspace_id,
    'closure_request_id', request_id,
    'effective_at', effective_at
  );
end;
$$;


ALTER FUNCTION "public"."request_workspace_closure_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "closure_mode" "text", "typed_workspace_name" "text", "acknowledged" boolean, "target_effective_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_weekly_exchange_employee_warning"("actor" "uuid", "w" "uuid", "emp" "uuid", "target" "jsonb", "command" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare warning jsonb;
begin
 if not exists(select 1 from public.employee_profiles e join public.workspace_memberships m
  on m.workspace_id=e.workspace_id and m.user_id=e.user_id and m.status='active'
  where e.workspace_id=w and e.id=emp and e.user_id=actor and e.archived_at is null) then
  raise exception 'Employee acceptance access denied' using errcode='42501',hint='authz.out_of_scope'; end if;
 warning:=public.weekly_exchange_employee_warning(w,emp,target);
 if warning is not null and command->>'availability_fingerprint' is distinct from warning->>'fingerprint' then
  raise exception 'Your availability conflicts with this shift. Refresh the request and choose to continue anyway.' using errcode='PT409'; end if;
end; $$;


ALTER FUNCTION "public"."require_weekly_exchange_employee_warning"("actor" "uuid", "w" "uuid", "emp" "uuid", "target" "jsonb", "command" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_owner_onboarding_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  onboarding_status public.onboarding_status;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.setup');

  select onboarding.status
  into onboarding_status
  from public.workspace_onboarding onboarding
  where onboarding.workspace_id = target_workspace_id
  for update;

  if onboarding_status is null then
    raise exception 'workspace onboarding was not found' using errcode = 'P0002';
  end if;
  if onboarding_status = 'complete'::public.onboarding_status then
    raise exception 'completed owner onboarding cannot be reset' using errcode = '22023';
  end if;
  -- The reset deletes every job; a Management job somebody other than the owner holds would go with it
  -- and leave them without one (KARARLAR S-168, ROL-CIFT 1.3).
  if exists (
    select 1 from public.membership_management_jobs held
    join public.workspace_memberships membership on membership.id = held.membership_id
    join public.workspace_roles role on role.id = membership.role_id
    where held.workspace_id = target_workspace_id and role.access_class <> 'owner'
  ) then
    raise exception 'somebody besides the owner holds a Management job; setup cannot start over'
      using errcode = '22023', hint = 'onboarding.reset_management_jobs_held';
  end if;

  delete from public.employee_profiles
  where workspace_id = target_workspace_id
    and user_id is null;

  delete from public.jobs
  where workspace_id = target_workspace_id;

  delete from public.departments
  where workspace_id = target_workspace_id;

  delete from public.locations
  where workspace_id = target_workspace_id;

  update public.workspace_onboarding
  set status = 'incomplete'::public.onboarding_status,
      current_step = 1,
      completed_at = null,
      updated_by = actor_user_id,
      updated_at = now()
  where workspace_id = target_workspace_id;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id
  ) values (
    target_workspace_id,
    actor_user_id,
    'workspace.onboarding_reset',
    'workspace',
    target_workspace_id::text
  );
end;
$$;


ALTER FUNCTION "public"."reset_owner_onboarding_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_workspace_context_service"("actor_user_id" "uuid", "target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "workspace_id" "uuid", "workspace_name" "text", "workspace_logo_storage_path" "text", "workspace_logo_file_name" "text", "workspace_logo_updated_at" timestamp with time zone, "schedule_logo_scale" numeric, "schedule_logo_offset_x" numeric, "schedule_logo_offset_y" numeric, "membership_id" "uuid", "management_access" "public"."workspace_role", "employee_access" boolean, "membership_role_id" "uuid", "membership_role_name" "text", "permission_keys" "text"[], "all_locations" boolean, "onboarding_status" "public"."onboarding_status", "onboarding_current_step" smallint, "onboarding_revision" integer, "actions" "text"[], "location_ids" "uuid"[], "document_restricted" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chosen uuid := target_workspace_id;
  state app_private.actor_state;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;

  if chosen is null then
    select membership.workspace_id into chosen
    from public.workspace_memberships membership
    left join public.user_workspace_preferences preference on preference.user_id = membership.user_id
    where membership.user_id = actor_user_id
      and membership.status = 'active'
      and (
        membership.workspace_id = preference.active_workspace_id
        or (
          select count(*) from public.workspace_memberships other
          where other.user_id = actor_user_id and other.status = 'active'
        ) = 1
      )
    order by (membership.workspace_id = preference.active_workspace_id) desc nulls last, membership.created_at
    limit 1;
    if chosen is null then
      return;
    end if;
  else
    perform set_config('app.allow_incomplete_workspace_context', 'on', true);
  end if;

  state := app_private.actor(actor_user_id, chosen);

  return query
  select
    membership.user_id,
    workspace.id,
    workspace.name,
    workspace.logo_storage_path,
    workspace.logo_file_name,
    workspace.logo_updated_at,
    workspace.schedule_logo_scale,
    workspace.schedule_logo_offset_x,
    workspace.schedule_logo_offset_y,
    membership.id,
    -- The two slots (ROL-CIFT 1.5): the management slot's class, or none; whether the employee slot is held.
    (select management.access_class from public.workspace_roles management where management.id = membership.role_id),
    membership.employee_role_id is not null,
    role.id,
    role.name,
    coalesce(
      array_agg(grant_row.permission_key order by permission.sort_order)
        filter (where grant_row.permission_key is not null),
      '{}'::text[]
    ),
    role.access_class in ('owner', 'admin'),
    onboarding.status,
    onboarding.current_step,
    onboarding.revision,
    app_private.actor_actions(state),
    case when role.access_class in ('owner', 'admin') then '{}'::uuid[]
         when role.access_class = 'manager' then state.manages else state.works end,
    state.document_blocked
  from public.workspace_memberships membership
  join public.workspaces workspace
    on workspace.id = membership.workspace_id
  -- The role a screen shows: the management slot's, else the employee slot's (ROL-CIFT 1.4; the
  -- membership's two slots reach the API in 1.5).
  join public.workspace_roles role
    on role.id = coalesce(membership.role_id, membership.employee_role_id)
   and role.workspace_id = membership.workspace_id
  left join public.workspace_role_permissions grant_row
    on grant_row.role_id = role.id
  left join public.permissions permission
    on permission.key = grant_row.permission_key
  join public.workspace_onboarding onboarding
    on onboarding.workspace_id = workspace.id
  where membership.user_id = actor_user_id
    and membership.workspace_id = chosen
    and membership.status = 'active'
    -- ponytail: the workspace they last chose is not checked for being open,
    -- as before; its actions are empty when it is closed (the core refuses).
    and (target_workspace_id is null or app_private.workspace_allows_interactive_access(workspace.id))
  group by
    membership.user_id,
    workspace.id,
    workspace.name,
    workspace.logo_storage_path,
    workspace.logo_file_name,
    workspace.logo_updated_at,
    workspace.schedule_logo_scale,
    workspace.schedule_logo_offset_x,
    workspace.schedule_logo_offset_y,
    membership.id,
    membership.role_id,
    membership.employee_role_id,
    role.access_class,
    role.id,
    role.name,
    onboarding.status,
    onboarding.current_step,
    onboarding.revision;
end;
$$;


ALTER FUNCTION "public"."resolve_workspace_context_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_workspace_todo_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_todo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.workspace_todos%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.todos');
  -- Asked before the lock: a to-do about somebody out of reach is not theirs to touch.
  select * into target
  from public.workspace_todos
  where id = target_todo_id
    and workspace_id = target_workspace_id;
  if not found then
    raise exception 'workspace todo not found' using errcode = 'P0002';
  end if;
  if target.employee_id is not null then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.read', target_person => target.employee_id);
  end if;
  if target.system_generated then
    raise exception 'system todo resolves from source' using errcode = '42501', hint = 'authz.missing_permission';
  end if;

  update public.workspace_todos
  set status = 'resolved',
      resolved_at = now(),
      updated_at = now()
  where id = target_todo_id
    and workspace_id = target_workspace_id
    and status = 'open'
  returning * into target;

  if not found then
    select * into target
    from public.workspace_todos
    where id = target_todo_id
      and workspace_id = target_workspace_id;
  end if;

  return app_private.workspace_todo_json(target);
end;
$$;


ALTER FUNCTION "public"."resolve_workspace_todo_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_todo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_workspace_ownership_transfer_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "transfer_id" "uuid", "transfer_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  transfer_row public.workspace_ownership_transfers%rowtype;
  owner_role_id uuid;
  admin_role_id uuid;
  owed public.employee_onboarding_requirements%rowtype;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501', hint = 'actor.required';
  end if;
  if transfer_action not in ('accept', 'reject') then
    raise exception 'valid ownership transfer action required' using errcode = '22023', hint = 'transfer.action_invalid';
  end if;

  perform 1 from public.workspaces where id = target_workspace_id for update;

  select * into transfer_row
  from public.workspace_ownership_transfers transfer
  where transfer.id = transfer_id
    and transfer.workspace_id = target_workspace_id
  for update;

  if transfer_row.id is null or transfer_row.status <> 'pending' then
    raise exception 'pending ownership transfer not found' using errcode = '02000', hint = 'transfer.not_found';
  end if;
  if transfer_row.target_user_id <> actor_user_id then
    raise exception 'ownership transfer target access required' using errcode = '42501', hint = 'transfer.target_required';
  end if;
  if transfer_row.expires_at <= now() then
    update public.workspace_ownership_transfers
    set status = 'cancelled',
        cancelled_at = now(),
        cancelled_by = actor_user_id,
        updated_at = now()
    where id = transfer_row.id;
    raise exception 'ownership transfer has expired' using errcode = '23514', hint = 'transfer.expired';
  end if;

  if transfer_action = 'reject' then
    update public.workspace_ownership_transfers
    set status = 'rejected',
        rejected_at = now(),
        updated_at = now()
    where id = transfer_row.id;

    insert into public.audit_events (
      workspace_id,
      actor_user_id,
      action,
      target_type,
      target_id
    )
    values (
      target_workspace_id,
      actor_user_id,
      'workspace.ownership_transfer.rejected',
      'workspace_ownership_transfer',
      transfer_id::text
    );

    perform app_private.ownership_tell(transfer_row, 'declined', actor_user_id);
    return jsonb_build_object(
      'status', 'rejected',
      'transfer_id', transfer_id,
      'workspace_id', target_workspace_id
    );
  end if;

  if not app_private.workspace_allows_interactive_access(target_workspace_id) or not exists (
    select 1 from public.workspace_memberships m
    left join public.workspace_roles r on r.id = m.role_id and r.workspace_id = m.workspace_id
    join auth.users u on u.id = m.user_id and u.email_confirmed_at is not null
    where m.id = transfer_row.target_membership_id and m.workspace_id = target_workspace_id
      and m.user_id = actor_user_id and m.status = 'active' and r.access_class = 'admin'
      and not exists (select 1 from public.employee_onboarding_cases c
        where c.membership_id = m.id and c.workspace_id = m.workspace_id and c.status <> 'approved')
      -- The Owner job is the owner's management job (membership_slot_rows_follow), so taking
      -- ownership asks for no employee record (ROL-CIFT, design §4.12).
  ) or not exists (
    select 1 from public.workspace_memberships m
    left join public.workspace_roles r on r.id = m.role_id and r.workspace_id = m.workspace_id
    where m.id = transfer_row.previous_owner_membership_id and m.workspace_id = target_workspace_id
      and m.user_id = transfer_row.initiated_by and m.status = 'active' and r.access_class = 'owner'
  ) then raise exception 'ownership transfer participants are no longer eligible' using errcode = '42501', hint = 'transfer.participants_ineligible'; end if;

  select id into owner_role_id
  from public.workspace_roles
  where workspace_id = target_workspace_id
    and system_key = 'owner';

  select id into admin_role_id
  from public.workspace_roles
  where workspace_id = target_workspace_id
    and system_key = 'admin';

  if owner_role_id is null or admin_role_id is null then
    raise exception 'system owner and admin roles are required' using errcode = 'P0002', hint = 'workspace.roles_missing';
  end if;

  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);
  perform set_config('app.owner_transfer', 'on', true);

  update public.workspace_memberships
  set role_id = owner_role_id,
      updated_at = now()
  where id = transfer_row.target_membership_id
    and workspace_id = target_workspace_id
    and status = 'active';

  update public.workspace_memberships
  set role_id = admin_role_id,
      updated_at = now()
  where id = transfer_row.previous_owner_membership_id
    and workspace_id = target_workspace_id
    and status = 'active';

  -- The Owner job moves with ownership (BL-218): off the old owner's record,
  -- onto the new owner's, with every location, in this transaction.
  update public.employee_job_assignments assignment
  set ended_at = now(), is_primary = false
  from public.jobs job
  where job.id = assignment.job_id
    and job.workspace_id = target_workspace_id
    and job.system_key = 'owner'
    and assignment.ended_at is null
    and not app_private.employee_record_is_workspace_owner(target_workspace_id, assignment.employee_id);
  perform app_private.open_owner_record_to_everything(target_workspace_id, employee.id, actor_user_id)
  from public.employee_profiles employee
  where employee.workspace_id = target_workspace_id
    and employee.user_id = actor_user_id
    and employee.archived_at is null;

  -- The new owner is asked for no document from now on, like any owner
  -- (BL-246): what they still owed is excused the way a document reaching an
  -- owner later is, and the document block lifts with it. Each excuse is
  -- recorded like any exemption, as the old owner's are when taken back.
  for owed in
  update public.employee_onboarding_requirements requirement
  set (owner_excused, lifecycle_exempt, required, blocks_activation, deadline_at, lifecycle_close_reason,
       paused_remaining_seconds, document_suspended_at, lifecycle_closed_at) = (
        select excused.owner_excused, excused.lifecycle_exempt, excused.required, excused.blocks_activation,
          excused.deadline_at, excused.lifecycle_close_reason,
          excused.paused_remaining_seconds, excused.document_suspended_at, excused.lifecycle_closed_at
        from app_private.owner_document_excused(requirement) excused
      ),
      lifecycle_revision = requirement.lifecycle_revision + 1,
      updated_at = now()
  from public.employee_profiles employee
  where employee.id = requirement.employee_id
    and employee.workspace_id = target_workspace_id
    and employee.user_id = actor_user_id
    and requirement.workspace_id = target_workspace_id
    and requirement.kind in ('document', 'acknowledgement')
    and not requirement.lifecycle_exempt
    and requirement.lifecycle_retired_at is null
  returning requirement.*
  loop
    perform app_private.document_audit(owed, actor_user_id, 'document.exempted',
      jsonb_build_object('reason', 'Now the owner', 'revision', owed.lifecycle_revision));
  end loop;

  -- The old owner, now an admin, is asked for the documents everyone is
  -- (BL-252): the excuses they had for being the owner are taken back as a
  -- reviewer removes one. A document that is down keeps its excuse until it is
  -- put back up (set_document_publication_service).
  for owed in
    select r.* from public.employee_onboarding_requirements r
    join public.employee_profiles employee on employee.id = r.employee_id
    where r.workspace_id = target_workspace_id
      and employee.workspace_id = target_workspace_id
      and employee.user_id = transfer_row.initiated_by
      and r.kind in ('document', 'acknowledgement')
      and r.owner_excused
      and r.lifecycle_retired_at is null
    for update of r
  loop
    begin
      perform app_private.set_document_exemption(owed, actor_user_id, false, 'No longer the owner', owed.lifecycle_revision);
    exception when sqlstate 'PT409' then
      null;
    end;
  end loop;

  update public.workspace_ownership_transfers
  set status = 'accepted',
      accepted_at = now(),
      updated_at = now()
  where id = transfer_row.id;

  insert into public.audit_events (
    workspace_id,
    actor_user_id,
    action,
    target_type,
    target_id,
    metadata
  )
  values (
    target_workspace_id,
    actor_user_id,
    'workspace.ownership_transfer.accepted',
    'workspace_ownership_transfer',
    transfer_id::text,
    jsonb_build_object(
      'previous_owner_membership_id', transfer_row.previous_owner_membership_id,
      'target_membership_id', transfer_row.target_membership_id
    )
  );

  insert into public.audit_events (
    workspace_id,
    actor_user_id,
    action,
    target_type,
    target_id,
    metadata
  )
  values (
    target_workspace_id,
    actor_user_id,
    'billing.payment_method.detach_required_after_owner_transfer',
    'workspace',
    target_workspace_id::text,
    jsonb_build_object('previous_owner_user_id', transfer_row.initiated_by)
  );

  perform app_private.ownership_tell(transfer_row, 'accepted', actor_user_id);
  return jsonb_build_object(
    'status', 'accepted',
    'transfer_id', transfer_id,
    'workspace_id', target_workspace_id
  );
end;
$$;


ALTER FUNCTION "public"."respond_workspace_ownership_transfer_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "transfer_id" "uuid", "transfer_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_account_deletion_by_token_service"("recovery_token_digest" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  restored_request public.account_deletion_requests%rowtype;
begin
  if recovery_token_digest is null
    or recovery_token_digest !~ '^[a-f0-9]{64}$' then
    raise exception 'valid recovery token required' using errcode = '22023';
  end if;

  update public.account_deletion_requests
  set status = 'restored',
      restored_at = now(),
      recovery_token_digest = null,
      updated_at = now()
  where id = (
    select request.id
    from public.account_deletion_requests request
    where (request.recovery_token_digest = restore_account_deletion_by_token_service.recovery_token_digest
      or exists (select 1 from public.account_deletion_deliveries delivery
        where delivery.request_id = request.id
          and delivery.token_digest = restore_account_deletion_by_token_service.recovery_token_digest))
      and request.status = 'pending'
      and request.restore_until > now()
    order by request.requested_at desc
    limit 1
    for update
  )
  returning * into restored_request;

  if restored_request.id is null then
    raise exception 'valid recovery token required' using errcode = 'P0002';
  end if;

  perform app_private.record_security_audit_event_service(
    restored_request.user_id, null, 'account.deletion_restored', 'account.security',
    'account_deletion_request', restored_request.id::text, '{}'::jsonb
  );

  return jsonb_build_object(
    'status', restored_request.status,
    'request_id', restored_request.id,
    'user_id', restored_request.user_id,
    'restored_at', restored_request.restored_at
  );
end;
$_$;


ALTER FUNCTION "public"."restore_account_deletion_by_token_service"("recovery_token_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "target_submission_id" "uuid", "review_decision" "text", "review_reason" "text", "correction_period" "text", "file_decisions" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; s public.employee_document_submissions%rowtype; choice jsonb; next_deadline timestamptz; remaining numeric; suspended timestamptz; correction_draft uuid;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'documents.review',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id));
 perform 1 from public.employee_onboarding_cases c join public.employee_onboarding_requirements q on q.case_id=c.id where q.id=target_requirement_id and app_private.document_actor_can_read(actor_user_id,q.workspace_id,q.employee_id,q.lifecycle_user_id) for update of c;
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and workspace_id=target_workspace_id for update;
 if r.id is null then raise exception 'document unavailable' using errcode='P0002'; end if;
 perform app_private.assert_document_published(r);
 if r.lifecycle_revision<>expected_revision or r.submitted_document_id is distinct from target_submission_id then raise exception 'document changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 if r.lifecycle_closed_at is not null or r.lifecycle_exempt or r.status='superseded' then raise exception 'document obligation is closed' using errcode='22023'; end if;
 select * into s from public.employee_document_submissions where id=target_submission_id and requirement_id=r.id and state in ('pending_review','accepted') for update;
 if s.id is null then raise exception 'submission changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 if review_decision is null or review_decision not in ('approve','reject') or correction_period is null or correction_period not in ('full','remaining')
  or (review_decision='reject' and (nullif(btrim(review_reason),'') is null or char_length(review_reason)>500)) then raise exception 'valid review decision and reason required' using errcode='22023'; end if;
 if file_decisions is null or jsonb_typeof(file_decisions)<>'array' then raise exception 'file decisions required' using errcode='22023'; end if;
 if jsonb_array_length(file_decisions)<>(select count(*) from public.employee_document_submission_files where submission_id=s.id)
  or (select count(distinct value->>'id') from jsonb_array_elements(file_decisions))<>jsonb_array_length(file_decisions)
 then raise exception 'decide every file exactly once' using errcode='22023'; end if;
 for choice in select value from jsonb_array_elements(file_decisions) loop
  if choice->>'decision' is null or choice->>'decision' not in ('keep','discard') or char_length(coalesce(choice->>'note',''))>500
   or not exists(select 1 from public.employee_document_submission_files where submission_id=s.id and file_id=(choice->>'id')::uuid)
  then raise exception 'invalid file decision' using errcode='22023'; end if;
 end loop;
 if review_decision='approve' and not exists(select 1 from jsonb_array_elements(file_decisions) f where f->>'decision'='keep') then raise exception 'keep a file to approve' using errcode='22023'; end if;
 if review_decision='approve' and s.expiry_date is not null and app_private.document_employee_timezone(r.workspace_id,r.employee_id) is null then raise exception 'Document timezone needs administrator configuration' using errcode='22023'; end if; if review_decision='approve' and s.expiry_date<(now() at time zone app_private.document_employee_timezone(r.workspace_id,r.employee_id))::date then raise exception 'expired document cannot be approved' using errcode='22023'; end if;
 remaining:=coalesce(r.paused_remaining_seconds,case when r.deadline_at is not null then greatest(0,extract(epoch from r.deadline_at-now())) end);
 if review_decision='reject' and correction_period='remaining' and coalesce(remaining,0)<=0 then raise exception 'no correction time remains' using errcode='22023'; end if;
 suspended:=r.document_suspended_at;
 if app_private.document_obligation_blocked(r,now()) then suspended:=coalesce(suspended,now()); end if;
 next_deadline:=r.deadline_at;
 if review_decision='reject' then
  next_deadline:=case when correction_period='remaining' then now()+remaining*interval '1 second'
   when r.lifecycle_settings->>'period_days' is not null then now()+(r.lifecycle_settings->>'period_days')::integer*interval '24 hours' else null end;
 end if;
 for choice in select value from jsonb_array_elements(file_decisions) loop
  update public.employee_document_submission_files set decision=choice->>'decision',note=coalesce(choice->>'note','') where submission_id=s.id and file_id=(choice->>'id')::uuid;
 end loop;
 update public.employee_document_submissions set state=case when review_decision='approve' then 'accepted' else 'rejected' end,
  reviewed_at=now(),reviewed_by=actor_user_id,rejection_reason=case when review_decision='reject' then btrim(review_reason) end where id=s.id;
 update public.employee_onboarding_requirements set
  approved_document_id=case when review_decision='approve' then s.id when approved_document_id=s.id then null else approved_document_id end,
  deadline_at=next_deadline,paused_remaining_seconds=null,
  document_suspended_at=case when review_decision='approve' then null else suspended end,
  status=case when review_decision='approve' then 'completed'::public.employee_onboarding_requirement_status else 'rejected'::public.employee_onboarding_requirement_status end,
  rejection_reason=case when review_decision='reject' then btrim(review_reason) end,
  lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning lifecycle_revision into expected_revision;
 perform app_private.document_audit(r,actor_user_id,'document.'||review_decision,
  jsonb_build_object('submission_id',s.id,'revision',expected_revision,'reason',review_reason,'correction_period',correction_period,'old_deadline',r.deadline_at,'new_deadline',next_deadline,'files',file_decisions));

 if review_decision='reject' and exists(select 1 from public.employee_document_submission_files where submission_id=s.id and decision='keep')
  and not exists(select 1 from public.employee_document_submissions where requirement_id=r.id and state='draft') then
  insert into public.employee_document_submissions(workspace_id,employee_id,requirement_id,user_id,version,state,expiry_date,metadata)
  select r.workspace_id,r.employee_id,r.id,r.lifecycle_user_id,coalesce(max(version),0)+1,'draft',s.expiry_date,s.metadata from public.employee_document_submissions where requirement_id=r.id returning id into correction_draft;
  insert into public.employee_document_submission_files(submission_id,file_id,requirement_id,workspace_id,employee_id,decision,note)
  select correction_draft,file_id,requirement_id,workspace_id,employee_id,'keep',note from public.employee_document_submission_files where submission_id=s.id and decision='keep';
 end if;
 perform app_private.document_sync_onboarding(r.id,actor_user_id); return expected_revision;
end;
$$;


ALTER FUNCTION "public"."review_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "target_submission_id" "uuid", "review_decision" "text", "review_reason" "text", "correction_period" "text", "file_decisions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_employee_onboarding_before_availability_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "review_action" "text", "target_requirement_id" "uuid", "review_reason" "text", "expected_revision" integer, "production_ready" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_case public.employee_onboarding_cases%rowtype;
  requirement public.employee_onboarding_requirements%rowtype;
  private_profile public.employee_private_profiles%rowtype;
  target_employee_user_id uuid;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'onboarding.review', target_person => target_employee_id);

  select onboarding.* into target_case
  from public.employee_onboarding_cases onboarding
  where onboarding.workspace_id = target_workspace_id
    and onboarding.employee_id = target_employee_id
  for update of onboarding;
  if target_case.id is null or target_case.revision <> expected_revision then raise exception 'onboarding changed; refresh required' using errcode = 'PT409', hint = 'onboarding.changed'; end if;
  select employee.user_id into target_employee_user_id
  from public.employee_profiles employee
  where employee.id = target_employee_id
    and employee.workspace_id = target_workspace_id;
  if review_action in ('accept_requirement', 'reject_requirement') then
    select * into requirement from public.employee_onboarding_requirements
    where id = target_requirement_id and case_id = target_case.id for update;
    if requirement.id is null or not requirement.requires_review then raise exception 'reviewable requirement unavailable' using errcode = 'P0002'; end if;
    if requirement.kind = 'document'::public.employee_onboarding_requirement_kind then
      perform app_private.authorize(actor_user_id, target_workspace_id, 'documents.review', target_person => target_employee_id);
    end if;
    -- A legal name is approved by an owner or an admin only (FB-6.6 S1).
    if requirement.kind = 'profile'::public.employee_onboarding_requirement_kind then
      perform app_private.authorize(actor_user_id, target_workspace_id, 'onboarding.legal_name', target_person => target_employee_id);
    end if;
    if review_action = 'reject_requirement' and char_length(btrim(coalesce(review_reason, ''))) not between 1 and 500 then
      raise exception 'specific correction reason required' using errcode = '22023';
    end if;
    update public.employee_onboarding_requirements set
      status = case
        when review_action = 'accept_requirement' then 'completed'::public.employee_onboarding_requirement_status
        else 'rejected'::public.employee_onboarding_requirement_status
      end,
      rejection_reason = case when review_action = 'reject_requirement' then btrim(review_reason) else null end,
      reviewed_by = actor_user_id,
      reviewed_at = now(),
      completed_at = case when review_action = 'accept_requirement' then now() else null end,
      updated_at = now()
    where id = requirement.id;
    if requirement.kind = 'document'::public.employee_onboarding_requirement_kind then
      update public.employee_documents set
        review_status = case
          when review_action = 'accept_requirement' then 'accepted'::public.employee_document_review_status
          else 'rejected'::public.employee_document_review_status
        end,
        rejection_reason = case when review_action = 'reject_requirement' then btrim(review_reason) else null end,
        reviewed_by = actor_user_id, reviewed_at = now()
      where requirement_id = requirement.id and review_status = 'awaiting_review'::public.employee_document_review_status;
    end if;
    if requirement.kind = 'profile'::public.employee_onboarding_requirement_kind and review_action = 'accept_requirement' then
      select * into private_profile
      from public.employee_private_profiles
      where employee_id = target_employee_id;
      if private_profile.employee_id is null then
        raise exception 'private profile unavailable' using errcode = 'P0002';
      end if;
      update public.employee_profiles set
        first_name = private_profile.legal_first_name,
        last_name = private_profile.legal_last_name,
        revision = revision + 1,
        updated_at = now()
      where id = target_employee_id;
      insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
      values (target_workspace_id, target_employee_id, actor_user_id,
        'employee.legal_name_approved', 'Employee legal name change approved from onboarding');
    end if;
    if review_action = 'reject_requirement' then
      update public.employee_onboarding_cases set status = 'changes_requested'::public.employee_onboarding_case_status, revision = revision + 1,
        updated_at = now() where id = target_case.id returning revision into expected_revision;
      -- Back with the person: the reviewers' cards close, and the person hears what to change.
      select * into target_case from public.employee_onboarding_cases where id = target_case.id;
      perform app_private.onboarding_tell(target_case, 'changes', actor_user_id, review_reason);
    else
      update public.employee_onboarding_cases set revision = revision + 1, updated_at = now()
      where id = target_case.id returning revision into expected_revision;
      if target_case.status = 'submitted'::public.employee_onboarding_case_status
        and not target_case.final_approval_required
        and not exists (
          select 1
          from public.employee_onboarding_requirements
          where case_id = target_case.id
            and required
            and blocks_activation
            and status <> 'completed'::public.employee_onboarding_requirement_status
        ) then
        expected_revision := app_private.activate_employee_onboarding_case(
          target_case.id,
          actor_user_id,
          'employee.auto_activated_after_review'
        );
      end if;
      -- Not let in yet: the cards close once nothing in it is left for their holders (onboarding_tell).
      select * into target_case from public.employee_onboarding_cases where id = target_case.id;
      if target_case.status <> 'approved'::public.employee_onboarding_case_status then
        perform app_private.onboarding_tell(target_case, 'reviewed', actor_user_id);
      end if;
    end if;
  elsif review_action = 'activate' then
    if target_case.status <> 'submitted'::public.employee_onboarding_case_status then raise exception 'submitted onboarding required' using errcode = '23514'; end if;
    if not production_ready then raise exception 'sensitive infrastructure readiness required' using errcode = '55000'; end if;
    if exists (select 1 from public.employee_onboarding_requirements
      where case_id = target_case.id and required and blocks_activation and status <> 'completed'::public.employee_onboarding_requirement_status) then
      raise exception 'activation-blocking requirements remain' using errcode = '23514';
    end if;
    expected_revision := app_private.activate_employee_onboarding_case(
      target_case.id,
      actor_user_id,
      'employee.activated'
    );
  else
    raise exception 'unsupported onboarding review action' using errcode = '22023';
  end if;
  insert into public.onboarding_events (workspace_id, employee_id, case_id, actor_user_id, action, target_type, target_id, metadata)
  values (target_workspace_id, target_employee_id, target_case.id, actor_user_id,
    'onboarding.' || review_action, 'onboarding_case', target_case.id::text,
    jsonb_build_object('requirement_id', target_requirement_id, 'reason_present', nullif(btrim(coalesce(review_reason, '')), '') is not null));
  return expected_revision;
end;
$$;


ALTER FUNCTION "public"."review_employee_onboarding_before_availability_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "review_action" "text", "target_requirement_id" "uuid", "review_reason" "text", "expected_revision" integer, "production_ready" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_employee_onboarding_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "review_action" "text", "target_requirement_id" "uuid", "review_reason" "text", "expected_revision" integer, "production_ready" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform app_private.authorize(actor_user_id, target_workspace_id, 'onboarding.review', target_person => target_employee_id);
 perform public.get_employee_onboarding_review_service(actor_user_id,target_workspace_id,target_employee_id);
 if review_action in ('accept_requirement','reject_requirement') and exists (
  select 1 from public.employee_onboarding_requirements r where r.id=target_requirement_id
   and r.workspace_id=target_workspace_id and r.employee_id=target_employee_id and r.kind='availability'
 ) then raise exception 'Weekly availability is confirmed by the employee and does not require review' using errcode='22023'; end if;
 if exists(select 1 from public.employee_onboarding_requirements r where r.id=target_requirement_id and r.kind='document') then raise exception 'Review the submitted document version in Documents' using errcode='PT409',hint='onboarding.review_in_documents'; end if;
 return public.review_employee_onboarding_before_availability_service(actor_user_id,target_workspace_id,target_employee_id,
  review_action,target_requirement_id,review_reason,expected_revision,production_ready);
end; $$;


ALTER FUNCTION "public"."review_employee_onboarding_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "review_action" "text", "target_requirement_id" "uuid", "review_reason" "text", "expected_revision" integer, "production_ready" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_employee_invitation_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invitation_row public.employee_invitations%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.invite', target_person => target_employee_id);
  select * into invitation_row
  from public.employee_invitations
  where employee_id = target_employee_id and workspace_id = target_workspace_id and status = 'pending'
  order by created_at desc
  limit 1
  for update;
  if invitation_row.id is null then
    raise exception 'pending invitation not found' using errcode = 'P0002';
  end if;
  if not app_private.can_invite_with_role(actor_user_id, target_workspace_id, invitation_row.role_id) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  update public.employee_invitations
  set status = 'revoked', revoked_at = now(), updated_at = now()
  where employee_id = target_employee_id and workspace_id = target_workspace_id and status = 'pending';
  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (target_workspace_id, target_employee_id, actor_user_id, 'employee.invitation_revoked', 'Employee invitation revoked');
end;
$$;


ALTER FUNCTION "public"."revoke_employee_invitation_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_removed_assignment_availability_override"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform public.availability_lock_workspace(old.workspace_id);
 -- Save/acquire/discard copies can delete a row while its identical assignment
 -- still exists in the other store. Keep only evidence valid for retained work.
 update public.schedule_availability_overrides o set revoked_at=now()
 where o.workspace_id=old.workspace_id and o.shift_id=old.id and o.revoked_at is null
  and not exists(select 1 from public.schedule_edit_session_shifts s where s.workspace_id=o.workspace_id and s.id=o.shift_id
    and case when s.employee_id is not null then public.assess_weekly_shift_availability(s.workspace_id,s.employee_id,to_jsonb(s))->>'fingerprint'=o.assessment_fingerprint else false end)
  and not exists(select 1 from public.schedule_draft_shifts s where s.workspace_id=o.workspace_id and s.id=o.shift_id
    and case when s.employee_id is not null then public.assess_weekly_shift_availability(s.workspace_id,s.employee_id,to_jsonb(s))->>'fingerprint'=o.assessment_fingerprint else false end);

  return old;
end; $$;


ALTER FUNCTION "public"."revoke_removed_assignment_availability_override"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_announcement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid", "target_expected_revision" integer, "target_payload" "jsonb", "target_intent" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  w uuid := target_workspace_id;
  me app_private.actor_state;
  stored public.announcements;
  item public.announcements;
  shown text := 'new';
  n jsonb;
  author uuid;
  reason text;
  found jsonb;
  impact jsonb;
  offered jsonb := '[]'::jsonb;
  back jsonb := '[]'::jsonb;
  told integer := 0;
  reached uuid[] := '{}';
  content_changed boolean := true;
  reset boolean := false;
  acked uuid[] := '{}';
  earlier uuid[] := '{}';
  touched uuid[] := '{}';
  notified uuid[] := '{}';
  history_action text;
begin
  perform app_private.authorize(actor_user_id, w, 'announcement.read');
  if target_intent is null or target_intent not in ('draft', 'schedule', 'publish', 'save')
     or jsonb_typeof(coalesce(target_payload -> 'bring_back', '[]'::jsonb)) <> 'array'
     or exists (select 1 from jsonb_array_elements(coalesce(target_payload -> 'bring_back', '[]'::jsonb)) x
                where jsonb_typeof(x) <> 'string'
                   or x #>> '{}' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
    raise exception 'valid announcement intent required' using errcode = '22023', hint = 'announcement.invalid';
  end if;
  -- S4 and the shifts: one record at a time, then the Schedule's own lock.
  perform pg_advisory_xact_lock(hashtextextended(w::text, 931));
  if target_intent <> 'draft' then
    perform public.availability_lock_workspace(w);
  end if;
  perform app_private.announcement_release(w);
  me := app_private.actor(actor_user_id, w);

  if target_announcement_id is not null then
    select * into stored from public.announcements where id = target_announcement_id and workspace_id = w for update;
    if stored.id is null or not app_private.announcement_visible(me, stored) then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'announcement.write';
    end if;
    reason := app_private.announcement_reason(me, app_private.announcement_places(stored.id), stored.created_by,
      app_private.announcement_dates(stored));
    if reason is not null then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'announcement.write';
    end if;
    if stored.revision is distinct from target_expected_revision then
      raise exception 'This post changed since you opened it.' using errcode = 'PT409', hint = 'announcement.changed';
    end if;
    shown := app_private.announcement_display_status(stored);
    if shown in ('past', 'archived') then
      raise exception 'This post can''t change anymore.' using errcode = 'PT409', hint = 'announcement.read_only';
    end if;
  end if;
  if not ((target_intent = 'save' and shown = 'published')
          or (target_intent <> 'save' and shown in ('new', 'draft', 'scheduled', 'publish_failed', 'unpublished'))) then
    raise exception 'This post changed since you opened it.' using errcode = 'PT409', hint = 'announcement.changed';
  end if;

  author := coalesce(stored.created_by, actor_user_id);
  n := app_private.announcement_proposal(w, stored, coalesce(target_payload, '{}'::jsonb), author);
  perform app_private.announcement_authorize(me, n, author);
  found := app_private.announcement_problems(w, stored, n, target_intent);
  if jsonb_array_length(found) > 0 then
    raise exception '%', found -> 0 ->> 'message'
      using errcode = '22023', hint = 'announcement.' || (found -> 0 ->> 'code'), detail = found -> 0 ->> 'field';
  end if;

  if target_intent in ('publish', 'save') then
    impact := app_private.announcement_impact(w, stored.id, (n ->> 'starts_on')::date, (n ->> 'ends_on')::date,
      n -> 'locations', n -> 'choices', stored.choices_saved_at);
    if (jsonb_array_length(impact -> 'shifts') > 0 or jsonb_array_length(impact -> 'quiet') > 0)
       and (target_payload ->> 'fingerprint') is distinct from (impact ->> 'fingerprint') then
      raise exception 'The shifts on these days changed. Review the Shifts tab again.'
        using errcode = 'PT409', hint = 'announcement.shifts_changed';
    end if;
  end if;
  if target_intent = 'save' then
    offered := app_private.announcement_back_rows(stored, (n ->> 'starts_on')::date, (n ->> 'ends_on')::date, n -> 'locations');
  end if;

  if stored.id is null then
    insert into public.announcements (workspace_id, title, body, time_zone, created_by, updated_by)
    values (w, n ->> 'title', n ->> 'body', n ->> 'time_zone', actor_user_id, actor_user_id)
    returning * into item;
    insert into public.announcement_changes (workspace_id, announcement_id, actor_user_id, action)
    values (w, item.id, actor_user_id, 'created');
  else
    item := stored;
    -- K4: what it says (its text, its days, what a day does at a location it
    -- already had) is content; a location or a person added or taken off is
    -- only who gets it.
    content_changed := (stored.title, stored.body, stored.category::text, stored.category_other, stored.starts_on,
        stored.ends_on, stored.event_from, stored.event_until, stored.recurrence)
      is distinct from (n ->> 'title', n ->> 'body', n ->> 'category', n ->> 'category_other', (n ->> 'starts_on')::date,
        (n ->> 'ends_on')::date, (n ->> 'event_from')::time, (n ->> 'event_until')::time, n ->> 'recurrence')
      or exists (
        select 1 from jsonb_array_elements(app_private.announcement_rows(stored.id)) was
        join jsonb_array_elements(n -> 'locations') now_row on now_row ->> 'location_id' = was ->> 'location_id'
        where (was ->> 'day', was ->> 'opens', was ->> 'closes')
          is distinct from (now_row ->> 'day', now_row ->> 'opens', now_row ->> 'closes'));
  end if;

  update public.announcements
  set title = n ->> 'title', body = n ->> 'body',
      category = (n ->> 'category')::public.announcement_category, category_other = n ->> 'category_other',
      starts_on = (n ->> 'starts_on')::date, ends_on = (n ->> 'ends_on')::date,
      event_from = (n ->> 'event_from')::time, event_until = (n ->> 'event_until')::time,
      recurrence = n ->> 'recurrence',
      on_important_dates = (n ->> 'on_important_dates')::boolean, on_calendar = (n ->> 'on_calendar')::boolean,
      on_schedule = (n ->> 'on_schedule')::boolean, ask_ack = (n ->> 'ask_ack')::boolean,
      time_zone = n ->> 'time_zone',
      publish_at = case target_intent when 'publish' then now() when 'save' then item.publish_at
                                      else (n ->> 'publish_at')::timestamptz end,
      status = case target_intent when 'draft' then 'draft' when 'schedule' then 'scheduled'
                                  else 'published' end::public.announcement_status,
      scheduled_by = case target_intent when 'schedule' then actor_user_id when 'draft' then null else item.scheduled_by end,
      published_by = case when target_intent = 'publish' then actor_user_id else item.published_by end,
      published_at = case when target_intent = 'publish' then now() else item.published_at end,
      unpublished_at = case when target_intent = 'publish' then null else item.unpublished_at end,
      shift_choices = n -> 'choices',
      choices_saved_at = case when target_intent = 'draft' then null else now() end,
      release_failed_at = null, release_error = null,
      content_revision = item.content_revision + case when content_changed and stored.id is not null then 1 else 0 end,
      revision = item.revision + case when stored.id is null then 0 else 1 end,
      updated_by = actor_user_id, updated_at = now()
  where id = item.id
  returning * into item;

  delete from public.announcement_locations where announcement_id = item.id;
  insert into public.announcement_locations (workspace_id, announcement_id, location_id, day, opens, closes)
  select w, item.id, (r ->> 'location_id')::uuid, r ->> 'day', (r ->> 'opens')::time, (r ->> 'closes')::time
  from jsonb_array_elements(n -> 'locations') r;
  delete from public.announcement_people where announcement_id = item.id;
  insert into public.announcement_people (workspace_id, announcement_id, user_id)
  select w, item.id, x::uuid from jsonb_array_elements_text(n -> 'people') x;

  if target_intent = 'save' then
    back := app_private.announcement_bring_back(actor_user_id, item,
      array(select x::uuid from jsonb_array_elements_text(coalesce(target_payload -> 'bring_back', '[]'::jsonb)) x), offered);
  end if;
  if target_intent in ('publish', 'save') then
    earlier := array(select change.id from public.announcement_shift_changes change where change.announcement_id = item.id);
    told := app_private.announcement_apply(actor_user_id, item, impact);
    reached := app_private.announcement_recipients(item);
    -- Whoever's shift this write changed hears it, whatever else holds.
    touched := array(select distinct person.user_id from public.announcement_shift_changes change
                     join public.employee_profiles person on person.id = change.employee_id
                     where change.announcement_id = item.id and not change.silent and change.brought_back_at is null
                       and not change.id = any (earlier) and person.user_id is not null);
    -- K27: acknowledgements stay unless the writer asks for them again; then
    -- everyone it reaches answers anew.
    if item.ask_ack and coalesce((target_payload ->> 'reset_acknowledgements')::boolean, false)
       and exists (select 1 from public.announcement_acknowledgements ack where ack.announcement_id = item.id) then
      update public.announcements
      set acknowledged_before = array(select distinct who from unnest(acknowledged_before || array(
            select ack.user_id from public.announcement_acknowledgements ack where ack.announcement_id = item.id)) who)
      where id = item.id returning * into item;
      delete from public.announcement_acknowledgements where announcement_id = item.id;
      reset := true;
    end if;
    acked := array(select ack.user_id from public.announcement_acknowledgements ack where ack.announcement_id = item.id);
  end if;

  if target_intent = 'publish' then
    -- K4 (3), K27: brought out again with its acknowledgements kept, it is for
    -- whoever hasn't acknowledged; the first time, for everyone.
    notified := array(select who from unnest(reached) who where not who = any (acked) or who = any (touched));
  elsif target_intent = 'save' then
    -- K4: new people; a change in what it says for whoever hasn't acknowledged
    -- it (everyone, once asked again, K27); a changed or returned shift for its person.
    notified := array(select who from unnest(reached) who
                      where not who = any (item.delivered_to) or who = any (touched)
                         or ((content_changed or reset) and not who = any (acked))
                         or who = any (array(select (x ->> 'employee_user_id')::uuid from jsonb_array_elements(back) x
                                             where not coalesce((x ->> 'silent')::boolean, false))));
  end if;
  if target_intent = 'publish' then
    perform app_private.announcement_tell(actor_user_id, item, 'published', notified);
  elsif target_intent = 'save' then
    -- People it newly reaches hear it is out, unless they acknowledged it already (taken off, put back); a
    -- change in what it says, whoever it reached before and has not acknowledged it. A changed or returned shift is the Schedule's notice (schedule_tell_closed_day).
    perform app_private.announcement_tell(actor_user_id, item, 'published',
      array(select who from unnest(reached) who where not who = any (item.delivered_to) and not who = any (acked)));
    if content_changed or reset then
      perform app_private.announcement_tell(actor_user_id, item, 'updated',
        array(select who from unnest(reached) who where who = any (item.delivered_to) and not who = any (acked)));
    end if;
  end if;
  if target_intent in ('publish', 'save') then
    update public.announcements set delivered_to = reached where id = item.id returning * into item;
  end if;
  -- Scheduled, published or put back to draft: a failed schedule's card is done.
  if stored.release_failed_at is not null then
    perform app_private.notification_resolve(w, 'announcement', item.id, 'closed', actor_user_id);
  end if;

  history_action := case
    when target_intent = 'draft' and stored.status = 'scheduled' then 'unscheduled'
    when target_intent = 'draft' then 'saved'
    when target_intent = 'schedule' then 'scheduled'
    when target_intent = 'publish' then 'published'
    else 'updated' end;
  insert into public.announcement_changes (workspace_id, announcement_id, actor_user_id, action, detail)
  values (w, item.id, actor_user_id, history_action, jsonb_strip_nulls(jsonb_build_object(
    'publish_at', case when target_intent = 'schedule' then item.publish_at end,
    'rescheduled', case when target_intent = 'schedule' and stored.status = 'scheduled' then true end,
    'shift_changes', nullif(told, 0),
    'brought_back', nullif(jsonb_array_length(back), 0),
    'told', case when target_intent in ('publish', 'save') then cardinality(notified) end,
    'acknowledgements_reset', case when reset then true end)));
  insert into public.audit_events (workspace_id, actor_user_id, action, target_type, target_id, metadata)
  values (w, actor_user_id, 'announcement.' || history_action, 'announcement', item.id::text,
    jsonb_build_object('content_changed', content_changed, 'shift_changes', told, 'brought_back', jsonb_array_length(back)));

  return jsonb_build_object('status', item.status, 'display_status', app_private.announcement_display_status(item),
    'announcement_id', item.id, 'revision', item.revision, 'recipient_count', cardinality(item.delivered_to),
    'shift_changes', told, 'brought_back', jsonb_array_length(back));
end;
$_$;


ALTER FUNCTION "public"."save_announcement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid", "target_expected_revision" integer, "target_payload" "jsonb", "target_intent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_document_type_draft_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "document_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  return public.save_document_type_lifecycle_service(actor_user_id, target_workspace_id, target_document_type_id, expected_revision, document_payload);
end;
$$;


ALTER FUNCTION "public"."save_document_type_draft_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "document_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_document_type_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "document_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare settings jsonb:=document_payload->'lifecycle_settings'; saved_id uuid; actual_revision integer; period integer;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,52001));
 settings:=jsonb_set(settings,'{assignment_scope}','"all_active"'::jsonb); if target_document_type_id is null and jsonb_array_length(coalesce(settings->'target'->'employee_ids','[]'))>0 then raise exception 'Individual document assignment is not supported' using errcode='22023'; end if; if target_document_type_id is not null and exists(select 1 from public.document_types d where d.id=target_document_type_id and d.workspace_id=target_workspace_id and coalesce(d.lifecycle_settings->'target'->'employee_ids','[]') is distinct from coalesce(settings->'target'->'employee_ids','[]')) then raise exception 'Legacy named targets must be preserved' using errcode='22023'; end if; if settings is null or settings->>'mode' is null or settings->>'mode' not in ('optional','required','conditional')
  or settings->>'assignment_scope' is null or settings->>'assignment_scope' not in ('future_onboarding','all_active')
  or jsonb_typeof(settings->'target') is distinct from 'object'
 then raise exception 'valid document lifecycle settings required' using errcode='22023'; end if;
 perform app_private.assert_document_definition_target(actor_user_id,target_workspace_id,settings->'target'); period:=(settings->>'period_days')::integer;
 if (period is not null and period not between 1 and 3650)
  or (settings->>'mode'='conditional' and period is null)
  or (coalesce((settings->>'suspend_on_overdue')::boolean,false) and (settings->>'mode'='optional' or period is null))
 then raise exception 'valid document period required' using errcode='22023'; end if;
 if target_document_type_id is not null then
  select lifecycle_revision into actual_revision from public.document_types where id=target_document_type_id and workspace_id=target_workspace_id for update;
  if actual_revision is null then raise exception 'document type unavailable' using errcode='P0002'; end if;
  if actual_revision is distinct from expected_revision then raise exception 'document type changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 end if;
 saved_id:=public.save_document_type_service(actor_user_id,target_workspace_id,target_document_type_id,
  document_payload->>'title',coalesce(document_payload->>'description',''),settings->>'mode'='required',
  (document_payload->>'requires_review')::boolean,array(select jsonb_array_elements_text(document_payload->'accepted_formats')),
  (document_payload->>'tracks_expiry')::boolean,(document_payload->>'expiry_warning_days')::integer,'track_only');
 update public.document_types set lifecycle_settings=settings,lifecycle_revision=case when target_document_type_id is null then 1 else expected_revision+1 end where id=saved_id;
 return saved_id;
end;
$$;


ALTER FUNCTION "public"."save_document_type_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "document_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_document_type_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "document_title" "text", "document_description" "text", "is_required_at_onboarding" boolean, "is_review_required" boolean, "document_formats" "text"[], "should_track_expiry" boolean, "warning_days" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  return public.save_document_type_service(actor_user_id, target_workspace_id, target_document_type_id, document_title,
    document_description, is_required_at_onboarding, is_review_required, document_formats, should_track_expiry, warning_days, 'track_only');
end;
$$;


ALTER FUNCTION "public"."save_document_type_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "document_title" "text", "document_description" "text", "is_required_at_onboarding" boolean, "is_review_required" boolean, "document_formats" "text"[], "should_track_expiry" boolean, "warning_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_document_type_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "document_title" "text", "document_description" "text", "is_required_at_onboarding" boolean, "is_review_required" boolean, "document_formats" "text"[], "should_track_expiry" boolean, "warning_days" integer, "schedule_impact" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  saved_id uuid;
  normalized_formats text[];
  normalized_schedule_impact public.document_expiry_schedule_impact;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
 perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,52001));
  if char_length(btrim(document_title)) not between 1 and 80 then
    raise exception 'document title must be between 1 and 80 characters' using errcode = '22023';
  end if;
  if char_length(coalesce(document_description, '')) > 240 then
    raise exception 'document description must be 240 characters or fewer' using errcode = '22023';
  end if;
  if warning_days not between 1 and 365 then
    raise exception 'expiry warning days must be between 1 and 365' using errcode = '22023';
  end if;
  if coalesce(schedule_impact, 'track_only') not in ('track_only', 'warn', 'block') then
    raise exception 'invalid expiry schedule impact' using errcode = '22023';
  end if;
  normalized_schedule_impact := coalesce(schedule_impact, 'track_only')::public.document_expiry_schedule_impact;
  if not coalesce(should_track_expiry, false) then
    normalized_schedule_impact := 'track_only';
  end if;
  if normalized_schedule_impact = 'block' and not coalesce(is_required_at_onboarding, false) then
    raise exception 'only required documents can create hard schedule conflicts' using errcode = '22023';
  end if;

  select coalesce(array_agg(distinct lower(format) order by lower(format)), '{}'::text[])
  into normalized_formats
  from unnest(coalesce(document_formats, '{}'::text[])) format;

  if cardinality(normalized_formats) = 0
    or not normalized_formats <@ array['pdf', 'jpeg', 'png', 'webp']::text[] then
    raise exception 'document formats contain unsupported values' using errcode = '22023';
  end if;

  if target_document_type_id is null then
    insert into public.document_types (
      workspace_id,
      title,
      description,
      required_at_onboarding,
      requires_review,
      accepted_formats,
      tracks_expiry,
      expiry_warning_days,
      expiry_schedule_impact,
      sort_order,
      created_by
    ) values (
      target_workspace_id,
      btrim(document_title),
      btrim(coalesce(document_description, '')),
      is_required_at_onboarding,
      is_review_required,
      normalized_formats,
      should_track_expiry,
      warning_days,
      normalized_schedule_impact,
      coalesce((
        select max(sort_order) + 1 from public.document_types
        where workspace_id = target_workspace_id and archived_at is null
      ), 0),
      actor_id
    ) returning id into saved_id;
  else
    update public.document_types
    set title = btrim(document_title),
        description = btrim(coalesce(document_description, '')),
        required_at_onboarding = is_required_at_onboarding,
        requires_review = is_review_required,
        accepted_formats = normalized_formats,
        tracks_expiry = should_track_expiry,
        expiry_warning_days = warning_days,
        expiry_schedule_impact = normalized_schedule_impact,
        updated_at = now()
    where id = target_document_type_id
      and workspace_id = target_workspace_id
    returning id into saved_id;

    if saved_id is null then
      raise exception 'document type not found' using errcode = 'P0002';
    end if;
  end if;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id,
    actor_id,
    case when target_document_type_id is null then 'document_type.created' else 'document_type.updated' end,
    'document_type',
    saved_id::text,
    jsonb_build_object(
      'title', btrim(document_title),
      'expiry_schedule_impact', normalized_schedule_impact
    )
  );

  return saved_id;
end;
$$;


ALTER FUNCTION "public"."save_document_type_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "document_title" "text", "document_description" "text", "is_required_at_onboarding" boolean, "is_review_required" boolean, "document_formats" "text"[], "should_track_expiry" boolean, "warning_days" integer, "schedule_impact" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_employee_document_draft_file_service"("actor_user_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "storage_object_path" "text", "upload_filename" "text", "upload_media_type" "text", "upload_size_bytes" bigint) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; s public.employee_document_submissions%rowtype; file_id uuid; next_version integer; format text;
begin
 perform app_private.authorize(actor_user_id,(select q.workspace_id from public.employee_onboarding_requirements q where q.id=target_requirement_id),'documents.self',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id));
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and kind='document' for update;
 if r.id is null or r.lifecycle_user_id is distinct from actor_user_id or not app_private.document_actor_can_read(actor_user_id,r.workspace_id,r.employee_id,r.lifecycle_user_id)
 then raise exception 'document unavailable' using errcode='P0002'; end if;
 perform app_private.assert_document_published(r);
 if r.lifecycle_revision<>expected_revision then raise exception 'document changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 if r.lifecycle_closed_at is not null or (r.lifecycle_exempt and not r.owner_excused) or r.status='superseded' then raise exception 'document obligation is closed' using errcode='22023'; end if;
 format:=case upload_media_type when 'application/pdf' then 'pdf' when 'image/jpeg' then 'jpeg' when 'image/png' then 'png' when 'image/webp' then 'webp' end;
 if format is null or not coalesce(r.source_snapshot->'accepted_formats' ? format,false)
  or upload_size_bytes is null or upload_size_bytes not between 1 and 10485760
  or nullif(btrim(upload_filename),'') is null or char_length(upload_filename)>240
  or not app_private.is_employee_onboarding_document_path(storage_object_path,r.workspace_id,r.employee_id,r.id)
 then raise exception 'invalid private document upload' using errcode='22023'; end if;
 select * into s from public.employee_document_submissions where requirement_id=r.id and state='draft' for update;
 if s.id is null then
  select coalesce(max(version),0)+1 into next_version from public.employee_document_submissions where requirement_id=r.id;
  insert into public.employee_document_submissions(workspace_id,employee_id,requirement_id,user_id,version,state)
   values(r.workspace_id,r.employee_id,r.id,actor_user_id,next_version,'draft') returning * into s;
 end if;
 select coalesce(max(version_number),0)+1 into next_version from public.employee_documents where requirement_id=r.id;
 insert into public.employee_documents(workspace_id,employee_id,requirement_id,version_number,object_path,original_filename,media_type,size_bytes,review_status,uploaded_by)
 values(r.workspace_id,r.employee_id,r.id,next_version,storage_object_path,upload_filename,upload_media_type,upload_size_bytes,'superseded',actor_user_id) returning id into file_id;
 insert into public.employee_document_submission_files(submission_id,file_id,requirement_id,workspace_id,employee_id) values(s.id,file_id,r.id,r.workspace_id,r.employee_id);
 update public.employee_onboarding_requirements set lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning lifecycle_revision into expected_revision;
 perform app_private.document_audit(r,actor_user_id,'document.draft_file_added',jsonb_build_object('submission_id',s.id,'file_id',file_id,'revision',expected_revision));
 return expected_revision;
end;
$$;


ALTER FUNCTION "public"."save_employee_document_draft_file_service"("actor_user_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "storage_object_path" "text", "upload_filename" "text", "upload_media_type" "text", "upload_size_bytes" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_employee_onboarding_profile_service"("target_user_id" "uuid", "profile_payload" "jsonb", "expected_revision" integer, "target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  target_case public.employee_onboarding_cases%rowtype;
  employee public.employee_profiles%rowtype;
  normalized_country_code text := nullif(upper(btrim(coalesce(profile_payload->>'country_code', ''))), '');
  normalized_birth_date text := nullif(btrim(coalesce(profile_payload->>'date_of_birth', '')), '');
  submitted_phone text := nullif(btrim(coalesce(profile_payload->>'phone', '')), '');
  emergency_email text := btrim(coalesce(profile_payload->>'emergency_contact_email', ''));
  account_phone text;
  legal_name_changed boolean;
  next_requirement_status public.employee_onboarding_requirement_status;
begin
 perform app_private.authorize(target_user_id, app_private.onboarding_self_workspace(target_user_id, target_workspace_id, true), 'onboarding.self');
  select onboarding.* into target_case from public.employee_onboarding_cases onboarding
  where onboarding.id = app_private.employee_onboarding_case_id(target_user_id, target_workspace_id)
  for update;
  if target_case.id is null then raise exception 'onboarding unavailable' using errcode = 'P0002'; end if;
  if target_case.revision <> expected_revision then raise exception 'onboarding changed; refresh required' using errcode = 'PT409', hint = 'onboarding.changed'; end if;
  if target_case.status in ('submitted', 'approved', 'cancelled') then raise exception 'onboarding cannot be edited' using errcode = '22023'; end if;

  select * into employee
  from public.employee_profiles
  where id = target_case.employee_id
  for update;

  select profile.phone_e164 into account_phone
  from public.user_profiles profile
  where profile.user_id = target_user_id;

  if coalesce(profile_payload->>'legal_first_name', '') = ''
    or coalesce(profile_payload->>'legal_last_name', '') = ''
    or coalesce(account_phone, submitted_phone) is null
    or coalesce(profile_payload->>'emergency_contact_name', '') = ''
    or coalesce(profile_payload->>'emergency_contact_relationship', '') = ''
    or coalesce(profile_payload->>'emergency_contact_phone', '') = ''
    or (emergency_email <> '' and emergency_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$')
    or (normalized_country_code is not null and normalized_country_code !~ '^[A-Z]{2}$')
    or (normalized_birth_date is not null and normalized_birth_date !~ '^\d{4}-\d{2}-\d{2}$') then
    raise exception 'complete private profile required' using errcode = '22023';
  end if;

  -- TEL-2: the number is nobody else's in this workspace, and the
  -- emergency contact is somebody else. Two people saving one number at once
  -- in one workspace take turns, so the second sees the first.
  perform pg_advisory_xact_lock(hashtext(
    'onboarding-phone:' || target_case.workspace_id::text || ':'
    || coalesce(account_phone, app_private.account_phone_e164(submitted_phone), '')
  ));
  if app_private.phone_used_in_workspace(
    target_case.workspace_id,
    coalesce(account_phone, app_private.account_phone_e164(submitted_phone)),
    target_case.employee_id
  ) then
    raise exception 'phone used by someone else in this workspace'
      using errcode = '23505', hint = 'onboarding.phone_in_use';
  end if;
  if btrim(profile_payload->>'emergency_contact_phone')
    = coalesce(account_phone, app_private.account_phone_e164(submitted_phone)) then
    raise exception 'emergency contact phone is the person''s own'
      using errcode = '23514', hint = 'onboarding.emergency_is_own_phone';
  end if;

  -- The account is the phone's only source. An empty account takes the number
  -- typed here; a filled one keeps its own. The record copies the account.
  account_phone := app_private.adopt_account_phone(
    target_user_id, submitted_phone, btrim(employee.first_name || ' ' || employee.last_name)
  );

  legal_name_changed :=
    lower(btrim(profile_payload->>'legal_first_name')) is distinct from lower(btrim(employee.first_name))
    or lower(btrim(profile_payload->>'legal_last_name')) is distinct from lower(btrim(employee.last_name));
  next_requirement_status := case
    when legal_name_changed then 'awaiting_review'::public.employee_onboarding_requirement_status
    else 'completed'::public.employee_onboarding_requirement_status
  end;

  insert into public.employee_private_profiles (
    employee_id, workspace_id, legal_first_name, legal_middle_name, legal_last_name, preferred_name,
    phone, street_address, city, region, postal_code, country_code, date_of_birth,
    emergency_contact_name, emergency_contact_relationship, emergency_contact_phone,
    emergency_contact_email, share_phone_with_teammates, share_email_with_teammates
  ) values (
    target_case.employee_id, target_case.workspace_id,
    btrim(profile_payload->>'legal_first_name'),
    left(btrim(coalesce(profile_payload->>'legal_middle_name', '')), 80),
    btrim(profile_payload->>'legal_last_name'),
    left(btrim(coalesce(profile_payload->>'preferred_name', '')), 80),
    account_phone,
    nullif(btrim(coalesce(profile_payload->>'street_address', '')), ''),
    nullif(btrim(coalesce(profile_payload->>'city', '')), ''),
    nullif(btrim(coalesce(profile_payload->>'region', '')), ''),
    nullif(btrim(coalesce(profile_payload->>'postal_code', '')), ''),
    normalized_country_code,
    normalized_birth_date::date,
    btrim(profile_payload->>'emergency_contact_name'),
    btrim(profile_payload->>'emergency_contact_relationship'),
    btrim(profile_payload->>'emergency_contact_phone'),
    emergency_email,
    coalesce((profile_payload->>'share_phone_with_teammates')::boolean, false),
    coalesce((profile_payload->>'share_email_with_teammates')::boolean, false)
  ) on conflict (employee_id) do update set
    legal_first_name = excluded.legal_first_name,
    legal_middle_name = excluded.legal_middle_name,
    legal_last_name = excluded.legal_last_name,
    -- It was forced empty while the field was closed. The person answers it
    -- now, and leaving it blank is a valid answer.
    preferred_name = excluded.preferred_name,
    -- The account's number, same as the trigger writes; never the form's.
    phone = excluded.phone,
    street_address = excluded.street_address,
    city = excluded.city,
    region = excluded.region,
    postal_code = excluded.postal_code,
    country_code = excluded.country_code,
    date_of_birth = excluded.date_of_birth,
    emergency_contact_name = excluded.emergency_contact_name,
    emergency_contact_relationship = excluded.emergency_contact_relationship,
    emergency_contact_phone = excluded.emergency_contact_phone,
    emergency_contact_email = excluded.emergency_contact_email,
    share_phone_with_teammates = excluded.share_phone_with_teammates,
    share_email_with_teammates = excluded.share_email_with_teammates,
    updated_at = now();

  update public.employee_onboarding_requirements set
    status = next_requirement_status,
    requires_review = legal_name_changed,
    rejection_reason = null,
    reviewed_by = null,
    reviewed_at = null,
    completed_at = case when legal_name_changed then null else now() end,
    updated_at = now()
  where case_id = target_case.id and kind = 'profile'::public.employee_onboarding_requirement_kind;

  update public.employee_onboarding_cases set status = 'in_progress'::public.employee_onboarding_case_status, revision = revision + 1,
    updated_at = now() where id = target_case.id returning revision into expected_revision;
  insert into public.onboarding_events (workspace_id, employee_id, case_id, actor_user_id, action, target_type, target_id, metadata)
  values (target_case.workspace_id, target_case.employee_id, target_case.id, target_user_id,
    'onboarding.profile_saved', 'onboarding_case', target_case.id::text,
    jsonb_build_object('legal_name_review_required', legal_name_changed));
  return expected_revision;
end;
$_$;


ALTER FUNCTION "public"."save_employee_onboarding_profile_service"("target_user_id" "uuid", "profile_payload" "jsonb", "expected_revision" integer, "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_employee_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "employee_first_name" "text", "employee_middle_name" "text", "employee_last_name" "text", "employee_preferred_name" "text", "employee_invitation_email" "text", "employee_start_date" "date", "employee_internal_note" "text", "location_ids" "uuid"[], "primary_location_id" "uuid", "job_ids" "uuid"[], "primary_job_id" "uuid", "employee_is_remote" boolean, "employee_is_excluded_from_schedule" boolean, "expected_revision" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  saved_id uuid := target_employee_id;
  reachable uuid[];
  kept uuid[];
  current_revision integer;
  next_code bigint;
begin
  -- A new record is asked where it will work (a manager only where they
  -- manage, never nowhere); an existing one, whose it is.
  if target_employee_id is null then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.create',
      coalesce(location_ids, '{}'::uuid[]));
  else
    perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.save',
      target_person => target_employee_id);
  end if;

  -- An assignment at a location that is not live (archived) is left as it is,
  -- sent or not: that location counts nowhere, and the assignment is back when
  -- the archive is undone (G8a, KK-13). Only live locations are added, kept or
  -- taken away here; the primary mark still follows primary_location_id.
  kept := coalesce((
    select array_agg(existing.location_id)
    from public.employee_location_assignments existing
    join public.locations location on location.id = existing.location_id
    where existing.employee_id = target_employee_id and existing.ended_at is null
      and not app_private.location_is_live(location)
  ), '{}');

  if char_length(btrim(employee_first_name)) not between 1 and 80 or char_length(btrim(employee_last_name)) not between 1 and 80 then
    raise exception 'employee first and last name are required' using errcode = '22023';
  end if;
  -- DAVET-ERISIM: everybody needs a location, a primary location, a job and a primary job, Remote and
  -- excluded from Schedule too; any job can be the primary one, under Management too (EMP-001 S2). The owner's
  -- record needs none of it: the owner may work anywhere.
  if not app_private.employee_record_is_workspace_owner(target_workspace_id, target_employee_id) then
    if cardinality(coalesce(location_ids, '{}'::uuid[]) || kept) = 0 or primary_location_id is null then
      raise exception 'employee requires a location and a job'
        using errcode = '22023', hint = 'employee.location_required';
    end if;
    if cardinality(coalesce(job_ids, '{}'::uuid[])) = 0 then
      raise exception 'employee requires a location and a job'
        using errcode = '22023', hint = 'employee.job_required';
    end if;
    if primary_job_id is null then
      raise exception 'employee requires a primary job'
        using errcode = '22023', hint = 'employee.primary_job_required';
    end if;
  end if;
  if primary_location_id is not null and not primary_location_id = any(coalesce(location_ids, '{}'::uuid[]) || kept) then
    raise exception 'primary location must be assigned' using errcode = '22023';
  end if;
  if primary_job_id is not null and not primary_job_id = any(coalesce(job_ids, '{}'::uuid[])) then
    raise exception 'primary job must be assigned' using errcode = '22023';
  end if;

  -- A location added or taken away is one the actor reaches; an unknown or
  -- archived one reads the same.
  reachable := app_private.scope_set(actor_user_id, target_workspace_id, 'employee.save');
  if exists (
      select 1 from unnest(coalesce(location_ids, '{}'::uuid[])) selected(location_id)
      left join public.locations location
        on location.id = selected.location_id and location.workspace_id = target_workspace_id and location.archived_at is null
      where not selected.location_id = any (kept)
        and (location.id is null
         or (not selected.location_id = any (reachable) and not exists (
           select 1 from public.employee_location_assignments existing
           where existing.employee_id = target_employee_id and existing.location_id = selected.location_id
             and existing.ended_at is null)))
    )
    or exists (
      select 1 from public.employee_location_assignments existing
      where existing.employee_id = target_employee_id and existing.ended_at is null
        and not existing.location_id = any (coalesce(location_ids, '{}'::uuid[]) || kept)
        and not existing.location_id = any (reachable)
    ) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'employee.save';
  end if;
  if exists (select 1 from unnest(coalesce(job_ids, '{}'::uuid[])) selected(job_id) left join public.jobs j on j.id = selected.job_id and j.workspace_id = target_workspace_id and j.archived_at is null where j.id is null) then
    raise exception 'invalid employee job' using errcode = '22023';
  end if;

  if saved_id is null then
    insert into public.workspace_employee_counters (workspace_id, next_value)
    values (target_workspace_id, 1)
    on conflict (workspace_id) do nothing;

    update public.workspace_employee_counters counter
    set next_value = greatest(
      counter.next_value,
      coalesce((
        select max(substring(employee.employee_code from 3)::bigint) + 1
        from public.employee_profiles employee
        where employee.workspace_id = target_workspace_id
          and employee.employee_code ~ '^E-[0-9]{4,}$'
      ), 1)
    ) + 1
    where counter.workspace_id = target_workspace_id
    returning counter.next_value - 1 into next_code;

    insert into public.employee_profiles (
      workspace_id, employee_code, first_name, middle_name, last_name, preferred_name,
      invitation_email, start_date, internal_note, is_remote,
      is_excluded_from_schedule, created_by
    )
    values (
      target_workspace_id, 'E-' || lpad(next_code::text, 4, '0'),
      btrim(employee_first_name), left(btrim(coalesce(employee_middle_name, '')), 80), btrim(employee_last_name),
      '',
      nullif(lower(btrim(employee_invitation_email)), ''),
      employee_start_date, btrim(coalesce(employee_internal_note, '')),
      coalesce(employee_is_remote, false),
      coalesce(employee_is_excluded_from_schedule, false),
      actor_user_id
    )
    returning id into saved_id;
    insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
    values (target_workspace_id, saved_id, actor_user_id, 'employee.created', 'Employee record created');
  else
    select revision into current_revision from public.employee_profiles
    where id = saved_id and workspace_id = target_workspace_id and archived_at is null
    for update;
    if current_revision is null then raise exception 'employee not found' using errcode = 'P0002'; end if;
    if expected_revision is null or expected_revision <> current_revision then raise exception 'employee revision conflict' using errcode = 'PT409', hint = 'employee.revision_conflict'; end if;
    -- The preferred name is not the drawer's: it changes by request and answer.
    update public.employee_profiles set
      first_name = btrim(employee_first_name),
      middle_name = left(btrim(coalesce(employee_middle_name, '')), 80),
      last_name = btrim(employee_last_name),
      invitation_email = nullif(lower(btrim(employee_invitation_email)), ''),
      start_date = employee_start_date,
      internal_note = btrim(coalesce(employee_internal_note, '')),
      is_remote = coalesce(employee_is_remote, false),
      is_excluded_from_schedule = coalesce(employee_is_excluded_from_schedule, false),
      revision = revision + 1,
      updated_at = now()
    where id = saved_id;
    insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
    values (target_workspace_id, saved_id, actor_user_id, 'employee.updated', 'Employee profile and assignments updated');
  end if;

  -- Only what changed is written (BL-218): a kept assignment keeps its row, so
  -- the rules on the assignment tables (the owner stays at every location, the
  -- Owner job stays the owner's) judge a real removal, not every save. The
  -- primary flag is cleared before it is set, one row at a time for the index.
  update public.employee_location_assignments set ended_at = now(), is_primary = false
  where employee_id = saved_id and ended_at is null
    and not location_id = any(coalesce(location_ids, '{}'::uuid[]) || kept);
  update public.employee_location_assignments set is_primary = false
  where employee_id = saved_id and ended_at is null and is_primary
    and location_id is distinct from primary_location_id;
  insert into public.employee_location_assignments (workspace_id, employee_id, location_id, is_primary, created_by)
  select distinct target_workspace_id, saved_id, selected.location_id, false, actor_user_id
  from unnest(coalesce(location_ids, '{}'::uuid[])) selected(location_id)
  where not exists (select 1 from public.employee_location_assignments existing
    where existing.employee_id = saved_id and existing.location_id = selected.location_id and existing.ended_at is null);
  update public.employee_location_assignments set is_primary = true
  where employee_id = saved_id and ended_at is null and not is_primary and location_id = primary_location_id;

  update public.employee_job_assignments set ended_at = now(), is_primary = false
  where employee_id = saved_id and ended_at is null
    and not job_id = any(coalesce(job_ids, '{}'::uuid[]));
  update public.employee_job_assignments set is_primary = false
  where employee_id = saved_id and ended_at is null and is_primary
    and job_id is distinct from primary_job_id;
  insert into public.employee_job_assignments (workspace_id, employee_id, job_id, is_primary, created_by)
  select distinct target_workspace_id, saved_id, selected.job_id, false, actor_user_id
  from unnest(coalesce(job_ids, '{}'::uuid[])) selected(job_id)
  where not exists (select 1 from public.employee_job_assignments existing
    where existing.employee_id = saved_id and existing.job_id = selected.job_id and existing.ended_at is null);
  update public.employee_job_assignments set is_primary = true
  where employee_id = saved_id and ended_at is null and not is_primary and job_id = primary_job_id;

  -- K4: a manager keeps a location to manage.
  perform app_private.keep_manager_at_a_location(target_workspace_id, saved_id);
  return saved_id;
end;
$_$;


ALTER FUNCTION "public"."save_employee_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "employee_first_name" "text", "employee_middle_name" "text", "employee_last_name" "text", "employee_preferred_name" "text", "employee_invitation_email" "text", "employee_start_date" "date", "employee_internal_note" "text", "location_ids" "uuid"[], "primary_location_id" "uuid", "job_ids" "uuid"[], "primary_job_id" "uuid", "employee_is_remote" boolean, "employee_is_excluded_from_schedule" boolean, "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_notification_preferences_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_choices" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  choice jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'notifications.write_own');
  if jsonb_typeof(target_choices) is distinct from 'array' or jsonb_array_length(target_choices) not between 1 and 50 then
    raise exception 'valid choices required' using errcode = '22023', hint = 'notifications.invalid_choice';
  end if;
  for choice in select value from jsonb_array_elements(target_choices) loop
    if jsonb_typeof(choice) is distinct from 'object'
       or jsonb_typeof(choice -> 'enabled') is null or jsonb_typeof(choice -> 'enabled') not in ('boolean', 'null')
       or jsonb_typeof(choice -> 'topic') is distinct from 'string' or jsonb_typeof(choice -> 'channel') is distinct from 'string' then
      raise exception 'valid choices required' using errcode = '22023', hint = 'notifications.invalid_choice';
    end if;
    if choice ->> 'channel' = 'sms' and not app_private.sms_channel_open() then
      raise exception 'text messages are not available' using errcode = '22023', hint = 'notifications.sms_unavailable';
    end if;
    if choice ->> 'channel' not in ('email', 'push', 'sms') then
      raise exception 'only email, push and text messages are a choice' using errcode = '22023', hint = 'notifications.invalid_channel';
    end if;
    if not exists (select 1 from public.notification_types t where t.topic_key = choice ->> 'topic' and t.level <> 'required') then
      raise exception 'this topic is not a choice' using errcode = '22023', hint = 'notifications.topic_locked';
    end if;
    if choice -> 'enabled' = 'null'::jsonb then
      delete from public.notification_preferences p
      where p.workspace_id = target_workspace_id and p.user_id = actor_user_id
        and p.topic_key = choice ->> 'topic' and p.channel = choice ->> 'channel';
    else
      insert into public.notification_preferences (workspace_id, user_id, topic_key, channel, enabled)
      values (target_workspace_id, actor_user_id, choice ->> 'topic', choice ->> 'channel', (choice ->> 'enabled')::boolean)
      on conflict (workspace_id, user_id, topic_key, channel)
      do update set enabled = excluded.enabled, updated_at = now();
    end if;
  end loop;
  return public.get_notification_preferences_service(actor_user_id, target_workspace_id);
end;
$$;


ALTER FUNCTION "public"."save_notification_preferences_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_choices" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_notification_push_subscription_service"("actor_user_id" "uuid", "target_endpoint" "text", "target_p256dh" "text", "target_auth" "text", "target_label" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  label text := nullif(btrim(coalesce(target_label, '')), '');
  saved uuid;
begin
  perform app_private.authorize(actor_user_id, null, 'account.self', null, null, actor_user_id);
  if not app_private.push_endpoint_ok(target_endpoint) then
    raise exception 'a push service''s address is required' using errcode = '22023', hint = 'notifications.push_endpoint';
  end if;
  if target_p256dh is null or target_p256dh !~ '^[A-Za-z0-9_-]{87}$' or target_auth is null or target_auth !~ '^[A-Za-z0-9_-]{22}$' then
    raise exception 'the browser''s keys are required' using errcode = '22023', hint = 'notifications.push_keys';
  end if;
  if label is not null and (char_length(label) > 120 or label ~ '[[:cntrl:]]') then
    raise exception 'a device name is up to 120 characters' using errcode = '22023', hint = 'notifications.push_label';
  end if;

  insert into public.notification_push_subscriptions (user_id, endpoint, p256dh, auth_secret, device_label, last_used_at)
  values (actor_user_id, target_endpoint, target_p256dh, target_auth, label, now())
  on conflict (endpoint) do update set user_id = excluded.user_id, p256dh = excluded.p256dh, auth_secret = excluded.auth_secret,
    device_label = excluded.device_label, last_used_at = now(), revoked_at = null, revoked_reason = null
  returning id into saved;

  -- Ten at most: the one used longest ago goes.
  update public.notification_push_subscriptions s set revoked_at = now(), revoked_reason = 'expired'
  where s.id in (
    select x.id from public.notification_push_subscriptions x
    where x.user_id = actor_user_id and x.revoked_at is null and x.id <> saved
    order by coalesce(x.last_used_at, x.created_at) desc, x.id
    offset 9);

  return jsonb_build_object('devices', (select count(*) from public.notification_push_subscriptions s
                                        where s.user_id = actor_user_id and s.revoked_at is null));
end;
$_$;


ALTER FUNCTION "public"."save_notification_push_subscription_service"("actor_user_id" "uuid", "target_endpoint" "text", "target_p256dh" "text", "target_auth" "text", "target_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_notification_workspace_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_settings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  muted text[];
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.organization.write');
  if jsonb_typeof(target_settings) is distinct from 'object'
     or jsonb_typeof(target_settings -> 'email_enabled') is distinct from 'boolean'
     or jsonb_typeof(target_settings -> 'push_enabled') is distinct from 'boolean'
     or jsonb_typeof(target_settings -> 'sms_enabled') is distinct from 'boolean'
     or jsonb_typeof(target_settings -> 'muted_types') is distinct from 'array'
     or exists (select 1 from jsonb_array_elements(target_settings -> 'muted_types') e where jsonb_typeof(e) <> 'string') then
    raise exception 'valid notification settings required' using errcode = '22023', hint = 'notifications.invalid_settings';
  end if;
  if (target_settings ->> 'sms_enabled')::boolean and not app_private.sms_channel_open() then
    raise exception 'text messages are not available' using errcode = '22023', hint = 'notifications.sms_unavailable';
  end if;
  muted := array(select distinct e from jsonb_array_elements_text(target_settings -> 'muted_types') e);
  if exists (select 1 from unnest(muted) k
             where not exists (select 1 from public.notification_types t where t.key = k and t.level = 'optional')) then
    raise exception 'only an optional type can be turned off' using errcode = '22023', hint = 'notifications.not_optional';
  end if;

  insert into public.notification_workspace_settings (workspace_id, email_enabled, push_enabled, sms_enabled, updated_by, updated_at)
  values (target_workspace_id, (target_settings ->> 'email_enabled')::boolean, (target_settings ->> 'push_enabled')::boolean,
          (target_settings ->> 'sms_enabled')::boolean, actor_user_id, now())
  on conflict (workspace_id) do update set
    email_enabled = excluded.email_enabled, push_enabled = excluded.push_enabled, sms_enabled = excluded.sms_enabled,
    updated_by = excluded.updated_by, updated_at = now();
  delete from public.notification_workspace_muted_types m
  where m.workspace_id = target_workspace_id and not m.type_key = any(muted);
  insert into public.notification_workspace_muted_types (workspace_id, type_key, muted_by)
  select target_workspace_id, k, actor_user_id from unnest(muted) k
  on conflict (workspace_id, type_key) do nothing;
  return public.get_notification_workspace_settings_service(actor_user_id, target_workspace_id);
end;
$$;


ALTER FUNCTION "public"."save_notification_workspace_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_own_avatar_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "choice" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  membership uuid;
  chosen_art text := choice ->> 'art_key';
  chosen_photo text := choice ->> 'photo_path';
  previous text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'avatar.self');

  select m.id into membership
  from public.workspace_memberships m
  where m.workspace_id = target_workspace_id and m.user_id = actor_user_id;

  if chosen_photo is not null
     and not starts_with(chosen_photo, target_workspace_id::text || '/' || membership::text || '/') then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'avatar.self';
  end if;

  select a.photo_path into previous
  from public.member_avatars a
  where a.membership_id = membership
  for update;

  insert into public.member_avatars (membership_id, workspace_id, photo_path, art_key, updated_at)
  values (membership, target_workspace_id, chosen_photo, chosen_art, now())
  on conflict (membership_id) do update
  set photo_path = excluded.photo_path, art_key = excluded.art_key, updated_at = excluded.updated_at;

  insert into app_private.last_avatars (user_id, source_membership_id, art_key)
  values (actor_user_id, membership, chosen_art)
  on conflict (user_id) do update
  set source_membership_id = excluded.source_membership_id, art_key = excluded.art_key;

  return jsonb_build_object('previous_photo_path',
    case when previous is distinct from chosen_photo then previous end);
end;
$$;


ALTER FUNCTION "public"."save_own_avatar_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "choice" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_own_employment_contact_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "contact_name" "text", "contact_relationship" "text", "contact_phone" "text", "contact_email" "text" DEFAULT ''::"text", "personal_phone" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  employee_row public.employee_profiles%rowtype;
  private_row public.employee_private_profiles%rowtype;
  cleaned_personal_phone text := nullif(btrim(coalesce(personal_phone, '')), '');
  relationship text;
begin
  -- The one rule: your own record, whoever you are here. Somebody else's and
  -- an unknown one get the same answer (authz.out_of_scope).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.save_own_contact',
    target_person => target_employee_id);
  select * into employee_row
  from public.employee_profiles
  where id = target_employee_id
    and workspace_id = target_workspace_id
    and archived_at is null;

  if employee_row.id is null then
    raise exception 'employee not found'
      using errcode = 'P0002', hint = 'employee.not_found';
  end if;

  if char_length(btrim(coalesce(contact_name, ''))) < 1
    or char_length(btrim(coalesce(contact_phone, ''))) < 7 then
    raise exception 'an emergency contact needs a name and a phone number'
      using errcode = '22023';
  end if;
  -- A half-typed number is refused here, where the screen can read the refusal.
  if cleaned_personal_phone is not null
    and char_length(cleaned_personal_phone) < 7 then
    raise exception 'a personal phone number is too short to reach anybody'
      using errcode = '22023';
  end if;

  select * into private_row
  from public.employee_private_profiles
  where employee_id = employee_row.id
  for update;
  if private_row.employee_id is null then
    raise exception 'there is no legal name on file for this record yet'
      using errcode = '23514';
  end if;

  relationship := coalesce(
    nullif(btrim(coalesce(contact_relationship, '')), ''),
    private_row.emergency_contact_relationship
  );
  if relationship is null then
    raise exception 'an emergency contact needs a relationship' using errcode = '22023';
  end if;

  -- The phone is the account's (KK-7). An empty account takes this number and
  -- the trigger copies it onto every live record, this one included.
  perform app_private.adopt_account_phone(
    actor_user_id, cleaned_personal_phone,
    btrim(employee_row.first_name || ' ' || employee_row.last_name)
  );

  update public.employee_private_profiles
  set
    emergency_contact_name = btrim(contact_name),
    emergency_contact_relationship = relationship,
    emergency_contact_phone = btrim(contact_phone),
    emergency_contact_email = btrim(coalesce(contact_email, '')),
    updated_at = now()
  where employee_id = employee_row.id;
end;
$$;


ALTER FUNCTION "public"."save_own_employment_contact_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "contact_name" "text", "contact_relationship" "text", "contact_phone" "text", "contact_email" "text", "personal_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_owner_legal_name_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "legal_first_name" "text", "legal_middle_name" "text", "legal_last_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  own_employee_id uuid;
  previous_name jsonb;
  next_name jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.setup');

  select employee.id into own_employee_id
  from public.employee_profiles employee
  where employee.workspace_id = target_workspace_id
    and employee.user_id = actor_user_id
    and employee.archived_at is null;
  if own_employee_id is null then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;

  select jsonb_build_object(
    'first_name', private_profile.legal_first_name,
    'middle_name', private_profile.legal_middle_name,
    'last_name', private_profile.legal_last_name
  ) into previous_name
  from public.employee_private_profiles private_profile
  where private_profile.employee_id = own_employee_id
  for update;

  perform app_private.write_owner_legal_name(
    target_workspace_id, own_employee_id,
    legal_first_name, legal_middle_name, legal_last_name
  );

  select jsonb_build_object(
    'first_name', private_profile.legal_first_name,
    'middle_name', private_profile.legal_middle_name,
    'last_name', private_profile.legal_last_name
  ) into next_name
  from public.employee_private_profiles private_profile
  where private_profile.employee_id = own_employee_id;

  -- A save that changes nothing is not a change.
  if previous_name is not distinct from next_name then
    return;
  end if;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id,
    actor_user_id,
    'employee.legal_name_changed',
    'employee',
    own_employee_id::text,
    jsonb_build_object('previous', previous_name, 'next', next_name)
  );
end;
$$;


ALTER FUNCTION "public"."save_owner_legal_name_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "legal_first_name" "text", "legal_middle_name" "text", "legal_last_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_policy_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "policy_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare settings jsonb:=policy_payload->'lifecycle_settings'; saved_id uuid; period integer; prior_revision integer;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 if settings is null or settings->>'mode' is null or settings->>'mode' not in ('optional','required')
  or settings->>'assignment_scope' is null or settings->>'assignment_scope' not in ('future_onboarding','all_active') or jsonb_typeof(settings->'target') is distinct from 'object'
 then raise exception 'valid policy assignment settings required' using errcode='22023'; end if;
 perform app_private.assert_document_definition_target(actor_user_id,target_workspace_id,settings->'target');
 period:=(settings->>'period_days')::integer;
 if (period is not null and period not between 1 and 3650) or (coalesce((settings->>'suspend_on_overdue')::boolean,false) and (settings->>'mode'='optional' or period is null))
 then raise exception 'valid policy delivery period required' using errcode='22023'; end if;
 if target_template_id is not null then
  perform 1 from public.signature_templates where id=target_template_id and workspace_id=target_workspace_id for update;
  select lifecycle_revision into prior_revision from public.signature_template_versions where template_id=target_template_id and workspace_id=target_workspace_id and status='draft' for update;
  if prior_revision is not null and prior_revision is distinct from (policy_payload->>'lifecycle_revision')::integer then raise exception 'policy draft changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 end if;
 saved_id:=public.save_signature_template_draft_service(actor_user_id,target_workspace_id,target_template_id,
  policy_payload->>'title',policy_payload->>'summary',policy_payload->>'content_text',policy_payload->>'intent_statement',policy_payload->>'locale',
  (policy_payload->>'effective_date')::date,settings->>'mode'='required',settings->>'mode'='required',(policy_payload->>'retention_policy_id')::uuid);
 update public.signature_template_versions set lifecycle_settings=settings,lifecycle_revision=coalesce(prior_revision,0)+1 where template_id=saved_id and status='draft';
 return saved_id;
end;
$$;


ALTER FUNCTION "public"."save_policy_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "policy_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "target_name" "text", "target_draft_id" "uuid" DEFAULT NULL::"uuid", "expected_draft_revision" integer DEFAULT NULL::integer, "acknowledge_past_edits" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_session public.schedule_edit_sessions%rowtype;
  saved_draft public.schedule_drafts%rowtype;
  reach uuid[];
  current_week_start date;
  findings jsonb := '[]'::jsonb;
  blocked_findings jsonb := '[]'::jsonb;
  warning_findings jsonb := '[]'::jsonb;
  session_labels jsonb;
  result jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,921));
  perform public.shift_exchange_assert_session(target_workspace_id,target_session_id);

  -- a. A past week never changes; a shift that already started changes only
  -- when the person says they know.
  select * into target_session
  from public.schedule_edit_sessions session
  where session.id = target_session_id
    and session.workspace_id = target_workspace_id
  for update;

  if target_session.id is null or target_session.holder_user_id <> actor_user_id then
    raise exception 'edit session not found' using errcode = 'P0002';
  end if;
  if target_session.status <> 'active' then
    raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
  elsif target_session.expires_at <= now() then
    raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
  end if;
  if target_session.revision <> expected_session_revision then
    raise exception 'session revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
  end if;
  -- The edit's locations are still the person's to edit (B-3), and the draft
  -- it writes into is the one it was opened from, a new one, or one the core
  -- lets the person write at all its locations (B-1).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => target_session.location_ids);
  if target_draft_id is distinct from target_session.source_draft_id and target_draft_id is not null then
    select * into saved_draft from public.schedule_drafts draft
    where draft.id = target_draft_id and draft.workspace_id = target_workspace_id
      and draft.week_start = target_session.week_start and draft.archived_at is null;
    if saved_draft.id is null then
      raise exception 'Not allowed' using errcode = '42501', detail = 'schedule.edit', hint = 'authz.out_of_scope';
    end if;
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit',
      target_locations => app_private.live_draft_locations(target_workspace_id, saved_draft.location_ids));
    saved_draft := null;
  end if;

  reach := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit');
  current_week_start := public.schedule_current_week_start_service(target_workspace_id, target_session.location_ids);

  if current_week_start is not null and target_session.week_start < current_week_start then
    select coalesce(jsonb_agg(jsonb_build_object(
      'op_type', coalesce(shift.pending_op_type, 'update'),
      'shift_id', shift.id,
      'scheduled_date', to_char(shift.scheduled_date, 'YYYY-MM-DD'),
      'location_name', coalesce(location.name, 'Unknown location'),
      'employee_name', coalesce(
        nullif(trim(concat_ws(' ', nullif(employee.preferred_name, ''), employee.last_name)), ''),
        nullif(trim(concat_ws(' ', employee.first_name, employee.last_name)), '')
      ),
      'reason', 'past_week',
      'severity', 'blocked'
    ) order by shift.scheduled_date, shift.start_time, shift.id), '[]'::jsonb)
    into blocked_findings
    from public.schedule_edit_session_shifts shift
    left join public.locations location
      on location.id = shift.location_id
     and location.workspace_id = shift.workspace_id
    left join public.employee_profiles employee
      on employee.id = shift.employee_id
     and employee.workspace_id = shift.workspace_id
    where shift.session_id = target_session_id
      and shift.workspace_id = target_workspace_id
      and shift.location_id = any(reach);

    if jsonb_array_length(blocked_findings) = 0 then
      blocked_findings := jsonb_build_array(jsonb_build_object(
        'op_type', 'update',
        'shift_id', null,
        'scheduled_date', to_char(target_session.week_start, 'YYYY-MM-DD'),
        'location_name', 'Schedule week',
        'employee_name', null,
        'reason', 'past_week',
        'severity', 'blocked'
      ));
    end if;
  else
    -- S-01: the lock is per location. A place that has left the week keeps
    -- what it has: its published shifts and the shifts of the draft this edit
    -- came from may ride along untouched; anything new, changed, moved away or
    -- removed there is refused, by name, and the other places still save.
    select coalesce(jsonb_agg(finding.x order by finding.scheduled_date, finding.start_time, finding.id), '[]'::jsonb)
    into blocked_findings
    from (
      select shift.id, shift.scheduled_date, shift.start_time, jsonb_build_object(
        'op_type', coalesce(shift.pending_op_type, case when kept.id is null then 'create' else 'update' end),
        'shift_id', shift.id,
        'scheduled_date', to_char(shift.scheduled_date, 'YYYY-MM-DD'),
        'location_name', coalesce(location.name, 'Unknown location'),
        'employee_name', coalesce(
          nullif(trim(concat_ws(' ', nullif(employee.preferred_name, ''), employee.last_name)), ''),
          nullif(trim(concat_ws(' ', employee.first_name, employee.last_name)), '')
        ),
        'reason', 'past_week',
        'severity', 'blocked'
      ) as x
      from public.schedule_edit_session_shifts shift
      left join public.schedule_draft_shifts kept
        on kept.draft_id = target_session.source_draft_id
       and kept.id = shift.id
      -- The place that has left the week: where the shift came from (its
      -- source draft row, or any current publication of the week holding it,
      -- by either id a published copy keeps), else where it is now. A shift
      -- moved out of a closed place changes that place too.
      left join lateral (
        select place.id
        from (
          select 1 as n, kept.location_id as id
          union all
          select 1, published.location_id
          from public.schedule_published_shifts published
          join public.schedule_location_publications publication
            on publication.id = published.publication_id
           and publication.status = 'current'
           and publication.week_start = target_session.week_start
          where published.workspace_id = target_workspace_id
            and shift.source_published_shift_id in (published.source_shift_id, published.id)
          union all
          select 2, shift.location_id
        ) place
        where place.id is not null
          and target_session.week_start
            < public.schedule_current_week_start_service(target_workspace_id, array[place.id])
        order by place.n, place.id
        limit 1
      ) closed on true
      left join public.locations location
        on location.id = closed.id
       and location.workspace_id = shift.workspace_id
      left join public.employee_profiles employee
        on employee.id = shift.employee_id
       and employee.workspace_id = shift.workspace_id
      where shift.session_id = target_session_id
        and shift.workspace_id = target_workspace_id
        and (shift.pending_op_type is not null
          or (shift.source_published_shift_id is null and (kept.id is null or kept.revision <> shift.revision)))
        and shift.location_id = any(reach)
        and closed.id is not null
      union all
      -- A shift of the source draft taken out of the edit at such a place.
      select kept.id, kept.scheduled_date, kept.start_time, jsonb_build_object(
        'op_type', 'delete',
        'shift_id', kept.id,
        'scheduled_date', to_char(kept.scheduled_date, 'YYYY-MM-DD'),
        'location_name', coalesce(location.name, 'Unknown location'),
        'employee_name', coalesce(
          nullif(trim(concat_ws(' ', nullif(employee.preferred_name, ''), employee.last_name)), ''),
          nullif(trim(concat_ws(' ', employee.first_name, employee.last_name)), '')
        ),
        'reason', 'past_week',
        'severity', 'blocked'
      )
      from public.schedule_draft_shifts kept
      left join public.locations location
        on location.id = kept.location_id
       and location.workspace_id = kept.workspace_id
      left join public.employee_profiles employee
        on employee.id = kept.employee_id
       and employee.workspace_id = kept.workspace_id
      where kept.draft_id = target_session.source_draft_id
        and kept.workspace_id = target_workspace_id
        and kept.location_id = any(target_session.location_ids)
        and kept.location_id = any(reach)
        and target_session.week_start
          < public.schedule_current_week_start_service(target_workspace_id, array[kept.location_id])
        and not exists (
          select 1 from public.schedule_edit_session_shifts shift
          where shift.session_id = target_session_id and shift.id = kept.id)
    ) finding;

    select coalesce(jsonb_agg(jsonb_build_object(
      'op_type', shift.pending_op_type,
      'shift_id', shift.id,
      'scheduled_date', to_char(shift.scheduled_date, 'YYYY-MM-DD'),
      'location_name', coalesce(location.name, 'Unknown location'),
      'employee_name', coalesce(
        nullif(trim(concat_ws(' ', nullif(employee.preferred_name, ''), employee.last_name)), ''),
        nullif(trim(concat_ws(' ', employee.first_name, employee.last_name)), '')
      ),
      'reason', 'shift_started',
      'severity', 'warning'
    ) order by shift.scheduled_date, shift.start_time, shift.id), '[]'::jsonb)
    into warning_findings
    from public.schedule_edit_session_shifts shift
    join public.locations location
      on location.id = shift.location_id
     and location.workspace_id = shift.workspace_id
    left join public.employee_profiles employee
      on employee.id = shift.employee_id
     and employee.workspace_id = shift.workspace_id
    where shift.session_id = target_session_id
      and shift.workspace_id = target_workspace_id
      and shift.pending_op_type in ('create', 'update', 'delete')
      and shift.location_id = any(reach)
      and ((shift.scheduled_date::timestamp + shift.start_time) at time zone location.timezone) <= now();
  end if;

  if jsonb_array_length(blocked_findings) > 0 then
    findings := blocked_findings;
    raise exception '%', jsonb_build_object(
      'status', 'past_edit_blocked',
      'past_edits', findings,
      'past_edit_messages', (
        select coalesce(jsonb_agg(
          coalesce(finding->>'employee_name', 'An open shift')
          || ' - '
          || coalesce(finding->>'location_name', 'Unknown location')
          || ' on '
          || coalesce(finding->>'scheduled_date', target_session.week_start::text)
          || ' is in a past week and cannot change.'
        ), '[]'::jsonb)
        from jsonb_array_elements(findings) finding
      ),
      'current_week_start', current_week_start
    )::text using errcode = 'P0001';
  end if;

  if jsonb_array_length(warning_findings) > 0 and acknowledge_past_edits is distinct from true then
    findings := warning_findings;
    raise exception '%', jsonb_build_object(
      'status', 'past_shift_edit_requires_ack',
      'past_edits', findings,
      'past_edit_messages', (
        select coalesce(jsonb_agg(
          coalesce(finding->>'employee_name', 'An open shift')
          || ' - '
          || coalesce(finding->>'location_name', 'Unknown location')
          || ' on '
          || coalesce(finding->>'scheduled_date', target_session.week_start::text)
          || ' has already started. Employees will not be notified of this change.'
        ), '[]'::jsonb)
        from jsonb_array_elements(findings) finding
      )
    )::text using errcode = 'P0001';
  end if;

  -- b. The labels, kept aside: the draft rows are written fresh.
  perform public.availability_lock_workspace(target_workspace_id);
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', shift.id,
    'label_ids', to_jsonb(coalesce(shift.label_ids, '{}'::uuid[])),
    'label_names', to_jsonb(coalesce(shift.label_names, '{}'::text[]))
  )), '[]'::jsonb)
  into session_labels
  from public.schedule_edit_session_shifts shift
  join public.schedule_edit_sessions session
    on session.id = shift.session_id
   and session.workspace_id = shift.workspace_id
  where shift.session_id = target_session_id
    and shift.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id;

  -- c. Pending deletes go, then the draft is written.
  delete from public.schedule_edit_session_shifts shift
  using public.schedule_edit_sessions session
  where session.id = target_session_id
    and session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id
    and session.status = 'active'
    and shift.session_id = session.id
    and shift.pending_op_type = 'delete';

  begin
    select * into target_session from public.schedule_edit_sessions session
    where session.id = target_session_id and session.workspace_id = target_workspace_id
    for update;
    if target_session.id is null or target_session.holder_user_id <> actor_user_id then
      raise exception 'edit session not found' using errcode = 'P0002';
    end if;
    if target_session.status <> 'active' then
      raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
    elsif target_session.expires_at <= now() then
      raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
    end if;
    if target_session.revision <> expected_session_revision then
      raise exception 'session revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
    end if;
    if char_length(btrim(target_name)) not between 1 and 80 then
      raise exception 'invalid draft name' using errcode = '22023';
    end if;

    if target_draft_id is null then
      insert into public.schedule_drafts (
        workspace_id, week_start, name, created_by, updated_by, location_ids, base_publication_ids
      ) values (
        target_workspace_id, target_session.week_start, btrim(target_name),
        actor_user_id, actor_user_id, target_session.location_ids, target_session.base_publication_ids
      ) returning * into saved_draft;
    else
      update public.schedule_drafts draft
      set name = btrim(target_name), revision = revision + 1,
        updated_by = actor_user_id, updated_at = now(),
        location_ids = array(
          select distinct location_id from unnest(draft.location_ids || target_session.location_ids) location_id
          order by location_id
        ),
        -- The edit's locations now start where the edit started.
        base_publication_ids = array(
          select base_id from unnest(draft.base_publication_ids) base_id
          where not exists (
            select 1 from public.schedule_location_publications publication
            where publication.id = base_id
              and publication.location_id = any(target_session.location_ids)
          )
        ) || target_session.base_publication_ids
      where draft.id = target_draft_id and draft.workspace_id = target_workspace_id
        and draft.week_start = target_session.week_start and draft.archived_at is null
        and draft.revision = expected_draft_revision
      returning * into saved_draft;
      if saved_draft.id is null then
        raise exception 'draft revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
      end if;
    end if;

    -- BL-097: only the locations this session holds are replaced; the rest of
    -- the draft stays as it was.
    delete from public.schedule_draft_shifts shift
    where shift.draft_id = saved_draft.id
      and shift.location_id = any(target_session.location_ids);
    insert into public.schedule_draft_shifts (id, workspace_id, draft_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, revision)
    select shift.id, shift.workspace_id, saved_draft.id, shift.location_id, shift.employee_id, shift.job_id, shift.shift_type_id, shift.scheduled_date, shift.start_time, shift.end_time, shift.time_basis, shift.time_snapshot, shift.time_timezone, shift.unpaid_break_minutes, shift.hide_time_on_badge, shift.note, shift.revision from public.schedule_edit_session_shifts shift
    where shift.session_id = target_session_id;

    delete from public.schedule_edit_session_shifts where session_id = target_session_id;
    update public.schedule_edit_sessions
    set status = 'saved', dirty = false, closed_at = now(), expires_at = now()
    where id = target_session_id;

    result := jsonb_build_object(
      'id', saved_draft.id, 'workspace_id', saved_draft.workspace_id,
      'week_start', saved_draft.week_start, 'name', saved_draft.name,
      'revision', saved_draft.revision, 'created_by', saved_draft.created_by,
      'updated_by', saved_draft.updated_by, 'created_at', saved_draft.created_at,
      'updated_at', saved_draft.updated_at
    );
  exception
    when unique_violation then
      raise exception 'draft name conflict' using errcode = '23505';
  end;

  -- d. The labels back on the draft rows.
  update public.schedule_draft_shifts draft_shift
     set label_ids = coalesce(label_row.label_ids, '{}'::uuid[]),
         label_names = coalesce(label_row.label_names, '{}'::text[])
    from jsonb_to_recordset(session_labels) as label_row(
      id uuid,
      label_ids uuid[],
      label_names text[]
    )
   where draft_shift.draft_id = saved_draft.id
     and draft_shift.id = label_row.id
     and draft_shift.workspace_id = target_workspace_id;

  return result;
exception when serialization_failure then raise exception '%',SQLERRM using errcode='PT409', hint='schedule.edit_session_stale';
end;
$$;


ALTER FUNCTION "public"."save_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "target_name" "text", "target_draft_id" "uuid", "expected_draft_revision" integer, "acknowledge_past_edits" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_signature_retention_policy_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_policy_id" "uuid", "policy_name" "text", "policy_trigger" "text", "policy_duration_days" integer, "policy_jurisdiction_scope" "text", "policy_authority_reference" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  saved_id uuid;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  if char_length(btrim(policy_name)) not between 1 and 80
    or policy_trigger not in ('signed_at', 'employment_end')
    or policy_duration_days not between 1 and 36500
    or char_length(btrim(policy_jurisdiction_scope)) not between 1 and 120
    or char_length(btrim(policy_authority_reference)) not between 1 and 500 then
    raise exception 'invalid retention policy fields' using errcode = '22023';
  end if;

  if target_policy_id is null then
    insert into public.signature_retention_policies (
      workspace_id, name, retention_trigger, duration_days,
      jurisdiction_scope, authority_reference, created_by
    ) values (
      target_workspace_id, btrim(policy_name), policy_trigger::public.signature_retention_trigger,
      policy_duration_days, btrim(policy_jurisdiction_scope),
      btrim(policy_authority_reference), actor_id
    ) returning id into saved_id;
  else
    update public.signature_retention_policies
    set name = btrim(policy_name),
        retention_trigger = policy_trigger::public.signature_retention_trigger,
        duration_days = policy_duration_days,
        jurisdiction_scope = btrim(policy_jurisdiction_scope),
        authority_reference = btrim(policy_authority_reference),
        updated_at = now()
    where id = target_policy_id
      and workspace_id = target_workspace_id
      and status = 'draft'
    returning id into saved_id;

    if saved_id is null then
      raise exception 'editable retention policy not found' using errcode = 'P0002';
    end if;
  end if;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id, actor_id,
    case when target_policy_id is null then 'signature_retention_policy.created' else 'signature_retention_policy.updated' end,
    'signature_retention_policy', saved_id::text,
    jsonb_build_object('name', btrim(policy_name), 'trigger', policy_trigger, 'duration_days', policy_duration_days)
  );
  return saved_id;
end;
$$;


ALTER FUNCTION "public"."save_signature_retention_policy_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_policy_id" "uuid", "policy_name" "text", "policy_trigger" "text", "policy_duration_days" integer, "policy_jurisdiction_scope" "text", "policy_authority_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_signature_template_draft_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "template_name" "text", "template_summary" "text", "template_content" "text", "template_intent_statement" "text", "template_locale" "text", "template_effective_date" "date", "is_required_at_onboarding" boolean, "should_block_activation" boolean, "target_retention_policy_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_id uuid := actor_user_id;
  saved_template_id uuid;
  saved_version_id uuid;
  normalized_content text := replace(replace(template_content, E'\r\n', E'\n'), E'\r', E'\n');
  next_version integer;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  if char_length(btrim(template_name)) not between 1 and 80
    or char_length(coalesce(template_summary, '')) > 240
    or char_length(normalized_content) not between 1 and 50000
    or char_length(btrim(template_intent_statement)) not between 1 and 500
    or template_locale !~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$'
    or template_effective_date is null then
    raise exception 'invalid acknowledgement template fields' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.signature_retention_policies
    where id = target_retention_policy_id and workspace_id = target_workspace_id
      and archived_at is null
  ) then
    raise exception 'active retention policy required' using errcode = '22023';
  end if;
  if should_block_activation and not is_required_at_onboarding then
    raise exception 'activation blocking requires onboarding assignment' using errcode = '22023';
  end if;

  if target_template_id is null then
    insert into public.signature_templates (workspace_id, name, created_by)
    values (target_workspace_id, btrim(template_name), actor_id)
    returning id into saved_template_id;
    next_version := 1;
  else
    update public.signature_templates
    set name = btrim(template_name), updated_at = now()
    where id = target_template_id and workspace_id = target_workspace_id
      and archived_at is null
    returning id into saved_template_id;
    if saved_template_id is null then
      raise exception 'active acknowledgement template not found' using errcode = 'P0002';
    end if;
    select id into saved_version_id from public.signature_template_versions
      where template_id = saved_template_id and status = 'draft';
    select coalesce(max(version_number), 0) + 1 into next_version
      from public.signature_template_versions where template_id = saved_template_id;
  end if;

  if saved_version_id is null then
    insert into public.signature_template_versions (
      workspace_id, template_id, version_number, title, summary, execution_class,
      content_text, content_digest, intent_statement, locale, effective_date,
      required_at_onboarding, blocks_activation, retention_policy_id, created_by
    ) values (
      target_workspace_id, saved_template_id, next_version, btrim(template_name),
      btrim(coalesce(template_summary, '')), 'acknowledgement', normalized_content,
      encode(extensions.digest(convert_to(normalized_content, 'UTF8'), 'sha256'), 'hex'),
      btrim(template_intent_statement), template_locale, template_effective_date,
      is_required_at_onboarding, should_block_activation, target_retention_policy_id, actor_id
    ) returning id into saved_version_id;
  else
    update public.signature_template_versions
    set title = btrim(template_name), summary = btrim(coalesce(template_summary, '')),
        content_text = normalized_content,
        content_digest = encode(extensions.digest(convert_to(normalized_content, 'UTF8'), 'sha256'), 'hex'),
        intent_statement = btrim(template_intent_statement), locale = template_locale,
        effective_date = template_effective_date,
        required_at_onboarding = is_required_at_onboarding,
        blocks_activation = should_block_activation,
        retention_policy_id = target_retention_policy_id, updated_at = now()
    where id = saved_version_id;
  end if;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id, actor_id,
    case when target_template_id is null then 'signature_template.created' else 'signature_template.draft_saved' end,
    'signature_template', saved_template_id::text,
    jsonb_build_object('name', btrim(template_name), 'version_id', saved_version_id)
  );
  return saved_template_id;
end;
$_$;


ALTER FUNCTION "public"."save_signature_template_draft_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "template_name" "text", "template_summary" "text", "template_content" "text", "template_intent_statement" "text", "template_locale" "text", "template_effective_date" "date", "is_required_at_onboarding" boolean, "should_block_activation" boolean, "target_retention_policy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_workspace_layout_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_widget_order" "text"[], "target_hidden_widget_ids" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  allowed constant text[] := array[
    'operations',
    'pending_requests',
    'open_shifts',
    'announcements',
    'todos',
    'quick_actions'
  ];
begin
  -- The home's own gate (KK-34): whoever cannot open it does not arrange it.
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.todos');
  if cardinality(target_widget_order) <> cardinality(allowed)
    or (select count(distinct value) from unnest(target_widget_order) value) <> cardinality(allowed)
    or exists(select 1 from unnest(target_widget_order || target_hidden_widget_ids) value where not value = any(allowed)) then
    raise exception 'valid workspace layout required' using errcode = '22023';
  end if;

  insert into public.workspace_layout_preferences (
    workspace_id, user_id, widget_order, hidden_widget_ids
  ) values (
    target_workspace_id,
    actor_user_id,
    target_widget_order,
    array(select distinct value from unnest(target_hidden_widget_ids) value)
  )
  on conflict(workspace_id, user_id)
  do update set
    widget_order = excluded.widget_order,
    hidden_widget_ids = excluded.hidden_widget_ids,
    updated_at = now();

  return jsonb_build_object('status', 'saved');
end;
$$;


ALTER FUNCTION "public"."save_workspace_layout_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_widget_order" "text"[], "target_hidden_widget_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_workspace_layout_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_widget_order" "text"[], "target_hidden_widget_ids" "text"[], "target_location_order" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  allowed constant text[] := app_private.home_section_order(null);
begin
  -- The home's own gate (KK-34): whoever cannot open it does not arrange it.
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.todos');
  if target_widget_order is null or target_hidden_widget_ids is null or target_location_order is null
    or cardinality(target_widget_order) <> cardinality(allowed)
    or (select count(distinct value) from unnest(target_widget_order) value) <> cardinality(allowed)
    or exists (select 1 from unnest(target_widget_order || target_hidden_widget_ids) value where value is null or not value = any(allowed))
    or cardinality(target_location_order) > 500
    or exists (select 1 from unnest(target_location_order) value where value is null)
    or (select count(distinct value) from unnest(target_location_order) value) <> cardinality(target_location_order) then
    raise exception 'valid workspace layout required' using errcode = '22023';
  end if;

  insert into public.workspace_layout_preferences (workspace_id, user_id, widget_order, hidden_widget_ids, location_order)
  values (
    target_workspace_id,
    actor_user_id,
    target_widget_order,
    array(select distinct value from unnest(target_hidden_widget_ids) value),
    -- S-220: only this workspace's locations are kept; the read shows those in the actor's scope.
    array(
      select given.id
      from unnest(target_location_order) with ordinality given(id, ordinality)
      join public.locations location on location.id = given.id and location.workspace_id = target_workspace_id
      order by given.ordinality
    )
  )
  on conflict (workspace_id, user_id)
  do update set
    widget_order = excluded.widget_order,
    hidden_widget_ids = excluded.hidden_widget_ids,
    location_order = excluded.location_order,
    updated_at = now();

  return jsonb_build_object('status', 'saved');
end;
$$;


ALTER FUNCTION "public"."save_workspace_layout_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_widget_order" "text"[], "target_hidden_widget_ids" "text"[], "target_location_order" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_workspace_role_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_role_id" "uuid", "role_name" "text", "role_description" "text", "role_access_class" "public"."workspace_role", "permission_keys" "text"[], "expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target public.workspace_roles; saved uuid; normalized text[]; actor_class public.workspace_role;
begin
 -- Serialize role editors, including concurrent actor-grant changes.
 perform pg_advisory_xact_lock(hashtextextended('roles:'||target_workspace_id::text,0));
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.roles.write');
 if not app_private.can_edit_role(actor_user_id,target_workspace_id,target_role_id) then raise exception 'role management access denied' using errcode='42501',hint=case when target_role_id is not null and not exists(select 1 from public.workspace_roles r where r.id=target_role_id and r.workspace_id=target_workspace_id) then 'authz.out_of_scope' else 'authz.rank' end; end if;
 -- The editor's class, from the core (ROL-CIFT: the management slot's, else employee).
 actor_class := (app_private.actor(actor_user_id,target_workspace_id)).class;
 if target_role_id is not null then
  select * into target from public.workspace_roles where id=target_role_id and workspace_id=target_workspace_id for update;
  if expected_updated_at is null or expected_updated_at<>target.updated_at then raise exception 'Role changed since you opened it. Reload before saving.' using errcode='PT409',hint='role.changed'; end if;
  if role_access_class<>target.access_class then raise exception 'Existing role experience cannot change' using errcode='22023'; end if;
 elsif role_access_class not in ('manager','employee') then raise exception 'Custom roles require a manager or employee experience' using errcode='42501'; end if;
 if role_name is null or char_length(btrim(role_name)) not between 1 and 64 or char_length(coalesce(role_description,''))>240 then raise exception 'Valid role details required' using errcode='22023'; end if;
 select coalesce(array_agg(distinct key order by key),'{}'::text[]) into normalized from unnest(coalesce(permission_keys,'{}'::text[])) key;
 if not 'workspace.read'=any(normalized) then raise exception 'Basic account access required' using errcode='22023'; end if;
 if exists(select 1 from unnest(normalized) k left join public.permissions p on p.key=k where p.key is null) then raise exception 'Unknown permission' using errcode='22023'; end if;
 if role_access_class<>'admin' and exists(select 1 from public.permissions p where p.key=any(normalized) and not p.custom_grantable) then raise exception 'Permission is not eligible for a lower role' using errcode='42501', hint='authz.rank'; end if;
 if role_access_class<>'admin' and normalized && array['roles.manage','workspace.manage'] then raise exception 'Protected management access denied' using errcode='42501'; end if;
 if role_access_class='employee' and exists(select 1 from unnest(normalized) k where k not in (select p.key from public.permissions p where p.employee_eligible)) then raise exception 'Employee roles are limited to personal access' using errcode='42501'; end if;
 -- Admin delegation cannot manufacture permissions it does not itself hold.
 if actor_class='admin' and exists(select 1 from unnest(normalized) k where not k = any ((select (app_private.actor(actor_user_id,target_workspace_id)).permissions)::text[])) then raise exception 'Cannot grant access beyond your own permissions' using errcode='42501',hint='authz.missing_permission'; end if;
 if exists(select 1 from app_private.role_permission_dependencies d where d.permission_key=any(normalized) and not d.required_key=any(normalized)) then raise exception 'Permission set requires dependent read access' using errcode='22023'; end if;
 if target_role_id is null then
  insert into public.workspace_roles(workspace_id,name,description,access_class,sort_order,created_by) values(target_workspace_id,btrim(role_name),btrim(coalesce(role_description,'')),role_access_class,100,actor_user_id) returning id into saved;
 else
  saved:=target_role_id;
  update public.workspace_roles set name=case when system_key is null then btrim(role_name) else name end,description=case when system_key is null then btrim(coalesce(role_description,'')) else description end,updated_at=clock_timestamp() where id=saved;
 end if;
 delete from public.workspace_role_permissions where role_id=saved;
 insert into public.workspace_role_permissions(workspace_id,role_id,permission_key) select target_workspace_id,saved,unnest(normalized);
 insert into public.audit_events(workspace_id,actor_user_id,action,target_type,target_id,metadata) values(target_workspace_id,actor_user_id,case when target_role_id is null then 'role.created' else 'role.updated' end,'workspace_role',saved::text,jsonb_build_object('permissions',normalized));
 return saved;
end; $$;


ALTER FUNCTION "public"."save_workspace_role_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_role_id" "uuid", "role_name" "text", "role_description" "text", "role_access_class" "public"."workspace_role", "permission_keys" "text"[], "expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_availability_enrich_read"("actor" "uuid", "w" "uuid", "model" "jsonb", "draft" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare field text; item jsonb; result jsonb; stored jsonb; projection jsonb; codes jsonb;
begin
 foreach field in array array['shifts','ghost_shifts'] loop
  if not model ? field then continue; end if;
  result:='[]';
  for item in select value from jsonb_array_elements(coalesce(model->field,'[]')) loop
   stored:=null;
   if draft is not null and field='shifts' then
    select to_jsonb(s) into stored from public.schedule_draft_shifts s where s.workspace_id=w and s.draft_id=draft
     and s.id=(item->>'id')::uuid and s.location_id=(item->>'location_id')::uuid and s.scheduled_date=(item->>'scheduled_date')::date;
   else
    select to_jsonb(s) into stored from public.schedule_published_shifts s join public.schedule_location_publications p on p.id=s.publication_id and p.workspace_id=s.workspace_id
     where s.workspace_id=w and (s.source_shift_id=(item->>'id')::uuid or s.id=(item->>'id')::uuid)
      and s.location_id=(item->>'location_id')::uuid and s.scheduled_date=(item->>'scheduled_date')::date and p.status='current'
     order by p.version_number desc limit 1;
   end if;
   if stored is not null then
    projection:=public.schedule_availability_read_projection(actor,w,stored);
    select coalesce(jsonb_agg(value),'[]') into codes from jsonb_array_elements(coalesce(item->'warning_codes','[]')) where value<>'"availability"'::jsonb;
    if coalesce((projection->'availability_assessment'->>'has_availability_conflict')::boolean,false) or projection->'availability_assessment'->>'operation'<>'allowed' then codes:=codes||'"availability"'::jsonb; end if;
    item:=item||projection||jsonb_build_object('warning_codes',codes);
   end if;
   result:=result||jsonb_build_array(item);
  end loop;
  model:=jsonb_set(model,array[field],result);
 end loop;
 return model;
end; $$;


ALTER FUNCTION "public"."schedule_availability_enrich_read"("actor" "uuid", "w" "uuid", "model" "jsonb", "draft" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_availability_identity"("s" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select jsonb_build_object('id',coalesce(s->>'source_shift_id',s->>'id'),'employee_id',s->>'employee_id',
 'location_id',s->>'location_id','job_id',s->>'job_id','shift_type_id',s->>'shift_type_id',
 'scheduled_date',coalesce(s->>'scheduled_date',s->>'date'),'start_time',nullif(s->>'start_time','')::time,
 'end_time',nullif(s->>'end_time','')::time,'time_basis',s->>'time_basis','time_snapshot',s->'time_snapshot','time_timezone',s->>'time_timezone');
$$;


ALTER FUNCTION "public"."schedule_availability_identity"("s" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_availability_override"("w" "uuid", "s" "jsonb", "a" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select to_jsonb(o) from public.schedule_availability_overrides o where o.workspace_id=w
  and o.shift_id=coalesce(s->>'source_shift_id',s->>'id')::uuid and o.employee_id=(s->>'employee_id')::uuid
  and o.location_id=(s->>'location_id')::uuid and o.assessment_fingerprint=a->>'fingerprint' and o.revoked_at is null limit 1;
$$;


ALTER FUNCTION "public"."schedule_availability_override"("w" "uuid", "s" "jsonb", "a" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_availability_prior_publication"("w" "uuid", "s" "jsonb", "exclude_publication" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select to_jsonb(shift) from public.schedule_published_shifts shift
 join lateral (
  select p.id from public.schedule_location_publications p
  where p.workspace_id=w and p.location_id=(s->>'location_id')::uuid
   and (s->>'scheduled_date')::date between p.week_start and p.week_start+6
   and p.id is distinct from exclude_publication
   and (exclude_publication is null or p.version_number < (select version_number from public.schedule_location_publications where id=exclude_publication and workspace_id=w))
  order by p.version_number desc limit 1
 ) latest on latest.id=shift.publication_id
 where shift.workspace_id=w and public.schedule_availability_identity(to_jsonb(shift))=public.schedule_availability_identity(s)
 limit 1;
$$;


ALTER FUNCTION "public"."schedule_availability_prior_publication"("w" "uuid", "s" "jsonb", "exclude_publication" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_availability_read_projection"("actor" "uuid", "w" "uuid", "s" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare prior jsonb; a jsonb; today jsonb; evidence jsonb; retained boolean:=false; can_manage boolean;
begin
 can_manage:=app_private.authz_reason(actor,w,'schedule.edit',array[(s->>'location_id')::uuid]) is null
  or app_private.authz_reason(actor,w,'schedule.publish',array[(s->>'location_id')::uuid]) is null;
 if s->>'employee_id' is not null and can_manage then
  prior:=case when s->>'publication_id' is not null then s else public.schedule_availability_prior_publication(w,s) end;
  retained:=prior is not null;
  today:=public.assess_weekly_shift_availability(w,(s->>'employee_id')::uuid,s);
  -- An unchanged published shift keeps what was accepted when it went out
  -- (BL-174); availability is not an acceptance and is always today's (BL-186).
  if retained then
   a:=nullif(prior->'availability_snapshot'->'assessment','null');
   if a is not null then
    a:=a||jsonb_build_object('operation','allowed','responsibility_retained',true);
   end if;
  else
   a:=today;
   evidence:=public.schedule_availability_override(w,s,a);
   if a->>'operation'='warning_requires_override' and evidence is not null then
    a:=a||jsonb_build_object('operation','allowed','override_recorded',true);
   end if;
  end if;
  if a is not null and a->>'operation'='allowed' then
   a:=a||jsonb_build_object('has_availability_conflict',today->'has_availability_conflict','availability_fingerprint',today->'availability_fingerprint',
    'reasons',(select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(today->'reasons') r where r->>'code'='availability'));
  end if;
 end if;
 if a is not null then
  select jsonb_object_agg(key,value) into a from jsonb_each(a) where key=any(array[
   'conflict_severity','coverage','operation','time_basis','timezone','assessment_scope','intervals','available_intervals','unavailable_intervals','unknown_intervals',
   'reasons','fingerprint','policy_revision','fold_resolution','assessment_minutes','responsibility_retained','override_recorded',
   'warning_policy','has_availability_conflict','availability_fingerprint','preference_timezone']);
  -- A stored shift never carries the note: it shows only while writing (M12).
  a:=a||jsonb_build_object('can_override',can_manage,
   'reasons',(select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(coalesce(a->'reasons','[]')) r where r->>'code'<>'note'));
 end if;
 return jsonb_build_object('availability_assessment',a,'availability_responsibility_retained',retained,
  'time_basis',s->'time_basis','time_snapshot',s->'time_snapshot','time_timezone',s->'time_timezone',
  'hide_time_on_badge',coalesce((s->>'hide_time_on_badge')::boolean,false));
end; $$;


