CREATE OR REPLACE FUNCTION "public"."schedule_current_week_start_service"("target_workspace_id" "uuid", "target_location_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "date"
    LANGUAGE "sql" STABLE SECURITY DEFINER
