CREATE OR REPLACE FUNCTION "public"."search_workspace_ownership_candidates_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "search_text" "text") RETURNS TABLE("userId" "uuid", "name" "text", "email" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if actor_user_id is null or not app_private.workspace_allows_interactive_access(target_workspace_id)
    -- The core says who owns, and below who is an admin (ROL-CIFT 1.4).
    or not exists (
      select 1 from app_private.actor(actor_user_id, target_workspace_id) s
      where s.status = 'active' and s.class = 'owner'
    ) then raise exception 'workspace owner access required' using errcode = '42501', hint = 'workspace.owner_required'; end if;
  if search_text is null or char_length(btrim(search_text)) not between 2 and 80 then
    raise exception 'search must contain 2 to 80 characters' using errcode = '22023', hint = 'search.length_invalid';
  end if;
  return query
    select m.user_id, coalesce(nullif(concat_ws(' ', coalesce(nullif(e.preferred_name, ''), e.first_name), e.last_name), ''), p.display_name, u.email)::text, u.email::text
    from public.workspace_memberships m
    join auth.users u on u.id = m.user_id and u.email_confirmed_at is not null
    left join public.employee_profiles e on e.workspace_id = m.workspace_id and e.user_id = m.user_id and e.archived_at is null
    left join public.user_profiles p on p.user_id = m.user_id
    where m.workspace_id = target_workspace_id and m.status = 'active'
      and m.user_id <> actor_user_id
      -- The admin role first, then the core's word for each one left.
      and m.role_id = (select r.id from public.workspace_roles r where r.workspace_id = target_workspace_id and r.system_key = 'admin')
      and (app_private.actor(m.user_id, target_workspace_id)).class = 'admin'
      -- Active legacy memberships without an onboarding case are already complete.
      and not exists (select 1 from public.employee_onboarding_cases c
        where c.workspace_id = target_workspace_id and c.membership_id = m.id and c.status <> 'approved')
      -- A legal name on file, or the transfer would be refused (BL-080).
      and exists (select 1 from public.employee_private_profiles private_profile
        where private_profile.employee_id = e.id)
      -- Literal substring matching: '%' and '_' cannot enumerate the directory.
      and position(lower(btrim(search_text)) in lower(concat_ws(' ', e.first_name, e.last_name, e.preferred_name, p.display_name, u.email))) > 0
    order by 2, m.user_id limit 10;
end; $$;


ALTER FUNCTION "public"."search_workspace_ownership_candidates_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "search_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."service_actor_has_permission"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select not app_private.document_actor_blocked(actor_user_id,target_workspace_id) and exists(select 1 from public.workspace_memberships m
 where m.user_id=actor_user_id and m.workspace_id=target_workspace_id and m.status='active'
 and (target_permission in ('workspace.read','notifications.read','notifications.read_own','notifications.preferences.write_own')
 or exists(select 1 from public.workspace_role_permissions g where g.role_id=m.role_id and g.workspace_id=m.workspace_id and g.permission_key=target_permission)
 or exists(select 1 from public.workspace_role_permissions g join public.permissions p on p.key=g.permission_key and p.employee_eligible
   where g.role_id=m.employee_role_id and g.workspace_id=m.workspace_id and g.permission_key=target_permission)));
$$;


ALTER FUNCTION "public"."service_actor_has_permission"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_active_workspace"("target_workspace_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
begin
  if actor_id is null or not public.is_workspace_member(target_workspace_id) then
    raise exception 'active workspace is not available' using errcode = '42501';
  end if;

  insert into public.user_workspace_preferences (user_id, active_workspace_id)
  values (actor_id, target_workspace_id)
  on conflict (user_id) do update
    set active_workspace_id = excluded.active_workspace_id, updated_at = now();
end;
$$;


ALTER FUNCTION "public"."set_active_workspace"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_active_workspace_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;

  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);

  perform public.set_active_workspace(target_workspace_id);
end;
$$;


ALTER FUNCTION "public"."set_active_workspace_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_active_workspace_when_owner_onboarding_completes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status <> 'complete'::public.onboarding_status then
    return new;
  end if;

  if not exists (
    select 1
    from public.workspace_memberships membership
    join public.workspaces workspace
      on workspace.id = membership.workspace_id
    where membership.workspace_id = new.workspace_id
      and membership.user_id = new.updated_by
      and app_private.role_class(membership.role_id) = 'owner'
      and membership.status = 'active'::public.membership_status
      and workspace.lifecycle_status = 'active'::public.workspace_lifecycle_status
  ) then
    return new;
  end if;

  insert into public.user_workspace_preferences (user_id, active_workspace_id, updated_at)
  values (new.updated_by, new.workspace_id, now())
  on conflict (user_id) do update
    set active_workspace_id = excluded.active_workspace_id,
        updated_at = excluded.updated_at;

  return new;
end;
$$;


ALTER FUNCTION "public"."set_active_workspace_when_owner_onboarding_completes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_announcement_state_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid", "target_expected_revision" integer, "target_action" "text", "target_bring_back" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  w uuid := target_workspace_id;
  me app_private.actor_state;
  item public.announcements;
  shown text;
  reason text;
  told integer := 0;
  back jsonb := '[]'::jsonb;
  people uuid[];
begin
  perform app_private.authorize(actor_user_id, w, 'announcement.read');
  if target_action is null or target_action not in ('unschedule', 'unpublish', 'archive', 'bring_back', 'remind') then
    raise exception 'valid announcement action required' using errcode = '22023', hint = 'announcement.invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(w::text, 931));
  if target_action = 'bring_back' then
    perform public.availability_lock_workspace(w);
  end if;
  perform app_private.announcement_release(w);
  me := app_private.actor(actor_user_id, w);
  select * into item from public.announcements where id = target_announcement_id and workspace_id = w for update;
  if item.id is null or not app_private.announcement_visible(me, item) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'announcement.write';
  end if;
  reason := app_private.announcement_reason(me, app_private.announcement_places(item.id), item.created_by,
    app_private.announcement_dates(item));
  if reason is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'announcement.write';
  end if;
  shown := app_private.announcement_display_status(item);
  -- A past post can only be archived; an archived one is done (Mert, 2026-10-12).
  if (shown = 'past' and target_action <> 'archive') or shown = 'archived' then
    raise exception 'This post can''t change anymore.' using errcode = 'PT409', hint = 'announcement.read_only';
  end if;
  if item.revision is distinct from target_expected_revision
     or (target_action = 'unschedule' and shown not in ('scheduled', 'publish_failed'))
     or (target_action = 'unpublish' and shown <> 'published')
     or (target_action = 'archive' and shown not in ('draft', 'unpublished', 'past'))
     or (target_action = 'bring_back' and shown <> 'unpublished')
     -- Remind asks for an acknowledgement: only a post that asks for one has it.
     or (target_action = 'remind' and (shown <> 'published' or not item.ask_ack)) then
    raise exception 'This post changed since you opened it.' using errcode = 'PT409', hint = 'announcement.changed';
  end if;

  if target_action = 'unschedule' then
    update public.announcements
    set status = 'draft', scheduled_by = null, choices_saved_at = null, release_failed_at = null, release_error = null
    where id = item.id;
  elsif target_action = 'unpublish' then
    -- A dated post taken back tells whoever it reaches now; one without a day, nobody.
    people := case when item.starts_on is null then '{}'::uuid[] else app_private.announcement_recipients(item) end;
    told := cardinality(people);
    update public.announcements set status = 'unpublished', unpublished_at = now(), delivered_to = '{}' where id = item.id;
  elsif target_action = 'archive' then
    update public.announcements set archived_at = now(), delivered_to = '{}' where id = item.id;
  elsif target_action = 'remind' then
    -- S-126 (2): twice a day for one post at most, in the post's time zone; then the drawer's button rests.
    if app_private.announcement_reminders_left(item) = 0 then
      raise exception 'You can remind people about this post twice a day.' using errcode = 'PT409',
        hint = 'announcement.remind_limit';
    end if;
    people := array(select who from unnest(app_private.announcement_respondents(item)) who
                    where not exists (select 1 from public.announcement_acknowledgements ack
                                      where ack.announcement_id = item.id and ack.user_id = who));
    if cardinality(people) = 0 then
      raise exception 'Everyone acknowledged.' using errcode = 'PT409', hint = 'announcement.changed';
    end if;
    told := cardinality(people);
  else
    back := app_private.announcement_bring_back(actor_user_id, item, target_bring_back,
      app_private.announcement_back_rows(item, null, null, '[]'::jsonb));
    if jsonb_array_length(back) = 0 then
      raise exception 'Pick the shifts to bring back.' using errcode = '22023', hint = 'announcement.invalid';
    end if;
    -- Bringing shifts back has no notice yet: nobody is told, and its History counts nobody.
  end if;

  update public.announcements set revision = revision + 1, updated_by = actor_user_id, updated_at = now()
  where id = item.id returning * into item;
  insert into public.announcement_changes (workspace_id, announcement_id, actor_user_id, action, detail)
  values (w, item.id, actor_user_id,
    case target_action when 'unschedule' then 'unscheduled' when 'unpublish' then 'unpublished' when 'archive' then 'archived'
                       when 'remind' then 'reminded' else 'brought_back' end,
    jsonb_strip_nulls(jsonb_build_object('told', case when target_action in ('unpublish', 'remind') then told end,
      'brought_back', nullif(jsonb_array_length(back), 0))));
  insert into public.audit_events (workspace_id, actor_user_id, action, target_type, target_id, metadata)
  values (w, actor_user_id, 'announcement.' || case target_action when 'unschedule' then 'unscheduled'
      when 'unpublish' then 'unpublished' when 'archive' then 'archived' when 'remind' then 'reminded' else 'brought_back' end,
    'announcement', item.id::text, jsonb_build_object('told', told, 'brought_back', jsonb_array_length(back)));
  if target_action = 'unpublish' then
    perform app_private.announcement_tell(actor_user_id, item, 'cancelled', people);
  elsif target_action = 'remind' then
    -- One key per press: the day and which press it is (this one is already in the History).
    perform app_private.announcement_tell(actor_user_id, item, 'reminder', people,
      'remind:' || (now() at time zone item.time_zone)::date::text || ':' || (2 - app_private.announcement_reminders_left(item))::text);
  elsif target_action in ('unschedule', 'archive') then
    perform app_private.notification_resolve(w, 'announcement', item.id, 'closed', actor_user_id);
  end if;
  return jsonb_build_object('status', item.status, 'display_status', app_private.announcement_display_status(item),
    'announcement_id', item.id, 'revision', item.revision, 'archived_at', item.archived_at, 'told', told,
    'reminders_left_today', app_private.announcement_reminders_left(item));
end;
$$;


ALTER FUNCTION "public"."set_announcement_state_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid", "target_expected_revision" integer, "target_action" "text", "target_bring_back" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_document_publication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "expected_publication_revision" integer, "expected_preview_token" "text", "publish_reason" "text", "target_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d public.document_types%rowtype; preview jsonb; core_preview jsonb; result jsonb; r public.employee_onboarding_requirements%rowtype;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 if target_status is null or target_status not in ('draft','published') or nullif(btrim(publish_reason),'') is null or char_length(publish_reason)>500 then raise exception 'Valid publication status and reason required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,52001));
 select * into d from public.document_types where id=target_document_type_id and workspace_id=target_workspace_id for update;
 if d.id is null then raise exception 'document type not found' using errcode='P0002'; end if;
 if d.lifecycle_revision is distinct from expected_revision or d.publication_revision is distinct from expected_publication_revision or d.publication_status=target_status then raise exception 'Document publication changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 -- Assignment mutations use this same tenant advisory lock. Lock cases before requirements, as Submit/review do.
 perform 1 from public.employee_profiles where workspace_id=target_workspace_id order by id for update;
 perform 1 from public.employee_onboarding_cases where workspace_id=target_workspace_id order by id for update;
 perform 1 from public.employee_onboarding_requirements where workspace_id=target_workspace_id and source_id=d.id and kind='document' order by id for update;
 perform 1 from public.departments where workspace_id=target_workspace_id order by id for share;
 perform 1 from public.employee_location_assignments where workspace_id=target_workspace_id order by id for share;
 preview:=public.preview_document_publication_service(actor_user_id,target_workspace_id,d.id);
 if preview->>'preview_token' is distinct from expected_preview_token then raise exception 'Document publication impact changed; refresh preview' using errcode='PT409',hint='document.changed'; end if;
 if target_status='published' then
  update public.document_types set publication_status='published',publication_revision=publication_revision+1,published_at=now() where id=d.id;
  core_preview:=app_private.preview_lifecycle_definition(actor_user_id,target_workspace_id,d.id,'document');
  result:=app_private.apply_lifecycle_definition(actor_user_id,target_workspace_id,d.id,d.lifecycle_revision,core_preview->>'preview_token',publish_reason,'document');
  update public.employee_onboarding_requirements set publication_paused_at=null,lifecycle_revision=lifecycle_revision+1 where workspace_id=target_workspace_id and source_id=d.id and kind='document' and publication_paused_at is not null and (lifecycle_exempt or lifecycle_closed_at is not null or lifecycle_retired_at is not null or lifecycle_assignment_disabled or status='superseded');
  for r in select * from public.employee_onboarding_requirements where workspace_id=target_workspace_id and source_id=d.id and kind='document'
   and owner_excused and lifecycle_retired_at is null and not app_private.employee_record_is_workspace_owner(workspace_id,employee_id) loop
   perform app_private.set_document_exemption(r,actor_user_id,false,'No longer the owner',r.lifecycle_revision);
  end loop;
 else
  update public.document_types set publication_status='draft',publication_revision=publication_revision+1 where id=d.id;
  for r in update public.employee_onboarding_requirements set publication_paused_at=now(),deadline_at=null,document_suspended_at=null,lifecycle_revision=lifecycle_revision+1,updated_at=now()
   where workspace_id=target_workspace_id and source_id=d.id and kind='document' and lifecycle_retired_at is null and lifecycle_closed_at is null and not lifecycle_exempt and not lifecycle_assignment_disabled returning * loop
   perform app_private.document_audit(r,actor_user_id,'document.publication_paused',jsonb_build_object('reason',btrim(publish_reason),'publication_revision',d.publication_revision+1));
  end loop;
  result:=jsonb_build_object('paused',jsonb_array_length(preview->'employees'));
 end if;
 insert into public.audit_events(workspace_id,actor_user_id,action,target_type,target_id,metadata)
 values(target_workspace_id,actor_user_id,case when target_status='published' then 'document_type.published' else 'document_type.unpublished' end,'document_type',d.id::text,jsonb_build_object('reason',btrim(publish_reason),'definition_revision',d.lifecycle_revision,'publication_revision',d.publication_revision+1,'impact',preview->'employees'));
 return result||jsonb_build_object('publication_status',target_status,'publication_revision',d.publication_revision+1);
end;
$$;


ALTER FUNCTION "public"."set_document_publication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "expected_publication_revision" integer, "expected_preview_token" "text", "publish_reason" "text", "target_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_document_type_archived_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "should_archive" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  d public.document_types%rowtype;
  preview jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  -- Same tenant lock and row order as set_document_publication_service.
  perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text, 52001));
  select * into d from public.document_types
  where id = target_document_type_id and workspace_id = target_workspace_id
  for update;
  if d.id is null then
    raise exception 'document type not found' using errcode = 'P0002';
  end if;

  if should_archive and d.archived_at is null and d.publication_status = 'published' then
    preview := public.preview_document_publication_service(actor_user_id, target_workspace_id, d.id);
    perform public.set_document_publication_service(
      actor_user_id, target_workspace_id, d.id,
      d.lifecycle_revision, d.publication_revision, preview->>'preview_token',
      'Archived', 'draft'
    );
  end if;

  update public.document_types
  set archived_at = case when should_archive then now() else null end,
      updated_at = now()
  where id = d.id;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id,
    actor_id,
    case when should_archive then 'document_type.archived' else 'document_type.restored' end,
    'document_type',
    d.id::text,
    jsonb_build_object('title', d.title)
  );
end;
$$;


ALTER FUNCTION "public"."set_document_type_archived_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "should_archive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_employee_archived_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "should_archive" boolean, "restore_access" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  employee_user_id uuid;
  member public.workspace_memberships%rowtype;
  reopened public.workspace_memberships%rowtype;
  snapshot public.employee_access_snapshots%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.archive', target_person => target_employee_id);

  select user_id into employee_user_id
  from public.employee_profiles
  where id = target_employee_id and workspace_id = target_workspace_id
  for update;

  if not should_archive and restore_access then
    select * into snapshot
    from public.employee_access_snapshots
    where employee_id = target_employee_id and restored_at is null
    order by captured_at desc
    limit 1
    for update;
    if snapshot.id is null then
      raise exception 'restorable access snapshot not found' using errcode = 'P0002';
    end if;
    select * into reopened
    from public.workspace_memberships
    where id = snapshot.membership_id and workspace_id = target_workspace_id;
    -- Only the account still linked to the record is reopened: once a rehire
    -- restore detached it, reopening would hand its role to an account no
    -- record stands for (nf-guvenlik Y1).
    if employee_user_id is null or reopened.user_id is distinct from employee_user_id then
      raise exception 'employee has no linked workspace account' using errcode = '22023';
    end if;
    if not exists (
      select 1 from public.workspace_roles
      where id = snapshot.role_id and workspace_id = target_workspace_id
    ) then
      raise exception 'snapshotted role is no longer available' using errcode = '22023';
    end if;
    -- Giving the account back is the twin of taking it away, and hands out the
    -- role it had: both asked of the membership it reopens.
    perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.remove_access',
      target_user => reopened.user_id);
    perform app_private.authorize_role_grant(actor_user_id, target_workspace_id, snapshot.role_id,
      target_user => reopened.user_id);
  end if;

  select * into member
  from public.workspace_memberships
  where workspace_id = target_workspace_id and user_id = employee_user_id;

  if should_archive and member.id is not null and member.status in ('active', 'pending_activation') then
    insert into public.employee_access_snapshots (workspace_id, employee_id, membership_id, role_id, captured_by)
    values (target_workspace_id, target_employee_id, member.id, coalesce(member.role_id, member.employee_role_id), actor_user_id);

    update public.workspace_memberships
    set status = 'suspended'::public.membership_status, updated_at = now()
    where id = member.id;
  end if;

  update public.employee_profiles
  set archived_at = case when should_archive then now() else null end,
      archived_by = case when should_archive then actor_user_id else null end,
      user_id = case
        when not should_archive and not restore_access and employee_user_id is not null then null
        else user_id
      end,
      revision = revision + 1,
      updated_at = now()
  where id = target_employee_id;

  if not should_archive and restore_access then
    perform set_config('app.membership_change', snapshot.membership_id::text, true);
    update public.workspace_memberships
    set status = 'active'::public.membership_status, updated_at = now()
    where id = snapshot.membership_id;

    update public.employee_access_snapshots set restored_at = now() where id = snapshot.id;
  end if;

  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (
    target_workspace_id,
    target_employee_id,
    actor_user_id,
    case when should_archive then 'employee.archived' else 'employee.restored' end,
    case
      when should_archive then 'Employee archived and linked access suspended'
      when restore_access then 'Employee record and access restored'
      else 'Employee record restored for rehire'
    end
  );

  -- Archived with access: the person hears it ended. Restored with access: the person and who may publish
  -- where they work (access_tell_ended, access_tell_restored).
  if should_archive and member.id is not null and member.status in ('active', 'pending_activation') then
    perform app_private.access_tell_ended(target_workspace_id, target_employee_id, employee_user_id, member.id, actor_user_id);
  elsif should_archive then
    perform app_private.access_tell_ended(target_workspace_id, target_employee_id, null, null, actor_user_id);
  elsif not should_archive and restore_access then
    perform app_private.access_tell_restored(target_workspace_id, target_employee_id, reopened.user_id, actor_user_id);
  end if;
end;
$$;


ALTER FUNCTION "public"."set_employee_archived_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "should_archive" boolean, "restore_access" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_employee_document_exemption_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "make_exempt" boolean, "exemption_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'documents.review',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id));
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and workspace_id=target_workspace_id and kind='document' for update;
 if r.id is null then raise exception 'document unavailable' using errcode='P0002'; end if;
 return app_private.set_document_exemption(r,actor_user_id,make_exempt,exemption_reason,expected_revision);
end;
$$;


ALTER FUNCTION "public"."set_employee_document_exemption_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "make_exempt" boolean, "exemption_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_employee_document_timezone_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_employee_revision" integer, "reference_timezone" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r public.employee_onboarding_requirements%rowtype; e public.employee_profiles%rowtype;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'employee.save',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id));
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 select * into r from public.employee_onboarding_requirements where workspace_id=target_workspace_id and id=target_requirement_id;
 if r.id is null then raise exception 'document unavailable' using errcode='P0002'; end if;
 select * into e from public.employee_profiles where id=r.employee_id and workspace_id=r.workspace_id for update;
 if e.revision is distinct from expected_employee_revision then raise exception 'employee changed; refresh required' using errcode='PT409',hint='employee.revision_conflict'; end if;
 if not (e.is_remote or e.is_excluded_from_schedule) or app_private.time_off_timezone(e.workspace_id,e.id) is not null
 then raise exception 'an active location controls the document timezone' using errcode='22023'; end if;
 if reference_timezone is null or not (reference_timezone='UTC' or reference_timezone~'^[A-Za-z_]+/[A-Za-z0-9_+/-]+$') or not exists(select 1 from pg_catalog.pg_timezone_names where name=reference_timezone)
 then raise exception 'valid IANA timezone required' using errcode='22023'; end if;
 if e.document_timezone=reference_timezone then return e.revision; end if;
 update public.employee_profiles set document_timezone=reference_timezone,revision=revision+1,updated_at=now() where id=e.id returning revision into expected_employee_revision;
 perform app_private.document_audit(r,actor_user_id,'document.reference_timezone_changed',jsonb_build_object('previous',e.document_timezone,'timezone',reference_timezone,'employee_revision',expected_employee_revision));
 return expected_employee_revision;
end;
$_$;


ALTER FUNCTION "public"."set_employee_document_timezone_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_employee_revision" integer, "reference_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_onboarding_approval_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "approval_required" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  waiting record;
  activated integer := 0;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.organization.write');
  if approval_required is null then
    raise exception 'Choose whether new people wait for approval' using errcode = '22023';
  end if;

  -- The row is the lock: two changes of one workspace's setting run one after the other.
  insert into public.employee_onboarding_settings as setting (workspace_id, final_approval_required, updated_by, updated_at)
  values (target_workspace_id, approval_required, actor_user_id, now())
  on conflict (workspace_id) do update
    set final_approval_required = excluded.final_approval_required,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at;

  update public.employee_onboarding_cases c
  set final_approval_required = approval_required, updated_at = now()
  where c.workspace_id = target_workspace_id
    and c.status <> 'approved'::public.employee_onboarding_case_status
    and c.final_approval_required is distinct from approval_required;

  if not approval_required then
    -- Waiting for approval alone: finished (submitted), not in yet, and nothing activation asks for left
    -- (the same two checks app_private.activate_employee_onboarding_case makes before it lets anyone in).
    for waiting in
      select c.id, c.employee_id
      from public.employee_onboarding_cases c
      join public.workspace_memberships m on m.id = c.membership_id
      where c.workspace_id = target_workspace_id
        and c.status = 'submitted'::public.employee_onboarding_case_status
        and m.status = 'pending_activation'
        and not exists (
          select 1 from public.employee_onboarding_requirements r
          where r.case_id = c.id and app_private.document_activation_blocked(r))
        and not exists (
          select 1 from public.employee_onboarding_requirements r
          where r.case_id = c.id
            and (r.kind <> 'document' or (r.publication_paused_at is null and not r.lifecycle_exempt
                 and r.lifecycle_closed_at is null and r.status <> 'superseded'))
            and r.required and r.blocks_activation
            and r.status <> 'completed'::public.employee_onboarding_requirement_status)
      order by c.id
      for update of c
    loop
      perform app_private.activate_employee_onboarding_case(waiting.id, actor_user_id, 'employee.auto_activated');
      insert into public.onboarding_events (workspace_id, employee_id, case_id, actor_user_id, action, target_type, target_id, metadata)
      values (target_workspace_id, waiting.employee_id, waiting.id, actor_user_id,
        'onboarding.activate', 'onboarding_case', waiting.id::text,
        jsonb_build_object('source', 'approval_setting_off'));
      activated := activated + 1;
    end loop;
  end if;

  insert into public.audit_events (workspace_id, actor_user_id, action, target_type, target_id, metadata)
  values (target_workspace_id, actor_user_id, 'onboarding.approval_setting_changed', 'workspace', target_workspace_id::text,
    jsonb_build_object('final_approval_required', approval_required, 'activated', activated));

  return jsonb_build_object('final_approval_required', approval_required);
end;
$$;


ALTER FUNCTION "public"."set_onboarding_approval_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "approval_required" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_signature_retention_policy_archived_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_policy_id" "uuid", "should_archive" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  target_name text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  update public.signature_retention_policies
  set archived_at = case when should_archive then now() else null end,
      updated_at = now()
  where id = target_policy_id and workspace_id = target_workspace_id
  returning name into target_name;
  if target_name is null then
    raise exception 'retention policy not found' using errcode = 'P0002';
  end if;
  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id, actor_id,
    case when should_archive then 'signature_retention_policy.archived' else 'signature_retention_policy.restored' end,
    'signature_retention_policy', target_policy_id::text,
    jsonb_build_object('name', target_name)
  );
end;
$$;


ALTER FUNCTION "public"."set_signature_retention_policy_archived_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_policy_id" "uuid", "should_archive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_signature_template_archived_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "should_archive" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  target_name text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  update public.signature_templates
  set archived_at = case when should_archive then now() else null end,
      updated_at = now()
  where id = target_template_id and workspace_id = target_workspace_id
  returning name into target_name;
  if target_name is null then
    raise exception 'acknowledgement template not found' using errcode = 'P0002';
  end if;
  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id, actor_id,
    case when should_archive then 'signature_template.archived' else 'signature_template.restored' end,
    'signature_template', target_template_id::text,
    jsonb_build_object('name', target_name)
  );
end;
$$;


ALTER FUNCTION "public"."set_signature_template_archived_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "should_archive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_assert_session"("w" "uuid", "sid" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare shift record; base_created timestamptz; week date;
begin
 select created_at,week_start into base_created,week from public.schedule_edit_sessions where workspace_id=w and id=sid;
 for shift in select distinct p.* from public.shift_exchange_cases c
  join public.schedule_published_shifts p on p.workspace_id=w and coalesce(p.source_shift_id,p.id) in(c.offered_source_id,c.requested_source_id)
  join public.schedule_location_publications pub on pub.id=p.publication_id and pub.status='current'
  where c.workspace_id=w and c.status='completed' and c.updated_at>base_created and p.scheduled_date between week and week+6
  and exists(select 1 from public.schedule_edit_session_shifts scope where scope.session_id=sid and scope.location_id=p.location_id)
 loop
  if not exists(select 1 from public.schedule_edit_session_shifts d where d.session_id=sid
   and (d.id in(shift.id,shift.source_shift_id) or d.source_published_shift_id=shift.id)
   and d.pending_op_type is distinct from 'delete'
   and public.shift_exchange_edit_matches(to_jsonb(d),to_jsonb(shift))) then
   raise exception 'An approved shift change conflicts with this edit session. Rebase the affected shift before saving; your other edits are preserved.' using errcode='PT409';
  end if;
 end loop;
end; $$;


ALTER FUNCTION "public"."shift_exchange_assert_session"("w" "uuid", "sid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_draft_undoes"("w" "uuid", "draft" "uuid", "locations" "uuid"[], "departments" "uuid"[] DEFAULT NULL::"uuid"[], "include_no_department" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
 select coalesce(jsonb_agg(jsonb_build_object(
   'id','shift_exchange_undone:'||x.shift_id,'code','shift_exchange_undone',
   'severity','hard','overrideable',false,'tier','blocker','introduced',true,
   'location_id',x.location_id,'location_name',x.location_name,
   'employee_id',x.to_id,'employee_name',x.to_name,
   'scheduled_date',x.scheduled_date,'start_time',to_char(x.start_time,'HH24:MI'),'end_time',to_char(x.end_time,'HH24:MI'),
   'shift_ids',coalesce(to_jsonb(x.draft_ids),'[]'::jsonb),
   'exchange_case_id',x.case_id,'exchange_kind',x.kind,
   'from_employee_id',x.from_id,'from_employee_name',x.from_name,
   'to_employee_id',x.to_id,'to_employee_name',x.to_name,
   'draft_employee_id',x.draft_employee_id,'draft_employee_name',x.draft_employee_name,
   'message','This shift was '||case x.kind when 'swap' then 'swapped' else 'handed over' end||' from '||coalesce(x.from_name,'a teammate')
      ||' to '||coalesce(x.to_name,'a teammate')||' after the schedule was last published, and this draft does not have it. Publishing would undo it.')
  order by x.scheduled_date,x.start_time,x.shift_id),'[]'::jsonb)
 from (
  select distinct on (p.id) p.id shift_id,p.location_id,l.name location_name,p.scheduled_date,p.start_time,p.end_time,
   c.id case_id,c.kind,
   -- Who held it when the change was asked: the offered side's owner, or on
   -- a swap's requested side the teammate who gave it.
   nullif(case when coalesce(p.source_shift_id,p.id)=c.offered_source_id then c.offered_snapshot else c.requested_snapshot end->>'employee_id','')::uuid from_id,
   nullif(case when coalesce(p.source_shift_id,p.id)=c.offered_source_id then c.offered_snapshot else c.requested_snapshot end->>'employee_name','') from_name,
   p.employee_id to_id,nullif(concat_ws(' ',coalesce(nullif(e.preferred_name,''),e.first_name),e.last_name),'') to_name,
   own.ids draft_ids,own.employee_id draft_employee_id,own.employee_name draft_employee_name
  from public.shift_exchange_cases c
  join public.schedule_published_shifts p on p.workspace_id=w and coalesce(p.source_shift_id,p.id) in (c.offered_source_id,c.requested_source_id)
  -- The week's latest publication at that place, live or taken down (BL-230):
  -- taking a week down does not undo an approved change either.
  join public.schedule_location_publications pub on pub.id=p.publication_id
   and pub.version_number=(select max(latest.version_number) from public.schedule_location_publications latest
    where latest.location_id=pub.location_id and latest.week_start=pub.week_start)
  join public.schedule_drafts dr on dr.id=draft and dr.workspace_id=w
  join public.locations l on l.id=p.location_id and l.workspace_id=w
  left join public.employee_profiles e on e.id=p.employee_id and e.workspace_id=w
  -- The draft's copy of this shift: the same row, or else a row in the same
  -- slot (place, job, day, hours), e.g. a draft written after the change.
  left join lateral (
   select array[d.id] ids,d.employee_id,
    nullif(concat_ws(' ',coalesce(nullif(de.preferred_name,''),de.first_name),de.last_name),'') employee_name
   from public.schedule_draft_shifts d
   left join public.employee_profiles de on de.id=d.employee_id and de.workspace_id=w
   where d.workspace_id=w and d.draft_id=draft and (d.id in (p.id,p.source_shift_id)
    or (d.location_id,d.job_id,d.scheduled_date,d.start_time,d.end_time) is not distinct from (p.location_id,p.job_id,p.scheduled_date,p.start_time,p.end_time))
   order by d.id in (p.id,p.source_shift_id) desc,d.id limit 1
  ) own on true
  -- c.updated_at is when the change was decided (BL-228).
  where c.workspace_id=w and c.status='completed' and c.updated_at>pub.published_at
   and p.location_id=any(locations)
   and p.scheduled_date between dr.week_start and dr.week_start+6
   and public.schedule_shift_in_department_scope_service(p.job_id,departments,coalesce(include_no_department,true))
   and not exists (select 1 from public.schedule_draft_shifts d where d.workspace_id=w and d.draft_id=draft
    and public.shift_exchange_edit_matches(to_jsonb(d),to_jsonb(p)))
  order by p.id,c.updated_at desc
 ) x;
$$;


ALTER FUNCTION "public"."shift_exchange_draft_undoes"("w" "uuid", "draft" "uuid", "locations" "uuid"[], "departments" "uuid"[], "include_no_department" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_edit_matches"("a" "jsonb", "b" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select (a->>'employee_id',a->>'location_id',a->>'job_id',a->>'shift_type_id',
  coalesce(a->>'scheduled_date',a->>'date'),(a->>'start_time')::time,(a->>'end_time')::time,
  coalesce((a->>'unpaid_break_minutes')::integer,0),a->>'time_basis',a->'time_snapshot',a->>'time_timezone')
 is not distinct from
 (b->>'employee_id',b->>'location_id',b->>'job_id',b->>'shift_type_id',
  coalesce(b->>'scheduled_date',b->>'date'),(b->>'start_time')::time,(b->>'end_time')::time,
  coalesce((b->>'unpaid_break_minutes')::integer,0),b->>'time_basis',b->'time_snapshot',b->>'time_timezone');
$$;


ALTER FUNCTION "public"."shift_exchange_edit_matches"("a" "jsonb", "b" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_emit"("actor" "uuid", "w" "uuid", "cid" "uuid", "aid" "uuid", "act" "text", "msg" "text", "private_msg" "text" DEFAULT ''::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.shift_exchange_cases c where c.id = cid and c.owner_id is null) then
    msg := case act
      when 'application_submitted' then 'A teammate asked for this open shift. A manager decides.'
      when 'expired' then 'This offer closed 4 hours before the shift. The shift stays open.'
      when 'invalidated' then 'The shift changed, so this offer ended. The shift stays open.'
      when 'transfer_completed' then 'A manager approved. The teammate who asked now works this shift.'
      when 'case_closed' then replace(msg, 'A manager closed this request. The owner keeps this shift.', 'A manager closed this offer. The shift stays open.')
      else msg end;
  end if;
  -- The case's history (Shift Hub, Requests): one row per step.
  insert into public.shift_exchange_events(workspace_id,case_id,application_id,actor_user_id,action,message,private_note)
  values(w,cid,aid,actor,act,msg,private_msg);
  -- And the people the step changes (TAKAS-BILDIRIM).
  perform app_private.shift_exchange_tell(actor, w, cid, aid, act);
end; $$;


ALTER FUNCTION "public"."shift_exchange_emit"("actor" "uuid", "w" "uuid", "cid" "uuid", "aid" "uuid", "act" "text", "msg" "text", "private_msg" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_fingerprint"("w" "uuid", "s" "jsonb", "t" "jsonb") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
 select md5(jsonb_build_object('offered',public.shift_exchange_terms(s),'requested',public.shift_exchange_terms(t))::text);
$$;


ALTER FUNCTION "public"."shift_exchange_fingerprint"("w" "uuid", "s" "jsonb", "t" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_guard_commit_deadline"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if clock_timestamp()>=new.expires_at then
  raise exception 'This request closed 4 hours before the shift, before this approval could finish. No transfer was made. Refresh the request.' using errcode='PT409';
 end if;
 return new;
end;
$$;


ALTER FUNCTION "public"."shift_exchange_guard_commit_deadline"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_guard_eligibility_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare workspaces uuid[]; w uuid;
begin
 if tg_op='INSERT' then workspaces:=array[new.workspace_id];
 elsif tg_op='DELETE' then workspaces:=array[old.workspace_id];
 else workspaces:=array[old.workspace_id,new.workspace_id]; end if;
 for w in select distinct value from unnest(workspaces) value where value is not null order by value loop
  -- The same lock is held by a Shift Hub approval and by a publication.
  if not pg_try_advisory_xact_lock(hashtextextended(w::text,921)) then
   raise exception 'Another change is being saved in this workspace. Your changes were not saved; try again.' using errcode='PT409';
  end if;
 end loop;
 if tg_op='DELETE' then return old; end if;
 return new;
end; $$;


ALTER FUNCTION "public"."shift_exchange_guard_eligibility_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_live_status"("w" "uuid", "cid" "uuid") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare c public.shift_exchange_cases%rowtype; s jsonb; t jsonb;
begin
 select * into c from public.shift_exchange_cases where workspace_id=w and id=cid;
 if c.status<>'open' then return c.status; end if;
 if c.expires_at<=clock_timestamp() then return 'expired'; end if;
 s:=public.shift_exchange_shift(w,c.offered_source_id); t:=public.shift_exchange_shift(w,c.requested_source_id);
 if s is null or (c.kind='swap' and t is null) or public.shift_exchange_fingerprint(w,s,t) is distinct from c.consent_fingerprint then return 'invalidated'; end if;
 return 'open';
end; $$;


ALTER FUNCTION "public"."shift_exchange_live_status"("w" "uuid", "cid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_preview"("actor" "uuid", "w" "uuid", "cid" "uuid", "aid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.shift_exchange_cases%rowtype; a public.shift_exchange_applications%rowtype;
 s jsonb; t jsonb; r jsonb; g jsonb; problems text[]:='{}'; loc uuid; scoped boolean:=false; missing boolean:=false; fp text;
begin
 select * into c from public.shift_exchange_cases where workspace_id=w and id=cid;
 if c.id is null then raise exception 'Request not found' using errcode='P0002'; end if;
 s:=public.shift_exchange_shift(w,c.offered_source_id); t:=public.shift_exchange_shift(w,c.requested_source_id);
 for loc in select distinct x from unnest(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid]) x where x is not null loop
  scoped:=scoped or app_private.authz_reason(actor,w,'exchange.approve',array[loc]) is null;
 end loop;
 if not scoped then perform app_private.authorize(actor,w,'exchange.approve',array[(c.offered_snapshot->>'location_id')::uuid]); end if;
 select * into a from public.shift_exchange_applications where workspace_id=w and case_id=cid and id=aid;
 if a.id is null then raise exception 'Application not found' using errcode='P0002'; end if;
 if c.status<>'open' or a.status<>'pending_manager' then problems:=array_append(problems,'This request is no longer ready for approval'); end if;
 if s is null or (c.kind='swap' and t is null) then problems:=array_append(problems,'The published shift changed or was unpublished'); end if;
 fp:=public.shift_exchange_fingerprint(w,s,t);
 if fp is distinct from c.consent_fingerprint or fp is distinct from a.consent_fingerprint then problems:=array_append(problems,'Shift conditions changed. New employee consent is required'); end if;
 if c.expires_at<=clock_timestamp() then problems:=array_append(problems,'This request closed 4 hours before the shift');
 elsif (s->>'starts_at')::timestamptz<=clock_timestamp() or (t->>'starts_at')::timestamptz<=clock_timestamp() then problems:=array_append(problems,'This shift has already started'); end if;
 -- Nobody decides their own, but the owner whom nobody else can answer (KARARLAR S-164, S-169).
 if not exists(select 1 from unnest(array_remove(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid],null)) x
  where app_private.exchange_decision_reason(actor,w,c.owner_id,a.employee_id,x) is null) then
  problems:=array_append(problems,'A separate manager must approve your own exchange'); end if;
 if s is not null then r:=app_private.eligibility(w,a.employee_id,s,jsonb_build_object('operation',case when c.kind='swap' then 'swap' when c.audience='direct' then 'cover_accept' else 'release_pickup' end,'excluded',to_jsonb(array_remove(array[(s->>'id')::uuid,(t->>'id')::uuid],null)),'with_measures',true)); end if;
 if r is null then r:='{"status":"ineligible","reasons":["Published shift unavailable"]}'; end if;
 if r->>'status'<>'eligible' then problems:=array_append(problems,'The receiving employee is not eligible for the full shift'); end if;
 if c.kind='swap' and t is not null then
  g:=app_private.eligibility(w,c.owner_id,t,jsonb_build_object('operation','swap','excluded',jsonb_build_array(s->>'id',t->>'id'),'with_measures',true));
  if g->>'status'<>'eligible' then problems:=array_append(problems,'The other employee is not eligible for the exchanged shift'); end if;
 end if;
 for loc in select distinct x from unnest(array[(s->>'location_id')::uuid,(t->>'location_id')::uuid]) x where x is not null loop
  if app_private.exchange_decision_reason(actor,w,c.owner_id,a.employee_id,loc) is not null
   and not exists(select 1 from public.shift_exchange_votes v where v.case_id=cid and v.application_id=aid and v.location_id=loc and v.fingerprint=fp
   and app_private.exchange_decision_reason(v.actor_user_id,w,c.owner_id,a.employee_id,loc) is null
   and not exists(select 1 from public.employee_profiles e where e.workspace_id=w and e.user_id=v.actor_user_id and e.id in(c.owner_id,a.employee_id))) then missing:=true; end if;
 end loop;
 return jsonb_build_object('allowed',cardinality(problems)=0,'fingerprint',fp,'reasons',to_jsonb(problems),'receiver',r,'giver',g,'requires_other_manager',missing,
 'other_applications',(select count(*) from public.shift_exchange_applications where case_id=cid and id<>aid and status in('invited','pending_manager')));
end; $$;


ALTER FUNCTION "public"."shift_exchange_preview"("actor" "uuid", "w" "uuid", "cid" "uuid", "aid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_rebase_drafts"("w" "uuid", "s" "jsonb", "recipient" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
 with changed as (
  update public.schedule_draft_shifts d set employee_id=recipient,revision=revision+1,updated_at=now()
  where d.workspace_id=w and d.id in((s->>'source_id')::uuid,(s->>'id')::uuid)
   and public.shift_exchange_edit_matches(to_jsonb(d),s) returning d.draft_id
 ) update public.schedule_drafts set revision=revision+1,updated_at=now() where id in(select draft_id from changed);
 with changed as (
  update public.schedule_edit_session_shifts d set employee_id=recipient,revision=revision+1,updated_at=now()
  where d.workspace_id=w and (d.id in((s->>'source_id')::uuid,(s->>'id')::uuid) or d.source_published_shift_id=(s->>'id')::uuid)
   and public.shift_exchange_edit_matches(to_jsonb(d),s) and d.pending_op_type is distinct from 'delete' returning d.session_id
 ) update public.schedule_edit_sessions set revision=revision+1 where id in(select session_id from changed);
 -- DB-1c: Undo does not take the swap back.
 perform app_private.schedule_edit_undo_barrier();
end; $$;


ALTER FUNCTION "public"."shift_exchange_rebase_drafts"("w" "uuid", "s" "jsonb", "recipient" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_reconcile_batch"("actor" "uuid", "w" "uuid", "changes" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare s jsonb;
begin
 for s in select * from jsonb_array_elements(changes) loop
  perform public.shift_exchange_rebase_drafts(w,s,(s->>'new_employee_id')::uuid);
 end loop;
end; $$;


ALTER FUNCTION "public"."shift_exchange_reconcile_batch"("actor" "uuid", "w" "uuid", "changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_schedule_recovery_service"("actor" "uuid", "w" "uuid", "sid" "uuid", "expected_fingerprint" "text" DEFAULT NULL::"text", "idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare sess public.schedule_edit_sessions%rowtype; ps record; draft public.schedule_edit_session_shifts%rowtype;
 changes jsonb:='[]'; current_shift jsonb; result jsonb; fp text; command jsonb; prior public.shift_exchange_commands%rowtype;
 row_id uuid; edited_name text;
begin
 perform pg_advisory_xact_lock(hashtextextended(w::text,921));
 select * into sess from public.schedule_edit_sessions where workspace_id=w and id=sid for update;
 if sess.id is null or sess.holder_user_id<>actor then raise exception 'Your edit session was not found' using errcode='42501',hint='authz.out_of_scope'; end if;
 if sess.expires_at<=now() then raise exception 'This edit session expired. Reopen it before reviewing assignments' using errcode='PT409'; end if;
 -- BL-189: the edit's locations, asked of the core.
 perform app_private.authorize(actor,w,'schedule.edit',array(select distinct d.location_id from public.schedule_edit_session_shifts d where d.session_id=sid));
 command:=jsonb_build_object('action','recover_schedule','session_id',sid,'fingerprint',expected_fingerprint);
 if expected_fingerprint is not null then
  if idempotency_key is null then raise exception 'Idempotency key required' using errcode='22023'; end if;
  select * into prior from public.shift_exchange_commands c where c.workspace_id=w and c.actor_user_id=actor and c.idempotency_key=shift_exchange_schedule_recovery_service.idempotency_key;
  if prior.workspace_id is not null then
   if prior.command is distinct from command then raise exception 'Idempotency key already used' using errcode='22023'; end if;
   return prior.result;
  end if;
 end if;
 for ps in
  select distinct p.* from public.shift_exchange_cases c
  join public.schedule_published_shifts p on p.workspace_id=w and coalesce(p.source_shift_id,p.id) in(c.offered_source_id,c.requested_source_id)
  join public.schedule_location_publications pub on pub.id=p.publication_id and pub.status='current'
  where c.workspace_id=w and c.status='completed' and c.updated_at>sess.created_at
   and p.scheduled_date between sess.week_start and sess.week_start+6
   and exists(select 1 from public.schedule_edit_session_shifts scope where scope.session_id=sid and scope.location_id=p.location_id)
  order by p.id
 loop
  perform app_private.authorize(actor,w,'schedule.edit',array[ps.location_id]);
  select * into draft from public.schedule_edit_session_shifts d where d.workspace_id=w and d.session_id=sid
   and (d.id in(ps.id,ps.source_shift_id) or d.source_published_shift_id=ps.id) order by d.id limit 1;
  if draft.id is not null and draft.pending_op_type is distinct from 'delete' and public.shift_exchange_edit_matches(to_jsonb(draft),to_jsonb(ps)) then continue; end if;
  current_shift:=public.shift_exchange_shift(w,ps.id)||jsonb_build_object('shift_type_name',(select name from public.shift_types where id=ps.shift_type_id and workspace_id=w));
  select coalesce(nullif(preferred_name,''),concat_ws(' ',first_name,last_name)) into edited_name from public.employee_profiles where workspace_id=w and id=draft.employee_id;
  changes:=changes||jsonb_build_array(jsonb_build_object('current',current_shift,'session_shift_id',draft.id,'edited_revision',draft.revision,
   'edited_employee_name',edited_name,'edited_start_time',draft.start_time,'edited_end_time',draft.end_time,
   'edited_job_name',(select name from public.jobs where id=draft.job_id and workspace_id=w),
   'edited_shift_type_name',(select name from public.shift_types where id=draft.shift_type_id and workspace_id=w),
   'edited_timezone',draft.time_timezone,'edited_unpaid_break_minutes',draft.unpaid_break_minutes,
   'removed',draft.id is null or draft.pending_op_type='delete'));
 end loop;
 fp:=md5(jsonb_build_object('session_id',sid,'revision',sess.revision,'changes',changes)::text);
 if expected_fingerprint is null then return jsonb_build_object('session_id',sid,'session_revision',sess.revision,'fingerprint',fp,'changes',changes); end if;
 if fp is distinct from expected_fingerprint then raise exception 'Schedule or your edits changed. Review the latest comparison' using errcode='PT409'; end if;
 for current_shift in select x->'current' from jsonb_array_elements(changes) x loop
  select * into ps from public.schedule_published_shifts where workspace_id=w and id=(current_shift->>'id')::uuid;
  select id into row_id from public.schedule_edit_session_shifts d where d.workspace_id=w and d.session_id=sid
   and (d.id in(ps.id,ps.source_shift_id) or d.source_published_shift_id=ps.id) order by d.id limit 1;
  if row_id is null then
   insert into public.schedule_edit_session_shifts(id,workspace_id,session_id,location_id,employee_id,job_id,shift_type_id,scheduled_date,start_time,end_time,time_basis,time_snapshot,time_timezone,unpaid_break_minutes,hide_time_on_badge,note,source_published_shift_id,label_ids,label_names)
   values(ps.id,w,sid,ps.location_id,ps.employee_id,ps.job_id,ps.shift_type_id,ps.scheduled_date,ps.start_time,ps.end_time,ps.time_basis,ps.time_snapshot,ps.time_timezone,ps.unpaid_break_minutes,ps.hide_time_on_badge,ps.note,ps.id,ps.label_ids,ps.label_names);
  else
   update public.schedule_edit_session_shifts set location_id=ps.location_id,employee_id=ps.employee_id,job_id=ps.job_id,shift_type_id=ps.shift_type_id,
    scheduled_date=ps.scheduled_date,start_time=ps.start_time,end_time=ps.end_time,time_basis=ps.time_basis,time_snapshot=ps.time_snapshot,time_timezone=ps.time_timezone,
    unpaid_break_minutes=ps.unpaid_break_minutes,source_published_shift_id=ps.id,pending_op_type=null,revision=revision+1,updated_at=now()
    where workspace_id=w and session_id=sid and id=row_id;
  end if;
 end loop;
 if jsonb_array_length(changes)>0 then
  update public.schedule_edit_sessions set revision=revision+1,dirty=true,last_heartbeat=now(),expires_at=now()+interval '4 minutes' where id=sid;
 end if;
 -- EKRAN-01 Undo: the restore is not a step; Undo does not take it back.
 perform app_private.schedule_edit_undo_barrier();
 result:=public.get_schedule_edit_session_service(actor,w,sid);
 insert into public.shift_exchange_commands(workspace_id,actor_user_id,idempotency_key,command,result) values(w,actor,idempotency_key,command,result);
 return result;
end; $$;


ALTER FUNCTION "public"."shift_exchange_schedule_recovery_service"("actor" "uuid", "w" "uuid", "sid" "uuid", "expected_fingerprint" "text", "idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_shift"("w" "uuid", "source" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$

 select jsonb_build_object('id',s.id,'source_id',coalesce(s.source_shift_id,s.id),'location_id',s.location_id,'location_name',l.name,'timezone',coalesce(s.time_timezone,l.timezone),

 'requires_employee_access',true,'job_id',s.job_id,'job_name',coalesce(j.name,'Unassigned position'),'shift_type_id',s.shift_type_id,

 'unpaid_break_minutes',s.unpaid_break_minutes,'scheduled_date',s.scheduled_date,'date',s.scheduled_date,'time_basis',s.time_basis,'time_snapshot',s.time_snapshot,'time_timezone',s.time_timezone,'start_time',s.start_time,'end_time',s.end_time,

 'starts_at',lower(app_private.shift_time_range(s.scheduled_date,s.start_time,s.end_time,coalesce(s.time_timezone,l.timezone))),

 'ends_at',upper(app_private.shift_time_range(s.scheduled_date,s.start_time,s.end_time,coalesce(s.time_timezone,l.timezone))),

 'employee_id',s.employee_id,'employee_name',case when e.id is not null then coalesce(nullif(e.preferred_name,''),concat_ws(' ',e.first_name,e.last_name)) end)

 from public.schedule_published_shifts s join public.schedule_location_publications p on p.id=s.publication_id and p.status='current'

 join public.locations l on l.id=s.location_id left join public.jobs j on j.id=s.job_id left join public.employee_profiles e on e.id=s.employee_id

 where s.workspace_id=w and (s.id=source or coalesce(s.source_shift_id,s.id)=source) order by s.created_at desc limit 1;

$$;


ALTER FUNCTION "public"."shift_exchange_shift"("w" "uuid", "source" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchange_terms"("s" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select jsonb_build_object('time_basis',s->'time_basis','time_snapshot',s->'time_snapshot','time_timezone',s->'time_timezone','source',s->'source_id','owner',s->'employee_id','location',s->'location_id','job',s->'job_id','service',s->'shift_type_id','date',s->'date','start',s->'start_time','end',s->'end_time','unpaid_break_minutes',coalesce(s->'unpaid_break_minutes','0'::jsonb));
$$;


ALTER FUNCTION "public"."shift_exchange_terms"("s" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchanges_candidates_service"("actor" "uuid", "w" "uuid", "shift_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare emp public.employee_profiles%rowtype; s jsonb; t jsonb; e record; p record; checked jsonb; employees jsonb:='[]'; shifts jsonb:='[]';
begin
 emp:=public.employee_hub_actor_service(actor,w); s:=public.shift_exchange_shift(w,shift_id);
 if s is null or (s->>'employee_id')::uuid is distinct from emp.id then raise exception 'Only the owner can search for a replacement' using errcode='42501',hint='authz.out_of_scope'; end if;
 for e in select id,coalesce(nullif(preferred_name,''),concat_ws(' ',first_name,last_name)) name from public.employee_profiles where workspace_id=w and archived_at is null and id<>emp.id order by first_name loop
  checked:=app_private.eligibility(w,e.id,s,'{"operation":"cover_accept"}')-'approval_flags';
  -- A teammate's own marks stay theirs: the owner sees what they set aside, not when.
  checked:=jsonb_set(checked,'{acknowledgements}',coalesce((select jsonb_agg(jsonb_build_object('code',k->>'code'))
   from jsonb_array_elements(checked->'acknowledgements') k),'[]'::jsonb));
  if checked->>'status'='eligible' then employees:=employees||jsonb_build_array(jsonb_build_object('id',e.id,'name',e.name,'eligibility',checked)); end if;
 end loop;
 for p in select x.id from public.schedule_published_shifts x join public.schedule_location_publications pub on pub.id=x.publication_id and pub.status='current'
  where x.workspace_id=w and x.employee_id is not null and x.employee_id<>emp.id and x.scheduled_date between current_date-1 and current_date+62 order by x.scheduled_date,x.start_time loop
  t:=public.shift_exchange_shift(w,p.id);
  if (t->>'starts_at')::timestamptz>clock_timestamp() and app_private.eligibility(w,emp.id,t,jsonb_build_object('operation','swap','excluded',jsonb_build_array(s->>'id',t->>'id')))->>'status'='eligible'
   and app_private.eligibility(w,(t->>'employee_id')::uuid,s,jsonb_build_object('operation','swap','excluded',jsonb_build_array(s->>'id',t->>'id')))->>'status'='eligible' then shifts:=shifts||jsonb_build_array(t||jsonb_build_object('availability_warning',public.weekly_exchange_employee_warning(w,emp.id,t))); end if;
 end loop;
 return jsonb_build_object('employees',employees,'shifts',shifts);
end; $$;


ALTER FUNCTION "public"."shift_exchanges_candidates_service"("actor" "uuid", "w" "uuid", "shift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchanges_command_service"("actor" "uuid", "w" "uuid", "command" "jsonb", "idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare emp public.employee_profiles%rowtype; c public.shift_exchange_cases%rowtype; a public.shift_exchange_applications%rowtype;
 old_cmd public.shift_exchange_commands%rowtype; s jsonb; t jsonb; checked jsonb; result jsonb; fp text;
 action text:=command->>'action'; cid uuid:=(command->>'case_id')::uuid; aid uuid:=(command->>'application_id')::uuid;
 candidate uuid; loc uuid; other record; expires timestamptz; owns boolean; manager boolean;
 decides uuid[]:='{}'; fresh boolean:=false;
begin
 if idempotency_key is null then raise exception 'Idempotency key required'; end if;
 -- The core says who may act (FB-6.4 A2): one's own offer and application,
 -- never while restricted (D4); a decision on a case is asked below, per case.
 -- Offering and applying are the employee side's (ROL-CIFT, design §4.4); a
 -- manager's decision (approve, reject, close) is not, so a management access
 -- alone still decides: it only passes the membership gate here.
 perform app_private.authorize(actor,w,case when action in('apply','pass','accept','decline','withdraw') then 'exchange.apply_own'
   when action in('approve','reject','close') then 'workspace.read' else 'exchange.offer_own' end);
 perform pg_advisory_xact_lock(hashtextextended(w::text,921));
 select * into old_cmd from public.shift_exchange_commands q where q.workspace_id=w and q.actor_user_id=actor and q.idempotency_key=shift_exchanges_command_service.idempotency_key;
 if old_cmd.idempotency_key is not null then
  if old_cmd.command<>command then raise exception 'Idempotency key was used for another action' using errcode='22023'; end if;
  return old_cmd.result;
 end if;
 select * into emp from public.employee_profiles where workspace_id=w and user_id=actor and archived_at is null;
 if action in('create','apply','pass') then
  if emp.id is null then raise exception 'Employee profile required' using errcode='42501',hint='authz.out_of_scope'; end if;
  s:=public.shift_exchange_shift(w,(command->>'shift_id')::uuid);
  if s is null or (s->>'starts_at')::timestamptz<=clock_timestamp() then raise exception 'Choose an upcoming published shift' using errcode='PT409'; end if;
  if action='create' then
   if (s->>'employee_id')::uuid is distinct from emp.id then raise exception 'Only the current owner can offer this shift' using errcode='42501',hint='authz.out_of_scope'; end if;
   if command->>'kind' not in('cover','swap') then raise exception 'Invalid exchange kind'; end if;
   if command->>'kind'='swap' then
    t:=public.shift_exchange_shift(w,(command->>'requested_shift_id')::uuid);
    if t is null or t->>'employee_id' is null or t->>'employee_id'=emp.id::text or (t->>'starts_at')::timestamptz<=clock_timestamp() then raise exception 'Choose an upcoming teammate shift'; end if;
    candidate:=(t->>'employee_id')::uuid;
    perform public.require_weekly_exchange_employee_warning(actor,w,emp.id,t,command);
    if app_private.eligibility(w,emp.id,t,jsonb_build_object('operation','swap','excluded',jsonb_build_array(s->>'id',t->>'id')))->>'status'<>'eligible' then raise exception 'You are not eligible for the teammate shift'; end if;
   else candidate:=(command->>'employee_id')::uuid; end if;
   if candidate=emp.id then raise exception 'Choose a different teammate'; end if;
   if candidate is not null and app_private.eligibility(w,candidate,s,jsonb_build_object('operation',case when t is null then 'cover_accept' else 'swap' end,'excluded',to_jsonb(array_remove(array[(s->>'id')::uuid,(t->>'id')::uuid],null))))->>'status'<>'eligible' then raise exception 'This teammate is not eligible for the full shift'; end if;
   for other in select x.id,public.shift_exchange_live_status(w,x.id) live_status from public.shift_exchange_cases x
    where x.workspace_id=w and x.status='open' and x.offered_source_id=(s->>'source_id')::uuid loop
    if other.live_status<>'open' then
     update public.shift_exchange_cases set status=other.live_status,revision=revision+1,updated_at=now() where id=other.id;
     update public.shift_exchange_applications set status=other.live_status,updated_at=now() where case_id=other.id and status in('invited','pending_manager');
     delete from public.shift_exchange_votes where case_id=other.id;
     perform public.shift_exchange_emit(actor,w,other.id,null,other.live_status,'This offer ended because the shift changed or started. Review the current schedule before making a new request.');
    end if;
   end loop;
   fp:=public.shift_exchange_fingerprint(w,s,t);
   -- Nothing opens in the last 4 hours before the shift (plan 04:56).
   expires:=app_private.shift_exchange_deadline(s,t);
   if expires<=clock_timestamp() then raise exception 'Too close to the shift. Talk to your manager.' using errcode='PT409',hint='exchange.too_close'; end if;
   insert into public.shift_exchange_cases(workspace_id,kind,audience,offered_source_id,requested_source_id,owner_id,offered_snapshot,requested_snapshot,consent_fingerprint,expires_at,private_note,teammate_note,created_by)
   values(w,command->>'kind',case when candidate is null then 'eligible_pool' else 'direct' end,(s->>'source_id')::uuid,(t->>'source_id')::uuid,emp.id,s,t,fp,expires,coalesce(command->>'note',''),
    case when candidate is null then coalesce(trim(command->>'teammate_note'),'') else '' end,actor) returning * into c;
   cid:=c.id;
   if candidate is not null then
    insert into public.shift_exchange_applications(workspace_id,case_id,employee_id,status,consent_fingerprint) values(w,cid,candidate,'invited',fp) returning id into aid;
   end if;
   perform public.shift_exchange_emit(actor,w,cid,aid,case when candidate is null then 'cover_opened' else 'peer_invited' end,'Cover or swap requested. The current owner remains responsible until manager approval.');
  else
   if (s->>'employee_id')::uuid=emp.id then raise exception 'You already own this shift'; end if;
   select * into c from public.shift_exchange_cases where workspace_id=w and offered_source_id=(s->>'source_id')::uuid and status='open' for update;
   -- Only a release reaches the pool: a shift nobody holds stays the manager's (plan 07:08).
   if c.id is null then raise exception 'This shift has not been released'; end if;
   if c.audience<>'eligible_pool' or c.kind='swap' or (cid is not null and cid<>c.id) then raise exception 'This offer is not available' using errcode='42501',hint='authz.out_of_scope'; end if;
   if c.expires_at<=clock_timestamp() then raise exception 'This request closed 4 hours before the shift' using errcode='PT409'; end if;
   cid:=c.id;
   if action='pass' then
    -- Not for me (plan 04:52): the card leaves this person's Available Shifts. Only
    -- they read it; the request itself does not change, so the owner's Take back holds.
    -- One passes only on a card one is shown: eligible, or held back by approved time off alone.
    checked:=app_private.eligibility(w,emp.id,s,'{"operation":"release_pickup"}');
    if checked->>'status'<>'eligible' and exists(select 1 from jsonb_array_elements(checked->'blockers') b where b->>'code'<>'approved_time_off') then
     raise exception 'This offer is not available' using errcode='42501',hint='authz.out_of_scope';
    end if;
    if not exists(select 1 from public.shift_exchange_applications where case_id=cid and employee_id=emp.id and status='declined_by_employee') then
     insert into public.shift_exchange_applications(workspace_id,case_id,employee_id,status,consent_fingerprint) values(w,cid,emp.id,'declined_by_employee',c.consent_fingerprint);
    end if;
   else
    if public.shift_exchange_fingerprint(w,s,null)<>c.consent_fingerprint then raise exception 'Shift conditions changed. The owner must renew this offer' using errcode='PT409'; end if;
    perform public.require_weekly_exchange_employee_warning(actor,w,emp.id,s,command);
    if app_private.eligibility(w,emp.id,s,'{"operation":"release_pickup"}')->>'status'<>'eligible' then raise exception 'You are not eligible for the full shift'; end if;
    if exists(select 1 from public.shift_exchange_applications where case_id=cid and employee_id=emp.id and status='pending_manager') then raise exception 'You already have an active application'; end if;
    insert into public.shift_exchange_applications(workspace_id,case_id,employee_id,status,consent_fingerprint) values(w,cid,emp.id,'pending_manager',c.consent_fingerprint) returning id into aid;
    update public.shift_exchange_cases set revision=revision+1,updated_at=now() where id=cid returning * into c;
    perform public.shift_exchange_emit(actor,w,cid,aid,'application_submitted','A teammate requested this shift. The current owner remains responsible.');
   end if;
  end if;
 else
  select * into c from public.shift_exchange_cases where id=cid and workspace_id=w for update;
  if c.id is null then raise exception 'Request not found' using errcode='P0002'; end if;
  s:=public.shift_exchange_shift(w,c.offered_source_id); t:=public.shift_exchange_shift(w,c.requested_source_id);
  owns:=c.owner_id=emp.id;
  manager:=app_private.authz_reason(actor,w,'exchange.approve',array[(c.offered_snapshot->>'location_id')::uuid]) is null
   or (c.kind='swap' and app_private.authz_reason(actor,w,'exchange.approve',array[(c.requested_snapshot->>'location_id')::uuid]) is null);
  -- A pass on a release is no request of one's own (TAKAS-RELEASE).
  if not coalesce(owns,false) and not coalesce(manager,false) and not exists(select 1 from public.shift_exchange_applications ap where ap.case_id=cid and ap.employee_id=emp.id and (ap.status<>'declined_by_employee' or c.audience='direct')) then raise exception 'Request access denied' using errcode='42501',hint='authz.out_of_scope'; end if;
  if c.status<>'open' or c.revision is distinct from (command->>'expected_revision')::integer then raise exception 'This request changed. Review the latest details' using errcode='PT409'; end if;
  if c.expires_at<=clock_timestamp() then
   update public.shift_exchange_cases set status='expired',revision=revision+1,updated_at=now() where id=cid returning * into c;
   update public.shift_exchange_applications set status='expired',updated_at=now() where case_id=cid and status in('invited','pending_manager');
   delete from public.shift_exchange_votes where case_id=cid;
   perform public.shift_exchange_emit(null,w,cid,null,'expired','This request closed 4 hours before the shift. The current owner remains responsible.');
  elsif public.shift_exchange_live_status(w,cid)='invalidated' then
   update public.shift_exchange_cases set status='invalidated',revision=revision+1,updated_at=now() where id=cid returning * into c;
   update public.shift_exchange_applications set status='invalidated',updated_at=now() where case_id=cid and status in('invited','pending_manager');
   delete from public.shift_exchange_votes where case_id=cid;
   perform public.shift_exchange_emit(actor,w,cid,null,'invalidated','Shift details changed. This offer ended without a transfer. Start a new request from the current schedule.');
  elsif action='close' then
   -- P07: a peer reads the case (G1) and does not close it; the reason comes from the core.
   if not coalesce(owns,false) and not exists(select 1 from unnest(array_remove(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid],null)) x
    where app_private.exchange_decision_reason(actor,w,c.owner_id,null,x) is null) then
    raise exception 'Only the person who asked or someone who decides this request can close it' using errcode='42501',detail='exchange.approve',hint='authz.'||coalesce((select r from
     unnest(array_remove(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid],null)) x,
     app_private.exchange_decision_reason(actor,w,c.owner_id,null,x) r where r<>'out_of_scope' limit 1),'out_of_scope');
   end if;
   update public.shift_exchange_cases set status='cancelled',revision=revision+1,updated_at=now() where id=cid returning * into c;
   -- Take back needs no reason (plan 04:52); the owner keeps the shift.
   update public.shift_exchange_applications set status='closed_case_cancelled',reason=coalesce(trim(command->>'reason'),''),updated_at=now() where case_id=cid and status in('invited','pending_manager');
   perform public.shift_exchange_emit(actor,w,cid,null,'case_closed',coalesce(nullif(trim(command->>'reason'),''),
    case when coalesce(owns,false) then 'Taken back. The owner keeps this shift.' else 'A manager closed this request. The owner keeps this shift.' end),coalesce(command->>'private_note',''));
  else
   select * into a from public.shift_exchange_applications where id=aid and case_id=cid and workspace_id=w for update;
   if a.id is null or a.status not in('invited','pending_manager') then raise exception 'This application is no longer active' using errcode='PT409'; end if;
   if action in('accept','decline','withdraw') then
    if a.employee_id is distinct from emp.id then raise exception 'Only the invited employee can respond' using errcode='42501',hint='authz.out_of_scope'; end if;
    if action in('accept','decline') and a.status<>'invited' then raise exception 'This invitation already has a response'; end if;
    if action='accept' then
     if public.shift_exchange_fingerprint(w,s,t) is distinct from c.consent_fingerprint then raise exception 'Shift conditions changed. Ask for a new offer' using errcode='PT409'; end if;
     perform public.require_weekly_exchange_employee_warning(actor,w,emp.id,s,command);
     if app_private.eligibility(w,emp.id,s,jsonb_build_object('operation',case when c.kind='swap' then 'swap' when c.audience='direct' then 'cover_accept' else 'release_pickup' end,'excluded',to_jsonb(array_remove(array[(s->>'id')::uuid,(t->>'id')::uuid],null))))->>'status'<>'eligible'
      or (c.kind='swap' and app_private.eligibility(w,c.owner_id,t,jsonb_build_object('operation','swap','excluded',jsonb_build_array(s->>'id',t->>'id')))->>'status'<>'eligible') then raise exception 'Both employees must be eligible for the full exchange'; end if;
    end if;
    update public.shift_exchange_applications set status=case action when 'accept' then 'pending_manager' when 'decline' then 'declined_by_employee' else 'withdrawn' end,
     updated_at=now() where id=aid;
    delete from public.shift_exchange_votes where case_id=cid and application_id=aid;
    if c.audience='direct' and action in('decline','withdraw') then update public.shift_exchange_cases set status='cancelled' where id=cid; end if;
    perform public.shift_exchange_emit(actor,w,cid,aid,case action when 'accept' then 'peer_accepted' when 'decline' then 'peer_declined' else 'application_withdrawn' end,
     case action when 'accept' then 'Accepted. Awaiting manager approval; the original owner remains responsible.' when 'decline' then 'The teammate declined. No assignment changed.' else case when c.audience='direct' then 'The employee withdrew consent. This request ended without a transfer.' else 'The application was withdrawn. Other candidates remain available.' end end);
   elsif action in('reject','approve') then
    -- D3, K-S1, P07: a manager decides, approve or reject, where they outrank
    -- both people who change shifts; nobody decides their own.
    decides:=array(select x from unnest(array_remove(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid],null)) x
     where app_private.exchange_decision_reason(actor,w,c.owner_id,a.employee_id,x) is null);
    if cardinality(decides)=0 then
     raise exception 'Not allowed' using errcode='42501',detail='exchange.approve',hint='authz.'||coalesce((select r from
      unnest(array_remove(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid],null)) x,
      app_private.exchange_decision_reason(actor,w,c.owner_id,a.employee_id,x) r where r<>'out_of_scope' limit 1),'out_of_scope');
    end if;
    if action='reject' then
     -- The reason is optional; when given, the employee reads it (plan 05:03; Mert, 2026-10-16).
     update public.shift_exchange_applications set status='rejected_by_manager',reason=coalesce(trim(command->>'reason'),''),updated_at=now() where id=aid;
     delete from public.shift_exchange_votes where case_id=cid and application_id=aid;
     if c.audience='direct' then update public.shift_exchange_cases set status='cancelled' where id=cid; end if;
     perform public.shift_exchange_emit(actor,w,cid,aid,'application_rejected',coalesce(nullif(trim(command->>'reason'),''),'Your manager declined this request.'),coalesce(command->>'private_note',''));
    else
     checked:=public.shift_exchange_preview(actor,w,cid,aid);
     if not (checked->>'allowed')::boolean then raise exception '%',checked->'reasons' using errcode='PT409'; end if;
     if command->>'fingerprint' is distinct from checked->>'fingerprint' then raise exception 'This approval preview changed. Review the latest details' using errcode='PT409'; end if;
     fp:=checked->>'fingerprint';
     for loc in select distinct x from unnest(array[(s->>'location_id')::uuid,(t->>'location_id')::uuid]) x where x is not null loop
      if loc=any(decides) then
       fresh:=fresh or not exists(select 1 from public.shift_exchange_votes v where v.case_id=cid and v.location_id=loc
        and v.application_id=aid and v.actor_user_id=actor and v.fingerprint=fp);
       insert into public.shift_exchange_votes(case_id,workspace_id,application_id,location_id,actor_user_id,fingerprint) values(cid,w,aid,loc,actor,fp)
       on conflict(case_id,location_id) do update set application_id=excluded.application_id,actor_user_id=excluded.actor_user_id,fingerprint=excluded.fingerprint,created_at=now();
      end if;
     end loop;
     if (checked->>'requires_other_manager')::boolean then
      -- R2-18: the same manager approving again tells nobody again.
      if fresh then
       perform public.shift_exchange_emit(actor,w,cid,aid,'scope_approved','One location approved. Awaiting the other manager; assignments are unchanged.');
      end if;
     else
      perform 1 from public.schedule_published_shifts where id in((s->>'id')::uuid,(t->>'id')::uuid) order by id for update;
      -- Recheck after row locks as external Schedule writers may predate the shared workspace lock.
      checked:=public.shift_exchange_preview(actor,w,cid,aid);
      if not (checked->>'allowed')::boolean or checked->>'fingerprint'<>fp then raise exception 'Schedule changed during approval' using errcode='PT409'; end if;
      perform public.record_weekly_exchange_acceptance(w,cid,aid);
      -- BL-092: the two sides of a swap are one change for the assignment guard,
      -- in the publication and in the drafts reconciled after it.
      perform set_config('newfork.shift_exchange_scope',jsonb_build_object('workspace_id',w,'shift_ids',to_jsonb(array_remove(array[(s->>'source_id')::uuid,(t->>'source_id')::uuid],null)))::text,true);
      update public.schedule_published_shifts set employee_id=a.employee_id where id=(s->>'id')::uuid;
      if c.kind='swap' then update public.schedule_published_shifts set employee_id=c.owner_id where id=(t->>'id')::uuid; end if;
      perform public.shift_exchange_reconcile_batch(actor,w,jsonb_build_array(s||jsonb_build_object('new_employee_id',a.employee_id))||case when c.kind='swap' then jsonb_build_array(t||jsonb_build_object('new_employee_id',c.owner_id)) else '[]'::jsonb end);
      perform set_config('newfork.shift_exchange_scope','',true);
      
      update public.shift_exchange_applications set status='approved',updated_at=now() where id=aid;
      for other in select id from public.shift_exchange_applications where case_id=cid and id<>aid and status in('invited','pending_manager') loop
       update public.shift_exchange_applications set status='closed_other_selected',updated_at=now() where id=other.id;
       perform public.shift_exchange_emit(actor,w,cid,other.id,'other_selected','Another teammate was selected. Your schedule has not changed.');
      end loop;
      update public.shift_exchange_cases set status='completed' where id=cid;
      perform public.shift_exchange_emit(actor,w,cid,aid,'transfer_completed','Manager approved the transfer. The receiving employee is now responsible; the previous owner is released.',coalesce(command->>'private_note',''));
      for other in select x.id from public.shift_exchange_cases x where x.workspace_id=w and x.status='open' and x.id<>cid
       and (x.offered_source_id in(c.offered_source_id,c.requested_source_id) or x.requested_source_id in(c.offered_source_id,c.requested_source_id)) loop
       update public.shift_exchange_cases set status='invalidated',revision=revision+1,updated_at=now() where id=other.id;
       update public.shift_exchange_applications set status='invalidated',updated_at=now() where case_id=other.id and status in('invited','pending_manager');
       perform public.shift_exchange_emit(actor,w,other.id,null,'invalidated','An involved shift changed owner. Start a new request using the current schedule.');
      end loop;
     end if;
    end if;
   else raise exception 'Unknown exchange action'; end if;
   -- BL-228: when it was decided, not when its transaction began; an approval
   -- that waited for the workspace lock behind a publish is newer than it.
   update public.shift_exchange_cases set revision=revision+1,updated_at=clock_timestamp() where id=cid returning * into c;
  end if;
 end if;
 -- A pass changes nothing anyone else reads, so it tells nobody.
 if action<>'pass' then
  perform realtime.send(jsonb_build_object('workspace_id',w,'case_id',cid,'revision',c.revision),'changed','shift-exchanges:'||w::text,true);
 end if;
 result:=jsonb_build_object('case_id',cid,'status',c.status,'revision',c.revision);
 insert into public.shift_exchange_commands(workspace_id,actor_user_id,idempotency_key,command,result) values(w,actor,idempotency_key,command,result);
 return result;
end; $$;


ALTER FUNCTION "public"."shift_exchanges_command_service"("actor" "uuid", "w" "uuid", "command" "jsonb", "idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchanges_maintain_service"("target_batch_size" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare candidate record; c public.shift_exchange_cases%rowtype; live_status text;
 expired_count integer:=0; invalidated_count integer:=0; busy_count integer:=0;
begin
 if target_batch_size not between 1 and 500 then raise exception 'Maintenance batch must contain 1 to 500 cases' using errcode='22023'; end if;
 for candidate in select x.id,x.workspace_id from public.shift_exchange_cases x
  where x.status='open' and public.shift_exchange_live_status(x.workspace_id,x.id)<>'open'
  order by x.workspace_id,x.expires_at,x.id limit target_batch_size
 loop
  if not pg_try_advisory_xact_lock(hashtextextended(candidate.workspace_id::text,921)) then busy_count:=busy_count+1; continue; end if;
  select * into c from public.shift_exchange_cases where id=candidate.id and status='open' for update;
  if c.id is null then continue; end if;
  live_status:=public.shift_exchange_live_status(c.workspace_id,c.id);
  if live_status not in('expired','invalidated') then continue; end if;
  update public.shift_exchange_cases set status=live_status,revision=revision+1,updated_at=now() where id=c.id returning * into c;
  update public.shift_exchange_applications set status=live_status,updated_at=now() where case_id=c.id and status in('invited','pending_manager');
  delete from public.shift_exchange_votes where case_id=c.id;
  perform public.shift_exchange_emit(null,c.workspace_id,c.id,null,live_status,
   case when live_status='expired' then 'The decision deadline passed. This search closed without a transfer. Check your current schedule for your assignment.'
    else 'Shift details changed. This search closed without a transfer. Review your current schedule before making a new request.' end);
  perform realtime.send(jsonb_build_object('workspace_id',c.workspace_id,'case_id',c.id,'revision',c.revision),'changed','shift-exchanges:'||c.workspace_id::text,true);
  if live_status='expired' then expired_count:=expired_count+1; else invalidated_count:=invalidated_count+1; end if;
 end loop;
 return jsonb_build_object('expired',expired_count,'invalidated',invalidated_count,'skipped_busy',busy_count);
end; $$;


ALTER FUNCTION "public"."shift_exchanges_maintain_service"("target_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_exchanges_read_service"("actor" "uuid", "w" "uuid", "manager_view" boolean DEFAULT false, "from_date" "date" DEFAULT CURRENT_DATE, "to_date" "date" DEFAULT (CURRENT_DATE + 42), "focused_case_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare emp public.employee_profiles%rowtype; c public.shift_exchange_cases%rowtype; s jsonb; t jsonb; allowed boolean; mine boolean;
 case_items jsonb[]:='{}'; opportunities jsonb:='[]'; own_shifts jsonb:='[]'; chk jsonb; shift_row record; live_status text; published_cache jsonb:='{}'; source_key text;
 read_scope uuid[]:='{}'; tiers jsonb:='{}';
begin
 if to_date<from_date or to_date>from_date+62 then raise exception 'Choose a date range up to 62 days'; end if;
 if not manager_view then perform app_private.authorize(actor,w,'employee_hub.read'); end if;
 select * into emp from public.employee_profiles where workspace_id=w and user_id=actor and archived_at is null;
 if not manager_view and emp.id is null then raise exception 'Employee profile required' using errcode='42501',hint='authz.out_of_scope'; end if;
 if manager_view then
  read_scope:=app_private.scope_set(actor,w,'exchange.read');
  -- Nowhere to read requests: asked with no location, the core says why; with
  -- no live location in the workspace there is nothing to read.
  if cardinality(read_scope)=0 and (app_private.authz_reason(actor,w,'exchange.read') is distinct from 'out_of_scope'
   or exists(select 1 from public.locations l where l.workspace_id=w and l.deleted_at is null)) then
   perform app_private.authorize(actor,w,'exchange.read');
  end if;
 end if;
 for c in select * from public.shift_exchange_cases x where x.workspace_id=w and (x.status='open' or x.id=focused_case_id
  or (x.offered_snapshot->>'date')::date between from_date and to_date
  or (x.requested_snapshot->>'date')::date between from_date and to_date
  or exists(select 1 from public.schedule_published_shifts p
   join public.schedule_location_publications pub on pub.id=p.publication_id and pub.status='current'
   where p.workspace_id=w and coalesce(p.source_shift_id,p.id) in(x.offered_source_id,x.requested_source_id)
   and p.scheduled_date between from_date and to_date)) order by x.expires_at,x.created_at loop
  allowed:=manager_view and coalesce((c.offered_snapshot->>'location_id')::uuid=any(read_scope) or (c.kind='swap' and (c.requested_snapshot->>'location_id')::uuid=any(read_scope)),false);
  mine:=coalesce(c.owner_id=emp.id,false);
  if not allowed and not mine and not exists(select 1 from public.shift_exchange_applications a where a.case_id=c.id and a.employee_id=emp.id and (a.status<>'declined_by_employee' or c.audience='direct')) then continue; end if;
  -- A swap or a cover reaches a manager once both sides agreed (Mert, 2026-10-11):
  -- somebody asks for the shift, or the teammate accepted the swap.
  if manager_view and not mine
   and not exists(select 1 from public.shift_exchange_applications a where a.case_id=c.id and a.employee_id=emp.id and (a.status<>'declined_by_employee' or c.audience='direct'))
   and not coalesce(app_private.shift_exchange_reached_managers(w,c.id),false)
   then continue; end if;
  -- Requests holds what its reader answers: their own request is not there (design §4.6), but for
  -- the owner whom nobody else can answer (KARARLAR S-169).
  if manager_view and (mine or exists(select 1 from public.shift_exchange_applications a where a.case_id=c.id and a.employee_id=emp.id))
   and not exists(select 1 from unnest(array_remove(array[(c.offered_snapshot->>'location_id')::uuid,(c.requested_snapshot->>'location_id')::uuid],null)) x
    where app_private.exchange_decision_reason(actor,w,c.owner_id,case when mine then null else emp.id end,x) is null)
   then continue; end if;
  -- Repeated historical requests refer to the same published source. Resolve
  -- each source once in this read only; no cache survives the function call.
  foreach source_key in array array_remove(array[c.offered_source_id::text,c.requested_source_id::text],null) loop
   if not published_cache ? source_key then
    published_cache:=published_cache||jsonb_build_object(source_key,public.shift_exchange_shift(w,source_key::uuid));
   end if;
  end loop;
  s:=nullif(published_cache->c.offered_source_id::text,'null'::jsonb);
  t:=nullif(published_cache->c.requested_source_id::text,'null'::jsonb);
  live_status:=public.shift_exchange_live_status(w,c.id);
  -- The list follows the displayed dates on either side; in Requests an open
  -- request is listed whatever its date (BL-839). A focused deep link bypasses
  -- only the range, never the actor checks above.
  if c.id is distinct from focused_case_id and not (manager_view and live_status='open') and not (
   coalesce((coalesce(s,c.offered_snapshot)->>'date')::date between from_date and to_date,false)
   or coalesce((coalesce(t,c.requested_snapshot)->>'date')::date between from_date and to_date,false)
  ) then continue; end if;
  case_items:=array_append(case_items,app_private.shift_exchange_case_item(actor,w,c,allowed,emp.id,s,t,live_status));
 end loop;
 if not manager_view then
  for shift_row in select p.id from public.schedule_published_shifts p join public.schedule_location_publications pub on pub.id=p.publication_id and pub.status='current'
   where p.workspace_id=w and p.scheduled_date between from_date and to_date order by p.scheduled_date,p.start_time loop
   s:=public.shift_exchange_shift(w,shift_row.id);
   if (s->>'starts_at')::timestamptz<=clock_timestamp() then continue; end if;
   if (s->>'employee_id')::uuid=emp.id then
    -- Who a request for it would go to (KARARLAR S-169): 'self_only' tells the owner nobody else can approve it.
    if not tiers ? (s->>'location_id') then
     tiers:=tiers||jsonb_build_object(s->>'location_id',app_private.decision_tier(w,emp.id,(s->>'location_id')::uuid));
    end if;
    own_shifts:=own_shifts||jsonb_build_array(s||jsonb_build_object('decision_tier',tiers->(s->>'location_id'))); continue;
   end if;
   -- Only a release is in the pool (plan 07:08), and not one this person passed on (04:52).
   select * into c from public.shift_exchange_cases where workspace_id=w and offered_source_id=(s->>'source_id')::uuid and status='open' and expires_at>clock_timestamp() and audience='eligible_pool' and kind<>'swap';
   if c.id is null or exists(select 1 from public.shift_exchange_applications a where a.case_id=c.id and a.employee_id=emp.id and a.status='declined_by_employee') then continue; end if;
   chk:=(app_private.eligibility(w,emp.id,s,'{"operation":"release_pickup"}')-'approval_flags')||jsonb_build_object('availability_warning',public.weekly_exchange_employee_warning(w,emp.id,s));
   if (chk->>'status'='eligible' or (chk->>'status'='ineligible' and not exists(select 1 from jsonb_array_elements(chk->'blockers') b
     where b->>'code'<>'approved_time_off'))) and c.consent_fingerprint=public.shift_exchange_fingerprint(w,s,null) then
    opportunities:=opportunities||jsonb_build_array(jsonb_build_object('case_id',c.id,'shift',s,'eligibility',chk,'note',c.teammate_note));
   end if;
  end loop;
 end if;
 return jsonb_build_object('employee_id',emp.id,'cases',to_jsonb(case_items),'opportunities',opportunities,'own_shifts',own_shifts);
end; $$;


ALTER FUNCTION "public"."shift_exchanges_read_service"("actor" "uuid", "w" "uuid", "manager_view" boolean, "from_date" "date", "to_date" "date", "focused_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_employee_invitation_delivery_secret_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_invitation_id" "uuid", "invitation_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invitation_row public.employee_invitations%rowtype;
begin
  -- Asked before the lock (nf-guvenlik D-c); an unknown invitation has no
  -- person and gets the answer one out of reach gets.
  select * into invitation_row
  from public.employee_invitations
  where id = target_invitation_id
    and workspace_id = target_workspace_id;
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.invite', target_person => invitation_row.employee_id);
  if not app_private.can_invite_with_role(actor_user_id, target_workspace_id, invitation_row.role_id) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  select * into invitation_row
  from public.employee_invitations
  where id = target_invitation_id
  for update;
  if invitation_token is null
    or char_length(invitation_token) not between 32 and 256 then
    raise exception 'valid invitation token required' using errcode = '22023';
  end if;
  if invitation_row.status <> 'pending' or invitation_row.expires_at <= now() then
    raise exception 'active invitation not found' using errcode = 'P0002';
  end if;
  if invitation_row.token_hash <>
    encode(extensions.digest(invitation_token, 'sha256'), 'hex') then
    raise exception 'invitation token does not match' using errcode = '22023';
  end if;

  insert into public.employee_invitation_delivery_secrets (
    invitation_id,
    workspace_id,
    token
  ) values (
    invitation_row.id,
    invitation_row.workspace_id,
    invitation_token
  )
  on conflict (invitation_id) do update
  set token = excluded.token,
      updated_at = now();
end;
$$;


ALTER FUNCTION "public"."store_employee_invitation_delivery_secret_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_invitation_id" "uuid", "invitation_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "target_submission_id" "uuid", "submission_expiry" "date", "submission_metadata" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; s public.employee_document_submissions%rowtype; field jsonb; next_state text;
begin
 perform app_private.authorize(actor_user_id,(select q.workspace_id from public.employee_onboarding_requirements q where q.id=target_requirement_id),'documents.self',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id));
 perform 1 from public.employee_onboarding_cases c join public.employee_onboarding_requirements q on q.case_id=c.id where q.id=target_requirement_id and app_private.document_actor_can_read(actor_user_id,q.workspace_id,q.employee_id,q.lifecycle_user_id) for update of c;
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id for update;
 if r.id is null or r.lifecycle_user_id is distinct from actor_user_id or not app_private.document_actor_can_read(actor_user_id,r.workspace_id,r.employee_id,r.lifecycle_user_id)
 then raise exception 'document unavailable' using errcode='P0002'; end if;
 perform app_private.assert_document_published(r);
 if r.lifecycle_revision<>expected_revision then raise exception 'document changed; refresh required' using errcode='PT409',hint='document.changed'; end if;
 if r.lifecycle_closed_at is not null or (r.lifecycle_exempt and not r.owner_excused) or r.status='superseded' then raise exception 'document obligation is closed' using errcode='22023'; end if;
 select * into s from public.employee_document_submissions where id=target_submission_id and requirement_id=r.id and user_id=actor_user_id and state='draft' for update;
 if s.id is null or not exists(select 1 from public.employee_document_submission_files where submission_id=s.id and decision='keep') then raise exception 'a draft with retained files is required' using errcode='22023'; end if;
 if coalesce((r.source_snapshot->>'tracks_expiry')::boolean,false) and submission_expiry is null then raise exception 'expiration date required' using errcode='22023'; end if;
 if submission_expiry is not null and app_private.document_employee_timezone(r.workspace_id,r.employee_id) is null then raise exception 'Document timezone needs administrator configuration' using errcode='22023'; end if; if submission_expiry < (now() at time zone app_private.document_employee_timezone(r.workspace_id,r.employee_id))::date then raise exception 'expired documents cannot be submitted' using errcode='22023'; end if;
 if submission_metadata is null or jsonb_typeof(submission_metadata)<>'object' then raise exception 'document metadata required' using errcode='22023'; end if;
 for field in select value from jsonb_array_elements(coalesce(r.lifecycle_settings->'extra_fields','[]')) loop
  if (field->>'required')::boolean and nullif(btrim(submission_metadata->>(field->>'key')),'') is null then raise exception 'required document field missing' using errcode='22023'; end if;
  if nullif(submission_metadata->>(field->>'key'),'') is not null then
   if field->>'kind'='date' then perform (submission_metadata->>(field->>'key'))::date;
   elsif field->>'kind'='number' then perform (submission_metadata->>(field->>'key'))::numeric; end if;
  end if;
 end loop;
 -- Materialize overdue state before submission; cron delays cannot reopen access.
 if app_private.document_obligation_blocked(r,now()) then r.document_suspended_at:=coalesce(r.document_suspended_at,now()); end if;
 next_state:=case when r.requires_review and not r.owner_excused then 'pending_review' else 'accepted' end;
 update public.employee_document_submissions set state='superseded' where id=r.submitted_document_id and state='pending_review';
 update public.employee_document_submissions set state=next_state,submitted_at=now(),expiry_date=submission_expiry,metadata=submission_metadata,
  reviewed_at=case when next_state='accepted' then now() end where id=s.id;
 update public.employee_onboarding_requirements set submitted_document_id=s.id,
  approved_document_id=case when next_state='accepted' then s.id else approved_document_id end,
  paused_remaining_seconds=case when r.paused_remaining_seconds is not null then r.paused_remaining_seconds when deadline_at is not null then greatest(0,extract(epoch from deadline_at-now())) end,
  document_suspended_at=case when next_state='accepted' then null else r.document_suspended_at end,
  status=case when next_state='accepted' then 'completed'::public.employee_onboarding_requirement_status else 'awaiting_review'::public.employee_onboarding_requirement_status end,
  rejection_reason=null,conditional_reason=null,lifecycle_revision=lifecycle_revision+1,updated_at=now()
 where id=r.id returning lifecycle_revision into expected_revision;
 perform app_private.document_audit(r,actor_user_id,'document.submitted',jsonb_build_object('submission_id',s.id,'revision',expected_revision,'state',next_state));
 perform app_private.document_sync_onboarding(r.id,actor_user_id); return expected_revision;
end;
$$;


ALTER FUNCTION "public"."submit_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "target_submission_id" "uuid", "submission_expiry" "date", "submission_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_employee_onboarding_service"("target_user_id" "uuid", "expected_revision" integer, "target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_case public.employee_onboarding_cases%rowtype;
begin
 perform app_private.authorize(target_user_id, app_private.onboarding_self_workspace(target_user_id, target_workspace_id, true), 'onboarding.self');
  select onboarding.* into target_case
  from public.employee_onboarding_cases onboarding
  where onboarding.id = app_private.employee_onboarding_case_id(target_user_id, target_workspace_id)
  for update;

  if target_case.id is null or target_case.revision <> expected_revision then
    raise exception 'onboarding changed; refresh required' using errcode = 'PT409', hint = 'onboarding.changed';
  end if;
  if exists(select 1 from public.employee_onboarding_requirements r where r.case_id=target_case.id and app_private.document_initial_action_missing(r)) then raise exception 'Submit conditional documents or give an initial reason' using errcode='23514'; end if;
  if exists (
    select 1
    from public.employee_onboarding_requirements
    where case_id = target_case.id
      and (kind<>'document' or (not lifecycle_exempt and lifecycle_closed_at is null and status<>'superseded')) and required
      and status not in (
        'completed'::public.employee_onboarding_requirement_status,
        'awaiting_review'::public.employee_onboarding_requirement_status
      )
  ) then
    raise exception 'required onboarding items remain incomplete' using errcode = '23514';
  end if;

  update public.employee_onboarding_cases
  set status = 'submitted'::public.employee_onboarding_case_status,
      submitted_at = now(),
      revision = revision + 1,
      updated_at = now()
  where id = target_case.id
  returning * into target_case;

  insert into public.onboarding_events (workspace_id, employee_id, case_id, actor_user_id, action, target_type, target_id)
  values (
    target_case.workspace_id,
    target_case.employee_id,
    target_case.id,
    target_user_id,
    'onboarding.submitted',
    'onboarding_case',
    target_case.id::text
  );

  if not exists(select 1 from public.employee_onboarding_requirements r where r.case_id=target_case.id and app_private.document_activation_blocked(r)) and not target_case.final_approval_required
    and not exists (
      select 1
      from public.employee_onboarding_requirements
      where case_id = target_case.id
        and (kind<>'document' or (not lifecycle_exempt and lifecycle_closed_at is null and status<>'superseded')) and required
        and blocks_activation
        and status <> 'completed'::public.employee_onboarding_requirement_status
    ) then
    return app_private.activate_employee_onboarding_case(
      target_case.id,
      target_user_id,
      'employee.auto_activated'
    );
  end if;

  -- It waits: the person's "needs a change" card closes and who may act on it now is told (onboarding_tell).
  perform app_private.onboarding_tell(target_case, 'submitted', target_user_id);
  return target_case.revision;
end;
$$;


ALTER FUNCTION "public"."submit_employee_onboarding_service"("target_user_id" "uuid", "expected_revision" integer, "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_expiring_document_todos_service"("target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  inserted_count integer := 0;
  resolved_count integer := 0;
begin
  with latest_documents as (
    select distinct on (document.workspace_id, document.requirement_id)
      document.*
    from public.employee_documents document
    where document.review_status <> 'superseded'::public.employee_document_review_status
      and (target_workspace_id is null or document.workspace_id = target_workspace_id)
    order by document.workspace_id, document.requirement_id, document.version_number desc
  ),
  eligible as (
    select
      document.workspace_id,
      document.id as document_id,
      document.employee_id,
      document.requirement_id,
      document.expiry_date,
      requirement.title as document_title,
      employee.first_name,
      employee.last_name,
      type.expiry_schedule_impact
    from latest_documents document
    join public.workspaces workspace
      on workspace.id = document.workspace_id
     and app_private.workspace_allows_interactive_access(workspace.id)
    join public.employee_onboarding_requirements requirement
      on requirement.id = document.requirement_id
     and requirement.workspace_id = document.workspace_id
     and requirement.kind = 'document'::public.employee_onboarding_requirement_kind
     and requirement.status <> 'superseded'::public.employee_onboarding_requirement_status
    join public.document_types type
      on type.id = requirement.source_id
     and type.workspace_id = document.workspace_id
     and type.archived_at is null
     and type.tracks_expiry
    join public.employee_profiles employee
      on employee.id = document.employee_id
     and employee.workspace_id = document.workspace_id
     and employee.archived_at is null
    where document.review_status = 'accepted'::public.employee_document_review_status
      and document.expiry_date is not null
      and document.expiry_date <= current_date + type.expiry_warning_days
  )
  insert into public.workspace_todos (
    workspace_id,
    title,
    body,
    severity,
    status,
    system_generated,
    source_type,
    source_id,
    source_key,
    employee_id,
    due_at,
    action_url,
    resolved_at
  )
  select
    eligible.workspace_id,
    case
      when eligible.expiry_date < current_date then 'Expired employee document'
      else 'Employee document expires soon'
    end,
    btrim(eligible.first_name || ' ' || eligible.last_name) || ' - ' || eligible.document_title,
    case
      when eligible.expiry_date < current_date then 'action_required'::public.workspace_todo_severity
      else 'warning'::public.workspace_todo_severity
    end,
    'open'::public.workspace_todo_status,
    true,
    'employee_document_expiry',
    eligible.document_id,
    'requirement:' || eligible.requirement_id::text,
    eligible.employee_id,
    eligible.expiry_date::timestamptz,
    '/app/employees',
    null
  from eligible
  on conflict (workspace_id, source_type, source_id, source_key)
  do update set
    title = excluded.title,
    body = excluded.body,
    severity = excluded.severity,
    status = 'open'::public.workspace_todo_status,
    employee_id = excluded.employee_id,
    due_at = excluded.due_at,
    action_url = excluded.action_url,
    resolved_at = null,
    updated_at = now()
  where public.workspace_todos.status <> 'open'::public.workspace_todo_status
     or public.workspace_todos.title <> excluded.title
     or public.workspace_todos.body <> excluded.body
     or public.workspace_todos.severity <> excluded.severity
     or public.workspace_todos.employee_id is distinct from excluded.employee_id
     or public.workspace_todos.due_at is distinct from excluded.due_at
     or public.workspace_todos.action_url is distinct from excluded.action_url;
  get diagnostics inserted_count = row_count;

  with latest_documents as (
    select distinct on (document.workspace_id, document.requirement_id)
      document.*
    from public.employee_documents document
    where document.review_status <> 'superseded'::public.employee_document_review_status
      and (target_workspace_id is null or document.workspace_id = target_workspace_id)
    order by document.workspace_id, document.requirement_id, document.version_number desc
  ),
  eligible as (
    select document.workspace_id, document.id as document_id, document.requirement_id
    from latest_documents document
    join public.workspaces workspace
      on workspace.id = document.workspace_id
     and app_private.workspace_allows_interactive_access(workspace.id)
    join public.employee_onboarding_requirements requirement
      on requirement.id = document.requirement_id
     and requirement.workspace_id = document.workspace_id
     and requirement.kind = 'document'::public.employee_onboarding_requirement_kind
     and requirement.status <> 'superseded'::public.employee_onboarding_requirement_status
    join public.document_types type
      on type.id = requirement.source_id
     and type.workspace_id = document.workspace_id
     and type.archived_at is null
     and type.tracks_expiry
    join public.employee_profiles employee
      on employee.id = document.employee_id
     and employee.workspace_id = document.workspace_id
     and employee.archived_at is null
    where document.review_status = 'accepted'::public.employee_document_review_status
      and document.expiry_date is not null
      and document.expiry_date <= current_date + type.expiry_warning_days
  )
  update public.workspace_todos todo
  set status = 'resolved'::public.workspace_todo_status,
      resolved_at = now(),
      updated_at = now()
  where todo.source_type = 'employee_document_expiry'
    and todo.system_generated
    and todo.status = 'open'::public.workspace_todo_status
    and (target_workspace_id is null or todo.workspace_id = target_workspace_id)
    and not exists (
      select 1
      from eligible
      where eligible.workspace_id = todo.workspace_id
        and eligible.document_id = todo.source_id
        and 'requirement:' || eligible.requirement_id::text = todo.source_key
    );
  get diagnostics resolved_count = row_count;

  return jsonb_build_object(
    'status', 'synced',
    'affected', inserted_count + resolved_count,
    'opened_or_refreshed', inserted_count,
    'resolved', resolved_count
  );
end;
$$;


ALTER FUNCTION "public"."sync_expiring_document_todos_service"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_schedule_conflict_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.conflict_rules:=jsonb_build_object('document_required','confirm','document_conditional_grace','warn','document_conditional_overdue','confirm')
   ||case when tg_op='UPDATE' then old.conflict_rules else '{}'::jsonb end||new.conflict_rules;
 
 if tg_op='UPDATE' and auth.uid() is not null and (new.conflict_rules,new.minimum_travel_minutes,new.minimum_rest_minutes)
   is distinct from (old.conflict_rules,old.minimum_travel_minutes,old.minimum_rest_minutes)
   and not public.workspace_has_permission(new.workspace_id,'schedule.conflict_rules.manage') then
   raise exception 'Conflict settings access denied' using errcode='42501';
  end if;
 if tg_op='UPDATE' then
  new.conflict_rules_revision:=old.conflict_rules_revision+case when (new.conflict_rules,new.minimum_travel_minutes,new.minimum_rest_minutes)
   is distinct from (old.conflict_rules,old.minimum_travel_minutes,old.minimum_rest_minutes) then 1 else 0 end;
 end if;
 if exists(select 1 from jsonb_each(new.conflict_rules) rule where jsonb_typeof(rule.value)<>'string') then
  raise exception 'Conflict rules must contain valid actions' using errcode='22023';
 end if;
 return new;
end;
$$;


ALTER FUNCTION "public"."sync_schedule_conflict_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_weekly_onboarding_requirements"("w" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c record; required_now boolean; declared boolean;
begin
 select s.availability_onboarding_required into required_now from public.workspace_scheduling_settings s where s.workspace_id=w;
 if required_now is null then raise exception 'Scheduling settings unavailable' using errcode='P0002'; end if;
 -- Match onboarding's case lock so activation and a policy change serialize.
 for c in select id,employee_id from public.employee_onboarding_cases
  where workspace_id=w and status in ('in_progress','submitted','changes_requested') order by id for update
 loop
  declared:=exists(select 1 from public.employee_weekly_preferences p where p.workspace_id=w and p.employee_id=c.employee_id);
  update public.employee_onboarding_requirements r set required=required_now,updated_at=now()
  where r.case_id=c.id and r.kind='availability' and r.lifecycle_retired_at is null and (
   r.required is distinct from required_now or r.blocks_activation is distinct from required_now or r.requires_review
   or r.status::text is distinct from case when declared then 'completed' else 'not_started' end
  );
  if found then
   update public.employee_onboarding_cases set revision=revision+1,updated_at=now() where id=c.id;
  end if;
 end loop;
end; $$;


ALTER FUNCTION "public"."sync_weekly_onboarding_requirements"("w" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_weekly_onboarding_settings"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform public.sync_weekly_onboarding_requirements(new.workspace_id);
 return new;
end; $$;


ALTER FUNCTION "public"."sync_weekly_onboarding_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_workspace_entitlement_billing_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  owner_role uuid := (select r.id from public.workspace_roles r where r.workspace_id = new.workspace_id and r.access_class = 'owner');
begin
  if new.role_id = owner_role
     and new.status = 'active'::public.membership_status
     and (
       old.role_id is distinct from new.role_id
       or old.status is distinct from new.status
     ) then
    update public.workspace_entitlements
    set billing_owner_user_id = new.user_id,
        payment_method_required_at = case
          when billing_owner_user_id is distinct from new.user_id then now()
          else payment_method_required_at
        end,
        updated_at = now()
    where workspace_id = new.workspace_id
      and billing_owner_user_id is distinct from new.user_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_workspace_entitlement_billing_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."take_back_time_off_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_request_id" "uuid", "note" "text", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state;
  why text;
  found_request public.time_off_requests;
  closed uuid;
  note_text text := nullif(btrim(coalesce(note, '')), '');
begin
  perform public.availability_lock_workspace(target_workspace_id);
  me := app_private.actor(actor_user_id, target_workspace_id);
  why := app_private.time_off_decider_why(me, null);
  if why is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || why, detail = 'time_off.decide';
  end if;
  select * into found_request from public.time_off_requests r
  where r.id = target_request_id and r.workspace_id = target_workspace_id and r.kind = 'leave';
  if not found then
    -- A request that is not there answers as one at a location the actor does not reach (BL-354).
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'time_off.decide';
  end if;
  why := app_private.time_off_decider_why(me, found_request.employee_id);
  if why is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || why, detail = 'time_off.decide';
  end if;
  if note_text is null then
    raise exception 'Say why you revoke this time off' using errcode = '22023', hint = 'time_off.note_required';
  end if;
  if char_length(note_text) > 1000 then
    raise exception 'A note is at most 1000 characters' using errcode = '22023', hint = 'time_off.invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('time_off_person:' || found_request.employee_id::text, 0));
  select * into found_request from public.time_off_requests r where r.id = target_request_id for update;
  if found_request.revision is distinct from expected_revision then
    raise exception 'This time off changed. Review it again' using errcode = 'PT409', hint = 'time_off.changed';
  end if;
  if found_request.status <> 'approved' then
    raise exception 'Only approved time off can be revoked' using errcode = 'PT409', hint = 'time_off.not_approved';
  end if;
  if found_request.ends_at <= now() then
    raise exception 'This time off is over' using errcode = 'PT409', hint = 'time_off.ended';
  end if;

  perform app_private.time_off_cut(found_request.id, tstzrange(greatest(now(), found_request.starts_at), found_request.ends_at, '[)'));
  update public.time_off_requests
  set status = 'revoked', ended_by = actor_user_id, ended_at = now(), ended_note = note_text, updated_at = now()
  where id = found_request.id
  returning * into found_request;

  for closed in
    update public.time_off_requests c
    set status = 'withdrawn', ended_by = actor_user_id, ended_at = now(), ended_note = 'The time off was revoked.',
        revision = c.revision + 1, updated_at = now()
    where c.cancels_id = found_request.id and c.kind = 'cancel' and c.status = 'pending'
    returning c.id
  loop
    perform app_private.notification_resolve(found_request.workspace_id, 'time_off', closed, 'revoked', actor_user_id);
  end loop;

  perform app_private.time_off_request_tell(found_request, 'revoked', actor_user_id);
  return app_private.time_off_decider_view(found_request);
end;
$$;


ALTER FUNCTION "public"."take_back_time_off_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_request_id" "uuid", "note" "text", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."terminate_employee_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "effective_local" timestamp without time zone, "worksite_timezone" "text", "termination_reason" "text", "target_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  employee public.employee_profiles%rowtype;
  member public.workspace_memberships%rowtype;
  existing_termination public.employee_terminations%rowtype;
  v_termination_id uuid;
  resolved_effective_at timestamptz;
  released_count integer := 0;
  response jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.terminate', target_person => target_employee_id);
  perform public.availability_lock_workspace(target_workspace_id);
  if effective_local is null or target_idempotency_key is null then
    raise exception 'effective time and idempotency key are required' using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(termination_reason, ''))) not between 3 and 240 then
    raise exception 'termination reason must be between 3 and 240 characters' using errcode = '22023';
  end if;
  if not app_private.timezone_name_valid(worksite_timezone) then
    raise exception 'invalid worksite timezone' using errcode = '22023';
  end if;

  resolved_effective_at := effective_local at time zone worksite_timezone;
  if resolved_effective_at > now() + interval '5 minutes' then
    raise exception 'future termination requires a scheduled offboarding workflow' using errcode = '22023';
  end if;

  select candidate.* into existing_termination
  from public.employee_terminations candidate
  where candidate.workspace_id = target_workspace_id
    and candidate.actor_user_id = terminate_employee_service.actor_user_id
    and candidate.idempotency_key = target_idempotency_key
  for update;
  if found then
    if existing_termination.employee_id <> target_employee_id
      or existing_termination.effective_at <> resolved_effective_at
      or existing_termination.worksite_timezone <> worksite_timezone
      or existing_termination.reason <> btrim(termination_reason) then
      raise exception 'idempotency key payload conflict' using errcode = '23505';
    end if;
    return existing_termination.result || jsonb_build_object('idempotent_replay', true);
  end if;

  select candidate.* into employee
  from public.employee_profiles candidate
  where candidate.id = target_employee_id
    and candidate.workspace_id = target_workspace_id
    and candidate.archived_at is null
  for update;
  if not found then
    raise exception 'active employee not found' using errcode = 'P0002';
  end if;
  -- The time zone is one of the places they work; somebody with no location
  -- left (S1) has nothing to match, and any valid one is taken.
  if exists (
      select 1 from public.employee_location_assignments assignment
      where assignment.employee_id = target_employee_id and assignment.ended_at is null
    )
    and not exists (
      select 1
      from public.employee_location_assignments assignment
      join public.locations location
        on location.id = assignment.location_id
       and location.workspace_id = assignment.workspace_id
      where assignment.workspace_id = target_workspace_id
        and assignment.employee_id = target_employee_id
        and assignment.ended_at is null
        and location.timezone = worksite_timezone
    ) then
    raise exception 'worksite timezone must match an active employee location' using errcode = '22023';
  end if;

  select candidate.* into member
  from public.workspace_memberships candidate
  where candidate.workspace_id = target_workspace_id
    and candidate.user_id = employee.user_id
  for update;

  insert into public.employee_terminations (
    workspace_id, employee_id, actor_user_id, effective_at, worksite_timezone,
    reason, idempotency_key
  ) values (
    target_workspace_id, target_employee_id, actor_user_id, resolved_effective_at,
    worksite_timezone, btrim(termination_reason), target_idempotency_key
  ) returning id into v_termination_id;

  if member.id is not null and member.status in ('active', 'pending_activation') then
    insert into public.employee_access_snapshots (workspace_id, employee_id, membership_id, role_id, captured_by)
    values (target_workspace_id, target_employee_id, member.id, coalesce(member.role_id, member.employee_role_id), actor_user_id);
    update public.workspace_memberships
    set status = 'suspended', updated_at = now()
    where id = member.id;
  end if;

  update public.employee_invitations
  set status = 'revoked', revoked_at = now(), updated_at = now()
  where workspace_id = target_workspace_id
    and employee_id = target_employee_id
    and status = 'pending';

  insert into public.employee_offboarding_shift_actions (
    workspace_id, termination_id, shift_id, location_id,
    previous_employee_id, shift_start_at
  )
  select shift.workspace_id, v_termination_id, shift.id, shift.location_id,
    shift.employee_id,
    (shift.scheduled_date + shift.start_time) at time zone location.timezone
  from public.schedule_published_shifts shift
  join public.schedule_location_publications publication
    on publication.id = shift.publication_id
   and publication.workspace_id = shift.workspace_id
   and publication.location_id = shift.location_id
   and publication.status = 'current'
  join public.locations location
    on location.id = shift.location_id
   and location.workspace_id = shift.workspace_id
  where shift.workspace_id = target_workspace_id
    and shift.employee_id = target_employee_id
    and (shift.scheduled_date + shift.start_time) at time zone location.timezone >= greatest(resolved_effective_at, now());

  get diagnostics released_count = row_count;

  update public.schedule_published_shifts shift
  set employee_id = null
  from public.employee_offboarding_shift_actions action
  where action.termination_id = v_termination_id
    and action.shift_id = shift.id
    and action.workspace_id = shift.workspace_id;

  -- What they asked for or answered, and their time off waiting, closes with them (design §4.8).
  perform app_private.close_employee_side(target_workspace_id, target_employee_id, actor_user_id, 'terminated');

  update public.employee_profiles
  set archived_at = resolved_effective_at, archived_by = actor_user_id,
    revision = revision + 1, updated_at = now()
  where id = target_employee_id;

  insert into public.employee_events (
    workspace_id, employee_id, actor_user_id, action, summary, occurred_at
  ) values (
    target_workspace_id, target_employee_id, actor_user_id, 'employee.terminated',
    format('Employee terminated; %s published shift(s) released', released_count),
    resolved_effective_at
  );

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata, occurred_at
  ) values (
    target_workspace_id, actor_user_id, 'employee.terminated', 'employee', target_employee_id::text,
    jsonb_build_object(
      'termination_id', v_termination_id,
      'effective_at', resolved_effective_at,
      'worksite_timezone', worksite_timezone,
      'released_shift_count', released_count
    ),
    resolved_effective_at
  );

  -- The person hears their access ended, when they had any; the shifts left without anyone are told per
  -- location (access_tell_ended, schedule_tell_unassigned).
  if member.id is not null and member.status in ('active', 'pending_activation') then
    perform app_private.access_tell_ended(target_workspace_id, target_employee_id, employee.user_id, member.id, actor_user_id);
  else
    perform app_private.access_tell_ended(target_workspace_id, target_employee_id, null, null, actor_user_id);
  end if;
  perform app_private.schedule_tell_unassigned(target_workspace_id,
    array(select action.shift_id from public.employee_offboarding_shift_actions action
          where action.termination_id = v_termination_id), actor_user_id);

  response := jsonb_build_object(
    'termination_id', v_termination_id,
    'effective_at', resolved_effective_at,
    'worksite_timezone', worksite_timezone,
    'released_shift_count', released_count,
    'idempotent_replay', false
  );
  update public.employee_terminations
  set released_shift_count = released_count, result = response
  where id = v_termination_id;
  return response;
end;
$$;


ALTER FUNCTION "public"."terminate_employee_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "effective_local" timestamp without time zone, "worksite_timezone" "text", "termination_reason" "text", "target_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."time_off_assignment_impact"("w" "uuid", "emp" "uuid", "approved" "tstzmultirange") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select coalesce(jsonb_agg(public.shift_exchange_shift(w, affected.id)
   || jsonb_build_object('publication_id', affected.publication_id, 'time_unknown', false,
        'starts_at', lower(affected.span), 'ends_at', upper(affected.span)) order by affected.id), '[]'::jsonb)
 from (
  select ps.id, ps.publication_id,
   app_private.shift_time_range(ps.scheduled_date, ps.start_time, ps.end_time, coalesce(ps.time_timezone, l.timezone)) as span
  from public.schedule_published_shifts ps
  join public.schedule_location_publications pub on pub.id = ps.publication_id and pub.status = 'current'
  join public.locations l on l.id = ps.location_id
  where ps.workspace_id = w and ps.employee_id = emp and not isempty(approved)
   and ps.scheduled_date between (lower(range_merge(approved)) at time zone 'UTC')::date - 3
                             and (upper(range_merge(approved)) at time zone 'UTC')::date + 3
 ) affected
 where approved && affected.span;
$$;


ALTER FUNCTION "public"."time_off_assignment_impact"("w" "uuid", "emp" "uuid", "approved" "tstzmultirange") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."time_off_entry_people_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  why text := app_private.time_off_decider_why(me, null);
begin
  if why is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || why, detail = 'time_off.decide';
  end if;
  return jsonb_build_object('people', coalesce((
    select jsonb_agg(jsonb_build_object(
      'employee_id', p.id,
      'name', p.name,
      'location_names', p.location_names,
      'time_zone', p.zone_name,
      'today', (now() at time zone p.zone_name)::date) order by lower(p.name), p.id)
    from (
      select e.id, btrim(coalesce(nullif(btrim(e.preferred_name), ''), e.first_name) || ' ' || e.last_name) as name,
        app_private.time_off_timezone(target_workspace_id, e.id) as zone_name,
        coalesce((
          select jsonb_agg(l.name order by a.is_primary desc, a.assigned_at)
          from public.employee_location_assignments a
          join public.locations l on l.id = a.location_id and l.workspace_id = a.workspace_id
          where a.workspace_id = target_workspace_id and a.employee_id = e.id and a.ended_at is null
            and app_private.location_is_live(l)), '[]'::jsonb) as location_names
      from public.employee_profiles e
      where e.workspace_id = target_workspace_id and e.archived_at is null
        and (e.user_id is null or app_private.has_employee_access(target_workspace_id, e.user_id))
        and app_private.time_off_decider_why(me, e.id) is null
    ) p
    where p.zone_name is not null), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."time_off_entry_people_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."time_off_impact_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  read_rule app_private.authz_actions;
  why text;
  found_request public.time_off_requests;
  at_stake jsonb := '[]';
begin
  why := app_private.time_off_decider_why(me, null);
  if why is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || why, detail = 'time_off.decide';
  end if;
  select * into found_request from public.time_off_requests r
  where r.id = target_request_id and r.workspace_id = target_workspace_id and r.kind = 'leave';
  if not found then
    -- A request that is not there answers as one at a location the actor does not reach (BL-354).
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'time_off.decide';
  end if;
  why := app_private.time_off_decider_why(me, found_request.employee_id);
  if why is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || why, detail = 'time_off.decide';
  end if;
  select * into read_rule from app_private.authz_actions a where a.key = 'schedule.read';
  if found_request.status = 'pending' and found_request.starts_at > now() then
    at_stake := app_private.time_off_shifts_at_stake(found_request);
  end if;
  return jsonb_build_object(
    'request', app_private.time_off_decider_view(found_request),
    'fingerprint', app_private.time_off_shifts_print(at_stake),
    'shift_count', jsonb_array_length(at_stake),
    'hidden_shift_count', (select count(*)::integer from jsonb_array_elements(at_stake) x
      where app_private.authz_check(me, read_rule, array[(x ->> 'location_id')::uuid], null, null) is not null),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object('location_id', place.location_id, 'location_name', place.location_name,
        'shifts', place.shifts) order by place.location_name, place.location_id)
      from (
        select (x ->> 'location_id')::uuid as location_id, min(x ->> 'location_name') as location_name,
          jsonb_agg(jsonb_build_object(
            'id', x ->> 'id',
            'scheduled_date', x ->> 'scheduled_date',
            'start_time', to_char((x ->> 'start_time')::time, 'HH24:MI'),
            'end_time', to_char((x ->> 'end_time')::time, 'HH24:MI'),
            'job_name', x ->> 'job_name',
            'starts_at', x ->> 'starts_at',
            'ends_at', x ->> 'ends_at',
            'timezone', x ->> 'timezone') order by x ->> 'starts_at', x ->> 'id') as shifts
        from jsonb_array_elements(at_stake) x
        where app_private.authz_check(me, read_rule, array[(x ->> 'location_id')::uuid], null, null) is null
        group by (x ->> 'location_id')::uuid
      ) place), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."time_off_impact_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."time_off_requests_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_view" "text" DEFAULT 'all'::"text", "target_location_id" "uuid" DEFAULT NULL::"uuid", "target_search" "text" DEFAULT ''::"text", "target_sort" "text" DEFAULT 'needs_decision'::"text", "target_page" integer DEFAULT 1, "target_page_size" integer DEFAULT 50, "target_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  why text := app_private.time_off_decider_why(me, null);
  needle text := nullif(btrim(coalesce(target_search, '')), '');
  result jsonb;
begin
  if why is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || why, detail = 'time_off.decide';
  end if;
  if target_view is null or target_view not in ('all', 'open', 'closed')
     or target_sort is null or target_sort not in ('needs_decision', 'starts', 'newest')
     or target_page is null or target_page < 1 or target_page_size is null or target_page_size not in (25, 50, 100)
     or char_length(needle) > 200 then
    raise exception 'Choose a view, a sort and a page' using errcode = '22023', hint = 'time_off.invalid';
  end if;

  with answerable as materialized (
    select e.id, btrim(coalesce(nullif(btrim(e.preferred_name), ''), e.first_name) || ' ' || e.last_name) as name
    from public.employee_profiles e
    where e.workspace_id = target_workspace_id
      and exists (select 1 from public.time_off_requests q where q.workspace_id = target_workspace_id and q.employee_id = e.id)
      and app_private.time_off_decider_why(me, e.id) is null
  ), listed as materialized (
    select r as request, r.id, r.starts_at, r.created_at, coalesce(greatest(r.decided_at, r.ended_at), r.updated_at) as answered_at,
      (r.status = 'pending' and case when r.kind = 'cancel' then r.ends_at else r.starts_at end > now()) as waiting
    from public.time_off_requests r
    join answerable person on person.id = r.employee_id
    where r.workspace_id = target_workspace_id
      and r.status in ('pending', 'approved', 'declined', 'expired', 'cancelled', 'revoked')
      and (target_request_id is null or r.id = target_request_id)
      and (target_location_id is null or exists (
        select 1 from public.employee_location_assignments a
        where a.workspace_id = target_workspace_id and a.employee_id = r.employee_id and a.location_id = target_location_id
          and a.ended_at is null))
      and (needle is null or strpos(lower(person.name), lower(needle)) > 0 or strpos(lower(coalesce(r.note, '')), lower(needle)) > 0)
  ), viewed as (
    select * from listed l
    where target_view = 'all' or (target_view = 'open') = l.waiting
  ), page as (
    select v.request, row_number() over (order by
        case when target_sort = 'needs_decision' then not v.waiting end,
        case when target_sort = 'needs_decision' and v.waiting then v.starts_at end,
        case when target_sort = 'needs_decision' then v.answered_at end desc,
        case when target_sort = 'starts' then v.starts_at end,
        case when target_sort = 'newest' then v.created_at end desc,
        v.id) as at
    from viewed v
  )
  select jsonb_build_object(
    'total', (select count(*)::integer from viewed),
    'waiting', (select count(*)::integer from listed l where l.waiting),
    'page', target_page,
    'page_size', target_page_size,
    -- The page's own clock and location filter (D7: the old Requests read that carried them is gone): the
    -- workspace's time format, and the live locations whose time off this person answers.
    'time_format', (select st.time_format from public.workspace_scheduling_settings st where st.workspace_id = target_workspace_id),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name) order by l.name, l.id)
      from public.locations l
      where l.workspace_id = target_workspace_id and l.archived_at is null
        and app_private.time_off_reason(actor_user_id, target_workspace_id, 'time_off.decide', null, l.id) is null), '[]'::jsonb),
    'requests', coalesce((
      select jsonb_agg(app_private.time_off_decider_view(p.request) order by p.at)
      from page p
      where p.at > (target_page - 1) * target_page_size and p.at <= target_page * target_page_size), '[]'::jsonb))
  into result;
  return result;
end;
$$;


ALTER FUNCTION "public"."time_off_requests_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_view" "text", "target_location_id" "uuid", "target_search" "text", "target_sort" "text", "target_page" integer, "target_page_size" integer, "target_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."time_off_resolve_clock"("wall" timestamp without time zone, "zone_name" "text", "fold_choice" "text" DEFAULT NULL::"text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare candidates timestamptz[];
begin
 if not app_private.timezone_name_valid(zone_name) then raise exception 'Choose a valid time zone' using errcode='22023'; end if;
 if fold_choice is not null and fold_choice not in('earlier','later') then raise exception 'Choose the first or second occurrence of the repeated time' using errcode='22023'; end if;
 select array_agg(distinct instant order by instant) into candidates from (
  select (wall at time zone 'UTC')-make_interval(secs=>public.availability_utc_offset((wall at time zone zone_name)+probe,zone_name)) instant
   from unnest(array[interval '-2 days',interval '-1 day',interval '0',interval '1 day',interval '2 days']) probe
 ) attempts where instant at time zone zone_name=wall;
 if coalesce(cardinality(candidates),0)=0 then raise exception 'These hours do not exist on this date in the selected time zone' using errcode='22023'; end if;
 if cardinality(candidates)>1 and fold_choice is null then raise exception 'This clock repeats on this date. Choose its first or second occurrence' using errcode='22023'; end if;
 return candidates[case when fold_choice='later' then cardinality(candidates) else 1 end];
end $$;


ALTER FUNCTION "public"."time_off_resolve_clock"("wall" timestamp without time zone, "zone_name" "text", "fold_choice" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."touch_workspace_membership_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.workspace_memberships
  set last_used_at = now()
  where user_id = actor_user_id
    and workspace_id = target_workspace_id
    and status in ('active'::public.membership_status, 'pending_activation'::public.membership_status)
    and (last_used_at is null or last_used_at < now() - interval '5 minutes');
$$;


