CREATE OR REPLACE FUNCTION "public"."unapprove_signature_retention_policy_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_policy_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  target_name text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');

  update public.signature_retention_policies
  set status = 'draft', approved_by = null, approved_at = null, updated_at = now()
  where id = target_policy_id and workspace_id = target_workspace_id
    and status = 'approved' and archived_at is null
  returning name into target_name;
  if target_name is null then
    raise exception 'approved retention policy not found' using errcode = 'P0002';
  end if;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id, actor_id, 'signature_retention_policy.unapproved',
    'signature_retention_policy', target_policy_id::text,
    jsonb_build_object('name', target_name)
  );
end;
$$;


ALTER FUNCTION "public"."unapprove_signature_retention_policy_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_policy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."undo_schedule_edit_session_step_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  edit public.schedule_edit_sessions%rowtype;
  last_at timestamptz;
  last_xact xid8;
  steps jsonb;
  refused_message text;
  refused text;
begin
  perform public.availability_lock_workspace(target_workspace_id);
  select * into edit from public.schedule_edit_sessions session
  where session.id = target_session_id and session.workspace_id = target_workspace_id
  for update;
  if edit.id is null or edit.holder_user_id is distinct from actor_user_id then
    raise exception 'edit session not found' using errcode = 'P0002';
  end if;
  -- The edit's locations are still the person's to edit (B-3).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => edit.location_ids);
  if edit.status <> 'active' then
    raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
  elsif edit.expires_at <= now() then
    raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
  end if;
  if edit.revision is distinct from expected_session_revision then
    raise exception 'session revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
  end if;

  select step.step_at, step.step_xact into last_at, last_xact
  from app_private.schedule_edit_undo_steps step
  where step.session_id = edit.id
  -- The step written last, by its number (EKRAN-01 #12).
  order by step.step_no desc
  limit 1;
  if last_at is null then
    raise exception 'nothing to undo' using errcode = 'PT409', hint = 'schedule.nothing_to_undo';
  end if;

  -- BL-998: a step that can no longer come back (a rule that applies now:
  -- approved time off, a missing document, an acceptance the edit lost) leaves
  -- the history and the answer says why; nothing of it is written, and the
  -- steps before it stay in reach.
  begin
  -- Each shift the step touched, as it was before it. The step leaves the
  -- history first, so the writes below do not push an older step out.
  with taken as (
    delete from app_private.schedule_edit_undo_steps step
    where step.session_id = edit.id and step.step_at = last_at and step.step_xact = last_xact
    returning step.shift_id, step.before)
  select coalesce(jsonb_agg(jsonb_build_object('id', taken.shift_id, 'before', taken.before)), '[]'::jsonb)
  into steps from taken;

  -- Shifts the step added go first, so the ones coming back find room.
  delete from public.schedule_edit_session_shifts shift
  using jsonb_array_elements(steps) step
  where shift.session_id = edit.id and shift.id = (step ->> 'id')::uuid and step -> 'before' = 'null'::jsonb;

  -- The rows come back as they were; their revision moves on, so a screen
  -- that still holds the undone row is told it is stale.
  update public.schedule_edit_session_shifts shift
  set location_id = prior.location_id, employee_id = prior.employee_id, job_id = prior.job_id,
      shift_type_id = prior.shift_type_id, scheduled_date = prior.scheduled_date,
      start_time = prior.start_time, end_time = prior.end_time, note = prior.note,
      idempotency_key = prior.idempotency_key, source_published_shift_id = prior.source_published_shift_id,
      pending_op_type = prior.pending_op_type, locked = prior.locked,
      unpaid_break_minutes = prior.unpaid_break_minutes, hide_time_on_badge = prior.hide_time_on_badge,
      label_ids = prior.label_ids, label_names = prior.label_names, time_basis = prior.time_basis,
      time_snapshot = prior.time_snapshot, time_timezone = prior.time_timezone,
      revision = shift.revision + 1, updated_at = now()
  from jsonb_array_elements(steps) step
  cross join lateral jsonb_populate_record(null::public.schedule_edit_session_shifts, nullif(step -> 'before', 'null'::jsonb)) prior
  where shift.session_id = edit.id and shift.id = prior.id and step -> 'before' <> 'null'::jsonb;

  insert into public.schedule_edit_session_shifts (id, workspace_id, session_id, location_id, employee_id, job_id,
    shift_type_id, scheduled_date, start_time, end_time, note, revision, idempotency_key, created_at, updated_at,
    source_published_shift_id, pending_op_type, locked, unpaid_break_minutes, hide_time_on_badge, label_ids,
    label_names, time_basis, time_snapshot, time_timezone)
  select prior.id, edit.workspace_id, edit.id, prior.location_id, prior.employee_id, prior.job_id,
    prior.shift_type_id, prior.scheduled_date, prior.start_time, prior.end_time, prior.note,
    prior.revision + 1, prior.idempotency_key, prior.created_at, now(),
    prior.source_published_shift_id, prior.pending_op_type, prior.locked, prior.unpaid_break_minutes,
    prior.hide_time_on_badge, prior.label_ids, prior.label_names, prior.time_basis, prior.time_snapshot, prior.time_timezone
  from jsonb_array_elements(steps) step
  cross join lateral jsonb_populate_record(null::public.schedule_edit_session_shifts, nullif(step -> 'before', 'null'::jsonb)) prior
  where step -> 'before' <> 'null'::jsonb
    and not exists (select 1 from public.schedule_edit_session_shifts shift
      where shift.session_id = edit.id and shift.id = prior.id);

  -- A person missing a required document is never on a shift that day, Undo or not.
  if exists (
    select 1 from jsonb_array_elements(steps) step
    cross join lateral jsonb_populate_record(null::public.schedule_edit_session_shifts, nullif(step -> 'before', 'null'::jsonb)) prior
    where prior.employee_id is not null
      and public.employee_has_hard_document_schedule_conflict_service(target_workspace_id, prior.employee_id, prior.scheduled_date)
  ) then
    raise exception 'employee document hard conflict' using errcode = '23514';
  end if;
  exception when check_violation then
    get stacked diagnostics refused_message = message_text;
    refused := case refused_message
      when 'Resolve shift hours or approved time off before this assignment' then 'availability'
      when 'A current conflict acceptance is required' then 'conflict_acceptance'
      when 'employee document hard conflict' then 'document'
      else 'rule' end;
    delete from app_private.schedule_edit_undo_steps step
    where step.session_id = edit.id and step.step_at = last_at and step.step_xact = last_xact;
  end;

  -- Undo's own writes are not a step.
  delete from app_private.schedule_edit_undo_steps step
  where step.session_id = edit.id and step.step_at = statement_timestamp() and step.step_xact = pg_current_xact_id();

  update public.schedule_edit_sessions
  set revision = revision + 1, dirty = true, last_heartbeat = now(), expires_at = now() + interval '4 minutes'
  where id = edit.id;

  return public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id)
    || case when refused is not null then jsonb_build_object('undo_refused', jsonb_build_object('reason', refused)) else '{}'::jsonb end;
end;
$$;


ALTER FUNCTION "public"."undo_schedule_edit_session_step_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unpublish_schedule_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[], "expected_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  preview jsonb;
  normalized_locations uuid[];
  publication_ids uuid[];
  effective_unpublished_at timestamptz := now();
  unpublish_event_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,921));
  select array_agg(distinct location_id order by location_id) into normalized_locations
  from unnest(target_location_ids) location_id;
  perform 1 from public.schedule_location_publications publication
  where publication.workspace_id = target_workspace_id
    and publication.week_start = target_week_start
    and publication.location_id = any(normalized_locations)
    and publication.status = 'current' for update;
  -- The preview asks the core for every location.
  preview := public.preview_schedule_unpublication_service(
    actor_user_id, target_workspace_id, target_week_start, normalized_locations
  );
  if preview->>'status' = 'past_week_closed' then
    raise exception 'past schedule week is closed' using errcode = 'P0001', hint = 'schedule.past_week_closed';
  end if;
  if preview->>'fingerprint' <> expected_fingerprint then
    raise exception 'stale unpublication preview' using errcode = '40001';
  end if;
  select array_agg((item->>'publication_id')::uuid order by item->>'publication_id')
  into publication_ids from jsonb_array_elements(preview->'locations') item;

  update public.schedule_location_publications
  set status = 'unpublished', unpublished_by = actor_user_id,
    unpublished_at = effective_unpublished_at
  where id = any(publication_ids) and status = 'current';
  if not found then raise exception 'stale unpublication preview' using errcode = '40001'; end if;
  insert into public.schedule_publication_events (
    workspace_id, week_start, action, actor_user_id, location_ids,
    publication_ids, preflight_fingerprint, diff_summary
  ) values (
    target_workspace_id, target_week_start, 'unpublished', actor_user_id,
    normalized_locations, publication_ids, expected_fingerprint,
    jsonb_build_object('locations', preview->'locations')
  ) returning id into unpublish_event_id;
  perform app_private.schedule_tell_unpublished(target_workspace_id, actor_user_id, unpublish_event_id,
    target_week_start, publication_ids);
  return jsonb_build_object(
    'status', 'unpublished', 'workspace_id', target_workspace_id,
    'week_start', target_week_start, 'location_ids', to_jsonb(normalized_locations),
    'publication_ids', to_jsonb(publication_ids),
    'unpublished_at', effective_unpublished_at
  );
exception when serialization_failure then raise exception '%',SQLERRM using errcode='PT409', hint='schedule.publication_changed';
end;
$$;


ALTER FUNCTION "public"."unpublish_schedule_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[], "expected_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unpublish_signature_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  published_record public.signature_template_versions%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');

  select version.* into published_record
  from public.signature_template_versions version
  join public.signature_templates template on template.id = version.template_id
  where version.workspace_id = target_workspace_id
    and version.template_id = target_template_id
    and version.status = 'published'
    and template.archived_at is null
  order by version.version_number desc
  limit 1
  for update of version;

  if published_record.id is null then
    raise exception 'published acknowledgement template not found' using errcode = 'P0002';
  end if;

  if exists (
    select 1 from public.signature_template_versions draft
    where draft.template_id = target_template_id
      and draft.status = 'draft'
      and draft.id <> published_record.id
  ) then
    raise exception 'draft acknowledgement already exists' using errcode = '23505';
  end if;

  update public.signature_template_versions
  set status = 'draft', published_by = null, published_at = null, updated_at = now()
  where id = published_record.id;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id, actor_id, 'signature_template.unpublished',
    'signature_template', target_template_id::text,
    jsonb_build_object(
      'version_id', published_record.id,
      'version_number', published_record.version_number,
      'content_digest', published_record.content_digest
    )
  );
end;
$$;


ALTER FUNCTION "public"."unpublish_signature_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_department_with_jobs_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_department_id" "uuid", "department_input" "jsonb", "jobs_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare dep public.departments; added jsonb:='[]';
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.jobs.write');
  if jsonb_typeof(department_input->'name') is distinct from 'string' or jsonb_typeof(department_input->'color') is distinct from 'string'
    or jsonb_typeof(jobs_input) is distinct from 'array' then raise exception 'Valid department and jobs required' using errcode='22023'; end if;
  perform 1 from public.workspaces where id=target_workspace_id for update;
  update public.departments set name=btrim(department_input->>'name'),color=department_input->>'color',updated_at=now()
    where id=target_department_id and workspace_id=target_workspace_id returning * into dep;
  if not found then raise exception 'Department not found' using errcode='P0002'; end if;
  if jsonb_array_length(jobs_input)>0 then
    added:=public.create_department_jobs_service(actor_user_id,target_workspace_id,target_department_id,jobs_input);
  end if;
  return jsonb_build_object('department',to_jsonb(dep),'jobs',added);
exception when unique_violation then raise exception 'A department or job with that name already exists.' using errcode='23505';
end; $$;


ALTER FUNCTION "public"."update_department_with_jobs_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_department_id" "uuid", "department_input" "jsonb", "jobs_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_employee_invitation_access_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "target_employee_role_id" "uuid", "target_management_role_id" "uuid", "target_managed_location_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  pending public.employee_invitations;
  places uuid[] := array(select distinct p from unnest(coalesce(target_managed_location_ids, '{}')) p order by p);
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.invite', target_person => target_employee_id);
  select * into pending from public.employee_invitations i
  where i.workspace_id = target_workspace_id and i.employee_id = target_employee_id and i.status = 'pending'
    and i.expires_at > now()
  for update;
  if pending.id is null then
    raise exception 'open invitation not found' using errcode = 'P0002';
  end if;
  if not app_private.can_invite_with_role(actor_user_id, target_workspace_id, pending.role_id) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  perform app_private.invitation_access_check(actor_user_id, target_workspace_id,
    target_employee_role_id, target_management_role_id, places);

  update public.employee_invitations
  set employee_role_id = target_employee_role_id, management_role_id = target_management_role_id,
      managed_location_ids = places, updated_at = now()
  where id = pending.id;
  update public.employee_profiles
  set revision = revision + 1, updated_at = now()
  where id = target_employee_id and workspace_id = target_workspace_id;
  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (target_workspace_id, target_employee_id, actor_user_id, 'employee.invitation_access_changed',
    'Invitation access changed');
end;
$$;


ALTER FUNCTION "public"."update_employee_invitation_access_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "target_employee_role_id" "uuid", "target_management_role_id" "uuid", "target_managed_location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_job_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid", "assignment_changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare item jsonb; employee public.employee_profiles; target public.jobs; existing public.employee_job_assignments;
  actual boolean; desired boolean; changed integer:=0; unchanged integer:=0; replacement uuid;
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  save_rule app_private.authz_actions; reason text;
begin
  select * into save_rule from app_private.authz_actions r where r.key = 'employee.save';
  -- May they change anybody's jobs at all; whose, is asked person by person.
  reason := app_private.authz_check(me, save_rule, null, null, null);
  if reason is not null and reason <> 'out_of_scope' then
    raise exception 'Not allowed' using errcode='42501', hint='authz.' || reason, detail='employee.save'; end if;
  select * into target from public.jobs where id=target_job_id and workspace_id=target_workspace_id for update;
  if target.id is null then raise exception 'Job not found' using errcode='P0002'; end if;
  if target.deleted_at is not null then raise exception 'This job was deleted and is no longer available' using errcode='P0002'; end if;
  if target.archived_at is not null then raise exception 'Restore this job before changing assignments' using errcode='22023'; end if;
  if jsonb_typeof(assignment_changes) is distinct from 'array' then
    raise exception 'Valid assignment changes required' using errcode='22023'; end if;
  if jsonb_array_length(assignment_changes) not between 1 and 10000 then
    raise exception 'Choose between 1 and 10000 employees' using errcode='22023'; end if;
  if (select count(*)<>count(distinct value->>'employee_id') from jsonb_array_elements(assignment_changes)) then
    raise exception 'An employee may only appear once in a batch' using errcode='22023'; end if;
  -- Ask, lock and validate the entire batch before applying any change.
  for item in select value from jsonb_array_elements(assignment_changes) order by value->>'employee_id' loop
    if jsonb_typeof(item->'employee_id') is distinct from 'string'
      or jsonb_typeof(item->'assigned') is distinct from 'boolean'
      or jsonb_typeof(item->'expected_revision') is distinct from 'number'
      or (item->>'expected_revision') !~ '^[1-9][0-9]*$' then
      raise exception 'Valid employee assignment required' using errcode='22023'; end if;
    -- Somebody unknown gets the answer somebody out of reach gets.
    reason := app_private.authz_check(me, save_rule, null, (item->>'employee_id')::uuid, null);
    if reason is not null then
      raise exception 'Not allowed' using errcode='42501', hint='authz.' || reason, detail='employee.save'; end if;
    select * into employee from public.employee_profiles e
    where e.id=(item->>'employee_id')::uuid and e.workspace_id=target_workspace_id for update;
    if employee.archived_at is not null then raise exception 'An employee was archived. Reload the employee list.' using errcode='PT409',hint='employee.archived'; end if;
    select exists(select 1 from public.employee_job_assignments a where a.employee_id=employee.id
      and a.job_id=target_job_id and a.ended_at is null) into actual;
    if actual<>(item->>'assigned')::boolean and employee.revision<>(item->>'expected_revision')::integer then
      raise exception 'Employee % changed. Reload employees and review your pending changes.',employee.employee_code using errcode='PT409',hint='employee.revision_conflict';
    end if;
  end loop;
  for item in select value from jsonb_array_elements(assignment_changes) order by value->>'employee_id' loop
    select * into existing from public.employee_job_assignments a where a.employee_id=(item->>'employee_id')::uuid
      and a.job_id=target_job_id and a.ended_at is null;
    desired:=(item->>'assigned')::boolean;
    if (existing.id is not null)=desired then unchanged:=unchanged+1; continue; end if;
    if desired then
      insert into public.employee_job_assignments(workspace_id,employee_id,job_id,is_primary,created_by)
      values(target_workspace_id,(item->>'employee_id')::uuid,target_job_id,
        target.system_key is distinct from 'owner'
        and not exists(select 1 from public.employee_job_assignments a where a.employee_id=(item->>'employee_id')::uuid
          and a.ended_at is null and a.is_primary),actor_user_id);
    else
      update public.employee_job_assignments set ended_at=now() where id=existing.id;
      if existing.is_primary then
        select a.id into replacement from public.employee_job_assignments a join public.jobs j on j.id=a.job_id
        where a.employee_id=existing.employee_id and a.ended_at is null and j.system_key is distinct from 'owner'
        order by (j.archived_at is not null),lower(j.name),j.id limit 1;
        if replacement is not null then update public.employee_job_assignments set is_primary=true where id=replacement; end if;
      end if;
    end if;
    update public.employee_profiles set revision=revision+1,updated_at=now()
    where id=(item->>'employee_id')::uuid and workspace_id=target_workspace_id;
    insert into public.employee_events(workspace_id,employee_id,actor_user_id,action,summary)
    values(target_workspace_id,(item->>'employee_id')::uuid,actor_user_id,
      case when desired then 'job.assigned' else 'job.unassigned' end,
      case when desired then 'Assigned to ' else 'Removed from ' end||target.name);
    changed:=changed+1;
  end loop;
  return jsonb_build_object('changed_count',changed,'unchanged_count',unchanged);
end; $_$;


ALTER FUNCTION "public"."update_job_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid", "assignment_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_job_details_and_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid", "job_input" "jsonb" DEFAULT NULL::"jsonb", "expected_job" "jsonb" DEFAULT NULL::"jsonb", "assignment_changes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  target public.jobs;
  department public.departments;
  desired jsonb;
  actual jsonb;
  selected_department_id uuid;
  result jsonb := '{"changed_count":0,"unchanged_count":0}'::jsonb;
  me app_private.actor_state;
  save_rule app_private.authz_actions;
  reason text;
begin
  if job_input is not null then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.jobs.write');
  else
    -- Assignments alone: may they change anybody's jobs at all; whose, update_job_assignments_service
    -- asks person by person.
    me := app_private.actor(actor_user_id, target_workspace_id);
    select * into save_rule from app_private.authz_actions r where r.key = 'employee.save';
    reason := app_private.authz_check(me, save_rule, null, null, null);
    if reason is not null and reason <> 'out_of_scope' then
      raise exception 'Not allowed' using errcode='42501', hint='authz.' || reason, detail='employee.save'; end if;
  end if;
  if jsonb_typeof(assignment_changes) is distinct from 'array' then
    raise exception 'Valid assignment changes required' using errcode = '22023';
  end if;
  if jsonb_array_length(assignment_changes) > 10000
    or (job_input is null and jsonb_array_length(assignment_changes) = 0) then
    raise exception 'Choose at least one change and at most 10000 employees' using errcode = '22023';
  end if;
  if (job_input is null) <> (expected_job is null) then
    raise exception 'Job details require their original values' using errcode = '22023';
  end if;

  select * into target from public.jobs
    where id = target_job_id and workspace_id = target_workspace_id for update;
  if target.id is null or target.deleted_at is not null then
    raise exception 'This job is no longer available' using errcode = 'P0002';
  end if;

  if job_input is not null then
    if jsonb_typeof(job_input) is distinct from 'object'
      or jsonb_typeof(expected_job) is distinct from 'object'
      or jsonb_typeof(job_input->'name') is distinct from 'string'
      or char_length(btrim(job_input->>'name')) not between 1 and 100
      or jsonb_typeof(job_input->'color') is distinct from 'string'
      or (job_input->>'color') !~ '^#[0-9a-fA-F]{6}$'
      or not (job_input ? 'department_id')
      or jsonb_typeof(job_input->'department_id') not in ('string', 'null') then
      raise exception 'Valid job name, color and department required' using errcode = '22023';
    end if;
    if job_input ? 'lineup_icons' and jsonb_typeof(job_input->'lineup_icons') is distinct from 'array' then
      raise exception 'Choose up to 24 different drawings from the archive' using errcode = '22023', hint = 'job.lineup_icons_invalid';
    end if;
    selected_department_id := (job_input->>'department_id')::uuid;
    desired := jsonb_build_object(
      'name', btrim(job_input->>'name'), 'color', job_input->>'color', 'department_id', selected_department_id,
      'lineup_icons', coalesce(job_input->'lineup_icons', to_jsonb(target.lineup_icons))
    );
    actual := jsonb_build_object(
      'name', target.name, 'color', target.color, 'department_id', target.department_id,
      'lineup_icons', to_jsonb(target.lineup_icons)
    );
    -- A successful request can be retried with the same original values.
    if desired is distinct from actual then
      if expected_job is distinct from actual then
        raise exception 'Job details changed. Reload the latest job and review your draft.' using errcode = 'PT409', hint = 'job.changed';
      end if;
      if selected_department_id is not null and selected_department_id is distinct from target.department_id then
        select * into department from public.departments d
          where d.id = selected_department_id and d.workspace_id = target_workspace_id for share;
        if department.id is null or department.archived_at is not null or department.deleted_at is not null then
          raise exception 'Choose an active department in this workspace' using errcode = '22023';
        end if;
      end if;
      begin
        update public.jobs set
          name = desired->>'name', color = desired->>'color',
          department_id = selected_department_id,
          lineup_icons = array(select icon.key from jsonb_array_elements_text(desired->'lineup_icons') with ordinality as icon(key, n) order by icon.n),
          updated_at = now()
          where id = target_job_id and workspace_id = target_workspace_id
          returning * into target;
      exception when unique_violation then
        raise exception 'This job name already exists. Choose a unique name.' using errcode = '23505';
      end;
    end if;
  end if;

  if jsonb_array_length(assignment_changes) > 0 then
    result := public.update_job_assignments_service(
      actor_user_id, target_workspace_id, target_job_id, assignment_changes
    );
  end if;
  return result || jsonb_build_object('job', to_jsonb(target));
end;
$_$;


ALTER FUNCTION "public"."update_job_details_and_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid", "job_input" "jsonb", "expected_job" "jsonb", "assignment_changes" "jsonb") OWNER TO "postgres";


